test "lite index prefix comparison scales past 4096 records and detects mutations" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "index-prefix-comparison.aflite");
    defer a.free(path);
    var writer = try NativeFile.createWithIo(a, std.testing.io, path, .{ .no_sync = true });
    defer writer.close();
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const mutations = try arena.allocator().alloc(CatalogMutation, 5000);
    for (mutations, 0..) |*mutation, i| mutation.* = .{
        .key = try std.fmt.allocPrint(arena.allocator(), "/scope/{d:0>8}", .{i}),
        .value = "immutable",
    };
    try writer.putIndexCatalogBatch(mutations);
    var captured = try NativeFile.openWithIo(a, std.testing.io, path, .{ .read_only = true });
    defer captured.close();
    try writer.putDocument("primary", "unrelated");
    try writer.putIndexCatalogRecord("/unrelated/entry", "outside the captured prefix");
    const before_reads = writer.test_page_reads.load(.monotonic) + captured.test_page_reads.load(.monotonic);
    try std.testing.expect(try captured.indexCatalogPrefixUnchanged(&writer, "/scope/"));
    const reads = writer.test_page_reads.load(.monotonic) + captured.test_page_reads.load(.monotonic) - before_reads;
    // Comparing unchanged subtrees should read tree paths, not 5,000 records.
    try std.testing.expect(reads < 32);
    try std.testing.expect(try captured.indexCatalogPrefixUnchanged(&writer, "/absent/"));
    try writer.putIndexCatalogRecord("/scope/00002500", "new bytes");
    try std.testing.expect(!try captured.indexCatalogPrefixUnchanged(&writer, "/scope/"));
    try std.testing.expect(try captured.indexCatalogPrefixUnchanged(&writer, "/scope/00000"));
    try writer.deleteIndexCatalogRecord("/scope/00000001");
    try std.testing.expect(!try captured.indexCatalogPrefixUnchanged(&writer, "/scope/00000"));
    try writer.putIndexCatalogRecord("/absent/new", "inserted");
    try std.testing.expect(!try captured.indexCatalogPrefixUnchanged(&writer, "/absent/"));
}

test "lite runtime metadata comparison skips leases and fences secrets and documents" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "runtime-metadata.aflite");
    defer a.free(path);
    var writer = try NativeFile.createWithIo(a, std.testing.io, path, .{ .no_sync = true });
    defer writer.close();
    try writer.putCatalogRecord("secret-head", "original");
    var captured = try NativeFile.openWithIo(a, std.testing.io, path, .{ .read_only = true });
    defer captured.close();
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const mutations = try arena.allocator().alloc(CatalogMutation, 5000);
    for (mutations, 0..) |*mutation, i| mutation.* = .{
        .key = try std.fmt.allocPrint(arena.allocator(), "{s}{d:0>8}", .{ NativeFile.artifact_lease_key_prefix, i }),
        .value = "lease",
    };
    try writer.putCatalogBatch(mutations);
    const before = writer.test_page_reads.load(.monotonic) + captured.test_page_reads.load(.monotonic);
    try std.testing.expect(try captured.runtimeMetadataUnchanged(&writer));
    try std.testing.expect(writer.test_page_reads.load(.monotonic) + captured.test_page_reads.load(.monotonic) - before < 32);
    try captured.adoptIndexPublicationHeader(writer.header);
    try writer.putIndexCatalogRecord("/shadow/unpublished", "bytes");
    try std.testing.expect(try captured.runtimeMetadataUnchanged(&writer));
    try captured.adoptIndexPublicationHeader(writer.header);
    try writer.putCatalogRecord("secret-head", "changed");
    try std.testing.expect(!try captured.runtimeMetadataUnchanged(&writer));
    try captured.adoptIndexPublicationHeader(writer.header);
    try writer.putDocument("primary", "new row");
    try std.testing.expect(!try captured.runtimeMetadataUnchanged(&writer));
    try captured.adoptIndexPublicationHeader(writer.header);
    try writer.putCatalogRecord(NativeFile.artifact_lease_key_prefix ++ "evict-a", "lease");
    try writer.putCatalogRecord(NativeFile.artifact_lease_key_prefix ++ "evict-b", "lease");
    try std.testing.expect(!try captured.runtimeMetadataUnchanged(&writer));
}

test "lite index checkpoint adoption discards physical page caches" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "index-adoption-caches.aflite");
    defer a.free(path);
    var captured = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true });
    defer captured.close();
    try captured.putDocument("doc", "original");
    const original = (try captured.getDocumentAlloc(a, "doc")).?;
    a.free(original);
    try std.testing.expect(captured.page_cache.pages.count() != 0);
    var writer = try NativeFile.openWithIo(a, std.testing.io, path, .{ .externally_locked = true });
    defer writer.close();
    try writer.putDocument("doc", "updated");
    captured.free_pages_verified = true;
    try captured.adoptIndexPublicationHeader(writer.header);
    try std.testing.expectEqual(@as(usize, 0), captured.page_cache.pages.count());
    try std.testing.expect(!captured.free_pages_verified);
    const updated = (try captured.getDocumentAlloc(a, "doc")).?;
    defer a.free(updated);
    try std.testing.expectEqualStrings("updated", updated);
    try captured.putDocument("next", "after adoption");
    try std.testing.expect((try captured.check()).valid);
}

test "lite allocator verification follows only identical certain owner checkpoints" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "allocator-proof.aflite");
    defer a.free(path);
    var owner = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true });
    defer owner.close();
    try owner.putDocument("doc", "original");
    try std.testing.expect(owner.free_pages_verified);
    var borrowed = try NativeFile.openWithIo(a, std.testing.io, path, .{ .externally_locked = true });
    defer borrowed.close();
    try std.testing.expect(!borrowed.free_pages_verified);
    try borrowed.inheritAllocatorVerification(&owner);
    try std.testing.expect(borrowed.free_pages_verified);
    try borrowed.adoptIndexPublicationHeader(owner.header);
    try std.testing.expect(borrowed.free_pages_verified);
    try owner.putDocument("next", "new generation");
    borrowed.free_pages_verified = false;
    try borrowed.inheritAllocatorVerification(&owner);
    try std.testing.expect(!borrowed.free_pages_verified);
    try borrowed.adoptIndexPublicationHeader(owner.header);
    owner.checkpoint_publication_uncertain = true;
    try borrowed.inheritAllocatorVerification(&owner);
    try std.testing.expect(!borrowed.free_pages_verified);
    owner.checkpoint_publication_uncertain = false;
    try borrowed.inheritAllocatorVerification(&owner);
    try std.testing.expect(borrowed.free_pages_verified);
    const other_path = try testPath(a, tmp, "other-inode.aflite");
    defer a.free(other_path);
    var other = try NativeFile.createWithIo(a, std.testing.io, other_path, .{ .indexed_reclamation = true });
    defer other.close();
    other.header = owner.header;
    const other_owned_path = other.path;
    other.path = owner.path; // Same claimed path/header must still prove the inode.
    defer other.path = other_owned_path;
    other.free_pages_verified = false;
    try other.inheritAllocatorVerification(&owner);
    try std.testing.expect(!other.free_pages_verified);
    try std.testing.expectError(error.EnrichmentWaitCanceled, other.prepareAllocatorVerification(null));
    try borrowed.putDocument("after", "adopted");
    try std.testing.expect((try borrowed.check()).valid);
}

// perf/lwa-proof-fork: `verifyAllocatorAssumeLocked`'s stashed-receipt
// reuse (capi/lite_connection.zig) and `inheritAllocatorVerification`'s
// own post-walk transfer both used to gate on `std.meta.eql` of the
// *whole* `Header` -- including `commit_sequence`, which
// `commitTransactionWithDurability`'s ordinary redo-log append advances
// on every single commit (`self.header.checkpoints[...] = checkpoint`),
// even one that never touches a real page. That over-invalidated: a
// commit that cannot possibly have changed the free map still discarded
// a completed, still-correct proof, forcing `captureAllocatorVerificationSnapshot`
// to re-walk the ledger from scratch. The fix keys validity on exactly
// what the proof covers (`allocatorProofIdentity`: which checkpoint slot
// is active, its free-map root, its page count, and its redo fold
// boundary) instead of the whole header.
test "lite allocator proof receipt survives a redo-only commit but not a free-map-changing one" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "redo-proof-receipt.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithRedoLog(a, std.testing.io, path, .{ .indexed_reclamation = true }, 256 * 1024);
    defer file.close();
    // An explicit transaction, not a bare single-mutation call: only a
    // staged mutation (`stageMutation`, reached through `stagingTransaction()`)
    // takes the redo-diverting path at all -- a bare call always builds
    // real pages immediately, by design (perf/lwa-integration's
    // "bare commits never divert pages" fix).
    try file.beginTransaction();
    try file.putCatalogRecord("seed", "original");
    try file.commitTransaction();
    try std.testing.expect(file.free_pages_verified);

    // Stash a receipt for the current, verified state -- exactly what
    // `reader.allocatorProofReceipt()` hands `Owner.allocator_proof_receipt`
    // when a completed walk's immediate transfer has to wait for a busy
    // writer lease (lite_connection.zig's `verifyAllocatorAssumeLocked`).
    const receipt = (try file.allocatorProofReceipt()).?;

    // A redo-only commit: a small staged catalog write diverts entirely
    // into the redo log (design doc §9.3) -- no page allocation, no
    // ledger mutation -- yet `commit_sequence`, and so the whole
    // `Header`, still advances.
    const before = file.activeCheckpoint();
    try file.beginTransaction();
    try file.putCatalogRecord("seed2", "second");
    try file.commitTransaction();
    const after = file.activeCheckpoint();
    try std.testing.expect(after.commit_sequence != before.commit_sequence);
    try std.testing.expectEqual(before.free_map_root_page, after.free_map_root_page);
    try std.testing.expectEqual(before.page_count, after.page_count);
    try std.testing.expectEqual(before.redo_folded_through, after.redo_folded_through);
    try std.testing.expect(!std.meta.eql(file.header, receipt.header));

    // The stashed receipt must still be good for reuse: the free map it
    // proved is exactly the free map on disk right now.
    file.free_pages_verified = false;
    try file.inheritAllocatorProofReceipt(receipt);
    try std.testing.expect(file.free_pages_verified);

    // A free-map-changing commit (delete, fold, reclaim: the ledger's own
    // content -- and so its copy-on-write root page -- genuinely moves)
    // must invalidate a receipt captured before it.
    const stale = (try file.allocatorProofReceipt()).?;
    try file.beginTransaction();
    try file.deleteCatalogRecord("seed");
    try file.commitTransaction();
    try file.checkpointRedoLog();
    _ = try file.reclaimPages(4096);
    // The fold is a real, non-diverting commit (`checkpointing = true`
    // disables every diversion point for its span), so it advances the
    // redo fold boundary -- a reliable signal here, unlike
    // `free_map_root_page` alone, which can legitimately return to the
    // same page id on quick reuse (the ABA case other allocator tests
    // cover) without that meaning nothing changed.
    try std.testing.expect(file.activeCheckpoint().redo_folded_through != stale.header.checkpoints[stale.header.active_checkpoint].redo_folded_through);
    file.free_pages_verified = false;
    try file.inheritAllocatorProofReceipt(stale);
    try std.testing.expect(!file.free_pages_verified);
}

test "lite allocator detached verification cancels and refuses stale checkpoints" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "detached-proof.aflite");
    defer a.free(path);
    var owner = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer owner.close();
    try owner.putDocument("doc", "before");
    var captured = try NativeFile.openWithIo(a, std.testing.io, path, .{ .externally_locked = true, .no_sync = true });
    defer captured.close();
    var cancel: maintenance.CancelToken = .{};
    cancel.request();
    try std.testing.expectError(error.MaintenanceCanceled, captured.prepareAllocatorVerification(&cancel));
    try std.testing.expect(!captured.free_pages_verified);
    try owner.putDocument("doc", "after");
    try std.testing.expectError(error.EnrichmentWaitCanceled, captured.prepareAllocatorVerification(null));
    try std.testing.expect(!captured.free_pages_verified);
    try captured.adoptIndexPublicationHeader(owner.header);
    try captured.prepareAllocatorVerification(null);
    try std.testing.expect(captured.free_pages_verified);
    try captured.putDocument("next", "verified");
    try std.testing.expect((try captured.check()).valid);
}

test "lite allocator v4 clean certificate carries checked ownership across processes" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "certified-reopen.aflite");
    defer a.free(path);
    const large: [32768]u8 = @splat('v');
    {
        var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
        defer file.close();
        for (0..12) |_| try file.putDocument("doc", &large);
        _ = try file.reclaimPages(4096);
        try std.testing.expect(try file.certifyAllocator());
        try std.testing.expect((try file.check()).valid);
    }
    {
        var file = try NativeFile.openWithIo(a, std.testing.io, path, .{ .no_sync = true });
        defer file.close();
        try std.testing.expect(!file.free_pages_verified);
        try std.testing.expect(try file.inheritAllocatorCertificate());
        const reused = (try file.allocatorStats()).?.reused_pages;
        for (0..4) |_| try file.putDocument("doc", &large);
        try std.testing.expect((try file.allocatorStats()).?.reused_pages > reused);
        try std.testing.expect((try file.check()).valid);
        try std.testing.expect(try file.certifyAllocator());
    }
    {
        var file = try NativeFile.openWithIo(a, std.testing.io, path, .{ .no_sync = true });
        defer file.close();
        try std.testing.expect(try file.inheritAllocatorCertificate());
        const fallback = 1 - file.header.active_checkpoint;
        file.header.checkpoints[fallback].commit_sequence += 1;
        try std.testing.expect(!try file.inheritAllocatorCertificate());
        file.header.checkpoints[fallback].commit_sequence -= 1;
        const state = try file.loadLedger(file.activeCheckpoint());
        state.counts.items[0] ^= 1;
        try std.testing.expect(!try file.inheritAllocatorCertificate());
        state.counts.items[0] ^= 1;
        try std.testing.expect(try file.inheritAllocatorCertificate());
        // An older writer knows nothing about certificates. Its ordinary
        // publication invalidates the stored header binding automatically.
        try file.putDocument("foreign", "publication without a new seal");
    }
    {
        var file = try NativeFile.openWithIo(a, std.testing.io, path, .{ .no_sync = true });
        defer file.close();
        try std.testing.expect(!try file.inheritAllocatorCertificate());
        try std.testing.expect(!file.free_pages_verified);
        try std.testing.expect(!try file.certifyAllocator());
        try file.completeAllocatorVerification();
        try std.testing.expect(try file.certifyAllocator());
        try std.testing.expect((try file.check()).valid);
    }
}

// perf/lwa-peer-cert: every other certificate test in this file builds its
// `NativeFile` with `createWithIo`/`CreateOptions`, which never attaches a
// redo log (`self.redo` stays null) unless `createWithRedoLog`/
// `enableRedoLog` is called explicitly -- so `stageAllocatorCertificate`'s
// `self.redo == null or self.redo.?.checkpointing` check was always true
// for them, and the certificate it sealed always matched the real
// publish's unconditional slot flip. The redo log is the *default* one
// layer up (`docstore.zig`'s `opts.use_redo_log orelse true`), so a real
// writer's own `certifyAllocator()` call almost always has `self.redo`
// active and not mid-checkpoint -- the one case none of those tests ever
// exercised. There, the real commit diverts into an in-place redo-log
// append (`publishCheckpoint`'s ride-along/fresh-append branches: `self
// .header.checkpoints[self.header.active_checkpoint]` is overwritten,
// `active_checkpoint` never moves), while `stageAllocatorCertificate`
// still fingerprinted a header that assumed the v8/v9 flip -- sealing the
// certificate against a slot arrangement the real publish never produced,
// so every later `inheritAllocatorCertificate` replay of the identical
// formula disagreed with it.
test "lite native allocator certificate seals against the slot a redo-diverted commit actually publishes" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "redo-certificate-inherit.aflite");
    defer a.free(path);
    const active_before_seal, const sequence_before_seal = blk: {
        var file = try NativeFile.createWithRedoLog(a, std.testing.io, path, .{ .indexed_reclamation = true }, 256 * 1024);
        defer file.close();
        try file.beginTransaction();
        try file.putCatalogRecord("seed", "value");
        try file.commitTransaction();
        try std.testing.expect(file.free_pages_verified);
        // Exactly the common, previously-untested case: an active redo
        // log, not mid-checkpoint, so the imminent certifying commit
        // below diverts into an in-place append rather than a real
        // v8/v9 slot write.
        try std.testing.expect(file.redo != null and !file.redo.?.checkpointing);
        const before = file.activeCheckpoint();
        try std.testing.expect(try file.certifyAllocator());
        const after = file.activeCheckpoint();
        // Confirms the divert actually happened as expected: the commit
        // advanced but never flipped which physical slot is active.
        try std.testing.expect(after.commit_sequence != before.commit_sequence);
        break :blk .{ file.header.active_checkpoint, after.commit_sequence };
    };
    // A fresh handle on the same file -- recovers the redo log from disk,
    // exactly like a peer process (or, within one process, a post-refresh
    // reopen) opening after a certifying peer closed. Before this fix,
    // the certificate `certifyAllocator` just sealed disagreed with this
    // handle's own, correctly-recovered header, and this returned `false`.
    var peer = try NativeFile.openWithIo(a, std.testing.io, path, .{});
    defer peer.close();
    try std.testing.expectEqual(active_before_seal, peer.header.active_checkpoint);
    try std.testing.expectEqual(sequence_before_seal, peer.activeCheckpoint().commit_sequence);
    try std.testing.expect(!peer.free_pages_verified);
    try std.testing.expect(try peer.inheritAllocatorCertificate());
    try std.testing.expect(peer.free_pages_verified);
}

test "lite allocator v4 live certificates share the caller transaction and reject unchecked writers" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "live-certificate.aflite");
    defer a.free(path);
    {
        var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
        defer file.close();
        file.externally_locked = true;
        file.allocator_certificate_on_commit = true;
        const sequence = file.activeCheckpoint().commit_sequence;
        const catalog = file.activeCheckpoint().catalog_root_page;
        try file.beginTransaction();
        try file.putDocument("one", "committed");
        try file.putDocument("two", "same transaction");
        try file.commitTransactionWithDurability(false, null);
        try std.testing.expectEqual(sequence + 1, file.activeCheckpoint().commit_sequence);
        try std.testing.expectEqual(catalog, file.activeCheckpoint().catalog_root_page);
        var peer = try NativeFile.openWithIo(a, std.testing.io, path, .{ .read_only = true, .internal_reader = true });
        defer peer.close();
        try std.testing.expect(try peer.inheritAllocatorCertificate());
        try std.testing.expect((try peer.check()).valid);
    }
    {
        var unchecked = try NativeFile.openWithIo(a, std.testing.io, path, .{ .no_sync = true });
        defer unchecked.close();
        unchecked.defer_allocator_verification = true;
        unchecked.allocator_certificate_on_commit = true;
        try unchecked.beginArtifactLeaseTransaction();
        try unchecked.putCatalogRecord(NativeFile.artifact_lease_key_prefix ++ "unchecked", "unchecked append-only publication");
        try unchecked.commitTransaction();
        try std.testing.expect(!unchecked.free_pages_verified);
        var peer = try NativeFile.openWithIo(a, std.testing.io, path, .{ .read_only = true, .internal_reader = true });
        defer peer.close();
        try std.testing.expect(!try peer.inheritAllocatorCertificate());
        try std.testing.expect((try peer.check()).valid);
    }
}

