    var value: [128 * 1024]u8 = @splat('v');
    for (0..8) |i| {
        var key: [16]u8 = undefined;
        value[0] = @intCast(i);
        try file.putDocument(try std.fmt.bufPrint(&key, "doc-{d}", .{i}), &value);
    }
    // Vacuum publishes two identical recovery slots. Both must remain fully
    // checked, with each shared immutable payload read only once per proof.
    _ = try file.vacuum();
    file.page_cache_enabled.store(false, .monotonic);
    const checkpoint = file.activeCheckpoint();
    const state = try file.loadLedger(checkpoint);
    const before_single = file.test_page_reads.load(.monotonic);
    var graph = try file.indexedGraph(checkpoint, null, null);
    defer graph.deinit(a);
    const single = file.test_page_reads.load(.monotonic) - before_single;
    const before_proof = file.test_page_reads.load(.monotonic);
    try std.testing.expectEqual(@as(u64, 8), try file.validateIndexedAllocator(checkpoint, state, null));
    const proof = file.test_page_reads.load(.monotonic) - before_proof;
    try std.testing.expect(single > 256);
    try std.testing.expect(proof < single * 3 / 2);
}

test "lite allocator v4 small checkpoints bound counter and queue boundary growth" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "small-checkpoint-boundaries.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    file.reserve_retirement_capacity = true;
    var pages = try file.pageAllocatorFromFreeMap(file.activeCheckpoint());
    defer pages.deinit();
    const counter_entries = (file.maxPagePayloadBytes() - 24) / 4;
    const queue_entries = (file.maxPagePayloadBytes() - 16) / 48;
    const first = pages.next_page_id;
    while (pages.next_page_id < counter_entries - 2) {
        const page = try pages.allocate();
        try pages.writePage(page, .data, "raw block");
    }
    for (0..queue_entries - 1) |i| try pages.ledger.?.retire(.{ .epoch = file.publicationEpoch(), .page = first + i, .kind = .page });
    var checkpoint = file.activeCheckpoint();
    checkpoint.commit_sequence += 1;
    checkpoint.free_map_root_page = try pages.allocate();
    try file.advanceAllocatorCheckpoint(&pages, 1);
    try std.testing.expect(pages.ledger.?.force_checkpoint);
    try pages.flush();
    const writes = file.test_page_writes.load(.monotonic);
    try file.persistAllocator(&pages, &checkpoint);
    try std.testing.expect(file.test_page_writes.load(.monotonic) - writes <= 5);
    try std.testing.expectEqual(@as(u64, 0), pages.ledger.?.root.deltas);
    try std.testing.expectEqual(@as(u64, 0), pages.ledger.?.root.build_limit);
    try file.publishCheckpoint(checkpoint, false, null);
    file.invalidateLedger();
    try std.testing.expect((try file.check()).valid);
}

test "lite allocator v4 owner checkpoints bound metadata work across reopen and cancellation" {
    const CancelWrite = struct {
        var token: ?*maintenance.CancelToken = null;
        fn write(userdata: ?*anyopaque, file: std.Io.File, header: []const u8, data: []const []const u8, splat: usize, offset: u64) std.Io.File.WritePositionalError!usize {
            const written = try std.testing.io.vtable.fileWritePositional(userdata, file, header, data, splat, offset);
            if (token) |cancel| cancel.request();
            return written;
        }
    };
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "incremental-owner-checkpoint.aflite");
    defer a.free(path);
    {
        var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
        defer file.close();
        file.reserve_retirement_capacity = true;
        var pages = try file.pageAllocatorFromFreeMap(file.activeCheckpoint());
        defer pages.deinit();
        for (0..20_000) |_| {
            const page = try pages.allocate();
            try pages.writePage(page, .data, "raw block");
        }
        var checkpoint = file.activeCheckpoint();
        checkpoint.commit_sequence += 1;
        checkpoint.free_map_root_page = try pages.allocate();
        try file.persistAllocator(&pages, &checkpoint);
        try file.publishCheckpoint(checkpoint, false, null);
        const writes = file.test_page_writes.load(.monotonic);
        _ = try file.reclaimPages(1);
        try std.testing.expect(file.ledger.?.root.build_limit != 0);
        // One counter chunk plus bounded service/journal publication, regardless
        // of the twenty-page counter table that remains to be snapshotted.
        try std.testing.expect(file.test_page_writes.load(.monotonic) - writes < 16);
    }
    var vtable = std.testing.io.vtable.*;
    vtable.fileWritePositional = CancelWrite.write;
    const io = std.Io{ .userdata = std.testing.io.userdata, .vtable = &vtable };
    var file = try NativeFile.openWithIo(a, io, path, .{ .no_sync = true });
    defer file.close();
    file.reserve_retirement_capacity = true;
    const before = file.activeCheckpoint();
    const bytes = (try file.file.stat(std.testing.io)).size;
    var cancel = maintenance.CancelToken{};
    cancel.request();
    try std.testing.expectError(error.MaintenanceCanceled, file.reclaimPagesWithCancel(1, &cancel));
    try std.testing.expectEqualDeep(before, file.activeCheckpoint());
    try std.testing.expectEqual(bytes, (try file.file.stat(std.testing.io)).size);
    cancel.requested.store(false, .release);
    CancelWrite.token = &cancel;
    defer CancelWrite.token = null;
    try std.testing.expectError(error.MaintenanceCanceled, file.reclaimPagesWithCancel(1, &cancel));
    CancelWrite.token = null;
    try std.testing.expectEqualDeep(before, file.activeCheckpoint());
    try std.testing.expectEqual(bytes, (try file.file.stat(io)).size);
    try std.testing.expect(!file.checkpoint_publication_uncertain);
    cancel.requested.store(false, .release);
    file.invalidateLedger();
    const reads = file.test_page_reads.load(.monotonic);
    file.test_cancel_on_read = &cancel;
    defer file.test_cancel_on_read = null;
    try std.testing.expectError(error.MaintenanceCanceled, file.reclaimPagesWithCancel(1, &cancel));
    file.test_cancel_on_read = null;
    try std.testing.expect(file.test_page_reads.load(.monotonic) - reads <= 2);
    try std.testing.expectEqualDeep(before, file.activeCheckpoint());
    cancel.requested.store(false, .release);
    const remaining = (try file.loadLedger(before)).root.build_end;
    try file.putDocumentBatch(&.{.{ .key = "live", .value = "concurrent change" }});
    try std.testing.expectEqual(@max(@as(u64, 1), remaining -| (2 * ((file.maxPagePayloadBytes() - 24) / 4))), file.ledger.?.root.build_end);
    var batches: usize = 0;
    while (try file.retirementNeedsService()) : (batches += 1) {
        try std.testing.expect(batches < 500);
        _ = try file.reclaimPagesWithCancel(1, &cancel);
    }
    try std.testing.expect(batches > 16);
    try std.testing.expect((try file.check()).valid);
    const value = (try file.getDocumentAlloc(a, "live")).?;
    defer a.free(value);
    try std.testing.expectEqualStrings("concurrent change", value);
    // Private catch-up may have a sequence newer than the live generation.
    // Normalization must finish an active builder and persist rebased events.
    file.ledger.?.force_checkpoint = true;
    _ = try file.reclaimPages(1);
    try std.testing.expect(file.ledger.?.root.build_limit != 0);
    try file.preparePublicationSequence(1);
    file.invalidateLedger();
    try std.testing.expect((try file.check()).valid);
}

/// Per-operation admission for newly written external payload pages. Catalog
/// records and tree navigation pages remain eligible for caching. Bypassing
/// admission still invalidates both cached bytes and links for reused page IDs.
pub const WriteOptions = struct {
    payload_cache: enum { normal, cold_sequential } = .normal,
};

const recovery_agenda = @import("recovery_agenda.zig");

// v8: both formats moved their two recovery slots out of the header page
// into dedicated pages and gained a per-commit manifest (see
// `slotPhysicalPage`, `CheckpointSlot`, `recoverActiveCheckpoint`).
// v9 (lite-single-commit-write-path.md §3.2a "Manifest coverage"): the
// manifest payload encodes one or more appended page-id runs instead of
// exactly one (see `encodeManifestPayloadAlloc`/`verifyManifest`), so a
// commit whose appended pages span more than one contiguous range (several
// `commit_participant`s each triggering their own intermediate
// `flushTransactionWrites`/`persistAllocator` cycle, in particular) still
// gets the one-sync manifest path instead of always falling back to the
// two-sync presynced one.
// Antfly is unreleased, so no old layout is preserved: any file written by
// a build before this version bump -- v3/v7 (pre-v8), v4/v8 (single-run
// manifest), or any of the v5/v9/redo-v1 three-way magic split that
// preceded the unified feature-flags header below -- is refused by
// `decodeHeader`'s magic/version checks (surfaced as
// `error.InvalidNativeMagic`/`error.UnsupportedNativeFormatVersion`), not
// migrated.
//
// docs/design/lite-performance/lite-single-commit-write-path.md §9.5/§9.7a:
// a file's mode (indexed reclamation, redo-log commit, record packing) used
// to be encoded as which of several magic byte strings `encodeHeader`
// chose, with `decodeHeader` inferring the mode back from a magic
// equality check -- so two modes could never be combined (redo log and
// indexed reclamation specifically: `docstore.zig`'s `createWithOptions`
// and `NativeFile.createWithRedoLog(OwnedIo)` both refused the
// combination, since there was no single magic that meant both). This is
// replaced by one magic that means only "an aflite native file, format
// `format_version`", plus an explicit `feature_flags` word (see
// `feature_flags_offset`) carrying each mode as its own bit -- extensible
// to a fourth/fifth mode without ever needing another magic string or
// another priority-ordered branch.
// v11 (perf/lwa-fold-boundary): the checkpoint slot payload grows by one
// field, `redo_folded_through` (`checkpoint_slot_payload_size` 136 -> 144)
// -- the real, durable fold boundary a slot's own roots reflect,
// independent of its `commit_sequence`. A v10-or-earlier build has no way
// to interpret the extra 8 bytes (nor to know it must), so this is a hard
// version bump, refused the same way v9->v10 was, not a migration:
// Antfly is unreleased.
pub const magic = "AFLITE\x0cP";
pub const format_version: u32 = 11;
pub const default_page_size: u32 = 4096;

/// §9.5/§9.7a: explicit, independently-encoded mode bits, read from/written
/// to `feature_flags_offset`. Replaces the old magic-implied mode
/// inference (see `magic`'s own doc comment) -- a mode's bit is set (or
/// not) based purely on the `Header` field it corresponds to, never on
/// which other bits are also set, so any combination round-trips exactly
/// as written. Add new bits here as new modes are introduced; never reuse
/// a retired bit's position (none are retired yet).
const feature_flag_redo_log: u32 = 1 << 0;
const feature_flag_indexed_reclamation: u32 = 1 << 1;
const feature_flag_packed_records: u32 = 1 << 2;

