test "lite allocator v4 overwrite reuses pages across reopen" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "allocator-v4.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true });
    defer file.close();
    const value = try a.alloc(u8, 16384);
    defer a.free(value);
    @memset(value, 'x');
    for (0..80) |_| {
        try file.putDocument("doc", value);
        try file.putCatalogRecord("catalog", value);
    }
    const before = file.activeCheckpoint().page_count;
    for (0..80) |_| {
        try file.putDocument("doc", value);
        try file.putCatalogRecord("catalog", value);
    }
    // Each of these 160 bare commits reserves its own fresh manifest page
    // (`reserveBareCommitManifestPage` -- always a fresh id, never a reused
    // one, by design: see `PageAllocator.allocateFresh`), on top of the
    // pre-WS1(b) growth this bound already allowed for. Retirement reclaims
    // those pages for later reuse, bounded per commit, so growth is still
    // bounded, not unbounded -- just within a wider margin that accounts
    // for up to one extra page per commit in this window.
    try std.testing.expect(file.activeCheckpoint().page_count < before + 32 + 160);
    const got = (try file.getDocumentAlloc(a, "doc")).?;
    defer a.free(got);
    try std.testing.expectEqualSlices(u8, value, got);
    file.close();
    file = try NativeFile.openWithIo(a, std.testing.io, path, .{});
    for (0..20) |_| try file.putDocument("doc", value);
    const reopened = (try file.getDocumentAlloc(a, "doc")).?;
    defer a.free(reopened);
    try std.testing.expectEqualSlices(u8, value, reopened);
}
test "lite coordinated data readers permit reuse while preserving snapshots and foreign fences" {
    const a = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "coordinated-reuse.aflite");
    defer a.free(path);
    var coordinator = ReaderCoordinator.init(a, io);
    defer coordinator.deinit();
    var writer = try NativeFile.createWithIo(a, io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer writer.close();
    writer.reader_coordinator = &coordinator;
    var value: [8192]u8 = @splat('a');
    for (0..80) |_| try writer.putDocument("doc", &value);
    // This contract deliberately retains only logical document data. Generic
    // read-only opens also inspect allocator metadata and use full fences.
    var reader = try NativeFile.openWithIo(a, io, path, .{ .read_only = true, .internal_reader = true, .reader_coordinator = &coordinator });
    try reader.acquireReaderFence(writer.activeCheckpoint().commit_sequence, &writer);
    var reader_open = true;
    defer if (reader_open) reader.close();
    const before = (try writer.allocatorStats()).?.reused_pages;
    value[0] = 'b';
    for (0..20) |_| try writer.putDocument("doc", &value);
    try std.testing.expect((try writer.allocatorStats()).?.reused_pages > before);
    const captured = (try reader.getDocumentAlloc(a, "doc")).?;
    defer a.free(captured);
    try std.testing.expectEqual(@as(u8, 'a'), captured[0]);
    var external = try NativeFile.openWithIo(a, io, path, .{ .read_only = true });
    const blocked = (try writer.allocatorStats()).?.reused_pages;
    for (0..4) |_| try writer.putDocument("doc", &value);
    try std.testing.expectEqual(blocked, (try writer.allocatorStats()).?.reused_pages);
    external.close();
    try writer.putDocument("doc", &value);
    try std.testing.expect((try writer.allocatorStats()).?.reused_pages > blocked);
    try std.testing.expect((try writer.check()).valid);
    // A writer allocation can evict an idle source synchronously. Its close
    // must be able to unregister even while the reuse window is active.
    var pages = try writer.pageAllocatorFromFreeMap(writer.activeCheckpoint());
    reader.close();
    reader_open = false;
    pages.deinit();
    try writer.putDocument("after-close", "safe");
    try std.testing.expect((try writer.check()).valid);
}

