test "lite coordinator publication cancellation never performs fallible notification IO" {
    const Fault = struct {
        var cancel_stat: bool = false;
        var cancel_write: bool = false;
        var cancel_after_commit: bool = false;
        var writes: usize = 0;
        fn stat(userdata: ?*anyopaque, handle: std.Io.File) std.Io.File.StatError!std.Io.File.Stat {
            if (cancel_stat) return error.Canceled;
            return std.testing.io.vtable.fileStat(userdata, handle);
        }
        fn write(userdata: ?*anyopaque, handle: std.Io.File, header: []const u8, data: []const []const u8, splat: usize, offset: u64) std.Io.File.WritePositionalError!usize {
            writes += 1;
            if (cancel_write) {
                cancel_stat = true;
                return error.Canceled;
            }
            const written = try std.testing.io.vtable.fileWritePositional(userdata, handle, header, data, splat, offset);
            // The slot write is now the last write of the publication window
            // (there is no trailing active_checkpoint hint write).
            if (cancel_after_commit and (offset == slotPhysicalPage(0) * @as(u64, default_page_size) or offset == slotPhysicalPage(1) * @as(u64, default_page_size))) cancel_stat = true;
            return written;
        }
    };
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "publication-cancel.aflite");
    defer a.free(path);
    var vtable = std.testing.io.vtable.*;
    vtable.fileStat = Fault.stat;
    vtable.fileWritePositional = Fault.write;
    const io = std.Io{ .userdata = std.testing.io.userdata, .vtable = &vtable };
    var coordinator = ReaderCoordinator.init(a, std.testing.io);
    defer coordinator.deinit();
    var file = try NativeFile.createWithIo(a, io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    file.reader_coordinator = &coordinator;
    try file.putDocument("stable", "before");
    const before = file.header;
    var checkpoint = file.activeCheckpoint();
    checkpoint.commit_sequence += 1;
    defer {
        Fault.cancel_stat = false;
        Fault.cancel_write = false;
        Fault.cancel_after_commit = false;
    }
    Fault.writes = 0;
    Fault.cancel_stat = true;
    try std.testing.expectError(error.Canceled, file.publishCheckpoint(checkpoint, false, null));
    try std.testing.expectEqual(@as(usize, 0), Fault.writes);
    try std.testing.expectEqualDeep(before, file.header);
    try std.testing.expect(!file.checkpoint_publication_uncertain);
    Fault.cancel_stat = false;
    Fault.cancel_write = true;
    // Cancellation inside the uncertain window reports an unknown outcome.
    try std.testing.expectError(error.OutcomeUnknown, file.publishCheckpoint(checkpoint, false, null));
    try std.testing.expect(file.checkpoint_publication_uncertain);
    try std.testing.expectEqualDeep(before, file.header);
    Fault.cancel_stat = false;
    Fault.cancel_write = false;
    file.close();
    file = try NativeFile.openWithIo(a, io, path, .{ .no_sync = true, .reader_coordinator = &coordinator });
    try std.testing.expectEqualDeep(before, file.header);
    // Cancellation after the active-slot write cannot undo a committed result
    // or make its coordinator notification abort the process.
    Fault.cancel_after_commit = true;
    try file.publishCheckpoint(checkpoint, false, null);
    try std.testing.expect(!file.checkpoint_publication_uncertain);
    try std.testing.expectEqual(checkpoint, file.activeCheckpoint());
    Fault.cancel_after_commit = false;
    Fault.cancel_stat = false;
    const value = (try file.getDocumentAlloc(a, "stable")).?;
    defer a.free(value);
    try std.testing.expectEqualStrings("before", value);
    try std.testing.expect((try file.check()).valid);
}

// `checkpoint_publication_uncertain` means "a publication failed in a way
// that may have left disk ahead of header", never merely "a publication is
// in flight" -- see that field's doc comment. `publication_in_flight` is
// the separate signal for the latter: true for the whole span of one
// `publishCheckpoint` call past its point of no return, regardless of
// outcome, so a concurrent reader that only needs "wait for this to
// finish" never mistakes an ordinary in-flight commit for one needing
// reconciliation. This checks the field's lifecycle around both outcomes
// from the same thread (never stuck `true` after a call returns, either
// way); a cross-thread check that a concurrent reader observes it mid-sync
// without tripping reconciliation needs the as-yet-unmerged lock-release
// path (`sync_lock_hooks`) this fix prepares for to actually let anything
// run concurrently with the sync in the first place.
test "lite publication_in_flight never outlives a publishCheckpoint call, on either outcome" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "publication-in-flight.aflite");
    defer a.free(path);

    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true });
    defer file.close();
    try std.testing.expect(!file.publication_in_flight);
    try std.testing.expect(!file.checkpoint_publication_uncertain);

    try file.putDocument("doc", "durable");
    try std.testing.expect(!file.publication_in_flight);
    try std.testing.expect(!file.checkpoint_publication_uncertain);

    // An injected failure during that same window still latches
    // `checkpoint_publication_uncertain` and still reconciles, exactly as
    // before this change -- only the proactive, before-the-fact set is
    // gone. `publication_in_flight` clears regardless of outcome.
    file.test_fail_checkpoint_publication = error.InputOutput;
    try std.testing.expectError(error.OutcomeUnknown, file.putDocument("doc", "durable again"));
    try std.testing.expect(!file.publication_in_flight);
    try std.testing.expect(file.checkpoint_publication_uncertain);
    try file.reconcilePublicationUncertainty();
    try std.testing.expect(!file.checkpoint_publication_uncertain);
}

