// WS1(d): a page retired by a not-yet-durable commit must stay out of the
// reusable pool until a durability barrier actually makes that commit
// durable. Without `durable_header` folded into the reuse frontier
// (`metadataReuseFrontier`/`reuseFrontier`), reclamation driven purely off
// `self.header` (which a deferred commit already advances in memory) would
// promote these pages for reuse before the generation that retired them is
// durable — unsafe once a future pipelined group commit lets the next
// group stage while the current one's fsync is still outstanding, since a
// crash mid-fsync must still recover a prior checkpoint whose pages were
// never overwritten.
test "lite allocator v4 reuse frontier withholds pages retired by undurable commits" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reuse-durable-epoch.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true });
    defer file.close();
    const first: [32768]u8 = @splat('a');
    const second: [32768]u8 = @splat('b');
    // A durable baseline: "doc" occupies a whole page, not a packed record.
    try file.putDocument("doc", &first);
    try std.testing.expect(try file.certifyAllocator());

    // Many deferred (non-durable) overwrites retire that page's successive
    // replacements, all at epochs above the durable checkpoint, without
    // ever crossing a durability barrier.
    for (0..48) |i| {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("doc", if (i % 2 == 0) &second else &first);
        try file.commitTransactionWithDurability(false, null);
    }
    try std.testing.expect(file.durable_header != null);
    const pending_before = (try file.allocatorStats()).?.pending_data_objects;
    try std.testing.expect(pending_before > 0);

    // Reclamation must not free any of those pages yet: at the moment its
    // own drain runs, `durable_header` still pins the frontier at the
    // pre-barrier checkpoint, even though reclaimPages's own commit will
    // itself cross the barrier by the time it returns.
    _ = try file.reclaimPages(4096);
    try std.testing.expectEqual(@as(u64, 0), (try file.allocatorStats()).?.reusable_pages);
    try std.testing.expect(file.durable_header == null);
    try std.testing.expect((try file.check()).valid);

    // Now that the barrier crossed, the same backlog is eligible: drive
    // reclamation until the ledger reports no more service is due, and
    // confirm pages were actually freed for reuse.
    var rounds: usize = 0;
    while (try file.retirementNeedsService()) : (rounds += 1) {
        try std.testing.expect(rounds < 1000);
        _ = try file.reclaimPages(4096);
    }
    try std.testing.expect((try file.allocatorStats()).?.reusable_pages > 0);
    try std.testing.expect((try file.check()).valid);
}

// §9.6a follow-up: a plain, uncoordinated in-process reader -- no
// `reader_coordinator`, so it never claims a `shared_lock_region.Region`
// slot -- must still withhold the writer's page reuse for as long as it
// holds its own snapshot. `captureFullReadSnapshot`'s own reader is
// exactly this category (vacuum's verification snapshot uses the same
// path): before the inode_lock.Entry reader-pin registry existed, this
// reader was invisible to `reuseFrontier`'s combined computation, so
// nothing stopped the writer from reusing (and overwriting) a page this
// reader still depended on.
test "lite uncoordinated snapshot reader pins its checkpoint and survives page reuse" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reader-pin-reuse.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true });
    defer file.close();
    const first: [32768]u8 = @splat('a');
    const second: [32768]u8 = @splat('b');
    // A durable baseline: "doc" occupies a whole page, not a packed record.
    try file.putDocument("doc", &first);
    try std.testing.expect(try file.certifyAllocator());

    // No `reader_coordinator` is configured anywhere in this test, so
    // `captureFullReadSnapshot`'s `coordinated` is false: this snapshot
    // never claims a region slot or registers with a `ReaderCoordinator`
    // -- exactly the category the reader-pin registry exists for.
    var snapshot = try file.captureFullReadSnapshot();
    var snapshot_open = true;
    defer if (snapshot_open) snapshot.close();
    try std.testing.expect(snapshot.reader_pin_entry != null);
    const old = (try snapshot.getDocumentAlloc(a, "doc")).?;
    defer a.free(old);
    try std.testing.expectEqualStrings(&first, old);

    // Many durable overwrites retire "doc"'s successive page replacements,
    // all at sequences above the pinned snapshot's own. Reclamation must
    // withhold every one of them while the snapshot above stays open --
    // unlike the "undurable commits" case above, this backlog never
    // drains on its own while the pin holds (nothing about calling
    // `reclaimPages` itself resolves an external pin the way crossing a
    // durability barrier resolves `durable_header`), so a bounded number
    // of drive attempts, not a `retirementNeedsService`-driven loop, is
    // the right shape here.
    for (0..48) |i| try file.putDocument("doc", if (i % 2 == 0) &second else &first);
    for (0..16) |_| _ = try file.reclaimPages(4096);
    try std.testing.expectEqual(@as(u64, 0), (try file.allocatorStats()).?.reusable_pages);

    // The pinned snapshot still reads its own, untouched page correctly --
    // not a reused/overwritten one -- proving the pin actually withheld
    // reuse rather than merely coinciding with it.
    const still_old = (try snapshot.getDocumentAlloc(a, "doc")).?;
    defer a.free(still_old);
    try std.testing.expectEqualStrings(&first, still_old);
    try std.testing.expect((try file.check()).valid);

    // Releasing the pin (closing the snapshot) lets the same backlog
    // become reclaimable.
    snapshot.close();
    snapshot_open = false;
    var rounds: usize = 0;
    while (try file.retirementNeedsService()) : (rounds += 1) {
        try std.testing.expect(rounds < 1000);
        _ = try file.reclaimPages(4096);
    }
    try std.testing.expect((try file.allocatorStats()).?.reusable_pages > 0);
    try std.testing.expect((try file.check()).valid);
}

test "lite allocator v4 rollback and recovery retain the fallback root" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reuse-recovery.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    for (0..100) |_| try file.putDocument("doc", "stable");
    const checkpoint = file.activeCheckpoint();
    try file.beginTransaction();
    try file.putDocument("doc", "discarded");
    _ = try file.materializeTransactionCheckpoint();
    file.abortTransaction();
    try std.testing.expect(std.meta.eql(checkpoint, file.activeCheckpoint()));
    try std.testing.expect((try file.check()).valid);
    try file.putDocument("doc", "newest");
    const damaged = slotPhysicalPage(file.header.active_checkpoint) * @as(u64, file.header.page_size) + page_crc_offset;
    var bad: [4]u8 = @splat(0);
    try file.file.writePositionalAll(file.runtimeIo(), &bad, damaged);
    file.close();
    file = try NativeFile.openWithIo(a, std.testing.io, path, .{ .no_sync = true });
    const recovered = (try file.getDocumentAlloc(a, "doc")).?;
    defer a.free(recovered);
    try std.testing.expectEqualStrings("stable", recovered);
    for (0..40) |_| try file.putDocument("doc", "recovered");
    try std.testing.expect((try file.check()).valid);
}

// Regression for dc74b9a91c ("evict reused-page cache entries on
// failed/rolled-back commits") plus this change's own extension of it to
// `secondary_page_cache` (the read generation's independent `PageCache`,
// see `Store.initializeReadGenerationAssumeLocked` in docstore.zig).
//
// Repro shape: a transaction writes (and, via `flushTransactionWrites`,
// physically caches) a page id the free list is about to hand out again,
// then fails *after* that flush but *before* `publishCheckpoint` --
// `abortTransaction`/`discardTransactionTail` is the lowest-level stand-in
// for every such failure (an ordinary `errdefer` in
// `commitTransactionWithDurability`, a group member's own
// `rollbackTransactionSavepoint`, or this direct call). An identical retry
// then reuses the exact same page id (the free list the failed attempt drew
// from is otherwise untouched) and must read its own fresh write back, not
// the aborted attempt's abandoned content still sitting in either cache.
test "lite native evicts both the writer and read-generation page cache for a reused page after an aborted commit" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reuse-abort-cache.aflite");
    defer a.free(path);

    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();

    // Baseline: durable content for "doc", and pin down which page id its
    // value occupies -- "doc" is small enough to pack inline, so force a
    // dedicated page with a value that cannot be packed.
    const stable: [32768]u8 = @splat('s');
    for (0..3) |_| try file.putDocument("doc", &stable);
    const stable_checkpoint = file.activeCheckpoint();

    // Stand in for a secondary reader generation (docstore.zig's
    // `initializeReadGenerationAssumeLocked` wires this identically:
    // `self.file.secondary_page_cache = &generation.file.page_cache`) --
    // a second, independent handle onto the same path with its own cache.
    // Real callers always pass an explicit, separately-tracked checkpoint
    // for reads through this handle (`Store.observeReadCheckpoint` keeps
    // `ReadGeneration.checkpoint` current via `self.file.publication_observer`
    // -- the reader's own `self.header` is never touched after open), so
    // this test tracks `reader_checkpoint` the same way instead of relying
    // on `reader.activeCheckpoint()`.
    var reader = try NativeFile.openWithIo(a, std.testing.io, path, .{ .read_only = true, .no_sync = true });
    defer reader.close();
    file.secondary_page_cache = &reader.page_cache;
    var reader_checkpoint = stable_checkpoint;

    // Prime both caches on the page the next write will reuse: a read
    // through each handle for the current (small) value.
    {
        const seen = (try file.getDocumentAlloc(a, "doc")).?;
        a.free(seen);
        const seen_via_reader = (try reader.getDocumentAtCheckpointAlloc(a, reader_checkpoint, "doc")).?;
        a.free(seen_via_reader);
    }

    // Fails after flushTransactionWrites (which physically writes and
    // caches the reused page) but before publishCheckpoint.
    const discarded: [32768]u8 = @splat('d');
    try file.beginTransaction();
    try file.putDocument("doc", &discarded);
    _ = try file.materializeTransactionCheckpoint();
    file.abortTransaction();

    try std.testing.expect(std.meta.eql(stable_checkpoint, file.activeCheckpoint()));
    try std.testing.expect((try file.check()).valid);

    // The aborted attempt's page is back under "doc"'s old, stable
    // checkpoint, so re-reading it (through either handle) must prove no
    // stale "discarded" bytes survive in either cache -- `getCopy` only
    // ever returns a cache hit, never reads through to disk, so a bug here
    // would read back "discarded", not merely slow down.
    {
        const after_abort = (try file.getDocumentAlloc(a, "doc")).?;
        defer a.free(after_abort);
        try std.testing.expectEqualStrings(&stable, after_abort);
        const after_abort_via_reader = (try reader.getDocumentAtCheckpointAlloc(a, reader_checkpoint, "doc")).?;
        defer a.free(after_abort_via_reader);
        try std.testing.expectEqualStrings(&stable, after_abort_via_reader);
    }

    // The retry: an unrelated write that reuses the exact same page id the
    // aborted attempt drew from (the free list was never touched by the
    // abort). Its own fresh content must come back, not the abandoned one.
    const retried: [32768]u8 = @splat('r');
    try file.putDocument("doc", &retried);
    reader_checkpoint = file.activeCheckpoint();
    const after_retry = (try file.getDocumentAlloc(a, "doc")).?;
    defer a.free(after_retry);
    try std.testing.expectEqualStrings(&retried, after_retry);
    const after_retry_via_reader = (try reader.getDocumentAtCheckpointAlloc(a, reader_checkpoint, "doc")).?;
    defer a.free(after_retry_via_reader);
    try std.testing.expectEqualStrings(&retried, after_retry_via_reader);
    try std.testing.expect((try file.check()).valid);
}

test "lite allocator v4 rejects a durable free bit for a live page" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reuse-corruption.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    try file.putDocument("doc", "safe");
    var checkpoint = file.activeCheckpoint();
    const state = try file.loadLedger(checkpoint);
    try std.testing.expect(try state.release(checkpoint.document_index_root_page));
    var pages = PageAllocator{ .file = &file, .free_pages = &.{}, .next_page_id = checkpoint.page_count, .ledger = state, .can_reuse = false };
    defer pages.deinit();
    checkpoint.commit_sequence += 1;
    checkpoint.free_map_root_page = try pages.allocate();
    try file.persistAllocator(&pages, &checkpoint);
    try file.publishCheckpoint(checkpoint, false, null);
    const report = try file.check();
    try std.testing.expect(!report.valid);
    try std.testing.expectEqualStrings("invalid_allocator", report.issue.?);
    file.free_pages_verified = false;
    try std.testing.expectError(error.InvalidNativeAllocator, file.prepareAllocatorVerification(null));
    try std.testing.expect(!file.free_pages_verified);
    // Read-path aliases can append safely even with an untrusted ledger.
    // They cannot reuse the corrupt free claim or authorize an authored write.
    try file.beginArtifactLeaseTransaction();
    errdefer file.abortTransaction();
    try std.testing.expectError(error.InvalidArtifactLeaseMutation, file.putDocument("other", "refused"));
    try std.testing.expectError(error.InvalidArtifactLeaseMutation, file.putIndexCatalogRecord("index", "refused"));
    try file.putCatalogRecord(NativeFile.artifact_lease_key_prefix ++ "probe", "lease");
    try file.commitTransaction();
    try std.testing.expect(!file.free_pages_verified);
    _ = try file.reclaimPagesForMaintenanceWithCancel(1, null, true);
    try std.testing.expect(!file.free_pages_verified);
    const preserved = (try file.getDocumentAlloc(a, "doc")).?;
    defer a.free(preserved);
    try std.testing.expectEqualStrings("safe", preserved);
    try std.testing.expectError(error.InvalidNativeAllocator, file.putDocument("other", "refused"));
}

test "lite allocator v4 allocation failures release every private owner" {
    const Runner = struct {
        fn run(a: Allocator) !void {
            const backing = std.testing.allocator;
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            const path = try testPath(backing, tmp, "reuse-allocation-failures.aflite");
            defer backing.free(path);
            // Create and close through the same wrapper `a` for the whole
            // lifecycle. NativeFile's own long-lived state (ledger,
            // manifest_builder, free-map bookkeeping) is built up starting
            // at creation and only ever fully freed later, by `close()`;
            // creating with `backing` and only switching `self.allocator`
            // to `a` afterward (or switching back to `backing` before
            // `close()`, tried first) makes some of those bytes allocated
            // through one wrapper and freed through the other. Both are
            // real `std.testing.allocator` bytes either way (`a` only ever
            // forwards to `backing`) -- replaying this exact body,
            // fail_index by fail_index, directly against
            // std.testing.allocator's own leak-tracking GPA never reported
            // a leak under any allocator-swapping arrangement -- but
            // checkAllAllocationFailures' own per-wrapper-instance
            // allocated/freed byte counters see a false mismatch (a "leak"
            // or, as bad, a free with no matching tracked allocation)
            // whenever creation and close disagree on which wrapper to use.
            // One allocator for the full lifecycle removes the mismatch.
            var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
            file.invalidateLedger();
            file.page_cache.clear(a);
            file.page_cache_enabled.store(false, .monotonic);
            defer {
                file.abortTransaction();
                file.close();
            }
            const value: [8192]u8 = @splat('v');
            try file.putDocument("doc", &value);
            try file.beginTransaction();
            errdefer file.abortTransaction();
            try file.putDocument("doc", "updated");
            try file.putIndexCatalogRecord("index", &value);
            try file.appendIndexCatalogRecord("index", "tail");
            try file.commitTransaction();
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Runner.run, .{});
}

test "lite allocator v4 large deletes enqueue bounded foreground work" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reuse-large-delete.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    const value = try a.alloc(u8, 4 * 1024 * 1024);
    defer a.free(value);
    @memset(value, 'v');
    try file.putDocument("large", value);
    file.test_page_reads.store(0, .monotonic);
    try file.deleteDocument("large");
    try std.testing.expect(file.test_page_reads.load(.monotonic) < 16);
    var rounds: usize = 0;
    while (try file.retirementNeedsService()) : (rounds += 1) {
        try std.testing.expect(rounds < 1000);
        try std.testing.expect(try file.reclaimPages(8) <= 8);
    }
    try std.testing.expect(rounds > 100);
    try std.testing.expect(file.ledger.?.free_pages > 700);
    try std.testing.expect(file.ledger.?.collected > 1000);
    try std.testing.expect((try file.check()).valid);
}

pub const header_size: usize = 4096;
pub const checkpoint_slot_count = 2;
pub const page_magic = "AFLP";
pub const page_header_size: usize = 16;

const magic_offset: usize = 0;
const version_offset: usize = 8;
const page_size_offset: usize = 12;
const header_size_offset: usize = 16;
const reader_epoch_namespace_offset: usize = 24;
/// §9.1/§9.5: only meaningful (and only written) when `feature_flags`'s
/// `feature_flag_redo_log` bit is set. Fixed for the file's lifetime once
/// set at creation (`NativeFile.enableRedoLog`) -- the log region never
/// grows or moves.
const redo_log_offset_offset: usize = 56;
const redo_log_capacity_offset: usize = 64;
/// §9.5/§9.7a: the explicit mode-bits word (`feature_flag_*`). Placed
/// right after `redo_log_capacity` (which ends at byte 72); the next new
/// field after this one belongs at byte 76.
const feature_flags_offset: usize = 72;
const header_checksum_offset: usize = header_size - 4;
const page_crc_offset: usize = 12;

/// v8: a recovery slot is a dedicated page, physically separate from the
/// static header page and from the other slot, so a torn write of one can
/// never damage either the header or the other slot (the three used to
/// share header sector 0). Slot pages are permanently reserved, never
/// reused by the allocator: `reserved_header_pages` (the header plus both
/// slots) is the smallest legal `page_count`, and the lowest ordinary data
/// page id.
const reserved_header_pages: u64 = 1 + checkpoint_slot_count;
fn slotPhysicalPage(slot_index: u8) u64 {
    return 1 + @as(u64, slot_index);
}

/// Every page the commit wrote, for recovery to re-verify a non-presynced
/// slot without a full reachability walk: a (page id, CRC-at-write-time)
/// pair per page. Commits at or under this many distinct pages get the
/// 1-sync path (manifest written alongside the slot, one barrier); larger
/// commits fall back to the historical "sync data, then sync the slot"
/// order and are marked `presynced` (recovery trusts them unconditionally,
/// as today).
pub const max_single_sync_pages: usize = 1024;

pub const PageKind = enum(u8) {
    data = 1,
    catalog = 2,
    document = 3,
    value = 4,
    free_map = 5,
    document_index = 6,
    value_extent = 7,
    catalog_index = 8,
    record_bundle = 9,
    allocator = 10,
    key = 11,
    checkpoint_slot = 12,
    commit_manifest = 13,
};

// Record references reserve the high bit and a 16-bit byte offset. Ordinary
// page IDs retain their existing encoding; packed references never name value
// or index pages. Bounds and record boundaries are checked before decoding.
const packed_record_flag: u64 = @as(u64, 1) << 63;
const packed_page_mask: u64 = (@as(u64, 1) << 47) - 1;
fn physicalPage(reference: u64) u64 {
    return if (reference & packed_record_flag != 0) reference & packed_page_mask else reference;
}

fn recordWalkLimit(checkpoint: CheckpointSlot, page_size: u32) u64 {
    return checkpoint.page_count *| @as(u64, page_size / 4);
}

const catalog_key_len_mask: u32 = 0x00ff_ffff;
const catalog_delete_flag: u32 = 1 << 31;
const catalog_external_value_flag: u32 = 1 << 30;
const document_delete_flag: u8 = 1 << 0;
const document_external_value_flag: u8 = 1 << 1;
const document_namespace_link_flag: u8 = 1 << 2;
const document_content_digest_flag: u8 = 1 << 3;

fn documentHeaderSize(indexed: bool, key: []const u8) usize {
    // The digest flag belongs to indexed v7. Legacy v3 must remain readable
    // by its original readers; fingerprints can hash those values on demand.
    return if (indexed and std.mem.indexOf(u8, key, "\x00\x00__metadata__:") != null) 60 else 28;
}
const namespace_directory_key = "\x00antfly.document_namespaces.v1";
pub const secret_catalog_prefix = "\x00antfly.secrets.v1/";
const namespace_directory_magic = "AFNSIDX2";
const namespace_directory_snapshot_interval: u16 = 256;
const value_page_header_size: usize = 8;
const free_map_format_version: u32 = 1;
const free_map_header_size: usize = 16;
const document_index_magic = "AFDIDX02";
const document_index_header_size: usize = 12;

const DocumentIndexNodeKind = enum(u8) {
    leaf = 1,
    internal = 2,
};

// Bound every encoded key slot so an insertion can always split into two
// pages. Long keys borrow their bytes from immutable catalog/document records;
// separators retain the same record reference through copy-on-write splits.
const index_inline_key_limit = 512;
const index_external_key_marker = std.math.maxInt(u16);

const DocumentIndexNode = struct {
    kind: DocumentIndexNodeKind,
    keys: [][]u8,
    pointers: []u64,
    key_pages: ?[]u64 = null,
    /// Backing storage for every *inline* key in `keys`, one allocation
    /// instead of one `dupe` per key (a document-index leaf/internal node
    /// commonly has dozens of keys; `decodeDocumentIndexNode` used to call
    /// `allocator.dupe` once per key, measured as the single largest
    /// allocation-site contributor in the write-amplification CPU
    /// attribution -- ~472 allocations/write out of ~887 total, since a
    /// commit can decode several such nodes along the root-to-leaf path).
    /// `keys[i]` is a slice into this buffer when `key_pages[i] == 0`
    /// (inline). *External* keys (`key_pages[i] != 0`) are deliberately
    /// excluded: they stay their own individual (if zero-size) allocation
    /// exactly as before, because `resolveIndexKey` later frees and
    /// replaces exactly one such key in place once it resolves the real
    /// content from disk -- that `allocator.free` call requires the key to
    /// be its own allocation, not a sub-slice of this shared buffer. `null`
    /// only when no inline key needed any storage (every key external, or
    /// zero keys), matching `allocator.free` on a `null` being a no-op.
    key_storage: ?[]u8 = null,

    pub fn deinit(self: *DocumentIndexNode, allocator: Allocator) void {
        if (self.key_pages) |pages| {
            for (self.keys, pages) |key, page| if (page != 0) allocator.free(key);
        }
        if (self.key_storage) |storage| allocator.free(storage);
        allocator.free(self.keys);
        allocator.free(self.pointers);
        if (self.key_pages) |pages| allocator.free(pages);
        self.* = undefined;
    }
};

pub const DocumentIndexEntry = struct {
    key: []u8,
    document_page_id: u64,

    pub fn deinit(self: *DocumentIndexEntry, allocator: Allocator) void {
        allocator.free(self.key);
        self.* = undefined;
    }
};

/// Validated immutable index page. Inline keys borrow the retained page;
/// overflow comparisons use one reusable record buffer, never a key array.
const IndexReadFrame = IndexReadFrameType(false);
// Compare an index key with namespace ++ canonical key without materializing
// a second key batch. Exact bytes (including embedded zeroes) decide equality.
const PrefixedReadKey = struct {
    prefix: []const u8,
    key: []const u8,
    fn order(self: @This(), indexed: []const u8) std.math.Order {
        const count = @min(indexed.len, self.prefix.len);
        const prefix_order = std.mem.order(u8, indexed[0..count], self.prefix[0..count]);
        if (prefix_order != .eq) return prefix_order;
        if (indexed.len < self.prefix.len) return .lt;
        return std.mem.order(u8, indexed[self.prefix.len..], self.key);
    }
};

fn readKeyOrder(indexed: []const u8, wanted: anytype) std.math.Order {
    if (comptime @TypeOf(wanted) == PrefixedReadKey) return wanted.order(indexed);
    return std.mem.order(u8, indexed, wanted);
}

const BatchIndexReadFrame = IndexReadFrameType(true);

// Only batch frames carry leases and an allocator override. Ordinary readers
// and writers keep their original layout and allocation footprint.
fn IndexReadFrameType(comptime batch: bool) type {
    return struct {
        raw: ?[]u8 = null,
        payload: []const u8 = &.{},
        offsets: std.ArrayListUnmanaged(u16) = .empty,
        kind: DocumentIndexNodeKind = .leaf,
        position: usize = 0,
        overflow: ?[]u8 = null,
        overflow_reference: u64 = 0,
        overflow_key: []const u8 = &.{},

        working_allocator: if (batch) ?Allocator else void = if (batch) null else {},
        // Borrowing a cached, already-validated index view is not a
        // batch-only concern (PageCache.acquireIndex/IndexView are general
        // infrastructure); every ordinary single-key reader used to always
        // decode+CRC-validate a fresh scratch-buffer copy instead, even on a
        // page this process already verified or wrote. Kept as real fields
        // (not further comptime-gated by `batch`) so `load` below can borrow
        // for both frame kinds; `working_allocator`'s own batch-only
        // allocator override is unrelated and untouched.
        borrowed: ?*PageCache.IndexView = null,
        borrowed_file: ?*NativeFile = null,

        fn workingAllocator(self: *const @This(), file: *NativeFile) Allocator {
            return if (batch) self.working_allocator orelse file.allocator else file.allocator;
        }

        fn releaseView(self: *@This()) void {
            if (self.borrowed) |view| self.borrowed_file.?.page_cache.releaseIndex(self.borrowed_file.?.allocator, view);
            self.borrowed = null;
            self.borrowed_file = null;
            self.payload = &.{};
        }

        fn entries(self: *const @This()) []const u16 {
            if (self.borrowed) |view| return view.frame.offsets.items;
            return self.offsets.items;
        }

        pub fn deinit(self: *@This(), allocator: Allocator) void {
            self.releaseView();
            if (self.raw) |raw| allocator.free(raw);
            if (self.overflow) |raw| allocator.free(raw);
            self.offsets.deinit(allocator);
        }

        /// Kept as a name distinct from `load` for existing callers; both
        /// now do the same thing (try the cache's validated view first).
        fn loadBorrowed(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, page: u64) !void {
            return self.load(file, checkpoint, page);
        }

        fn load(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, page: u64) !void {
            self.releaseView();
            self.overflow_reference = 0;
            self.overflow_key = &.{};
            if (page == 0 or page >= checkpoint.page_count) return error.InvalidPageId;
            if (file.page_cache_enabled.load(.monotonic) and file.page_cache_bypass.load(.monotonic) == 0) {
                if (try file.page_cache.acquireIndex(file.allocator, page)) |view| {
                    self.borrowed = view;
                    self.borrowed_file = file;
                    self.payload = view.frame.payload;
                    self.kind = view.frame.kind;
                    self.position = 0;
                    if (builtin.is_test) _ = file.test_index_view_hits.fetchAdd(1, .monotonic);
                    return;
                }
            }
            if (self.raw == null or self.raw.?.len < file.header.page_size) {
                const a = self.workingAllocator(file);
                const raw = try a.alloc(u8, file.header.page_size);
                if (self.raw) |old| a.free(old);
                self.raw = raw;
            }
            const payload = try decodePagePayload(try file.readPageInto(page, checkpoint, self.raw.?), .document_index);
            try self.decode(self.workingAllocator(file), payload);
        }

        fn decode(self: *@This(), allocator: Allocator, payload: []const u8) !void {
            self.payload = &.{};
            self.offsets.clearRetainingCapacity();
            self.position = 0;
            if (payload.len < document_index_header_size or !std.mem.eql(u8, payload[0..8], document_index_magic) or payload[9] != 0)
                return error.InvalidDocumentIndex;
            self.kind = switch (payload[8]) {
                1 => .leaf,
                2 => .internal,
                else => return error.InvalidDocumentIndex,
            };
            const count = std.mem.readInt(u16, payload[10..12], .little);
            var pos: usize = document_index_header_size + @as(usize, if (self.kind == .internal) 8 else 0);
            if (pos > payload.len or count > (payload.len - pos) / 10 or (self.kind == .leaf and count == 0)) return error.InvalidDocumentIndex;
            try self.offsets.ensureTotalCapacity(allocator, count);
            var previous_inline: ?[]const u8 = null;
            for (0..count) |_| {
                if (pos + 10 > payload.len) return error.InvalidDocumentIndex;
                const offset: u16 = @intCast(pos);
                const len = std.mem.readInt(u16, payload[pos..][0..2], .little);
                pos += 10;
                if (len == index_external_key_marker) {
                    if (pos + 8 > payload.len or std.mem.readInt(u64, payload[pos..][0..8], .little) == 0) return error.InvalidDocumentIndex;
                    pos += 8;
                    previous_inline = null;
                } else {
                    if (len > index_inline_key_limit or pos + len > payload.len) return error.InvalidDocumentIndex;
                    const key_bytes = payload[pos..][0..len];
                    if (previous_inline) |previous| if (std.mem.order(u8, previous, key_bytes) != .lt) return error.InvalidDocumentIndex;
                    previous_inline = key_bytes;
                    pos += len;
                }
                self.offsets.appendAssumeCapacity(offset);
            }
            if (pos != payload.len) return error.InvalidDocumentIndex;
            self.payload = payload;
        }

        fn pointerCount(self: *const @This()) usize {
            return self.entries().len + @as(usize, if (self.kind == .internal) 1 else 0);
        }

        fn pointer(self: *const @This(), index: usize) u64 {
            if (self.kind == .internal and index == 0)
                return std.mem.readInt(u64, self.payload[document_index_header_size..][0..8], .little);
            const slot = if (self.kind == .internal) index - 1 else index;
            const offset = @as(usize, self.entries()[slot]) + 2;
            return std.mem.readInt(u64, self.payload[offset..][0..8], .little);
        }

        fn key(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, index: usize) ![]const u8 {
            const offset: usize = self.entries()[index];
            const len = std.mem.readInt(u16, self.payload[offset..][0..2], .little);
            if (len != index_external_key_marker) return self.payload[offset + 10 ..][0..len];
            const reference = std.mem.readInt(u64, self.payload[offset + 10 ..][0..8], .little);
            if (reference == self.overflow_reference) return self.overflow_key;
            // Invalidate before a fallible read: an error must not leave a cached
            // reference pointing at overwritten or partially validated bytes.
            self.overflow_reference = 0;
            self.overflow_key = &.{};
            if (self.overflow == null or self.overflow.?.len < file.header.page_size) {
                const a = self.workingAllocator(file);
                const raw = try a.alloc(u8, file.header.page_size);
                if (self.overflow) |old| a.free(old);
                self.overflow = raw;
            }
            const raw = try file.readPageInto(reference, checkpoint, self.overflow.?);
            const bytes = switch (raw[4]) {
                @backingInt(PageKind.catalog) => (try decodeCatalogEntry(try decodePagePayload(raw, .catalog))).key,
                @backingInt(PageKind.document) => (try decodeDocumentEntry(try decodePagePayload(raw, .document))).key,
                @backingInt(PageKind.key) => try NativeFile.decodeKey(try decodePagePayload(raw, .key)),
                else => return error.InvalidDocumentIndex,
            };
            if (bytes.len <= index_inline_key_limit) return error.InvalidDocumentIndex;
            self.overflow_key = bytes;
            self.overflow_reference = reference;
            return bytes;
        }

        fn keyReference(self: *const @This(), index: usize) u64 {
            const offset: usize = self.entries()[index];
            if (std.mem.readInt(u16, self.payload[offset..][0..2], .little) != index_external_key_marker) return 0;
            return std.mem.readInt(u64, self.payload[offset + 10 ..][0..8], .little);
        }

        fn bound(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, wanted: anytype, upper: bool) !usize {
            var low: usize = 0;
            var high = self.entries().len;
            while (low < high) {
                if (builtin.is_test) _ = file.test_index_comparisons.fetchAdd(1, .monotonic);
                const mid = low + (high - low) / 2;
                const order = readKeyOrder(try self.key(file, checkpoint, mid), wanted);
                if (order == .lt or (upper and order == .eq)) low = mid + 1 else high = mid;
            }
            return low;
        }

        // Sorted requests normally stay at the same separator or advance one
        // slot. Gallop from the previous bound, then binary-search the gap; this
        // avoids re-reading overflow separators for every dense request while
        // sparse batches still skip unrelated keys logarithmically.
        fn boundFrom(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, wanted: anytype, upper: bool, start: usize) !usize {
            const count = self.entries().len;
            if (start == count) return count;
            const first_order = readKeyOrder(try self.key(file, checkpoint, start), wanted);
            if (first_order == .gt or (!upper and first_order == .eq)) return start;
            var low = start + 1;
            var high = count;
            var stride: usize = 1;
            while (low < count) : (stride *= 2) {
                const probe = @min(start + stride, count - 1);
                const order = readKeyOrder(try self.key(file, checkpoint, probe), wanted);
                if (order == .gt or (!upper and order == .eq)) {
                    high = probe;
                    break;
                }
                low = probe + 1;
            }
            while (low < high) {
                const mid = low + (high - low) / 2;
                const order = readKeyOrder(try self.key(file, checkpoint, mid), wanted);
                if (order == .lt or (upper and order == .eq)) low = mid + 1 else high = mid;
            }
            return low;
        }
    };
}

/// Reuse buffers by depth across siblings and seeks. Frame addresses remain
/// stable when the path grows, including during recursive batch traversal.
const IndexReadPath = IndexReadPathType(false);
const BatchIndexReadPath = IndexReadPathType(true);
fn IndexReadPathType(comptime batch: bool) type {
    const Frame = IndexReadFrameType(batch);
    return struct {
        allocator: if (batch) ?Allocator else void = if (batch) null else {},
        frames: std.ArrayListUnmanaged(*Frame) = .empty,

        pub fn deinit(self: *@This(), allocator: Allocator) void {
            for (self.frames.items) |frame| {
                frame.deinit(allocator);
                allocator.destroy(frame);
            }
            self.frames.deinit(allocator);
        }

        fn load(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, depth: usize, page: u64) !*Frame {
            return self.loadMode(file, checkpoint, depth, page, false);
        }

        fn loadMode(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, depth: usize, page: u64, borrowed: bool) !*Frame {
            const allocator = if (batch) self.allocator orelse file.allocator else file.allocator;
            if (depth > 64) return error.InvalidDocumentIndex;
            if (depth == self.frames.items.len) {
                const frame = try allocator.create(Frame);
                errdefer allocator.destroy(frame);
                frame.* = .{ .working_allocator = if (batch) self.allocator else {} };
                try self.frames.append(allocator, frame);
            }
            const frame = self.frames.items[depth];
            if (batch and borrowed) try frame.loadBorrowed(file, checkpoint, page) else try frame.load(file, checkpoint, page);
            return frame;
        }
    };
}

/// §9.7c (`ReadView`): the raw B-tree walker, with no overlay knowledge
/// at all -- renamed from `DocumentIndexCursor` to say so plainly. Reads
/// *only* the physical, checkpointed page structure named by whatever
/// `checkpoint` it is given; a key logged-but-not-yet-folded by
/// `checkpointRedoLog` is invisible through this type by construction,
/// not by omission. Intended callers are `checkpointRedoLog`'s own
/// fold, vacuum, and recovery (which want exactly the physical tree, on
/// purpose), plus `CatalogCursor`/`LiveRecordCursor`/`ReadView` here in
/// native.zig, which wrap it with the overlay merge every other reader
/// needs. A new caller anywhere else should go through `ReadView`
/// instead of reaching for this directly -- still possible to do (kept
/// `pub` so existing, already-reviewed callers keep compiling), but a
/// deliberate, greppable code-review smell: `grep -n CheckpointedTree`
/// should only ever turn up the handful of sites listed above.
const CheckpointedTree = struct {
    file: *NativeFile,
    checkpoint: CheckpointSlot,
    path: IndexReadPath = .{},
    depth: usize = 0,
    key_allocator: Allocator,

    pub fn init(file: *NativeFile, checkpoint: CheckpointSlot) CheckpointedTree {
        return initWithKeyAllocator(file, checkpoint, file.allocator);
    }

    /// Returned entries own their keys through key_allocator. Traversal scratch
    /// remains file-owned; callers must free entries with the supplied allocator.
    pub fn initWithKeyAllocator(file: *NativeFile, checkpoint: CheckpointSlot, key_allocator: Allocator) CheckpointedTree {
        return .{ .file = file, .checkpoint = checkpoint, .key_allocator = key_allocator };
    }

    pub fn deinit(self: *CheckpointedTree) void {
        self.path.deinit(self.file.allocator);
        self.* = undefined;
    }

    pub fn first(self: *CheckpointedTree) !?DocumentIndexEntry {
        self.clear();
        errdefer self.clear();
        if (self.checkpoint.document_index_root_page == 0) return null;
        try self.descendExtreme(self.checkpoint.document_index_root_page, true);
        return try self.currentEntry();
    }

    pub fn last(self: *CheckpointedTree) !?DocumentIndexEntry {
        self.clear();
        errdefer self.clear();
        if (self.checkpoint.document_index_root_page == 0) return null;
        try self.descendExtreme(self.checkpoint.document_index_root_page, false);
        return try self.currentEntry();
    }

    pub fn seekAtOrAfter(self: *CheckpointedTree, key: []const u8, strict: bool) !?DocumentIndexEntry {
        self.clear();
        errdefer self.clear();
        var page = self.checkpoint.document_index_root_page;
        while (page != 0) {
            const frame = try self.push(page);
            frame.position = try frame.bound(self.file, self.checkpoint, key, if (frame.kind == .leaf) strict else true);
            if (frame.kind == .leaf) {
                if (frame.position < frame.entries().len) return try self.currentEntry();
                return try self.next();
            }
            page = frame.pointer(frame.position);
        }
        return null;
    }

    pub fn seekAtOrBefore(self: *CheckpointedTree, key: []const u8, strict: bool) !?DocumentIndexEntry {
        self.clear();
        errdefer self.clear();
        var page = self.checkpoint.document_index_root_page;
        while (page != 0) {
            const frame = try self.push(page);
            const bound = try frame.bound(self.file, self.checkpoint, key, if (frame.kind == .leaf) !strict else true);
            if (frame.kind == .leaf) {
                frame.position = if (bound == 0) 0 else bound - 1;
                if (bound > 0) return try self.currentEntry();
                return try self.prev();
            }
            frame.position = bound;
            page = frame.pointer(bound);
        }
        return null;
    }

    pub fn next(self: *CheckpointedTree) !?DocumentIndexEntry {
        errdefer self.clear();
        if (self.depth == 0) return null;
        const leaf = self.path.frames.items[self.depth - 1];
        if (leaf.kind != .leaf) return error.InvalidDocumentIndex;
        if (leaf.position + 1 < leaf.entries().len) {
            leaf.position += 1;
            return try self.currentEntry();
        }
        self.depth -= 1;
        while (self.depth > 0) {
            const parent = self.path.frames.items[self.depth - 1];
            if (parent.kind != .internal) return error.InvalidDocumentIndex;
            if (parent.position + 1 < parent.pointerCount()) {
                parent.position += 1;
                try self.descendExtreme(parent.pointer(parent.position), true);
                return try self.currentEntry();
            }
            self.depth -= 1;
        }
        return null;
    }

    fn subtreePage(self: *CheckpointedTree, depth: usize) u64 {
        return if (depth == 0) self.checkpoint.document_index_root_page else blk: {
            const parent = self.path.frames.items[depth - 1];
            break :blk parent.pointer(parent.position);
        };
    }

    // Advance to a sibling without opening it. Paired cursors can skip equal
    // immutable sibling references without an I/O for every leaf in the range.
    fn nextSubtree(self: *CheckpointedTree, depth: usize) !u64 {
        self.depth = depth;
        while (self.depth > 0) {
            const parent = self.path.frames.items[self.depth - 1];
            if (parent.kind != .internal) return error.InvalidDocumentIndex;
            if (parent.position + 1 < parent.pointerCount()) {
                parent.position += 1;
                return parent.pointer(parent.position);
            }
            self.depth -= 1;
        }
        return 0;
    }

    pub fn prev(self: *CheckpointedTree) !?DocumentIndexEntry {
        errdefer self.clear();
        if (self.depth == 0) return null;
        const leaf = self.path.frames.items[self.depth - 1];
        if (leaf.kind != .leaf) return error.InvalidDocumentIndex;
        if (leaf.position > 0 and leaf.position <= leaf.entries().len) {
            leaf.position -= 1;
            return try self.currentEntry();
        }
        self.depth -= 1;
        while (self.depth > 0) {
            const parent = self.path.frames.items[self.depth - 1];
            if (parent.kind != .internal) return error.InvalidDocumentIndex;
            if (parent.position > 0) {
                parent.position -= 1;
                try self.descendExtreme(parent.pointer(parent.position), false);
                return try self.currentEntry();
            }
            self.depth -= 1;
        }
        return null;
    }

    fn push(self: *CheckpointedTree, page: u64) !*IndexReadFrame {
        const frame = try self.path.load(self.file, self.checkpoint, self.depth, page);
        self.depth += 1;
        return frame;
    }

    fn descendExtreme(self: *CheckpointedTree, root: u64, first_key: bool) !void {
        var page = root;
        while (page != 0) {
            const frame = try self.push(page);
            frame.position = if (first_key) 0 else frame.pointerCount() - 1;
            page = if (frame.kind == .internal) frame.pointer(frame.position) else 0;
        }
    }

    fn currentEntry(self: *CheckpointedTree) !?DocumentIndexEntry {
        if (self.depth == 0) return null;
        const frame = self.path.frames.items[self.depth - 1];
        if (frame.kind != .leaf or frame.position >= frame.entries().len) return null;
        return .{
            .key = try self.key_allocator.dupe(u8, try frame.key(self.file, self.checkpoint, frame.position)),
            .document_page_id = frame.pointer(frame.position),
        };
    }

    fn clear(self: *CheckpointedTree) void {
        self.depth = 0;
    }
};

/// A view of one immutable physical record page. Borrow shared authenticated
/// pages and bundle boundaries when admitted; otherwise reuse bounded local
/// scratch. Payload slices remain valid until the next physical page is loaded.
/// The caller must keep the file generation and checkpoint pinned for its life.
pub const RecordPageReader = struct {
    raw: ?[]u8 = null,
    lease: ?*PageCache.RawView = null,
    lease_file: ?*NativeFile = null,
    payload: []const u8 = &.{},
    page_id: u64 = 0,
    kind: PageKind = .data,
    offsets: std.ArrayListUnmanaged(u16) = .empty,
    record_position: usize = 0,

    pub fn deinit(self: *RecordPageReader, allocator: Allocator) void {
        if (self.lease) |lease| self.lease_file.?.page_cache.releaseRaw(self.lease_file.?.allocator, lease);
        if (self.raw) |raw| allocator.free(raw);
        self.offsets.deinit(allocator);
        self.* = .{};
    }

    pub fn read(self: *RecordPageReader, file: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, reference: u64, expected: PageKind) ![]const u8 {
        return self.readWithWindow(false, null, file, allocator, checkpoint, reference, expected, 1);
    }

    /// Only callers with sorted, known references supply a multi-page run.
    /// The window is allocated lazily and admits pages only when requested.
    fn readWithWindow(self: *RecordPageReader, comptime windowed: bool, window: ?*RecordReadWindow, file: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, reference: u64, expected: PageKind, ahead: usize) ![]const u8 {
        return self.readWithWindowAllocators(windowed, window, file, allocator, allocator, checkpoint, reference, expected, ahead);
    }
    fn readWithWindowAllocators(self: *RecordPageReader, comptime windowed: bool, window: ?*RecordReadWindow, file: *NativeFile, allocator: Allocator, optional_allocator: Allocator, checkpoint: CheckpointSlot, reference: u64, expected: PageKind, ahead: usize) ![]const u8 {
        const page = physicalPage(reference);
        if (page == 0 or page >= checkpoint.page_count) return error.InvalidPageId;
        const bundled = reference & packed_record_flag != 0;
        const kind: PageKind = if (bundled) .record_bundle else expected;
        if (self.page_id != page or (self.lease_file != null and self.lease_file != file) or
            (self.lease != null and (!file.page_cache_enabled.load(.monotonic) or file.page_cache_bypass.load(.monotonic) != 0)) or
            (windowed and window.?.count != 0 and file.page_cache_bypass.load(.monotonic) != 0))
        {
            // Invalidate before any fallible load, so a failed validation can
            // never leave a reusable, partially validated view.
            self.page_id = 0;
            self.payload = &.{};
            self.offsets.clearRetainingCapacity();
            self.record_position = 0;
            if (windowed) window.?.record_offset_count = 0;
            if (self.lease) |lease| self.lease_file.?.page_cache.releaseRaw(self.lease_file.?.allocator, lease);
            self.lease = null;
            self.lease_file = null;
            if (file.page_cache_enabled.load(.monotonic) and file.page_cache_bypass.load(.monotonic) == 0) {
                self.lease = try file.page_cache.acquirePayload(file.allocator, page, file.header.page_size);
                if (self.lease != null) self.lease_file = file;
            }
            if (self.lease) |lease| {
                if (builtin.is_test) _ = file.test_page_reads.fetchAdd(1, .monotonic);
                const validation = lease.validation.?;
                if (validation.kind != kind) {
                    file.page_cache.releaseRaw(file.allocator, lease);
                    self.lease = null;
                    self.lease_file = null;
                    return error.UnexpectedNativePageKind;
                }
                self.payload = lease.bytes[page_header_size..][0..validation.payload_len];
            } else {
                if (windowed) {
                    const raw = try window.?.readAllocators(file, allocator, optional_allocator, checkpoint, page, ahead);
                    if (builtin.is_test) _ = file.test_page_reads.fetchAdd(1, .monotonic);
                    self.payload = try decodePagePayload(raw, kind);
                    if (file.page_cache_enabled.load(.monotonic) and file.page_cache_bypass.load(.monotonic) == 0 and file.admitPageToCache(raw)) file.page_cache.put(file.allocator, page, raw);
                } else {
                    if (self.raw == null) self.raw = try allocator.alloc(u8, file.header.page_size);
                    _ = try file.readPageInto(page, checkpoint, self.raw.?);
                    self.payload = try decodePagePayload(self.raw.?, kind);
                }
            }
            if (bundled and (self.lease == null or self.lease.?.record_offsets == null)) {
                var offset: usize = 0;
                if (windowed) {
                    while (offset < self.payload.len and window.?.record_offset_count < window.?.record_offsets.len) {
                        const record = try packedRecordAtOffset(self.payload, offset);
                        window.?.record_offsets[window.?.record_offset_count] = @intCast(offset);
                        window.?.record_offset_count += 1;
                        offset += 4 + record.bytes.len;
                    }
                    if (offset < self.payload.len) {
                        // At most one spill allocation: every record has a
                        // four-byte length prefix, bounding the entry count.
                        try self.offsets.ensureTotalCapacity(allocator, self.payload.len / 4);
                        try self.offsets.appendSlice(allocator, window.?.record_offsets[0..window.?.record_offset_count]);
                        window.?.record_offset_count = 0;
                    }
                }
                while (offset < self.payload.len) {
                    const record = try packedRecordAtOffset(self.payload, offset);
                    try self.offsets.append(allocator, @intCast(offset));
                    offset += 4 + record.bytes.len;
                }
            }
            self.kind = kind;
            self.page_id = page;
        }
        if (self.kind != kind) return error.InvalidNativePageKind;
        if (!bundled) return self.payload;
        const local_offsets = if (windowed and window.?.record_offset_count != 0) window.?.record_offsets[0..window.?.record_offset_count] else self.offsets.items;
        const offsets = if (self.lease) |lease| lease.record_offsets orelse local_offsets else local_offsets;
        const wanted: u16 = @intCast((reference >> 47) & 0xffff);
        var low = self.record_position;
        // Ordered scans normally request the same or the next record. Reuse
        // the cursor position before falling back to binary search for seeks.
        if (low >= offsets.len or offsets[low] != wanted) {
            if (low < offsets.len and low + 1 < offsets.len and offsets[low + 1] == wanted) {
                low += 1;
            } else {
                low = 0;
                var high = offsets.len;
                while (low < high) {
                    const mid = low + (high - low) / 2;
                    if (offsets[mid] < wanted) low = mid + 1 else high = mid;
                }
            }
        }
        if (low == offsets.len or offsets[low] != wanted) return error.InvalidPageId;
        self.record_position = low;
        const record = try packedRecordAtOffset(self.payload, wanted);
        if (record.kind != expected) return error.InvalidNativePageKind;
        return record.bytes;
    }

    /// Validate the record and its key without touching external value pages.
    /// Legacy v3 indexes may still reference tombstones.
    pub fn documentIsLive(self: *RecordPageReader, file: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, indexed: DocumentIndexEntry) !bool {
        const entry = try decodeDocumentEntry(try self.read(file, allocator, checkpoint, indexed.document_page_id, .document));
        if (!std.mem.eql(u8, entry.key, indexed.key)) return error.InvalidDocumentIndex;
        return !entry.is_delete;
    }

    /// The document's real logical size (key plus value) without touching
    /// external value pages: an external value stores its length inline in
    /// the document's own index-page header record (`external_value_len`),
    /// so this costs exactly the same one bounded page read as
    /// `documentIsLive`, never the external value's own pages. WS5's
    /// journal-retirement ledger release uses this so a large document's
    /// replay entry is never materialized just to account for its deletion.
    pub fn documentValueLen(self: *RecordPageReader, file: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, indexed: DocumentIndexEntry) !?usize {
        const entry = try decodeDocumentEntry(try self.read(file, allocator, checkpoint, indexed.document_page_id, .document));
        if (!std.mem.eql(u8, entry.key, indexed.key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return null;
        return if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
    }

    pub fn documentValueAlloc(self: *RecordPageReader, file: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, indexed: DocumentIndexEntry) !?[]u8 {
        const entry = try decodeDocumentEntry(try self.read(file, allocator, checkpoint, indexed.document_page_id, .document));
        if (!std.mem.eql(u8, entry.key, indexed.key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return null;
        return if (entry.external_value_root_page != 0)
            try file.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint)
        else
            try allocator.dupe(u8, entry.value);
    }
};

/// Batch-local read-ahead state. Ordinary record readers retain their original
/// layout and compile a path with no window checks or storage. Only proven
/// adjacent requests use this lazily allocated, bounded buffer.
const RecordReadWindow = struct {
    bytes: ?[]u8 = null,
    file: ?*NativeFile = null,
    first: u64 = 0,
    count: usize = 0,
    growth_failed: bool = false,
    // Ordinary 4 KiB bundles fit without allocating a boundary list. This
    // storage belongs only to batch windows, preserving the point-reader ABI.
    record_offsets: [256]u16 = undefined,
    record_offset_count: usize = 0,

    fn deinit(self: *RecordReadWindow, allocator: Allocator) void {
        if (self.bytes) |bytes| allocator.free(bytes);
        self.* = .{};
    }

    fn contains(self: *const RecordReadWindow, file: *NativeFile, page: u64) bool {
        return self.count != 0 and self.file == file and page >= self.first and page - self.first < self.count;
    }

    fn read(self: *RecordReadWindow, file: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, page: u64, ahead: usize) ![]const u8 {
        return self.readAllocators(file, allocator, allocator, checkpoint, page, ahead);
    }
    fn readAllocators(self: *RecordReadWindow, file: *NativeFile, allocator: Allocator, optional_allocator: Allocator, checkpoint: CheckpointSlot, page: u64, ahead: usize) ![]const u8 {
        const bypass = file.page_cache_bypass.load(.monotonic) != 0;
        const size: usize = file.header.page_size;
        if (!bypass and self.contains(file, page)) return self.bytes.?[@as(usize, @intCast(page - self.first)) * size ..][0..size];
        self.count = 0;
        var count: usize = @intCast(@min(if (bypass) 1 else ahead, 16, (64 * 1024) / size, checkpoint.page_count - page));
        // Single-page requests need only page-sized scratch until a run appears.
        const needed = count * size;
        if (self.bytes == null or (!self.growth_failed and self.bytes.?.len < needed)) {
            const growth_allocator = if (count > 1) optional_allocator else allocator;
            if (growth_allocator.alloc(u8, needed)) |bytes| {
                if (self.bytes) |old| allocator.free(old);
                self.bytes = bytes;
            } else |_| {
                self.growth_failed = true;
                // Read-ahead is optional. Keep existing page-sized storage or
                // fall back to it when the larger window cannot be allocated.
                if (self.bytes == null) self.bytes = try allocator.alloc(u8, size);
            }
        }
        count = @min(count, self.bytes.?.len / size);
        const use_cache = file.page_cache_enabled.load(.monotonic) and !bypass;
        if (use_cache and file.page_cache.copyInto(page, self.bytes.?[0..size])) {
            self.first = page;
            self.file = file;
            self.count = 1;
            return self.bytes.?[0..size];
        }
        try file.readBackingPages(self.bytes.?[0 .. count * size], page * size);
        self.first = page;
        self.file = file;
        self.count = if (bypass) 0 else count;
        return self.bytes.?[0..size];
    }
};

pub fn decodeScore(raw: []const u8) !f64 {
    if (raw.len != 8) return error.InvalidGraphMetricScore;
    const score: f64 = @bitCast(std.mem.readInt(u64, raw[0..8], .little));
    if (!std.math.isFinite(score)) return error.InvalidGraphMetricScore;
    return score;
}

/// Independently owned scores/offsets for one request at one pinned snapshot.
/// Prepared requests retain only decoded scores and an owned identity; generic
/// requests also own keys and offsets. No reader, descriptor, or cache pin is
/// retained. Bounded optional construction leaves streaming reads available.
pub const ResolvedScoreBatch = struct {
    const Binding = struct { owner: u64, generation: u64 };
    storage: ?[]u8 = null,
    binding: ?Binding = null,
    checkpoint: CheckpointSlot = .{},
    keys: []const []const u8 = &.{},
    references: []u64 = &.{},
    order: ?[]usize = null,
    decoded: []f64 = &.{},
    decoded_ready: bool = false,
    borrowed: bool = false,
    recovered_optional_failure: bool = false,
    promotion_allocator: ?Allocator = null,
    prepared_identity: ?ReadIdentity = null,
    prepared_count: usize = 0,
    compact: bool = false,

    pub fn deinit(self: *@This(), a: Allocator) void {
        const promotion = self.promotion_allocator;
        const recovered = self.recovered_optional_failure;
        if (self.storage) |bytes| (promotion orelse a).free(bytes);
        self.* = .{ .promotion_allocator = promotion, .recovered_optional_failure = recovered };
    }

    fn matches(self: *const @This(), binding: Binding, checkpoint: CheckpointSlot, keys: []const []const u8) bool {
        if (self.compact or self.binding == null or !std.meta.eql(self.binding.?, binding) or
            !std.meta.eql(self.checkpoint, checkpoint) or self.keys.len != keys.len) return false;
        for (self.keys, keys) |owned, key| if (!std.mem.eql(u8, owned, key)) return false;
        return true;
    }

    fn matchesPrepared(self: *const @This(), binding: Binding, checkpoint: CheckpointSlot, identity: ReadIdentity, count: usize) bool {
        const owned = self.prepared_identity orelse return false;
        return self.binding != null and std.meta.eql(self.binding.?, binding) and
            std.meta.eql(self.checkpoint, checkpoint) and self.prepared_count == count and
            owned.canonical == identity.canonical and std.mem.eql(u8, owned.namespace, identity.namespace);
    }

    // Prepared identities prove canonical key ownership. Offset/key copies are
    // unnecessary. Capture is optional after reference resolution and can be
    // dropped to preserve required-read admission.
    fn rememberPrepared(self: *@This(), a: Allocator, binding: Binding, checkpoint: CheckpointSlot, identity: ReadIdentity, count: usize) bool {
        self.deinit(a);
        if (count > 4096) return false;
        const required = std.math.add(usize, count * @sizeOf(f64) + 8, identity.namespace.len) catch return false;
        if (required > 128 * 1024) return false;
        const capacity = std.math.ceilPowerOfTwo(usize, required) catch return false;
        const storage = (self.promotion_allocator orelse a).alloc(u8, capacity) catch return false;
        var arena = std.heap.FixedBufferAllocator.init(storage);
        const alloc = arena.allocator();
        self.decoded = alloc.alloc(f64, count) catch unreachable;
        const namespace = alloc.dupe(u8, identity.namespace) catch unreachable;
        self.storage = storage;
        self.prepared_identity = .{ .canonical = identity.canonical, .namespace = namespace };
        self.prepared_count = count;
        self.compact = true;
        self.binding = binding;
        self.checkpoint = checkpoint;
        return true;
    }

    fn remember(self: *@This(), a: Allocator, binding: Binding, checkpoint: CheckpointSlot, keys: []const []const u8, references: []const u64, order: ?[]const usize, prepared: ?ReadIdentity) !bool {
        if (prepared) |identity| {
            if (self.matchesPrepared(binding, checkpoint, identity, keys.len)) return true;
            return self.rememberPrepared(a, binding, checkpoint, identity, keys.len);
        } else if (self.matches(binding, checkpoint, keys)) return true;
        self.binding = null;
        if (keys.len > 4096) {
            self.deinit(a);
            return false;
        }
        var required = std.math.mul(usize, keys.len, @sizeOf([]const u8) + @sizeOf(u64) + @sizeOf(usize)) catch return false;
        required = std.math.add(usize, required, 32) catch return false;
        for (keys) |key| required = std.math.add(usize, required, key.len) catch return false;
        if (required > 128 * 1024) {
            self.deinit(a);
            return false;
        }
        // Decoded values share the existing cap. Large requests retain the
        // offset-only path rather than increasing the cache memory ceiling.
        const decoded_bytes = keys.len * @sizeOf(f64);
        const retain_decoded = decoded_bytes <= 128 * 1024 - required;
        if (retain_decoded) required += decoded_bytes;
        const capacity = std.math.ceilPowerOfTwo(usize, required) catch return false;
        if (self.storage == null or self.storage.?.len < capacity) {
            self.deinit(a);
            self.storage = (self.promotion_allocator orelse a).alloc(u8, capacity) catch return false;
        }
        var arena = std.heap.FixedBufferAllocator.init(self.storage.?);
        const alloc = arena.allocator();
        const owned = try alloc.alloc([]const u8, keys.len);
        self.references = try alloc.alloc(u64, keys.len);
        const positions = try alloc.alloc(usize, keys.len);
        self.decoded = if (retain_decoded) try alloc.alloc(f64, keys.len) else &.{};
        self.decoded_ready = false;
        for (owned, keys) |*copy, key| copy.* = try alloc.dupe(u8, key);
        self.keys = owned;
        self.prepared_identity = null;
        self.prepared_count = 0;
        self.compact = false;
        @memcpy(self.references, references);
        self.order = if (order != null) positions else null;
        if (order) |indices| @memcpy(positions, indices);
        self.checkpoint = checkpoint;
        self.binding = binding;
        return true;
    }
};

/// Scope-local working storage. No page views survive a call; bounded buffers
/// and stable index frames are retained for the next batch. Never share a state
/// between concurrent reads. Detach before releasing the owning transaction
/// or file; allocators for retained storage must outlive the state.
pub const DocumentBatchReadState = struct {
    binding: ?ResolvedScoreBatch.Binding = null,
    resolved: ?*ResolvedScoreBatch = null,
    allocator: ?Allocator = null,
    file: ?*NativeFile = null,
    path_allocator: ?Allocator = null,
    path: BatchIndexReadPath = .{},
    reader: RecordPageReader = .{},
    window: RecordReadWindow = .{},

    pub fn deinit(self: *@This()) void {
        if (self.allocator) |a| {
            if (self.resolved) |resolved| resolved.deinit(a);
            if (self.path_allocator) |pa| self.path.deinit(pa);
            self.reader.deinit(a);
            self.window.deinit(a);
        }
        self.* = .{};
    }

    fn prepare(self: *@This(), file: *NativeFile) void {
        const path_override = self.path.allocator;
        const path_allocator = path_override orelse file.allocator;
        const allocator_changed = if (self.path_allocator) |old| old.ptr != path_allocator.ptr or old.vtable != path_allocator.vtable else false;
        if ((self.file != null and self.file != file) or allocator_changed) {
            const allocator = self.allocator;
            const binding = self.binding;
            const resolved = self.resolved;
            self.deinit();
            self.resolved = resolved;
            self.binding = binding;
            self.allocator = allocator;
            self.path.allocator = path_override;
        }
        self.file = file;
        self.path_allocator = path_allocator;
        if (self.allocator == null) self.allocator = file.allocator;
    }

    pub fn detach(self: *@This()) void {
        self.reset();
        self.file = null;
        self.binding = null;
        self.window.file = null;
    }

    pub fn reset(self: *@This()) void {
        const a = self.allocator orelse return;
        // Release shared page pins before returning, including on errors.
        if (self.reader.lease) |lease| self.reader.lease_file.?.page_cache.releaseRaw(self.reader.lease_file.?.allocator, lease);
        self.reader.lease = null;
        self.reader.lease_file = null;
        self.reader.payload = &.{};
        self.reader.page_id = 0;
        self.reader.offsets.clearRetainingCapacity();
        self.reader.record_position = 0;
        self.window.count = 0;
        self.window.record_offset_count = 0;
        self.window.growth_failed = false;
        var retained: usize = self.path.frames.capacity * @sizeOf(*BatchIndexReadFrame);
        for (self.path.frames.items) |frame| {
            frame.releaseView();
            frame.overflow_reference = 0;
            frame.overflow_key = &.{};
            retained += @sizeOf(BatchIndexReadFrame) + frame.offsets.capacity * @sizeOf(u16);
            if (frame.raw) |raw| retained += raw.len;
            if (frame.overflow) |raw| retained += raw.len;
        }
        if (self.window.bytes) |bytes| retained += bytes.len;
        if (self.reader.raw) |raw| retained += raw.len;
        retained += self.reader.offsets.capacity * @sizeOf(u16);
        if (self.resolved) |resolved| if (resolved.storage) |bytes| {
            retained += bytes.len;
        };
        if (retained > 256 * 1024) {
            if (self.resolved) |resolved| resolved.deinit(a);
            const path_allocator = self.path.allocator;
            self.path.deinit(self.path_allocator.?);
            self.path = .{ .allocator = path_allocator };
            self.reader.deinit(a);
            self.window.deinit(a);
        }
    }
};

/// Count only consecutive physical pages proven by sorted record references.
/// Repeated records in one bundle do not consume another window slot.
fn recordRunAhead(references: []const u64, order: ?[]const usize, start: usize) usize {
    const first = physicalPage(references[if (order) |indices| indices[start] else start]);
    var last = first;
    var count: usize = 1;
    const len = if (order) |indices| indices.len else references.len;
    var i = start + 1;
    while (i < len and count < 16) : (i += 1) {
        const page = physicalPage(references[if (order) |indices| indices[i] else i]);
        if (page == last) continue;
        if (page <= last or page - last != 1) break;
        last = page;
        count += 1;
    }
    return count;
}

/// Ordered live catalog keys at a pinned checkpoint. The prefix is borrowed
/// for the cursor lifetime. Callers keep the checkpoint pinned and fence
/// generation replacement (vacuum) while using this cursor; ordinary copy-on-write
/// commits may continue concurrently.
pub const CatalogCursor = struct {
    records: RecordPageReader = .{},
    index: CheckpointedTree,
    prefix: []const u8,
    started: bool = false,
    done: bool = false,
    immediate_children_only: bool = false,
    start_after: ?[]const u8 = null,
    /// §9.3a revised: the redo-log logical_overlay root this scan merges
    /// in, so an uncheckpointed put/delete is visible to -- and a
    /// deleted-in-the-overlay key is never surfaced by -- every catalog
    /// scan, not only point lookups. `null` for a cursor over a root the
    /// overlay never covers (there is none today; kept optional so a
    /// future caller over a root outside TransactionWrites.Root's three
    /// has a documented, explicit opt-out rather than a silent mismatch).
    overlay_root: ?TransactionWrites.Root = null,
    overlay: NativeFile.OverlayScanState = .{ .allocator = undefined },
    overlay_started: bool = false,
    /// The tree's own already-fetched candidate, held here whenever the
    /// overlay's smaller key wins a comparison without a tie: the
    /// underlying `index` cursor's position has already advanced past it,
    /// so losing track of it here would silently skip it forever, not
    /// just defer it. Checked before ever asking `index` for a fresh one.
    pending_tree: ?DocumentIndexEntry = null,

    pub fn deinit(self: *CatalogCursor) void {
        if (self.pending_tree) |*p| p.deinit(self.index.file.allocator);
        self.overlay.deinit();
        self.records.deinit(self.index.file.allocator);
        self.index.deinit();
        self.* = undefined;
    }

    pub fn nextRecordAlloc(self: *CatalogCursor, allocator: Allocator) !?OwnedCatalogRecord {
        const file = self.index.file;
        const key = (try self.next()) orelse return null;
        defer file.allocator.free(key.key);
        const value = if (key.page_id == 0) blk: {
            // `next()` only ever returns a `page_id == 0` key once its own
            // resolve of this exact key, at this exact checkpoint,
            // already succeeded (§9.7c: a phantom resolve there is
            // treated as absent and never surfaced as a key at all) --
            // this second resolve, moments later with nothing able to
            // have changed in between, is expected to agree. A `null`
            // here would mean that invariant broke, not a legitimately
            // absent key, so this stays a hard error rather than quietly
            // skipping (which `nextRecordAlloc`'s own one-key-at-a-time
            // contract has no loop to do safely).
            const entry = (try file.redoOverlayEntry(self.overlay_root.?, self.index.checkpoint, key.key)) orelse return error.InvalidNativeRedoRecord;
            defer file.allocator.free(entry.value);
            break :blk try file.catalogEntryValueAtCheckpointAlloc(allocator, entry, self.index.checkpoint);
        } else blk: {
            const entry = try decodeCatalogEntry(try self.records.read(file, file.allocator, self.index.checkpoint, key.page_id, .catalog));
            break :blk try file.catalogEntryValueAtCheckpointAlloc(allocator, entry, self.index.checkpoint);
        };
        errdefer allocator.free(value);
        return .{ .key = try allocator.dupe(u8, key.key), .value = value };
    }

    /// The caller owns the returned key, allocated with the native file
    /// allocator. `page_id == 0` means the key's live value is in the
    /// redo-log overlay, not on any page yet -- see `overlay_root`.
    pub fn next(self: *CatalogCursor) !?OwnedCatalogKey {
        if (self.done) return null;
        const file = self.index.file;
        if (!self.overlay_started) {
            self.overlay_started = true;
            if (self.start_after) |key| while (try self.overlay.peek()) |k| {
                if (std.mem.order(u8, k, key) != .gt) try self.overlay.consumeIfEqual(k) else break;
            };
        }
        while (true) {
            const candidate = self.pending_tree orelse blk: {
                self.pending_tree = null;
                const fetched = if (self.started) try self.index.next() else if (self.start_after) |key| try self.index.seekAtOrAfter(key, true) else try self.index.seekAtOrAfter(self.prefix, false);
                self.started = true;
                break :blk fetched;
            };
            self.pending_tree = null;
            // Merge-join: the smallest of the tree's current candidate key
            // and the overlay's smallest remaining key wins. A tie means
            // the overlay supersedes the tree's own (now-stale) entry for
            // that exact key -- consume both, keep only the overlay's.
            const overlay_key = try self.overlay.peek();
            const tree_key: ?[]const u8 = if (candidate) |c| c.key else null;
            const take_overlay = overlay_key != null and (tree_key == null or std.mem.order(u8, overlay_key.?, tree_key.?) != .gt);
            if (take_overlay) {
                const key = overlay_key.?;
                if (!std.mem.startsWith(u8, key, self.prefix)) {
                    // Past the prefix range entirely (overlay keys are
                    // sorted, so nothing later in it can match either).
                    self.overlay.exhaust();
                    self.pending_tree = candidate;
                    continue;
                }
                if (self.immediate_children_only and std.mem.indexOfScalar(u8, key[self.prefix.len..], '/') != null) {
                    _ = try self.overlay.takeFront();
                    self.pending_tree = candidate;
                    continue;
                }
                // §9.7c (ReadView): resolve before deciding whether to
                // consume `candidate` -- the overlay enumerates every key
                // with *any* version currently in the live map, regardless
                // of this cursor's own pinned checkpoint, so a cursor
                // pinned to an older, already-superseded checkpoint can
                // enumerate a key whose entire chain postdates it (a
                // brand-new key created only after this pin's own
                // snapshot was taken). `resolveAlloc` then correctly
                // returns `null` -- "nothing at or before this
                // checkpoint" -- which must be treated exactly like the
                // real tree never having had this key diverted away from
                // it at this checkpoint (continue to the tree's own
                // candidate, if any, on the next iteration), not as
                // corruption; and if `candidate` happens to tie with this
                // phantom key, it must stay buffered rather than being
                // freed as if the overlay had genuinely superseded it
                // (same bug class as `MergedCursor.advance`'s own fix).
                const entry = try file.redoOverlayEntry(self.overlay_root.?, self.index.checkpoint, key);
                _ = try self.overlay.takeFront();
                if (entry == null) {
                    self.pending_tree = candidate;
                    continue;
                }
                defer file.allocator.free(entry.?.value);
                const tied = tree_key != null and std.mem.eql(u8, tree_key.?, key);
                if (tied) {
                    var owned = candidate.?;
                    owned.deinit(file.allocator);
                } else {
                    self.pending_tree = candidate;
                }
                if (entry.?.is_delete) continue;
                return .{ .key = try file.allocator.dupe(u8, key), .page_id = 0 };
            }
            const owned = candidate orelse break;
            var entry = owned;
            defer entry.deinit(file.allocator);
            if (!std.mem.startsWith(u8, entry.key, self.prefix)) break;
            if (self.immediate_children_only) {
                if (std.mem.indexOfScalar(u8, entry.key[self.prefix.len..], '/')) |slash| {
                    // '/' is not the maximum byte, so incrementing the final
                    // slash is the exact exclusive upper bound of this subtree.
                    // Seek before decoding any descendant catalog records.
                    const bound = try file.allocator.dupe(u8, entry.key[0 .. self.prefix.len + slash + 1]);
                    defer file.allocator.free(bound);
                    bound[bound.len - 1] += 1;
                    self.pending_tree = try self.index.seekAtOrAfter(bound, false);
                    continue;
                }
            }
            const record = try decodeCatalogEntry(try self.records.read(file, file.allocator, self.index.checkpoint, entry.document_page_id, .catalog));
            if (!std.mem.eql(u8, entry.key, record.key)) return error.InvalidDocumentIndex;
            if (record.is_delete) continue;
            const key = entry.key;
            entry.key = &.{};
            return .{ .key = key, .page_id = entry.document_page_id };
        }
        self.done = true;
        return null;
    }
};

fn recordReferenceLessThan(a: u64, b: u64) bool {
    const pa = physicalPage(a);
    const pb = physicalPage(b);
    return pa < pb or (pa == pb and a < b);
}

fn mutationKeysSorted(mutations: anytype) bool {
    if (mutations.len < 2) return true;
    for (mutations[1..], mutations[0 .. mutations.len - 1]) |right, left| {
        if (std.mem.order(u8, left.key, right.key) == .gt) return false;
    }
    return true;
}

/// Transaction-local copy-on-write B+ tree editor. External keys remain
/// references until compared. Sorted batches seal and release completed subtrees
/// while retaining the active frontier and rebalance neighbors; unsorted batches
/// retain visited nodes until finish. All writes remain private until checkpoint
/// publication, preserving old pages and separators for pinned readers.
const IndexEditor = struct {
    const Key = struct {
        bytes: []const u8,
        page: u64 = 0,

        fn slotSize(self: Key) usize {
            return 10 + (if (self.page != 0) @as(usize, 8) else self.bytes.len);
        }
    };
    const Link = struct { page: u64 = 0, node: ?*Node = null };
    const Node = struct {
        kind: DocumentIndexNodeKind,
        arena: ?std.heap.ArenaAllocator = null,
        previous: ?*Node = null,
        next: ?*Node = null,
        sealed_before: usize = 0,
        compact_at: usize = 128 * 1024,
        page: u64 = 0,
        original_page: u64 = 0,
        dirty: bool = true,
        keys: std.ArrayListUnmanaged(Key) = .empty,
        links: std.ArrayListUnmanaged(Link) = .empty,

        fn size(self: *const Node) usize {
            var result: usize = document_index_header_size + @as(usize, if (self.kind == .internal) 8 else 0);
            for (self.keys.items) |key| result += key.slotSize();
            return result;
        }
    };
    const Split = struct { separator: Key, right: Link };
    const Erased = struct { removed: bool, split: ?Split = null };

    file: *NativeFile,
    checkpoint: CheckpointSlot,
    arena: std.heap.ArenaAllocator,
    root: Link,
    streaming_pages: ?*PageAllocator = null,
    accounting_pages: ?*PageAllocator = null,
    original_page_count: u64,
    nodes: ?*Node = null,

    fn init(file: *NativeFile, checkpoint: CheckpointSlot, root: u64) IndexEditor {
        return .{ .file = file, .checkpoint = checkpoint, .arena = .init(file.allocator), .root = .{ .page = root }, .original_page_count = checkpoint.page_count };
    }

    pub fn deinit(self: *IndexEditor) void {
        while (self.nodes) |node| self.destroyNode(node);
        self.arena.deinit();
    }

    // Sorted batches keep only the active frontier and its rebalance neighbors.
    // Unsorted/single-key writes retain the transaction arena fast path.
    fn useSortedBatch(self: *IndexEditor, pages: *PageAllocator, mutations: anytype) void {
        self.accounting_pages = pages;
        if (mutations.len > 1 and mutationKeysSorted(mutations)) self.streaming_pages = pages;
    }

    fn nodeAllocator(self: *IndexEditor, node: *Node) Allocator {
        return if (node.arena) |*arena| arena.allocator() else self.arena.allocator();
    }

    fn retainKey(self: *IndexEditor, node: *Node, key: Key) !Key {
        return .{ .bytes = if (self.streaming_pages != null) try self.nodeAllocator(node).dupe(u8, key.bytes) else key.bytes, .page = key.page };
    }

    fn newNode(self: *IndexEditor, kind: DocumentIndexNodeKind) !*Node {
        const node = try (if (self.streaming_pages != null) self.file.allocator else self.arena.allocator()).create(Node);
        node.* = .{ .kind = kind };
        if (self.streaming_pages != null) {
            node.arena = .init(self.file.allocator);
            node.next = self.nodes;
            if (self.nodes) |head| head.previous = node;
            self.nodes = node;
        }
        return node;
    }

    fn destroyNode(self: *IndexEditor, node: *Node) void {
        if (node.arena) |*arena| {
            if (node.previous) |previous| previous.next = node.next else self.nodes = node.next;
            if (node.next) |next| next.previous = node.previous;
            arena.deinit();
            self.file.allocator.destroy(node);
        }
    }

    fn releaseSubtree(self: *IndexEditor, node: *Node) void {
        if (node.kind == .internal) for (node.links.items) |link| {
            if (link.node) |child| self.releaseSubtree(child);
        };
        self.destroyNode(node);
    }

    // Rebalancing may revisit a sealed private page. Make queued records/pages
    // readable only then; flushing at every frontier step would defeat packing.
    fn prepareRead(self: *IndexEditor, reference: u64) !void {
        const pages = self.streaming_pages orelse return;
        const page = physicalPage(reference);
        const reused = pages.wasReused(page);
        if (page >= self.original_page_count or reused) {
            try pages.flush();
            self.checkpoint.page_count = pages.next_page_id;
        }
    }

    // A repeatedly merged node must not accumulate dead arena allocations for
    // the entire batch. Repack geometrically, preserving child ownership.
    fn compactNode(self: *IndexEditor, node: *Node) !void {
        const arena = if (node.arena) |*value| value else return;
        const capacity = arena.queryCapacity();
        if (capacity < node.compact_at) return;
        var live = node.keys.items.len * @sizeOf(Key) + node.links.items.len * @sizeOf(Link);
        for (node.keys.items) |key| live += key.bytes.len;
        if (capacity < live * 4) {
            node.compact_at = capacity * 2;
            return;
        }
        var fresh: Node = .{ .kind = node.kind, .arena = .init(self.file.allocator) };
        errdefer fresh.arena.?.deinit();
        const alloc = fresh.arena.?.allocator();
        try fresh.keys.ensureTotalCapacity(alloc, node.keys.items.len);
        for (node.keys.items) |key| fresh.keys.appendAssumeCapacity(.{ .bytes = try alloc.dupe(u8, key.bytes), .page = key.page });
        try fresh.links.appendSlice(alloc, node.links.items);
        arena.deinit();
        node.arena = fresh.arena;
        node.keys = fresh.keys;
        node.links = fresh.links;
        node.compact_at = @max(128 * 1024, node.arena.?.queryCapacity() * 2);
    }

    fn advance(self: *IndexEditor, key: []const u8) !void {
        if (self.streaming_pages == null or self.root.node == null) return;
        try self.sealBefore(self.root.node.?, key, 0);
    }

    fn sealBefore(self: *IndexEditor, node: *Node, key: []const u8, depth: usize) anyerror!void {
        if (depth > 64) return error.InvalidDocumentIndex;
        try self.compactNode(node);
        if (node.kind == .leaf) return;
        const index = try self.bound(node, key, true);
        const stop = index -| 1; // Retain the immediate left sibling for deletion.
        while (node.sealed_before < stop) : (node.sealed_before += 1) {
            const link = &node.links.items[node.sealed_before];
            if (link.node) |child| {
                link.page = try self.flush(link, self.streaming_pages.?, depth + 1);
                self.releaseSubtree(child);
                link.node = null;
            }
        }
        if (node.links.items[index].node) |child| try self.sealBefore(child, key, depth + 1);
    }

    fn load(self: *IndexEditor, link: *Link) !*Node {
        if (link.node) |node| return node;
        try self.prepareRead(link.page);
        const node = try self.newNode(.leaf);
        const alloc = self.nodeAllocator(node);
        // Decoded buffers belong to the editor arena; transfer key slices
        // directly instead of allocating another copy of every inline key.
        const decoded = blk: {
            // Fast path: this page's bytes are already resident (this writer
            // read or wrote them in an earlier commit on this same
            // `NativeFile` and nothing since has reused/rewritten/rolled
            // back that page -- `page_cache`'s existing eviction already
            // guarantees that: `PageAllocator.allocate`'s reuse path and
            // `evictCacheForPagesReusedSince`'s rollback path both call
            // `page_cache.remove`/`removeLinks` the moment a page's content
            // actually changes, so a surviving cache entry here is
            // guaranteed current). `acquirePayload` validates the CRC once
            // on promotion into a `RawView` and skips it on every
            // subsequent acquire of the same still-resident view -- the
            // same cache-hit-skips-CRC property "lite warm value ranges
            // borrow pages without copies or allocations" already proves
            // for the value/record path; this reuses that exact mechanism
            // instead of inventing a parallel one. A `null` return (cold
            // cache, a concurrent `IndexView` promoted on the same page, or
            // this writer's own page size mismatch, none of which should
            // happen in practice for a document-index page) falls back to
            // the always-correct disk-read-and-decode path below, which
            // re-seeds the cache for next time via `readPhysicalPageAlloc`.
            if (self.file.page_cache_enabled.load(.monotonic) and self.file.page_cache_bypass.load(.monotonic) == 0) {
                const physical = physicalPage(link.page);
                if (physical != 0 and physical < self.checkpoint.page_count) {
                    if (try self.file.page_cache.acquirePayload(self.file.allocator, physical, @intCast(self.file.header.page_size))) |view| {
                        defer self.file.page_cache.releaseRaw(self.file.allocator, view);
                        if (view.validation.?.kind != .document_index) return error.UnexpectedNativePageKind;
                        const payload = view.bytes[page_header_size..][0..view.validation.?.payload_len];
                        if (builtin.is_test) _ = PageDecodeMetrics.index_editor_cache_hits.fetchAdd(1, .monotonic);
                        break :blk try decodeDocumentIndexNode(alloc, payload);
                    }
                }
            }
            if (builtin.is_test) _ = PageDecodeMetrics.index_editor_cache_misses.fetchAdd(1, .monotonic);
            const payload = try self.file.readPagePayloadByKindAllocForCheckpoint(self.file.allocator, link.page, .document_index, self.checkpoint);
            defer self.file.allocator.free(payload);
            break :blk try decodeDocumentIndexNode(alloc, payload);
        };
        node.kind = decoded.kind;
        node.page = link.page;
        node.original_page = link.page;
        node.dirty = false;
        // Reserve the decoded entries and one insertion without geometric
        // over-allocation in the arena's bounded single-key edit scratch.
        try node.keys.ensureTotalCapacityPrecise(alloc, decoded.keys.len + 1);
        try node.links.ensureTotalCapacityPrecise(alloc, decoded.pointers.len + 1);
        for (decoded.keys, decoded.key_pages.?) |key, page| {
            node.keys.appendAssumeCapacity(.{ .bytes = key, .page = page });
        }
        for (decoded.pointers) |page| node.links.appendAssumeCapacity(.{ .page = page });
        link.node = node;
        return node;
    }

    fn resolve(self: *IndexEditor, node: *Node, key: *Key) ![]const u8 {
        if (key.page == 0 or key.bytes.len != 0) return key.bytes;
        try self.prepareRead(key.page);
        const raw = try self.file.readPageAllocForCheckpoint(self.file.allocator, key.page, self.checkpoint);
        defer self.file.allocator.free(raw);
        const bytes = switch (raw[4]) {
            @backingInt(PageKind.catalog) => (try decodeCatalogEntry(try decodePagePayload(raw, .catalog))).key,
            @backingInt(PageKind.document) => (try decodeDocumentEntry(try decodePagePayload(raw, .document))).key,
            @backingInt(PageKind.key) => try NativeFile.decodeKey(try decodePagePayload(raw, .key)),
            else => return error.InvalidDocumentIndex,
        };
        if (bytes.len <= index_inline_key_limit) return error.InvalidDocumentIndex;
        key.bytes = try self.nodeAllocator(node).dupe(u8, bytes);
        return key.bytes;
    }

    fn bound(self: *IndexEditor, node: *Node, key: []const u8, upper: bool) !usize {
        var low: usize = 0;
        var high = node.keys.items.len;
        while (low < high) {
            const mid = low + (high - low) / 2;
            const order = std.mem.order(u8, try self.resolve(node, &node.keys.items[mid]), key);
            if (order == .lt or (upper and order == .eq)) low = mid + 1 else high = mid;
        }
        return low;
    }

    fn put(self: *IndexEditor, key: []const u8, page: u64) !void {
        try self.advance(key);
        if (self.root.page == 0 and self.root.node == null) self.root.node = try self.newNode(.leaf);
        if (try self.insert(try self.load(&self.root), key, page, 0)) |split| {
            const root = try self.newNode(.internal);
            try root.keys.append(self.nodeAllocator(root), try self.retainKey(root, split.separator));
            try root.links.appendSlice(self.nodeAllocator(root), &.{ self.root, split.right });
            self.root = .{ .node = root };
        }
    }

    fn insert(self: *IndexEditor, node: *Node, key: []const u8, page: u64, depth: usize) anyerror!?Split {
        if (depth > 64) return error.InvalidDocumentIndex;
        const alloc = self.nodeAllocator(node);
        const index = try self.bound(node, key, node.kind == .internal);
        if (node.kind == .leaf) {
            if (builtin.is_test) DocumentIndexKeyLog.record("insert", node.original_page, key);
            const replacement = index < node.keys.items.len and std.mem.eql(u8, try self.resolve(node, &node.keys.items[index]), key);
            if (replacement) {
                if (self.accounting_pages) |pages| if (node.links.items[index].page != page) try pages.retire(node.links.items[index].page, .record);
                if (!self.file.header.indexed_reclamation) node.keys.items[index].page = if (key.len > index_inline_key_limit) page else 0;
                node.links.items[index] = .{ .page = page };
            } else {
                const owned = Key{ .bytes = try alloc.dupe(u8, key), .page = if (key.len > index_inline_key_limit) page else 0 };
                try node.keys.insert(alloc, index, owned);
                try node.links.insert(alloc, index, .{ .page = page });
            }
        } else {
            const child = try self.load(&node.links.items[index]);
            if (try self.insert(child, key, page, depth + 1)) |split| {
                try node.keys.insert(alloc, index, try self.retainKey(node, split.separator));
                node.sealed_before = 0;
                try node.links.insert(alloc, index + 1, split.right);
            }
        }
        node.dirty = true;
        if (node.size() <= self.file.maxPagePayloadBytes()) return null;
        return try self.splitNode(node);
    }

    /// Choose a byte-balanced split in linear time without fetching key bytes.
    fn splitNode(self: *IndexEditor, node: *Node) !Split {
        const capacity = self.file.maxPagePayloadBytes();
        const header: usize = document_index_header_size + @as(usize, if (node.kind == .internal) 8 else 0);
        const total = node.size() - header;
        var prefix: usize = 0;
        var best: ?usize = null;
        var imbalance: usize = std.math.maxInt(usize);
        for (node.keys.items, 0..) |key, i| {
            const left = header + prefix;
            const right = header + total - prefix - (if (node.kind == .internal) key.slotSize() else 0);
            if ((node.kind == .internal or i > 0) and left <= capacity and right <= capacity) {
                const delta = if (left > right) left - right else right - left;
                if (delta < imbalance) {
                    best = i;
                    imbalance = delta;
                }
            }
            prefix += key.slotSize();
        }
        const at = best orelse return error.DocumentIndexNodeTooLarge;
        const right = try self.newNode(node.kind);
        const separator = node.keys.items[at];
        const key_start = at + @as(usize, if (node.kind == .internal) 1 else 0);
        const link_start = key_start;
        try right.keys.ensureTotalCapacity(self.nodeAllocator(right), node.keys.items.len - key_start);
        for (node.keys.items[key_start..]) |key| right.keys.appendAssumeCapacity(try self.retainKey(right, key));
        try right.links.appendSlice(self.nodeAllocator(right), node.links.items[link_start..]);
        node.sealed_before = 0;
        node.keys.items.len = at;
        node.links.items.len = at + @as(usize, if (node.kind == .internal) 1 else 0);
        node.dirty = true;
        return .{ .separator = separator, .right = .{ .node = right } };
    }

    fn remove(self: *IndexEditor, key: []const u8) !void {
        try self.advance(key);
        if (self.root.page == 0 and self.root.node == null) return;
        const root = try self.load(&self.root);
        const result = try self.erase(root, key, 0);
        if (!result.removed) return;
        if (result.split) |split| {
            const parent = try self.newNode(.internal);
            try parent.keys.append(self.nodeAllocator(parent), try self.retainKey(parent, split.separator));
            try parent.links.appendSlice(self.nodeAllocator(parent), &.{ self.root, split.right });
            self.root = .{ .node = parent };
        }
        if (root.links.items.len == 0) {
            self.root = .{};
            try self.retireNode(root);
            self.destroyNode(root);
            return;
        }
        var depth: usize = 0;
        while (true) : (depth += 1) {
            if (depth > 64) return error.InvalidDocumentIndex;
            const current = try self.load(&self.root);
            if (current.kind != .internal or current.links.items.len != 1) break;
            self.root = current.links.items[0];
            try self.retireNode(current);
            self.destroyNode(current);
        }
    }

    fn erase(self: *IndexEditor, node: *Node, key: []const u8, depth: usize) anyerror!Erased {
        if (depth > 64) return error.InvalidDocumentIndex;
        const index = try self.bound(node, key, node.kind == .internal);
        if (node.kind == .leaf) {
            if (builtin.is_test) DocumentIndexKeyLog.record("erase", node.original_page, key);
            if (index == node.keys.items.len or !std.mem.eql(u8, try self.resolve(node, &node.keys.items[index]), key)) return .{ .removed = false };
            if (self.accounting_pages) |pages| try pages.retire(node.links.items[index].page, .record);
            _ = node.keys.orderedRemove(index);
            _ = node.links.orderedRemove(index);
        } else {
            const child = try self.load(&node.links.items[index]);
            const result = try self.erase(child, key, depth + 1);
            if (!result.removed) return result;
            if (result.split) |split| {
                try node.keys.insert(self.nodeAllocator(node), index, try self.retainKey(node, split.separator));
                node.sealed_before = 0;
                try node.links.insert(self.nodeAllocator(node), index + 1, split.right);
            } else if (child.links.items.len == 0) {
                _ = node.links.orderedRemove(index);
                node.sealed_before = 0;
                try self.retireNode(child);
                self.destroyNode(child);
                if (node.keys.items.len != 0) _ = node.keys.orderedRemove(if (index == 0) 0 else index - 1);
            } else if (node.links.items.len > 1 and child.size() < self.file.maxPagePayloadBytes() / 2) {
                try self.rebalance(node, if (index == 0) 0 else index - 1);
            }
        }
        node.dirty = true;
        // Replacing a separator during redistribution can grow a parent even
        // during deletion: variable-width inline keys need the same split
        // propagation as insertion.
        return .{ .removed = true, .split = if (node.size() > self.file.maxPagePayloadBytes()) try self.splitNode(node) else null };
    }

    fn rebalance(self: *IndexEditor, parent: *Node, left_index: usize) !void {
        const left = try self.load(&parent.links.items[left_index]);
        const right = try self.load(&parent.links.items[left_index + 1]);
        if (left.kind != right.kind) return error.InvalidDocumentIndex;
        const alloc = self.nodeAllocator(left);
        if (left.kind == .internal) try left.keys.append(alloc, try self.retainKey(left, parent.keys.items[left_index]));
        try left.keys.ensureUnusedCapacity(alloc, right.keys.items.len);
        for (right.keys.items) |key| left.keys.appendAssumeCapacity(try self.retainKey(left, key));
        try left.links.appendSlice(alloc, right.links.items);
        left.dirty = true;
        left.sealed_before = 0;
        parent.sealed_before = 0;
        if (left.size() <= self.file.maxPagePayloadBytes()) {
            _ = parent.keys.orderedRemove(left_index);
            _ = parent.links.orderedRemove(left_index + 1);
        } else {
            const halves = try self.splitNode(left);
            parent.keys.items[left_index] = try self.retainKey(parent, halves.separator);
            parent.links.items[left_index + 1] = halves.right;
        }
        try self.retireNode(right);
        self.destroyNode(right);
    }

    fn retireNode(self: *IndexEditor, node: *Node) !void {
        if (self.accounting_pages) |pages| try pages.retire(node.original_page, .index);
        node.original_page = 0;
    }

    fn finish(self: *IndexEditor, pages: *PageAllocator) !u64 {
        if (self.root.page == 0 and self.root.node == null) return 0;
        return try self.flush(&self.root, pages, 0);
    }

    fn flush(self: *IndexEditor, link: *Link, pages: *PageAllocator, depth: usize) anyerror!u64 {
        if (depth > 64) return error.InvalidDocumentIndex;
        const node = link.node orelse return link.page;
        if (!node.dirty) return node.page;
        const alloc = if (self.streaming_pages != null) self.file.allocator else self.arena.allocator();
        const pointers = try alloc.alloc(u64, node.links.items.len);
        defer alloc.free(pointers);
        for (node.links.items, 0..) |*child, i| pointers[i] = if (node.kind == .leaf) child.page else try self.flush(child, pages, depth + 1);
        const keys = try alloc.alloc([]u8, node.keys.items.len);
        defer alloc.free(keys);
        const key_pages = try alloc.alloc(u64, node.keys.items.len);
        defer alloc.free(key_pages);
        for (node.keys.items, 0..) |key, i| {
            keys[i] = @constCast(key.bytes);
            key_pages[i] = key.page;
        }
        try self.retireNode(node);
        const page = try self.file.writeDocumentIndexNode(pages, .{ .kind = node.kind, .keys = keys, .pointers = pointers, .key_pages = key_pages });
        node.page = page;
        node.original_page = page;
        if (self.file.header.indexed_reclamation) for (node.keys.items, key_pages) |*key, key_page| {
            key.page = key_page;
        };
        node.dirty = false;
        link.page = page;
        return page;
    }
};

/// Scan-based proof that an index names each key's newest history record.
/// Retain record references, not full keys. Hash buckets are only candidates:
/// collisions and older versions are resolved by comparing the complete key.
const HistoryIndexCoverage = struct {
    const Entry = struct { reference: u64, next: ?usize, seen: bool = false };
    buckets: std.AutoHashMapUnmanaged(u64, usize) = .empty,
    entries: std.ArrayListUnmanaged(Entry) = .empty,
    reader: RecordPageReader = .{},
    unresolved: usize = 0,
    // Tests force collisions to exercise the exact-key proof.
    hash_mask: u64 = std.math.maxInt(u64),

    pub fn deinit(self: *HistoryIndexCoverage, allocator: Allocator) void {
        self.buckets.deinit(allocator);
        self.entries.deinit(allocator);
        self.reader.deinit(allocator);
    }

    fn add(self: *HistoryIndexCoverage, allocator: Allocator, hash: u64, reference: u64, seen: bool) !void {
        try self.entries.ensureUnusedCapacity(allocator, 1);
        const bucket = try self.buckets.getOrPut(allocator, hash);
        self.entries.appendAssumeCapacity(.{ .reference = reference, .next = if (bucket.found_existing) bucket.value_ptr.* else null, .seen = seen });
        bucket.value_ptr.* = self.entries.items.len - 1;
    }

    fn initIndex(self: *HistoryIndexCoverage, file: *NativeFile, checkpoint: CheckpointSlot, root: u64, cancel: ?*const maintenance.CancelToken) !void {
        var indexed = checkpoint;
        indexed.document_index_root_page = root;
        var cursor = CheckpointedTree.init(file, indexed);
        defer cursor.deinit();
        var current = try cursor.first();
        while (current) |entry| {
            var owned = entry;
            defer owned.deinit(file.allocator);
            if (cancel) |token| try token.check();
            try self.add(file.allocator, std.hash_map.hashString(entry.key) & self.hash_mask, entry.document_page_id, false);
            self.unresolved += 1;
            current = try cursor.next();
        }
    }

    /// History must be visited newest first. A missing key is legal only when
    /// its newest record is a tombstone. Returns true for the first occurrence.
    fn observe(self: *HistoryIndexCoverage, file: *NativeFile, checkpoint: CheckpointSlot, kind: PageKind, reference: u64, key: []const u8, is_delete: bool) !bool {
        const hash = std.hash_map.hashString(key) & self.hash_mask;
        var candidate = self.buckets.get(hash);
        while (candidate) |index| {
            const entry = &self.entries.items[index];
            if (entry.reference != reference) {
                const payload = try self.reader.read(file, file.allocator, checkpoint, entry.reference, kind);
                const other_key = if (kind == .catalog) (try decodeCatalogEntry(payload)).key else (try decodeDocumentEntry(payload)).key;
                if (!std.mem.eql(u8, key, other_key)) {
                    candidate = entry.next;
                    continue;
                }
            }
            if (entry.seen) return false;
            if (entry.reference != reference) return error.InvalidDocumentIndex;
            entry.seen = true;
            self.unresolved -= 1;
            return true;
        }
        if (!is_delete) return error.InvalidDocumentIndex;
        try self.add(file.allocator, hash, reference, true);
        return true;
    }
};

const CatalogRoot = enum {
    metadata,
    index,
};

pub const CatalogEntry = struct {
    previous_page: u64,
    key: []const u8,
    value: []const u8,
    is_delete: bool = false,
    external_value_root_page: u64 = 0,
    external_value_len: usize = 0,
};

pub const DocumentEntry = struct {
    previous_page: u64,
    previous_namespace_page: u64 = 0,
    key: []const u8,
    value: []const u8 = "",
    is_delete: bool = false,
    external_value_root_page: u64 = 0,
    external_value_len: usize = 0,
    content_digest: ?[32]u8 = null,
};

const ValuePage = struct {
    next_page: u64,
    chunk: []const u8,
};

const EncodedCatalogEntry = struct {
    previous_page: u64,
    key: []const u8,
    value: []const u8 = "",
    is_delete: bool = false,
    external_value_root_page: u64 = 0,
    external_value_len: usize = 0,
};

const FreeMap = struct {
    covered_page_count: u64,
    free_pages: []u64,
};

const PageAllocator = struct {
    file: *NativeFile,
    free_pages: []u64,
    next_free_index: usize = 0,
    next_page_id: u64,
    batch: ?PageWriteBatch = null,
    // §9 (redo + indexed reclamation): true only for
    // `pageAllocatorForDivertingCommit`'s own allocator -- the one
    // "page-shaped exception" a diverting transactional commit still
    // makes (external value chains, per `RedoCommitState`'s own doc
    // comment). `PageWriteBatch.flushCount` reads this (propagated
    // through `writePage`'s lazy batch init, and threaded explicitly into
    // every `ExtentAppender`/`CatalogAppendState` batch literal built from
    // this allocator) to decide whether a page it is about to flush
    // should divert into the redo log instead of a real pwrite. A bare
    // commit's own allocator (`pageAllocatorFromFreeMap`) leaves this
    // `false`, so its document/catalog/index/free-map pages always write
    // for real regardless of `self.file.redo` -- matching
    // `putIndexedDocumentBatch`'s and `publishBareCommit`'s own doc
    // comments ("a bare commit never diverts"), which `flushCount`'s
    // earlier, allocator-blind `file.redo != null` check silently broke
    // once `use_redo_log` became the default.
    diverting: bool = false,
    pack_records: bool = false,
    record_buffer: [65536]u8 = undefined,
    record_used: usize = 0,
    record_page: u64 = 0,
    encoded_record: std.ArrayListUnmanaged(u8) = .empty,
    data_lock_file: ?inode_lock.Handle = null,
    coordinated_reader_window: bool = false,
    ledger: ?*allocator_v4.State = null,
    ledger_persisted: bool = false,
    can_reuse: bool = false,
    reuse_retry_enabled: bool = false,
    reuse_retry_pages: u8 = 0,
    append_only: bool = false,
    reused: std.AutoHashMapUnmanaged(u64, void) = .empty,
    pending_values: std.AutoHashMapUnmanaged(u64, u64) = .empty,
    metadata_reserve: std.ArrayList(u64) = .empty,
    metadata_cursor: usize = 0,

    pub fn deinit(self: *PageAllocator) void {
        if (self.data_lock_file) |held| {
            held.release(self.file.runtimeIo());
            self.file.epoch_window = null;
        }
        if (self.coordinated_reader_window) self.file.endReaderWindow();
        self.file.allocator.free(self.free_pages);
        self.encoded_record.deinit(self.file.allocator);
        self.reused.deinit(self.file.allocator);
        self.pending_values.deinit(self.file.allocator);
        self.metadata_reserve.deinit(self.file.allocator);
        if (self.ledger != null and self.file.ledger == self.ledger) {
            const state = self.ledger.?;
            if (!self.ledger_persisted or state.changes.count() != 0 or state.added.items.len != 0 or state.completed.items.len != 0) self.file.invalidateLedger();
        }
    }

    fn retire(self: *PageAllocator, reference: u64, kind: allocator_v4.Kind) !void {
        if (self.ledger) |state| if (reference != 0) try state.retire(.{
            .epoch = self.file.publicationEpoch(),
            .page = reference,
            .kind = kind,
        });
    }
    fn noteValue(self: *PageAllocator, page: u64, length: u64) !void {
        if (self.ledger) |state| if (state.count(page) == 0) {
            // A temporary builder root owns its children until it is linked or
            // retired. This also collects orphaned intermediate append roots.
            try state.retain(page);
            try self.pending_values.put(self.file.allocator, page, length);
        };
    }
    fn retainValue(self: *PageAllocator, page: u64) !void {
        if (self.ledger) |state| {
            try state.retain(page);
            if (self.pending_values.remove(page)) _ = try state.release(page);
        }
    }
    fn takeMetadataPage(context: *anyopaque) !u64 {
        const self: *PageAllocator = @ptrCast(@alignCast(context));
        if (self.metadata_cursor == self.metadata_reserve.items.len) return error.InvalidNativeAllocator;
        const page = self.metadata_reserve.items[self.metadata_cursor];
        self.metadata_cursor += 1;
        return page;
    }
    fn readLedgerPage(context: *anyopaque, a: Allocator, page: u64) ![]u8 {
        const self: *PageAllocator = @ptrCast(@alignCast(context));
        return NativeFile.ledgerRead(self.file, a, page);
    }
    fn writeLedgerPage(context: *anyopaque, page: u64, payload: []const u8) !void {
        const self: *PageAllocator = @ptrCast(@alignCast(context));
        const kind: PageKind = if (std.mem.startsWith(u8, payload, "AFL4ALOC")) .free_map else .allocator;
        try self.file.writePage(page, kind, payload);
    }

    fn writePage(self: *PageAllocator, page: u64, kind: PageKind, payload: []const u8) !void {
        if (self.ledger) |state| switch (kind) {
            .catalog_index, .data => try state.retain(page),
            .catalog, .document => try self.retainRecord(page, kind, payload),
            .document_index => {
                try state.retain(page);
                // Ownership needs encoded references, not copies of every key.
                var frame: IndexReadFrame = .{};
                defer frame.deinit(self.file.allocator);
                try frame.decode(self.file.allocator, payload);
                for (0..frame.entries().len) |i| {
                    const key = frame.keyReference(i);
                    if (key == 0) continue;
                    try state.retain(physicalPage(key));
                }
            },
            else => {},
        };
        if (self.batch == null) self.batch = .{ .file = self.file, .diverting = self.diverting };
        try self.batch.?.appendPage(page, kind, payload);
    }

    fn flush(self: *PageAllocator) !void {
        try self.flushRecords();
        if (self.batch) |*batch| try batch.flush();
    }

    // Encoded payloads fit one native page. Reuse scratch across records and
    // roots; writeRecord copies bytes before the next encoding can overwrite it.
    fn writeDocument(self: *PageAllocator, entry: DocumentEntry) !u64 {
        var encoded_entry = entry;
        if (!entry.is_delete and documentHeaderSize(self.file.header.indexed_reclamation, entry.key) == 60 and
            (entry.external_value_root_page == 0 or entry.value.len != 0))
        {
            var digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(entry.value, &digest, .{});
            encoded_entry.content_digest = digest;
        }
        if (!self.file.header.indexed_reclamation) encoded_entry.content_digest = null;
        self.encoded_record.clearRetainingCapacity();
        try encodeDocumentEntry(self.file.allocator, &self.encoded_record, encoded_entry);
        return self.writeRecord(.document, self.encoded_record.items);
    }

    fn writeCatalog(self: *PageAllocator, entry: CatalogEntry) !u64 {
        self.encoded_record.clearRetainingCapacity();
        try encodeCatalogEntry(self.file.allocator, &self.encoded_record, entry);
        return self.writeRecord(.catalog, self.encoded_record.items);
    }

    fn writeRecord(self: *PageAllocator, kind: PageKind, payload: []const u8) !u64 {
        std.debug.assert(kind == .catalog or kind == .document);
        const capacity = self.file.maxPagePayloadBytes();
        if (!self.pack_records or payload.len + 4 > capacity / 2) {
            const page = try self.allocate();
            try self.writePage(page, kind, payload);
            return page;
        }
        if (self.record_used + 4 + payload.len > capacity) try self.flushRecords();
        if (self.record_used == 0) {
            self.record_page = try self.allocate();
            if (self.record_page > packed_page_mask) return error.RecordTooLarge;
        }
        const offset = self.record_used;
        const out = self.record_buffer[offset..][0 .. 4 + payload.len];
        std.mem.writeInt(u16, out[0..2], @intCast(payload.len), .little);
        out[2] = @backingInt(kind);
        out[3] = 0;
        @memcpy(out[4..], payload);
        self.record_used += out.len;
        const reference = packed_record_flag | (@as(u64, @intCast(offset)) << 47) | self.record_page;
        try self.retainRecord(reference, kind, payload);
        return reference;
    }

    fn retainRecord(self: *PageAllocator, reference: u64, kind: PageKind, payload: []const u8) !void {
        const state = self.ledger orelse return;
        try state.retain(physicalPage(reference));
        const root = switch (kind) {
            .document => (try decodeDocumentEntry(payload)).external_value_root_page,
            .catalog => (try decodeCatalogEntry(payload)).external_value_root_page,
            else => return error.InvalidNativeAllocator,
        };
        if (root != 0) try self.retainValue(root);
    }

    fn flushRecords(self: *PageAllocator) !void {
        if (self.record_used == 0) return;
        try self.writePage(self.record_page, .record_bundle, self.record_buffer[0..self.record_used]);
        self.record_used = 0;
    }

    fn allocate(self: *PageAllocator) !u64 {
        if (self.reuse_retry_enabled and !self.can_reuse) if (self.ledger) |state| if (state.free_pages != 0 and self.file.free_pages_verified) {
            self.reuse_retry_pages += 1;
            if (self.reuse_retry_pages == 64) {
                self.reuse_retry_pages = 0;
                try self.resumeReuseIfUnblocked();
            }
        };
        if (self.ledger) |state| if (self.can_reuse) {
            if (try state.allocate()) |page| {
                try self.reused.put(self.file.allocator, page, {});
                self.file.page_cache.remove(self.file.allocator, page);
                if (self.file.secondary_page_cache) |cache| cache.remove(self.file.allocator, page);
                return page;
            }
        };
        if (!self.append_only and self.next_free_index < self.free_pages.len) {
            const page_id = self.free_pages[self.next_free_index];
            self.next_free_index += 1;
            return page_id;
        }
        return self.allocateFresh();
    }

    /// Like `allocate`, but never satisfies the request from a reused free
    /// page -- always the next monotonically increasing id. The manifest
    /// reservation in `flushTransactionWrites` needs this: a reused page can
    /// still be the live target of a root this very flush never touched
    /// (carried forward unchanged from `self.activeCheckpoint()`, such as
    /// another catalog root's secondary-index pointer written earlier in
    /// the same flush, or in an earlier commit within this since-last-
    /// durable window) because the free-map ledger has no way to know a
    /// commit later turned out to be `.unchanged` and silently discarded its
    /// own reservation/free-map-root allocation without ever adopting it
    /// into `self.header` -- on reload, that page still looks free, and
    /// handing it to a *different* live root, or to this reservation, while
    /// something else still legitimately points at it is a real corruption,
    /// not just a tracking gap. A fresh id is never referenced by anything
    /// yet, so it cannot collide with a live root under any of this.
    // Explicit `anyerror` (not inferred): breaks a mutual inferred-error-set
    // dependency loop with `allocate` (which calls this, and which this
    // calls back on its reuse-retry path) that a reader-side change
    // upstream of both (`resumeReuseIfUnblocked` -> `acquireEpochReuseLock`)
    // can otherwise trip during inference, depending on what that chain's
    // own inferred set happens to look like. `anyerror` already subsumes
    // every error either function can actually produce; no caller here
    // switches exhaustively on either's error set (all plain `try`), so
    // this is a type-level fix only, not a behavior change.
    fn allocateFresh(self: *PageAllocator) anyerror!u64 {
        const page_id = self.next_page_id;
        if (self.file.max_file_bytes) |limit| {
            if (page_id >= limit / self.file.header.page_size) {
                try self.resumeReuseIfUnblocked();
                if (self.can_reuse and self.ledger != null and self.ledger.?.free_pages != 0) return self.allocate();
                return error.LiteStorageBudgetExceeded;
            }
        }
        self.file.allocator_work.appended_pages +|= 1;
        if (self.ledger) |state| if (!self.can_reuse and state.free_pages != 0) {
            self.file.allocator_work.reuse_blocked_append_pages +|= 1;
        };
        self.next_page_id = try std.math.add(u64, self.next_page_id, 1);
        if (self.ledger) |state| try state.reserveTail(page_id);
        return page_id;
    }

    fn resumeReuseIfUnblocked(self: *PageAllocator) !void {
        if (!self.reuse_retry_enabled or self.can_reuse or !self.file.free_pages_verified or self.ledger == null or self.ledger.?.free_pages == 0) return;
        // The initial shared-reader conflict may have disappeared during a
        // large batch. Retry without sleeping or changing its proof/frontier.
        // Unsuspended own readers and every foreign reader still fence reuse.
        if (self.coordinated_reader_window) {
            if (self.file.reader_window_lock == null) {
                const lock = self.file.acquireEpochReuseLock("resumeReuseIfUnblocked(coordinated)") catch |err| switch (err) {
                    error.WouldBlock => return,
                    else => return err,
                };
                if (builtin.mode == .debug) std.debug.assert(self.file.reader_window_lock == null);
                self.file.reader_window_lock = lock;
            }
            self.can_reuse = true;
        } else {
            const lock = self.file.acquireEpochReuseLock("resumeReuseIfUnblocked(uncoordinated)") catch |err| switch (err) {
                error.WouldBlock => return,
                else => return err,
            };
            if (builtin.mode == .debug) std.debug.assert(self.data_lock_file == null);
            self.data_lock_file = lock;
            self.can_reuse = true;
        }
    }

    /// Free pages were validated against both durable checkpoint slots when
    /// this allocator was created. Pages not consumed by the current commit
    /// remain safe to advertise without re-walking every historical chain.
    fn remainingFreePages(self: *const PageAllocator) []const u64 {
        return self.free_pages[self.next_free_index..];
    }

    fn wasReused(self: *const PageAllocator, page: u64) bool {
        if (self.ledger != null) return self.reused.contains(page);
        var low: usize = 0;
        var high = self.next_free_index;
        while (low < high) {
            const mid = low + (high - low) / 2;
            if (self.free_pages[mid] < page) low = mid + 1 else high = mid;
        }
        return low < self.next_free_index and self.free_pages[low] == page;
    }
};

pub const DocumentMutation = struct {
    key: []const u8,
    value: []const u8 = "",
    is_delete: bool = false,
    /// Internal transaction-local reference to a streamed, already written value.
    external_value_root_page: u64 = 0,
    external_value_len: usize = 0,
};

const PendingDocumentIndexEntry = struct {
    key: []const u8,
    document_page_id: u64,
    ordinal: usize,

    fn lessThan(_: void, lhs: PendingDocumentIndexEntry, rhs: PendingDocumentIndexEntry) bool {
        return switch (std.mem.order(u8, lhs.key, rhs.key)) {
            .lt => true,
            .gt => false,
            .eq => lhs.ordinal < rhs.ordinal,
        };
    }
};

pub const CatalogMutation = struct {
    key: []const u8,
    value: []const u8 = "",
    is_delete: bool = false,
    /// Internal transaction-local reference to a streamed, already written value.
    external_value_root_page: u64 = 0,
    external_value_len: usize = 0,
};

/// Bounded final-key write set shared by all callbacks in a native transaction.
/// Payloads larger than one record are streamed immediately; only their extent
/// references are retained. A spill rebuilds each touched index once, without
/// publishing a checkpoint or ending the transaction.
const TransactionWrites = struct {
    const Root = enum { metadata, index, documents };
    const max_keys = 1024;
    const max_bytes = 1024 * 1024;
    const max_append_files = 4;
    maps: [3]std.StringHashMapUnmanaged(CatalogMutation) = .{ .empty, .empty, .empty },
    bytes: usize = 0,
    count: usize = 0,
    pages: PageAllocator,
    // Each active file retains one page tail, a write batch, and a bounded
    // extent frontier. Limit simultaneous frontiers independently of key/value
    // staging; a fifth file spills the transaction's private state.
    appends: [2]std.StringHashMapUnmanaged(*NativeFile.CatalogAppendState) = .{ .empty, .empty },
    append_count: usize = 0,
    // Undo log for a per-member savepoint within a shared group transaction
    // (WS2). Recorded only while `undo_depth > 0`, i.e. between
    // `beginTransactionSavepoint` and its matching release/rollback, so a
    // single member of a group-commit batch can be unwound without
    // disturbing any other member's already-staged entries. Page allocations
    // and catalog-append state made by a rolled-back member are not
    // reclaimed; they stay allocated-but-unreferenced until the next vacuum.
    undo: std.ArrayListUnmanaged(UndoEntry) = .empty,
    undo_depth: usize = 0,
    // Every key/value `stageMutation` stages (and every undo-log snapshot of
    // one it replaces) dies at the exact same moment: this instance's own
    // `clear`/`deinit`, called once per flush window. Individually
    // `allocator.free`-ing each of them bought nothing but 2-4 extra
    // allocator calls per staged write; one arena reclaims all of them in a
    // single `deinit`. `self.pages`/`self.undo`/`self.maps`/`self.appends`
    // are unrelated containers with their own, unchanged lifecycles.
    value_arena: std.heap.ArenaAllocator,

    const UndoEntry = struct {
        root: usize,
        key: []u8,
        previous: ?CatalogMutation,
    };

    fn clear(self: *TransactionWrites, allocator: Allocator) void {
        for (&self.appends) |*map| {
            var it = map.valueIterator();
            while (it.next()) |state| state.*.destroy();
            map.deinit(allocator);
            map.* = .empty;
        }
        self.append_count = 0;
        self.value_arena.deinit();
        self.undo.clearRetainingCapacity();
        self.undo_depth = 0;
        for (&self.maps) |*map| map.clearRetainingCapacity();
        self.bytes = 0;
        self.count = 0;
    }

    pub fn deinit(self: *TransactionWrites, allocator: Allocator) void {
        self.clear(allocator);
        self.undo.deinit(allocator);
        for (&self.maps) |*map| map.deinit(allocator);
        self.pages.deinit();
        allocator.destroy(self);
    }

    fn entry(mutation: CatalogMutation) CatalogEntry {
        return .{ .previous_page = 0, .key = mutation.key, .value = mutation.value, .is_delete = mutation.is_delete, .external_value_root_page = mutation.external_value_root_page, .external_value_len = mutation.external_value_len };
    }
};

/// A mark taken mid-transaction so one group-commit member's staged writes
/// can be unwound without aborting the members staged before or after it.
/// `checkpoint` is a snapshot of the transaction's private root pointers,
/// restored verbatim on rollback (safe even across a flush, since pages are
/// copy-on-write). `writes_generation`/`undo_mark` additionally cover
/// whatever is still only in the in-memory write set, for a member whose
/// writes never triggered a flush; see `beginTransactionSavepoint`.
/// External page allocations and catalog-append state made since the mark
/// are not reclaimed by a rollback.
pub const TransactionSavepoint = struct {
    checkpoint: CheckpointSlot,
    writes_generation: u64,
    undo_mark: usize,
    /// perf/lwa-txn-overlay: `RedoCommitState.overlay_undo.items.len` at
    /// savepoint time (0 for a non-redo file) -- unlike `undo_mark`
    /// above, this one is *not* gated on `writes_generation`: a private
    /// flush (which replaces `TransactionWrites`, invalidating `undo_mark`'s
    /// own replay) moves staged mutations out of `writes.maps` and into
    /// `shared`/`logical_pending` instead, which this field's own replay
    /// must still be able to undo after a flush, not just before one.
    overlay_undo_mark: usize,
    /// perf/lwa-txn-overlay (unbounded buffering): `RedoCommitState
    /// .logical_pending`/`.pending`'s own lengths at savepoint time (0
    /// for a non-redo file) -- truncated back to on rollback so the
    /// eventual commit's own log record never encodes a mutation this
    /// savepoint discarded.
    logical_pending_mark: usize,
    pending_mark: usize,
    /// perf/lwa-budget-tail (Bug 2): `TransactionWrites.pages.next_page_id`
    /// at savepoint time. A diverting commit's own "page-shaped exception"
    /// (`stageMutation`'s external value chains, written eagerly at stage
    /// time through this same allocator -- `pageAllocatorForDivertingCommit`'s
    /// own doc comment) can advance this past a budget-rejected member's
    /// own failure, and unlike `checkpoint.page_count` (restored above,
    /// verbatim, by every rollback already), nothing previously undid
    /// that advance: the cursor stayed pinned at wherever the failed
    /// member's own allocation left it, permanently stealing that much
    /// budget headroom from every later write in this same since-last-
    /// durable window. Rolling it back here (`rollbackTransactionSavepoint`,
    /// cursor rewind plus a matching cache-eviction-and-truncate, mirroring
    /// `discardTransactionTail`'s own pattern for the same reason) is
    /// only safe for a diverting commit's own allocator
    /// (`PageAllocator.diverting`): no ledger is ever attached to it
    /// (`pageAllocatorForDivertingCommit`'s own doc comment, "never
    /// ledger bookkeeping"), so nothing in its range can already be
    /// `retain()`-ed inside a ledger's in-memory state the way a real,
    /// page-shaped (non-diverting) build's freshly allocated ids might
    /// be -- even one with no ledger attached at all (an
    /// `indexed_reclamation`-disabled file still physically grows through
    /// the same real build path) -- see this struct's own pre-existing
    /// doc comment ("External page allocations ... are not reclaimed by a
    /// rollback"), deliberately left in place for that case.
    pages_next_page_id: u64,
};

pub const OwnedDocument = struct {
    key: []u8,
    value: []u8,
};

/// Optional hooks a caller passes into exactly one
/// `commitTransactionWithDurability` call, to release an outer lock for the
/// actual durability-barrier syscall and re-acquire it immediately after
/// (WS2): everything `syncIfRequired` does before and after this pair --
/// the preceding page/slot writes, and the checkpoint-slot publication that
/// follows once it returns -- still runs under that lock, since those touch
/// state other lock holders read. `context` is opaque here on purpose:
/// NativeFile has no business knowing what kind of lock a caller above it
/// uses. Threaded explicitly as a parameter (never stored on `NativeFile`)
/// so two commits on the same file -- the group leader's, and any other
/// caller's (reclaim, vacuum, `sync()`) that passes `null` -- can never
/// observe or act on each other's hooks.
pub const SyncLockHooks = struct {
    context: *anyopaque,
    release: *const fn (context: *anyopaque) void,
    reacquire: *const fn (context: *anyopaque) void,
};

/// Opaque identities never repeat after recovery-slot rollback. Allocator and
/// reader-lease publications retain them; authored roots receive fresh IDs.
pub const LogicalGenerations = struct {
    primary: [16]u8 = @splat(0),
    metadata: [16]u8 = @splat(0),
    indexes: [16]u8 = @splat(0),
};

pub const CheckpointSlot = struct {
    logical: LogicalGenerations = .{},
    commit_sequence: u64 = 0,
    catalog_root_page: u64 = 0,
    document_root_page: u64 = 0,
    index_catalog_root_page: u64 = 0,
    free_map_root_page: u64 = 0,
    page_count: u64 = reserved_header_pages,
    namespace_directory_root_page: u64 = 0,
    document_index_root_page: u64 = 0,
    /// v8 commit manifest: every page this commit wrote, (page id, CRC at
    /// write time) pairs, stored in one `.commit_manifest` page named here.
    /// Meaningless (and zero) when `presynced` is true.
    manifest_page: u64 = 0,
    manifest_crc: u32 = 0,
    manifest_page_count: u32 = 0,
    /// True for a commit whose data pages were already fsynced before this
    /// slot was written (the historical two-sync order: commits over
    /// `max_single_sync_pages`, and the bootstrap slot written before any
    /// commit exists). Recovery trusts a presynced slot unconditionally,
    /// the same way every slot was trusted before v8. A non-presynced slot
    /// must have its manifest re-verified: a slot can be durable on disk
    /// while a page it names was never actually written (the write and the
    /// slot's own sync are not atomic with each other).
    presynced: bool = true,
    /// perf/lwa-fold-boundary: the real, durable fold boundary this slot's
    /// own roots actually reflect -- the same sequence `RedoCommitState
    /// .checkpoint_sequence` tracks in memory, persisted here so a *cold*
    /// reopen (a fresh process, no in-memory state at all) can tell "every
    /// log record at or below this sequence is already in these real
    /// pages" apart from "`commit_sequence` has simply advanced past it."
    /// Those two used to be the same field (`commit_sequence` itself),
    /// which is exactly the bug class this exists to close: a real publish
    /// that advances `commit_sequence` for bookkeeping reasons (a bare
    /// log-full fallback slot, a ledger-only reclaim commit, a stable
    /// snapshot's copied slot) without ever folding the overlay's still-
    /// pending logical heads into these roots used to leave
    /// `recoverRedoLog` trusting `commit_sequence` as if it had, silently
    /// skipping -- as already-real -- log records that were never folded
    /// (`ee1241f843`/`e85c073f3c`/`2b6ee404e8`, three separate instances
    /// of exactly this). Written by every real (physically-synced)
    /// checkpoint publish, not just a fold: `checkpointRedoLog`'s own
    /// commit and `prepareVacuum`'s compaction (which folds everything by
    /// construction) advance it to their own new `commit_sequence`; every
    /// other real publish reaching `publishCheckpoint`'s own disk-write
    /// tail only ever does so once its own caller has already proven
    /// (`reclaimPagesImpl`'s and the log-full bare-slot fallback's own
    /// "still unfolded" guards, kept for exactly this reason even though
    /// the recovery-side data-loss bug they were first written against is
    /// now closed structurally here) that the shared overlay holds no
    /// unfolded logical work at all -- so stamping that publish's own
    /// `commit_sequence` here is not merely a safe upper bound, it is the
    /// exact value, and leaving a stale, carried-forward one instead would
    /// create a real gap in the log's own sequence numbering (see
    /// `publishCheckpoint`'s own comment at the write site). Zero for a
    /// non-redo-log file (meaningless there) and for a brand-new/bootstrap
    /// checkpoint (nothing to fold yet, correctly).
    redo_folded_through: u64 = 0,
};

/// A compact, log-record-sized encoding of exactly the `CheckpointSlot`
/// fields a redo-log commit needs to carry (docs/design/lite-performance/
/// lite-single-commit-write-path.md §9.3): the manifest/presynced fields
/// are meaningless under redo-log commit (no manifest is ever built -- see
/// `NativeFile.manifest_commits_enabled`) and are not persisted here;
/// `toCheckpointSlot` fills them back in with their "no manifest" values.
/// Every redo-log record's payload starts with exactly one of these,
/// followed by the commit's page entries (`decodeRedoGroupPayload`).
const CompactCheckpoint = struct {
    logical: LogicalGenerations,
    commit_sequence: u64,
    catalog_root_page: u64,
    document_root_page: u64,
    index_catalog_root_page: u64,
    free_map_root_page: u64,
    page_count: u64,
    namespace_directory_root_page: u64,
    document_index_root_page: u64,

    const encoded_size: usize = 48 + 8 * 8;

    fn fromCheckpointSlot(slot: CheckpointSlot) CompactCheckpoint {
        return .{
            .logical = slot.logical,
            .commit_sequence = slot.commit_sequence,
            .catalog_root_page = slot.catalog_root_page,
            .document_root_page = slot.document_root_page,
            .index_catalog_root_page = slot.index_catalog_root_page,
            .free_map_root_page = slot.free_map_root_page,
            .page_count = slot.page_count,
            .namespace_directory_root_page = slot.namespace_directory_root_page,
            .document_index_root_page = slot.document_index_root_page,
        };
    }

    fn toCheckpointSlot(self: CompactCheckpoint) CheckpointSlot {
        return .{
            .logical = self.logical,
            .commit_sequence = self.commit_sequence,
            .catalog_root_page = self.catalog_root_page,
            .document_root_page = self.document_root_page,
            .index_catalog_root_page = self.index_catalog_root_page,
            .free_map_root_page = self.free_map_root_page,
            .page_count = self.page_count,
            .namespace_directory_root_page = self.namespace_directory_root_page,
            .document_index_root_page = self.document_index_root_page,
            .presynced = true,
            .manifest_page = 0,
            .manifest_crc = 0,
            .manifest_page_count = 0,
        };
    }

    fn encode(self: CompactCheckpoint, out: *[encoded_size]u8) void {
        @memcpy(out[0..16], &self.logical.primary);
        @memcpy(out[16..32], &self.logical.metadata);
        @memcpy(out[32..48], &self.logical.indexes);
        std.mem.writeInt(u64, out[48..56], self.commit_sequence, .little);
        std.mem.writeInt(u64, out[56..64], self.catalog_root_page, .little);
        std.mem.writeInt(u64, out[64..72], self.document_root_page, .little);
        std.mem.writeInt(u64, out[72..80], self.index_catalog_root_page, .little);
        std.mem.writeInt(u64, out[80..88], self.free_map_root_page, .little);
        std.mem.writeInt(u64, out[88..96], self.page_count, .little);
        std.mem.writeInt(u64, out[96..104], self.namespace_directory_root_page, .little);
        std.mem.writeInt(u64, out[104..112], self.document_index_root_page, .little);
    }

    fn decode(bytes: *const [encoded_size]u8) CompactCheckpoint {
        return .{
            .logical = .{
                .primary = bytes[0..16].*,
                .metadata = bytes[16..32].*,
                .indexes = bytes[32..48].*,
            },
            .commit_sequence = std.mem.readInt(u64, bytes[48..56], .little),
            .catalog_root_page = std.mem.readInt(u64, bytes[56..64], .little),
            .document_root_page = std.mem.readInt(u64, bytes[64..72], .little),
            .index_catalog_root_page = std.mem.readInt(u64, bytes[72..80], .little),
            .free_map_root_page = std.mem.readInt(u64, bytes[80..88], .little),
            .page_count = std.mem.readInt(u64, bytes[88..96], .little),
            .namespace_directory_root_page = std.mem.readInt(u64, bytes[96..104], .little),
            .document_index_root_page = std.mem.readInt(u64, bytes[104..112], .little),
        };
    }
};

/// In-memory state for a redo-log-format file (`CreateOptions`'s
/// `redo_log_capacity_bytes` opt-in; docs/design/lite-performance/
/// lite-single-commit-write-path.md §9, build steps (c)/(d), revised per
/// review to log logical mutations instead of copy-on-write pages).
///
/// `flushTransactionWrites` hands every root's staged `CatalogMutation`s
/// to `appendLogicalMutation` instead of running `IndexEditor`/
/// `PageAllocator` to build real tree pages: `logical_pending` accumulates
/// this transaction's own mutations, and `logical_overlay` mirrors every
/// mutation not yet applied to the real tree, so no copy-on-write path
/// copy happens per commit at all -- only once per checkpoint, batched
/// across however many commits accumulated (`checkpointRedoLog`).
///
/// `pending`/`overlay` (page-shaped) still exist for the one thing that
/// cannot be expressed as a logical mutation: externally-chained large
/// document/catalog values (`CatalogAppendState`'s own append-only value
/// chains). Those pages are never rewritten once written -- a later
/// mutation of the same key always allocates a fresh chain rather than
/// editing one in place -- so logging them as pages (not logically) costs
/// nothing extra: deferring their physical write to the next checkpoint is
/// exactly one write either way, just later. `PageWriteBatch.flushCount`
/// is still the diversion point for these.
///
/// `checkpointing` is the flag every diversion point in this file checks
/// (alongside `self.redo != null`) to run its real, undiverted behavior
/// instead: true only for the span of `checkpointRedoLog`'s own
/// transaction, whose whole job is to perform the deferred copy-on-write
/// work and publish a real checkpoint.
///
/// One entry in `RedoCommitState.overlay_undo` -- either a logical
/// mutation's `(root, key)` (the value/version itself lives in `shared`'s
/// own chain; only enough is kept here to find and remove it again) or a
/// page-shaped write's `page_id`.
const OverlayUndoEntry = union(enum) {
    logical: struct { root: u8, key: []u8 },
    page: u64,
};

/// perf/lwa-txn-overlay (unbounded buffering): the default
/// `RedoCommitState.large_txn_fallback_bytes` -- see that field's own
/// doc comment and docs/design/lite-performance/
/// lite-single-commit-write-path.md §9 for the sizing rationale.
const default_large_txn_fallback_bytes: u64 = 16 * 1024;

const RedoCommitState = struct {
    writer: redo_log.Writer,
    /// This transaction's accumulated logical mutations, encoded via
    /// `redo_overlay.SharedRedoOverlay.decodeLogicalMutationsPayload`'s own
    /// shape. Cleared after every append (durable or not).
    logical_pending: std.ArrayListUnmanaged(u8) = .empty,
    /// §9.6a: the per-inode overlay (versioned logical mutations, plus
    /// page-shaped external-value-chain writes), shared via
    /// `inode_lock.Entry` by every `NativeFile` on this inode -- the live
    /// writer and every `ReadGeneration` reader alike -- instead of each
    /// building its own independent copy. Always `std.heap.page_allocator`-owned
    /// internally (see that type's own doc comment); never deinited here,
    /// only by the `Entry` itself once every reference to it is gone.
    shared: *redo_overlay.SharedRedoOverlay,
    /// This transaction's accumulated page-shaped writes (external value
    /// chains only -- see this struct's own doc comment), encoded as
    /// `redo_overlay.SharedRedoOverlay.decodeRedoGroupPayload`'s
    /// `[page_id:u64][len:u32][bytes]` shape. Cleared after every append.
    pending: std.ArrayListUnmanaged(u8) = .empty,
    /// Highest `commit_sequence` this process has made durable (appended
    /// *and* synced). May run ahead of the on-disk checkpoint slot's own
    /// `commit_sequence`, which only a real checkpoint advances.
    durable_sequence: u64 = 0,
    /// §9.3b: the on-disk checkpoint sequence this log is currently
    /// relative to -- what a fresh reopen's `redo_log.replay` would use
    /// as `start_after_sequence`. Set from the on-disk checkpoint at
    /// `recoverRedoLog`/`createWithRedoLog` time, advanced only when a
    /// real checkpoint lands (`checkpointRedoLog`), never by an ordinary
    /// redo commit. Published to the shared lock region (alongside
    /// `durable_sequence` and the log's current tail offset) so a
    /// cross-process reader knows whether its own cached baseline is
    /// still current or whether it must rebuild from a new one ("re-open
    /// semantics").
    checkpoint_sequence: u64 = 0,
    /// See this struct's own doc comment.
    checkpointing: bool = false,
    /// Set by `NativeFile.maybeAutoCheckpointRedoLog` when its own
    /// opportunistic checkpoint attempt fails (budget, disk, an
    /// allocator invariant, OOM -- any error); cleared the moment a
    /// checkpoint attempt (opportunistic or not) next succeeds. While
    /// set, `maybeAutoCheckpointRedoLog` keeps retrying on every
    /// subsequent commit regardless of how close to full the log
    /// currently is -- the point of this flag is that a persistent
    /// failure must not quietly wait for the log to refill back past the
    /// 25%-remaining bound before trying again, which could otherwise
    /// let it grow uncheckpointed all the way to `error.LogFull`.
    checkpoint_pending_error: bool = false,
    /// perf/lwa-fold-churn: the cross-process `minimumPinnedSequence()`
    /// that blocked the *last* fold's physical log-space reclaim (the
    /// `pinned_below` branch of `checkpointRedoLogWithDurability`'s own
    /// epilogue), or `null` if the last attempt reclaimed cleanly (or no
    /// fold has run yet). While set, a blocked fold never actually shrinks
    /// `redo.writer.remaining()` -- the writer keeps appending past the
    /// old tail instead of resetting over it -- so under steady load
    /// `maybeAutoCheckpointRedoLog`'s own 25%-remaining trigger stays true
    /// forever and would otherwise re-run the *entire* logical fold (a
    /// real `IndexEditor` pass over every root, `SharedRedoOverlay.reclaim`'s
    /// own full scan, real page writes) on every single commit for no
    /// gain: the physical bytes can only free up once this exact pin
    /// advances. `maybeAutoCheckpointRedoLog` checks the *current*
    /// `minimumPinnedSequence()` cheaply (one shared-memory read, no fold)
    /// before paying for another attempt, and skips unless that pin has
    /// moved past the value recorded here. Never consulted by the hard
    /// `error.LogFull` paths in `commitTransactionWithDurability`/
    /// `publishCheckpoint` (`pendingRecordLen() > redo.writer.remaining()`):
    /// those force an unconditional fold the moment a record genuinely
    /// cannot fit, regardless of this backoff -- this only throttles the
    /// *opportunistic* 25%-remaining attempt, which exists purely to stay
    /// ahead of that hard limit, never to be the thing enforcing it.
    checkpoint_backoff_min_pinned: ?u64 = null,
    /// perf/lwa-txn-overlay (transaction isolation): every `appendVersion`/
    /// `appendPage` call this in-flight transaction has itself made onto
    /// `shared`, in staging order -- the redo-overlay analogue of
    /// `TransactionWrites.undo`. Previously, `appendLogicalMutation`
    /// pushed a mutation's new version onto `shared` the moment a private
    /// batch flushed, with nothing to undo it: an aborted transaction's
    /// writes stayed visible in the shared overlay forever (both to other
    /// readers immediately, and to this same file later, once some
    /// unrelated later commit's sequence number caught up to the one the
    /// abandoned version was tagged with). `abortTransaction` now pops
    /// every entry (removing each from `shared`, restoring its chain to
    /// whatever was current before this transaction touched it);
    /// `rollbackTransactionSavepoint` pops back to a savepoint mark only.
    /// A successful commit simply drops this list without touching
    /// `shared` again -- every version it names is already exactly the
    /// state the transaction means to publish.
    overlay_undo: std.ArrayListUnmanaged(OverlayUndoEntry) = .empty,
    /// perf/lwa-txn-overlay (unbounded buffering): once `logical_pending`
    /// reaches this many bytes, `flushTransactionWrites` stops diverting
    /// *new* private batches into the log/overlay for the remainder of
    /// this transaction, falling back to the ordinary page-shaped commit
    /// path instead (the same per-batch-bounded cost the non-redo path
    /// has always had). Keeps one oversized transaction (`deleteTree`'s
    /// own many-small-key subtree walk, in particular) from buffering
    /// unboundedly no matter how large it grows -- see docs/design/
    /// lite-performance/lite-single-commit-write-path.md §9 for the
    /// sizing rationale. A small transaction never reaches this and
    /// keeps the redo log's full I/O savings.
    large_txn_fallback_bytes: u64 = default_large_txn_fallback_bytes,

    fn deinit(self: *RedoCommitState, allocator: Allocator) void {
        self.logical_pending.deinit(allocator);
        self.pending.deinit(allocator);
        for (self.overlay_undo.items) |entry| switch (entry) {
            .logical => |e| allocator.free(e.key),
            .page => {},
        };
        self.overlay_undo.deinit(allocator);
    }

    /// Undoes every `overlay_undo` entry back to `mark` (an earlier
    /// `overlay_undo.items.len`), in reverse (LIFO) order -- see that
    /// field's own doc comment. Used by both `abortTransaction` (`mark =
    /// 0`) and `rollbackTransactionSavepoint` (`mark = ` the savepoint's
    /// own recorded length).
    fn undoOverlaySince(self: *RedoCommitState, allocator: Allocator, io: std.Io, mark: usize) void {
        while (self.overlay_undo.items.len > mark) {
            const entry = self.overlay_undo.pop().?;
            switch (entry) {
                .logical => |e| {
                    self.shared.removeLastVersion(std.heap.page_allocator, io, e.root, e.key);
                    allocator.free(e.key);
                },
                .page => |page_id| self.shared.discardPage(std.heap.page_allocator, io, page_id),
            }
        }
    }

    /// Drops every `overlay_undo` entry *without* touching `shared` --
    /// called once this transaction's own staged versions/pages have
    /// actually published (durably or as a ride-along), so there is
    /// nothing left to ever undo. Frees each entry's own tracking key;
    /// the version/page itself stays in `shared`, exactly as published.
    /// Must run on every path that successfully publishes this
    /// transaction's content, or a later, unrelated transaction's own
    /// `abortTransaction`/`rollbackTransactionSavepoint` (which replay
    /// `overlay_undo` back to a mark relative to *their own* starting
    /// length) would walk past these already-published entries and
    /// wrongly undo them too.
    fn dropOverlayUndo(self: *RedoCommitState, allocator: Allocator) void {
        for (self.overlay_undo.items) |entry| switch (entry) {
            .logical => |e| allocator.free(e.key),
            .page => {},
        };
        self.overlay_undo.clearRetainingCapacity();
    }

    /// perf/lwa-txn-overlay (unbounded buffering): true once this
    /// transaction's own buffered record has already reached
    /// `large_txn_fallback_bytes` -- see that field's own doc comment.
    /// Deliberately `logical_pending` alone, not `+ pending`: `pending`
    /// (page-shaped external value chains) is written eagerly at stage
    /// time, one document's own value at a time (`pageAllocatorForDivertingCommit`'s
    /// own doc comment -- "one document write is one external value,
    /// written once, with no comparable unbounded private-flush
    /// accumulation to begin with"), so a single large document's own
    /// legitimate external value must never disqualify *that same*
    /// flush's logical diversion the moment it is staged -- it did,
    /// before this exclusion, breaking "lite check tolerates page_count
    /// run ahead of physical size on a still-diverting redo-log file"
    /// and three sibling tests whose 64 KiB document values alone
    /// exceeded the threshold on their very first (and only) write.
    /// `logical_pending` is the buffer that actually grows unboundedly
    /// across *many* private flushes within one long transaction
    /// (`deleteTree`'s own subtree walk, this fallback's own target) --
    /// `pending` growing the same way is a different, not-yet-observed
    /// risk (many large documents in one long transaction), left for a
    /// follow-up with a test that actually exercises it.
    fn overLargeTransactionThreshold(self: *const RedoCommitState) bool {
        return self.logical_pending.items.len >= self.large_txn_fallback_bytes;
    }

    /// Records one logical mutation for the in-flight transaction.
    /// `sequence` is the `commit_sequence` this transaction will publish
    /// as (known deterministically from `beginTransaction` time onward --
    /// see `flushTransactionWrites`'s own call site -- even though the
    /// real checkpoint slot isn't written until later).
    fn appendLogicalMutation(self: *RedoCommitState, allocator: Allocator, io: std.Io, root: u8, m: CatalogMutation, sequence: u64) !void {
        std.debug.assert(root < 3);
        var header: [3]u8 = undefined;
        header[0] = root;
        std.mem.writeInt(u16, header[1..3], @intCast(m.key.len), .little);
        try self.logical_pending.appendSlice(allocator, &header);
        try self.logical_pending.appendSlice(allocator, m.key);
        const has_external = m.external_value_root_page != 0;
        try self.logical_pending.append(allocator, @as(u8, @intFromBool(m.is_delete)) | (@as(u8, @intFromBool(has_external)) << 1));
        var value: []u8 = &.{};
        if (has_external) {
            var ext: [16]u8 = undefined;
            std.mem.writeInt(u64, ext[0..8], m.external_value_root_page, .little);
            std.mem.writeInt(u64, ext[8..16], m.external_value_len, .little);
            try self.logical_pending.appendSlice(allocator, &ext);
        } else {
            var len_buf: [4]u8 = undefined;
            std.mem.writeInt(u32, &len_buf, @intCast(m.value.len), .little);
            try self.logical_pending.appendSlice(allocator, &len_buf);
            try self.logical_pending.appendSlice(allocator, m.value);
            // Owned by `redo_overlay.owned_allocator`, not `allocator`: this
            // value is about to live in the shared overlay, which may
            // outlive this specific NativeFile instance -- see `shared`'s
            // own doc comment.
            value = try redo_overlay.owned_allocator.dupe(u8, m.value);
        }
        errdefer redo_overlay.owned_allocator.free(value);
        // perf/lwa-txn-overlay (transaction isolation): reserve everything
        // fallible for undo-tracking *before* pushing the version into
        // `shared` below. Once that call succeeds, this function must not
        // fail without recording how to undo it -- an untracked version
        // would survive an abort/rollback and leak into view the moment
        // some later, unrelated commit's sequence number catches up to
        // the one it was tagged with (this bug's own original shape).
        const owned_key = try allocator.dupe(u8, m.key);
        errdefer allocator.free(owned_key);
        try self.overlay_undo.ensureUnusedCapacity(allocator, 1);
        try self.shared.appendVersion(std.heap.page_allocator, io, root, m.key, sequence, value, m.is_delete, m.external_value_root_page, m.external_value_len);
        self.overlay_undo.appendAssumeCapacity(.{ .logical = .{ .root = root, .key = owned_key } });
    }

    /// Records one page-shaped write for the in-flight transaction (see
    /// this struct's own doc comment for why only external value chains
    /// use this, never B-tree pages).
    fn appendPending(self: *RedoCommitState, allocator: Allocator, io: std.Io, page_id: u64, bytes: []const u8) !void {
        var header: [12]u8 = undefined;
        std.mem.writeInt(u64, header[0..8], page_id, .little);
        std.mem.writeInt(u32, header[8..12], @intCast(bytes.len), .little);
        try self.pending.appendSlice(allocator, &header);
        try self.pending.appendSlice(allocator, bytes);
        // Also `redo_overlay.owned_allocator`-owned -- see `appendLogicalMutation`.
        const owned = try redo_overlay.owned_allocator.dupe(u8, bytes);
        errdefer redo_overlay.owned_allocator.free(owned);
        // perf/lwa-txn-overlay: same undo-tracking discipline as
        // `appendLogicalMutation` above, reserved before the push.
        try self.overlay_undo.ensureUnusedCapacity(allocator, 1);
        try self.shared.appendPage(std.heap.page_allocator, io, page_id, owned);
        self.overlay_undo.appendAssumeCapacity(.{ .page = page_id });
    }

    /// Appends `logical_pending`/`pending` (prefixed with `compact` and a
    /// length-delimited boundary between the two sections) as one
    /// redo-log record for `commit_sequence` -- called once per
    /// `commitTransactionWithDurability` call that actually changed
    /// anything, whether or not it ends up durable (a ride-along commit
    /// still appends, unsynced, exactly like a ride-along copy-on-write
    /// commit still physically writes its pages today).
    ///
    /// Deliberately does NOT clear `logical_pending`/`pending` or drop
    /// `overlay_undo` itself: a successful `self.writer.append` here only
    /// means the record is staged in the writer's own in-memory buffer,
    /// not that this commit has actually published. The durable caller
    /// (`publishCheckpoint`'s redo branch) still has to `sync()` after
    /// this returns, and that sync can fail independently -- clearing the
    /// pending buffers or dropping the undo log here, before that sync is
    /// known to have succeeded, would discard the only record of what to
    /// undo if it does not (perf/lwa-maint-serialize: a sync failure left
    /// `overlay_undo` already dropped and `shared`'s versions/pages
    /// permanently, invisibly published with no corresponding durable log
    /// record, which a later `checkpointRedoLog` fold would then bake
    /// into the real tree as if the commit had succeeded). Every caller
    /// must itself clear both buffers and call `dropOverlayUndo` once its
    /// own durability barrier (a successful `sync()`, or -- for a
    /// ride-along append, which has no further barrier of its own --
    /// this call returning at all) is confirmed, and must instead call
    /// `undoOverlaySince(allocator, io, 0)` plus clear both buffers on
    /// failure.
    fn appendRecord(self: *RedoCommitState, allocator: Allocator, commit_sequence: u64, compact: CompactCheckpoint) !void {
        var compact_buf: [CompactCheckpoint.encoded_size]u8 = undefined;
        compact.encode(&compact_buf);
        var logical_len_buf: [4]u8 = undefined;
        std.mem.writeInt(u32, &logical_len_buf, @intCast(self.logical_pending.items.len), .little);
        var record = try std.ArrayListUnmanaged(u8).initCapacity(allocator, compact_buf.len + logical_len_buf.len + self.logical_pending.items.len + self.pending.items.len);
        defer record.deinit(allocator);
        record.appendSliceAssumeCapacity(&compact_buf);
        record.appendSliceAssumeCapacity(&logical_len_buf);
        record.appendSliceAssumeCapacity(self.logical_pending.items);
        record.appendSliceAssumeCapacity(self.pending.items);
        try self.writer.append(commit_sequence, record.items);
    }

    /// The exact byte length `appendRecord` would write right now for the
    /// currently staged `logical_pending`/`pending`, including the
    /// redo-log's own record framing (`redo_log.header_len`) -- callers
    /// check this against `self.writer.remaining()` *before* calling
    /// `appendRecord`, so a log that cannot fit this record is caught
    /// before anything is written, never surfacing as a failed, partial
    /// append (`error.LogFull`, which `publishCheckpoint` would otherwise
    /// report as the much less specific `error.OutcomeUnknown`).
    fn pendingRecordLen(self: *const RedoCommitState) u64 {
        return redo_log.header_len + CompactCheckpoint.encoded_size + 4 + self.logical_pending.items.len + self.pending.items.len;
    }
};

pub const LockMode = enum {
    writer,
    reader,
    internal_reader,
};

pub const OpenOptions = struct {
    externally_locked: bool = false,
    /// Internal data-reader coordination. The caller holds the path-writer
    /// lease for every publication; coordinated readers never inspect old
    /// allocator metadata. Integrity/allocator snapshots retain normal locks.
    reader_coordinator: ?*ReaderCoordinator = null,
    /// Owner read-only opens wait for in-place service; primitives default to fail-fast.
    wait_for_reader_lock: bool = false,
    internal_reader: bool = false,
    read_only: bool = false,
    no_sync: bool = false,
    resource_manager: ?*resource_manager_mod.ResourceManager = null,
    /// Only consulted when this open builds its own `std.Io.Threaded`
    /// runtime (i.e. not `openWithIo`): upgrades the default durability
    /// barrier to also flush the drive's own write cache (`F_FULLFSYNC` on
    /// Darwin; no effect on platforms without that distinction).
    full_fsync: bool = false,
    /// Pin the checkpoint this open recovers -- both the overlay mark `M`
    /// (`SharedRedoOverlay.pins`, protecting still-unfolded redo-log
    /// content from a concurrent fold's own reclaim) and the checkpoint
    /// `C` itself (`inode_lock.Entry.reader_pins`, protecting its pages
    /// from reuse) -- before this function returns, released in
    /// `close()`. Only `docstore.Store.openWithOptions` sets this
    /// (whenever `opts.read_only`): a *fresh*, standalone open with no
    /// `Txn`/`ReadView` of its own to pin it, read through immediately
    /// after open returns (`backend.zig`'s `initNativeSingleFile`, a
    /// caller's own first `getCatalogRecordAlloc`, ...) with nothing else
    /// protecting the checkpoint it just recovered from a concurrent
    /// writer's own background fold in between. Deliberately opt-in, not
    /// a blanket rule keyed on `read_only and !internal_reader`: several
    /// internal call sites (`docstore.initializeReadGenerationAssumeLocked`'s
    /// own read-generation open chief among them) open a read-only
    /// `NativeFile` directly, outlive any single read, and already have
    /// their own, separately-scoped pin lifecycle
    /// (`Store.pinInitializedReadGeneration`/`releaseReadGeneration`) tied
    /// to individual `ReadPin`s coming and going -- pinning *this* open
    /// unconditionally and for its own unrelated lifetime would starve
    /// every future fold the moment one such generation existed, since
    /// nothing ever closes it to release the pin (confirmed: broke "lite
    /// redo-log idle-flush timer checkpoints an uncheckpointed overlay
    /// without a foreground checkpoint call" during development).
    pin_read_checkpoint: bool = false,
};

/// Per-owner writer-lease timing, exposed under `background_publications`.
/// Log2 nanosecond buckets give bounded percentile ranges. Callers update it
/// under the in-process path gate.
pub const LeaseTiming = struct {
    /// Successful acquisitions, split by how the lease was obtained.
    acquisitions: u64 = 0,
    uncontended: u64 = 0,
    queued: u64 = 0,
    handoffs: u64 = 0,
    /// Refused at the deadline (including abandoned queue tickets).
    busy: u64 = 0,
    busy_wait_ns: u64 = 0,
    wait_ns: u64 = 0,
    wait_max_ns: u64 = 0,
    wait_log2_ns: [64]u64 = @splat(0),
    holds: u64 = 0,
    hold_ns: u64 = 0,
    hold_max_ns: u64 = 0,
    hold_log2_ns: [64]u64 = @splat(0),

    pub const Kind = enum { uncontended, queued, handoff };

    pub fn recordAcquired(self: *LeaseTiming, kind: Kind, wait_ns: u64) void {
        self.acquisitions +|= 1;
        switch (kind) {
            .uncontended => self.uncontended +|= 1,
            .queued => self.queued +|= 1,
            .handoff => self.handoffs +|= 1,
        }
        self.wait_ns +|= wait_ns;
        self.wait_max_ns = @max(self.wait_max_ns, wait_ns);
        self.wait_log2_ns[std.math.log2_int(u64, @max(1, wait_ns))] +|= 1;
    }

    pub fn recordBusy(self: *LeaseTiming, wait_ns: u64) void {
        self.busy +|= 1;
        self.busy_wait_ns +|= wait_ns;
    }

    pub fn recordHold(self: *LeaseTiming, hold_ns: u64) void {
        self.holds +|= 1;
        self.hold_ns +|= hold_ns;
        self.hold_max_ns = @max(self.hold_max_ns, hold_ns);
        self.hold_log2_ns[std.math.log2_int(u64, @max(1, hold_ns))] +|= 1;
    }
};

pub const PathWriterLock = struct {
    io_impl: std.Io.Threaded,
    borrowed_io: ?std.Io = null,
    /// `null` for a lease whose only safety authority is `region` below
    /// (not yet the case for any constructor -- see `region`'s own doc
    /// comment); every constructor today still takes the real sidecar
    /// `flock`, so this is populated whenever `region` is too.
    file: ?std.Io.File,
    /// Admission owns this scope. Closing/yielding the kernel lease drops all
    /// idle anchors; escaped readers retain independent marker references.
    reader_registration_batch: ?ReaderCoordinator.RegistrationBatch = null,
    /// §8.2's shared mmap lock region, set by whichever of this type's own
    /// six constructors could use it -- `null` for a lease taken through
    /// the single plain-flock fallback (§8.6: the region unusable for this
    /// path, or `lockWriterPath`'s own CLI path, which never attempts the
    /// region at all -- see its own doc comment). Heap-allocated
    /// (`std.heap.page_allocator`, matching `inode_lock.Entry.region`'s own
    /// convention) rather than stored by value, because unlike
    /// `inode_lock.Entry` (always accessed through one `*Entry`, never
    /// copied) a `PathWriterLock` value is copied and moved pervasively by
    /// its own callers (`var lease = held;`, `self.retained = lease.*;`) --
    /// a `Region` copied that way would let two independent values both
    /// believe they own the one mapping/fd and both try to tear it down.
    ///
    /// The region's own `writer_holder` CAS is *not* this lease's safety
    /// authority by itself: the sidecar `flock` (`file` above), taken by
    /// every constructor (region-backed or plain-flock fallback alike), is
    /// what every caller actually excludes against, so a region-backed
    /// lease and a plain-flock fallback lease on the same file still
    /// correctly exclude each other. The region's CAS only decides
    /// *fairness order* among the constructors that use it.
    region: ?*shared_lock_region.Region = null,
    /// Whether `fairWriterLockWithIo` took a real region ticket to get
    /// this lease rather than winning the ticketless fast path -- the
    /// same `.queued` vs `.uncontended` admission-stats distinction
    /// `writer_queue.zig`'s own `queue_turn` (a real turn) versus
    /// `queue_watch` (an idle-queue bypass) used to carry before this
    /// design moved off it. `false` for every other constructor (never
    /// set by them).
    contended: bool = false,
    /// When the kernel lease was first taken; kept across in-process handoffs.
    acquired_ns: i96 = 0,
    /// Where `close` records this holder's hold time. Cleared on handoff
    /// (the giver records its share) so a kept lease never points at an
    /// owner that may since have closed.
    hold_stats: ?*LeaseTiming = null,
    hold_started_ns: i96 = 0,

    /// Starts hold accounting for the current holder.
    pub fn startHold(self: *PathWriterLock, stats: *LeaseTiming) void {
        self.hold_stats = stats;
        self.hold_started_ns = std.Io.Clock.awake.now(self.borrowed_io orelse return).nanoseconds;
    }

    /// Records the current holder's share and detaches its stats.
    pub fn endHold(self: *PathWriterLock) void {
        const stats = self.hold_stats orelse return;
        self.hold_stats = null;
        const io = self.borrowed_io orelse return;
        stats.recordHold(@intCast(@max(0, std.Io.Clock.awake.now(io).nanoseconds - self.hold_started_ns)));
    }

    /// Whether a writer in another process has queued behind this lease.
    /// Unknown (no region -- the single plain-flock fallback, §8.6) answers
    /// true so callers release instead of keeping it.
    pub fn othersWaiting(self: *const PathWriterLock) bool {
        if (self.region) |region| return region.othersWaiting();
        return true;
    }

    /// Like `othersWaiting`, but true only for a waiter in a genuinely
    /// different *process*, or a different in-process `Owner` (a
    /// distinct `Region.open`, so a distinct `own_liveness_slot`) -- see
    /// `Region.othersWaitingAcrossProcesses`. Unlike `othersWaiting`,
    /// this process's own maintenance worker reusing *this exact*
    /// handoff-shared lease/region never counts, since its ticket is
    /// tagged with this same opener's pid and liveness slot both.
    /// Callers that would otherwise treat their own maintenance work as
    /// a hostile waiter -- starving it by never releasing, since it
    /// only ever shows up as "someone is queued" and never actually
    /// goes away on its own -- use this instead. A genuinely separate
    /// `Owner` in this process (its own `Region.open`, its own liveness
    /// slot) still counts as foreign here, exactly as a cross-process
    /// waiter would: it cannot make the same zero-cost same-process
    /// progress a handoff caller can, so it needs the same bounded wait.
    pub fn othersWaitingAcrossProcesses(self: *const PathWriterLock, own_pid: u32) bool {
        if (self.region) |region| return region.othersWaitingAcrossProcesses(own_pid);
        return true;
    }

    pub fn close(self: *PathWriterLock) void {
        if (self.reader_registration_batch) |batch| batch.end();
        const io = self.borrowed_io orelse self.io_impl.io();
        if (self.file) |f| f.close(io);
        // The hold ends when the descriptor (and its flock) is released, so
        // it covers reader-marker cleanup done under the lock, as handoffs do.
        self.endHold();
        if (self.region) |region| {
            // Released only here, held for this lease's whole lifetime.
            region.releaseWriter();
            region.close();
            std.heap.page_allocator.destroy(region);
        }
        if (self.borrowed_io == null) self.io_impl.deinit();
        self.* = undefined;
    }
};

const LockFile = struct {
    file: std.Io.File,
};

