fn liveRecordRefLessThan(_: void, lhs: OwnedLiveRecordRef, rhs: OwnedLiveRecordRef) bool {
    return std.mem.order(u8, lhs.key, rhs.key) == .lt;
}

/// Decoded chain-navigation metadata for a page, cached so reachability
/// walks can traverse chains without re-reading and re-decoding page
/// payloads. Mirrors exactly the fields the walks consume.
const PageLinkInfo = struct {
    kind: PageKind,
    /// catalog/document: previous page in the chain; value: next page.
    link_page: u64 = 0,
    external_value_root_page: u64 = 0,
    external_value_len: usize = 0,
    /// value pages only.
    chunk_len: usize = 0,
    is_delete: bool = false,
    value_len: usize = 0,
    /// catalog pages only; owned by the cache.
    key: []u8 = &.{},
};

/// A copy of one page's link info handed out by the cache. `key` (catalog
/// pages) is owned by the caller.
const PageLinkCopy = struct {
    kind: PageKind,
    link_page: u64,
    external_value_root_page: u64,
    external_value_len: usize,
    chunk_len: usize,
    key: ?[]u8,
};

pub const PageDecodeMetrics = struct {
    var crc_calls: if (builtin.is_test) std.atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {};
    var crc_bytes: if (builtin.is_test) std.atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {};
    var extent_decodes: if (builtin.is_test) std.atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {};
    // Diagnostic-only counters for IndexEditor.load's cache-hit fast path
    // (debugging the item-2 write-amplification fix), not load-bearing.
    var index_editor_cache_hits: if (builtin.is_test) std.atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {};
    var index_editor_cache_misses: if (builtin.is_test) std.atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {};

    pub fn crcSnapshot() struct { calls: u64, bytes: u64 } {
        if (!builtin.is_test) return .{ .calls = 0, .bytes = 0 };
        return .{ .calls = crc_calls.load(.monotonic), .bytes = crc_bytes.load(.monotonic) };
    }
    pub fn resetCrc() void {
        if (!builtin.is_test) return;
        crc_calls.store(0, .monotonic);
        crc_bytes.store(0, .monotonic);
    }
};

/// Diagnostic-only pwrite attribution by `PageKind` (perf/lwa-cpu's
/// pwrite-breakdown attribution task), not load-bearing. Bucketed by kind
/// rather than call site: `PageWriteBatch.flushCount`'s own coalesced
/// writes can mix several pages (and thus several commits' worth of calls)
/// under one `write_amplification_trace` scope by the time the actual
/// syscall happens (ledger pages staged in `persistAllocator` are not
/// flushed until a later, shared `PageAllocator.flush()` call -- scoping
/// around `persistAllocator` alone would not reliably cover its own
/// pwrite), while every page's `PageKind` byte is known exactly at the
/// point of the write regardless of when it was staged. A contiguous run
/// written in one syscall (`flushCount`) is bucketed by its first page's
/// kind; `commit_manifest` and `checkpoint_slot` are always exactly one
/// page per write by construction, so their buckets are already precise.
pub const PageWriteMetrics = struct {
    pub const Bucket = struct {
        calls: if (builtin.is_test) std.atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
        bytes: if (builtin.is_test) std.atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    };
    var buckets: if (builtin.is_test) [14]Bucket else void = if (builtin.is_test) @splat(.{}) else {};

    fn record(kind: PageKind, bytes: u64) void {
        if (!builtin.is_test) return;
        const bucket = &buckets[@backingInt(kind)];
        _ = bucket.calls.fetchAdd(1, .monotonic);
        _ = bucket.bytes.fetchAdd(bytes, .monotonic);
    }

    /// Snapshot a bucket's (calls, bytes) pair for `kind`. Public so an
    /// external harness (perf/lwa-cpu's CPU bench) can read the pwrite
    /// attribution by page kind without reaching into this module's
    /// internals.
    pub fn get(kind: PageKind) struct { calls: u64, bytes: u64 } {
        if (!builtin.is_test) return .{ .calls = 0, .bytes = 0 };
        const bucket = &buckets[@backingInt(kind)];
        return .{ .calls = bucket.calls.load(.monotonic), .bytes = bucket.bytes.load(.monotonic) };
    }

    pub fn reset() void {
        if (!builtin.is_test) return;
        for (&buckets) |*bucket| {
            bucket.calls.store(0, .monotonic);
            bucket.bytes.store(0, .monotonic);
        }
    }
};

/// Diagnostic-only (perf/lwa-cpu, document-index write-count investigation):
/// when armed, logs every key `IndexEditor.insert`/`erase` touches at the
/// leaf level -- the leaf's original (pre-commit) on-disk page id, so
/// multiple keys landing in the *same* leaf are visibly grouped, and the
/// key bytes themselves -- to answer "how many distinct leaves does one
/// commit's document-index writes actually touch, and why". Not armed by
/// default; armed only by the dedicated attribution test in
/// `write_amplification_cpu_bench_test.zig`.
pub const DocumentIndexKeyLog = struct {
    var armed: if (builtin.is_test) std.atomic.Value(bool) else void = if (builtin.is_test) .init(false) else {};

    pub fn arm(on: bool) void {
        if (!builtin.is_test) return;
        armed.store(on, .monotonic);
    }

    fn record(comptime op: []const u8, leaf_original_page: u64, key: []const u8) void {
        if (!builtin.is_test) return;
        if (!armed.load(.monotonic)) return;
        var hex_buf: [256]u8 = undefined;
        var pos: usize = 0;
        for (key) |byte| {
            if (pos + 2 > hex_buf.len) break;
            _ = std.fmt.bufPrint(hex_buf[pos..][0..2], "{x:0>2}", .{byte}) catch break;
            pos += 2;
        }
        std.debug.print("DOCIDX_KEY op={s} leaf_original_page={d} key_len={d} key_hex={s}\n", .{ op, leaf_original_page, key.len, hex_buf[0..pos] });
    }
};

/// In-memory cache of encoded pages, keyed by page id.
///
/// Safe when OS file locks are available because page contents are stable for
/// the lifetime of an open handle: all in-process page writes flow through
/// `writePage` (which updates the cache) or vacuum replacement (which
/// clears it), sidecar writer locks serialize writers, and read-only
/// data-file shared locks block the exclusive data-rewrite lock needed for
/// free-page reuse and vacuum. Filesystems that cannot provide those locks are
/// rejected before a `NativeFile` is returned, so cached pages are never used
/// by an unfenced handle.
const PageCache = struct {
    const default_limit_bytes: usize = 64 * 1024 * 1024;
    const default_link_limit_bytes: usize = 16 * 1024 * 1024;
    const link_entry_overhead: usize = @sizeOf(PageLinkInfo) + @sizeOf(u64);

    // Promotion shares the encoded page with an immutable decoded view. Pins
    // permit overflow-key I/O without holding the cache mutex; eviction drops
    // residency immediately, but charges pinned storage until its last reader
    // releases it. Cursor positions and overflow scratch are never shared.
    const IndexView = struct {
        frame: IndexReadFrame,
        references: usize = 1,

        fn size(self: *const IndexView) usize {
            return @sizeOf(IndexView) + self.frame.raw.?.len + self.frame.offsets.capacity * @sizeOf(u16);
        }
    };
    /// Immutable encoded bytes, owned jointly by residency and active readers.
    /// Retired pinned pages remain charged until the last reader releases them.
    const ExtentEntry = struct { page: u64, end: u64 };
    const RawView = struct {
        bytes: []u8,
        references: std.atomic.Value(usize) = .init(1),
        // Published once under the cache mutex, before a validated borrower
        // can observe it. Raw-only borrowers never inspect these fields.
        validation: ?struct { kind: PageKind, payload_len: usize } = null,
        extent_entries: ?[]ExtentEntry = null,
        record_offsets: ?[]u16 = null,
        extent_height: u8 = 0,
        extent_length: u64 = 0,

        fn size(self: *const RawView) usize {
            return @sizeOf(RawView) + self.bytes.len +
                (if (self.extent_entries) |entries| entries.len * @sizeOf(ExtentEntry) else @as(usize, 0)) +
                (if (self.record_offsets) |offsets| offsets.len * @sizeOf(u16) else @as(usize, 0));
        }
        fn packedRecord(self: *const RawView, reference: u64) !PackedRecord {
            const payload = self.bytes[page_header_size..][0..self.validation.?.payload_len];
            const offsets = self.record_offsets orelse return packedRecordPayload(payload, reference);
            const wanted: u16 = @intCast((reference >> 47) & 0xffff);
            const position = std.sort.lowerBound(u16, offsets, wanted, struct {
                fn compare(lhs: u16, rhs: u16) std.math.Order {
                    return std.math.order(lhs, rhs);
                }
            }.compare);
            if (position == offsets.len or offsets[position] != wanted) return error.InvalidPageId;
            return packedRecordAtOffset(payload, wanted);
        }
    };
    const CachedPage = struct { bytes: []u8, credit: u8, metadata: bool, index: ?*IndexView = null, raw_view: ?*RawView = null };
    mutex: std.atomic.Mutex = .unlocked,
    pages: std.AutoArrayHashMapUnmanaged(u64, CachedPage) = .empty,
    clock_hand: usize = 0,
    links: std.AutoHashMapUnmanaged(u64, PageLinkInfo) = .empty,
    total_bytes: usize = 0,
    test_copied_bytes: if (builtin.is_test) u64 else void = if (builtin.is_test) 0 else {},
    test_raw_release_locks: if (builtin.is_test) u64 else void = if (builtin.is_test) 0 else {},
    link_bytes: usize = 0,
    resource_manager: ?*resource_manager_mod.ResourceManager = null,
    resource_page_accounted_bytes: u64 = 0,
    resource_link_accounted_bytes: u64 = 0,
    /// CLOCK admission starts payloads cold; accesses promote them, while
    /// navigation metadata starts with a second chance. Overflow evicts only
    /// enough bytes for the incoming page, preserving the rest of the cache.
    limit_bytes: usize = default_limit_bytes,
    link_limit_bytes: usize = default_link_limit_bytes,

    fn getCopy(self: *PageCache, allocator: Allocator, page_id: u64) !?[]u8 {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        const cached = self.pages.getPtr(page_id) orelse return null;
        cached.credit = if (cached.metadata) 3 else 2;
        const owned = try allocator.dupe(u8, cached.bytes);
        if (builtin.is_test) self.test_copied_bytes += cached.bytes.len;
        return owned;
    }

    fn copyInto(self: *PageCache, page_id: u64, out: []u8) bool {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        const cached = self.pages.getPtr(page_id) orelse return false;
        if (cached.bytes.len != out.len) return false;
        cached.credit = if (cached.metadata) 3 else 2;
        @memcpy(out, cached.bytes);
        if (builtin.is_test) self.test_copied_bytes += out.len;
        return true;
    }

    fn acquireRaw(self: *PageCache, allocator: Allocator, page_id: u64, size: usize) ?*RawView {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        return self.acquireRawLocked(allocator, page_id, size);
    }

    /// Caller holds the cache mutex; promotion is optional and remains bounded.
    fn acquireRawLocked(self: *PageCache, allocator: Allocator, page_id: u64, size: usize) ?*RawView {
        const before_bytes = self.total_bytes;
        defer if (self.total_bytes != before_bytes) self.refreshPageResourceUsageLocked();
        if (self.clearPagesForHardPressureLocked(allocator)) return null;
        const cached = self.pages.getPtr(page_id) orelse return null;
        if (cached.bytes.len != size or cached.index != null) return null;
        if (cached.raw_view) |view| {
            cached.credit = if (cached.metadata) 3 else 2;
            _ = view.references.fetchAdd(1, .monotonic);
            return view;
        }
        const extra = @sizeOf(RawView);
        if (extra > self.limit_bytes or size > self.limit_bytes - extra) return null;
        const view = allocator.create(RawView) catch return null;
        var promoted = false;
        defer if (!promoted) allocator.destroy(view);
        self.evictPagesToExceptLocked(allocator, self.limit_bytes - extra, page_id);
        if (self.total_bytes > self.limit_bytes - extra) return null;
        const resident = self.pages.getPtr(page_id).?;
        view.* = .{ .bytes = resident.bytes, .references = .init(2) };
        resident.raw_view = view;
        resident.credit = if (resident.metadata) 3 else 2;
        self.total_bytes += extra;
        promoted = true;
        self.refreshPageResourceUsageLocked();
        _ = self.clearPagesForHardPressureLocked(allocator);
        return view;
    }

    fn acquirePayload(self: *PageCache, allocator: Allocator, page_id: u64, size: usize) !?*RawView {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        const before_bytes = self.total_bytes;
        defer if (self.total_bytes != before_bytes) self.refreshPageResourceUsageLocked();
        const view = self.acquireRawLocked(allocator, page_id, size) orelse return null;
        errdefer self.releaseRawLocked(allocator, view);
        if (view.validation != null) return view;
        if (view.bytes.len < page_header_size) return error.TruncatedNativePage;
        const kind = std.enums.fromInt(PageKind, view.bytes[4]) orelse return error.InvalidNativePageKind;
        const payload = try decodePagePayload(view.bytes, kind);
        if (kind == .value_extent) {
            const decoded = try NativeFile.decodeExtentNodeWithLength(payload);
            view.extent_height = decoded.node.height;
            view.extent_length = decoded.length;
            const extra = decoded.node.count * @sizeOf(ExtentEntry);
            // A pressure reclaim may already have retired this owner. Avoid
            // building navigation which could never serve another borrower.
            const resident = if (self.pages.get(page_id)) |page| page.raw_view == view else false;
            if (resident and extra <= self.limit_bytes) {
                self.evictPagesToExceptLocked(allocator, self.limit_bytes - extra, page_id);
                if (self.total_bytes <= self.limit_bytes - extra) {
                    if (allocator.alloc(ExtentEntry, decoded.node.count)) |entries| {
                        var end: u64 = 0;
                        for (entries, decoded.node.children[0..decoded.node.count]) |*entry, child| {
                            end += child.len; // Checked by decodeExtentNodeWithLength.
                            entry.* = .{ .page = child.page, .end = end };
                        }
                        view.extent_entries = entries;
                        self.total_bytes += extra;
                    } else |_| {} // Payload validation still avoids repeated CRC.
                }
            }
        }
        if (kind == .record_bundle) {
            var count: usize = 0;
            var offset: usize = 0;
            while (offset < payload.len) {
                const record = try packedRecordAtOffset(payload, offset);
                offset += 4 + record.bytes.len;
                count += 1;
            }
            const extra = count * @sizeOf(u16);
            const resident = if (self.pages.get(page_id)) |page| page.raw_view == view else false;
            if (resident and extra <= self.limit_bytes) {
                self.evictPagesToExceptLocked(allocator, self.limit_bytes - extra, page_id);
                if (self.total_bytes <= self.limit_bytes - extra) {
                    if (allocator.alloc(u16, count)) |offsets| {
                        offset = 0;
                        for (offsets) |*record_offset| {
                            record_offset.* = @intCast(offset);
                            offset += 4 + (try packedRecordAtOffset(payload, offset)).bytes.len;
                        }
                        view.record_offsets = offsets;
                        self.total_bytes += extra;
                    } else |_| {}
                }
            }
        }
        view.validation = .{ .kind = kind, .payload_len = payload.len };
        self.refreshPageResourceUsageLocked();
        _ = self.clearPagesForHardPressureLocked(allocator);
        return view;
    }

    fn dropRawReference(view: *RawView) bool {
        const previous = view.references.fetchSub(1, .acq_rel);
        std.debug.assert(previous > 0);
        return previous == 1;
    }

    fn releaseRaw(self: *PageCache, allocator: Allocator, view: *RawView) void {
        // Cache residency normally retains a reference. Only final reclamation
        // needs the mutex; no owner fields may be read after a nonfinal drop.
        if (!dropRawReference(view)) return;
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        if (builtin.is_test) self.test_raw_release_locks += 1;
        self.freeRawLocked(allocator, view);
        self.refreshPageResourceUsageLocked();
    }

    fn releaseRawLocked(self: *PageCache, allocator: Allocator, view: *RawView) void {
        if (dropRawReference(view)) self.freeRawLocked(allocator, view);
    }

    fn freeRawLocked(self: *PageCache, allocator: Allocator, view: *RawView) void {
        self.total_bytes -= view.size();
        if (view.extent_entries) |entries| allocator.free(entries);
        if (view.record_offsets) |offsets| allocator.free(offsets);
        allocator.free(view.bytes);
        allocator.destroy(view);
    }

    fn acquireIndex(self: *PageCache, allocator: Allocator, page_id: u64) !?*IndexView {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        const before_bytes = self.total_bytes;
        defer if (self.total_bytes != before_bytes) self.refreshPageResourceUsageLocked();
        if (self.clearPagesForHardPressureLocked(allocator)) return null;
        const cached = self.pages.getPtr(page_id) orelse return null;
        if (cached.index) |view| {
            cached.credit = 3;
            view.references += 1;
            return view;
        }
        if (cached.raw_view != null) return null;
        const payload = try decodePagePayload(cached.bytes, .document_index);
        const view = allocator.create(IndexView) catch return null;
        view.* = .{ .frame = .{} };
        var promoted = false;
        defer if (!promoted) {
            view.frame.deinit(allocator);
            allocator.destroy(view);
        };
        view.frame.decode(allocator, payload) catch |err| switch (err) {
            error.OutOfMemory => return null,
            else => return err,
        };
        const extra = @sizeOf(IndexView) + view.frame.offsets.capacity * @sizeOf(u16);
        if (extra > self.limit_bytes or cached.bytes.len > self.limit_bytes - extra) return null;
        self.evictPagesToExceptLocked(allocator, self.limit_bytes - extra, page_id);
        if (self.total_bytes > self.limit_bytes - extra) return null;
        // Eviction can move the map entry. No I/O or unlock occurs between
        // validation and publication, so this view describes these exact bytes.
        const resident = self.pages.getPtr(page_id).?;
        view.frame.raw = resident.bytes;
        view.references = 2; // cache and caller
        resident.index = view;
        resident.credit = 3;
        self.total_bytes += extra;
        promoted = true;
        self.refreshPageResourceUsageLocked();
        _ = self.clearPagesForHardPressureLocked(allocator);
        return view;
    }

    fn releaseIndex(self: *PageCache, allocator: Allocator, view: *IndexView) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        const before_bytes = self.total_bytes;
        self.releaseIndexLocked(allocator, view);
        if (self.total_bytes != before_bytes) self.refreshPageResourceUsageLocked();
    }

    fn releaseIndexLocked(self: *PageCache, allocator: Allocator, view: *IndexView) void {
        std.debug.assert(view.references > 0);
        view.references -= 1;
        if (view.references != 0) return;
        self.total_bytes -= view.size();
        view.frame.deinit(allocator);
        allocator.destroy(view);
    }

    fn freePageLocked(self: *PageCache, allocator: Allocator, page: CachedPage) void {
        if (page.index) |view| {
            self.releaseIndexLocked(allocator, view);
        } else if (page.raw_view) |view| {
            self.releaseRawLocked(allocator, view);
        } else {
            self.total_bytes -= page.bytes.len;
            allocator.free(page.bytes);
        }
    }

    fn attachResourceManager(self: *PageCache, manager: *resource_manager_mod.ResourceManager) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        self.resource_manager = manager;
        self.refreshPageResourceUsageLocked();
        self.refreshLinkResourceUsageLocked();
    }

    fn put(self: *PageCache, allocator: Allocator, page_id: u64, page: []const u8) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        // Replacement must invalidate the old bytes even if admission fails.
        if (self.pages.fetchSwapRemove(page_id)) |old| {
            self.freePageLocked(allocator, old.value);
        }
        defer self.refreshPageResourceUsageLocked();
        if (self.clearPagesForHardPressureLocked(allocator)) return;
        if (page.len > self.limit_bytes) return;
        self.evictPagesToLocked(allocator, self.limit_bytes - page.len);
        if (self.total_bytes > self.limit_bytes - page.len) return;
        const owned = allocator.dupe(u8, page) catch return;
        const metadata = page.len >= page_header_size and switch (page[4]) {
            @backingInt(PageKind.document_index), @backingInt(PageKind.catalog_index), @backingInt(PageKind.value_extent) => true,
            else => false,
        };
        self.pages.put(allocator, page_id, .{ .bytes = owned, .credit = if (metadata) 2 else 0, .metadata = metadata }) catch {
            allocator.free(owned);
            return;
        };
        self.total_bytes += page.len;
        self.refreshPageResourceUsageLocked();
        _ = self.clearPagesForHardPressureLocked(allocator);
    }

    fn evictPagesToLocked(self: *PageCache, allocator: Allocator, target: usize) void {
        self.evictPagesToExceptLocked(allocator, target, null);
    }

    fn evictPagesToExceptLocked(self: *PageCache, allocator: Allocator, target: usize, protected: ?u64) void {
        while (self.total_bytes > target and self.pages.count() != 0) {
            if (self.clock_hand >= self.pages.count()) self.clock_hand = 0;
            if (protected != null and self.pages.keys()[self.clock_hand] == protected.?) {
                if (self.pages.count() == 1) break;
                self.clock_hand += 1;
                continue;
            }
            const entry = &self.pages.values()[self.clock_hand];
            if (entry.credit != 0) {
                entry.credit -= 1;
                self.clock_hand += 1;
            } else {
                self.freePageLocked(allocator, entry.*);
                self.pages.swapRemoveAt(self.clock_hand);
            }
        }
    }

    fn getLinksCopy(self: *PageCache, allocator: Allocator, page_id: u64) !?PageLinkCopy {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        const cached = self.links.get(page_id) orelse return null;
        return .{
            .kind = cached.kind,
            .link_page = cached.link_page,
            .external_value_root_page = cached.external_value_root_page,
            .external_value_len = cached.external_value_len,
            .chunk_len = cached.chunk_len,
            .key = if (cached.key.len > 0) try allocator.dupe(u8, cached.key) else null,
        };
    }

    fn putLinks(self: *PageCache, allocator: Allocator, page_id: u64, info: PageLinkInfo) void {
        const owned_key = if (info.key.len > 0) allocator.dupe(u8, info.key) catch return else @as([]u8, &.{});
        var owned = info;
        owned.key = owned_key;

        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        if (self.clearLinksForHardPressureLocked(allocator)) {
            if (owned.key.len > 0) allocator.free(owned.key);
            return;
        }
        if (self.links.getEntry(page_id)) |entry| {
            self.link_bytes -= entry.value_ptr.key.len + link_entry_overhead;
            if (entry.value_ptr.key.len > 0) allocator.free(entry.value_ptr.key);
            entry.value_ptr.* = owned;
            self.link_bytes += owned.key.len + link_entry_overhead;
            self.refreshLinkResourceUsageLocked();
            _ = self.clearLinksForHardPressureLocked(allocator);
            return;
        }
        if (self.link_bytes + owned.key.len + link_entry_overhead > self.link_limit_bytes) {
            // At capacity, prefer keeping the resident entries: chain walks
            // revisit the same old pages every commit, so evicting them to
            // admit one new entry would thrash the whole walk.
            if (owned.key.len > 0) allocator.free(owned.key);
            return;
        }
        self.links.put(allocator, page_id, owned) catch {
            if (owned.key.len > 0) allocator.free(owned.key);
            return;
        };
        self.link_bytes += owned.key.len + link_entry_overhead;
        self.refreshLinkResourceUsageLocked();
        _ = self.clearLinksForHardPressureLocked(allocator);
    }

    fn remove(self: *PageCache, allocator: Allocator, page_id: u64) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        self.removeLocked(allocator, page_id);
    }

    fn removeLinks(self: *PageCache, allocator: Allocator, page_id: u64) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        if (self.links.fetchRemove(page_id)) |entry| {
            self.link_bytes -= entry.value.key.len + link_entry_overhead;
            if (entry.value.key.len > 0) allocator.free(entry.value.key);
            self.refreshLinkResourceUsageLocked();
        }
    }

    fn removeLocked(self: *PageCache, allocator: Allocator, page_id: u64) void {
        var removed_page = false;
        var removed_links = false;
        if (self.pages.fetchSwapRemove(page_id)) |entry| {
            self.freePageLocked(allocator, entry.value);
            removed_page = true;
        }
        if (self.links.fetchRemove(page_id)) |entry| {
            self.link_bytes -= entry.value.key.len + link_entry_overhead;
            if (entry.value.key.len > 0) allocator.free(entry.value.key);
            removed_links = true;
        }
        if (removed_page) self.refreshPageResourceUsageLocked();
        if (removed_links) self.refreshLinkResourceUsageLocked();
    }

    /// Rollback makes the append tail reusable. Streamed private-image writes
    /// can bypass this cache, so discard both bytes and links for those IDs.
    /// Preserve cached pages from the restored checkpoint.
    fn discardFrom(self: *PageCache, allocator: Allocator, first_page: u64) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        var i: usize = 0;
        while (i < self.pages.count()) {
            const page = self.pages.keys()[i];
            if (page >= first_page) self.removeLocked(allocator, page) else i += 1;
        }
        // Hash-map removal leaves other entries and the iterator stable.
        var links = self.links.keyIterator();
        while (links.next()) |page| {
            if (page.* >= first_page) self.removeLocked(allocator, page.*);
        }
    }

    fn clear(self: *PageCache, allocator: Allocator) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        self.clearLocked(allocator);
    }

    fn clearLocked(self: *PageCache, allocator: Allocator) void {
        self.clearPagesLocked(allocator);
        self.clearLinksLocked(allocator);
        self.refreshPageResourceUsageLocked();
        self.refreshLinkResourceUsageLocked();
    }

    fn clearPagesLocked(self: *PageCache, allocator: Allocator) void {
        for (self.pages.values()) |page| self.freePageLocked(allocator, page);
        self.clock_hand = 0;
        self.pages.clearRetainingCapacity();
    }

    fn clearLinksLocked(self: *PageCache, allocator: Allocator) void {
        var link_it = self.links.valueIterator();
        while (link_it.next()) |info| {
            if (info.key.len > 0) allocator.free(info.key);
        }
        self.links.clearRetainingCapacity();
        self.link_bytes = 0;
    }

    pub fn deinit(self: *PageCache, allocator: Allocator) void {
        self.clearLocked(allocator);
        self.releaseResourceUsageLocked();
        self.pages.deinit(allocator);
        self.links.deinit(allocator);
    }

    fn refreshPageResourceUsageLocked(self: *PageCache) void {
        const manager = self.resource_manager orelse return;
        manager.observeUsage(.lite_native_page_cache, &self.resource_page_accounted_bytes, @intCast(self.total_bytes));
    }

    fn refreshLinkResourceUsageLocked(self: *PageCache) void {
        const manager = self.resource_manager orelse return;
        manager.observeUsage(.lite_native_link_cache, &self.resource_link_accounted_bytes, @intCast(self.link_bytes));
    }

    fn releaseResourceUsageLocked(self: *PageCache) void {
        const manager = self.resource_manager orelse return;
        manager.observeUsage(.lite_native_page_cache, &self.resource_page_accounted_bytes, 0);
        manager.observeUsage(.lite_native_link_cache, &self.resource_link_accounted_bytes, 0);
        self.resource_manager = null;
    }

    fn clearPagesForHardPressureLocked(self: *PageCache, allocator: Allocator) bool {
        const manager = self.resource_manager orelse return false;
        const stats = manager.sliceStats(.lite_native_page_cache);
        if (stats.pressure != .hard or stats.hard_action != .shrink_cache) return false;
        // Budgets are shared across generations and handles. Reclaim this
        // cache's share of the aggregate excess, even when it is individually
        // smaller than the slice's soft limit.
        const reclaim: usize = @intCast(@min(stats.used_bytes -| stats.soft_limit_bytes, self.total_bytes));
        self.evictPagesToLocked(allocator, @min(self.total_bytes - reclaim, self.limit_bytes));
        self.refreshPageResourceUsageLocked();
        return true;
    }

    fn clearLinksForHardPressureLocked(self: *PageCache, allocator: Allocator) bool {
        const manager = self.resource_manager orelse return false;
        const stats = manager.sliceStats(.lite_native_link_cache);
        if (stats.pressure != .hard or stats.hard_action != .shrink_cache) return false;
        self.clearLinksLocked(allocator);
        self.refreshLinkResourceUsageLocked();
        return true;
    }
};

/// Bounded, page-addressed write staging. Pages may finish out of allocation
/// order (notably packed records and streaming index nodes). Keep ready pages
/// ordered in one fixed buffer, then write contiguous runs without filling gaps.
/// Cache admission happens only after every run succeeds; failure poisons the
/// batch so partially written private pages cannot be retried or published.
const PageWriteBatch = struct {
    const capacity = 64 * 1024;
    const max_pages = capacity / 4096;
    file: *NativeFile,
    options: WriteOptions = .{},
    // See `PageAllocator.diverting`'s own doc comment: propagated from the
    // allocator that owns this batch (`PageAllocator.writePage`'s lazy
    // init, or threaded explicitly into a standalone `ExtentAppender`/
    // `CatalogAppendState` batch literal built from that allocator).
    // `false` by default, so a batch built with no allocator in the
    // picture at all (a bare commit's ledger/free-map pages via
    // `writeLedgerPage`, a checkpoint-slot write, a disposable vacuum/copy
    // workspace file) never diverts regardless of `file.redo`.
    diverting: bool = false,
    buffer: [capacity]u8 = undefined,
    page_ids: [max_pages]u64 = undefined,
    used: usize = 0,
    failure: ?anyerror = null,

    fn reserve(self: *PageWriteBatch, page_id: u64) ![]u8 {
        if (self.failure) |err| return err;
        const size: usize = self.file.header.page_size;
        var count = self.used / size;
        var slot = count;
        // Consecutive writes append without moving bytes. Late packed pages
        // normally move only their immediately following index page.
        while (slot > 0 and self.page_ids[slot - 1] > page_id) : (slot -= 1) {}
        if (slot > 0 and self.page_ids[slot - 1] == page_id)
            return self.buffer[(slot - 1) * size ..][0..size];
        if (self.used + size > self.buffer.len) {
            // Drain only the earliest contiguous run. Keep the later run in
            // the window so an unfinished packed page can still join it.
            var end: usize = 1;
            while (end < count and self.page_ids[end] - self.page_ids[end - 1] == 1) : (end += 1) {}
            try self.flushCount(end);
            count = self.used / size;
            slot = count;
            while (slot > 0 and self.page_ids[slot - 1] > page_id) : (slot -= 1) {}
        }
        std.mem.copyBackwards(u8, self.buffer[(slot + 1) * size .. self.used + size], self.buffer[slot * size .. self.used]);
        std.mem.copyBackwards(u64, self.page_ids[slot + 1 .. count + 1], self.page_ids[slot..count]);
        self.page_ids[slot] = page_id;
        self.used += size;
        return self.buffer[slot * size ..][0..size];
    }

    fn appendPage(self: *PageWriteBatch, page_id: u64, kind: PageKind, payload: []const u8) !void {
        if (payload.len > self.file.maxPagePayloadBytes()) return error.PageTooLarge;
        const page = try self.reserve(page_id);
        encodePage(page, kind, payload);
    }

    fn appendValue(self: *PageWriteBatch, page_id: u64, next: u64, chunk: []const u8) !void {
        if (chunk.len == 0 or chunk.len > self.file.maxValuePagePayloadBytes()) return error.InvalidNativeValueChain;
        const page = try self.reserve(page_id);
        var prefix: [value_page_header_size]u8 = undefined;
        std.mem.writeInt(u64, &prefix, next, .little);
        encodePageParts(page, .value, &prefix, chunk);
    }

    fn flush(self: *PageWriteBatch) !void {
        try self.flushCount(self.used / self.file.header.page_size);
    }

    fn flushCount(self: *PageWriteBatch, count: usize) !void {
        var zig017_return_error: ?anyerror = null;
        if (self.failure) |err| return err;
        if (count == 0) return;
        errdefer {
            if (zig017_return_error) |err| self.failure = err;
        }
        const file = self.file;
        const size: usize = file.header.page_size;
        var start: usize = 0;
        while (start < count) {
            var end = start + 1;
            while (end < count and self.page_ids[end] - self.page_ids[end - 1] == 1) : (end += 1) {}
            if (self.diverting and file.redo != null and !file.redo.?.checkpointing) {
                // `self.diverting` (propagated from the owning
                // `PageAllocator`, see its own doc comment) scopes this
                // branch to the one legitimate page-shaped exception -- an
                // external value chain staged through
                // `pageAllocatorForDivertingCommit` during an ordinary
                // (non-fold) transactional commit. A bare commit's own
                // pages (`pageAllocatorFromFreeMap`, `diverting = false`)
                // always take the real-pwrite branch below, matching
                // `putIndexedDocumentBatch`'s and `publishBareCommit`'s own
                // doc comments ("a bare commit never diverts") --
                // `file.redo != null` alone used to be this check's only
                // condition, which silently broke that invariant for every
                // bare commit once `use_redo_log` became the default.
                // Only page-shaped writes (external value chains) reach
                // this at all -- see `RedoCommitState`'s own doc comment --
                // since `flushTransactionWrites` diverts the B-tree roots
                // logically, before any page is ever built.
                //
                // §9 (heap-bound writes): staging every page through
                // `redo.appendPending` instead of writing it -- buffering a
                // full copy in `redo.pending` (tracked) and another in the
                // overlay (untracked, via `std.heap.page_allocator`) until
                // this commit's own eventual `appendRecord`/overflow check,
                // which only ever runs once, at the end of the whole
                // commit -- makes peak memory proportional to a single
                // external value chain's own size. For a *catalog* value
                // (`file.direct_value_pages`, see its own doc comment:
                // `writeCatalogValue`, `CatalogAppendState`,
                // `putIndexCatalogRecordFromFile`), that is unbounded by
                // the caller's own private-flush chunking (which only
                // bounds the staged catalog *mutation*, never the
                // page-shaped bytes underneath it), so these pages are
                // written for real, immediately, exactly like the
                // non-diverting branch below (same run-coalesced write,
                // same test instrumentation) -- always safe: each is a
                // fresh, append-only id (`pageAllocatorForDivertingCommit`'s
                // own doc comment) that nothing can reference until this
                // same commit's logical mutation durably publishes, so a
                // torn or orphaned page here on an abort or a crash is
                // exactly as harmless as the one a bare, non-diverting
                // commit already risks the same way. No separate durable
                // copy belongs in the redo log for it either, matching
                // `commitTransactionWithDurability`'s and
                // `publishCheckpoint`'s own "page-shaped only" fallback,
                // which already writes these pages directly rather than
                // ever embedding them in a log record. No manifest
                // bookkeeping, unlike the non-diverting branch below --
                // meaningless under a redo-log commit; see
                // `NativeFile.manifest_commits_enabled`, already `false`
                // for this file.
                //
                // A document's own value chain (`file.direct_value_pages ==
                // false`) keeps staging through `redo.appendPending`
                // exactly as before: one document write is one external
                // value, written once, with no comparable unbounded
                // private-flush accumulation to begin with, and other
                // tests already depend on the current page_count-runs-ahead-
                // of-physical-size behavior for a still-diverting
                // document write (`check()`'s own redo-aware tolerance,
                // vacuum/cross-process recovery).
                if (file.direct_value_pages) {
                    if (builtin.is_test) {
                        if (file.test_page_write_fail_after) |remaining| {
                            if (remaining == 0) return zig017_failure: {
                                zig017_return_error = error.TestPageWriteFailure;
                                break :zig017_failure error.TestPageWriteFailure;
                            };
                            file.test_page_write_fail_after = remaining - 1;
                        }
                        _ = file.test_page_write_calls.fetchAdd(1, .monotonic);
                        _ = file.test_page_writes.fetchAdd(@intCast(end - start), .monotonic);
                    }
                    file.file.writePositionalAll(file.runtimeIo(), self.buffer[start * size .. end * size], self.page_ids[start] * @as(u64, size)) catch |zig017_err| {
                        zig017_return_error = zig017_err;
                        return zig017_err;
                    };
                } else {
                    const redo = &file.redo.?;
                    for (self.page_ids[start..end], start..end) |page_id, i| {
                        redo.appendPending(file.allocator, file.runtimeIo(), page_id, self.buffer[i * size ..][0..size]) catch |zig017_err| {
                            zig017_return_error = zig017_err;
                            return zig017_err;
                        };
                    }
                }
            } else {
                if (builtin.is_test) {
                    if (file.test_page_write_fail_after) |remaining| {
                        if (remaining == 0) return zig017_failure: {
                            zig017_return_error = error.TestPageWriteFailure;
                            break :zig017_failure error.TestPageWriteFailure;
                        };
                        file.test_page_write_fail_after = remaining - 1;
                    }
                    _ = file.test_page_write_calls.fetchAdd(1, .monotonic);
                    _ = file.test_page_writes.fetchAdd(@intCast(end - start), .monotonic);
                }
                // Reserve room for this window's entries before the write below,
                // so `note` itself never allocates -- see
                // `ManifestBuilder.reserveCapacity`'s doc comment: a no-op for
                // every window after the file's first.
                if (file.manifest_commits_enabled) {
                    try file.manifest_builder.reserveCapacity(file.allocator);
                }
                (file.file.writePositionalAll(file.runtimeIo(), self.buffer[start * size .. end * size], self.page_ids[start] * @as(u64, size)) catch |zig017_err| {
                    zig017_return_error = zig017_err;
                    return zig017_err;
                });
                if (builtin.is_test) if (std.enums.fromInt(PageKind, self.buffer[start * size ..][4])) |kind| {
                    PageWriteMetrics.record(kind, (end - start) * size);
                };
                // This loop is the choke point every PageWriteBatch-staged data
                // page passes through on its way to disk (appendPage/appendValue
                // only stage bytes into `buffer`; this is where they are
                // actually written), so recording the manifest entry here --
                // instead of at every staging call site -- cannot miss one
                // regardless of which higher-level writer staged it, and
                // regardless of whether this write happens during staging, a
                // non-durable commit, or the eventual durable one.
                if (file.manifest_commits_enabled) {
                    for (self.page_ids[start..end], start..end) |page_id, i|
                        file.manifest_builder.note(page_id, std.mem.readInt(u32, self.buffer[i * size ..][page_crc_offset..][0..4], .little));
                }
            }
            start = end;
        }
        for (self.page_ids[0..count], 0..) |page_id, i|
            file.cacheWrittenPage(page_id, self.buffer[i * size ..][0..size], self.options);
        const remaining = self.used - count * size;
        std.mem.copyForwards(u8, self.buffer[0..remaining], self.buffer[count * size .. self.used]);
        std.mem.copyForwards(u64, self.page_ids[0 .. remaining / size], self.page_ids[count .. self.used / size]);
        self.used = remaining;
    }
};

pub const ChangeCapture = struct {
    pub const Root = enum { metadata, index, documents };
    const max_key_bytes = 4 * 1024 * 1024;
    const max_keys = 65536;
    keys: [3]std.StringHashMapUnmanaged(void) = .{ .empty, .empty, .empty },
    key_bytes: usize = 0,
    count: usize = 0,
    overflow: bool = false,

    pub fn deinit(self: *ChangeCapture, allocator: Allocator) void {
        for (&self.keys) |*map| {
            var it = map.keyIterator();
            while (it.next()) |key| allocator.free(key.*);
            map.deinit(allocator);
        }
        self.* = .{};
    }

    fn record(self: *ChangeCapture, allocator: Allocator, root: Root, key: []const u8) void {
        if (self.overflow) return;
        const map = &self.keys[@backingInt(root)];
        if (map.contains(key)) return;
        if (key.len > max_key_bytes - self.key_bytes or self.count == max_keys) {
            self.overflow = true;
            return;
        }
        const owned = allocator.dupe(u8, key) catch {
            self.overflow = true;
            return;
        };
        map.put(allocator, owned, {}) catch {
            allocator.free(owned);
            self.overflow = true;
            return;
        };
        self.count += 1;
        self.key_bytes += key.len;
    }
};

pub const VacuumImage = struct {
    prepared: NativeFile,
    report: VacuumReport,

    pub fn deinit(self: *VacuumImage) void {
        {
            const io = self.prepared.runtimeIo();
            const previous = io.swapCancelProtection(.blocked);
            defer _ = io.swapCancelProtection(previous);
            deleteFilePath(io, self.prepared.path) catch {};
        }
        // Restore protection before close can release an owned I/O runtime.
        self.prepared.close();
        self.* = undefined;
    }
};

pub const ReaderCoordinator = @import("reader_coordinator.zig").Coordinator;

/// Off by default. Crash/durability investigations (regression B: an
/// acknowledged full_index write surviving to a stale checkpoint after a
/// ride-along merge/retirement) flip this on for the duration of their own
/// run to log every recovery candidate's slot index/commit_sequence/verify
/// result, and every ride-along (non-durable) commit's resulting
/// commit_sequence and whether durable_header moved.
pub var recovery_debug_log: bool = false;

fn recoveryDebugLog(comptime fmt: []const u8, args: anytype) void {
    if (!recovery_debug_log) return;
    std.debug.print("[native-recovery] " ++ fmt ++ "\n", args);
}

var test_header_fingerprint_hashes: std.atomic.Value(u64) = .init(0);

test "lite header fingerprints cache unchanged state and fence every header field" {
    var file: NativeFile = .{ .allocator = std.testing.allocator, .io_impl = undefined, .path = undefined, .file = undefined, .header = .{} };
    const original = file.header;
    const expected = NativeFile.fingerprintHeader(original);
    const before = test_header_fingerprint_hashes.load(.monotonic);
    for (0..64) |_| try std.testing.expectEqual(expected, file.headerFingerprint());
    try std.testing.expectEqual(before + 1, test_header_fingerprint_hashes.load(.monotonic));
    inline for (@typeInfo(Header).@"struct".field_names, @typeInfo(Header).@"struct".field_types) |field, Field| {
        if (comptime std.mem.eql(u8, field, "checkpoints")) {
            inline for (0..checkpoint_slot_count) |slot| {
                inline for (@typeInfo(CheckpointSlot).@"struct".field_names, @typeInfo(CheckpointSlot).@"struct".field_types) |checkpoint_field, CheckpointField| {
                    // fingerprintHeader hashes both slots unconditionally
                    // (see its doc comment), so a mutation to either one is
                    // observable regardless of which is active; setting
                    // active_checkpoint here is just to exercise both.
                    if (comptime std.mem.eql(u8, checkpoint_field, "logical")) {
                        inline for (@typeInfo(LogicalGenerations).@"struct".field_names) |identity| {
                            file.header = original;
                            file.header.indexed_reclamation = true;
                            file.header.active_checkpoint = slot;
                            const indexed_before = NativeFile.fingerprintHeader(file.header);
                            @field(file.header.checkpoints[slot].logical, identity)[0] = 1;
                            try std.testing.expectEqual(NativeFile.fingerprintHeader(file.header), file.headerFingerprint());
                            try std.testing.expect(!std.mem.eql(u8, &indexed_before, &file.headerFingerprint()));
                        }
                        continue;
                    }
                    file.header = original;
                    file.header.active_checkpoint = slot;
                    const before_mutation = NativeFile.fingerprintHeader(file.header);
                    if (comptime CheckpointField == bool) {
                        @field(file.header.checkpoints[slot], checkpoint_field) = !@field(file.header.checkpoints[slot], checkpoint_field);
                    } else {
                        @field(file.header.checkpoints[slot], checkpoint_field) += 1;
                    }
                    try std.testing.expectEqual(NativeFile.fingerprintHeader(file.header), file.headerFingerprint());
                    try std.testing.expect(!std.mem.eql(u8, &before_mutation, &file.headerFingerprint()));
                }
            }
        } else if (comptime std.mem.eql(u8, field, "active_checkpoint")) {
            // Both slots are hashed unconditionally, in fixed index order:
            // which one is active is not part of the recoverable identity
            // (each slot already carries its own commit_sequence), so this
            // field alone must never change the fingerprint -- even with
            // differing slot content, let alone the identical defaults
            // `original` starts with.
            file.header = original;
            file.header.checkpoints[1].commit_sequence = 1;
            file.header.active_checkpoint = 0;
            const before_flip = file.headerFingerprint();
            file.header.active_checkpoint = 1;
            try std.testing.expectEqual(before_flip, file.headerFingerprint());
        } else {
            file.header = original;
            if (comptime Field == bool) {
                @field(file.header, field) = !@field(original, field);
            } else if (comptime Field == [32]u8) {
                file.header.indexed_reclamation = true;
                const indexed = NativeFile.fingerprintHeader(file.header);
                @field(file.header, field)[0] ^= 1;
                try std.testing.expect(!std.mem.eql(u8, &indexed, &file.headerFingerprint()));
            } else @field(file.header, field) += 1;
            try std.testing.expectEqual(NativeFile.fingerprintHeader(file.header), file.headerFingerprint());
            try std.testing.expect(!std.mem.eql(u8, &expected, &file.headerFingerprint()));
        }
    }
    file.header = original;
    file.transaction_header = original;
    file.transaction_header.?.checkpoints[1].commit_sequence = 99;
    try std.testing.expectEqual(NativeFile.fingerprintHeader(file.transaction_header.?), file.headerFingerprint());
    // Abort restores the committed key; no stale transaction digest may survive.
    file.transaction_header = null;
    try std.testing.expectEqual(expected, file.headerFingerprint());
}

test "lite header fingerprint cache publishes coherent keys and digests to concurrent readers" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const Shared = struct {
        cache: HeaderFingerprintCache = .{},
        failed: std.atomic.Value(bool) = .init(false),
        fn run(self: *@This(), worker: usize) void {
            for (0..64) |i| {
                var header: Header = .{};
                header.checkpoints[worker % checkpoint_slot_count].commit_sequence = @intCast(i % 3);
                const expected = NativeFile.fingerprintHeader(header);
                const digest = self.cache.lookup(header) orelse blk: {
                    self.cache.remember(header, expected);
                    break :blk expected;
                };
                if (!std.mem.eql(u8, &expected, &digest)) self.failed.store(true, .monotonic);
            }
        }
    };
    var shared: Shared = .{};
    var tasks: [4]std.Io.Future(void) = undefined;
    var started: usize = 0;
    defer for (tasks[0..started]) |*task| task.await(std.testing.io);
    for (&tasks, 0..) |*task, worker| {
        task.* = try std.testing.io.concurrent(Shared.run, .{ &shared, worker });
        started += 1;
    }
    for (&tasks) |*task| task.await(std.testing.io);
    started = 0;
    try std.testing.expect(!shared.failed.load(.monotonic));
}

// NativeFile generations can serve concurrent readers. Cache only a complete
// structural header match, including the inactive recovery slot and transaction
// header. A publication, rollback or reload therefore invalidates naturally;
// persisted certificate bytes and the canonical digest remain unchanged.
const HeaderFingerprintCache = struct {
    mutex: std.atomic.Mutex = .unlocked,
    cached: ?struct { header: Header, digest: [32]u8 } = null,

    fn lookup(self: *HeaderFingerprintCache, header: Header) ?[32]u8 {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        if (self.cached) |entry| if (std.meta.eql(entry.header, header)) return entry.digest;
        return null;
    }

    fn remember(self: *HeaderFingerprintCache, header: Header, digest: [32]u8) void {
        platform_sync.lockYielding(&self.mutex);
        defer self.mutex.unlock();
        self.cached = .{ .header = header, .digest = digest };
    }
};

/// §9.7c: the one read primitive for a redo-log-capable `NativeFile`. A
/// pinned pair -- checkpoint `C` (the physical B-tree root this view's
/// tree-side reads are pinned to) and overlay read mark `M` (the
/// logical commit sequence this view's overlay-side reads are pinned
/// to) -- captured together, at the same moment, because under redo
/// mode they are not always the same number (`NativeFile.committedSequence`'s
/// own doc comment): an ordinary commit can advance `M` without
/// `C`'s own physical root pages moving at all, until the next
/// `checkpointRedoLog`.
///
/// This exists to stop the overlay-blind-read bug class found three
/// separate times on three separate call sites while flipping the
/// redo-log default (`docstore.Cursor`'s own three-way merge,
/// `getDocumentsAtCheckpointWithState`'s batch pre-pass, and
/// `readBackingPages`'s read-ahead window -- see this struct's own
/// design-doc section for the full account) and a fourth found
/// building this type itself (`OverlayScanState.initForPrefix`'s old
/// "must equal the live checkpoint exactly" gate silently emptying the
/// overlay for every `ReadView`-shaped caller reached through a
/// `ReadGeneration`'s separately-opened file, including the
/// dense/sparse/graph/full-text native-catalog seed in
/// `native_catalog_sink.zig` and the index virtual-filesystem's
/// directory listing in `index_storage.zig` -- fixed by deleting that
/// gate, since per-key resolution was already checkpoint-independent;
/// see that function's own doc comment).
///
/// `open`/`openAt` pin with exactly the two calls
/// `Store.pinInitializedReadGeneration` already makes, in the same
/// order: the overlay mark `M` first (`redo.shared.pin`), then the
/// checkpoint `C` (`inode_lock.pinReader`); `release` unpins in
/// reverse. A `ReadView` constructed via `borrowed` instead describes
/// an already-pinned generation (a `Txn`'s own `ReadPin`, held for the
/// whole transaction) and never pins or unpins on its own -- `release`
/// on one of these is a no-op, matching `ReadGeneration`'s existing,
/// separate, longer-lived pin lifecycle. Both constructor families
/// resolve the exact same read methods below the exact same way.
pub const ReadView = struct {
    file: *NativeFile,
    checkpoint: CheckpointSlot, // C: physical tree-root pointers
    mark: u64, // M: overlay resolution ceiling (logical commit sequence)
    owns_pin: bool = false,

    /// Pins the current generation: `C` is `file`'s own active
    /// checkpoint, `M` is its own committed (logical) sequence,
    /// captured together. For the live writer's own handle these two
    /// numbers already move in lockstep (`NativeFile.committedSequence`'s
    /// doc comment); captured as two separate fields regardless, so a
    /// future caller that opens this on a handle where they genuinely
    /// diverge gets the correct answer without this type changing.
    ///
    /// perf/lwa-restore-open-txn (design doc §9.8): this constructor
    /// already pinned correctly (`openAt` below takes the overlay pin
    /// and the inode reader-table pin together, atomically with respect
    /// to itself) -- the bug was a caller, `docstore.zig`'s
    /// `Txn.openReadWithPrefix`'s `store.read_only` short-circuit,
    /// capturing `store.file.activeCheckpoint()` into a bare `Txn`
    /// literal instead of ever calling `open`/`openAt` at all, so nothing
    /// pinned it: a concurrent fold's own `SharedRedoOverlay.reclaim`
    /// (gated on `minimumPinnedSequence`, which only ever protects a mark
    /// some live pin actually registered) could drop an overlay-only
    /// (unfolded) key that bare checkpoint still depended on, between the
    /// capture and the read -- a fully committed, redo-log-only document
    /// going missing from a fresh `.query_readonly` open racing a live
    /// writer's own background maintenance fold. Fixed at that call
    /// site, not here: it now opens a real `ReadView` and keeps it pinned
    /// for the `Txn`'s own lifetime (released in `abort()`), the same
    /// scope every other read path already gets this primitive for.
    pub fn open(file: *NativeFile, io: std.Io) !ReadView {
        return openAt(file, io, file.activeCheckpoint());
    }

    /// Pins an explicit checkpoint: either an older, already-
    /// checkpointed generation (`C == M == checkpoint.commit_sequence`
    /// trivially, nothing logged against it is still only in the
    /// overlay), or the live writer's own freshly observed checkpoint
    /// passed in by a caller that tracks it externally (`docstore.zig`'s
    /// `ReadGeneration.checkpoint`, kept current by
    /// `Store.observeReadCheckpoint` on every publish even though
    /// `file` itself -- a separately-opened `ReadGeneration.file` --
    /// never processes a commit itself and so never advances its own
    /// `activeCheckpoint()`/`committedSequence()`).
    pub fn openAt(file: *NativeFile, io: std.Io, checkpoint: CheckpointSlot) !ReadView {
        var view: ReadView = .{ .file = file, .checkpoint = checkpoint, .mark = file.readMark(checkpoint), .owns_pin = false };
        // A handle frozen at an older checkpoint whose overlay versions a
        // fold has since reclaimed cannot be read correctly any more:
        // refuse it (`error.ReadSnapshotReclaimed`) instead of letting it
        // fall through missing overlay entries to a tree that predates
        // the fold. Callers reopen to get a current view.
        if (file.redo) |*redo| try redo.shared.pinUnlessReclaimed(std.heap.page_allocator, io, view.mark, checkpoint.commit_sequence);
        errdefer if (file.redo) |*redo| redo.shared.unpin(io, view.mark);
        if (file.inode_lock_ref.load(.acquire)) |entry| {
            try inode_lock.pinReader(entry, io, .{ .data = checkpoint.commit_sequence, .metadata = checkpoint.commit_sequence });
        }
        view.owns_pin = true;
        return view;
    }

    /// A view over a generation already pinned by some longer-lived
    /// mechanism (today: `docstore.zig`'s `ReadPin`/`ReadGeneration`,
    /// held for a whole `Txn`'s lifetime). `release` is a no-op; the
    /// caller's own pin lifecycle remains authoritative. Every read
    /// method below behaves identically regardless of which
    /// constructor produced this view.
    pub fn borrowed(file: *NativeFile, checkpoint: CheckpointSlot) ReadView {
        return .{ .file = file, .checkpoint = checkpoint, .mark = file.readMark(checkpoint), .owns_pin = false };
    }

    /// Unpins, in reverse of `open`/`openAt`'s own order. A no-op for a
    /// `borrowed` view. Idempotent: safe to call more than once, or on
    /// a view that never owned a pin.
    pub fn release(self: *ReadView, io: std.Io) void {
        if (!self.owns_pin) return;
        self.owns_pin = false;
        if (self.file.inode_lock_ref.load(.acquire)) |entry| {
            inode_lock.unpinReader(entry, io, .{ .data = self.checkpoint.commit_sequence, .metadata = self.checkpoint.commit_sequence });
        }
        if (self.file.redo) |*redo| redo.shared.unpin(io, self.mark);
    }

    pub fn getDocumentAlloc(self: *const ReadView, allocator: Allocator, key: []const u8) !?[]u8 {
        return self.file.getDocumentAtCheckpointAlloc(allocator, self.checkpoint, key);
    }

    pub fn documentReference(self: *const ReadView, key: []const u8) !?u64 {
        return self.file.documentReferenceAtCheckpoint(self.checkpoint, key);
    }

    pub fn documentFingerprint(self: *const ReadView, key: []const u8) !?[32]u8 {
        return self.file.documentFingerprintAtCheckpoint(self.checkpoint, key);
    }

    pub fn getDocumentsAlloc(self: *const ReadView, allocator: Allocator, keys: []const []const u8, values: []?[]const u8) !void {
        return self.file.getDocumentsAtCheckpointAlloc(allocator, self.checkpoint, keys, values);
    }

    pub fn getDocumentsWithState(self: *const ReadView, allocator: Allocator, temporary: Allocator, keys: []const []const u8, buffers: ?[]const []u8, values: []?[]const u8, state: *DocumentBatchReadState) !void {
        return self.file.getDocumentsAtCheckpointWithState(allocator, temporary, self.checkpoint, keys, buffers, values, state);
    }

    pub fn openIndexValue(self: *const ReadView, allocator: Allocator, key: []const u8) !NativeFile.IndexValue {
        return self.file.openIndexValue(allocator, key, self.checkpoint);
    }

    pub fn readIndexValueInto(self: *const ReadView, value: NativeFile.IndexValue, offset: u64, out: []u8) !void {
        return self.file.readIndexValueInto(value, offset, out, self.checkpoint);
    }

    pub fn checksumIndexValue(self: *const ReadView, value: NativeFile.IndexValue, offset: u64, length: u64) !u32 {
        return self.file.checksumIndexValue(value, offset, length, self.checkpoint);
    }

    pub fn readAuthenticatedIndexValue(self: *const ReadView, value: NativeFile.IndexValue, offset: u64, length: u64, within: usize, out: []u8, expected: ?u32) !void {
        return self.file.readAuthenticatedIndexValue(value, offset, length, within, out, expected, self.checkpoint);
    }

    pub fn copyIndexValueTo(self: *const ReadView, value: NativeFile.IndexValue, destination: std.Io.File) !void {
        return self.file.copyIndexValueTo(value, destination, self.checkpoint);
    }

    /// A prefix/range cursor over the metadata catalog root, overlay
    /// merged exactly like every other `ReadView` read (`catalogCursor`'s
    /// `OverlayScanState.initForPrefix`, gate-free since the fix above).
    pub fn openMetadataCursor(self: *const ReadView, prefix: []const u8) !CatalogCursor {
        return self.file.metadataCatalogCursor(self.checkpoint, prefix);
    }

    /// Like `openMetadataCursor`, over the index catalog root (full-text/
    /// dense/sparse/graph native-catalog records, artifact leases,
    /// virtual-filesystem directory entries).
    pub fn openIndexCursor(self: *const ReadView, prefix: []const u8) !CatalogCursor {
        return self.file.indexCatalogCursor(self.checkpoint, prefix);
    }

    /// Like `openIndexCursor`, restricted to `prefix`'s immediate
    /// children (one path segment deep) -- the virtual-filesystem
    /// directory-listing shape.
    pub fn openIndexDirectoryCursor(self: *const ReadView, prefix: []const u8) !CatalogCursor {
        return self.file.indexCatalogDirectoryCursor(self.checkpoint, prefix);
    }

    /// A two-way (checkpointed tree, redo-log overlay) merged cursor
    /// over the document root, scoped to `prefix`. The only way to walk
    /// the document root other than the fully-resolved
    /// `getDocumentAlloc`/`getDocumentsAlloc` family -- `MergedCursor`
    /// hides `CheckpointedTree` (non-`pub`) behind this one constructor,
    /// per §9.7c's "the raw tree becomes a distinct type, reachable
    /// only through `ReadView`." `docstore.Cursor` layers its own
    /// transaction's `pending_tree` on top of this (design doc: "pending
    /// writes of the transaction itself layer on top, in docstore").
    pub fn openMergedDocumentCursor(self: *const ReadView, key_allocator: Allocator, prefix: []const u8) !MergedCursor {
        return .{
            .tree = CheckpointedTree.initWithKeyAllocator(self.file, self.checkpoint, key_allocator),
            .overlay = try NativeFile.OverlayScanState.initForPrefixUnchecked(key_allocator, self.file, .documents, prefix),
            .mark = self.mark,
        };
    }
};

/// §9.7c (ReadView): the two-way (checkpointed tree, redo-log overlay)
/// merge-join every document-root scan needs -- extracted, not
/// reinvented, from `docstore.Cursor`'s own original three-way merge
/// (`pending_tree` over this over the real B-tree): the comparison,
/// tie-breaking (a tie always favors the overlay, the newer state),
/// and lookahead-buffering rules here are exactly the ones that merge
/// already used for its own "redo" vs "disk" half, just relocated so
/// `CheckpointedTree` no longer needs to be `pub`. `docstore.Cursor`
/// now holds one of these instead of a `CheckpointedTree` plus an
/// `OverlayScanState`, and compares its own `pending_tree` candidate
/// against whatever this type returns.
pub const MergedCursor = struct {
    pub const Direction = enum { forward, backward };

    tree: CheckpointedTree,
    overlay: NativeFile.OverlayScanState,
    mark: u64,
    /// The tree's own already-fetched candidate, held here whenever the
    /// overlay's candidate won a comparison without a tie: `tree`'s own
    /// position has already advanced past it, so losing track of it
    /// here would silently skip it forever, not just defer it to the
    /// next call. `null` means either nothing is buffered yet, or the
    /// last `advance` call fully consumed (returned, or matched a tie
    /// against) whatever it held.
    tree_lookahead: ?DocumentIndexEntry = null,

    pub const Entry = union(enum) {
        disk: DocumentIndexEntry,
        overlay: struct { key: []const u8, entry: CatalogEntry },

        pub fn key(self: Entry) []const u8 {
            return switch (self) {
                .disk => |d| d.key,
                .overlay => |o| o.key,
            };
        }

        /// Frees whichever side owns allocated memory: `disk`'s own
        /// key (`DocumentIndexEntry.deinit`'s own contract) or
        /// `overlay`'s resolved entry value (the owned copy
        /// `SharedRedoOverlay.resolveAlloc` returns, via
        /// `redoOverlayEntryAt`). `overlay`'s own `key` is borrowed from
        /// `MergedCursor.overlay`'s current (or, briefly, most recently
        /// superseded) position and must never be freed here --
        /// `OverlayScanState` owns and frees it on its own schedule
        /// (`stale`'s own doc comment: it stays valid until this same
        /// `OverlayScanState` is asked to move again).
        pub fn deinit(self: *Entry, allocator: Allocator) void {
            switch (self.*) {
                .disk => |*d| d.deinit(allocator),
                .overlay => |*o| allocator.free(o.entry.value),
            }
        }
    };

    pub fn deinit(self: *MergedCursor) void {
        self.clearTreeLookahead();
        self.overlay.deinit();
        self.tree.deinit();
        self.* = undefined;
    }

    fn clearTreeLookahead(self: *MergedCursor) void {
        if (self.tree_lookahead) |*entry| entry.deinit(self.tree.file.allocator);
        self.tree_lookahead = null;
    }

    fn fetchTree(self: *MergedCursor, direction: Direction) !?DocumentIndexEntry {
        if (self.tree_lookahead) |entry| {
            self.tree_lookahead = null;
            return entry;
        }
        return switch (direction) {
            .forward => try self.tree.next(),
            .backward => try self.tree.prev(),
        };
    }

    pub fn first(self: *MergedCursor) !?Entry {
        self.clearTreeLookahead();
        self.tree_lookahead = try self.tree.first();
        try self.overlay.resetToFirst();
        return self.advance(.forward);
    }

    pub fn last(self: *MergedCursor) !?Entry {
        self.clearTreeLookahead();
        self.tree_lookahead = try self.tree.last();
        try self.overlay.resetToLast();
        return self.advance(.backward);
    }

    pub fn seekAtOrAfter(self: *MergedCursor, key: []const u8, strict: bool) !?Entry {
        self.clearTreeLookahead();
        self.tree_lookahead = try self.tree.seekAtOrAfter(key, strict);
        try self.overlay.resetToAtOrAfter(key, strict);
        return self.advance(.forward);
    }

    pub fn seekAtOrBefore(self: *MergedCursor, key: []const u8, strict: bool) !?Entry {
        self.clearTreeLookahead();
        self.tree_lookahead = try self.tree.seekAtOrBefore(key, strict);
        try self.overlay.resetToAtOrBefore(key, strict);
        return self.advance(.backward);
    }

    /// `continued`: true to pick up where the last `next`/`advance`
    /// call left off (reusing a buffered tree lookahead instead of a
    /// fresh seek) -- false (a direction change) forces `seekAtOrAfter`
    /// from `current_key` instead, mirroring `docstore.Cursor`'s own
    /// `last_direction`-gated choice between `takeBufferedDisk()` and a
    /// fresh seek. The overlay side always re-seeks fresh from
    /// `current_key` regardless of `continued` -- an O(log n) seek, same
    /// cost either way, so there is no "continuation" to preserve there.
    pub fn next(self: *MergedCursor, current_key: []const u8, continued: bool) !?Entry {
        if (!continued) {
            self.clearTreeLookahead();
            self.tree_lookahead = try self.tree.seekAtOrAfter(current_key, true);
        }
        try self.overlay.resetToAtOrAfter(current_key, true);
        return self.advance(.forward);
    }

    pub fn prev(self: *MergedCursor, current_key: []const u8, continued: bool) !?Entry {
        if (!continued) {
            self.clearTreeLookahead();
            self.tree_lookahead = try self.tree.seekAtOrBefore(current_key, true);
        }
        try self.overlay.resetToAtOrBefore(current_key, true);
        return self.advance(.backward);
    }

    /// Advances past a tombstoned overlay winner on its own (the
    /// overlay already proves that key dead; nothing left for the
    /// caller to check there). A `.disk` winner is returned exactly as
    /// the tree gave it, unresolved -- the caller decides liveness
    /// (`RecordPageReader.documentValueAlloc`/`documentValueLen`/
    /// `documentIsLive`, the keys-only/length-only short-circuits
    /// `MergedCursor` deliberately knows nothing about) and, if it
    /// turns out dead, calls `advance` again directly to continue past
    /// it -- `tree_lookahead` is already `null` at that point (a
    /// `.disk` return always clears it), so the next call fetches
    /// fresh, exactly like finding a live one would have.
    pub fn advance(self: *MergedCursor, direction: Direction) !?Entry {
        var disk = try self.fetchTree(direction);
        errdefer if (disk) |*d| d.deinit(self.tree.file.allocator);
        while (true) {
            const overlay_key: ?[]const u8 = self.overlay.current;
            const Source = enum { overlay, disk };
            var winner: ?Source = null;
            var winner_key: []const u8 = undefined;
            if (overlay_key) |k| {
                winner = .overlay;
                winner_key = k;
            }
            if (disk) |d| {
                const better = if (winner != null) switch (direction) {
                    .forward => std.mem.order(u8, d.key, winner_key) == .lt,
                    .backward => std.mem.order(u8, d.key, winner_key) == .gt,
                } else true;
                if (better) {
                    winner = .disk;
                    winner_key = d.key;
                }
            }
            const chosen = winner orelse return null;

            // A tie always sets `chosen = .overlay` (the `better`
            // check above requires a strict order for disk to win), so
            // `chosen == .disk` here implies `overlay_key` is either
            // `null` or strictly past `winner_key` -- nothing to
            // consume on the overlay side.
            if (chosen == .disk) {
                self.tree_lookahead = null;
                return .{ .disk = disk.? };
            }

            // `chosen == .overlay`: advance the overlay's own position
            // past this key regardless of what it resolves to below --
            // visited either way. `winner_key` stays valid past this
            // call (`OverlayScanState.step`'s own `stale`-retention
            // contract) through everything this loop iteration still
            // does with it below, including a `return` that hands it
            // out as a borrowed `Entry.overlay.key`.
            try self.overlay.step(direction == .forward);
            // The overlay enumerates every key with *any* version
            // currently in the live map, regardless of this cursor's
            // own `mark` -- correct and necessary for the *current*
            // generation (every version predates "now" by definition),
            // but a `ReadView` pinned to an older, already-superseded
            // mark can enumerate a key whose entire chain postdates it
            // (e.g. a brand-new key created only after this pin's own
            // snapshot was taken). `resolveAlloc` then correctly
            // returns `null` -- "nothing at or before this mark" --
            // which must be treated exactly like the real tree never
            // having had this key diverted away from it at this mark:
            // resolved *before* deciding whether to consume a tied
            // `disk` candidate below, so a phantom overlay entry never
            // wrongly discards a disk candidate that is, in fact, the
            // correct answer for this view.
            const entry = try self.tree.file.redoOverlayEntryAt(.documents, self.mark, winner_key);
            if (disk != null and std.mem.eql(u8, disk.?.key, winner_key) and entry != null) {
                var consumed = disk.?;
                consumed.deinit(self.tree.file.allocator);
                disk = try self.fetchTree(direction);
            }
            if (entry == null) continue; // phantom: disk (if tied) stays live for the next iteration.
            if (entry.?.is_delete) {
                self.tree.file.allocator.free(entry.?.value);
                continue;
            }
            // Whatever disk candidate remains (possibly null) must
            // survive to the next call.
            self.tree_lookahead = disk;
            return .{ .overlay = .{ .key = winner_key, .entry = entry.? } };
        }
    }
};
/// Debug-only overlap backstop for `beginTransaction`/`commitTransactionWithDurability`/
/// `abortTransaction` (lite-writer-race investigation, docs/design/lite-performance/
/// lite-single-commit-write-path.md §8/§9). See `NativeFile.commit_span_depth`'s
/// own doc comment for what this catches and why it is scoped wider than
/// `transaction_header != null`. Off in release builds, like
/// `publication_mutex_owner_tracking` in docstore.zig, which this mirrors.
///
/// Deliberately *not* identity-based (no thread id, no owner field):  an
/// earlier version of this guard keyed the sanctioned-reentry exception off
/// "is the current thread already the holder", which this codebase's own
/// `std.Io.Threaded` runtime can defeat -- a logical task is not 1:1 with an
/// OS thread under its scheduler (one worker thread can run two unrelated
/// tasks back to back, and `std.Thread.getCurrentId()` cannot tell them
/// apart), so a thread-identity check can quietly treat a second, unrelated
/// caller as "the same caller, reentering" and skip the very overlap it
/// exists to catch. A plain depth counter, deepened only by the few call
/// sites that *know* they are nested (see `commit_span_nested_allowance`),
/// has no such gap: it never has to guess who is calling.
const debug_commit_span_tracking = std.debug.runtime_safety;

pub const NativeFile = struct {
    allocator: Allocator,
    /// The default constructors own this Threaded runtime. Borrowed-I/O
    /// constructors leave it undefined and retain `borrowed_io` instead. This
    /// keeps the production convenience API while making the complete Lite
    /// file lifecycle executable by deterministic std.Io implementations.
    io_impl: std.Io.Threaded,
    borrowed_io: ?std.Io = null,
    path: []u8,
    file: std.Io.File,
    writer_lock_file: ?std.Io.File = null,
    /// The embedded connection layer holds the path lease around complete calls.
    externally_locked: bool = false,
    reader_coordinator: ?*ReaderCoordinator = null,
    reader_fence: ?*ReaderCoordinator.Fence = null,
    /// This NativeFile's reference to the process-wide, per-inode lock
    /// registry entry for `path` (see inode_lock.zig) -- established once,
    /// at open/create time, and released exactly once, in `close()`. Every
    /// in-process acquisition of the epoch-reuse (exclusive) or
    /// reader-fence (shared) lock on the underlying file goes through this
    /// entry, which is what lets independent NativeFile/Store instances on
    /// the same path (as `externally_locked` explicitly allows) coordinate
    /// through one kernel fd instead of self-conflicting across their own.
    ///
    /// Atomic, not a plain field: `replaceWithPreparedGeneration` (an
    /// atomic generation swap -- vacuum, restore) redirects this to a
    /// different entry mid-lifetime, and a concurrent foreground commit on
    /// this same NativeFile can read it at any time (this codebase
    /// deliberately allows a commit to interleave with another's released
    /// "sync window" -- see that comment in `pageAllocatorFromFreeMapWithProof`).
    /// A plain read during the swap could see a torn/mixed value; an
    /// atomic load always sees a whole, valid entry pointer, either the
    /// pre- or post-swap one. Whichever one a given acquire sees, the
    /// `Handle` it gets back captures that exact entry, so a concurrent
    /// swap can only ever affect which entry a *future* acquire resolves
    /// to -- never which one an in-flight `Handle` releases against.
    inode_lock_ref: std.atomic.Value(?*inode_lock.Entry) = .init(null),
    /// The registry handle backing an outstanding `reader_fence`
    /// (`acquireReaderFence`/`captureFullReadSnapshot`), released in
    /// `releaseReaderFence` or, defensively, in `close()`.
    reader_fence_lock: ?inode_lock.Handle = null,
    /// Set by `captureFullReadSnapshot` on the *returned* snapshot reader,
    /// and by `openWithRuntime` for every read-only, non-`internal_reader`
    /// open, when it registers a pin in `inode_lock.Entry.reader_pins`
    /// (the in-process reader-pin registry -- see that field's own doc
    /// comment) protecting the checkpoint this reader was opened at (or,
    /// for `captureFullReadSnapshot`, the checkpoint the *writer* that
    /// captured it was already on). Released in `close()`; `null` for a
    /// write open, an `internal_reader` probe, or the live writer file
    /// that called `captureFullReadSnapshot` itself (the pin lives on the
    /// returned snapshot reader, not on `self`, in that case).
    reader_pin_entry: ?*inode_lock.Entry = null,
    reader_pin_sequence: u64 = 0,
    /// The overlay mark `M` pinned in `SharedRedoOverlay.pins` (via
    /// `redo.shared.pinUnlessReclaimed`) by `openWithRuntime` for every
    /// read-only, non-`internal_reader` open on a redo-log file, mirroring
    /// `reader_pin_entry`/`reader_pin_sequence`'s own role for the
    /// page-reuse side of the same (C, M) pin pair (`ReadView.open`'s own
    /// doc comment). `null` for a legacy (non-redo) file, a write open, or
    /// an `internal_reader` probe. Must be released (`redo.shared.unpin`)
    /// before `close()` tears down `self.redo` below.
    open_time_overlay_pin_mark: ?u64 = null,
    /// §9.3b: this instance's own claimed reader slot in the shared lock
    /// region, used only by `refreshCrossProcessRedoOverlay` to pin the
    /// `commit_sequence` this process has safely caught up to in another
    /// process's redo log -- distinct from `reader_fence` (page-reuse
    /// retention, pinned at a checkpoint sequence, one slot already
    /// spoken for by the plain-reader-open/`acquireReaderFence`/
    /// `captureFullReadSnapshot` triad). Claimed lazily on first refresh,
    /// released in `close()`.
    cross_process_redo_reader_slot: ?u32 = null,
    reader_window_depth: usize = 0,
    reader_window_lock: ?inode_lock.Handle = null,
    /// The reuse frontier `acquireEpochReuseLock` last read directly from
    /// the shared lock region's reader table (`Region.minimumPinnedSequence`
    /// /`minimumMetadataPinnedSequence`) -- a plain in-memory atomic scan,
    /// visible across every process mapping the region, not just this one.
    /// Replaces the old per-commit `reader_epochs.zig` namespace-directory
    /// scan (and the cache that amortized its `open`/`stat` cost) entirely:
    /// the region never needs that caching layer, since the scan itself
    /// never touches the filesystem.
    epoch_window: ?ReaderCoordinator.Frontier = null,
    minimum_metadata_reader_sequence: ?u64 = null,
    reader_window_previous_metadata_frontier: ?u64 = null,
    reader_window_previous_frontier: ?u64 = null,
    header: Header,
    header_fingerprint_cache: HeaderFingerprintCache = .{},
    transaction_header: ?Header = null,
    /// Debug-only overlap backstop: an atomic count of how many
    /// `beginTransaction` calls on this instance are currently open
    /// (incremented in `debugEnterCommitSpan`, decremented in
    /// `debugExitCommitSpan`) -- deliberately wider than
    /// `transaction_header != null`, which `commitTransactionWithDurability`
    /// clears early (right after `flushTransactionWrites`, well before
    /// `publishCheckpoint`/the durability barrier) so that a *different*
    /// `NativeFile`'s own `beginTransaction` can overlap *this* commit's
    /// still-in-flight publish under WS2 pipelining (see `docstore.zig`'s
    /// `lockStore`/`lockStoreExclusive`/`commit_in_sync`). A non-nested
    /// `beginTransaction` reaching this same instance while the count is
    /// already non-zero is always a caller-side serialization failure (the
    /// writer lease or group-commit queue failed to exclude a second
    /// commit on this exact file), never a legitimate overlap -- WS2
    /// pipelining only ever overlaps two *different* `NativeFile`
    /// instances' spans, not two on the same one.
    ///
    /// The three sanctioned same-call-stack reentries -- `checkpointRedoLog`
    /// opening its own nested transaction from inside
    /// `commitTransactionWithDurability`'s deferred-publication branch or
    /// `publishCheckpoint`'s own redo branch, and
    /// `commitTransactionWithDurability`'s own tail call into
    /// `maybeAutoCheckpointRedoLog` (which can also reach `checkpointRedoLog`)
    /// -- are each wrapped at their call site with
    /// `commit_span_nested_allowance`, not detected here by inference. An
    /// earlier version of this guard tried to infer "is this call nested"
    /// from thread identity (same OS thread as the current holder = assume
    /// reentry) or from `redo.checkpointing` (the codebase's own "this call
    /// stack is building a real checkpoint" signal); both were wrong.
    /// Thread identity is wrong because this codebase's own `std.Io.Threaded`
    /// runtime does not guarantee one logical task per OS thread -- a
    /// worker thread can run two unrelated tasks back to back, so
    /// "same thread id" does not mean "same call stack", and a second,
    /// genuinely unrelated caller can be misread as a reentrant one.
    /// `redo.checkpointing` is wrong because it is `true` for *both* the
    /// genuinely nested call sites above *and* a wholly standalone one
    /// (`docstore.zig`'s `maybeCheckpointRedoLogOnIdleTurn`, which calls
    /// `checkpointRedoLog` fresh, under its own `lockStoreExclusive`, with
    /// no outer transaction open at all) -- so keying off it silently
    /// passed the exact overlap this guard exists to catch. Explicit,
    /// call-site-driven signaling has no such gap: it never has to guess.
    commit_span_depth: if (debug_commit_span_tracking) std.atomic.Value(usize) else void = if (debug_commit_span_tracking) .init(0) else {},
    /// Set (incremented before, decremented after, always paired) by a call
    /// site that is *itself* already inside an open commit span and is
    /// about to make a synchronous, same-call-stack nested call that will
    /// re-enter `beginTransaction` on this exact instance -- see
    /// `commit_span_depth`'s own doc comment for the three sites. Plain
    /// (non-atomic): by construction, only the call stack that already
    /// holds the span can ever reach one of these sites, so there is never
    /// concurrent access to this field to guard against -- that is the
    /// whole difference between this and `commit_span_depth`.
    commit_span_nested_allowance: if (debug_commit_span_tracking) usize else void = if (debug_commit_span_tracking) 0 else {},
    // Lease-only metadata transactions may append without proving free-page
    // reuse. General mutations still validate before any physical reuse.
    artifact_lease_transaction: bool = false,
    /// Set (only) by the capi Owner/Connection layer (lite_connection.zig)
    /// on the specific instances it subjects to the writer-lease admission
    /// gate: the Owner's own `current` live root, at both of the two
    /// places that are ever assigned (`Owner.create`'s initial open and
    /// the generation-swap in its "replace" helper), and `Owner
    /// .refreshMaintenanceSnapshot`'s detached snapshot, at the one place
    /// it creates a new one. Gates the `active_writer` backstop in
    /// `publishCheckpoint`/`beginTransaction` below: countless legitimate
    /// `NativeFile` publishers never go through that gate at all --
    /// recovery/replay at open, bare docstore.zig unit tests, backend.zig's
    /// vector-block storage, a borrowed index writer's
    /// `adoptIndexPublicationHeader` rebind, a vacuum-prepared image -- and
    /// checking `active_writer` against any of them is a guaranteed false
    /// positive, since nothing ever claims it on their behalf. `false` by
    /// default: only a file this layer explicitly marks is ever subject to
    /// the check.
    lease_managed: bool = false,
    /// Set by `beginTransaction` (only when `lease_managed`) right after it
    /// claims `inode_lock.Entry.active_writer`; consumed (checked, then
    /// cleared) by the one `publishCheckpoint` call that actually ends
    /// this transaction, and cleared without being checked by
    /// `abortTransaction`/at the end of `commitTransactionWithDurability`
    /// on every other path (the deferred-publication branch, and the
    /// "not changed" branch's plain `sync()`, neither of which call
    /// `publishCheckpoint` for this transaction's own commit at all).
    /// Scopes the backstop to only the commit that follows a
    /// `beginTransaction` on *this* instance: `publishCheckpoint` is also
    /// reached directly from `sync()` to flush an already-pending
    /// `durable_header` with no transaction open at all, and
    /// `active_writer` can otherwise still hold a stale, unrelated claim
    /// that call never itself contested.
    claimed_active_writer: bool = false,
    /// Native connection owners carry checked allocator ownership across live
    /// commits. Primitives retain explicit certification and proof semantics.
    allocator_certificate_on_commit: bool = false,
    allocator_certificate_staged: bool = false,
    /// A previously checked cache may follow a bounded journal suffix, but
    /// cannot enable reuse until the new checkpoint certificate matches.
    allocator_rebase_header: ?Header = null,
    allocator_ledger_rebased: bool = false,
    allocator_work: @import("reclamation.zig").AllocatorWork = .{},
    transaction_writes: ?*TransactionWrites = null,
    /// Bumped each time `transactionWrites` allocates a new instance (a
    /// flush destroys the old one). A `TransactionSavepoint` records the
    /// generation of the instance live when it was taken, so a savepoint
    /// can tell "no flush since" from "a flush recreated the write set,
    /// possibly at the same address" without an ABA hazard on the pointer.
    transaction_writes_generation: u64 = 0,
    flushing_transaction: bool = false,
    transaction_pages: ?*PageAllocator = null,
    /// §9 (redo + indexed reclamation): page ids `checkpointRedoLog`
    /// flushed from the overlay's page-shaped staging area (external
    /// value chains a diverting commit wrote without ever touching the
    /// ledger) for *this* transaction, consumed once by
    /// `flushTransactionWrites`'s own real (non-diverting) fold, right
    /// after its root loop and before `persistAllocator`. See
    /// `checkpointRedoLog`'s own doc comment for why this cannot simply
    /// be retained inline where the bytes are flushed: `putDocumentBatch`/
    /// `putCatalogBatchForRoot`, called from inside an open transaction,
    /// only *stage* into `TransactionWrites.maps` there -- the real
    /// `IndexEditor` pass (and the `retainRecord` call that retains each
    /// chain's own *root* page) does not run until `flushTransactionWrites`
    /// processes those maps later. Owned by `checkpointRedoLog`; cleared
    /// (and freed) by whichever of the two reaches it first.
    redo_fold_retain_pending: ?[]const u64 = null,
    /// perf/lwa-orphan-pages: page ids `checkpointRedoLog` found owned by
    /// a version its own fold just discovered superseded or deleted,
    /// strictly within the window just folded -- see
    /// `redo_overlay.SharedRedoOverlay.SupersededChain`'s own doc comment
    /// for the orphaned-page-retention bug this fixes. Consumed once by
    /// `flushTransactionWrites`'s own real (non-diverting) fold, the same
    /// way and at the same point as `redo_fold_retain_pending` -- each
    /// chain this names gets retained (idempotently: harmless if
    /// `redo_fold_retain_pending`'s own sweep, or a surviving head's own
    /// write, already retained some of its pages) and then immediately
    /// queued for retirement, exactly like a normal, non-redo overwrite's
    /// `IndexEditor` replace already does inline for the record it
    /// displaces. Owned by `checkpointRedoLog`; cleared (and freed) by
    /// whichever of the two reaches it first.
    redo_fold_retire_pending: ?[]const redo_overlay.SharedRedoOverlay.SupersededChain = null,
    /// Accumulates (page_id, crc) for every data page `PageWriteBatch`
    /// physically writes since the *last durable checkpoint publish* --
    /// across staging (`stageMutation`'s eager external-value writes,
    /// which happen well before any commit function runs), every
    /// intervening non-durable (`commitTransactionWithDurability(false)`)
    /// commit, and the eventual durable commit's own writes. A non-durable
    /// commit is only made durable by a later durable commit's single sync
    /// barrier, so that barrier's manifest must cover everything written
    /// since the last durable point, not just its own commit's writes, or
    /// a torn page from an earlier non-durable commit would verify as
    /// fine. Reset only inside `publishCheckpoint`, right after a durable
    /// publish actually succeeds (regardless of whether it used a manifest
    /// or fell back to presynced): that is the new "last durable
    /// checkpoint" baseline, so tracking restarts from there.
    manifest_builder: ManifestBuilder = .{},
    /// Set by `commitTransactionWithDurability` immediately before calling
    /// `flushTransactionWrites`, true only for a commit that might end up
    /// durably publishing (not deferred, not no_sync, manifest commits
    /// enabled): `flushTransactionWrites` reserves `manifest_builder`'s
    /// page under this flag, since only the commit that will actually call
    /// `tryBuildCommitManifest` needs one reserved.
    allow_manifest_reservation: bool = false,
    /// Per-instance override of the historically compile-time
    /// `manifest_commits_enabled` constant -- see that name's own doc
    /// comment just above its (former) declaration. Every file defaults
    /// this to `true`, identical to the old constant; only a redo-log
    /// file (`redo` below) ever sets it `false`, since the v8/v9 manifest
    /// this flag gates is exactly what the redo log replaces
    /// (docs/design/lite-performance/lite-single-commit-write-path.md §9).
    manifest_commits_enabled: bool = true,
    /// Non-null only for a file created with a redo-log region
    /// (`enableRedoLog`) or opened from one (`recoverRedoLog`). See
    /// `RedoCommitState`'s own doc comment.
    redo: ?RedoCommitState = null,
    /// Scopes `PageWriteBatch.flushCount`'s page-shaped diverting exception
    /// (an external value chain staged through `pageAllocatorForDivertingCommit`
    /// during an ordinary transactional commit -- `RedoCommitState`'s own
    /// doc comment) to catalog value writes specifically, never document
    /// ones. Set transiently, for the duration of the synchronous call,
    /// by every catalog-exclusive value-writing entry point
    /// (`writeCatalogValue`, `CatalogAppendState.append`/`finish`,
    /// `putIndexCatalogRecordFromFile`) -- never by `writeDocumentValue` or
    /// anything document-shaped, which keep staging through
    /// `redo.appendPending` (buffered until this commit's own
    /// `appendRecord`/overflow check) exactly as before. A catalog value's
    /// own private-flush chunking (`CatalogDeleteBatch`, the 64-key subtree
    /// delete batches) only bounds the staged *mutation*, never a single
    /// large external value underneath one of its puts, so without this a
    /// big atomic import's own page-shaped bytes would buffer in full
    /// (`redo.pending`, plus the overlay's own untracked copy) regardless
    /// of how many small commits the caller's own code paths it through --
    /// unbounded by the caller's own chunking. Writing these pages for
    /// real, immediately, is always safe (see `flushCount`'s own doc
    /// comment on this), and a document's own value chain has no
    /// comparable unbounded-accumulation path to begin with (one document
    /// write is one external value, written once, not staged incrementally
    /// across many private flushes the way a catalog append is) --
    /// changing its behavior too would only risk the redo-log-core
    /// invariants other tests (`check()`'s own redo-aware tolerance for
    /// page_count running ahead of physical size, vacuum/cross-process
    /// recovery) already depend on, for no corresponding benefit.
    direct_value_pages: bool = false,
    durable_header: ?Header = null,
    last_synced_header: ?Header = null,
    change_capture: ?*ChangeCapture = null,
    read_only: bool = false,
    no_sync: bool = false,
    /// When set, durability barriers (`syncIfRequired`) call
    /// `antfly_platform.filesystem.syncData` directly on the raw handle
    /// instead of `self.file.sync(io)`: `fdatasync` on Linux instead of
    /// `fsync`, skipping metadata the data does not need to be retrievable.
    /// Null (the default) keeps going through the `std.Io` vtable, which
    /// every backend (including an evented/fiber scheduler) already knows
    /// how to run without blocking its reactor. Set this only when the
    /// runtime backing this file's `Io` is known to run blocking ops
    /// synchronously on the calling thread (e.g. the default `Threaded`
    /// backend embedded Lite normally opens with), since this bypasses the
    /// vtable (and its cancellation support) entirely.
    durability_policy: ?antfly_platform.filesystem.DurabilityPolicy = null,
    // A publication that fails after it may have started writing the slot
    // may leave disk ahead of header -- this means exactly that: a
    // publication *failed* in a way that leaves the relationship between
    // disk and this in-memory header unknown. It is set only in
    // `publishCheckpoint`'s own failure path (and by an injected test
    // fault), never proactively before an attempt: an ordinary, still
    // in-flight publish that hasn't failed is not "uncertain", and must
    // not be treated as needing reconciliation by a concurrent observer of
    // this same NativeFile (see `publication_in_flight` for that case).
    // Do not elide a subsequent write based on the old in-memory checkpoint
    // while this is set.
    checkpoint_publication_uncertain: bool = false,
    /// True for the entire span of one `publishCheckpoint` call past its
    /// point of no return (the slot write/sync attempt), regardless of how
    /// it ends -- success, a reconciled failure, or a latched one. Concurrent
    /// code (e.g. a maintenance pass, an owner refresh) that only needs to
    /// know "a publish is in progress, wait for it" belongs on this flag,
    /// never on `checkpoint_publication_uncertain`: that one means failure,
    /// this one means "in flight", and conflating them is exactly what let
    /// a benign in-flight commit be mistaken for one needing reconciliation.
    publication_in_flight: bool = false,
    /// The checkpoint `publishCheckpoint` was writing into `uncertain_slot`
    /// when the I/O that set `checkpoint_publication_uncertain` failed.
    /// `reconcilePublicationUncertainty` compares this against what is
    /// actually on disk to resolve the latch in-process, without a
    /// close+reopen. Captured before the risky write (unconditionally, same
    /// as `publication_in_flight`) so it is available the moment a failure
    /// does set the latch, and cleared together with it whenever the latch
    /// clears (on success in `publishCheckpoint`, or by reconciliation).
    uncertain_checkpoint: ?CheckpointSlot = null,
    uncertain_slot: ?u8 = null,
    // WS2's `sync_lock_hooks` field was removed: it let a commit that never
    // installed its own hooks (reclaim's `reclaimPagesImpl`, `sync()`,
    // `publishBareCommit`) silently observe and act on whatever *another*
    // commit happened to have installed on this same `NativeFile`, since
    // the field was shared mutable state rather than scoped to one call.
    // That is how a reclaim/maintenance commit running concurrently with a
    // foreground group's fsync ended up releasing and reacquiring the
    // group leader's lock on its behalf -- an extra unlock that skips a
    // ticket (`PublicationMutex` in `docstore.zig`), and a `defer` in the
    // leader's own call that can observe the field already cleared by the
    // *other* caller's matching commit and skip reacquiring entirely. Hooks
    // are now passed explicitly as a parameter to the one call that may
    // use them (`commitTransactionWithDurability`, threaded through to its
    // `syncIfRequired`/`publishCheckpoint`), captured on that call's own
    // stack, so two concurrent commits on the same file can never see or
    // act on each other's hooks. See `SyncLockHooks`'s doc comment for what
    // the hooks themselves still do.
    /// Owner admission budget. Reuse remains permitted at the file-size cap.
    /// Null means unlimited; the owner subtracts retired/workspace capacity.
    max_file_bytes: ?u64 = null,
    /// Foreground owners preserve allocator workspace inside the hard limit.
    /// Private rewrite images use their separately admitted workspace instead.
    reserve_retirement_capacity: bool = false,
    maintenance_publication: bool = false,
    /// Committed reclamation activity, independent of physical file growth.
    retirement_activity_bytes: u64 = 0,
    vacuum_workspace_limit: ?u64 = null,
    vacuum_target_indexed: bool = false,
    ledger: ?*allocator_v4.State = null,
    minimum_reader_sequence: ?u64 = null,
    reader_frontier: ?*const std.atomic.Value(u64) = null,
    publication_observer: ?struct { context: *anyopaque, notify: *const fn (*anyopaque, CheckpointSlot, bool) void } = null,
    secondary_page_cache: ?*PageCache = null,
    retirement_work_pages: usize = 128,
    allocator_cancel_token: ?*const maintenance.CancelToken = null,
    private_retirement_epoch: ?u64 = null,
    incremental_checkpoints: bool = false,
    page_cache_enabled: std.atomic.Value(bool) = .init(true),
    /// Maintenance readers and private images retain navigation pages only.
    page_cache_policy: enum { normal, metadata_only } = .normal,
    page_cache: PageCache = .{},
    namespace_directory_cache: NamespaceDirectory = .empty,
    namespace_directory_cache_root: u64 = std.math.maxInt(u64),
    namespace_directory_delta_depth: u16 = 0,
    /// While non-zero, page reads bypass the page cache and hit disk.
    /// Integrity checks hold this so they verify on-disk state rather than
    /// cached copies.
    page_cache_bypass: std.atomic.Value(u32) = .init(0),
    test_fail_vacuum_after_adoption: bool = false,
    test_fail_generation_directory_sync: bool = false,
    /// Set once the on-disk free map has been cross-checked against every
    /// valid checkpoint slot (including the crash-safety fallback slot) for
    /// this open file handle. That full-database reachability scan is only
    /// needed to catch corruption present when the file was opened (or
    /// written to out of band); this process's own commits can only ever
    /// consume pages that a prior, already-verified free map declared free,
    /// so re-running the scan on every single mutation is unnecessary and,
    /// for large stores, quadratic in the number of commits. `check()` (via
    /// `validateReachableFreeMap`) always re-verifies regardless of this
    /// flag, for explicit integrity audits.
    free_pages_verified: bool = false,
    /// Connection owners verify on their detached lane. Until completion,
    /// authored commits append and never consume an unproven free page.
    defer_allocator_verification: bool = false,
    /// Only locally authored append-only descendants can inherit this proof.
    /// Rebinding an externally published header or inode clears the lineage.
    allocator_verification_base: ?Header = null,
    allocator_proof_window: ?*AllocatorProofWindow = null,
    // Structural scaling assertions count page operations, independent of
    // filesystem speed and cache warmth. No counters exist in production.
    // Exact backing-file page reads, after shared and cursor-local caches.
    // These count read operations/bytes, not storage-device cache misses.
    test_backing_read_calls: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_backing_read_bytes: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_value_read_bytes: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_value_cache_borrowed_bytes: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_value_cache_copy_bytes: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_value_read_calls: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_cancel_on_read: if (builtin.is_test) ?*maintenance.CancelToken else void = if (builtin.is_test) null else {},
    test_page_reads: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    /// §9.3a: `readBackingPages`'s overlay consult (below) returns a fresh,
    /// transient `dupe` for each physical page that is still staged in the
    /// redo log overlay (not yet folded by a checkpoint) -- correct, but
    /// unlike a page already folded onto disk, it is never cached, so it
    /// costs one allocation on *every* read of that page, not just the
    /// first. Counted separately so a test asserting "a retry over an
    /// unchanged read allocates nothing new" can account for this
    /// legitimate, bounded cost instead of either ignoring it or wrongly
    /// treating it as a regression (see the "retry after page cache
    /// eviction" test in docstore.zig).
    test_redo_page_overlay_hits: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_index_view_hits: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_index_comparisons: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_page_writes: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},

    test_page_write_calls: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    test_page_write_fail_after: if (builtin.is_test) ?usize else void = if (builtin.is_test) null else {},
    /// `test_page_write_fail_after`'s own counterpart for a catalog
    /// mutation that diverts purely logically (no page-shaped content at
    /// all -- a small put/delete under the redo log's default diversion,
    /// `flushTransactionWrites`'s own diverting branch). A fault-injection
    /// test written against the legacy B-tree rebuild could rely on
    /// `test_page_write_fail_after` firing partway through a batch of real
    /// page writes; under full logical diversion that batch may never
    /// touch a real page at all, so this counts/fails on logical mutations
    /// instead. Checked in `flushTransactionWrites`'s diverting loop, once
    /// per mutation.
    test_logical_write_fail_after: if (builtin.is_test) ?usize else void = if (builtin.is_test) null else {},
    /// `test_page_writes`'s own counterpart for `test_logical_write_fail_after`.
    test_logical_mutations: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    /// Counts durability barriers (`syncIfRequired`'s underlying `file.sync`
    /// calls), independent of filesystem speed. Used to assert syncs/commit.
    test_sync_calls: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    /// Artificially slows every durability barrier by this many
    /// nanoseconds (0: no delay), via a raw `nanosleep` -- not `Io.sleep`,
    /// so it never depends on whatever `Io` scheduler happens to be live
    /// and cannot interact with a concurrent `Io.concurrent` task the way
    /// that caused a hang elsewhere. Set on a real filesystem (never
    /// `no_sync`) to widen the window a concurrent writer's own admission
    /// and staging has to land in the same group before this one's
    /// `syncIfRequired` returns, for tests that need to tell "no group
    /// formed because nothing else was ready yet" apart from "no group
    /// formed because something still serializes writers upstream of the
    /// fsync". The lock `sync_lock_hooks` already releases for the real
    /// `fileSync` call is held released across this delay too (see
    /// `syncIfRequired`), exactly like the real syscall it is standing in
    /// front of.
    test_sync_delay_ns: if (builtin.is_test) @import("antfly_platform").atomic.Value(u64) else void = if (builtin.is_test) .init(0) else {},
    /// Fails the next checkpoint publication inside its uncertain window
    /// (after the flag is set, before the slot write), then disarms.
    test_fail_checkpoint_publication: if (builtin.is_test) ?anyerror else void = if (builtin.is_test) null else {},
    /// Fails the redo log's own durability barrier (`RedoCommitState.writer
    /// .sync()`) on the next redo-log durable commit, but only *after* that
    /// commit's own `appendRecord` has already succeeded -- unlike
    /// `test_fail_checkpoint_publication`, which fires before `appendRecord`
    /// is ever reached. Exercises the gap `redo_log.Writer.rollbackTo`
    /// closes: a record whose append succeeded but whose own sync failed
    /// must not leave the writer's physical cursor permanently ahead of
    /// the logical state every later commit computes its next sequence
    /// from. Disarms itself after firing once.
    test_fail_redo_sync: if (builtin.is_test) ?anyerror else void = if (builtin.is_test) null else {},
    /// Fails the very next `checkpointRedoLog` call outright (before it
    /// touches anything), then disarms. For exercising a caller's own
    /// error handling around that call directly -- e.g. docstore.zig's
    /// `maybeCheckpointRedoLogOnIdleTurn`, which the real
    /// `error.OutcomeUnknown`-from-a-close-during-the-crash-sweep case
    /// only reaches occasionally -- without needing to reproduce that
    /// exact crash timing by hand.
    test_fail_checkpoint_redo_log: if (builtin.is_test) ?anyerror else void = if (builtin.is_test) null else {},
    /// Test-only: makes `checkpointRedoLog` stop right after its new slot
    /// is durable, skipping the log-zeroing step, to exercise that known
    /// gap's exact window (see that function's own doc comment) instead
    /// of a hand-rolled approximation of it.
    test_skip_redo_log_zero: if (builtin.is_test) bool else void = if (builtin.is_test) false else {},
    /// §9.7f: the caller's own *configured* `reclamation.max_storage_bytes`
    /// (`0` meaning unbounded) -- deliberately not `max_file_bytes`, which
    /// also folds in transient disk-headroom/workspace adjustments
    /// (`docstore.Store.refreshAdmissionAssumeLocked`) that should never
    /// drive a log-capacity resize. Set once at creation
    /// (`docstore.Store.createWithOptions`) and refreshed on every commit
    /// alongside `max_file_bytes`, so `checkpointRedoLog`'s own fold
    /// (`maybeShrinkRedoLogCapacity`) always sees the budget as the caller
    /// most recently configured it, not just the one in effect at creation.
    redo_log_budget_bytes: u64 = 0,

    pub fn open(allocator: Allocator, path: []const u8, read_only: bool) !NativeFile {
        return try openWithOptions(allocator, path, .{ .read_only = read_only });
    }

    pub fn openWithOptions(allocator: Allocator, path: []const u8, opts: OpenOptions) !NativeFile {
        var io_impl = threaded_io_limits.initService(allocator);
        errdefer io_impl.deinit();
        return try openWithRuntime(allocator, path, opts, io_impl, null);
    }

    /// Opens a Lite file using a caller-owned std.Io runtime. The runtime must
    /// outlive the returned file. No native thread or host-I/O escape is
    /// created by this path.
    pub fn openWithIo(allocator: Allocator, io: std.Io, path: []const u8, opts: OpenOptions) !NativeFile {
        return try openWithRuntime(allocator, path, opts, undefined, io);
    }

    fn openWithRuntime(
        allocator: Allocator,
        path: []const u8,
        opts: OpenOptions,
        io_impl: std.Io.Threaded,
        borrowed_io: ?std.Io,
    ) !NativeFile {
        var owned_io_impl = io_impl;
        const io = borrowed_io orelse owned_io_impl.io();

        const owned_path = try allocator.dupe(u8, path);
        errdefer allocator.free(owned_path);

        var writer_lock_file: ?std.Io.File = null;
        if (!opts.read_only and !opts.externally_locked) {
            const writer_lock = try acquireWriterLock(allocator, io, path);
            writer_lock_file = writer_lock.file;
        }
        errdefer if (writer_lock_file) |lock_file| lock_file.close(io);

        const inode_entry = try inode_lock.open(io, path);
        errdefer inode_lock.unref(inode_entry, io);
        // Eagerly establish (or attach to an already-cached) this inode's
        // shared lock region here, at open time, instead of leaving its
        // one-time create/validate cost (`Region.openSized`) to land
        // lazily inside whichever call happens to be first to need it --
        // which, for a writer, can be the first page-reusing commit
        // (`acquireEpochReuseLock` -> `regionForInode`), landing region
        // setup work inside a commit's own fault window. Every error is
        // swallowed exactly like `regionForInode` already does: a region
        // that can't be set up here just means every later caller's own
        // region-mode fallback engages instead, never a reason to fail
        // this open.
        _ = inode_lock.ensureRegion(inode_entry, io) catch {};

        // Every read-only open used to ask `openDataFile` to take its
        // `.shared` kernel lock atomically at open, on its own fd, for
        // `.reader` mode (a plain reader with neither `internal_reader`
        // nor `externally_locked` set). That self-conflicts the same way
        // `acquireReaderFence` did against another NativeFile's warm
        // `.exclusive` registry hold on this inode in this process.
        // `.internal_reader` already means "no lock at open" to
        // `openDataFile`; request that uniformly for every read-only open
        // now, and acquire the registry's `.shared` grant explicitly for
        // a plain reader below instead.
        const plain_reader = opts.read_only and !opts.internal_reader and !opts.externally_locked;
        const opened_file = try openDataFile(io, path, if (opts.read_only) .internal_reader else .writer, opts.wait_for_reader_lock);
        const file = opened_file.file;
        errdefer file.close(io);

        var header_bytes: [header_size]u8 = undefined;
        try readHeaderExactAt(file, io, &header_bytes);
        var header = try decodeHeader(&header_bytes);
        const file_size = (try file.stat(io)).size;
        header.checkpoints = loadCheckpointSlots(file, io, header.page_size, file_size);
        // Only a writer (not a read-only probe) may truncate a rejected
        // fallback candidate's tail away.
        const recovered = try recoverActiveCheckpoint(file, io, header, file_size, !opts.read_only);
        header.active_checkpoint = recovered.index;

        var result = NativeFile{
            .allocator = allocator,
            .io_impl = owned_io_impl,
            .borrowed_io = borrowed_io,
            .path = owned_path,
            .file = file,
            .writer_lock_file = writer_lock_file,
            .inode_lock_ref = .init(inode_entry),
            .externally_locked = opts.externally_locked,
            .reader_coordinator = opts.reader_coordinator,
            .header = header,
            .read_only = opts.read_only,
            .no_sync = opts.no_sync,
            .page_cache_enabled = .init(true),
            // Only when this open built its own Threaded runtime (not
            // openWithIo, whose caller's Io might be a test/sim wrapper or
            // an evented backend): see `durability_policy`'s doc.
            .durability_policy = if (borrowed_io == null)
                (if (opts.full_fsync) .full_fsync else .default)
            else
                null,
        };
        // §9.5: replay the redo log into a fresh in-memory overlay before
        // anything else touches `result.header`/`result.manifest_commits_enabled`
        // below. Every production opener of a redo-log file reaches this.
        if (header.redo_log_capacity != 0) try result.recoverRedoLog(allocator, io);
        // `opts.pin_read_checkpoint` (see its own doc comment for why
        // this is opt-in, set only by `docstore.Store.openWithOptions`):
        // pin the checkpoint this open just recovered before this
        // function returns, so a caller like backend.zig's
        // `initNativeSingleFile` -- which reads straight through
        // `self.header`/`self.redo` the instant `openWithOptions`/
        // `openWithIo` returns, with no `Txn`/`ReadView` of its own in
        // between -- cannot land between "checkpoint recovered" and
        // "something protects it," the exact gap a concurrent writer's
        // own background fold can win: reclaiming the checkpoint's pages
        // (or dropping its still-unfolded redo-log content) before this
        // open's first real read ever runs.
        //
        // Use exactly the primitive `ReadView.open`/`Store.
        // pinInitializedReadGeneration` already use for this, inlined
        // (not `ReadView` itself: storing a `ReadView` whose own `file`
        // field points back at this function's own `result` local would
        // leave a dangling self-reference once `result` is returned by
        // value) -- the overlay mark `M` first
        // (`redo.shared.pinUnlessReclaimed`, which checks whether `M` was
        // already reclaimed and pins it atomically under one lock, so no
        // fold can slip between the check and the pin), then the
        // checkpoint `C` (`inode_lock.pinReader`); released in reverse in
        // `close()`. `pinUnlessReclaimed` failing with
        // `error.ReadSnapshotReclaimed` propagates out of this open
        // entirely -- exactly the error `restore_staging.zig`'s own
        // reopen-and-retry loop (and any other caller that already
        // handles a stale-snapshot reopen) already expects.
        if (opts.pin_read_checkpoint) {
            std.debug.assert(opts.read_only);
            const checkpoint = result.activeCheckpoint();
            const mark = result.readMark(checkpoint);
            if (result.redo) |*redo| try redo.shared.pinUnlessReclaimed(std.heap.page_allocator, io, mark, checkpoint.commit_sequence);
            errdefer if (result.redo) |*redo| redo.shared.unpin(io, mark);
            if (result.inode_lock_ref.load(.acquire)) |entry| {
                try inode_lock.pinReader(entry, io, .{ .data = checkpoint.commit_sequence, .metadata = checkpoint.commit_sequence });
            }
            result.reader_pin_entry = result.inode_lock_ref.load(.acquire);
            result.reader_pin_sequence = checkpoint.commit_sequence;
            result.open_time_overlay_pin_mark = mark;
        }
        if (plain_reader) {
            // Register with the coordinator *before* acquiring the
            // registry grant below, so `blocks_exclusive` reflects whether
            // this reader actually ended up with a live region slot
            // (`Fence.hasEpoch()`, private to reader_coordinator.zig,
            // inlined below as the `slot` check) -- not just whether a
            // coordinator exists. A region unavailable or exhausted falls
            // back to an inode-only fence inside `registerFull` itself,
            // never a reason to fail this open, only to fence more
            // conservatively (the kernel lock below still blocks this
            // process's own exclusive reuse either way). A full-graph
            // plain reader always retains metadata regardless of
            // `indexed_reclamation` -- the region doesn't distinguish
            // the two, so there is no longer a reason to branch on it
            // here either.
            if (opts.reader_coordinator) |coordinator| {
                const region = inode_lock.ensureRegion(inode_entry, io) catch |err| region_blk: {
                    if (!inode_lock.isRegionUnusable(err)) return err;
                    break :region_blk null;
                };
                result.reader_fence = try coordinator.registerFull(file, region, (try file.stat(io)).inode, result.metadataReuseFrontier(), result.headerFingerprint());
            }
            errdefer if (result.reader_fence) |fence| opts.reader_coordinator.?.unregister(fence);
            const blocks_exclusive = if (result.reader_fence) |fence| fence.slot == null else true;
            // Preserves the kernel-level protection a plain reader held
            // for its whole lifetime before (`openDataFile`'s old atomic
            // `.shared` lock at open), now through the registry so it
            // cannot self-conflict against this same process's own
            // warm `.exclusive` hold on the same inode.
            // `opts.wait_for_reader_lock` is this call's only lever for
            // fail-fast vs. wait; preserve it exactly. (A fail-fast
            // acquire still retries briefly inside `inode_lock.acquire`
            // before surfacing `error.WouldBlock` -- see
            // `shared_fail_fast_retry_ns`.)
            result.reader_fence_lock = try inode_lock.acquire(inode_entry, io, .shared, opts.wait_for_reader_lock, blocks_exclusive, "openWithRuntime(plain_reader)");
        }
        errdefer if (result.reader_fence_lock) |handle| handle.release(io);
        if (opts.resource_manager) |manager| result.page_cache.attachResourceManager(manager);
        // See the matching comment in `createWithIo`.
        if (result.manifest_commits_enabled) try result.manifest_builder.reserveCapacity(allocator);
        return result;
    }

    pub fn create(allocator: Allocator, path: []const u8) !NativeFile {
        return try createWithMode(allocator, path, false, false, null, "", false, false);
    }

    pub fn createNew(allocator: Allocator, path: []const u8) !NativeFile {
        return try createWithMode(allocator, path, true, false, null, "", false, false);
    }

    pub fn createWithOptions(allocator: Allocator, path: []const u8, opts: CreateOptions) !NativeFile {
        return try createWithMode(allocator, path, opts.exclusive, opts.no_sync, opts.resource_manager, opts.writer_lock_marker, opts.indexed_reclamation, opts.full_fsync);
    }

    /// Creates a Lite file using a caller-owned std.Io runtime. The runtime
    /// must outlive the returned file.
    pub fn createWithIo(allocator: Allocator, io: std.Io, path: []const u8, opts: CreateOptions) !NativeFile {
        return try createWithRuntime(allocator, path, opts.exclusive, opts.no_sync, opts.resource_manager, opts.writer_lock_marker, undefined, io, opts.indexed_reclamation, opts.full_fsync);
    }

    /// Creates a file with a log-structured commit region (docs/design/
    /// lite-performance/lite-single-commit-write-path.md §9, build step
    /// (c)): bootstraps an ordinary file via `createWithIo`, then upgrades
    /// it in place via `enableRedoLog`. A separate entry point rather than
    /// a new `CreateOptions` field, deliberately: `CreateOptions` also
    /// feeds `createWithMode`/`createWithOptions`, whose positional-param
    /// plumbing into `createWithRuntime` has no slot for this, so a field
    /// that only one of several constructors actually honored would be a
    /// silent trap for a caller using any of the others. `opts.indexed_reclamation`
    /// may be `true` or `false`: combining indexed reclamation with a redo
    /// log is supported (§9, redo+indexed_reclamation work) -- `enableRedoLog`
    /// reserves the log region's page-id span starting after whatever
    /// pages `createWithIo`'s own bootstrap (indexed or not) already
    /// allocated, rather than assuming a fixed `reserved_header_pages`
    /// start.
    pub fn createWithRedoLog(allocator: Allocator, io: std.Io, path: []const u8, opts: CreateOptions, redo_log_capacity_bytes: u64) !NativeFile {
        var file = try createWithIo(allocator, io, path, opts);
        errdefer file.close();
        try file.enableRedoLog(redo_log_capacity_bytes);
        return file;
    }

    /// `createWithRedoLog`'s owned-io counterpart, for every caller that
    /// (like plain `createWithOptions`) has no `std.Io` of its own to lend
    /// and expects this file to own and manage its own runtime. Point 3's
    /// default-for-new-files policy (docstore.zig's `Store.createWithOptions`)
    /// needs this: it is reached whenever a caller passes no `opts.io`.
    pub fn createWithRedoLogOwnedIo(allocator: Allocator, path: []const u8, opts: CreateOptions, redo_log_capacity_bytes: u64) !NativeFile {
        var file = try createWithOptions(allocator, path, opts);
        errdefer file.close();
        try file.enableRedoLog(redo_log_capacity_bytes);
        return file;
    }

    /// Default log region size for a newly created redo-log file. Reserved
    /// eagerly, in full, at creation (`enableRedoLog`'s own `setLength`) --
    /// real physical file size from byte zero, not amortized content --
    /// so this is a direct, unconditional floor on every redo-log file's
    /// footprint, independent of how much (or little) it ever actually
    /// stores. 512 KiB holds several hundred small commits (the §9.8 gate
    /// target is ~1.2 KB durable bytes per primary-only write) before the
    /// synchronous 25%-remaining backpressure check
    /// (`maybeAutoCheckpointRedoLog`) forces a checkpoint -- comfortably
    /// more than the background idle/threshold checkpointer (§9.4b) needs
    /// to drain it under normal conditions -- while staying well under
    /// footprint bounds existing reclamation tests already assert on
    /// (e.g. "lite reclamation writable reopen services debt..." asserts
    /// peak file size stays under 2 MiB across repeated small-write/
    /// reclaim cycles; the first version of this constant, 8 MiB, blew
    /// through that on its own, before a single document was written).
    /// `docstore.Store.createWithOptions` scales this down further under
    /// a small configured `max_storage_bytes`, but never scales it up --
    /// no prior sizing precedent exists in this codebase to inherit, so
    /// this is a deliberately modest default, not a measured optimum.
    pub const default_redo_log_capacity_bytes: u64 = 512 * 1024;

    /// §9.7a/§9.7f: the redo-log capacity reservation a given configured
    /// `reclamation.max_storage_bytes` implies (`0` meaning unbounded).
    /// Shared by `docstore.Store.createWithOptions` (the reservation a
    /// newly-created file starts with) and `checkpointRedoLog`'s own
    /// fold (`maybeShrinkRedoLogCapacity`, which re-derives this on every
    /// fold so an *existing* file's reservation tracks a budget the
    /// caller lowers after creation too, not just the one in effect
    /// when the file was first created).
    pub fn redoLogCapacityForBudget(max_storage_bytes: u64) u64 {
        return if (max_storage_bytes != 0)
            @min(default_redo_log_capacity_bytes, @max(max_storage_bytes / 4, 64 * 1024))
        else
            default_redo_log_capacity_bytes;
    }

    /// §9.7f: the floor below which `docstore.Store.createWithOptions`
    /// defaults a newly-created file's `use_redo_log` to `false` (legacy
    /// commit path) instead of `true`, when the caller configures a
    /// `reclamation.max_storage_bytes` below this value and does not pass
    /// an explicit `use_redo_log`. Below this floor, the scaled redo-log
    /// reservation `docstore.zig` derives from the budget
    /// (`max(max_storage_bytes / 4, 64 KiB)`) is a disproportionately
    /// large slice of a small budget -- the 64 KiB absolute floor alone
    /// is 25% of a 256 KiB budget, rising past 50% well below that -- so
    /// legacy, which pays no such fixed reservation, is the better
    /// default there. At exactly this floor the scaled reservation is
    /// `max(4 MiB / 4, 64 KiB) = 1 MiB`, 25% of budget: the same
    /// steady-state ratio every larger bounded budget already pays, so
    /// this floor caps the *worst case* at that same ratio rather than
    /// a worse one. 8x the unscaled `default_redo_log_capacity_bytes`
    /// (512 KiB). An unbounded (`max_storage_bytes == 0`) store is
    /// unaffected either way: it always defaults to `true`. An explicit
    /// `use_redo_log`, `true` or `false`, always wins over this default,
    /// and the policy applies only at creation -- reopening an existing
    /// file never changes its mode.
    pub const use_redo_log_min_budget_bytes: u64 = 4 * 1024 * 1024;

    /// Upgrades a freshly bootstrapped file (indexed or not) to the
    /// redo-log format in place: reserves `redo_log_capacity_bytes`
    /// (rounded up to a whole number of pages) as a dedicated, zero-filled
    /// byte region immediately after whatever pages the bootstrap commit
    /// already covers (§9.1 -- in-file, not a sibling file; `reserved_header_pages`
    /// for a plain bootstrap, more for an indexed one, whose own bootstrap
    /// commit already allocated a free-map/ledger page -- using the
    /// checkpoint's own `page_count` rather than a hardcoded
    /// `reserved_header_pages` is what makes this correct for both),
    /// reserves that same range's page-id span so `PageAllocator` never
    /// hands any of it out as an ordinary page, and rewrites the header
    /// and both checkpoint slots to record the region (§9.5's format
    /// bump). Must only be called once, on a file with no transaction in
    /// flight and nothing durable yet beyond the bootstrap checkpoint --
    /// both slots are still identical at that point (an indexed bootstrap
    /// writes both explicitly; a plain one leaves slot 1 structurally
    /// invalid until the first real commit), so writing both here keeps
    /// them that way rather than leaving slot 1 stale with a `page_count`
    /// that doesn't reserve the log region, which a tie in recovery's slot
    /// selection could otherwise surface.
    ///
    /// For an indexed bootstrap specifically, bumping `page_count` alone
    /// is not enough: `allocator_v4.State`'s own root page cross-checks
    /// its `covered_pages` against the checkpoint's `page_count`
    /// (`decodeRoot`), so the two must be re-persisted together. Reserve
    /// the log region's page-id span through the real allocator instead
    /// -- the same `allocateFresh`/`reserveTail` path every ordinary
    /// commit's own fresh page allocation already uses -- so the
    /// ledger's coverage and the checkpoint's `page_count` land in
    /// lockstep, then let `persistAllocator` write the updated ledger the
    /// same way a real commit would. A plain (non-indexed) bootstrap has
    /// no such cross-check (`readFreePagesAlloc` tolerates a `page_count`
    /// ahead of the free-map page's own last-written content), so it
    /// keeps the simpler direct bump.
    fn enableRedoLog(self: *NativeFile, capacity_bytes: u64) !void {
        std.debug.assert(self.redo == null);
        const page_size: u64 = self.header.page_size;
        const log_pages = std.math.divCeil(u64, @max(capacity_bytes, 1), page_size) catch unreachable;
        const capacity = log_pages * page_size;
        const io = self.runtimeIo();

        var checkpoint = self.header.checkpoints[self.header.active_checkpoint];
        const offset = checkpoint.page_count * page_size;

        // Zero-filled, preallocated extent: `redo_log.replay`'s
        // end-of-region detection relies on untouched space reading back
        // as zero, exactly like every other page range this file grows.
        try self.file.setLength(io, offset + capacity);

        if (self.header.indexed_reclamation) {
            var pages = try self.pageAllocatorFromFreeMap(checkpoint);
            defer pages.deinit();
            for (0..log_pages) |_| _ = try pages.allocateFresh();
            checkpoint.free_map_root_page = try pages.allocate();
            checkpoint.page_count = pages.next_page_id;
            try pages.flush();
            // `persistAllocator` -> `State.preparePersist` retires the
            // ledger's previous root page (`state.root_page`, the old
            // free_map_root_page) stamped with `self.publicationEpoch()`
            // -- `self.header.checkpoints[active].commit_sequence + 1`,
            // read from `self.header` as it stands right now, since this
            // runs outside any transaction (`self.transaction_header` is
            // null). That epoch is a promise that the checkpoint which
            // ends up containing the retirement carries at least that
            // sequence number. Capture it before `self.header` changes
            // and stamp the checkpoint we are about to publish with it,
            // or `validateIndexedOwnership`'s "every pending retirement's
            // epoch is already covered by its own checkpoint" invariant
            // sees an epoch one past a checkpoint stuck at the old,
            // unchanged sequence (see "crash sweep: redo log checkpoint
            // with indexed reclamation retires pages").
            const epoch = self.publicationEpoch();
            try self.persistAllocator(&pages, &checkpoint);
            checkpoint.commit_sequence = epoch;
        } else {
            checkpoint.page_count += log_pages;
        }
        // perf/lwa-fold-boundary: this file has no redo log at all yet
        // (`self.redo == null`, asserted above) -- everything this
        // checkpoint names is real, physical content, so its own
        // `commit_sequence` is trivially the fold boundary too. Every
        // later real publish either advances this in lockstep
        // (`checkpointRedoLog`'s fold, `prepareVacuum`'s compaction) or
        // carries it forward unchanged; see `redo_folded_through`'s own
        // doc comment.
        checkpoint.redo_folded_through = checkpoint.commit_sequence;
        self.header.checkpoints = .{ checkpoint, checkpoint };
        self.header.redo_log_offset = offset;
        self.header.redo_log_capacity = capacity;

        // Both checkpoint slots and the header are written here, but
        // deliberately synced *once*, together: a crash before that one
        // sync leaves every write below unsynced, which `power_loss`
        // modeling in the crash-sim harness can drop in full, reverting
        // the file to exactly its pre-call state -- not a redo-log file
        // yet, safe to retry `enableRedoLog` again from scratch. Two
        // separate syncs (slots, then header) used to leave a window
        // where the checkpoint slot (and, for an indexed file, the
        // ledger `persistAllocator` just durably wrote) already reserves
        // the log region's page-id span while the header's own
        // `redo_log_capacity` is still durably 0 -- a combination
        // `check()`'s indexed-allocator validation has no way to
        // reconcile (nothing on disk says "these reserved-but-unreachable
        // pages belong to a redo log, not a hole"), surfacing as
        // `invalid_allocator` on exactly that crash window, reproducibly,
        // with no crash-sim power loss involved at all (see "crash sweep:
        // redo log checkpoint with indexed reclamation retires pages").
        var slot_buf: [max_page_size]u8 = undefined;
        const slot_page = slot_buf[0..page_size];
        encodeCheckpointSlotPage(slot_page, checkpoint);
        try self.file.writePositionalAll(io, slot_page, slotPhysicalPage(0) * page_size);
        try self.file.writePositionalAll(io, slot_page, slotPhysicalPage(1) * page_size);
        var header_buf: [header_size]u8 = undefined;
        encodeHeader(&header_buf, self.header);
        try self.file.writePositionalAll(io, &header_buf, 0);
        if (!self.no_sync) try self.file.sync(io);

        try self.attachFreshRedoState(io, offset, capacity, checkpoint.commit_sequence, checkpoint.commit_sequence);
    }

    /// Shared tail of `enableRedoLog` and `prepareVacuum`'s own redo-log
    /// reservation (§9's "the vacuumed generation should come out as a
    /// redo-log file too" -- `replaceWithPreparedGeneration` used to drop
    /// `self.redo` unconditionally on every vacuum, permanently reverting
    /// any redo-log store to the legacy commit path after its first
    /// vacuum): wires up `self.redo` for a file whose log region at
    /// `(offset, capacity)` is freshly reserved and has nothing in it yet
    /// to replay -- true both for a brand-new file (`enableRedoLog`'s own
    /// precondition) and for a vacuum's private, freshly-built compacted
    /// image (every live mutation already landed in the compacted tree
    /// itself via the ordinary copy pass, never through this fresh log).
    /// `self.inode_lock_ref` must already resolve to this file's own real
    /// registry entry (true for both callers: `enableRedoLog` runs after
    /// `createWithIo`/`createWithOptions`'s own bootstrap; `prepareVacuum`
    /// calls this on `prepared`, after `inode_lock.open` on its tmp path).
    fn attachFreshRedoState(self: *NativeFile, io: std.Io, offset: u64, capacity: u64, durable_sequence: u64, checkpoint_sequence: u64) !void {
        std.debug.assert(self.redo == null);
        self.manifest_commits_enabled = false;
        const entry = self.inode_lock_ref.load(.acquire) orelse return error.InvalidTransactionState;
        const shared = try inode_lock.ensureRedoOverlay(entry, io, {}, struct {
            // Nothing to replay: the shared overlay this populates stays
            // empty until the first commit appends to it.
            fn populate(_: void, _: *redo_overlay.SharedRedoOverlay, _: Allocator) anyerror!void {}
        }.populate);
        // `durable_sequence = checkpoint_sequence`: the same convention
        // `recoverRedoLog` uses when its own replay finds nothing past the
        // checkpoint (`outcome.last_sequence orelse checkpoint.commit_sequence`,
        // this file's own doc comment a few lines up) -- an empty log
        // attached to an already-durable checkpoint means that checkpoint's
        // sequence *is* the highest durable one so far, not zero. For
        // `enableRedoLog`'s brand-new-file caller this is a no-op either
        // way (the bootstrap checkpoint's own sequence is already the
        // zero/initial value); for `prepareVacuum`'s caller it is load-
        // bearing -- the vacuum's own checkpoint just became durable via a
        // real sync, not a log append, and `durableSequence()`/every
        // caller that compares an acknowledged write's sequence against it
        // (`Store.Ticket`'s own durability wait, cross-process readers via
        // `publishRedoLogState` below) must see that immediately, not
        // revert to "nothing is durable yet" the moment a vacuum lands.
        //
        // perf/lwa-fold-boundary: `durable_sequence` (the tip) and
        // `checkpoint_sequence` (the fold boundary) are no longer always
        // the same number, so they are now two separate parameters rather
        // than one reused for both. `enableRedoLog`'s own caller still
        // passes the same value for each (nothing has diverged yet for a
        // brand-new file), and a genuinely vacuum-compacted `prepared`
        // also still passes the same value for each (`prepareVacuum`'s
        // own compaction folds everything, so its new checkpoint's
        // `redo_folded_through == commit_sequence` by construction) --
        // but `replaceWithPreparedGeneration`'s own caller, reached from
        // this same shared tail, can legitimately pass two different
        // ones: if `prepared`'s inode already carries a shared overlay
        // with content durably logged past its own last real fold (not
        // true for an ordinary vacuum-built `prepared`, which is never
        // itself redo-attached before this call -- but true whenever a
        // caller hands this a `prepared` that was written to directly
        // under redo, as the inode's shared overlay persists past the
        // `self.redo = null` reset above, independent of whether this
        // function's own freshly-attached state's fold boundary covers
        // it), the tip must still name every such durably-logged
        // version (so `committedSequence()`/`readMark`-based reads keep
        // resolving them through that still-live overlay), while the
        // fold boundary must stay at the real value or a later
        // `checkpointRedoLog` on `self` would wrongly treat that
        // unfolded content as already covered (`redo_folded_through`'s
        // own doc comment).
        self.redo = RedoCommitState{ .writer = redo_log.Writer.init(self.file, io, offset, capacity), .shared = shared, .checkpoint_sequence = checkpoint_sequence, .durable_sequence = durable_sequence };
    }

    /// Replays the valid log prefix past the on-disk checkpoint's own
    /// `commit_sequence`, and wires up `self.redo` -- including the
    /// per-inode shared overlay (§9.6a) -- so every subsequent read/commit
    /// on this handle sees the result (§9.5). Called from
    /// `openWithRuntime` for every file whose decoded header carries a
    /// non-zero `redo_log_capacity`, before anything else touches
    /// `self.header`/`self.manifest_commits_enabled`.
    ///
    /// Two passes, deliberately: a cheap, metadata-only replay runs here,
    /// every time, decoding just each record's leading `CompactCheckpoint`
    /// -- every opener on this inode needs `outcome` (valid_bytes/
    /// last_sequence) and the last record's compact checkpoint to
    /// initialize its own `redo.writer`/`self.header`, regardless of
    /// whether it is also the one that populates the shared overlay.
    /// `ensureRedoOverlay`'s own `populate` callback (invoked only for a
    /// genuinely first opener on this inode, under its own lock) runs a
    /// second, full replay that also decodes the logical/page-shaped
    /// content, directly into the (`std.heap.page_allocator`-owned)
    /// shared overlay -- a second opener never replays that content at
    /// all, since the first opener's replay already populated the
    /// structure every later opener on this inode shares.
    fn recoverRedoLog(self: *NativeFile, allocator: Allocator, io: std.Io) !void {
        const checkpoint = self.activeCheckpoint();
        // perf/lwa-fold-boundary: the real, durable fold boundary this
        // on-disk slot's own roots reflect -- NOT `checkpoint.commit_sequence`,
        // which several real-publish paths (a stable-snapshot copy, a
        // log-full bare-slot fallback, a ledger-only reclaim commit) can
        // leave strictly ahead of what was actually folded. Captured here,
        // before anything below overwrites `self.header.checkpoints[active]`,
        // and used as `start_after_sequence` for both replay passes --
        // `commit_sequence` is only ever the fold boundary too when
        // nothing has advanced it without folding, which is exactly the
        // bug class `redo_folded_through` exists to stop recovery from
        // having to assume. See that field's own doc comment.
        const folded_through = checkpoint.redo_folded_through;
        const MetaCtx = struct {
            compact: ?CompactCheckpoint = null,
            fn onRecord(ctx_ptr: ?*anyopaque, record: redo_log.RecordView) anyerror!void {
                const ctx: *@This() = @ptrCast(@alignCast(ctx_ptr.?));
                if (record.payload.len < CompactCheckpoint.encoded_size) return error.InvalidNativeRedoRecord;
                ctx.compact = CompactCheckpoint.decode(record.payload[0..CompactCheckpoint.encoded_size]);
            }
        };
        var meta_ctx: MetaCtx = .{};
        const meta_outcome = try redo_log.replay(allocator, self.file, io, self.header.redo_log_offset, self.header.redo_log_capacity, folded_through, MetaCtx.onRecord, &meta_ctx);
        // A torn tail or a clean (never-written-past-the-checkpoint) end
        // are both benign (§9.5) -- the valid prefix, possibly empty, is
        // everything this recovery trusts. A corrupt record is not: this
        // open must fail rather than silently serve a truncated view of
        // acknowledged work.
        if (meta_outcome.stop_reason == .corrupt_record) return error.NativeRedoLogCorrupt;
        self.manifest_commits_enabled = false;

        const entry = self.inode_lock_ref.load(.acquire) orelse return error.InvalidTransactionState;
        // perf/lwa-proof-fork: `ensureRedoOverlay`'s own populate callback
        // below runs a *second*, independent scan of the same physical log
        // -- strictly after the one just above, but with no lock excluding
        // a concurrent writer (a different process, racing to append its
        // own next commit right now) from appending between the two. That
        // writer's new record is durable (fsynced) the moment its own
        // `redo_log.replay` could possibly see it, so this second scan can
        // only find as much or *more* of the log than the first one did,
        // never less -- confirmed live as "lite redo log cross-process: a
        // forked child sees commits the parent makes after the child
        // opens" timing out: the overlay this call populates already had
        // both the parent's pre-fork and post-fork commits (because a
        // concurrent writer landed between these two scans), while
        // `meta_outcome`/`meta_ctx.compact` -- from the earlier scan --
        // only reflected the first, leaving `redo.durable_sequence` (the
        // version-resolution mark every overlay read is bounded by)
        // permanently behind an overlay entry already sitting right there,
        // so the second commit stayed invisible forever, including across
        // every later `refreshCrossProcessRedoOverlay` call (gated on
        // `published.durable_sequence > redo.durable_sequence`, which
        // never fires once both already agree, wrongly, on the stale
        // value). `PopulateCtx.outcome`/`.compact` carry this scan's own
        // (more complete) result back out, below, for exactly this reason.
        const PopulateCtx = struct {
            file: *NativeFile,
            io: std.Io,
            start_after_sequence: u64,
            compact: ?CompactCheckpoint = null,
            outcome: ?redo_log.ReplayOutcome = null,
        };
        var pctx = PopulateCtx{ .file = self, .io = io, .start_after_sequence = folded_through };
        const shared = try inode_lock.ensureRedoOverlay(entry, io, &pctx, struct {
            fn populate(ctx: *PopulateCtx, overlay: *redo_overlay.SharedRedoOverlay, pop_allocator: Allocator) anyerror!void {
                const RecordCtx = struct {
                    overlay: *redo_overlay.SharedRedoOverlay,
                    pop_allocator: Allocator,
                    compact: ?CompactCheckpoint = null,
                    fn onRecord(ctx_ptr: ?*anyopaque, record: redo_log.RecordView) anyerror!void {
                        const rc: *@This() = @ptrCast(@alignCast(ctx_ptr.?));
                        if (record.payload.len < CompactCheckpoint.encoded_size + 4) return error.InvalidNativeRedoRecord;
                        rc.compact = CompactCheckpoint.decode(record.payload[0..CompactCheckpoint.encoded_size]);
                        const logical_len = std.mem.readInt(u32, record.payload[CompactCheckpoint.encoded_size..][0..4], .little);
                        const logical_start = CompactCheckpoint.encoded_size + 4;
                        if (logical_start + logical_len > record.payload.len) return error.InvalidNativeRedoRecord;
                        try rc.overlay.decodeLogicalMutationsPayload(rc.pop_allocator, record.payload[logical_start..][0..logical_len], record.commit_sequence);
                        try rc.overlay.decodeRedoGroupPayload(rc.pop_allocator, record.payload[logical_start + logical_len ..]);
                    }
                };
                var rctx: RecordCtx = .{ .overlay = overlay, .pop_allocator = pop_allocator };
                const full_outcome = try redo_log.replay(pop_allocator, ctx.file.file, ctx.io, ctx.file.header.redo_log_offset, ctx.file.header.redo_log_capacity, ctx.start_after_sequence, RecordCtx.onRecord, &rctx);
                if (full_outcome.stop_reason == .corrupt_record) return error.NativeRedoLogCorrupt;
                ctx.compact = rctx.compact;
                ctx.outcome = full_outcome;
            }
        }.populate);

        // Prefer the overlay populate's own scan whenever it actually ran
        // (strictly as complete as, or more complete than, the meta scan
        // above -- never less, per this function's own comment). When the
        // overlay was already populated for this pid (`ensureRedoOverlay`'s
        // "second opener in this process" skip, the common case), nothing
        // ran here and `meta_outcome`/`meta_ctx.compact` are already
        // consistent with it: every in-process commit keeps the overlay
        // and the real log in lockstep by construction.
        const outcome = pctx.outcome orelse meta_outcome;
        if (pctx.compact orelse meta_ctx.compact) |compact| {
            // perf/lwa-restore-open-txn: a bare (non-Txn) commit (schema/
            // catalog bookkeeping, a transaction-manager intent record,
            // ...) publishes straight to the on-disk checkpoint slot and
            // never appends a matching log record at all -- the exact
            // "log-full bare-slot fallback" case `redo_folded_through`'s
            // own doc comment already names as a real-publish path that
            // can leave `commit_sequence` ahead of what the log itself
            // reflects. When such a bare commit lands *after* this log's
            // own latest record, `checkpoint` above (loaded from the
            // on-disk slot before anything in this function ran) is
            // already strictly newer than `compact` -- every root pointer
            // it carries (`catalog_root_page` included) is the correct,
            // current one. Unconditionally overwriting it with `compact
            // .toCheckpointSlot()`'s older tip regresses those roots back
            // to pages the bare commit's own allocation may already have
            // retired and reused for something else: a concurrent or
            // later open then either reads the wrong physical page kind
            // (`error.UnexpectedNativePageKind`) or, when the retired
            // page still looks structurally plausible, silently resolves
            // a stale, pre-bare-commit view -- including a document
            // logged just before the bare commit going missing from a
            // fresh open, since this same regression also drags
            // `commit_sequence`, and therefore every overlay resolution's
            // own `mark`, backward with it. Apply the log's own tip only
            // when it is actually newer than what the on-disk slot
            // already published; otherwise the on-disk slot already is
            // the correct, current state and this function has nothing
            // to refine.
            if (compact.commit_sequence > checkpoint.commit_sequence) {
                // `CompactCheckpoint` carries no `redo_folded_through` of
                // its own (a log record's own embedded checkpoint is
                // always just the *tip* as of that commit, never a fold
                // boundary -- only `checkpointRedoLog`'s own fold and
                // `prepareVacuum`'s compaction ever advance one, and
                // neither ever appends a log record for the commit that
                // does) -- so `toCheckpointSlot()` comes back with the
                // field defaulted to zero. Restore the value this on-disk
                // slot actually carried: the latest log record only ever
                // refines the *tip* (roots/commit_sequence), never the
                // fold boundary, which stays exactly what the real,
                // physically-published checkpoint slot said it was.
                self.header.checkpoints[self.header.active_checkpoint] = compact.toCheckpointSlot();
                self.header.checkpoints[self.header.active_checkpoint].redo_folded_through = folded_through;
            }
        }

        // `checkpointRedoLog`'s own fold consumes a fresh `commit_sequence`
        // for its checkpoint publish without ever appending a matching log
        // record (its `checkpointing = true` span disables every diversion
        // point, so that sequence is never logged) -- by design, since the
        // checkpoint slot is already a complete, self-sufficient durability
        // record for it. `redo_log.replay`'s own scan of the physical log
        // therefore legitimately stops one behind the checkpoint whenever
        // the most recent event before a crash was such a fold: `outcome
        // .last_sequence` reports the last record it actually found on
        // disk (superseded or not), which is correct for *that* question,
        // but is not on its own a safe cursor to resume the writer from.
        // Recovery's restored checkpoint (`recovered_checkpoint_sequence`,
        // taken after the `compact.toCheckpointSlot()` update above) is
        // never behind what the log physically holds, but a fold can leave
        // it strictly *ahead* -- resuming the writer at the log's own
        // last-seen sequence in that case lets the very next commit
        // recompute `checkpoint.commit_sequence + 1` as its own next
        // sequence while the writer's continuity check still expects
        // `outcome.last_sequence + 1`, one behind -- a guaranteed
        // `error.SequenceOutOfOrder` (surfacing as `error.OutcomeUnknown`)
        // on the very first write after reopen. Clamping the writer's
        // resumed sequence to at least the recovered checkpoint's own
        // keeps the two in the same continuity domain they share on every
        // live commit (ride-along and durable alike both advance
        // `self.header`'s checkpoint and the log's `last_sequence`
        // together; only a fold's own checkpoint-only publish ever splits
        // them).
        const recovered_checkpoint_sequence = self.header.checkpoints[self.header.active_checkpoint].commit_sequence;
        const resumed_sequence = @max(outcome.last_sequence orelse recovered_checkpoint_sequence, recovered_checkpoint_sequence);
        self.redo = RedoCommitState{
            .writer = redo_log.Writer.initAt(self.file, io, self.header.redo_log_offset, self.header.redo_log_capacity, outcome.valid_bytes, resumed_sequence),
            .shared = shared,
            .durable_sequence = resumed_sequence,
            .checkpoint_sequence = folded_through,
        };
        self.publishRedoLogState();
    }

    /// Turns every page the redo log's overlay is still carrying into a
    /// real, durable on-disk page, and advances the real checkpoint slot
    /// to match -- build step (d) of docs/design/lite-performance/
    /// lite-single-commit-write-path.md §9.9. A no-op if there is nothing
    /// to checkpoint. Not yet wired to any automatic trigger (idle timer,
    /// log-capacity threshold, or the owner maintenance turn): callable
    /// explicitly for now, same as `sync()`; owner-only/background
    /// scheduling is follow-up work, not yet needed to exercise or gate
    /// this step's own correctness.
    ///
    /// Ordering is safety-load-bearing, not incidental: physical pages are
    /// written and the *new* checkpoint slot is made durable before the
    /// log's now-superseded prefix is ever touched. A crash at any point
    /// up to and including the new slot's own sync leaves the *old*
    /// checkpoint plus the still-intact log exactly as capable of
    /// recovering every acknowledged commit as it was before this call
    /// started (recovery just redoes the same checkpoint later). Only
    /// after the new slot is durable does this function zero the log's
    /// stale prefix, which is pure space reclamation, never a source of
    /// truth for anything by that point.
    ///
    /// A crash strictly between the new slot's durable sync and the
    /// log-zeroing step below leaves stale (but harmless -- already fully
    /// reflected in the new, durable checkpoint) bytes at the start of the
    /// log. `redo_log.replay` recognizes this directly (its own
    /// superseded-vs-corrupt distinction): a record whose sequence is at
    /// or below the checkpoint baseline is superseded, not corrupt, so
    /// recovery treats it as a clean end rather than failing closed. See
    /// "lite redo log checkpoint recovers cleanly from a crash between
    /// the new slot and log-zeroing" for the exercised scenario.
    ///
    /// §9.3b: the zero/reset step below is also gated on the shared
    /// region's minimum pinned sequence -- a live cross-process reader
    /// may not have caught up to this checkpoint yet, in which case the
    /// reclaim is deferred (not skipped forever; the next pass retries).
    /// While deferred, the writer keeps appending past the stale prefix
    /// instead of resetting over it, so `replay`'s superseded handling
    /// must (and does) tolerate a superseded run followed by genuinely
    /// new records, not just a superseded run with nothing after it.
    /// Calls `checkpointRedoLog` from a call site that is itself already
    /// inside an open `beginTransaction`..`commitTransactionWithDurability`/
    /// `publishCheckpoint` span on this instance -- see
    /// `commit_span_nested_allowance`'s own doc comment. `checkpointRedoLog`
    /// opens its *own* nested transaction (`beginTransaction`/
    /// `commitTransactionWithDurability`) on the same `*NativeFile`, which
    /// `debugEnterCommitSpan` would otherwise read as a second, overlapping
    /// caller and panic on; this brackets that nested call so the guard
    /// knows it is sanctioned. Every production call site that reaches
    /// `checkpointRedoLog` from inside an already-open span (the two
    /// log-full branches in `commitTransactionWithDurability`/
    /// `publishCheckpoint`, and `maybeAutoCheckpointRedoLogNested`) goes
    /// through this wrapper, never `checkpointRedoLog` directly -- the
    /// standalone callers (`docstore.zig`'s `maybeCheckpointRedoLogOnIdleTurn`,
    /// `maintainOnceWithCancel`-adjacent reclaim, tests) call
    /// `checkpointRedoLog` directly instead, with no outer span open to
    /// bracket.
    fn checkpointRedoLogNested(self: *NativeFile) anyerror!void {
        if (debug_commit_span_tracking) self.commit_span_nested_allowance += 1;
        defer if (debug_commit_span_tracking) {
            self.commit_span_nested_allowance -= 1;
        };
        try self.checkpointRedoLog();
    }

    pub fn checkpointRedoLog(self: *NativeFile) anyerror!void {
        return self.checkpointRedoLogWithDurability(true);
    }

    /// perf/lwa-wamp-regress: `durable=false` lets a caller fold the
    /// overlay into real pages without forcing its own standalone fsync.
    /// This transaction stays exactly as isolated as the always-durable
    /// case -- nothing else's writes are ever staged into it, only this
    /// function's own fold-build below -- so every retain/ownership-
    /// accounting invariant in that fold is untouched; only whether THIS
    /// transaction's own commit forces a sync right now, or defers,
    /// changes, via the same `deferred_publication` branch of
    /// `commitTransactionWithDurability` every ordinary ride-along commit
    /// on this file already relies on. A deferred fold's pages are
    /// already durable the moment any later commit on this file actually
    /// syncs (`self.header` already reflects them, and that later sync's
    /// own `publishCheckpoint` covers everything since the last durable
    /// checkpoint, this fold included) -- nothing here is lost, just not
    /// yet synced; `wal_trace.recordCommit()`/`recordSync()` never fire
    /// for a deferred commit (they live inside `publishCheckpoint`'s own
    /// durable-publish branches), so a deferred fold costs nothing in the
    /// write-amplification bench either, matching its real cost.
    ///
    /// The epilogue below splits in two. The writer's own logical-sequence
    /// advance and the in-memory overlay reclaim (`redo.shared.reclaim`/
    /// `maybeClearPages`) run regardless of `durable`: the pages they
    /// govern are physically written either way, so the overlay genuinely
    /// no longer needs those entries whether or not this commit has
    /// synced yet (a crash before it becomes durable just replays the log
    /// from the last truly durable checkpoint). Only the *physical*
    /// log-space reclaim (zeroing the now-superseded tail, shrinking
    /// capacity) and the cross-process publish are skipped for a deferred
    /// commit, because those specifically need the commit to already be
    /// durable: zeroing a log range this commit hasn't actually synced
    /// yet would lose data on a crash, and publishing the advanced
    /// checkpoint sequence to `shared_lock_region.zig` would tell other
    /// processes about state that is not actually safe yet. A later,
    /// genuinely durable fold (explicit API, the 25%-remaining
    /// backpressure, or this same idle path once byte pressure makes it
    /// durable) runs that part of the epilogue then.
    pub fn checkpointRedoLogWithDurability(self: *NativeFile, durable: bool) anyerror!void {
        if (comptime builtin.is_test) if (self.test_fail_checkpoint_redo_log) |err| {
            self.test_fail_checkpoint_redo_log = null;
            return err;
        };
        const redo: *RedoCommitState = if (self.redo) |*r| r else return error.InvalidTransactionState;
        const io = self.runtimeIo();
        const has_logical_work = for (0..3) |root_idx| {
            if (redo.shared.count(io, @intCast(root_idx)) != 0) break true;
        } else false;
        // Page-shaped writes (external value chains) never accumulate
        // without an accompanying logical mutation that points at them in
        // the same commit (`appendLogicalMutation`'s own doc comment) --
        // so `has_logical_work == false` implies there is no pending page
        // work either.
        if (!has_logical_work) return;

        // Disables every diversion point (`PageWriteBatch.flushCount`,
        // `flushTransactionWrites`'s logical-mutation branch,
        // `commitTransactionWithDurability`, `publishCheckpoint`) for the
        // span of the transaction below, so it builds real copy-on-write
        // pages and publishes a real, physical checkpoint slot -- the
        // whole point of this function -- instead of logging itself.
        redo.checkpointing = true;
        defer redo.checkpointing = false;

        // Apply every accumulated logical mutation to the real B-tree, one
        // `IndexEditor` pass per root (inside `putDocumentBatch`/
        // `putCatalogBatchForRoot`, called below exactly as
        // `flushTransactionWrites` already calls them for an ordinary
        // commit's own batch) batched across however many commits
        // contributed to `logical_overlay` -- not once per commit. A page
        // this checkpoint's own build touches gets copy-on-write'd exactly
        // once here, regardless of how many of the batched commits also
        // touched it.
        try self.beginTransaction();
        errdefer self.abortTransaction();

        // Flush every still-staged page (external value chains) directly
        // to its real location before the logical fold below: a
        // reference to one of these from a folded head (`external_value_root_page`)
        // only stores the page_id, never re-derives or re-writes the
        // page's own bytes, so without this explicit flush the
        // referenced page would stay parked in the overlay forever
        // (`maybeClearPages`, called after this function's own commit,
        // assumes every staged page has *already* been folded into a
        // real, physical one by this point -- this is what actually
        // makes that assumption true, rather than relying on the
        // logical fold to do it incidentally, which it never did).
        // Snapshotted, not removed, until every page is durably written
        // below (`SharedRedoOverlay.snapshotAllPagesAlloc`'s own doc
        // comment): removing first (what this used to do) left a window,
        // for however long this loop takes to reach a given page, where a
        // concurrent reader on another thread (this fold's own exclusive
        // writer lock excludes other writers, never readers) would find
        // that page in neither the overlay (already removed) nor its real
        // location (not yet written) -- `readBackingPages`'s own
        // overlay-then-disk order makes exactly that gap observable as
        // `error.EndOfStream`.
        const staged_pages = try redo.shared.snapshotAllPagesAlloc(std.heap.page_allocator, io);
        defer {
            for (staged_pages) |p| std.heap.page_allocator.free(p.bytes);
            std.heap.page_allocator.free(staged_pages);
        }
        for (staged_pages) |p| {
            try self.file.writePositionalAll(io, p.bytes, p.page_id * @as(u64, self.header.page_size));
        }
        redo.shared.removePages(std.heap.page_allocator, io, staged_pages);
        // §9.7c (ReadView): `self.header.checkpoints[active].page_count`
        // still reflects the *last already-published* checkpoint here --
        // the commit that triggered this fold (log-full, mid-`publishCheckpoint`)
        // may itself have allocated fresh pages past that (a large
        // external value's own extent tree, via that commit's own
        // `TransactionWrites.pages`, seeded from `page_count` as it stood
        // *before* this fold ever ran) whose `next`/`checkpoint` was never
        // published, since the log-full branch runs before that
        // publication step. Without this, `validateDocumentMutation`/
        // `validateCatalogMutation`'s own bounds check
        // (`external_value_root_page >= self.activeCheckpoint().page_count`)
        // sees a reference to one of the pages just flushed above as
        // out-of-range and fails with `error.InvalidNativeValueChain` --
        // and, independent of that check, a fresh `PageAllocator` this
        // fold's own `transactionWrites()` is about to construct (seeded
        // from the same stale `page_count`) would start handing out page
        // ids that collide with the ones just flushed. Advance it to
        // cover every flushed page before anything below references or
        // allocates past it.
        if (staged_pages.len != 0) {
            var max_staged_page: u64 = 0;
            for (staged_pages) |p| max_staged_page = @max(max_staged_page, p.page_id);
            const required = max_staged_page + 1;
            if (required > self.header.checkpoints[self.header.active_checkpoint].page_count) {
                self.header.checkpoints[self.header.active_checkpoint].page_count = required;
            }
            // Force `commitTransactionWithDurability`'s own `changed` check
            // (`next.commit_sequence != previous.checkpoints[...].commit_sequence`,
            // `previous` being the snapshot `beginTransaction` took just
            // above, before this bump) to see this fold as having changed
            // something, even if every logical head below turns out to be
            // a content no-op (`putCatalogBatchForRoot`'s own "small index
            // files include WAL control records" shortcut, which returns
            // without ever staging into `transaction_writes` when a
            // mutation's value already matches what's on disk). Without
            // this, `changed == false` takes the plain-`sync()` branch
            // instead of `publishCheckpoint`, so the real on-disk
            // checkpoint slot is never advanced to cover the pages just
            // physically written above -- yet the epilogue below still
            // unconditionally reclaims the overlay and resets/zeros the
            // log on the assumption ("everything above is durable now")
            // that a fresh durable checkpoint was just published. The
            // result: the pages are physically correct on disk, but
            // nothing durable (neither the checkpoint slot nor the
            // now-wiped log) points to them any more -- invisible, not
            // merely stale, on the next open. Bumping here is safe: every
            // reader of `commit_sequence` through this fold's own
            // transaction only ever sees the final, already-published
            // value `self.header` settles on past this point.
            self.header.checkpoints[self.header.active_checkpoint].commit_sequence += 1;
        }
        // §9 (redo + indexed reclamation): every page just flushed was
        // allocated and written by an earlier *diverting* commit
        // (`pageAllocatorForDivertingCommit`'s own doc comment -- "the
        // one page-shaped exception a diverting commit still makes"),
        // which never touches the ledger at all, unlike every other
        // path that physically writes a page through this file's real,
        // ledger-backed `PageAllocator.writePage`. The fold below (the
        // `root_idx` loop just past this) runs inside this already-open
        // transaction, so `putDocumentBatch`/`putCatalogBatchForRoot`
        // only *stage* into `TransactionWrites.maps` here -- the real
        // `IndexEditor` pass that actually writes each document/catalog
        // record (and, via `writePage`'s own `.document`/`.catalog`
        // branch calling `retainRecord`, retains each chain's own
        // *root* page for exactly this reason) does not run until
        // `flushTransactionWrites` processes those maps later, inside
        // `commitTransactionWithDurability` below. Handing the page ids
        // to `self` here, for `flushTransactionWrites`'s own fold to
        // pick up right after it -- not retaining them here directly --
        // avoids double-retaining a root the real build is about to
        // retain itself, while still covering a chain's own
        // *continuation* pages beyond that root, which nothing else
        // retains at all (a normal, non-diverting commit retains those
        // at `.data`-kind write time; these were written raw, by a
        // commit that never touched a ledger). Left uncovered,
        // `validateIndexedOwnership`'s reachability walk finds a
        // referenced page the ledger never counted (indistinguishable
        // from an `allocateFresh` page whose own retain never ran) and
        // fails with `error.InvalidNativeAllocator`.
        //
        // perf/lwa-verify-crash: deliberately NOT assigned here. See the
        // assignment just before `redo_fold_retire_pending` below for why:
        // `staged_pages` covers every page-shaped write since the last
        // fold, across *every* key, including ones a later version in
        // this same window superseded before this fold ever ran (the
        // `retiring_chains`/`redo_fold_retire_pending` case just below).
        // Publishing this list before that superseded-chain analysis has
        // finished lets an unrelated private flush mid-loop (`putDocumentBatch`'s
        // own `TransactionWrites.max_keys` early-flush gate, triggered by
        // a large backlog of *unrelated* pending heads) drain it early and
        // retain a superseded chain's pages as if they were a live
        // continuation -- `validateIndexedOwnership`'s later "surviving
        // owner" filter then sees that premature retain as
        // `ledger_state.count(chain.root) != 0` and treats it as proof the
        // chain is still referenced, silently dropping it from
        // `retiring_chains` instead of queuing it for retirement. The
        // chain's pages end up permanently retained (an unreachable
        // phantom reference) with no live owner and no pending retirement
        // ever able to release them -- reproduced live by the
        // `lite_sqlite_comparison.py --workers 8` benchmark and the test
        // below. `staged_pages` itself stays alive for the rest of this
        // function (freed only by the `defer` registered where it was
        // captured), so computing `redo_fold_retain_pending` from it down
        // below, alongside `redo_fold_retire_pending`, costs nothing extra.
        // §9 (redo, re-fold guard): the sequence boundary this fold is
        // building on top of -- `redo.checkpoint_sequence` is not
        // advanced to `new_checkpoint_sequence` until this function's own
        // epilogue, well after this loop, so every version at or below
        // this captured value was already included in a *prior*
        // `checkpointRedoLog` fold. `reclaim`'s own pin-aware floor can
        // leave such an already-folded head sitting in `redo.shared.maps`
        // indefinitely (a live pin older than the key's entire chain
        // never finds anything `<= floor` to collapse, so the key is
        // never dropped, even though it is already durably on disk) --
        // without this guard, `snapshotHeadsAlloc` would hand this same
        // stale head to a *later* fold again, which would build a
        // *second* real record for the same key, re-referencing an
        // external value chain's `external_value_root_page` that the
        // first fold already attached to the first record. See
        // `snapshotHeadsAlloc`'s own doc comment for the full mechanism
        // and the "redo differential oracle" / "crash sweep ... dense
        // native-catalog" failures this caused.
        const fold_floor = redo.checkpoint_sequence;
        // perf/lwa-orphan-pages: every page-shaped chain this fold's own
        // overlay snapshot finds superseded or deleted within
        // `(fold_floor, new fold]`, across every root -- see
        // `redo_overlay.SharedRedoOverlay.SupersededChain`'s own doc
        // comment. Collected across all three roots' loop iterations
        // below, then handed to `flushTransactionWrites` the same way
        // `redo_fold_retain_pending` already is.
        var retiring_chains: std.ArrayListUnmanaged(redo_overlay.SharedRedoOverlay.SupersededChain) = .empty;
        errdefer retiring_chains.deinit(self.allocator);
        // perf/lwa-lease-fold: every root page a *surviving* head (any
        // root, this same fold) still points at via its own
        // `external_value_root_page` -- an open artifact lease's own
        // catalog record (`artifact_source.zig`'s `Capture.apply`) is
        // exactly this: it never writes a new value chain, it just
        // copies an *existing* `external_value_root_page` into a second,
        // independent record. When the original record superseded by
        // this same fold (an overwrite or delete) happens to point at
        // the identical chain -- aliasing, not a coincidence of ids,
        // since nothing else hands out that exact page number again --
        // retiring that chain below must not also release the surviving
        // alias's own hold on it. See the loop below, after every root
        // has been collected, for how this set is used.
        var surviving_roots: std.AutoHashMapUnmanaged(u64, void) = .empty;
        defer surviving_roots.deinit(self.allocator);
        for (0..3) |root_idx| {
            // A fully-owned snapshot, folded outside `shared`'s own lock
            // (`snapshotHeadsAlloc`'s own doc comment) -- `putDocumentBatch`/
            // `putCatalogBatchForRoot` below run a real `IndexEditor` pass,
            // not something to do while holding a lock every reader on
            // this inode also needs.
            const heads = try redo.shared.snapshotHeadsAlloc(self.allocator, io, @intCast(root_idx), fold_floor);
            defer {
                for (heads) |h| {
                    self.allocator.free(h.key);
                    self.allocator.free(h.value);
                }
                self.allocator.free(heads);
            }
            for (heads) |h| {
                if (!h.is_delete and h.external_value_root_page != 0) try surviving_roots.put(self.allocator, h.external_value_root_page, {});
            }
            // Same `fold_floor` boundary as `heads` above -- see
            // `snapshotSupersededChainsAlloc`'s own doc comment for why
            // this never double-counts a chain an earlier fold already
            // retired.
            const superseded = try redo.shared.snapshotSupersededChainsAlloc(self.allocator, io, @intCast(root_idx), fold_floor);
            defer self.allocator.free(superseded);
            try retiring_chains.appendSlice(self.allocator, superseded);
            if (heads.len == 0) continue;
            if (root_idx == @backingInt(TransactionWrites.Root.documents)) {
                var docs = try std.ArrayListUnmanaged(DocumentMutation).initCapacity(self.allocator, heads.len);
                defer docs.deinit(self.allocator);
                for (heads) |h| docs.appendAssumeCapacity(.{
                    .key = h.key,
                    .value = h.value,
                    .is_delete = h.is_delete,
                    .external_value_root_page = h.external_value_root_page,
                    .external_value_len = h.external_value_len,
                });
                std.mem.sort(DocumentMutation, docs.items, {}, struct {
                    fn less(_: void, a: DocumentMutation, b: DocumentMutation) bool {
                        return std.mem.order(u8, a.key, b.key) == .lt;
                    }
                }.less);
                try self.putDocumentBatch(docs.items);
            } else {
                var batch = try std.ArrayListUnmanaged(CatalogMutation).initCapacity(self.allocator, heads.len);
                defer batch.deinit(self.allocator);
                for (heads) |h| batch.appendAssumeCapacity(.{
                    .key = h.key,
                    .value = h.value,
                    .is_delete = h.is_delete,
                    .external_value_root_page = h.external_value_root_page,
                    .external_value_len = h.external_value_len,
                });
                std.mem.sort(CatalogMutation, batch.items, {}, struct {
                    fn less(_: void, a: CatalogMutation, b: CatalogMutation) bool {
                        return std.mem.order(u8, a.key, b.key) == .lt;
                    }
                }.less);
                try self.putCatalogBatchForRoot(if (root_idx == 0) .metadata else .index, batch.items, .{});
            }
        }
        // perf/lwa-lease-fold: drop every retiring chain whose root page
        // is still referenced by a live owner -- either a surviving head
        // collected just above (`surviving_roots`), or a reference this
        // fold did not create at all (the page already had a nonzero
        // ledger count *before* this fold's own build ran, e.g. an
        // artifact lease's own catalog record a previous fold already
        // retained -- nothing below this point has retained anything
        // yet: every build above only stages into `TransactionWrites
        // .maps`; the real `IndexEditor`/retain pass does not run until
        // `flushTransactionWrites`, well after this). Retiring one of
        // these anyway would queue a `.value` retirement that, once
        // drained, releases a reference that reference's own surviving
        // owner still needs -- the exact corruption a leased immutable
        // source's pages must never suffer (see `retainUnretainedValueChainPages`'s
        // own doc comment: it is safe to call after a surviving record
        // already retained the same root, but the matching `retire()`
        // call below is not, and this is the only point with enough
        // information to tell the two cases apart). A chain filtered out
        // here needs no retain of its own either: whatever still
        // references its pages already retains them (the surviving
        // head's own `retainRecord`/`retainUnretainedValueChainPages`
        // sweep in `flushTransactionWrites`, or the prior fold that
        // established the pre-existing count), and `redo_fold_retain_pending`'s
        // generic staged-page sweep covers any continuation page neither
        // of those reaches.
        if (retiring_chains.items.len != 0) {
            const ledger_state: ?*allocator_v4.State = if (self.transaction_writes) |writes| writes.pages.ledger else null;
            var keep: usize = 0;
            for (retiring_chains.items) |chain| {
                const referenced = surviving_roots.contains(chain.external_value_root_page) or
                    (if (ledger_state) |state| state.count(chain.external_value_root_page) != 0 else false);
                if (referenced) continue;
                retiring_chains.items[keep] = chain;
                keep += 1;
            }
            retiring_chains.shrinkRetainingCapacity(keep);
        }
        // `retiring_chains` used to never grow at all (stay `.empty`,
        // nothing allocated) whenever `items.len == 0` here -- nothing
        // to free in that case, so the code below this comment used to
        // skip `toOwnedSlice` entirely rather than risk a double-`deinit`
        // against the `errdefer` registered where this list was
        // declared (`deinit` leaves the list `undefined`; calling it a
        // second time on that is its own bug, not a safe no-op).
        // perf/lwa-lease-fold: that is no longer the only way to reach
        // `items.len == 0` -- the surviving-owner filter just above can
        // empty a list that *did* allocate (grew while collecting, then
        // every entry filtered out), and that backing allocation is
        // real and leaks if nothing frees it (reproduced live: "lite
        // fold with an open lease never corrupts the leased bytes"
        // leaking exactly one `retiring_chains` growth on a fold whose
        // only superseded chain was also the lease's own surviving
        // alias). `toOwnedSlice` unconditionally, regardless of length,
        // sidesteps both problems at once: it always leaves the list in
        // the same safe, empty, re-`deinit`-able state `toOwnedSlice`
        // already left it in on the non-empty path before this change,
        // whether or not anything was ever appended, so the still-armed
        // `errdefer` stays harmless either way.
        const retiring_owned = try retiring_chains.toOwnedSlice(self.allocator);
        if (retiring_owned.len != 0) {
            self.redo_fold_retire_pending = retiring_owned;
        } else {
            self.allocator.free(retiring_owned);
        }
        // perf/lwa-verify-crash: assigned here, alongside `redo_fold_retire_pending`
        // above, rather than back where `staged_pages` was captured -- see
        // that assignment's own doc comment for why: this generic sweep
        // must never become visible to a private flush before the
        // superseded-chain analysis just above has finished deciding
        // which of `staged_pages` belongs to a chain that must be
        // *retired*, not retained as live. `staged_pages` is still alive
        // here (freed only by the `defer` registered where it was
        // captured).
        if (staged_pages.len != 0 and self.header.indexed_reclamation) {
            // `installCommitForFold` (both of its callers run this fold
            // right after it) may already have recorded the pages *it*
            // flushed ahead of this fold -- the newest commit's own, so
            // never a superseded chain. Merge rather than overwrite, or
            // that batch loses its only retain tracking.
            if (self.redo_fold_retain_pending) |existing| {
                const merged = try self.allocator.alloc(u64, existing.len + staged_pages.len);
                @memcpy(merged[0..existing.len], existing);
                for (staged_pages, merged[existing.len..]) |p, *out| out.* = p.page_id;
                self.allocator.free(existing);
                self.redo_fold_retain_pending = merged;
            } else {
                const pending = try self.allocator.alloc(u64, staged_pages.len);
                for (staged_pages, pending) |p, *out| out.* = p.page_id;
                self.redo_fold_retain_pending = pending;
            }
        }
        // Builds the real pages above, then (via `flushTransactionWrites`,
        // `commitTransactionWithDurability`, `publishCheckpoint`, all
        // running their ordinary non-redo behavior because `checkpointing`
        // is true) syncs them and writes a real, physical checkpoint slot.
        // `flushTransactionWrites` itself consumes and frees
        // `self.redo_fold_retain_pending`/`self.redo_fold_retire_pending`
        // (see those fields' own doc comments); this only cleans up if
        // something above returned an error before `flushTransactionWrites`
        // ever ran.
        errdefer if (self.redo_fold_retain_pending) |pending| {
            self.allocator.free(pending);
            self.redo_fold_retain_pending = null;
        };
        errdefer if (self.redo_fold_retire_pending) |retiring| {
            self.allocator.free(retiring);
            self.redo_fold_retire_pending = null;
        };
        // perf/lwa-reclaim-reconcile: this fold's own real commit goes
        // through `flushTransactionWrites`'s `!diverting` branch, which
        // (same as any ordinary bare/non-diverting commit) calls
        // `persistAllocator`, whose own reserve-capacity admission check
        // (`persistAllocator`'s own comment; mirrored for a diverting
        // commit by Bug 2, perf/lwa-budget-tail) fails closed whenever
        // free page-id headroom under `max_file_bytes` is below
        // `retirementReservePages`'s own fixed overhead. Near budget --
        // exactly when this fold is most needed -- that headroom is
        // tightest, so without this exemption the one commit that exists
        // to relieve the pressure (folding every diverted commit's own
        // superseded chains back into the ledger, `reclaimPagesImpl`'s
        // own fold call just above this function, via
        // `checkpointRedoLog() catch {}`) could itself fail closed with
        // the same `error.LiteStorageBudgetExceeded`, leaving the real
        // retirement debt (`redoCheckpointWouldRetire`) permanently
        // unserviced -- confirmed live via "lite reclamation capacity
        // reserve sustains bounded overwrites"/"drains wide value
        // graphs" looping through every retry with
        // `retirementNeedsService()` correctly reporting debt but never
        // able to act on it. `reclaimPagesImpl`'s own ledger-only
        // retirement body (a few lines below this function's own caller)
        // already exempts itself from this exact check the same way, for
        // the same reason.
        const previous_maintenance = self.maintenance_publication;
        self.maintenance_publication = true;
        defer self.maintenance_publication = previous_maintenance;
        try self.commitTransactionWithDurability(durable, null);

        // Everything above is durable now (if `durable`); only space reclamation is
        // left. `redo.writer` was never touched by the commit just above
        // (every diversion point was disabled), so its `tail` still names
        // exactly the log bytes every diverted commit before this call
        // appended -- now fully superseded by the checkpoint that just
        // landed.
        const old_tail = redo.writer.tail;
        const new_checkpoint_sequence = self.activeCheckpoint().commit_sequence;
        // The commit just above already consumed `new_checkpoint_sequence`
        // without ever appending a matching log record for it
        // (`checkpointing = true` disabled the whole redo-append branch for
        // that one commit, same as the `redo_fell_back_to_slot` case this
        // mirrors) -- `self.header`'s checkpoint is durably ahead of
        // `redo.writer.last_sequence` from this point on, committed or not.
        // Advance the writer's own sequence counter (never `tail`, which
        // the reclaim/zero/shrink steps below still own) right here, before
        // any of them, rather than only as a side effect of the `Writer
        // .init`/`initAt` calls those steps reach on success: every step
        // from here through the end of this function is itself a durability
        // barrier the crash sweep injects faults into (the log-zeroing
        // write+sync, `maybeShrinkRedoLogCapacity`'s own commit), and a
        // `try` failing partway through used to return with the writer
        // never fixed up -- `self.header` already durably one ahead,
        // `redo.writer.last_sequence` still naming the pre-fold value.
        // Every later commit then recomputed the same doomed
        // `header.commit_sequence + 1` from the unmoved header and
        // collided with the writer's own stale continuity check forever
        // (`error.SequenceOutOfOrder`, surfacing as the equally far less
        // specific `error.OutcomeUnknown`) -- a derived worker retrying
        // that error treats it as transient and backs off, but nothing
        // about this file ever changes on its own, so it never recovers.
        // Reproduced via "crash sweep: graph metric build and compaction
        // mid-scenario": a fault landing on this function's own log-zero
        // sync, right after its internal fold commit had already landed.
        redo.writer.last_sequence = new_checkpoint_sequence;
        // §9.6a: unlike the pre-sharing design, this is not an
        // unconditional clear -- a reader pinned to an older checkpoint
        // than the one that just landed may still need an overlay version
        // this checkpoint's own build also folded into real pages
        // (`reclaim` keeps exactly those, dropping only what no live pin
        // can ever resolve to). The checkpoint just published covers
        // every version folded above by construction (its own
        // `commit_sequence` is freshly assigned after all of them), so it
        // is the correct reclaim floor.
        redo.shared.reclaim(std.heap.page_allocator, io, new_checkpoint_sequence);
        redo.shared.maybeClearPages(std.heap.page_allocator, io);
        // The real on-disk checkpoint is durable now regardless of
        // whether the log's stale prefix below gets physically reclaimed
        // this pass: a fresh reopen already reads this baseline straight
        // off the checkpoint slot, and a cross-process reader must see it
        // too, so a stale cached baseline on its side is recognized as
        // stale rather than silently misread ("re-open semantics",
        // §9.3b).
        redo.checkpoint_sequence = new_checkpoint_sequence;
        // perf/lwa-wamp-regress: everything above this point (the writer's
        // own logical-sequence advance, `redo.shared.reclaim`/`maybeClearPages`,
        // `redo.checkpoint_sequence`) is safe regardless of `durable` --
        // the pages these govern were physically written by
        // `flushTransactionWrites` above no matter what, so the in-memory
        // overlay genuinely no longer needs them, durable or not (a crash
        // before this commit becomes durable just replays the log from
        // the last truly durable checkpoint, same as any other deferred
        // commit). Only what follows -- physically zeroing/reclaiming log
        // bytes and publishing to the cross-process shared region -- needs
        // real durability: zeroing a log range this commit's own publish
        // hasn't actually synced yet would lose data on a crash, and
        // `publishRedoLogState` specifically advertises a *durable*
        // sequence to other processes. Mirror the `pinned_below` branch's
        // own "defer the physical reclaim, still advance the logical
        // writer past `new_checkpoint_sequence`" shape below (same
        // reason, different cause: a live cross-process reader there, no
        // durability yet here) -- `old_tail`'s bytes stay exactly as they
        // are, still valid, until a later, genuinely durable fold (byte
        // pressure, the explicit API, or this same idle path once pressure
        // makes it durable) retries this and actually reclaims them.
        if (!durable) {
            redo.writer = redo_log.Writer.initAt(self.file, io, self.header.redo_log_offset, self.header.redo_log_capacity, old_tail, new_checkpoint_sequence);
            return;
        }
        if (builtin.is_test and self.test_skip_redo_log_zero) {
            self.publishRedoLogState();
            return;
        }
        // §9.3b: must not physically reclaim log bytes a live
        // cross-process reader still needs. Gated on the region's
        // minimum pinned sequence -- the only mechanism that tracks "a
        // reader outside this process hasn't caught up yet": an
        // in-process reader never reads raw log bytes at all, only
        // `redo.shared`'s own in-memory version chains, which `reclaim`
        // above already governs through its own, separate pin list. If a
        // live cross-process reader is pinned below this checkpoint,
        // defer the reclaim entirely -- the writer keeps appending past
        // `old_tail` instead of resetting over it (safe:
        // `redo_log.replay`'s superseded-record handling tolerates a
        // stale leading run followed by genuinely new records, see
        // redo_log.zig's own "a superseded run can be followed by
        // genuinely new records" test) -- and the next checkpointer pass
        // retries once the blocking reader has caught up or died. A
        // bounded-retry posture, not a `retirementNeedsService()`-driven
        // one: an externally-pinned backlog never resolves on its own,
        // the same rule every other reader-pin-blocks-reclaim case in
        // this codebase already follows.
        const blocking_pin: ?u64 = blk: {
            const region = (self.regionForInode() catch break :blk null) orelse break :blk null;
            const min_pinned = region.minimumUncoveredPinnedSequence(antfly_platform.process.currentId() orelse 0, redo.shared.minimumPin(io)) orelse break :blk null;
            break :blk if (min_pinned < new_checkpoint_sequence) min_pinned else null;
        };
        const pinned_below = blocking_pin != null;
        if (!pinned_below) {
            if (old_tail > 0) {
                const zeros = try self.allocator.alloc(u8, @intCast(old_tail));
                defer self.allocator.free(zeros);
                @memset(zeros, 0);
                try self.file.writePositionalAll(io, zeros, self.header.redo_log_offset);
                try self.file.sync(io);
            }
            // §9.7f: the same "no cross-process reader pinned below the
            // checkpoint this fold just published" gate this branch
            // already establishes is also the right one for shrinking
            // the log's own capacity reservation -- see
            // `maybeShrinkRedoLogCapacity`'s own doc comment.
            try self.maybeShrinkRedoLogCapacity();
            redo.writer = redo_log.Writer.init(self.file, io, self.header.redo_log_offset, self.header.redo_log_capacity);
            // perf/lwa-fold-churn: a clean reclaim means the next
            // opportunistic attempt is worth paying for again regardless
            // of what used to block it.
            redo.checkpoint_backoff_min_pinned = null;
        } else {
            // perf/lwa-fold-churn: record exactly which pin blocked this
            // reclaim so `maybeAutoCheckpointRedoLog`'s next call can skip
            // its own expensive attempt until that pin has actually moved
            // -- see `RedoCommitState.checkpoint_backoff_min_pinned`'s own
            // doc comment for why retrying blind, every commit, is pure
            // waste while this is set.
            redo.checkpoint_backoff_min_pinned = blocking_pin;
            // Deferred: `old_tail`/the bytes already in the log are left
            // exactly as they are (still correct, just now superseded).
            // But `redo.writer.last_sequence` must still advance past
            // `new_checkpoint_sequence` -- the checkpoint commit above
            // consumed that sequence number without ever appending a log
            // record for it (`checkpointing = true` disabled the whole
            // redo-append branch for that one commit) -- otherwise the
            // *next* ordinary commit's own append would fail the
            // writer's own continuity check (`error.SequenceOutOfOrder`,
            // expecting `old_tail`'s last record's sequence + 1, which is
            // now one behind the real next value). `redo_log.replay`'s
            // own superseded-run handling (redo_log.zig) is built to
            // tolerate exactly this gap on a later reopen/cross-process
            // catch-up.
            redo.writer = redo_log.Writer.initAt(self.file, io, self.header.redo_log_offset, self.header.redo_log_capacity, old_tail, new_checkpoint_sequence);
        }
        self.publishRedoLogState();
    }

    /// §9.7f: shrinks this file's redo-log capacity reservation to
    /// `NativeFile.redoLogCapacityForBudget(self.redo_log_budget_bytes)`,
    /// when that is smaller than the current `header.redo_log_capacity`
    /// -- the gap that left a store's reservation frozen at its
    /// creation-time size even after `maintenance_policy.options
    /// .max_storage_bytes` (and therefore `redo_log_budget_bytes`,
    /// refreshed every commit by `docstore.Store
    /// .refreshAdmissionAssumeLocked`) was lowered well below it.
    ///
    /// Growing back is not attempted here: once a shrunk range's pages
    /// are released to the free map (the indexed branch below), any
    /// later write may claim one of them for ordinary content, so
    /// safely re-reserving the same contiguous range for a larger log
    /// again would need to relocate whatever has since claimed it --
    /// the same class of gap §9.7f's own "growing the reservation from a
    /// small floor ... instead of reserving the maximum eagerly" already
    /// defers as future work for the unbounded case. A budget raised
    /// back up after being lowered keeps whatever smaller capacity the
    /// most recent shrink left it at; a dedicated vacuum/rewrite is the
    /// existing mechanism for enlarging it again.
    ///
    /// Called only from `checkpointRedoLog`'s own epilogue, inside the
    /// same `!pinned_below` branch that already gates resetting the log
    /// at all: no cross-process reader is pinned below the checkpoint
    /// this fold just published. That is the gate that matters here too
    /// -- not the general content-retirement reader-pin frontier
    /// (`allocator_v4.State.eligible`'s own `data_frontier`/
    /// `metadata_frontier`), which these specific pages were never
    /// subject to in the first place: they were reserved directly by
    /// `enableRedoLog`'s own `allocateFresh` loop, at reference count 0,
    /// and held only log bytes -- no checkpoint, old or new, ever
    /// exposed one of them through any content-reading API, so no
    /// pinned reader's content view can ever legitimately depend on one
    /// still reading as reserved. A cross-process reader's own *log
    /// replay*, not its content view, is what `pinned_below` protects.
    ///
    /// Crash safety: the new, smaller `header.redo_log_capacity` is
    /// written and synced to disk *before* the pages it frees are
    /// released in the ledger and that release is published as a real
    /// checkpoint. A crash in between leaves the header already showing
    /// the smaller capacity (safe: a recovered writer re-opens bounded
    /// to it, never appending past where the shrink intended) with
    /// those specific pages still shown reserved in the ledger (safe:
    /// merely not yet reclaimed, retried on a later fold) -- never the
    /// reverse (pages already free while the header still claims the
    /// old, larger capacity), which would let an ordinary write claim
    /// one of them for real content while a crash-recovered writer
    /// still believed it owned that exact byte range for the log.
    fn maybeShrinkRedoLogCapacity(self: *NativeFile) !void {
        const target_raw = redoLogCapacityForBudget(self.redo_log_budget_bytes);
        const page_size: u64 = self.header.page_size;
        const target_pages = std.math.divCeil(u64, @max(target_raw, 1), page_size) catch unreachable;
        const target_capacity = target_pages * page_size;
        const old_capacity = self.header.redo_log_capacity;
        if (target_capacity >= old_capacity) return;
        const old_capacity_pages = old_capacity / page_size;
        const offset_page = self.header.redo_log_offset / page_size;

        // Durable on its own, first -- see this function's own doc
        // comment for why this exact order is the safe one.
        var next_header = self.header;
        next_header.redo_log_capacity = target_capacity;
        var encoded: [header_size]u8 = undefined;
        encodeHeader(&encoded, next_header);
        const io = self.runtimeIo();
        try self.file.writePositionalAll(io, &encoded, 0);
        try self.file.sync(io);
        self.header.redo_log_capacity = target_capacity;
        self.last_synced_header = self.header;

        if (!self.header.indexed_reclamation) {
            // No free-map/ledger to release into at all for a
            // non-reusing file -- page ids there are a one-way,
            // append-only counter, never a reusable pool (the same
            // reason vacuum for a non-indexed file works by rewriting a
            // whole new, smaller file, never by freeing pages in
            // place). The physical bytes stay reserved for the file's
            // lifetime; only the accounted/active capacity above
            // shrinks, which is still real: `header.redo_log_capacity`
            // is exactly the `fixed_overhead` Bug 3 (perf/lwa-budget-tail)
            // already nets out of every proportional reclamation ratio,
            // and `pageAllocatorForDivertingCommit`'s own admission
            // check reads it directly too.
            return;
        }

        // Release the now-excess pages into the free map, through the
        // exact same ledger-only commit shape `reclaimPagesImpl` already
        // uses on a redo-log file (`redo.checkpointing` is already
        // `true` for this whole call, set by `checkpointRedoLog`'s own
        // entry; a dedicated transaction; `persistAllocator`;
        // `publishCheckpoint`; then the same post-commit redo
        // sequence/durable-watermark resync that function's own comment
        // explains). `releaseMetadata` (not `retire`/`complete`): these
        // pages were reserved at reference count 0, never `retain`ed --
        // exactly the page-state class `releaseMetadata` already exists
        // for, not a retained, content-bearing page that needs the
        // general retire/eligible/complete lifecycle at all.
        try self.beginTransaction();
        errdefer self.abortTransaction();
        const before = self.activeCheckpoint();
        var pages = try self.pageAllocatorFromFreeMap(before);
        defer pages.deinit();
        const state = pages.ledger orelse return error.InvalidNativeAllocator;
        var p = target_pages;
        while (p < old_capacity_pages) : (p += 1) try state.releaseMetadata(offset_page + p);
        const previous_maintenance = self.maintenance_publication;
        self.maintenance_publication = true;
        defer self.maintenance_publication = previous_maintenance;
        var next = before;
        next.commit_sequence += 1;
        next.free_map_root_page = try pages.allocate();
        try self.persistAllocator(&pages, &next);
        try self.syncIfRequired(null);
        try self.publishCheckpoint(next, false, null);
        try self.commitTransactionWithDurability(true, null);
        if (self.redo) |*redo| {
            const new_sequence = self.activeCheckpoint().commit_sequence;
            redo.checkpoint_sequence = new_sequence;
            redo.durable_sequence = new_sequence;
            redo.writer.last_sequence = new_sequence;
        }
    }

    /// §9.3b/step (g): catches this process's own redo-log overlay up to
    /// whatever another process has published to the shared lock region,
    /// without reopening. Safe to call on any redo-log `NativeFile`,
    /// including the live writer itself (a no-op there: its own
    /// `durable_sequence` is always >= whatever it last published).
    ///
    /// Always pins this process's own reader slot at `redo.durable_sequence`
    /// *before* reading anything new -- never at the newer value this call
    /// is about to advance to -- so the writer's own reclaim gate
    /// (`checkpointRedoLog`'s `pinned_below` check) can never race ahead
    /// of what this call is in the middle of reading. The pin only moves
    /// forward once the corresponding bytes have actually been applied.
    ///
    /// Reuses `redo_log.replay` with this process's own last-applied
    /// sequence as `start_after_sequence`: everything already applied is,
    /// from this call's own point of view, "superseded" by its own
    /// baseline (§9.3b's generalized superseded-skip in redo_log.zig), so
    /// one call always scans the *whole* log region (replay has no
    /// resume-from-byte-offset primitive) but only ever delivers genuinely
    /// new records to the overlay -- correct regardless of whether the
    /// writer's own on-disk checkpoint advanced since the last refresh.
    /// If it did, the *real* on-disk checkpoint slot (roots, page_count,
    /// manifest) is re-read first (`loadCheckpointSlots`/
    /// `recoverActiveCheckpoint`/`adoptIndexPublicationHeader`, exactly
    /// `refreshIfWriterBaseStale`'s own in-process staleness fix, reused
    /// here for the cross-process case) -- this instance's own real-page
    /// reads must follow the new roots, not the stale ones it opened or
    /// last refreshed with. Either way, once the overlay is caught up,
    /// `self.header.checkpoints[active].commit_sequence` is bumped to the
    /// new `durable_sequence` -- the same "provisional, no real pages
    /// touched" trick an ordinary redo commit already applies to its own
    /// writer (`publishCheckpoint`'s redo branch) -- so overlay-aware
    /// reads (`redoOverlayEntry`'s own `checkpoint.commit_sequence` bound)
    /// actually see the records this call just applied.
    pub fn refreshCrossProcessRedoOverlay(self: *NativeFile) !void {
        const redo: *RedoCommitState = if (self.redo) |*r| r else return error.InvalidTransactionState;
        const region = (try self.regionForInode()) orelse return;
        const io = self.runtimeIo();
        const entry = self.inode_lock_ref.load(.acquire) orelse return error.InvalidTransactionState;

        const slot = self.cross_process_redo_reader_slot orelse blk: {
            const pid: u32 = @bitCast(std.c.getpid());
            const claimed = try region.claimReaderSlot(pid);
            self.cross_process_redo_reader_slot = claimed;
            break :blk claimed;
        };
        // Pin at what we already have *before* reading anything new.
        region.pinReader(slot, @max(redo.durable_sequence, 1));

        const published = region.readLogState();

        // §9.3b "re-open semantics": the real on-disk checkpoint has
        // moved since this instance last synced with it. Re-read it
        // (roots, page_count, manifest -- real fields, not the logical
        // watermark bumped below) before anything else, the same
        // in-process staleness fix `refreshIfWriterBaseStale` already
        // applies, triggered here by the region's published watermark
        // instead of `inode_lock.committedSequence`.
        if (published.checkpoint_sequence > redo.checkpoint_sequence) {
            var header_bytes: [header_size]u8 = undefined;
            try readHeaderExactAt(self.file, io, &header_bytes);
            var header = try decodeHeader(&header_bytes);
            const file_size = (try self.file.stat(io)).size;
            header.checkpoints = loadCheckpointSlots(self.file, io, header.page_size, file_size);
            const recovered = try recoverActiveCheckpoint(self.file, io, header, file_size, false);
            header.active_checkpoint = recovered.index;
            try self.adoptIndexPublicationHeader(header);
            // perf/lwa-fold-boundary: `commit_sequence` is the writer's
            // *tip*, not its fold boundary -- the same distinction
            // `recoverRedoLog` makes on a cold open. `redo_folded_through`
            // just came back from the on-disk slot this re-read loaded,
            // so it is this process's own correct, authoritative fold
            // boundary going forward, exactly as if this were a fresh
            // open.
            redo.checkpoint_sequence = self.header.checkpoints[self.header.active_checkpoint].redo_folded_through;
        }

        if (published.durable_sequence > redo.durable_sequence) {
            const ApplyCtx = struct {
                overlay: *redo_overlay.SharedRedoOverlay,
                fn onRecord(ctx_ptr: ?*anyopaque, record: redo_log.RecordView) anyerror!void {
                    const ac: *@This() = @ptrCast(@alignCast(ctx_ptr.?));
                    if (record.payload.len < CompactCheckpoint.encoded_size + 4) return error.InvalidNativeRedoRecord;
                    const logical_len = std.mem.readInt(u32, record.payload[CompactCheckpoint.encoded_size..][0..4], .little);
                    const logical_start = CompactCheckpoint.encoded_size + 4;
                    if (logical_start + logical_len > record.payload.len) return error.InvalidNativeRedoRecord;
                    try ac.overlay.decodeLogicalMutationsPayload(std.heap.page_allocator, record.payload[logical_start..][0..logical_len], record.commit_sequence);
                    try ac.overlay.decodeRedoGroupPayload(std.heap.page_allocator, record.payload[logical_start + logical_len ..]);
                }
            };

            const ReplayCtx = struct {
                file: *NativeFile,
                io: std.Io,
                start_after_sequence: u64,
                outcome: redo_log.ReplayOutcome = undefined,
                fn run(rc: *@This(), overlay: *redo_overlay.SharedRedoOverlay) anyerror!void {
                    var actx: ApplyCtx = .{ .overlay = overlay };
                    rc.outcome = try redo_log.replay(rc.file.allocator, rc.file.file, rc.io, rc.file.header.redo_log_offset, rc.file.header.redo_log_capacity, rc.start_after_sequence, ApplyCtx.onRecord, &actx);
                    if (rc.outcome.stop_reason == .corrupt_record) return error.NativeRedoLogCorrupt;
                }
            };
            // Records at or below the adopted checkpoint's fold boundary are
            // already in its tree. Replaying from an older durable sequence
            // instead walks into the sequence a deferred fold consumed
            // without appending a record, which reads as a gap
            // (`NativeRedoLogCorrupt`).
            var rctx: ReplayCtx = .{ .file = self, .io = io, .start_after_sequence = @max(redo.durable_sequence, redo.checkpoint_sequence) };
            try inode_lock.withRedoOverlayLock(entry, io, &rctx, ReplayCtx.run);

            const outcome = rctx.outcome;
            redo.durable_sequence = outcome.last_sequence orelse redo.durable_sequence;
            redo.writer = redo_log.Writer.initAt(self.file, io, self.header.redo_log_offset, self.header.redo_log_capacity, outcome.valid_bytes, outcome.last_sequence);
        }

        // Provisional bump, exactly as an ordinary redo commit already
        // does for its own writer: no real pages touched, just the
        // logical watermark overlay-aware reads compare against.
        self.header.checkpoints[self.header.active_checkpoint].commit_sequence = redo.durable_sequence;

        // Advance our pin to match what we just safely applied.
        region.pinReader(slot, @max(redo.durable_sequence, 1));
    }

    fn createWithMode(
        allocator: Allocator,
        path: []const u8,
        exclusive: bool,
        no_sync: bool,
        resource_manager: ?*resource_manager_mod.ResourceManager,
        writer_lock_marker: []const u8,
        indexed: bool,
        full_fsync: bool,
    ) !NativeFile {
        var io_impl = threaded_io_limits.initService(allocator);
        errdefer io_impl.deinit();
        return try createWithRuntime(allocator, path, exclusive, no_sync, resource_manager, writer_lock_marker, io_impl, null, indexed, full_fsync);
    }

    fn createWithRuntime(
        allocator: Allocator,
        path: []const u8,
        exclusive: bool,
        no_sync: bool,
        resource_manager: ?*resource_manager_mod.ResourceManager,
        writer_lock_marker: []const u8,
        io_impl: std.Io.Threaded,
        borrowed_io: ?std.Io,
        indexed: bool,
        full_fsync: bool,
    ) !NativeFile {
        var owned_io_impl = io_impl;
        const io = borrowed_io orelse owned_io_impl.io();

        // Reserved up front, before anything below -- including a
        // replacement create's own rename-into-place -- commits anything
        // irreversible: an allocation failure here must still be a clean,
        // pre-replacement failure ("lite allocator v4 failed replacement
        // create preserves original"), not an error returned after the
        // original file has already been replaced on disk. Moved into
        // `result.manifest_builder` at the final `return` below, once
        // construction can no longer fail; `errdefer` only needs to cover
        // the window before that move.
        var manifest_builder_reservation: ManifestBuilder = .{};
        // No `NativeFile` exists yet to carry a per-instance
        // `manifest_commits_enabled` -- every file begins life with
        // manifest commits enabled (the default); a redo-log file's own
        // `enableRedoLog` disables them afterward, on the fully
        // constructed value, same as it also replaces this reservation's
        // work with nothing to track.
        try manifest_builder_reservation.reserveCapacity(allocator);
        errdefer manifest_builder_reservation.deinit(allocator);

        const owned_path = try allocator.dupe(u8, path);
        errdefer allocator.free(owned_path);

        const writer_lock = try acquireWriterLock(allocator, io, path);
        var writer_lock_file = writer_lock.file;
        errdefer writer_lock_file.close(io);
        if (writer_lock_marker.len > 0) {
            try writer_lock_file.writePositionalAll(io, writer_lock_marker, 0);
            try writer_lock_file.setLength(io, writer_lock_marker.len);
            if (!no_sync) try writer_lock_file.sync(io);
        }

        var encoded: [header_size]u8 = undefined;
        encodeHeader(&encoded, .{});

        const replace_existing = !exclusive and pathExists(io, path);
        const replacement_path = if (replace_existing)
            try realPathAlloc(allocator, io, path)
        else
            null;
        defer if (replacement_path) |canonical| allocator.free(canonical);
        const create_target = if (replacement_path) |canonical| canonical else path;
        const staging_path = if (replace_existing)
            try std.fmt.allocPrint(allocator, "{s}.tmp-aflite-create", .{create_target})
        else
            null;
        defer if (staging_path) |tmp_path| allocator.free(tmp_path);
        errdefer if (staging_path) |tmp_path| deleteFilePath(io, tmp_path) catch {};

        // Reinitializing an existing artifact is an atomic generation swap.
        // Truncating the existing inode would corrupt snapshots held by
        // concurrent read-only processes, whose shared lock intentionally
        // permits an append-only writer.
        const create_path = staging_path orelse create_target;
        var file = try createDataFile(io, create_path, .{
            .truncate = true,
            .exclusive = exclusive,
        });
        var file_open = true;
        errdefer if (file_open) file.close(io);

        try file.writePositionalAll(io, &encoded, 0);
        // Reserve both slot pages' room up front (zero-filled), so even the
        // non-indexed bootstrap below -- which only writes slot 0 -- leaves
        // a file whose length already matches its checkpoint's page_count.
        // Slot 1 reads back as structurally invalid (an all-zero page fails
        // decodePagePayload's magic check) until something actually
        // publishes to it.
        try file.setLength(io, reserved_header_pages * @as(u64, default_page_size));
        var initialized_header: Header = .{};
        {
            var slot_buf: [max_page_size]u8 = undefined;
            const slot_page = slot_buf[0..default_page_size];
            encodeCheckpointSlotPage(slot_page, initialized_header.checkpoints[0]);
            try file.writePositionalAll(io, slot_page, slotPhysicalPage(0) * @as(u64, default_page_size));
        }
        if (indexed) {
            // Finish every fallible initialization step on the private inode.
            var staged = NativeFile{ .allocator = allocator, .io_impl = undefined, .borrowed_io = io, .path = owned_path, .file = file, .header = .{}, .read_only = false, .no_sync = no_sync, .page_cache_enabled = .init(false) };
            defer staged.invalidateLedger();
            defer staged.page_cache.deinit(allocator);
            // `staged` never goes through `close()` (it shares `file`/`path`/
            // `io_impl` with the real `result` built below, so closing it
            // here would close the file out from under that later value).
            // Its commits during `initializeIndexedAllocator` still run the
            // ordinary transaction path, so with manifest commits enabled
            // they accumulate into `staged.manifest_builder` exactly like
            // any other writer -- a non-durable intermediate commit, or a
            // durable one that stayed presynced, can leave entries behind
            // with no later durable publish on this same value to reset
            // them. Free that tracking state explicitly; it is never
            // referenced again once `initialized_header` is captured below.
            defer staged.manifest_builder.deinit(allocator);
            try staged.initializeIndexedAllocator();
            initialized_header = staged.header;
        }
        if (!no_sync) {
            try file.sync(io);
        }
        if (staging_path) |tmp_path| {
            file.close(io);
            file_open = false;
            renameFilePath(io, tmp_path, create_target) catch |err| {
                deleteFilePath(io, tmp_path) catch {};
                return err;
            };
            if (!no_sync) try fs_paths.syncDirPortable(io, std.fs.path.dirname(create_target) orelse ".");
            file = (try openDataFile(io, path, .writer, false)).file;
            file_open = true;
        } else if (!no_sync) {
            try fs_paths.syncDirPortable(io, std.fs.path.dirname(create_target) orelse ".");
        }

        // Only now, with the data file in its final place at `path`, can
        // this resolve an inode to register with the process-wide lock
        // registry (`inode_lock.zig`) -- `path` may not have existed at
        // all before the staging/rename dance above for a first-time
        // create.
        const inode_entry = try inode_lock.open(io, path);
        errdefer inode_lock.unref(inode_entry, io);
        // See the matching comment in `openWithRuntime`: set the region up
        // eagerly here too, so a freshly created file never defers that
        // one-time cost into its first page-reusing commit either.
        _ = inode_lock.ensureRegion(inode_entry, io) catch {};

        var result = NativeFile{
            .allocator = allocator,
            .io_impl = owned_io_impl,
            .borrowed_io = borrowed_io,
            .path = owned_path,
            .file = file,
            .writer_lock_file = writer_lock_file,
            .inode_lock_ref = .init(inode_entry),
            .header = initialized_header,
            .read_only = false,
            .no_sync = no_sync,
            .page_cache_enabled = .init(true),
            .durability_policy = if (borrowed_io == null)
                (if (full_fsync) .full_fsync else .default)
            else
                null,
        };
        if (resource_manager) |manager| result.page_cache.attachResourceManager(manager);
        // Already reserved (see this function's own top, before any of
        // the replacement/rename dance above could commit) -- moved in
        // now that construction can no longer fail. Pre-paying for this
        // one allocation at open, rather than lazily on the first commit,
        // is what lets a caller tracking "no allocation during ordinary
        // writes" (see "lite native page batches coalesce runs without
        // heap allocation and preserve gaps") start measuring right after
        // this call returns, before issuing any writes.
        result.manifest_builder = manifest_builder_reservation;
        return result;
    }

    /// Relinquish lifetime ownership after the embedded connection finishes initialization.
    /// No mutation may run until its caller holds lockWriterPath again.
    pub fn releaseWriterOwnership(self: *NativeFile) void {
        if (self.writer_lock_file) |file| file.close(self.runtime());
        self.writer_lock_file = null;
        self.externally_locked = true;
    }

    pub fn close(self: *NativeFile) void {
        std.debug.assert(self.reader_window_depth == 0);
        const io = self.runtimeIo();
        if (self.reader_fence) |fence| self.reader_coordinator.?.unregister(fence);
        if (self.transaction_writes) |writes| writes.deinit(self.allocator);
        self.transaction_writes = null;
        self.manifest_builder.deinit(self.allocator);
        // Must run before `redo.deinit` just below, which frees the shared
        // overlay this pin lives on.
        if (self.open_time_overlay_pin_mark) |mark| {
            if (self.redo) |*redo| redo.shared.unpin(io, mark);
            self.open_time_overlay_pin_mark = null;
        }
        if (self.redo) |*redo| redo.deinit(self.allocator);
        self.redo = null;
        deinitNamespaceDirectory(self.allocator, &self.namespace_directory_cache);
        self.page_cache.deinit(self.allocator);
        self.invalidateLedger();
        if (self.writer_lock_file) |lock_file| {
            lock_file.close(io);
        }
        // Defensive: every acquirer above already pairs its own
        // acquire/release (reader_window_lock is asserted empty just
        // above; acquireReaderFence/captureFullReadSnapshot pair through
        // releaseReaderFence). This only catches a caller that skipped
        // that pairing instead of relying on it.
        if (self.reader_fence_lock) |handle| {
            handle.release(io);
            self.reader_fence_lock = null;
        }
        // Must run before the `inode_lock.unref` below: that call can be
        // the one that drops this inode's `Entry` refcount to zero and
        // frees it, so releasing this pin against it has to happen first.
        if (self.reader_pin_entry) |entry| {
            inode_lock.unpinReader(entry, io, .{ .data = self.reader_pin_sequence, .metadata = self.reader_pin_sequence });
            self.reader_pin_entry = null;
        }
        // Same ordering requirement as `reader_pin_entry` just above:
        // releasing this slot needs `regionForInode()`, which needs
        // `self.inode_lock_ref` still live, so it must run before the
        // `inode_lock.unref` below.
        if (self.cross_process_redo_reader_slot) |slot| {
            if (self.regionForInode() catch null) |region| {
                region.unpinReader(slot);
                region.releaseReaderSlot(slot);
            }
            self.cross_process_redo_reader_slot = null;
        }
        if (self.inode_lock_ref.load(.acquire)) |entry| {
            inode_lock.unref(entry, io);
            self.inode_lock_ref.store(null, .release);
        }
        self.file.close(io);
        self.allocator.free(self.path);
        if (self.borrowed_io == null) self.io_impl.deinit();
        self.* = undefined;
    }

    pub fn usesBorrowedIo(self: *const NativeFile) bool {
        return self.borrowed_io != null;
    }

    /// Returns the runtime used for file operations and synchronization. The
    /// returned interface is borrowed from this file and is invalid after
    /// `close`.
    pub fn runtime(self: *NativeFile) std.Io {
        return self.borrowed_io orelse self.io_impl.io();
    }

    fn runtimeIo(self: *NativeFile) std.Io {
        return self.runtime();
    }

    pub fn activeCheckpoint(self: *const NativeFile) CheckpointSlot {
        return self.header.checkpoints[self.header.active_checkpoint];
    }

    /// The logical commit sequence: whether a commit has happened, or
    /// advanced, independent of whether its own physical checkpoint slot
    /// page or redo-log record has actually landed on disk yet. Use this
    /// wherever code (or a test) means "did a commit happen, or
    /// advance" -- not `activeCheckpoint().commit_sequence` directly,
    /// which only answers a physical-layout question (and, for a
    /// redo-log file, may not move at all for a commit that only
    /// appended to the log: `checkpointRedoLog`, not every commit, is
    /// what advances the physical checkpoint slot there).
    ///
    /// In redo-log mode this is `self.redo.?.durable_sequence` -- the
    /// log's own latest durable (appended and synced) record, which is
    /// what actually advances on every synced commit. Otherwise this
    /// mirrors `Store.durableSequence`'s own distinction between a
    /// ride-along-advanced `activeCheckpoint()` and the actually-durable
    /// `durable_header`: `commitTransactionWithDurability`'s
    /// `deferred_publication` branch writes `next` straight into
    /// `self.header.checkpoints[active]` with no sync at all, leaving
    /// `durable_header` holding the last checkpoint that *was* actually
    /// synced -- whenever `durable_header` is set, that, not the
    /// ride-along-advanced `activeCheckpoint()`, is the durable sequence.
    pub fn committedSequence(self: *const NativeFile) u64 {
        if (self.redo) |redo| return redo.durable_sequence;
        if (self.durable_header) |durable| return durable.checkpoints[durable.active_checkpoint].commit_sequence;
        return self.activeCheckpoint().commit_sequence;
    }

    /// Rebind a borrowed index writer after its owner has verified the inode,
    /// catalog epoch and unchanged immutable index inputs under a writer lease.
    /// The newest allocator state must accompany the newest primary roots.
    pub fn adoptIndexPublicationHeader(self: *NativeFile, header: Header) !void {
        if (self.transaction_header != null or self.durable_header != null or self.checkpoint_publication_uncertain or
            self.header.page_size != header.page_size or self.header.indexed_reclamation != header.indexed_reclamation) return error.EnrichmentWaitCanceled;
        if (std.meta.eql(self.header, header)) return;
        // perf/lwa-fold-churn: under the redo log, this rebind runs on
        // essentially every commit (`self.header` changes every commit --
        // `commit_sequence` alone guarantees that), but almost none of
        // those commits touch the allocator's own free map at all. Only
        // `AllocatorProofIdentity` (`active_checkpoint`, `free_map_root_page`,
        // `page_count`, `redo_folded_through` -- see that type's own doc
        // comment, same reasoning as 105b6eaa3d's fix one layer up in
        // `Owner.verifyAllocatorAssumeLocked`) says whether the free map
        // this instance already verified is still the free map on disk.
        // Unconditionally clearing `free_pages_verified` here regardless
        // -- as every commit used to -- threw away an otherwise-still-good
        // verification on every redo-only commit, forcing
        // `inheritAllocatorCertificate`/the full ledger walk to redo work
        // that had nothing left to find; under a steadily re-folding log
        // (the companion fix in `maybeAutoCheckpointRedoLog`/
        // `checkpointRedoLogWithDurability`) that meant *every* commit,
        // not just an occasional one, which is what kept the background
        // allocator-verification walk permanently busy and, by holding a
        // verification snapshot's own reader pin open across that
        // perpetual re-walk, kept `checkpointRedoLogWithDurability`'s own
        // `pinned_below` gate blocked too -- the two problems reinforced
        // each other. When the identity hasn't moved, skip straight to
        // adopting the new header: no ledger invalidation, no clearing of
        // `free_pages_verified`/`allocator_verification_base`, nothing for
        // a pending verification to lose.
        const identity_unchanged = std.meta.eql(allocatorProofIdentity(self.header), allocatorProofIdentity(header));
        if (identity_unchanged) {
            self.allocator_rebase_header = null;
        } else {
            self.allocator_rebase_header = if (self.free_pages_verified and self.ledger != null) self.header else null;
            if (self.allocator_rebase_header == null) self.invalidateLedger();
            self.free_pages_verified = false;
            self.allocator_verification_base = null;
        }
        self.page_cache.clear(self.allocator);
        if (self.secondary_page_cache) |cache| cache.clear(self.allocator);
        self.namespace_directory_cache_root = std.math.maxInt(u64);
        self.namespace_directory_delta_depth = 0;
        deinitNamespaceDirectory(self.allocator, &self.namespace_directory_cache);
        self.namespace_directory_cache = .empty;
        self.header = header;
    }

    /// The real fix for the stale-writer corruption (`UnexpectedNativePageKind`
    /// seen under sustained concurrent Lite load): a second `NativeFile`
    /// instance on the same inode in this process -- most commonly a
    /// maintenance turn's own detached snapshot (`refreshMaintenanceSnapshot`),
    /// but potentially a writer-lease handoff's receiving instance too -- can
    /// fall behind another instance's commits and still go on to allocate or
    /// reuse pages out of its own now-stale free map. By the time
    /// `publishCheckpoint`'s own backstop assertion would catch that, the
    /// damage (a page another commit already made live has been reused and
    /// overwritten) is already done. The fix is to catch it here instead,
    /// before this instance gains the right to allocate or reuse anything:
    /// every entry point that leads to `pageAllocatorFromFreeMap`/
    /// `pageAllocatorFromFreeMapWithProof` for an ordinary write
    /// (`beginTransaction`, which `reclaimPagesImpl` also funnels through)
    /// or for vacuum (`vacuumWithCancel`) calls this first.
    ///
    /// If this instance's own base (its currently active checkpoint) is
    /// behind the inode registry's shared, process-wide latest known-durable
    /// sequence, refresh in place: re-read the header and checkpoint slots
    /// from disk (cheap -- the same file's pages are already in the OS page
    /// cache even for an unsynced ride-along commit) and pick the active
    /// checkpoint exactly as a fresh open would, then reuse
    /// `adoptIndexPublicationHeader`'s cache/ledger invalidation to rebind
    /// this instance to it, exactly as a borrowed index writer rebinds to
    /// its owner's newest header. Never truncates: unlike `open`'s own
    /// recovery, this is not resolving a crash, so a rejected candidate's
    /// tail is left alone for whichever instance still needs it.
    fn refreshIfWriterBaseStale(self: *NativeFile) !void {
        const entry = self.inode_lock_ref.load(.acquire) orelse return;
        const latest = inode_lock.committedSequence(entry);
        // perf/lwa-grouped-stall: `base` below (the checkpoint's own
        // `commit_sequence`) and `redo.writer.last_sequence` (this
        // instance's redo-log continuity counter, independently checked
        // by `redo_log.Writer.append`) are two different pieces of state
        // that can desync even when `base` itself already matches
        // `latest` -- confirmed live: `base == latest == 57` while
        // `redo.writer.last_sequence` was still 55 on a maintenance
        // owner's repeatedly-reopened `NativeFile` instance, so every
        // later append computed `commit_sequence = base + 1 = 58`,
        // which failed `58 != 55 + 1` (`error.SequenceOutOfOrder`,
        // surfacing as the far less specific `error.OutcomeUnknown`)
        // forever -- nothing ever advanced the redo writer's own counter
        // to match, because the full refresh below only runs when `base`
        // itself is stale, and the `base >= latest` early return skipped
        // past this instance's own now-separately-stale redo counter.
        // Sync it unconditionally and first. The logical overlay for this
        // inode is already shared and current across every same-process
        // instance (`inode_lock.Entry`'s one `redo.shared`, per
        // `recoverRedoLog`'s own doc comment -- "there is nothing to
        // replay here, only this instance's own bookkeeping to catch
        // up"), so no second populate of it is needed; but `redo.writer`
        // is NOT shared -- its `tail` is this instance's own physical
        // append cursor, and bumping only `last_sequence`/`durable_sequence`
        // without it left `tail` pointing right after this instance's own
        // last-seen record, so its next append wrote over bytes a
        // different, more current instance had already physically
        // written for the sequences in between (`error.NativeRedoLogCorrupt`
        // on replay, caught live the first time this fix tried the
        // `last_sequence`-only version). A no-op-callback replay of the
        // valid prefix recomputes the real `tail`/`last_sequence` the
        // same way a cold `recoverRedoLog` open would, without re-applying
        // any record content (already shared and current).
        const base = self.activeCheckpoint().commit_sequence;
        const redo_stale = if (self.redo) |*redo| latest > (redo.writer.last_sequence orelse 0) else false;
        if (base >= latest and !redo_stale) return;
        const io = self.runtime();
        // perf/lwa-xproc-redocorrupt: read the real on-disk checkpoint (and
        // thus the authoritative fold boundary, `redo_folded_through`)
        // before, not after, the redo writer's own no-op replay below. A
        // fold whose physical log reclaim another same-process instance
        // deferred (a reader pinned behind it) consumes a commit sequence
        // without ever appending a log record for it, so the log skips
        // that sequence (`checkpointRedoLog`'s own "consumed-but-unlogged
        // sequence" case, design doc §9.3b). Replaying from this
        // instance's own, still-stale `redo.checkpoint_sequence` -- the
        // original ordering here, which only refreshed it afterward, down
        // in the `base`-staleness branch below -- walks straight into that
        // skipped sequence and reports it as `error.NativeRedoLogCorrupt`:
        // the same class of bug `refreshCrossProcessRedoOverlay` was fixed
        // for (commit `9a31bd7778`), just reached from this in-process
        // staleness path instead of the cross-process one.
        var header_bytes: [header_size]u8 = undefined;
        try readHeaderExactAt(self.file, io, &header_bytes);
        var header = try decodeHeader(&header_bytes);
        const file_size = (try self.file.stat(io)).size;
        header.checkpoints = loadCheckpointSlots(self.file, io, header.page_size, file_size);
        const recovered = try recoverActiveCheckpoint(self.file, io, header, file_size, false);
        header.active_checkpoint = recovered.index;
        if (self.redo) |*redo| {
            const disk_folded_through = header.checkpoints[header.active_checkpoint].redo_folded_through;
            if (disk_folded_through > redo.checkpoint_sequence) redo.checkpoint_sequence = disk_folded_through;
            const current = redo.writer.last_sequence orelse 0;
            if (latest > current) {
                const Noop = struct {
                    fn onRecord(_: ?*anyopaque, _: redo_log.RecordView) anyerror!void {}
                };
                // Records at or below the adopted checkpoint's fold
                // boundary are already in its tree -- start after the
                // later of the two, exactly `refreshCrossProcessRedoOverlay`'s
                // own fix.
                const outcome = try redo_log.replay(self.allocator, self.file, io, self.header.redo_log_offset, self.header.redo_log_capacity, @max(redo.durable_sequence, redo.checkpoint_sequence), Noop.onRecord, null);
                if (outcome.stop_reason == .corrupt_record) return error.NativeRedoLogCorrupt;
                redo.writer.tail = outcome.valid_bytes;
                redo.writer.last_sequence = outcome.last_sequence;
                if (latest > redo.durable_sequence) redo.durable_sequence = latest;
            }
        }
        if (base >= latest) return;
        // perf/lwa-stale-base: for a redo-log file, the on-disk checkpoint
        // slot's own `commit_sequence` just read above is only the last
        // real *fold* boundary (`recoverRedoLog`'s own `folded_through`) --
        // every ordinary redo-diverted commit since then only ever
        // advanced the logical tip inside the shared, in-process overlay
        // (`inode_lock.Entry.redo_overlay`) and this inode's registry
        // (`inode_lock.committedSequence`, this call's own `latest`),
        // never the physical slot. Trusting the raw on-disk value here
        // regresses this instance's base *below* where it already
        // correctly was -- confirmed live via the debug log two lines
        // down firing with `old_base=90 new_base=1 registry_latest=91`:
        // this same instance's own prior commits had already kept
        // `self.header` at the correct logical 90, and this "refresh",
        // meant to fix a one-commit-behind staleness, instead clobbered
        // it with the ancient fold boundary -- so the very next commit's
        // `publishCheckpoint` backstop panicked against a base this call
        // itself had just regressed. Bump the recovered slot's own
        // `commit_sequence` up to `latest` instead -- exactly the
        // "provisional, no real pages touched" bump an ordinary redo
        // commit already applies to its own writer (`publishCheckpoint`'s
        // redo branch) and `refreshCrossProcessRedoOverlay`'s own
        // cross-process counterpart applies after replaying the overlay.
        // The shared overlay this instance's own `self.redo.shared`
        // already points at (same `inode_lock.Entry`, same process) is
        // already current -- there is nothing to replay here, only this
        // instance's own bookkeeping to catch up.
        if (header.redo_log_capacity != 0 and header.checkpoints[header.active_checkpoint].commit_sequence < latest) {
            header.checkpoints[header.active_checkpoint].commit_sequence = latest;
        }
        const new_sequence = header.checkpoints[header.active_checkpoint].commit_sequence;
        std.log.debug("lite: NativeFile instance refreshed a stale writer base (path={s} ptr={*} old_base={d} new_base={d} registry_latest={d})", .{ self.path, self, base, new_sequence, latest });
        try self.adoptIndexPublicationHeader(header);
        if (self.redo) |*redo| {
            // Mirror `refreshCrossProcessRedoOverlay`'s own bookkeeping:
            // the fold boundary just read from disk is this process's own
            // correct, authoritative one going forward, and `durable_sequence`/
            // `writer.last_sequence` must agree with the bumped logical tip
            // above so the next append's continuity check expects
            // `latest + 1`, not a value already behind what the shared
            // overlay carries.
            redo.checkpoint_sequence = header.checkpoints[header.active_checkpoint].redo_folded_through;
            if (latest > redo.durable_sequence) {
                redo.durable_sequence = latest;
                redo.writer.last_sequence = latest;
            }
        }
    }

    /// Carry pending lineage across identical runtime generations, or inherit
    /// a completed proof for append-only descendants of its captured base.
    /// The caller serializes publications; foreign headers, inode changes
    /// and uncertainty reject inheritance.
    /// A completed allocator proof of `header` on the file with `inode`,
    /// kept after its reader is gone (for example across a busy yield that
    /// happened before the proof could be transferred).
    pub const AllocatorProofReceipt = struct {
        header: Header,
        inode: @FieldType(std.Io.File.Stat, "inode"),
    };

    pub fn allocatorProofReceipt(self: *NativeFile) !?AllocatorProofReceipt {
        if (!self.free_pages_verified) return null;
        return .{ .header = self.header, .inode = (try self.file.stat(self.runtime())).inode };
    }

    /// perf/lwa-proof-fork: the exact state an allocator free-page proof's
    /// validity depends on -- not the whole `Header`. `commit_sequence`
    /// (and, for a redo-log file, the whole checkpoint slot payload)
    /// advances on *every* commit (`commitTransactionWithDurability`'s
    /// ordinary redo-log append stamps `self.header.checkpoints[active] =
    /// checkpoint` regardless of whether anything page-shaped happened),
    /// but a redo-only commit -- everything diverted into the log, no
    /// page allocation, no ledger mutation -- never touches the free map
    /// a completed proof walked. Comparing whole headers (`std.meta.eql`)
    /// discarded a still-correct proof after every such commit, forcing
    /// `captureAllocatorVerificationSnapshot` to re-walk the ledger from
    /// scratch. These three fields are exactly what the walk verified:
    /// `free_map_root_page` is the ledger's own copy-on-write root (any
    /// real mutation of the free map moves it), `page_count` is the
    /// universe of pages the ledger accounts for (a page-shaped redo
    /// diversion -- an external-value chain bypassing the ledger
    /// entirely, see `redo_folded_through`'s own doc comment -- can
    /// advance this without the ledger ever knowing), and
    /// `redo_folded_through` is the fold boundary the walk's own
    /// snapshot was pinned to. `active_checkpoint` is included so a real
    /// checkpoint publish that ping-pongs slots is never mistaken for a
    /// same-slot republish even in the (page-id-collision) limit.
    /// Whatever else a commit changes (`commit_sequence`, the primary/
    /// catalog/index-catalog/namespace-directory roots, the manifest
    /// descriptor) is irrelevant to whether the free map this proof
    /// covers is still the free map on disk.
    pub const AllocatorProofIdentity = struct {
        active_checkpoint: u8,
        free_map_root_page: u64,
        page_count: u64,
        redo_folded_through: u64,
    };

    pub fn allocatorProofIdentity(header: Header) AllocatorProofIdentity {
        const checkpoint = header.checkpoints[header.active_checkpoint];
        return .{
            .active_checkpoint = header.active_checkpoint,
            .free_map_root_page = checkpoint.free_map_root_page,
            .page_count = checkpoint.page_count,
            .redo_folded_through = checkpoint.redo_folded_through,
        };
    }

    /// Same acceptance as `inheritAllocatorVerification` from a verified
    /// owner: the identical generation, or a descendant of the proof's base.
    /// Callers fence it the same way, under the writer lease.
    pub fn inheritAllocatorProofReceipt(self: *NativeFile, receipt: AllocatorProofReceipt) !void {
        if (self.free_pages_verified or self.transaction_header != null or self.durable_header != null or
            self.checkpoint_publication_uncertain) return;
        const identical = std.meta.eql(allocatorProofIdentity(self.header), allocatorProofIdentity(receipt.header));
        const descendant = if (self.allocator_verification_base) |base| std.meta.eql(allocatorProofIdentity(base), allocatorProofIdentity(receipt.header)) else false;
        if (!identical and !descendant) return;
        if ((try self.file.stat(self.runtime())).inode != receipt.inode) return;
        self.free_pages_verified = true;
        self.allocator_verification_base = null;
    }

    pub fn inheritAllocatorVerification(self: *NativeFile, owner: *NativeFile) !void {
        if (!owner.free_pages_verified and (self.free_pages_verified or owner.allocator_verification_base == null)) return;
        if (!std.mem.eql(u8, self.path, owner.path) or owner.transaction_header != null or owner.durable_header != null or
            owner.checkpoint_publication_uncertain or self.transaction_header != null or self.durable_header != null or
            self.checkpoint_publication_uncertain) return;
        const identical = std.meta.eql(allocatorProofIdentity(self.header), allocatorProofIdentity(owner.header));
        const descendant = if (self.allocator_verification_base) |base| std.meta.eql(allocatorProofIdentity(base), allocatorProofIdentity(owner.header)) else false;
        if (!identical and !descendant) return;
        if ((try self.file.stat(self.runtime())).inode != (try owner.file.stat(owner.runtime())).inode) return;
        if (!owner.free_pages_verified) {
            // Reopening the identical generation must retain the pending
            // append-only lineage too. This grants no reuse: only completion
            // of the independently fenced original proof can verify it.
            if (identical and !self.free_pages_verified and owner.allocator_verification_base != null)
                self.allocator_verification_base = owner.allocator_verification_base;
            return;
        }
        self.free_pages_verified = true;
        self.allocator_verification_base = null;
    }

    /// Move an exclusively owned verifier's cache before index initialization
    /// can publish leases. Verification inheritance alone deliberately does not
    /// share mutable state with snapshots or retired serving runtimes.
    pub fn takeVerifiedAllocator(self: *NativeFile, donor: *NativeFile) !bool {
        if (self == donor or !donor.free_pages_verified or donor.ledger == null or
            !std.meta.eql(self.allocator, donor.allocator) or
            !std.meta.eql(self.header, donor.header) or !std.mem.eql(u8, self.path, donor.path) or
            self.transaction_header != null or donor.transaction_header != null or
            self.durable_header != null or donor.durable_header != null or
            self.checkpoint_publication_uncertain or donor.checkpoint_publication_uncertain) return false;
        if ((try self.file.stat(self.runtime())).inode != (try donor.file.stat(donor.runtime())).inode) return false;
        const state = donor.ledger.?;
        if (state.root_page != self.activeCheckpoint().free_map_root_page or
            state.changes.count() != 0 or state.added.items.len != 0 or state.completed.items.len != 0) return false;
        self.invalidateLedger();
        self.ledger = state;
        donor.ledger = null;
        self.allocator_work.absorb(&donor.allocator_work);
        self.allocator_work.cache_transfers +|= 1;
        self.free_pages_verified = true;
        self.allocator_verification_base = null;
        return true;
    }

    /// The caller exclusively owns the donor cache. This only transfers a
    /// validation base: it grants no authority to allocate at the new tip.
    pub fn takeAllocatorRebaseBase(self: *NativeFile, donor: *NativeFile) !bool {
        if (self == donor or !donor.free_pages_verified or donor.ledger == null or
            !std.meta.eql(self.allocator, donor.allocator) or !std.mem.eql(u8, self.path, donor.path) or
            !self.header.indexed_reclamation or !donor.header.indexed_reclamation or
            self.header.page_size != donor.header.page_size or
            self.activeCheckpoint().commit_sequence < donor.activeCheckpoint().commit_sequence or
            self.transaction_header != null or donor.transaction_header != null or
            self.durable_header != null or donor.durable_header != null or
            self.checkpoint_publication_uncertain or donor.checkpoint_publication_uncertain) return false;
        if ((try self.file.stat(self.runtime())).inode != (try donor.file.stat(donor.runtime())).inode) return false;
        const state = donor.ledger.?;
        if (state.root_page != donor.activeCheckpoint().free_map_root_page or state.digest_cache == null or
            state.changes.count() != 0 or state.added.items.len != 0 or state.completed.items.len != 0) return false;
        self.invalidateLedger();
        self.ledger = donor.ledger;
        donor.ledger = null;
        self.allocator_work.absorb(&donor.allocator_work);
        self.allocator_work.cache_transfers +|= 1;
        self.allocator_rebase_header = donor.header;
        self.free_pages_verified = false;
        return true;
    }

    /// Like takeAllocatorRebaseBase, but copies the donor's ledger so the
    /// donor keeps its warm cache. Only for a cold receiver: an existing
    /// cache is never replaced. Grants no authority; the caller must still
    /// authenticate the rebased copy (inheritAllocatorCertificate).
    pub fn copyAllocatorRebaseBase(self: *NativeFile, donor: *NativeFile) !bool {
        if (self.ledger != null or self.free_pages_verified) return false;
        if (self == donor or !donor.free_pages_verified or donor.ledger == null or
            !std.meta.eql(self.allocator, donor.allocator) or !std.mem.eql(u8, self.path, donor.path) or
            !self.header.indexed_reclamation or !donor.header.indexed_reclamation or
            self.header.page_size != donor.header.page_size or
            self.activeCheckpoint().commit_sequence < donor.activeCheckpoint().commit_sequence or
            self.transaction_header != null or donor.transaction_header != null or
            self.durable_header != null or donor.durable_header != null or
            self.checkpoint_publication_uncertain or donor.checkpoint_publication_uncertain) return false;
        if ((try self.file.stat(self.runtime())).inode != (try donor.file.stat(donor.runtime())).inode) return false;
        const source = donor.ledger.?;
        if (source.root_page != donor.activeCheckpoint().free_map_root_page or source.digest_cache == null or
            source.changes.count() != 0 or source.added.items.len != 0 or source.completed.items.len != 0) return false;
        const state = try self.allocator.create(allocator_v4.State);
        errdefer self.allocator.destroy(state);
        state.* = try source.clone(self.allocator);
        self.invalidateLedger();
        self.ledger = state;
        self.allocator_work.cache_copies +|= 1;
        self.allocator_rebase_header = donor.header;
        return true;
    }

    /// Prepare reuse against a separately inode-fenced reader, without holding
    /// a caller's foreground publication gate. Publication must still compare
    /// the current inode and both checkpoints before using this proof.
    pub fn prepareAllocatorVerification(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !void {
        if (self.free_pages_verified) return;
        const reader = try self.allocatorVerificationSnapshot(cancel);
        defer {
            reader.close();
            self.allocator.destroy(reader);
        }
        try self.inheritAllocatorVerification(reader);
        if (!self.free_pages_verified) return error.EnrichmentWaitCanceled;
    }

    /// Owns an inode fence through proof publication. Close and destroy with
    /// this file's allocator. Keep the reader at a stable address because its
    /// page-cache reclamation callbacks can borrow it while the walk runs.
    pub fn allocatorVerificationSnapshot(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !*NativeFile {
        const reader = try self.captureAllocatorVerificationSnapshot(cancel);
        errdefer {
            reader.close();
            self.allocator.destroy(reader);
        }
        try reader.completeAllocatorVerification();
        return reader;
    }

    /// Capture only the immutable header/inode fence. The caller can release
    /// its foreground gate before walking the protected page graphs.
    ///
    /// `pin_read_checkpoint = true`: this reader's whole reason to exist is
    /// a long, unprotected walk (`completeAllocatorVerification`'s
    /// `validateIndexedAllocator`/`validateIndexedOwnership`, reading many
    /// data pages) that the caller deliberately runs *after* releasing the
    /// admission gate (`verifyAllocatorAssumeLocked`'s own comment: "Keep
    /// it outside both publication locks"), so a concurrent writer is free
    /// to keep committing and folding while this walk is in flight. Before
    /// this pin, nothing protected that walk's pages from exactly that
    /// fold -- the header-equality check below only catches a change that
    /// already happened by the time this function returns, not one that
    /// happens during the walk this reader exists to run (confirmed: the
    /// `benchcrash` sequential-batch repro's `UnexpectedNativePageKind`
    /// traced here, through `validateIndexedOwnership`'s own
    /// `decodePagePayload(raw, .data)`). Safe to hold for this reader's
    /// whole lifetime, unlike a cached, open-ended one
    /// (`initializeReadGenerationAssumeLocked`'s own): every caller closes
    /// this reader itself once its one walk finishes (`allocatorVerificationSnapshot`/
    /// `prepareAllocatorVerification`'s own `defer`), never retains or
    /// reuses it across turns.
    pub fn captureAllocatorVerificationSnapshot(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !*NativeFile {
        if (cancel) |token| try token.check();
        const reader = try self.allocator.create(NativeFile);
        errdefer self.allocator.destroy(reader);
        // perf/lwa-xproc-pagekind: `pin_read_checkpoint` only ever pins
        // `inode_lock.Entry.reader_pins` -- in-process, invisible to a
        // different OS process's own reclaim frontier
        // (`shared_lock_region.Region.minimumPinnedSequence`). This
        // reader's whole reason to exist is to walk the allocator/
        // ownership graph *after* `verifyAllocatorAssumeLocked` has
        // already released the writer lease (its own "keep it outside
        // both publication locks" comment), so a foreign process can
        // already be reclaiming while this walk is in flight. Passing
        // `self.reader_coordinator` through makes this open a real
        // `plain_reader` (`openWithRuntime`'s own gate: `read_only` and
        // neither `internal_reader` nor `externally_locked`, both unset
        // here), which claims and pins a shared-region reader-table slot
        // (§8.3) at open time -- the same primitive `captureFullReadSnapshot`
        // right below already engages via its own `coordinated` flag.
        // `openWithRuntime`'s own fallback (no coordinator, no region, or
        // the region's slot table exhausted) degrades to exactly today's
        // inode-only fence, never a reason to fail this open.
        reader.* = try NativeFile.openWithIo(self.allocator, self.runtime(), self.path, .{ .read_only = true, .pin_read_checkpoint = true, .reader_coordinator = self.reader_coordinator, .resource_manager = self.page_cache.resource_manager });
        errdefer reader.close();
        reader.page_cache_policy = .metadata_only;
        reader.allocator_cancel_token = cancel;
        if (!std.meta.eql(self.header, reader.header) or
            (try self.file.stat(self.runtime())).inode != (try reader.file.stat(reader.runtime())).inode) return error.EnrichmentWaitCanceled;
        self.allocator_verification_base = self.header;
        return reader;
    }

    /// Capture under the path-writer lease (or standalone writer ownership).
    /// Full scans need allocator metadata as well as logical data protected.
    /// Same-owner writers may suspend this inode lock only while both
    /// retirement frontiers retain the captured recovery slots.
    pub fn captureFullReadSnapshot(self: *NativeFile) !NativeFile {
        if (self.transaction_header != null or self.checkpoint_publication_uncertain) return error.FileBusy;
        // Deferred standalone images have unpublished roots. Preserve their
        // existing whole-inode protection until a durability barrier publishes
        // them; the shared coordinator only recognizes published headers.
        const coordinated = self.reader_coordinator != null and self.durable_header == null and !self.read_only;
        // Reader-pin registry (inode_lock.Entry.reader_pins): protects
        // this snapshot even when `coordinated` is false (no reader_coordinator
        // at all, or a deferred/read-only file -- exactly vacuum's own
        // verification snapshot's common case), which none of the other
        // reuse-safety mechanisms reach: a plain, uncoordinated reader
        // like this one never claims a `region` slot, and it is a
        // different `NativeFile` instance than whatever a `Store`'s own
        // `reader_frontier` atomic is wired into. Pin *before* opening
        // `reader` below, using `self`'s own currently-known checkpoint:
        // whatever `reader` actually resolves to a moment later can only
        // be the same sequence or a later one (checkpoints never move
        // backward), so this value is always a safe, if momentarily
        // conservative, lower bound -- closing the window a writer's
        // frontier computation could otherwise run through between
        // "the checkpoint `reader` will depend on becomes real" and "a
        // pin exists to protect it."
        const entry = self.inode_lock_ref.load(.acquire) orelse return error.InvalidTransactionState;
        const guard_sequence = self.activeCheckpoint().commit_sequence;
        const guard_pin: inode_lock.ReaderPin = .{ .data = guard_sequence, .metadata = guard_sequence };
        try inode_lock.pinReader(entry, self.runtime(), guard_pin);
        errdefer inode_lock.unpinReader(entry, self.runtime(), guard_pin);
        var reader = try NativeFile.openWithIo(self.allocator, self.runtime(), self.path, .{
            .read_only = true,
            .internal_reader = coordinated,
            .reader_coordinator = if (coordinated) self.reader_coordinator else null,
            .no_sync = self.no_sync,
            .resource_manager = self.page_cache.resource_manager,
        });
        errdefer reader.close();
        reader.reader_pin_entry = entry;
        reader.reader_pin_sequence = guard_sequence;
        const inode = (try reader.file.stat(reader.runtime())).inode;
        // §9.7a: a redo-log file's *inactive* checkpoint slot is never
        // synchronized once `enableRedoLog` bootstraps it -- ordinary
        // diverted commits and `publishCheckpoint`'s own redo branch only
        // ever touch `checkpoints[active_checkpoint]`; the other slot's
        // in-memory copy here (inherited from file-creation's bootstrap)
        // and whatever a fresh reopen actually decodes from that slot's
        // never-rewritten physical page can legitimately disagree with no
        // semantic change at all (confirmed: the only field that ever
        // differed in practice was that slot's stale `page_count`). A
        // byte-for-byte `std.meta.eql(self.header, reader.header)` would
        // treat that as "something changed concurrently" and wrongly
        // refuse this snapshot. For a redo-log file, compare the fields
        // that actually carry meaning instead -- `active_checkpoint`
        // (also covers the case where a real `checkpointRedoLog` commit
        // *did* run and legitimately flip slots) and the active slot's
        // own content, which is the only slot a redo-log file ever
        // publishes through. Every other field (`indexed_reclamation`,
        // `redo_log_offset`/`capacity`, etc.) is immutable for the file's
        // lifetime once set, so comparing just these two is equivalent to
        // the full comparison for everything that can actually change.
        // The legacy (non-redo) path is untouched: both slots stay in
        // sync there (every commit alternates and rewrites them), so the
        // strict full-header comparison was never spuriously tripped and
        // must stay exactly as strict.
        // perf/lwa-read-audit: `redo_folded_through` is a derived
        // bookkeeping hint -- how far back a *fresh, independent* replay
        // from the log can safely trust the overlay (`recoverRedoLog`'s
        // own doc comment) -- not a reflection of physical tree content,
        // and it can legitimately differ here even when nothing on disk
        // changed at all. A real-publish bookkeeping-only commit (e.g.
        // `maintainOnce`'s startup pass through `reclaimPagesImpl`'s
        // ledger consolidation; see that call site's own "bookkeeping-
        // only commit advances commit_sequence past the true fold
        // boundary" comment and the matching redo differential oracle
        // regression it is already safe against on reopen) advances this
        // process's own in-memory `redo_folded_through` without a
        // corresponding slot-page rewrite reaching disk for that field,
        // so `reader` (freshly opened by path, recovered via the exact
        // same conservative, log-replay-derived computation a real
        // reopen would use) can come back with a strictly smaller value
        // for the *same* `commit_sequence` and the *same* roots --
        // confirmed live: every other field byte-identical, only this
        // one differing. Comparing it here is also pointless, not just
        // wrong: `reader.header` is unconditionally replaced by
        // `self.header` a few lines below regardless of what this
        // comparison decides, so `reader`'s own `redo_folded_through` is
        // never actually used. Exclude it; everything else (roots,
        // page_count, commit_sequence, logical generations) still
        // compares exactly, so a real concurrent change is still caught.
        const headers_equivalent = if (self.redo != null) blk: {
            if (self.header.active_checkpoint != reader.header.active_checkpoint) break :blk false;
            var self_slot = self.header.checkpoints[self.header.active_checkpoint];
            var reader_slot = reader.header.checkpoints[reader.header.active_checkpoint];
            self_slot.redo_folded_through = 0;
            reader_slot.redo_folded_through = 0;
            break :blk std.meta.eql(self_slot, reader_slot);
        } else std.meta.eql(self.header, reader.header);
        if ((self.durable_header == null and !headers_equivalent) or inode != (try self.file.stat(self.runtime())).inode) return error.EnrichmentWaitCanceled;
        reader.header = self.header;
        if (coordinated) {
            // Same self-conflict `acquireReaderFence` guards against:
            // `reader` is a fresh fd on this same writer's (`self`'s)
            // path, and `self`'s own exclusive grant (if parked warm by
            // `acquireEpochReuseLock`) would self-conflict a direct lock
            // on `reader.file`'s own fd. Go through the shared per-inode
            // registry entry instead -- `errdefer reader.close()` above
            // releases this via `reader_fence_lock` if anything below
            // still fails.
            if (builtin.mode == .debug) std.debug.assert(reader.reader_fence_lock == null);
            reader.reader_fence_lock = try reader.acquireInodeLock(.shared, true, false, "captureFullReadSnapshot");
            // A full-graph snapshot reader always retains metadata, region
            // slot or not -- `registerFull` handles both uniformly now,
            // regardless of `indexed_reclamation`.
            reader.reader_fence = try self.reader_coordinator.?.registerFull(reader.file, try self.regionForInode(), inode, reader.metadataReuseFrontier(), self.headerFingerprint());
        }
        return reader;
    }

    pub fn completeAllocatorVerification(self: *NativeFile) !void {
        const cancel = self.allocator_cancel_token;
        if (cancel) |token| try token.check();
        const checkpoint = self.activeCheckpoint();
        if (self.header.indexed_reclamation) {
            const state = try self.loadLedger(checkpoint);
            if (checkpoint.free_map_root_page != 0) _ = try self.validateIndexedAllocator(checkpoint, state, cancel);
        } else {
            const pages = try self.readFreePagesAlloc(checkpoint);
            defer self.allocator.free(pages);
            try self.validateFreePagesSafeForCheckpointSlots(pages);
        }
        if (cancel) |token| try token.check();
        self.free_pages_verified = true;
    }

    const allocator_certificate_key = "\x00AFCERT/allocator-v1";
    const allocator_certificate_magic = "AFACERT1";
    const allocator_certificate_live_magic = "AFACERT2";
    const allocator_certificate_size = 72;

    // v8's encodeHeader only covers the static page-0 fields (magic,
    // version, page_size, reader_epoch_namespace): the recovery slots moved
    // to their own pages. Both recovery slots and the complete loaded
    // ledger must match for an allocator certificate to carry over
    // (inheritAllocatorCertificate's doc comment): a certificate is only
    // safe to inherit if NEITHER recovery slot moved since it was issued,
    // not just the one that happens to be active. So this hashes both
    // slots' payloads, in fixed index order, independent of
    // active_checkpoint: which index is active is not itself part of the
    // recoverable identity (both slots already carry their own
    // commit_sequence).
    fn fingerprintHeader(header: Header) [32]u8 {
        if (builtin.is_test) _ = test_header_fingerprint_hashes.fetchAdd(1, .monotonic);
        var encoded: [header_size]u8 = undefined;
        encodeHeader(&encoded, header);
        var hasher = std.crypto.hash.Blake3.init(.{});
        hasher.update(&encoded);
        for (header.checkpoints) |slot| {
            var slot_payload: [checkpoint_slot_payload_size]u8 = undefined;
            encodeCheckpointSlotPayload(&slot_payload, slot);
            hasher.update(&slot_payload);
        }
        var digest: [32]u8 = undefined;
        hasher.final(&digest);
        return digest;
    }

    pub fn headerFingerprint(self: *NativeFile) [32]u8 {
        const header = self.transaction_header orelse self.header;
        if (self.header_fingerprint_cache.lookup(header)) |digest| return digest;
        // Hash outside the cache lock. Concurrent first readers may duplicate
        // this bounded work; hits never hash or wait behind a hash operation.
        const digest = fingerprintHeader(header);
        self.header_fingerprint_cache.remember(header, digest);
        return digest;
    }

    /// Hash the complete canonical allocator state, not the physical encoding
    /// or hash-map iteration order. Loading already checks every ledger CRC.
    /// The pending list is ordered by monotonic ID on mutation and recovery.
    fn allocatorFingerprint(state: *const allocator_v4.State) ![32]u8 {
        var hash = std.crypto.hash.Blake3.init(.{});
        hash.update("Antfly checked allocator v1");
        var root: [128]u8 = undefined;
        allocator_v4.State.encodeRoot(state.root, &root);
        hash.update(&root);
        var counters: [4096]u8 = undefined;
        var start: usize = 0;
        while (start < state.counts.items.len) {
            const n: usize = @min(counters.len / 4, state.counts.items.len - start);
            for (state.counts.items[start..][0..n], 0..) |value, k|
                std.mem.writeInt(u32, counters[k * 4 ..][0..4], value, .little);
            hash.update(counters[0 .. n * 4]);
            start += n;
        }
        var previous: u64 = 0;
        var id = state.first_pending;
        var count: usize = 0;
        while (id != 0) {
            const item = state.pending.get(id) orelse return error.InvalidNativeAllocator;
            if (id <= previous or item.id != id or count >= state.pending.count()) return error.InvalidNativeAllocator;
            var encoded: [40]u8 = @splat(0);
            std.mem.writeInt(u64, encoded[0..8], id, .little);
            std.mem.writeInt(u64, encoded[8..16], item.epoch, .little);
            std.mem.writeInt(u64, encoded[16..24], item.page, .little);
            std.mem.writeInt(u64, encoded[24..32], item.length, .little);
            encoded[32] = @backingInt(item.kind);
            hash.update(&encoded);
            count += 1;
            previous = id;
            id = item.next;
        }
        if (count != state.pending.count()) return error.InvalidNativeAllocator;
        var result: [32]u8 = undefined;
        hash.final(&result);
        return result;
    }

    /// A clean native writer can carry its checked ownership invariant across
    /// processes. Both recovery slots and the complete loaded ledger must match;
    /// old writers, crash fallback and changed/corrupt state invalidate the seal.
    /// Explicit integrity checks and ordinary primitive opens still walk graphs.
    pub fn inheritAllocatorCertificate(self: *NativeFile) !bool {
        if (!self.header.indexed_reclamation or self.transaction_header != null or
            self.durable_header != null or self.checkpoint_publication_uncertain) return false;
        const checkpoint = self.activeCheckpoint();
        if (checkpoint.free_map_root_page != 0) {
            const root = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
            defer self.allocator.free(root);
            _ = try allocator_v4.State.decodeRoot(root);
            if (root.len == 192) {
                if (!std.mem.eql(u8, root[128..160], &self.headerFingerprint())) return false;
                return self.acceptAllocatorDigest(root[160..192], true);
            }
        }
        // Older checked publications stored seals in a catalog record.
        if (try self.inheritAllocatorCertificateFrom(.index)) return true;
        return self.inheritAllocatorCertificateFrom(.metadata);
    }

    fn inheritAllocatorCertificateFrom(self: *NativeFile, root: CatalogRoot) !bool {
        const certificate = (if (root == .index)
            try self.getIndexCatalogRecordAlloc(self.allocator, allocator_certificate_key)
        else
            try self.getCatalogRecordAlloc(self.allocator, allocator_certificate_key)) orelse return false;
        defer self.allocator.free(certificate);
        if (certificate.len != allocator_certificate_size) return false;
        const live = std.mem.eql(u8, certificate[0..8], allocator_certificate_live_magic);
        if (!live and !std.mem.eql(u8, certificate[0..8], allocator_certificate_magic)) return false;
        const header_hash = self.headerFingerprint();
        if (!std.mem.eql(u8, certificate[8..40], &header_hash)) return false;
        return self.acceptAllocatorDigest(certificate[40..72], live);
    }

    fn acceptAllocatorDigest(self: *NativeFile, expected: []const u8, live: bool) !bool {
        self.free_pages_verified = false;
        const state = try self.loadLedgerForDigest(self.activeCheckpoint(), self.allocator_cancel_token, false);
        const canceled = if (self.allocator_cancel_token) |token| &token.requested else null;
        const digest_started = std.Io.Clock.awake.now(self.runtime());
        var rebuilding = live and !self.allocator_ledger_rebased;
        defer if (rebuilding) {
            self.allocator_work.digest_rebuilds +|= 1;
            self.allocator_work.digest_rebuild_ns +|= @intCast(@max(0, digest_started.durationTo(std.Io.Clock.awake.now(self.runtime())).nanoseconds));
        };
        var ownership_hash = if (live)
            if (self.allocator_ledger_rebased) try state.incrementalFingerprint() else try state.rebuildFingerprintWithCancel(canceled)
        else
            try allocatorFingerprint(state);
        if (self.allocator_ledger_rebased and !std.mem.eql(u8, expected, &ownership_hash)) {
            // A reused physical journal anchor is not logical ancestry. The
            // certificate must match an independent reload before admitting
            // reuse; a cache miss must not force an unnecessary graph proof.
            self.invalidateLedger();
            const independent = try self.loadLedgerForDigest(self.activeCheckpoint(), self.allocator_cancel_token, false);
            rebuilding = live;
            ownership_hash = if (live) try independent.rebuildFingerprintWithCancel(canceled) else try allocatorFingerprint(independent);
        }
        if (!std.mem.eql(u8, expected, &ownership_hash)) {
            self.free_pages_verified = false;
            self.allocator_rebase_header = null;
            self.allocator_ledger_rebased = false;
            return false;
        }
        self.free_pages_verified = true;
        self.allocator_rebase_header = null;
        self.allocator_ledger_rebased = false;
        self.allocator_verification_base = null;
        return true;
    }

    /// Publish only from an already checked writer, at a clean durability
    /// boundary. The record includes its own exact allocator ownership.
    pub fn certifyAllocator(self: *NativeFile) !bool {
        if (self.read_only) return error.ReadOnly;
        if (!self.header.indexed_reclamation or !self.free_pages_verified or
            self.transaction_header != null or self.durable_header != null or
            self.checkpoint_publication_uncertain) return false;
        if (self.allocator_certificate_on_commit) {
            const checkpoint = self.activeCheckpoint();
            const root = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
            defer self.allocator.free(root);
            if (root.len == 192 and std.mem.eql(u8, root[128..160], &self.headerFingerprint())) return true;
        }
        // Use the ordinary rollback/publication boundary. Allocation, budget
        // and page-write errors must leave no unpublished tail at clean close;
        // commitTransaction retains the fence if publication becomes uncertain.
        try self.beginTransaction();
        errdefer self.abortTransaction();
        // `beginTransaction` can itself call `refreshIfWriterBaseStale`
        // (perf/lwa-grouped-stall) when this instance's writer base is
        // behind the inode registry's latest committed sequence. That
        // resync adopts the newer on-disk header
        // (`adoptIndexPublicationHeader`), which unconditionally clears
        // `free_pages_verified` -- invalidating the precondition this
        // function already checked above, between that check and
        // `stageAllocatorCertificate`'s own assertion of it. Re-check
        // after beginning the transaction and abort cleanly (certifying
        // nothing, same as the pre-check above) instead of asserting.
        if (!self.header.indexed_reclamation or !self.free_pages_verified) {
            self.abortTransaction();
            return false;
        }
        try self.stageAllocatorCertificate(.metadata);
        try self.commitTransaction();
        return true;
    }

    /// Seal the final private checkpoint before its ordinary data durability
    /// barrier. This adds no checkpoint publication or fsync of its own.
    noinline fn stageAllocatorCertificate(self: *NativeFile, root: CatalogRoot) !void {
        const original = self.transaction_header orelse return error.InvalidTransactionState;
        std.debug.assert(self.header.indexed_reclamation and self.free_pages_verified);
        std.debug.assert(self.durable_header == null and !self.checkpoint_publication_uncertain);
        const before = self.activeCheckpoint();
        const root_page = if (root == .index) before.index_catalog_root_page else before.catalog_root_page;
        const roots = try self.readCatalogRoots(root_page, before);
        var pages = try self.pageAllocatorFromFreeMap(before);
        defer pages.deinit();
        const empty: [allocator_certificate_size]u8 = @splat(0);
        const record = try pages.writeCatalog(.{ .previous_page = 0, .key = allocator_certificate_key, .value = &empty });
        var editor = IndexEditor.init(self, before, roots.index);
        editor.accounting_pages = &pages;
        defer editor.deinit();
        try editor.put(allocator_certificate_key, record);
        var next = before;
        // Intermediate mutations may increment their private sequence many
        // times. The outer transaction publishes exactly one new generation.
        next.commit_sequence = original.checkpoints[original.active_checkpoint].commit_sequence + 1;
        // perf/lwa-lease-fold: same stamp, same reason, as
        // `commitTransactionWithDurability`'s own two sites (see
        // `redo_folded_through`'s own doc comment) -- this function
        // builds and fingerprints `next`/`published` itself, bypassing
        // that shared commit path entirely, so it needs its own copy of
        // the same rule or the certificate it seals here fingerprints a
        // `redo_folded_through` one behind the value the *actual*
        // publish (this function's own `self.commitTransaction()`
        // caller, which does go through the shared path and applies the
        // identical stamp there) ends up writing to the real on-disk
        // slot -- `inheritAllocatorCertificate`'s byte-for-byte replay of
        // this same fingerprint formula then disagrees with what is
        // actually on disk on every subsequent open, for a reason that
        // has nothing to do with the ownership the certificate exists to
        // attest.
        if (self.redo == null or self.redo.?.checkpointing) next.redo_folded_through = next.commit_sequence;
        const next_root = try self.writeCatalogRoot(&pages, record, try editor.finish(&pages), root_page);
        if (root == .index) next.index_catalog_root_page = next_root else next.catalog_root_page = next_root;
        next.free_map_root_page = try pages.allocate();
        next.page_count = pages.next_page_id;
        try self.persistAllocator(&pages, &next);
        var published = original;
        // perf/lwa-peer-cert: the `self.commitTransaction()` call this
        // function's own caller (`certifyAllocator`) makes right after it
        // returns only flips `active_checkpoint` to the *other* physical
        // slot when that commit reaches the real v8/v9 slot write
        // (`self.redo == null`, a checkpointing fold, or a last-second
        // log-full fallback `publishCheckpoint` itself discovers) -- the
        // same "will this be a real, physically-written checkpoint"
        // condition `redo_folded_through` above already has to predict,
        // for the identical reason (see that stamp's comment just
        // above). Otherwise -- by far the common case, since the redo
        // log is the default and this commit has nothing forcing a fold
        // -- the real publish diverts into an in-place redo-log append:
        // `self.header.checkpoints[self.header.active_checkpoint]` is
        // simply overwritten with `next` and `active_checkpoint` never
        // moves (`publishCheckpoint`'s own ride-along/fresh-append
        // branches). `fingerprintHeader` hashes both slots in fixed
        // physical-index order, independent of which one is active (its
        // own doc comment), so which physical slot ends up holding
        // `next`'s content is exactly what `published` must predict
        // correctly: unconditionally flipping here fingerprinted a
        // header the real diverted commit never produces, so every
        // later `inheritAllocatorCertificate` byte-for-byte replay of
        // this formula disagreed with what was actually on disk/in
        // `self.header`, for a reason that has nothing to do with the
        // ownership the certificate exists to attest.
        if (self.redo == null or self.redo.?.checkpointing) published.active_checkpoint = 1 - original.active_checkpoint;
        published.checkpoints[published.active_checkpoint] = next;
        var certificate: [allocator_certificate_size]u8 = undefined;
        @memcpy(certificate[0..8], if (root == .index) allocator_certificate_live_magic else allocator_certificate_magic);
        @memcpy(certificate[8..40], &fingerprintHeader(published));
        const ownership_hash = if (root == .index) try pages.ledger.?.incrementalFingerprint() else try allocatorFingerprint(pages.ledger.?);
        @memcpy(certificate[40..72], &ownership_hash);
        var encoded = std.ArrayListUnmanaged(u8).empty;
        defer encoded.deinit(self.allocator);
        try encodeCatalogEntry(self.allocator, &encoded, .{ .previous_page = 0, .key = allocator_certificate_key, .value = &certificate });
        // All pending batches, including the placeholder, have been flushed by
        // persistAllocator. Replace only this unpublished standalone record.
        try self.writePage(record, .catalog, encoded.items);
        // Stage the root in memory. The ordinary commit supplies the single
        // data durability barrier before publishing the checkpoint slots.
        try self.publishCheckpoint(next, false, null);
        self.allocator_certificate_staged = true;
    }

    /// Acquires `mode` on this file's inode, through the process-wide
    /// registry (`inode_lock_ref`) when one was established at open/create
    /// time, or falling back to the original, unshared direct acquisition
    /// (`inode_lock.acquireStandalone`) when it was not -- true only for a
    /// handful of internal vacuum/compaction workspace `NativeFile`s built
    /// directly rather than through `open`/`create`, on private or even
    /// path-less temp files nothing else in this process could plausibly
    /// share an inode with.
    /// `blocks_exclusive` only matters for `mode == .shared` (see
    /// `inode_lock.acquire`'s doc comment): pass `true` for a plain
    /// reader relying solely on the kernel lock, `false` for one whose
    /// protection against this same process's own writer comes from
    /// `ReaderCoordinator` instead.
    fn acquireInodeLock(self: *NativeFile, mode: inode_lock.Mode, blocking: bool, blocks_exclusive: bool, site: []const u8) !inode_lock.Handle {
        // One atomic read of the current entry; the returned `Handle`
        // captures this exact pointer, so a concurrent rebind
        // (`replaceWithPreparedGeneration`) after this point can only
        // affect a *later* acquire, never this one or its eventual release.
        if (self.inode_lock_ref.load(.acquire)) |entry| return try inode_lock.acquire(entry, self.runtime(), mode, blocking, blocks_exclusive, site);
        return try inode_lock.acquireStandalone(self.runtime(), self.path, mode, blocking);
    }

    /// The shared lock region for this inode's registry entry, or `null`
    /// when there is no entry at all (a standalone/`externally_locked`-free
    /// file never registered, which has no registry `Entry` to carry a
    /// region on) or the region itself is genuinely unusable right now
    /// (`inode_lock.isRegionUnusable`, the same check the writer side
    /// shares) -- every reader-fence/epoch-reuse caller treats a `null`
    /// region the same way: fall back to inode-only kernel fencing, never
    /// fail the whole open or commit over it. Any other error (notably
    /// `OutOfMemory`) propagates instead of being swallowed into a
    /// fallback that would likely fail the same way.
    pub fn regionForInode(self: *NativeFile) !?*shared_lock_region.Region {
        const entry = self.inode_lock_ref.load(.acquire) orelse return null;
        return inode_lock.ensureRegion(entry, self.runtime()) catch |err| {
            if (inode_lock.isRegionUnusable(err)) return null;
            return err;
        };
    }

    /// §9.3b: publishes `self.redo`'s current state (the checkpoint
    /// baseline it is relative to, the highest durable sequence, and the
    /// log's durable tail offset) to the shared lock region, if this
    /// inode has one -- the cross-process WAL index a reader in a
    /// different process consults to catch up. A no-op (not an error)
    /// when there is no redo log or no usable region: both are the same
    /// "nothing to publish, nothing to read" case `regionForInode`
    /// already treats uniformly elsewhere. Called at `recoverRedoLog`/
    /// `createWithRedoLog` time (so a fresh reader sees *some* state
    /// immediately rather than stale zeros until the first commit) and
    /// after every durable append or checkpoint thereafter. No new
    /// syscalls on the steady-state path: `regionForInode` only opens the
    /// region the first time any caller on this inode needs it (already
    /// done by the ordinary commit path's own reuse-frontier scan), every
    /// call after that is a mutex lock plus atomic stores into the
    /// already-mapped region.
    ///
    /// Deliberately `void`, not an error union: this is a cross-process
    /// convenience, not part of the durability contract this process's
    /// own commit just satisfied (the fsync already happened; a reader
    /// in *this* process already sees the result through `self.redo`
    /// regardless). Any failure to reach or publish to the region --
    /// including `OutOfMemory`, unlike `regionForInode`'s own stricter
    /// contract for callers that need the region for correctness -- is
    /// swallowed here: a cross-process reader just sees stale (but never
    /// wrong) watermarks until the next successful publish, the same
    /// "stale but safe" posture every other process already has before
    /// this call ever runs once.
    fn publishRedoLogState(self: *NativeFile) void {
        const redo = if (self.redo) |*r| r else return;
        const region = (self.regionForInode() catch return) orelse return;
        region.publishLogState(.{
            .checkpoint_sequence = redo.checkpoint_sequence,
            .durable_sequence = redo.durable_sequence,
            .durable_offset = redo.writer.tail,
        });
    }

    /// Read-generation locks join the same-owner frontier only while
    /// pinned. Acquires the shared grant through `inode_lock_ref` (the
    /// process-wide, per-inode registry) rather than locking `self.file`'s
    /// own fd directly: `self` (this reader) and `owner` (the writer being
    /// fenced against) are different NativeFile instances with different
    /// fds, possibly on the very same inode -- flock() does not recognize
    /// a different fd from the same process as compatible with one
    /// already held, so locking `self.file` directly here can queue
    /// behind `owner`'s own exclusive hold (parked warm by
    /// `acquireEpochReuseLock` to amortize it across commits) forever,
    /// since nothing else in this process would ever release it for this
    /// call. Going through the shared registry entry for this inode
    /// instead makes that self-conflict structurally impossible: both
    /// `owner`'s exclusive hold and this shared request resolve against
    /// the same entry, which grants a `.shared` request for free whenever
    /// it already holds `.exclusive` in-process.
    pub fn acquireReaderFence(self: *NativeFile, sequence: u64, owner: *NativeFile) !void {
        // Claim and pin a shared-lock-region reader slot (§8.3) before
        // deciding `blocks_exclusive`: whether this reader actually ends up
        // with a live slot (the writer's own `acquireEpochReuseLock`/
        // `epoch_window` can see it, from any process, not just this one)
        // is only known after the attempt, not guessable up front from
        // `owner.read_only` alone. A region unavailable for this inode, or
        // exhausted, falls back to an inode-only fence inside
        // `coordinator.registerEpoch` itself -- never a reason to fail this
        // whole call, only to fence more conservatively (the kernel lock
        // below still blocks this process's own exclusive reuse either
        // way).
        // `self.reader_fence` is a single field, not a list: a plain
        // read-only open (`openWithRuntime`'s `plain_reader` branch) may
        // already have registered one here before this call ever runs,
        // and -- since every `pin.kernel_reader` read-generation window
        // now reaches this call regardless (`perf/lwa-xproc-pagekind`
        // dropped the old `scoped_reader_lock` restriction) -- a second
        // window on the same already-fenced `NativeFile` would otherwise
        // overwrite that live registration without ever unregistering it,
        // leaking the old `Fence` (and its region slot) for the rest of
        // this `NativeFile`'s life. Release it first, exactly the hazard
        // the `reader_fence_lock` overwrite below already guards against.
        if (self.reader_fence) |stale| {
            self.reader_coordinator.?.unregister(stale);
            self.reader_fence = null;
        }
        if (self.reader_coordinator) |coordinator| {
            self.reader_fence = try coordinator.registerEpoch(self.file, try self.regionForInode(), (try self.file.stat(self.runtime())).inode, sequence, owner.headerFingerprint(), false);
        }
        errdefer if (self.reader_fence) |fence| self.reader_coordinator.?.unregister(fence);
        // Only a fence that actually got a live region slot (`Fence
        // .hasEpoch()`, private to reader_coordinator.zig -- inlined here
        // as the `slot` check) is covered by that separate mechanism
        // instead; see `inode_lock.Entry.blocking_shared_count`'s doc
        // comment. Every case without a live slot -- no coordinator, no
        // region, or the region's own exhaustion fallback -- still needs
        // this lock to actively block this process's own exclusive reuse
        // too.
        const blocks_exclusive = if (self.reader_fence) |fence| fence.slot == null else true;
        const handle = try self.acquireInodeLock(.shared, true, blocks_exclusive, "acquireReaderFence");
        errdefer handle.release(self.runtime());
        // A plain read-only open (`openWithRuntime`'s `plain_reader`
        // branch) already took its own shared grant, stored here, before
        // this call -- a caller that later attaches a `reader_coordinator`
        // and then explicitly calls `acquireReaderFence` (as a test
        // simulating "retroactively coordinated" readers does) would
        // otherwise overwrite that handle here without ever releasing it,
        // permanently leaking its `blocking_shared_count` share.
        if (self.reader_fence_lock) |stale| stale.release(self.runtime());
        self.reader_fence_lock = null;
        if (builtin.mode == .debug) std.debug.assert(self.reader_fence_lock == null);
        self.reader_fence_lock = handle;
    }
    pub fn releaseReaderFence(self: *NativeFile) void {
        if (self.reader_fence) |fence| self.reader_coordinator.?.unregister(fence);
        self.reader_fence = null;
        if (self.reader_fence_lock) |handle| {
            handle.release(self.runtime());
            self.reader_fence_lock = null;
        }
    }
    /// Acquires this inode's shared epoch-reuse (exclusive) grant through
    /// the process-wide registry (`inode_lock_ref`), never blocking: a
    /// foreign process already holding anything conflicting surfaces as
    /// `error.WouldBlock`, which every caller already treats as "skip
    /// reuse this commit." Granted for free (no kernel call) whenever this
    /// process -- any NativeFile on this inode, not just `self` -- already
    /// holds the kernel lock exclusively; that in-process sharing, and the
    /// warm parking across commits once released, both live inside the
    /// registry entry now, not on this NativeFile.
    fn acquireEpochReuseLock(self: *NativeFile, caller: []const u8) !inode_lock.Handle {
        self.epoch_window = null;
        if (self.activeCheckpoint().free_map_root_page != 0) {
            // Same hazard the old direct-reacquire path guarded against:
            // an external rename/replace (backup/restore, vacuum) could
            // have swapped the file at `self.path` out from under this
            // NativeFile since it was opened. A plain `statFile` (no
            // `open`) is enough: it tells us what `self.path` currently
            // resolves to, and `self.file`'s own inode never changes for
            // this NativeFile's lifetime, so comparing the two still
            // catches the same case the old open-and-compare did.
            const current = std.Io.Dir.cwd().statFile(self.runtime(), self.path, .{}) catch return error.EnrichmentSourceChanged;
            if (current.inode != (try self.file.stat(self.runtime())).inode) return error.EnrichmentSourceChanged;
        }
        // `caller` (not a fixed literal) so the permanent debug-outstanding
        // dump in inode_lock.zig names the actual call site -- beginReaderWindow
        // vs. either branch of resumeReuseIfUnblocked -- not just this
        // shared wrapper, which is what originally hid an overwritten-handle
        // leak behind a single undifferentiated label.
        const handle = try self.acquireInodeLock(.exclusive, false, false, caller);
        errdefer handle.release(self.runtime());
        // Replaces `scanReaderEpochsCached`'s namespace-directory walk: a
        // plain in-memory atomic scan over the region's reader table (§8.3),
        // no filesystem I/O, no amortizing cache to maintain. `null` (no
        // region for this inode, or genuinely nothing pinned) just leaves
        // `epoch_window` at its already-cleared `null`, which
        // `reuseFrontier`/`metadataReuseFrontier` already treat as "no
        // additional frontier from this source."
        if (try self.regionForInode()) |region| self.epoch_window = .{ .data = region.minimumPinnedSequence(), .metadata = region.minimumMetadataPinnedSequence() };
        return handle;
    }
    fn beginReaderWindow(self: *NativeFile) !bool {
        const coordinator = self.reader_coordinator orelse return false;
        if (self.reader_window_depth != 0) {
            self.reader_window_depth += 1;
            return true;
        }
        const inode = (try self.file.stat(self.runtime())).inode;
        const frontier = coordinator.beginWithMetadata(inode, self.headerFingerprint(), self.free_pages_verified, try self.regionForInode());
        errdefer coordinator.end();
        self.reader_window_previous_frontier = self.minimum_reader_sequence;
        if (frontier.data) |sequence| self.minimum_reader_sequence = @min(self.minimum_reader_sequence orelse sequence, sequence);
        errdefer self.minimum_reader_sequence = self.reader_window_previous_frontier;
        self.reader_window_previous_metadata_frontier = self.minimum_metadata_reader_sequence;
        if (frontier.metadata) |sequence| self.minimum_metadata_reader_sequence = @min(self.minimum_metadata_reader_sequence orelse sequence, sequence);
        errdefer self.minimum_metadata_reader_sequence = self.reader_window_previous_metadata_frontier;
        // Even an append-only owner must fence and account for readers before
        // promoting retirement. Proof authority separately controls page reuse.
        const held = self.acquireEpochReuseLock("beginReaderWindow") catch |err| switch (err) {
            error.WouldBlock => blk: {
                self.allocator_work.reuse_lock_refusals +|= 1;
                break :blk null;
            },
            else => return err,
        };
        if (builtin.mode == .debug) std.debug.assert(self.reader_window_lock == null);
        self.reader_window_lock = held;
        self.reader_window_depth = 1;
        return true;
    }
    fn endReaderWindow(self: *NativeFile) void {
        std.debug.assert(self.reader_window_depth != 0);
        self.reader_window_depth -= 1;
        if (self.reader_window_depth != 0) return;
        if (self.reader_window_lock) |held| held.release(self.runtime());
        self.reader_window_lock = null;
        self.epoch_window = null;
        self.minimum_reader_sequence = self.reader_window_previous_frontier;
        self.minimum_metadata_reader_sequence = self.reader_window_previous_metadata_frontier;
        self.reader_coordinator.?.end();
    }

    fn invalidateLedger(self: *NativeFile) void {
        self.allocator_rebase_header = null;
        self.allocator_ledger_rebased = false;
        if (self.ledger) |state| {
            state.deinit();
            self.allocator.destroy(state);
            self.ledger = null;
        }
    }

    fn ledgerRead(context: *anyopaque, a: Allocator, page: u64) ![]u8 {
        const file: *NativeFile = @ptrCast(@alignCast(context));
        const expected_kind: PageKind = if (page == file.activeCheckpoint().free_map_root_page) .free_map else .allocator;
        // A cache hit already holds a CRC-validated page; borrow its payload
        // directly instead of duplicating the whole page just to decode and
        // immediately discard the full-page copy. allocator_v4's ledger load
        // calls this once per ledger page per commit, so this was the single
        // largest allocation site in the write path.
        const use_cache = file.page_cache_enabled.load(.monotonic) and file.page_cache_bypass.load(.monotonic) == 0;
        if (use_cache) {
            const physical = physicalPage(page);
            if (try file.page_cache.acquirePayload(file.allocator, physical, @intCast(file.header.page_size))) |view| {
                defer file.page_cache.releaseRaw(file.allocator, view);
                if (view.validation.?.kind != expected_kind) return error.UnexpectedNativePageKind;
                return try a.dupe(u8, view.bytes[page_header_size..][0..view.validation.?.payload_len]);
            }
        }
        const raw = try file.readPageAlloc(a, page);
        defer a.free(raw);
        return try a.dupe(u8, try decodePagePayload(raw, expected_kind));
    }
    fn ledgerReadOnlyAllocate(_: *anyopaque) !u64 {
        return error.ReadOnly;
    }
    fn ledgerReadOnlyWrite(_: *anyopaque, _: u64, _: []const u8) !void {
        return error.ReadOnly;
    }

    /// Delta pages a cached ledger may replay before falling back to a full
    /// load. Replay reads only the suffix written since the base; the
    /// fallback reads and rehashes the whole ledger. Large foreground batches
    /// between maintenance turns routinely exceed a few hundred pages.
    const max_ledger_rebase_delta_pages = 1024;

    fn loadLedger(self: *NativeFile, checkpoint: CheckpointSlot) !*allocator_v4.State {
        return self.loadLedgerWithCancel(checkpoint, self.allocator_cancel_token);
    }
    fn loadLedgerWithCancel(self: *NativeFile, checkpoint: CheckpointSlot, cancel: ?*const maintenance.CancelToken) !*allocator_v4.State {
        return self.loadLedgerForDigest(checkpoint, cancel, self.allocator_certificate_on_commit);
    }
    fn loadLedgerForDigest(self: *NativeFile, checkpoint: CheckpointSlot, cancel: ?*const maintenance.CancelToken, prepare_digest: bool) !*allocator_v4.State {
        if (cancel) |token| try token.check();
        // Adoption may return to the same physical root number after reuse.
        // A pending rebase is never a cache hit merely because IDs match.
        if (self.ledger) |state| if (self.allocator_rebase_header == null and state.root_page == checkpoint.free_map_root_page) {
            if (prepare_digest) try state.prepareDigestWithCancel(if (cancel) |token| &token.requested else null);
            return state;
        };
        if (self.allocator_rebase_header != null) if (self.ledger) |state| {
            errdefer self.invalidateLedger();
            const started = std.Io.Clock.awake.now(self.runtime());
            const rebased = state.rebase(.{
                .context = self,
                .allocate = ledgerReadOnlyAllocate,
                .read = ledgerRead,
                .write = ledgerReadOnlyWrite,
                .payload_bytes = self.maxPagePayloadBytes(),
                .cancel_requested = if (cancel) |token| &token.requested else null,
            }, checkpoint.free_map_root_page, max_ledger_rebase_delta_pages) catch |err| switch (err) {
                // Unprotected physical anchors may have been reused. An
                // independent load distinguishes cache ancestry failure from
                // corruption in the current generation.
                error.InvalidNativeAllocator, error.UnexpectedNativePageKind, error.InvalidNativePageKind, error.InvalidPageId => false,
                else => return err,
            };
            const base = self.allocator_rebase_header.?;
            const retained = for (self.header.checkpoints) |slot| {
                if (std.meta.eql(slot, base.checkpoints[base.active_checkpoint])) break true;
            } else false;
            var authenticated = retained;
            if (rebased and !retained) {
                const root = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
                defer self.allocator.free(root);
                authenticated = root.len == 192 and std.mem.eql(u8, root[128..160], &self.headerFingerprint()) and
                    std.mem.eql(u8, root[160..192], &try state.incrementalFingerprint());
            }
            if (rebased and authenticated) {
                // §9.7d: on a redo-log file, a diverting commit's own
                // page-shaped exception (an external value chain) can
                // advance `checkpoint.page_count` without the ledger ever
                // rebuilding to match -- the same lag `decodeFreeMapAlloc`
                // and the sibling full-ledger-load check just below both
                // already tolerate via `allow_behind`. This rebase
                // fast-path compared the two unconditionally and flagged
                // every such (legitimate) lag as `InvalidNativeAllocator`.
                const allow_behind = self.header.redo_log_capacity != 0;
                if (if (allow_behind) state.root.covered_pages > checkpoint.page_count else state.root.covered_pages != checkpoint.page_count) return error.InvalidNativeAllocator;
                self.allocator_ledger_rebased = true;
                self.allocator_work.journal_rebases +|= 1;
                self.allocator_work.journal_rebase_ns +|= @intCast(@max(0, started.durationTo(std.Io.Clock.awake.now(self.runtime())).nanoseconds));
                self.allocator_rebase_header = null;
                return state;
            }
        };
        self.invalidateLedger();
        if (checkpoint.free_map_root_page != 0) {
            const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
            defer self.allocator.free(payload);
            // §9.7d: same `allow_behind` lag as the rebase fast-path above
            // and `decodeFreeMapAlloc` -- a redo-log file's diverting
            // page-shaped exception can leave `checkpoint.page_count`
            // legitimately ahead of what the ledger root itself covers.
            const covered_pages = (try allocator_v4.State.decodeRoot(payload)).covered_pages;
            const allow_behind = self.header.redo_log_capacity != 0;
            if (if (allow_behind) covered_pages > checkpoint.page_count else covered_pages != checkpoint.page_count) return error.InvalidNativeAllocator;
        }
        const started = std.Io.Clock.awake.now(self.runtime());
        self.allocator_work.full_loads +|= 1;
        defer self.allocator_work.full_load_ns +|= @intCast(@max(0, started.durationTo(std.Io.Clock.awake.now(self.runtime())).nanoseconds));
        const state = try self.allocator.create(allocator_v4.State);
        errdefer self.allocator.destroy(state);
        state.* = if (checkpoint.free_map_root_page == 0) allocator_v4.State.init(self.allocator) else try allocator_v4.State.load(self.allocator, .{
            .context = self,
            .allocate = ledgerReadOnlyAllocate,
            .read = ledgerRead,
            .write = ledgerReadOnlyWrite,
            .payload_bytes = self.maxPagePayloadBytes(),
            .cancel_requested = if (cancel) |token| &token.requested else null,
        }, checkpoint.free_map_root_page);
        errdefer state.deinit();
        if (prepare_digest) try state.prepareDigestWithCancel(if (cancel) |token| &token.requested else null);
        self.ledger = state;
        return state;
    }

    const LeafProof = struct { kind: PageKind, maximum_page: u64 };
    const LeafProofs = std.AutoHashMapUnmanaged(u64, LeafProof);

    const IndexedGraph = struct {
        leaf_proofs: LeafProofs = .empty,
        checked_leaves: ?*const LeafProofs = null,
        collect_leaf_proofs: bool = false,
        maximum_page: u64 = 0,
        pages: ReachablePageSet = .empty,
        nodes: ReachablePageSet = .empty,
        records: ReachablePageSet = .empty,
        values: std.AutoHashMapUnmanaged(u64, u64) = .empty,
        owners: ?*allocator_v4.State = null,
        record_count: u64 = 0,
        // Packed record validation borrows one physical page at a time. Never
        // synthesize and checksum a full page for each inline record.
        record_reader: RecordPageReader = .{},
        pub fn deinit(graph: *IndexedGraph, a: Allocator) void {
            graph.leaf_proofs.deinit(a);
            graph.pages.deinit(a);
            graph.nodes.deinit(a);
            graph.records.deinit(a);
            graph.values.deinit(a);
            graph.record_reader.deinit(a);
        }
    };

    fn indexedMark(self: *NativeFile, graph: *IndexedGraph, checkpoint: CheckpointSlot, reference: u64) !void {
        const page = physicalPage(reference);
        if (page == 0 or page >= checkpoint.page_count) return error.InvalidPageId;
        graph.maximum_page = @max(graph.maximum_page, page);
        try graph.pages.put(self.allocator, page, {});
    }

    /// Retains every page of the external value chain rooted at `root`
    /// (extent tree or simple linked chain) that `state` has not already
    /// counted -- idempotent per page via `state.count(page) == 0`, so
    /// it is safe to call even after the chain's own root was already
    /// retained elsewhere (`retainRecord`'s own `retainValue(root)` call,
    /// made when the record pointing at this chain was built).
    ///
    /// `checkpointRedoLog`'s own fold needs this for one case
    /// `redo_fold_retain_pending`'s staged-page sourcing never covers: a
    /// *catalog* value's own pages (`file.direct_value_pages`,
    /// `writeCatalogValue`'s own doc comment) are written for real,
    /// immediately, by the diverting commit that creates them --
    /// `PageWriteBatch.flushCount`'s own `direct_value_pages` branch
    /// pwrites them directly rather than staging them through
    /// `SharedRedoOverlay.pages`, to avoid holding an unboundedly large
    /// catalog value in memory across private-flush chunking. That same
    /// diverting commit's own `writeExtentNode`/`writeValuePagesAllocated`
    /// calls -- which normally retain every child page the moment it is
    /// linked -- ran against `pageAllocatorForDivertingCommit`'s allocator,
    /// which never attaches a ledger, so every one of those retains was a
    /// silent no-op; only the chain's root ever gets retained, by
    /// `retainRecord`, once the fold finally builds a real record for it.
    /// Reading the chain's actual on-disk structure here (rather than
    /// anything staged in memory) is also safe across a crash between the
    /// diverting commit and the fold that first processes its head: the
    /// bytes are already durably on disk by the time this ever runs.
    fn retainUnretainedValueChainPages(self: *NativeFile, state: *allocator_v4.State, checkpoint: CheckpointSlot, root: u64, length: u64, cancel: ?*const maintenance.CancelToken) !void {
        if (length == 0 or physicalPage(root) != root) return error.InvalidNativeValueChain;
        const Value = struct { page: u64, length: u64 };
        var work: std.ArrayList(Value) = .empty;
        defer work.deinit(self.allocator);
        var visited: std.AutoHashMapUnmanaged(u64, void) = .empty;
        defer visited.deinit(self.allocator);
        try work.append(self.allocator, .{ .page = root, .length = length });
        while (work.pop()) |value| {
            if (cancel) |token| try token.check();
            if (value.length == 0 or physicalPage(value.page) != value.page) return error.InvalidNativeValueChain;
            if ((try visited.fetchPut(self.allocator, value.page, {})) != null) continue;
            if (state.count(value.page) == 0 and !state.isSelfDescribingPage(value.page)) try state.retain(value.page);
            const raw = try self.readPageAllocForCheckpoint(self.allocator, value.page, checkpoint);
            defer self.allocator.free(raw);
            switch (raw[4]) {
                @backingInt(PageKind.value) => {
                    const leaf = try decodeValuePage(try decodePagePayload(raw, .value));
                    if (leaf.chunk.len == 0 or leaf.chunk.len > value.length) return error.InvalidNativeValueChain;
                    const remaining = value.length - leaf.chunk.len;
                    if (leaf.next_page != 0) try work.append(self.allocator, .{ .page = leaf.next_page, .length = remaining });
                },
                @backingInt(PageKind.value_extent) => {
                    const node = try decodeExtentNode(try decodePagePayload(raw, .value_extent), value.length);
                    for (node.children[0..node.count]) |child| try work.append(self.allocator, .{ .page = child.page, .length = child.len });
                },
                else => return error.InvalidNativeValueChain,
            }
        }
    }

    fn indexedValue(self: *NativeFile, graph: *IndexedGraph, checkpoint: CheckpointSlot, root: u64, length: u64, cancel: ?*const maintenance.CancelToken) !void {
        const Value = struct { page: u64, length: u64, height: ?u8 = null };
        var work: std.ArrayList(Value) = .empty;
        defer work.deinit(self.allocator);
        try work.append(self.allocator, .{ .page = root, .length = length });
        while (work.pop()) |value| {
            if (cancel) |token| try token.check();
            if (value.length == 0 or physicalPage(value.page) != value.page) return error.InvalidNativeValueChain;
            try self.indexedMark(graph, checkpoint, value.page);
            if (graph.owners) |owners| try owners.retain(value.page);
            if (graph.values.get(value.page)) |old_length| {
                if (old_length != value.length) return error.InvalidNativeValueChain;
                // This shared value was checked earlier, outside this leaf.
                // A conservative bound keeps the leaf certificate independent
                // of traversal order without retaining a second value graph.
                graph.maximum_page = @max(graph.maximum_page, checkpoint.page_count - 1);
                continue;
            }
            try graph.values.put(self.allocator, value.page, value.length);
            const raw = try self.readPageAllocForCheckpoint(self.allocator, value.page, checkpoint);
            defer self.allocator.free(raw);
            switch (raw[4]) {
                @backingInt(PageKind.value) => {
                    const leaf = try decodeValuePage(try decodePagePayload(raw, .value));
                    if (leaf.chunk.len == 0 or leaf.chunk.len > value.length) return error.InvalidNativeValueChain;
                    if (value.height) |height| if (height != 0 or leaf.next_page != 0) return error.InvalidNativeValueChain;
                    const remaining = value.length - leaf.chunk.len;
                    if ((remaining == 0) != (leaf.next_page == 0)) return error.InvalidNativeValueChain;
                    if (leaf.next_page != 0) try work.append(self.allocator, .{ .page = leaf.next_page, .length = remaining });
                },
                @backingInt(PageKind.value_extent) => {
                    const node = try decodeExtentNode(try decodePagePayload(raw, .value_extent), value.length);
                    if (value.height) |height| if (height != node.height) return error.InvalidNativeValueChain;
                    for (node.children[0..node.count]) |child| try work.append(self.allocator, .{ .page = child.page, .length = child.len, .height = child.height });
                },
                else => return error.InvalidNativeValueChain,
            }
        }
    }

    fn indexedTree(self: *NativeFile, graph: *IndexedGraph, checkpoint: CheckpointSlot, page: u64, kind: PageKind, lower: ?[]const u8, upper: ?[]const u8, depth: usize, cancel: ?*const maintenance.CancelToken) anyerror!void {
        if (page == 0) return;
        if (depth > 64 or physicalPage(page) != page or graph.nodes.contains(page)) return error.InvalidDocumentIndex;
        if (cancel) |token| try token.check();
        try graph.nodes.put(self.allocator, page, {});
        try self.indexedMark(graph, checkpoint, page);
        if (graph.owners) |owners| try owners.retain(page);
        var node = try self.readDocumentIndexNode(page, checkpoint);
        defer node.deinit(self.allocator);
        for (node.keys, node.key_pages.?, 0..) |key, key_page, i| {
            if (i != 0 and std.mem.order(u8, node.keys[i - 1], key) != .lt) return error.InvalidDocumentIndex;
            if (lower) |bound| if (std.mem.order(u8, key, bound) == .lt) return error.InvalidDocumentIndex;
            if (upper) |bound| if (std.mem.order(u8, key, bound) != .lt) return error.InvalidDocumentIndex;
            if (key_page != 0) {
                if (physicalPage(key_page) != key_page) return error.InvalidDocumentIndex;
                try self.indexedMark(graph, checkpoint, key_page);
                const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, key_page, .key, checkpoint);
                defer self.allocator.free(payload);
                if (!std.mem.eql(u8, key, try decodeKey(payload))) return error.InvalidDocumentIndex;
                if (graph.owners) |owners| try owners.retain(key_page);
            }
        }
        switch (node.kind) {
            .internal => for (node.pointers, 0..) |child, i| {
                try self.indexedTree(graph, checkpoint, child, kind, if (i == 0) lower else node.keys[i - 1], if (i == node.keys.len) upper else node.keys[i], depth + 1, cancel);
            },
            .leaf => {
                // Both recovery slots usually share almost every immutable
                // leaf. Reuse the active slot's completed record/value proof,
                // while independently checking this slot's tree bounds,
                // duplicate references and physical-page limit. The allocator
                // ownership pass checks all active pages before this reuse.
                const proof = if (graph.checked_leaves) |checked| checked.get(page) else null;
                const reuse_leaf = if (proof) |checked| checked.kind == kind and checked.maximum_page < checkpoint.page_count else false;
                const previous_maximum = graph.maximum_page;
                graph.maximum_page = page;
                defer graph.maximum_page = @max(graph.maximum_page, previous_maximum);
                for (node.key_pages.?) |key_page| graph.maximum_page = @max(graph.maximum_page, physicalPage(key_page));
                for (node.keys, node.pointers) |key, reference| {
                    if (graph.records.contains(reference)) return error.InvalidDocumentIndex;
                    try graph.records.put(self.allocator, reference, {});
                    try self.indexedMark(graph, checkpoint, reference);
                    if (reuse_leaf) {
                        graph.record_count += 1;
                        continue;
                    }
                    const payload = try graph.record_reader.read(self, self.allocator, checkpoint, reference, kind);
                    const record: CatalogEntry = switch (kind) {
                        .catalog => try decodeCatalogEntry(payload),
                        .document => blk: {
                            const doc = try decodeDocumentEntry(payload);
                            if (doc.previous_namespace_page != 0) return error.InvalidNativePageChain;
                            break :blk .{ .previous_page = doc.previous_page, .key = doc.key, .value = doc.value, .is_delete = doc.is_delete, .external_value_root_page = doc.external_value_root_page, .external_value_len = doc.external_value_len };
                        },
                        else => unreachable,
                    };
                    if (record.previous_page != 0 or record.is_delete or !std.mem.eql(u8, key, record.key)) return error.InvalidDocumentIndex;
                    if (graph.owners) |owners| try owners.retain(physicalPage(reference));
                    if (record.external_value_root_page != 0) try self.indexedValue(graph, checkpoint, record.external_value_root_page, record.external_value_len, cancel);
                    graph.record_count += 1;
                }
                if (!reuse_leaf and graph.collect_leaf_proofs) try graph.leaf_proofs.put(self.allocator, page, .{ .kind = kind, .maximum_page = graph.maximum_page });
            },
        }
    }

    fn indexedGraph(self: *NativeFile, checkpoint: CheckpointSlot, owners: ?*allocator_v4.State, cancel: ?*const maintenance.CancelToken) !IndexedGraph {
        return self.indexedGraphUsingLeaves(checkpoint, owners, null, false, cancel);
    }

    fn indexedGraphUsingLeaves(self: *NativeFile, checkpoint: CheckpointSlot, owners: ?*allocator_v4.State, checked: ?*const LeafProofs, collect: bool, cancel: ?*const maintenance.CancelToken) !IndexedGraph {
        var graph: IndexedGraph = .{ .owners = owners, .checked_leaves = checked, .collect_leaf_proofs = collect };
        errdefer graph.deinit(self.allocator);
        if (checkpoint.document_root_page != 0 or checkpoint.namespace_directory_root_page != 0) return error.InvalidNativePageChain;
        for ([_]u64{ checkpoint.catalog_root_page, checkpoint.index_catalog_root_page }) |descriptor| {
            if (descriptor == 0) continue;
            try self.indexedMark(&graph, checkpoint, descriptor);
            const roots = try self.readCatalogRoots(descriptor, checkpoint);
            if (!roots.indexed or roots.history != 0) return error.InvalidNativePageChain;
            if (owners) |state| try state.retain(descriptor);
            try self.indexedTree(&graph, checkpoint, roots.index, .catalog, null, null, 0, cancel);
        }
        try self.indexedTree(&graph, checkpoint, checkpoint.document_index_root_page, .document, null, null, 0, cancel);
        return graph;
    }

    fn validateIndexedOwnership(self: *NativeFile, checkpoint: CheckpointSlot, state: *allocator_v4.State, graph: *IndexedGraph, expected: *allocator_v4.State, cancel: ?*const maintenance.CancelToken) !void {
        var current_metadata: ReachablePageSet = .empty;
        defer current_metadata.deinit(self.allocator);
        for (state.metadata.items) |page| {
            if (cancel) |token| try token.check();
            try current_metadata.put(self.allocator, page, {});
        }
        var metadata_retirements: ReachablePageSet = .empty;
        defer metadata_retirements.deinit(self.allocator);
        var pending = state.pending.valueIterator();
        while (pending.next()) |item| {
            if (cancel) |token| try token.check();
            if (item.kind != .record and physicalPage(item.page) != item.page) return error.InvalidNativeAllocator;
            if (item.epoch > checkpoint.commit_sequence) return error.InvalidNativeAllocator;
            try self.indexedMark(graph, checkpoint, item.page);
            switch (item.kind) {
                .allocator_chain => {
                    var page = item.page;
                    while (page != 0) {
                        if (cancel) |token| try token.check();
                        try self.indexedMark(graph, checkpoint, page);
                        if (state.count(page) != 0 or page == state.root_page or metadata_retirements.contains(page) or current_metadata.contains(page)) return error.InvalidNativeAllocator;
                        try metadata_retirements.put(self.allocator, page, {});
                        const next = try self.retiredAllocatorNext(page, checkpoint);
                        page = if (next == item.length) 0 else next;
                    }
                },
                .metadata => {
                    if (state.count(item.page) != 0 or item.page == state.root_page or metadata_retirements.contains(item.page) or current_metadata.contains(item.page)) return error.InvalidNativeAllocator;
                    try metadata_retirements.put(self.allocator, item.page, {});
                },
                .page => try expected.retain(item.page),
                .value => try self.indexedValue(graph, checkpoint, item.page, item.length, cancel),
                .index => {
                    if (graph.nodes.contains(item.page)) return error.InvalidNativeAllocator;
                    try graph.nodes.put(self.allocator, item.page, {});
                    try expected.retain(item.page);
                    const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, item.page, .document_index, checkpoint);
                    defer self.allocator.free(payload);
                    var node = try decodeDocumentIndexNode(self.allocator, payload);
                    defer node.deinit(self.allocator);
                    for (node.key_pages.?) |key_page| if (key_page != 0) {
                        try self.indexedMark(graph, checkpoint, key_page);
                        try expected.retain(key_page);
                    };
                },
                .record => {
                    if (graph.records.contains(item.page)) return error.InvalidNativeAllocator;
                    try graph.records.put(self.allocator, item.page, {});
                    try expected.retain(physicalPage(item.page));
                    const raw = try self.readPageAllocForCheckpoint(self.allocator, item.page, checkpoint);
                    defer self.allocator.free(raw);
                    const root, const length = switch (raw[4]) {
                        @backingInt(PageKind.document) => blk: {
                            const record = try decodeDocumentEntry(try decodePagePayload(raw, .document));
                            break :blk .{ record.external_value_root_page, record.external_value_len };
                        },
                        @backingInt(PageKind.catalog) => blk: {
                            const record = try decodeCatalogEntry(try decodePagePayload(raw, .catalog));
                            break :blk .{ record.external_value_root_page, record.external_value_len };
                        },
                        else => return error.InvalidNativeAllocator,
                    };
                    if (root != 0) try self.indexedValue(graph, checkpoint, root, length, cancel);
                },
            }
        }
        for (state.counts.items, 0..) |references, page| {
            if (cancel) |token| try token.check();
            const wanted = expected.count(page);
            if (references == allocator_v4.free) {
                if (wanted != 0) return error.InvalidNativeAllocator;
            } else if (references != wanted) {
                // allocatePage exposes owned raw blocks without an index edge.
                if (wanted != 0 or references != 1) return error.InvalidNativeAllocator;
                const raw = try self.readPageAllocForCheckpoint(self.allocator, page, checkpoint);
                defer self.allocator.free(raw);
                _ = try decodePagePayload(raw, .data);
            }
        }
    }

    fn validateIndexedAllocator(self: *NativeFile, checkpoint: CheckpointSlot, state: *allocator_v4.State, cancel: ?*const maintenance.CancelToken) !u64 {
        var window: AllocatorProofWindow = undefined;
        window.initInto(self);
        defer window.deinit();
        // §9 (redo + indexed reclamation): a diverting commit advances
        // `checkpoint.page_count` on its own, directly, for a fresh
        // external value chain (`pageAllocatorForDivertingCommit`)
        // without ever touching the ledger, so `checkpoint.page_count`
        // legitimately runs ahead of the ledger's own `covered_pages`
        // between two real checkpoints. A ledger that claims to cover
        // *more* pages than the checkpoint's own page_count is still
        // always invalid, redo or not: no page beyond page_count exists
        // yet for anything to be owned within.
        const allow_behind = self.header.redo_log_capacity != 0;
        if (if (allow_behind) state.root.covered_pages > checkpoint.page_count else state.root.covered_pages != checkpoint.page_count) return error.InvalidNativeAllocator;
        // §9 (redo + indexed reclamation): `state` was loaded against, and
        // `checkpoint` names, one specific generation -- but neither caller
        // of this function holds any lock that stops another generation
        // from becoming active while this call is still reading (`check()`
        // in particular calls through `NativeFile.checkAtFileSizeWithCancel`
        // with no store-level lock at all, by design, so a live redo-log
        // file's background `rideAlongFlushLoop`/`maybeCheckpointRedoLogOnIdleTurn`
        // can publish a newer checkpoint -- a real, correct commit, not a
        // corruption -- between this function's caller capturing
        // `checkpoint` and this line re-reading `self.activeCheckpoint()`).
        // That is a genuine supersession, not an ownership defect: `state`
        // and `checkpoint` remain fully self-consistent with each other
        // (copy-on-write means `checkpoint`'s own pages are never mutated
        // in place), so this is reported as its own distinct, retryable
        // condition rather than folded into `error.InvalidNativeAllocator`
        // -- a caller that captures a fresh checkpoint and retries (see
        // `checkAtFileSizeWithCancel`) converges once the background
        // publisher goes quiet; one that doesn't still fails closed.
        if (!std.meta.eql(self.activeCheckpoint(), checkpoint)) return error.NativeCheckpointSuperseded;
        var expected = allocator_v4.State.init(self.allocator);
        defer expected.deinit();
        var active_graph = try self.indexedGraphUsingLeaves(checkpoint, &expected, null, true, cancel);
        defer active_graph.deinit(self.allocator);
        const active_records = active_graph.record_count;
        // Active pages are checked first so fallback certificates can rely on
        // their liveness even when the active checkpoint occupies slot one.
        //
        // perf/lwa-lease-fold: under redo, the *other* (inactive) slot is
        // never a real recovery candidate the way it is under legacy --
        // see `metadataReuseFrontier`'s own doc comment: an ordinary redo
        // commit never touches either on-disk slot at all, only a real
        // fold does, and that slot's own write is confirmed durable
        // before the call that made it ever returns. The inactive slot
        // is simply whatever the *previous* real fold left behind --
        // stale, not a second valid recovery outcome -- and once
        // `redo_folded_through`-gated reuse (this same perf/lwa-lease-fold
        // change) lets a later real fold's own retirement free pages the
        // inactive slot still references, validating it here as if it
        // still needed every one of them to stay live is exactly the
        // legacy double-buffer invariant this file no longer has: a
        // `.free_map` page read through it can legitimately already be
        // something else (reused once the redo-aware frontier agreed to
        // it), which is not corruption, just this check asking a
        // question redo's own recovery contract never promises an
        // answer to. Validate only the slot redo's own recovery would
        // ever actually choose.
        const checked_slots: []const usize = if (self.redo != null)
            &[_]usize{self.header.active_checkpoint}
        else
            &[_]usize{ self.header.active_checkpoint, 1 - @as(usize, self.header.active_checkpoint) };
        for (checked_slots) |index| {
            const slot = self.header.checkpoints[index];
            if (!validCheckpointSlot(slot)) continue;
            const active = index == self.header.active_checkpoint;
            var fallback: ?IndexedGraph = if (active) null else try self.indexedGraphUsingLeaves(slot, null, &active_graph.leaf_proofs, false, cancel);
            defer if (fallback) |*graph| graph.deinit(self.allocator);
            const graph = if (fallback) |*other| other else &active_graph;
            var pages = graph.pages.keyIterator();
            while (pages.next()) |page| {
                if (cancel) |token| try token.check();
                if (state.count(page.*) == allocator_v4.free or state.count(page.*) == 0) return error.InvalidNativeAllocator;
            }
            const old_payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, slot.free_map_root_page, .free_map, slot);
            defer self.allocator.free(old_payload);
            const old_root = try allocator_v4.State.decodeRoot(old_payload);
            // Same `allow_behind` lag as this function's own
            // `covered_pages` check above -- `slot` here can be a
            // ride-along (non-durable) checkpoint snapshot whose
            // `page_count` several diverting commits already advanced
            // in memory (`flushTransactionWrites`'s own `next.page_count
            // = writes.pages.next_page_id;`, unconditional regardless of
            // `diverting`), while its *free_map_root_page* is untouched
            // since those commits never rebuild the free map -- so this
            // slot's own stored root legitimately still covers fewer
            // pages than `slot.page_count` now says.
            if ((if (allow_behind) old_root.covered_pages > slot.page_count else old_root.covered_pages != slot.page_count) or state.count(slot.free_map_root_page) == allocator_v4.free) return error.InvalidNativeAllocator;
            // The fallback may name an older ledger. Read it independently;
            // loading it into the owner's cache would discard current state.
            var pinned_old_ctx = CheckpointPinnedLedgerContext{ .file = self, .checkpoint = slot };
            var old_state = try allocator_v4.State.load(self.allocator, .{ .context = &pinned_old_ctx, .allocate = pinnedLedgerReadOnlyAllocate, .read = pinnedLedgerReadAny, .write = pinnedLedgerReadOnlyWrite, .payload_bytes = self.maxPagePayloadBytes(), .cancel_requested = if (cancel) |token| &token.requested else null }, slot.free_map_root_page);
            defer old_state.deinit();
            for (old_state.metadata.items) |page| {
                if (cancel) |token| try token.check();
                if (state.count(page) == allocator_v4.free) return error.InvalidNativeAllocator;
            }
            if (active) {
                // Same supersession as the entry check above (this
                // function's own doc comment on `error.NativeCheckpointSuperseded`):
                // `self.header.active_checkpoint`/its slot can legitimately
                // have moved on since `checkpoint` was captured, with no
                // lock held across this call to stop it.
                if (!std.meta.eql(slot, checkpoint)) return error.NativeCheckpointSuperseded;
                try self.validateIndexedOwnership(checkpoint, state, graph, &expected, cancel);
            }
        }
        return active_records;
    }

    fn ledgerReadAny(context: *anyopaque, a: Allocator, page: u64) ![]u8 {
        const file: *NativeFile = @ptrCast(@alignCast(context));
        const raw = try file.readPageAlloc(a, page);
        defer a.free(raw);
        const kind: PageKind = switch (raw[4]) {
            @backingInt(PageKind.free_map) => .free_map,
            @backingInt(PageKind.allocator) => .allocator,
            else => return error.InvalidNativeAllocator,
        };
        return try a.dupe(u8, try decodePagePayload(raw, kind));
    }

    /// §9 (redo + indexed reclamation): a checkpoint-pinned twin of
    /// `ledgerReadAny`, for the one caller (`check()`, via
    /// `checkAtFileSizeWithCancel`/`validateIndexedAllocator`'s own
    /// `old_state` load) that reads a ledger with no writer-exclusive lock
    /// held across the whole call -- `ledgerReadAny`'s `file.readPageAlloc`
    /// reads through `self.activeCheckpoint()` (today's, whatever that
    /// happens to be *right now*), which is exactly right for every other
    /// caller (always under the single-writer lock, so it cannot move
    /// mid-call) but wrong here: a redo-log file's background
    /// `rideAlongFlushLoop`/`checkpointRedoLog` can publish a newer
    /// checkpoint between any two of this multi-page load's own reads,
    /// and -- with page reuse enabled -- can have already retired and
    /// reused one of the very pages this load is mid-way through reading,
    /// so two reads of "the same" page id inside one `State.load` call
    /// could silently return two different generations' content. That
    /// torn view is what let `State.load`'s own `next_id`-vs-delta-chain
    /// consistency checks fire spuriously (confirmed via the redo
    /// differential oracle, seed 1). Reading through the *specific*
    /// checkpoint the caller is loading, instead of whatever is active at
    /// the instant each individual page read happens, makes the whole
    /// load self-consistent regardless of how much the live file moves on
    /// underneath it; `validateIndexedAllocator`'s own
    /// `NativeCheckpointSuperseded` retry (same doc comment) is the
    /// complementary half -- it catches "the checkpoint identity itself
    /// moved on", this catches "a page read mid-load could have torn".
    const CheckpointPinnedLedgerContext = struct { file: *NativeFile, checkpoint: CheckpointSlot };

    fn pinnedLedgerReadAny(context: *anyopaque, a: Allocator, page: u64) ![]u8 {
        const ctx: *CheckpointPinnedLedgerContext = @ptrCast(@alignCast(context));
        const raw = try ctx.file.readPageAllocForCheckpoint(a, page, ctx.checkpoint);
        defer a.free(raw);
        const kind: PageKind = switch (raw[4]) {
            @backingInt(PageKind.free_map) => .free_map,
            @backingInt(PageKind.allocator) => .allocator,
            else => return error.InvalidNativeAllocator,
        };
        return try a.dupe(u8, try decodePagePayload(raw, kind));
    }

    fn pinnedLedgerReadOnlyAllocate(_: *anyopaque) !u64 {
        return error.ReadOnly;
    }

    fn pinnedLedgerReadOnlyWrite(_: *anyopaque, _: u64, _: []const u8) !void {
        return error.ReadOnly;
    }

    fn publicationEpoch(self: *NativeFile) u64 {
        if (self.private_retirement_epoch) |epoch| return epoch;
        const header = self.transaction_header orelse self.header;
        return header.checkpoints[header.active_checkpoint].commit_sequence + 1;
    }
    fn metadataReuseFrontier(self: *NativeFile) u64 {
        var frontier: u64 = std.math.maxInt(u64);
        const header = self.transaction_header orelse self.header;
        // perf/lwa-lease-fold: under redo, a crash cannot recover to an
        // arbitrary earlier checkpoint slot the way legacy's own
        // per-commit two-slot alternation needs to guard against --
        // ordinary redo commits (diverting, or a bare already-real one)
        // never touch either on-disk slot at all (`publishCheckpoint`'s
        // own redo branch rewrites `self.header.checkpoints[active]`
        // in-memory only); only a real fold (`checkpointRedoLog`, or
        // this file's own ledger-only commit) ever performs the v8/v9
        // slot write that advances `active_checkpoint`, and that write
        // is confirmed durable (synced) before the call that made it
        // ever returns -- by the time any later caller reaches this
        // frontier, there is no in-flight, possibly-torn write for a
        // crash to fall back past. Recovery's own real boundary under
        // redo is `redo_folded_through` (format v11): "the slot recovery
        // would choose" is simply `activeCheckpoint()` (the one real
        // folds keep advancing; ordinary commits only ever bump its
        // `commit_sequence` in memory, never its `redo_folded_through`,
        // which already "carries forward unchanged" until the next real
        // fold -- same field, same value, whether that commit reads it
        // mid-transaction or `durable_header` holds an older copy), and
        // its own `redo_folded_through` is exactly the point below which
        // everything is already in the real tree; anything still above
        // it is live-but-unfolded redo overlay content, already kept
        // alive by the overlay's own retention (`SharedRedoOverlay.pin`/
        // `maybeClearPages`), not by this frontier. Using the raw
        // two-slot minimum here instead -- the legacy term below --
        // treats every ordinary commit as if it were a real fold that
        // might not have landed yet, which it structurally cannot be
        // under redo: that term only ever advances on the next real
        // fold, so a workload that only folds rarely (or whose folds
        // never clear page-shaped debt at all) never reuses anything,
        // independent of whether reuse would actually be safe.
        //
        // `self.redo.?.checkpointing` is true for exactly the span of a
        // real-fold-equivalent commit's own transaction
        // (`checkpointRedoLog`, `reclaimPagesImpl`'s own ledger-only
        // commit) -- both call this function themselves, through their
        // own `pageAllocatorFromFreeMapWithProof`'s inline drain and
        // (`reclaimPagesImpl`) their own explicit `drainRetirement` call,
        // *before* their own `publishCheckpoint` has run, so
        // `header.checkpoints[active].redo_folded_through` read at that
        // moment is still last fold's value, one commit stale -- the
        // same "my own flip lands after I already read the old value"
        // gap the two-slot term had, just moved to a different field.
        // Unlike an ordinary commit, this exact transaction's own
        // `redo_folded_through` is already fully determined before any
        // of its own building starts (`self.transaction_header`, snapshot
        // at `beginTransaction`, never moves again), and is one atomic
        // unit with everything `drainRetirement` does here: either this
        // whole transaction commits, making that boundary real, or it
        // aborts and nothing this call did persists either. Safe to use
        // early, exactly like `publicationEpoch()` -- same formula --
        // already does for the retirement items this same fold queues.
        if (self.redo) |redo| {
            frontier = @min(frontier, if (redo.checkpointing) self.publicationEpoch() else header.checkpoints[header.active_checkpoint].redo_folded_through);
        } else {
            for (header.checkpoints) |slot| if (validCheckpointSlot(slot)) {
                frontier = @min(frontier, slot.commit_sequence);
            };
            if (self.durable_header) |durable| for (durable.checkpoints) |slot| {
                if (validCheckpointSlot(slot)) frontier = @min(frontier, slot.commit_sequence);
            };
        }
        if (self.epoch_window) |epochs| if (epochs.metadata) |sequence| {
            frontier = @min(frontier, sequence);
        };
        frontier = @min(frontier, self.minimum_metadata_reader_sequence orelse frontier);
        // In-process reader-pin registry (inode_lock.Entry.reader_pins):
        // covers a reader category none of the terms above reach -- see
        // that field's own doc comment and `captureFullReadSnapshot`.
        if (self.inode_lock_ref.load(.acquire)) |entry| {
            if (inode_lock.minimumMetadataReaderSequence(entry, self.runtime())) |sequence| frontier = @min(frontier, sequence);
        }
        return frontier;
    }
    fn reuseFrontier(self: *NativeFile) u64 {
        var frontier = self.metadataReuseFrontier();
        if (self.epoch_window) |epochs| if (epochs.data) |sequence| {
            frontier = @min(frontier, sequence);
        };
        frontier = @min(@min(frontier, self.minimum_reader_sequence orelse frontier), if (self.reader_frontier) |readers| readers.load(.acquire) else frontier);
        if (self.inode_lock_ref.load(.acquire)) |entry| {
            if (inode_lock.minimumReaderSequence(entry, self.runtime())) |sequence| frontier = @min(frontier, sequence);
        }
        return frontier;
    }

    /// Work is bounded by retired graph objects, including value subtrees. A
    /// delete only enqueues its record; value-page traversal happens here.
    fn retiredAllocatorNext(self: *NativeFile, page: u64, checkpoint: CheckpointSlot) !u64 {
        const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, page, .allocator, checkpoint);
        defer self.allocator.free(payload);
        if (payload.len < 16 or (!std.mem.eql(u8, payload[0..4], "L4SS") and !std.mem.eql(u8, payload[0..4], "L4RQ") and !std.mem.eql(u8, payload[0..4], "L4DL"))) return error.InvalidNativeAllocator;
        return std.mem.readInt(u64, payload[8..16], .little);
    }

    /// The inline drainRetirement call every foreground commit makes (inside
    /// pageAllocatorFromFreeMapWithProof) is capped to this many pages,
    /// independent of the much larger background-maintenance budget
    /// (retirement_work_pages, reclaimPagesForMaintenanceWithCancel's own
    /// separate call). Reclaiming cold, first-touch pages is background
    /// maintenance's job; the foreground path only needs enough headroom
    /// that a backlog never grows unbounded between maintenance turns.
    const foreground_retirement_cap_pages: usize = 16;

    fn drainRetirement(self: *NativeFile, state: *allocator_v4.State, checkpoint: CheckpointSlot, budget: usize, fence_held: bool) !usize {
        // A registering reader may still hold its shared inode lock before
        // publishing its epoch. Without the exclusive scan fence, even
        // logical promotion would let a later writer consume that reader's
        // old pages. `fence_held` (not `self.epoch_window != null`) is the
        // right test for that: `epoch_window` only reflects *cross-process*
        // readers (via a shared `regionForInode()`), so it stays null
        // whenever no `reader_coordinator` is configured -- the common,
        // single-process case -- even though the caller's own exclusive
        // inode lock (`acquireEpochReuseLock`, unconditional whether or not
        // a region exists) already fences every other writer, and
        // in-process readers are tracked unconditionally by `reuseFrontier`/
        // `metadataReuseFrontier` themselves (reader pins, `ReadView`s),
        // not by `epoch_window`. Treating "no region" as "fence not held"
        // made this a permanent no-op for any store without a configured
        // `reader_coordinator`: `state.heap`/`metadata_heap`/`chains_heap`
        // items were never completed/released on that path (confirmed live
        // as "lite reclamation writable reopen services debt and read only
        // reopen does not (redo)" never reaching a bounded steady state --
        // this file's own ledger bookkeeping pages, retired every fold,
        // never promoted back to reusable). Not redo-specific: this gate
        // has no legacy/redo branch, so it was equally dead for legacy
        // `page_reuse = true` stores with no reader_coordinator.
        if (budget == 0 or !fence_held) return 0;
        const frontier = self.reuseFrontier();
        const metadata_frontier = self.metadataReuseFrontier();
        // Completed data/chain pages use the metadata fence too: recovery can
        // replay an older retirement queue that still needs their bytes. Scale
        // physical reuse promotion with the maximum key fanout of data work.
        const promotions = @max(@as(usize, 8), budget *| (self.maxPagePayloadBytes() / 18 + 2));
        for (0..promotions) |_| {
            if (self.allocator_cancel_token) |token| try token.check();
            const root = state.metadata_heap.peek() orelse break;
            if (root.epoch > metadata_frontier) break;
            if (root.page == 0 or root.page >= checkpoint.page_count) return error.InvalidNativeAllocator;
            try state.complete(root);
            try state.releaseMetadata(root.page);
        }
        // Metadata service must retire more pages than its own publication
        // creates. Scale cleanup with data work and keep an eight-page minimum
        // so even a one-object budget drains its publication overhead.
        for (0..@max(@as(usize, 8), budget)) |_| {
            if (self.allocator_cancel_token) |token| try token.check();
            const item = state.chains_heap.peek() orelse break;
            if (item.epoch > metadata_frontier) break;
            if (state.pending.count() + 8 >= state.pending_limit + allocator_v4.collector_reserve) break;
            const linked_page = try self.retiredAllocatorNext(item.page, checkpoint);
            const next_page = if (linked_page == item.length) 0 else linked_page;
            try state.complete(item);
            try state.retireCollected(.{ .epoch = self.publicationEpoch(), .page = item.page, .kind = .metadata });
            if (next_page != 0) try state.retireCollected(.{ .epoch = item.epoch, .page = next_page, .length = item.length, .kind = .allocator_chain });
        }
        var done: usize = 0;
        while (done < budget) : (done += 1) {
            if (self.allocator_cancel_token) |token| try token.check();
            const item = state.heap.peek() orelse break;
            if (item.epoch > frontier) break;
            // A single node can discover value children or release many typed
            // keys. Keep publication space when collector admission is full;
            // advancing slots then promotes older completed pages first.
            const expansion: usize = switch (item.kind) {
                .value => 64 + 8,
                .index => self.maxPagePayloadBytes() / 18 + 8,
                else => 8,
            };
            if (state.pending.count() + expansion >= state.pending_limit + allocator_v4.collector_reserve) break;
            if (physicalPage(item.page) == 0 or physicalPage(item.page) >= checkpoint.page_count) return error.InvalidNativeAllocator;
            try state.complete(item);
            switch (item.kind) {
                .metadata => try state.releaseMetadata(item.page),
                .allocator_chain => return error.InvalidNativeAllocator,
                .page => {
                    _ = try self.releaseRetiredPage(state, item.page);
                },
                .record => {
                    const raw = try self.readPageAllocForCheckpoint(self.allocator, item.page, checkpoint);
                    defer self.allocator.free(raw);
                    const root, const length = switch (raw[4]) {
                        @backingInt(PageKind.document) => blk: {
                            const record = try decodeDocumentEntry(try decodePagePayload(raw, .document));
                            state.retired_inline_bytes +|= record.key.len + record.value.len;
                            break :blk .{ record.external_value_root_page, record.external_value_len };
                        },
                        @backingInt(PageKind.catalog) => blk: {
                            const record = try decodeCatalogEntry(try decodePagePayload(raw, .catalog));
                            state.retired_inline_bytes +|= record.key.len + record.value.len;
                            break :blk .{ record.external_value_root_page, record.external_value_len };
                        },
                        else => return error.InvalidNativeAllocator,
                    };
                    if (root != 0) try state.retireCollected(.{ .epoch = item.epoch, .page = root, .length = length, .kind = .value });
                    _ = try self.releaseRetiredPage(state, physicalPage(item.page));
                },
                .index => {
                    const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, item.page, .document_index, checkpoint);
                    defer self.allocator.free(payload);
                    var frame: IndexReadFrame = .{};
                    defer frame.deinit(self.allocator);
                    try frame.decode(self.allocator, payload);
                    for (0..frame.entries().len) |i| {
                        const key = frame.keyReference(i);
                        if (key == 0) continue;
                        _ = try self.releaseRetiredPage(state, physicalPage(key));
                    }
                    _ = try self.releaseRetiredPage(state, item.page);
                },
                .value => {
                    // Children belong to a shared immutable node, rather than
                    // separately to every document that points at its root.
                    if (try self.releaseRetiredPage(state, item.page)) {
                        const raw = try self.readPageAllocForCheckpoint(self.allocator, item.page, checkpoint);
                        defer self.allocator.free(raw);
                        switch (raw[4]) {
                            @backingInt(PageKind.value) => {
                                const value = try decodeValuePage(try decodePagePayload(raw, .value));
                                if (value.chunk.len == 0 or value.chunk.len > item.length) return error.InvalidNativeValueChain;
                                if (value.next_page != 0) try state.retireCollected(.{ .epoch = item.epoch, .page = value.next_page, .length = item.length - value.chunk.len, .kind = .value });
                            },
                            @backingInt(PageKind.value_extent) => {
                                const node = try decodeExtentNode(try decodePagePayload(raw, .value_extent), item.length);
                                for (node.children[0..node.count]) |child| try state.retireCollected(.{ .epoch = item.epoch, .page = child.page, .length = child.len, .kind = .value });
                            },
                            else => return error.InvalidNativeValueChain,
                        }
                    }
                },
            }
        }
        return done;
    }

    fn releaseRetiredPage(self: *NativeFile, state: *allocator_v4.State, page: u64) !bool {
        const last = try state.releaseDeferred(page);
        if (last) {
            try state.retireCollected(.{ .epoch = self.publicationEpoch(), .page = page, .kind = .metadata });
            state.released_data_pages +|= 1;
        }
        return last;
    }

    /// Writes `slot` to its dedicated physical page. Bypasses the normal
    /// page cache/allocator path (as the header page always has): slot
    /// pages are never read back except at open/recovery time.
    fn writeSlotPage(self: *NativeFile, index: u8, slot: CheckpointSlot) !void {
        try writeSlotPageTo(self.file, self.runtimeIo(), self.header.page_size, index, slot);
    }

    fn initializeIndexedAllocator(self: *NativeFile) !void {
        if (self.activeCheckpoint().page_count != reserved_header_pages) return error.InvalidTransactionState;
        self.header.indexed_reclamation = true;
        self.header.packed_records = true;
        // createWithRuntime's first header write always encodes the
        // all-defaults (non-indexed) Header{} literal, before it is known
        // whether this file ends up indexed. Correct it now that
        // indexed_reclamation (and the identity namespace) are final: the
        // magic bytes and reader_epoch_namespace this function just set
        // must land on disk, since nothing else here rewrites the header.
        var header_buf: [header_size]u8 = undefined;
        encodeHeader(&header_buf, self.header);
        try self.file.writePositionalAll(self.runtimeIo(), &header_buf, 0);
        var pages = try self.pageAllocatorFromFreeMap(self.activeCheckpoint());
        defer pages.deinit();
        var checkpoint = self.activeCheckpoint();
        checkpoint.free_map_root_page = try pages.allocate();
        try self.persistAllocator(&pages, &checkpoint);
        // The bootstrap commit has no prior durable slot to race against:
        // it is covered by createWithRuntime's own single closing sync, the
        // same way the header and the rest of this commit's pages are. No
        // manifest is needed.
        checkpoint.presynced = true;
        checkpoint.manifest_page = 0;
        checkpoint.manifest_crc = 0;
        checkpoint.manifest_page_count = 0;
        self.header.checkpoints = .{ checkpoint, checkpoint };
        try self.writeSlotPage(0, checkpoint);
        try self.writeSlotPage(1, checkpoint);
        try self.syncIfRequired(null);
    }

    fn stampLogicalGenerations(self: *NativeFile, checkpoint: *CheckpointSlot) !void {
        if (!self.header.indexed_reclamation) return;
        const before = self.activeCheckpoint();
        if ((before.document_root_page != checkpoint.document_root_page or
            before.document_index_root_page != checkpoint.document_index_root_page or
            before.namespace_directory_root_page != checkpoint.namespace_directory_root_page) and
            std.mem.eql(u8, &before.logical.primary, &checkpoint.logical.primary))
            try self.runtimeIo().randomSecure(&checkpoint.logical.primary);
        if (before.index_catalog_root_page != checkpoint.index_catalog_root_page and
            std.mem.eql(u8, &before.logical.indexes, &checkpoint.logical.indexes))
            try self.runtimeIo().randomSecure(&checkpoint.logical.indexes);
        if (before.catalog_root_page != checkpoint.catalog_root_page and !self.artifact_lease_transaction and
            std.mem.eql(u8, &before.logical.metadata, &checkpoint.logical.metadata))
            try self.runtimeIo().randomSecure(&checkpoint.logical.metadata);
    }

    fn persistAllocator(self: *NativeFile, pages: *PageAllocator, checkpoint: *CheckpointSlot) !void {
        // Certificate fingerprints include identities before any seal is built.
        try self.stampLogicalGenerations(checkpoint);
        if (!self.header.indexed_reclamation) {
            checkpoint.page_count = pages.next_page_id;
            return self.writeFreeMapPage(checkpoint.free_map_root_page, checkpoint.page_count, pages.remainingFreePages());
        }
        const state = pages.ledger orelse return error.InvalidNativeAllocator;
        var orphaned = pages.pending_values.iterator();
        while (orphaned.next()) |entry| try state.retire(.{ .epoch = self.publicationEpoch(), .page = entry.key_ptr.*, .length = entry.value_ptr.*, .kind = .value });
        pages.pending_values.clearRetainingCapacity();
        // Writers contribute bounded metadata work too, so a busy owner does
        // not depend on scheduling to compact journals before reaching quota.
        // Small tables finish in one bounded publication; large builders advance
        // at most two pages. Explicit service and private normalization supply
        // their own checkpoint budget.
        if (state.incremental and state.root.snapshot != 0 and self.retirement_work_pages != 0 and self.private_retirement_epoch == null) {
            if (state.checkpointDue() or self.budgetedCheckpointDue(state)) {
                try self.advanceAllocatorCheckpoint(pages, 2);
            }
        }
        try state.preparePersist(self.publicationEpoch(), self.maxPagePayloadBytes());
        // Consume free bits before emitting the journal/snapshot. Otherwise the
        // next open could allocate one of the allocator's own metadata pages.
        while (pages.metadata_reserve.items.len < state.pagesRequired(self.maxPagePayloadBytes())) {
            if (self.allocator_cancel_token) |token| try token.check();
            try pages.metadata_reserve.append(self.allocator, try pages.allocate());
        }
        try pages.flush();
        try state.persist(.{ .context = pages, .allocate = PageAllocator.takeMetadataPage, .read = PageAllocator.readLedgerPage, .write = PageAllocator.writeLedgerPage, .payload_bytes = self.maxPagePayloadBytes(), .cancel_requested = if (self.allocator_cancel_token) |token| &token.requested else null }, checkpoint.free_map_root_page, &pages.next_page_id);
        if (pages.metadata_cursor != pages.metadata_reserve.items.len) return error.InvalidNativeAllocator;
        checkpoint.page_count = pages.next_page_id;
        pages.ledger_persisted = true;
        if (self.reserve_retirement_capacity and !self.maintenance_publication) {
            if (self.max_file_bytes) |limit| {
                const available = (limit / self.header.page_size -| pages.next_page_id) +|
                    (if (pages.can_reuse) state.free_pages else 0);
                if (available < allocator_v4.retirementReservePages(self.maxPagePayloadBytes(), state.counts.items.len, state.pending.count())) return error.LiteStorageBudgetExceeded;
            }
        }
    }

    pub fn retirementReserveBytes(self: *NativeFile) !u64 {
        return self.retirementReserveBytesWithCancel(self.allocator_cancel_token);
    }

    pub fn retirementReserveBytesWithCancel(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !u64 {
        if (cancel) |token| try token.check();
        if (!self.header.indexed_reclamation) return 0;
        const state = try self.loadLedgerWithCancel(self.activeCheckpoint(), cancel);
        return allocator_v4.retirementReservePages(self.maxPagePayloadBytes(), state.counts.items.len, state.pending.count()) *| self.header.page_size;
    }

    pub fn estimatedGenerationReserveBytes(self: *const NativeFile, compact_bytes: u64) u64 {
        if (!(self.vacuum_target_indexed or self.header.indexed_reclamation)) return 0;
        const covered = std.math.divCeil(u64, compact_bytes, self.header.page_size) catch return std.math.maxInt(u64);
        return allocator_v4.retirementReservePages(self.maxPagePayloadBytes(), covered, 0) *| self.header.page_size;
    }

    /// Creation is admitted before opening/truncating/renaming any artifact.
    pub fn minimumOwnerStorageBytes(indexed: bool) u64 {
        if (!indexed) return default_page_size;
        return (3 + allocator_v4.retirementReservePages(default_page_size - page_header_size, 3, 0)) * default_page_size;
    }

    pub const AllocatorStats = struct {
        reusable_pages: u64,
        pending_objects: u64,
        pending_data_objects: u64,
        reused_pages: u64,
        serviced_objects: u64,
        journal_bytes: u64,
        data_frontier: u64,
        metadata_frontier: u64,
        oldest_data_epoch: ?u64,
        oldest_metadata_epoch: ?u64,
    };

    pub fn allocatorStats(self: *NativeFile) !?AllocatorStats {
        return self.allocatorStatsWithCancel(self.allocator_cancel_token);
    }

    pub fn allocatorStatsWithCancel(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !?AllocatorStats {
        if (cancel) |token| try token.check();
        if (!self.header.indexed_reclamation) return null;
        const state = try self.loadLedgerWithCancel(self.activeCheckpoint(), cancel);
        return .{
            .reusable_pages = state.free_pages,
            .pending_objects = state.pending.count(),
            .pending_data_objects = state.data_pending,
            .reused_pages = state.allocations,
            .serviced_objects = state.collected,
            .journal_bytes = state.root.delta_bytes,
            .data_frontier = self.reuseFrontier(),
            .metadata_frontier = self.metadataReuseFrontier(),
            .oldest_data_epoch = if (state.heap.peek()) |item| item.epoch else null,
            .oldest_metadata_epoch = if (state.metadata_heap.peek()) |item| item.epoch else null,
        };
    }

    pub fn retirementNeedsService(self: *NativeFile) !bool {
        return self.retirementNeedsServiceWithCancel(self.allocator_cancel_token);
    }

    pub fn retirementNeedsServiceWithCancel(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !bool {
        return self.retirementNeedsServiceCoreWithCancel(cancel, true);
    }

    /// §9 (redo retirement signal): the same check, but never considering
    /// redo-overlay debt. Formerly used by `Store.startMaintenanceAssumeLocked`
    /// (docstore.zig) to avoid starting the background maintenance loop
    /// for a redo-only retirement reason, which used to race a live redo
    /// commit's own overlay/pending state (§9.7d). One mechanism behind
    /// that race is fixed at the source now (`RedoCommitState
    /// .appendRecord`'s own doc comment: a failed sync/append undoes its
    /// staged overlay content instead of leaving it permanently published
    /// with no durable record), so `startMaintenanceAssumeLocked` is back
    /// on the full, `retirementNeedsServiceWithCancel` signal like every
    /// other caller -- a second, separately-tracked mechanism is not yet
    /// fixed (see that function's own comment). Kept only for the
    /// regression test that pins the full signal is wired in
    /// ("startMaintenanceAssumeLocked starts for a redo-only retirement
    /// signal", docstore.zig) by contrasting against this one.
    pub fn retirementNeedsServiceLedgerOnlyWithCancel(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !bool {
        return self.retirementNeedsServiceCoreWithCancel(cancel, false);
    }

    fn retirementNeedsServiceCoreWithCancel(self: *NativeFile, cancel: ?*const maintenance.CancelToken, consider_redo_debt: bool) !bool {
        if (cancel) |token| try token.check();
        if (!self.header.indexed_reclamation or self.read_only) return false;
        const state = try self.loadLedgerWithCancel(self.activeCheckpoint(), cancel);
        if (state.checkpointDue() or self.budgetedCheckpointDue(state)) return true;
        // §9 (redo retirement signal): under the redo log, a superseded
        // overlay version's chain (an old external-value chain included)
        // is retirement debt the on-disk ledger above cannot see -- only
        // `checkpointRedoLog`'s next fold discovers and retires it. "The
        // overlay has anything at all" was tried and rejected (it fires
        // for a plain, never-overwritten bulk insert, which supersedes
        // nothing); `pendingRetirementVersions` only counts versions a
        // *later* write in this same uncheckpointed window has actually
        // superseded, so a key touched exactly once since the last
        // checkpoint contributes zero. Unconditional like the two checks
        // above: there is no epoch/reader-fence question to ask yet (the
        // real `Retirement` item this debt will become does not exist
        // until the fold runs), so this can only ever be a useful next
        // step, never a wrong one -- except for `consider_redo_debt ==
        // false`'s own caller, see that parameter's doc comment above.
        if (consider_redo_debt and self.redoCheckpointWouldRetire()) return true;
        const excess_promotions = state.metadata_heap.count() > 2;
        if (state.data_pending == 0 and state.chains_heap.count() == 0 and !excess_promotions) return false;
        if (excess_promotions) {
            const root = state.metadata_heap.peek().?;
            if (root.epoch <= self.metadataReuseFrontier() or self.durable_header == null) return true;
        }
        if (state.eligibleWork(self.reuseFrontier(), self.metadataReuseFrontier()) != null) return true;
        // Metadata readers are fenced by recovery/durability slots, so a
        // pinned data transaction cannot prevent advancing an idle chain.
        if (state.chains_heap.count() != 0 and self.durable_header == null) return true;
        const item = state.heap.peek() orelse return false;
        // Advancing a fallback slot makes progress only if a reader or a
        // deferred durability barrier is not the remaining visibility fence.
        return item.epoch <= self.reuseFrontier() or (self.minimum_reader_sequence == null and (if (self.reader_frontier) |readers| readers.load(.acquire) == std.math.maxInt(u64) else true) and self.durable_header == null);
    }

    fn budgetedCheckpointDue(self: *NativeFile, state: *allocator_v4.State) bool {
        if (!self.reserve_retirement_capacity) return false;
        _ = self.max_file_bytes orelse return false;
        // Budgeted owners compact profitable sparse journals proactively. A
        // write may need substantially more than collector reserve; waiting
        // until reserve itself is threatened can leave a rejected large write
        // with no eligible data debt and no maintenance work to free capacity.
        // Require twice the snapshot size to amortize construction/publication
        // and avoid a checkpoint-per-service loop.
        const snapshot_bytes = allocator_v4.snapshotPages(self.maxPagePayloadBytes(), state.counts.items.len, state.pending.count()) *| self.maxPagePayloadBytes();
        return state.root.delta_bytes >= 2 *| snapshot_bytes;
    }

    /// §9 (redo retirement signal): true when the overlay holds at least
    /// one version a fold would discover is garbage (see
    /// `SharedRedoOverlay.pending_retirement_versions`'s own doc comment).
    /// Read-only and O(1): a lock, a load, nothing allocated -- safe to
    /// call from `retirementNeedsServiceWithCancel` on every maintenance
    /// check.
    fn redoCheckpointWouldRetire(self: *NativeFile) bool {
        const redo = self.redo orelse return false;
        return redo.shared.pendingRetirementVersions(self.runtimeIo()) != 0;
    }

    fn advanceAllocatorCheckpoint(self: *NativeFile, pages: *PageAllocator, budget: usize) !void {
        const state = pages.ledger.?;
        if (state.root.build_limit == 0 and allocator_v4.snapshotPages(self.maxPagePayloadBytes(), state.counts.items.len, state.pending.count()) <= 3) {
            // Root/old-chain retirement can add a queue page and reserving
            // metadata can add a counter page. preparePersist caps this fast
            // path at four snapshot pages after those events have been added.
            state.force_checkpoint = true;
            return;
        }
        for (0..budget) |_| {
            const page = try pages.allocate();
            try state.checkpointStep(.{ .context = pages, .allocate = PageAllocator.takeMetadataPage, .read = PageAllocator.readLedgerPage, .write = PageAllocator.writeLedgerPage, .payload_bytes = self.maxPagePayloadBytes(), .cancel_requested = if (self.allocator_cancel_token) |token| &token.requested else null }, page, self.publicationEpoch());
            if (state.root.build_limit == 0) break;
        }
    }

    /// Services idle retirement and advances recovery slots independently of
    /// file shrinking. The owner serializes this with mutations and snapshots.
    pub fn reclaimPages(self: *NativeFile, budget: usize) !usize {
        return self.reclaimPagesWithCancel(budget, null);
    }

    /// A sustained writer must contribute reclamation before filling the bounded
    /// retirement queue. Background scheduling and online vacuum are insufficient
    /// admission guarantees, particularly while a copy pins an older generation.
    /// Called by the serialized owner before starting the caller's transaction.
    pub fn reclaimRetirementPressure(self: *NativeFile) !void {
        if (!self.header.indexed_reclamation or self.read_only) return;
        for (0..16) |_| {
            const state = try self.loadLedger(self.activeCheckpoint());
            if (state.pending.count() <= state.pending_limit / 2) return;
            if (!try self.retirementNeedsService()) return error.FileBusy;
            _ = try self.reclaimPages(4096);
        }
        // No caller mutation has started. Readers may retain the remaining debt;
        // reject admission rather than overflowing or spinning under the lock.
        const state = try self.loadLedger(self.activeCheckpoint());
        if (state.pending.count() > state.pending_limit / 2) return error.FileBusy;
    }

    pub fn reclaimPagesWithCancel(self: *NativeFile, budget: usize, cancel: ?*const maintenance.CancelToken) !usize {
        return self.reclaimPagesImpl(budget, cancel, true, true);
    }

    /// Detached housekeeping must not move an open's deferred graph proof
    /// into its short foreground publication fence. Unverified owners append
    /// allocator metadata; verified owners retain normal page reuse. Capacity
    /// limits still require proof/admission before using the free pool.
    ///
    /// `durable`: §3.2a ride-along. An ordinary background reclamation pass
    /// (the Store's own self-driven maintenance loop, not hard retirement
    /// pressure) passes `false`: the commit stages its freed pages and
    /// advanced checkpoint into `self.header`/`self.durable_header` without
    /// its own `syncData`, becoming durable for free on the next durable
    /// commit (a foreground write, this file's own idle-flush/close
    /// barrier, or cross-process lease handoff). Freed pages stay
    /// unreusable until then: page reuse is already gated on the durable
    /// epoch (`reuseFrontier`/`durable_header`), not on this commit alone.
    pub fn reclaimPagesForMaintenanceWithCancel(self: *NativeFile, budget: usize, cancel: ?*const maintenance.CancelToken, durable: bool) !usize {
        return self.reclaimPagesImpl(budget, cancel, false, durable);
    }

    fn reclaimPagesImpl(self: *NativeFile, budget: usize, cancel: ?*const maintenance.CancelToken, require_reuse_proof: bool, durable: bool) !usize {
        if (!self.header.indexed_reclamation or self.read_only) return 0;
        if (cancel) |token| try token.check();
        // §9 (redo retirement signal): a page-shaped write (an external
        // value chain) a diverting commit staged is real, physical
        // content the on-disk free map does not know about yet -- that
        // commit never touched the ledger at all (`checkpointRedoLog`'s
        // own "page-shaped exception" doc comment). Building a
        // `PageAllocator` from that stale free map below, as this
        // function's own ledger-only retirement is about to do, risks
        // allocating a page id a still-live staged chain already
        // occupies -- found by reproducing it: running this function's
        // existing ledger body on a redo file with a staged chain
        // corrupts that chain, surfacing later as `check()`'s
        // `unexpected_page_kind`. Only `checkpointRedoLog`'s own fold
        // (via `redo_fold_retain_pending`) reconciles the ledger with
        // that physical growth, so this function must not touch the
        // ledger while any page-shaped write is still staged, unless it
        // folds first.
        if (self.redo) |*redo| {
            const io = self.runtimeIo();
            // perf/lwa-reuse-loss: unfolded *logical* overlay content
            // (document/catalog heads still only in `redo.shared.maps`,
            // never yet applied to the real tree) is unsafe for this
            // body to run past for a different reason than staged pages
            // are: this body's own commit below (`redo.checkpointing =
            // true`, the same real-physical-publish branch of
            // `publishCheckpoint` `checkpointRedoLog`'s fold uses)
            // consumes a fresh `commit_sequence` for pure ledger/free-map
            // bookkeeping -- see `next.commit_sequence += 1` below and
            // its own doc comment ("this commit folds no logical
            // overlay"). That consumed sequence is never appended to the
            // log, so on the next reopen `recoverRedoLog`'s replay
            // treats `checkpoint.commit_sequence` (now this commit's own,
            // higher number) as the boundary below which everything is
            // already in the real tree -- but `redo.checkpoint_sequence`
            // (the *true* fold boundary, only `checkpointRedoLog` ever
            // advances) never moved, so every still-unfolded head with a
            // sequence between the true boundary and this commit's own
            // number is silently skipped as "superseded" on the next
            // open, even though it was never folded -- confirmed live as
            // "redo differential oracle" data loss and resurrection
            // across a reopen that follows a plain `Store.openWithOptions`
            // (every open runs one `maintainOnce`), with no explicit
            // checkpoint or page-shaped write involved at all. It is also
            // reachable from the background maintenance loop
            // (`startMaintenanceAssumeLocked`/`maintainOnceWithCancel`)
            // the moment `retirementNeedsService()` sees any overlay
            // debt, so this gate matters even for a scenario built to
            // exercise a different bug (`publishCheckpoint`'s log-full
            // fallback): without it, the background thread's own
            // `reclaimPagesImpl` pass can independently inflate
            // `commit_sequence` past unfolded content and reproduce this
            // same loss on its own.
            const has_unfolded_logical_work = for (0..3) |root_idx| {
                if (redo.shared.count(io, @intCast(root_idx)) != 0) break true;
            } else false;
            if (!redo.shared.pagesEmpty(io) or has_unfolded_logical_work) {
                // Folding is worth its own real, physical (and, outside
                // `no_sync`, syncing) commit only when capacity pressure
                // is the reason this function is running at all -- the
                // same `budgetedCheckpointDue` gate (a real
                // `max_file_bytes` reserve). An unbudgeted caller (e.g.
                // a plain `Store.maintainOnce` ride-along with no
                // storage limit configured) must stay exactly as cheap
                // and sync-free as the ledger-only path already is --
                // see the "ride-along passes force no sync" test, which
                // has no budget and must not pay for a fold it does not
                // need, and correctly does nothing here instead (the
                // debt it asserted via `retirementNeedsService` is real
                // but not yet safe nor urgent enough to act on without
                // one): `checkpointRedoLog`'s own commit is always
                // fully durable (never a ride-along -- see that
                // function's own doc comment), so running it
                // unconditionally here would force a sync on every
                // ride-along pass regardless of `durable`.
                //
                // Logical debt gets exactly the same treatment as a
                // staged page here, not a more eager one: an unbudgeted
                // *ride-along* caller must stay deferred (several tests --
                // "artifact leases defer allocator proof until an
                // authored write," "ride-along passes force no sync" --
                // assert exactly that: a read-driven or idle maintenance
                // pass must not unilaterally force the proof/fold a
                // caller never asked for). Skipping this pass's own
                // ledger work entirely when unbudgeted is always safe for
                // the same reason skipping it for a staged page is:
                // `redo.checkpoint_sequence` (and the real checkpoint
                // slot) simply stay exactly where they were, so nothing
                // here can ever make the "superseded" boundary used on
                // the next reopen worse than it already is.
                //
                // perf/lwa-peer-cert: `require_reuse_proof` is exactly
                // the opposite posture, though -- it marks a caller that
                // already *asked* for real reclamation, synchronously,
                // right now (`reclaimPagesWithCancel`/`reclaimPages`;
                // `reclaimRetirementPressure`'s own doc comment: "a
                // sustained writer must contribute reclamation before
                // filling the bounded retirement queue"). Deferring for
                // such a caller just because no `max_file_bytes` budget
                // happens to be configured silently turned every explicit
                // reclaim request into a guaranteed no-op whenever any
                // logical overlay debt was outstanding, with nothing else
                // in the system ever unblocking it on its own -- found
                // live via `reclaimRetirementPressure`'s own foreground
                // admission loop (`capi.db_test`'s "coalesces allocator
                // proof outside publication gates": `reclaimPages` calls
                // retired nothing without a budget, so `reusable_pages`
                // never moved) and matching `reclaimRetirementPressure`'s
                // own 16-iteration loop, which would otherwise spin to
                // `error.FileBusy` with zero progress once pending debt
                // crossed half the queue limit on any unbudgeted store.
                // `durable` is always `true` for every existing
                // `require_reuse_proof = true` caller (`reclaimPagesWithCancel`
                // hard-codes both), so folding here is exactly as durable
                // as the rest of this explicit path already is -- never a
                // surprise ride-along sync.
                if (require_reuse_proof or (self.reserve_retirement_capacity and self.max_file_bytes != null)) {
                    self.checkpointRedoLog() catch {};
                }
                // Whether or not folding ran (skipped above, or
                // attempted and failed), the ledger body below remains
                // unsafe while anything -- page-shaped or logical -- is
                // still staged and unfolded: this body's own commit
                // below would otherwise consume a `commit_sequence` past
                // content the real tree does not have yet.
                const still_unfolded = !redo.shared.pagesEmpty(io) or for (0..3) |root_idx| {
                    if (redo.shared.count(io, @intCast(root_idx)) != 0) break true;
                } else false;
                if (still_unfolded) return 0;
            }
        }
        const previous_cancel = self.allocator_cancel_token;
        self.allocator_cancel_token = cancel;
        defer self.allocator_cancel_token = previous_cancel;
        // §9 (redo + indexed reclamation): this commit builds a real page
        // (persistAllocator's ledger/free-map write below) exactly like
        // `checkpointRedoLog`'s own transaction, so it needs the same
        // `checkpointing = true` guard for the same reason (see that
        // function's own doc comment): `commitTransactionWithDurability`'s
        // `syncIfRequired` skip and `publishCheckpoint`'s redo-log-record
        // append both key off `self.redo.?.checkpointing` to tell "a real,
        // physically-synced commit" apart from "a diverting one whose only
        // durability barrier is the log append." Without this, a reclaim
        // commit on a redo-log file is misclassified as diverting -- its
        // real page work's own sync gets skipped and an empty, spurious
        // log record is appended for a sequence the log has no logical
        // mutation to replay for, corrupting the log's sequence
        // continuity on the next reopen.
        if (self.redo) |*redo| redo.checkpointing = true;
        defer if (self.redo) |*redo| {
            redo.checkpointing = false;
        };
        try self.beginTransaction();
        errdefer self.abortTransaction();
        const before = self.activeCheckpoint();
        const previous_budget = self.retirement_work_pages;
        self.retirement_work_pages = 0;
        defer self.retirement_work_pages = previous_budget;
        var pages = try self.pageAllocatorFromFreeMapWithProof(before, require_reuse_proof);
        defer pages.deinit();
        if (self.budgetedCheckpointDue(pages.ledger.?)) pages.ledger.?.force_checkpoint = true;
        var work = budget;
        if (self.max_file_bytes) |limit| {
            const available = (limit / self.header.page_size -| pages.next_page_id) +|
                (if (pages.can_reuse) pages.ledger.?.free_pages else 0);
            // Keep normal-sized batches when capacity permits. Under pressure
            // bound journal allocation before traversing/mutating the ledger.
            const advances = 2 *| allocator_v4.serviceJournalPages(self.maxPagePayloadBytes(), 1);
            while (work > 1 and allocator_v4.serviceJournalPages(self.maxPagePayloadBytes(), work) +| advances > available) work = work / 2 + work % 2;
        }
        // Same `fence_held` condition as `pageAllocatorFromFreeMapWithProof`'s
        // own `drainRetirement` call (that function's own doc comment):
        // `pages` was already built by this transaction's one call into
        // it above, so its `data_lock_file`/`coordinated_reader_window`
        // report whether this transaction actually holds the exclusive
        // scan fence, independent of whether `self.epoch_window` ended up
        // populated (cross-process readers only).
        const fence_held = pages.data_lock_file != null or pages.coordinated_reader_window;
        const count = try self.drainRetirement(pages.ledger.?, before, work, fence_held);
        const state = pages.ledger.?;
        if (state.checkpointDue()) {
            // Bound metadata construction independently of the physical ledger
            // size. Each service publication makes its partial chains durable.
            try self.advanceAllocatorCheckpoint(&pages, @max(@as(usize, 1), @min(work, 16)));
        }
        const previous_maintenance = self.maintenance_publication;
        self.maintenance_publication = true;
        defer self.maintenance_publication = previous_maintenance;
        var next = before;
        next.commit_sequence += 1;
        next.free_map_root_page = try pages.allocate();
        try self.persistAllocator(&pages, &next);
        // Never the group-commit path: this reclaim commit holds whatever
        // outer lock its caller took (Store's `maintainOnceWithCancel`)
        // unreleased across its own sync, rather than racing a foreground
        // group's released window. Passing a real hooks value here would
        // have this commit act on a lock it does not own.
        try self.syncIfRequired(null);
        try self.publishCheckpoint(next, false, null);
        if (cancel) |token| try token.check();
        // No cancellation checks after checkpoint publication begins: preserve
        // the usual uncertain-outcome fencing across the durability boundary.
        try self.commitTransactionWithDurability(durable, null);
        // §9 (redo + reclamation): `redo.checkpointing = true` above sent
        // this commit through the same real, physical-slot-write branch
        // of `publishCheckpoint` that `checkpointRedoLog`'s own build
        // commit uses (neither one appends to the log), so this commit's
        // sequence was consumed without ever being logged. Unlike
        // `checkpointRedoLog`, this commit folds no logical overlay --
        // it is purely a free-map/ledger write -- so the log's own bytes
        // are untouched and must stay exactly as they are (still correct,
        // still needed for a future fold): no zeroing, no `old_tail`
        // bookkeeping, just resyncing the sequence-continuity counters
        // the next ordinary commit's own `redo.appendRecord` call checks.
        // Left undone, that next commit fails with the far less specific
        // `error.OutcomeUnknown` (via `error.SequenceOutOfOrder`), on a
        // commit that is otherwise perfectly fine.
        if (self.redo) |*redo| {
            const new_sequence = self.activeCheckpoint().commit_sequence;
            redo.durable_sequence = new_sequence;
            redo.writer.last_sequence = new_sequence;
        }
        return count;
    }

    pub fn check(self: *NativeFile) !CheckReport {
        return try self.checkWithCancel(null);
    }

    pub fn checkWithCancel(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !CheckReport {
        if (cancel) |token| try token.check();
        return self.checkAtFileSizeWithCancel((try self.file.stat(self.runtimeIo())).size, cancel);
    }

    /// Check a pinned header against the file length captured with that header.
    /// Appends after pinning do not turn a valid snapshot into a tail error.
    pub fn checkAtFileSizeWithCancel(self: *NativeFile, file_size: u64, cancel: ?*const maintenance.CancelToken) !CheckReport {
        if (cancel) |token| try token.check();
        // Integrity checking must observe on-disk state, not cached pages.
        _ = self.page_cache_bypass.fetchAdd(1, .monotonic);
        defer _ = self.page_cache_bypass.fetchSub(1, .monotonic);

        const checkpoint = self.activeCheckpoint();
        const expected_size = try checkpointPrefixSize(checkpoint, self.header.page_size);

        const report = CheckReport{
            .valid = true,
            .file_size = file_size,
            .valid_prefix_size = @min(file_size, expected_size),
            .tail_bytes = if (file_size > expected_size) file_size - expected_size else 0,
            .record_count = if (checkpoint.page_count > 0) checkpoint.page_count - 1 else 0,
            .live_file_count = 0,
            .live_bytes = 0,
            .compact_size = expected_size,
            .reclaimable_bytes = 0,
        };

        if (checkpoint.page_count == 0) return invalidCheck(report, "invalid_page_count");
        // §9 (redo + indexed reclamation): a diverting commit advances
        // `checkpoint.page_count` on its own, to hand out fresh page ids
        // for external value chains (`pageAllocatorForDivertingCommit`),
        // before the file's own physical extent grows to match -- that
        // growth only happens at the next `checkpointRedoLog` fold (or
        // the "page-shaped only" pre-flush `publishCheckpoint` runs when
        // the log itself is close to full). `decodeFreeMapAlloc`'s own
        // `allow_behind` already tolerates exactly this gap for the free
        // map's `covered_page_count`; `expected_size` here, built from
        // the same `page_count`, inherits the identical gap and must be
        // tolerated the same way, or every `check()` call on a live,
        // still-diverting redo-log file reports `truncated_file` for
        // pages that are not missing -- they are staged in the shared
        // redo overlay, recoverable from the log, exactly like any other
        // page in that gap. The floor this check still enforces for a
        // redo-log file is the one thing that is never deferred: the
        // fixed prefix every opener reads before any divert can happen
        // at all (header, both checkpoint slots, and the log's own
        // reserved region) -- a file truncated short of *that* is
        // genuinely corrupt, not merely mid-divert. Every individual
        // page read below (reachable-chain walks, the indexed-allocator
        // graph walk) already goes through the overlay-aware primitives,
        // so a page that is *not* actually recoverable -- truly missing,
        // not merely undiverted -- still fails there, not here.
        const truncation_floor = if (self.header.redo_log_capacity != 0)
            self.header.redo_log_offset +| self.header.redo_log_capacity
        else
            expected_size;
        if (file_size < truncation_floor) return invalidCheck(report, "truncated_file");

        if (self.header.indexed_reclamation) {
            // §9 (redo + indexed reclamation): `check()` deliberately holds
            // no store-level lock across this whole block (that is the
            // point of it being callable concurrently with a live
            // writer/background maintenance for diagnostics), so a
            // redo-log file's own `rideAlongFlushLoop`/
            // `maybeCheckpointRedoLogOnIdleTurn` can publish a newer,
            // perfectly valid checkpoint while this is still running --
            // `validateIndexedAllocator` reports that as
            // `error.NativeCheckpointSuperseded`, distinct from a real
            // ownership defect, specifically so this loop can re-capture a
            // fresh checkpoint and retry instead of reporting a false
            // `invalid_allocator`. Bounded, not infinite: a background
            // publisher that never goes quiet for even one validation pass
            // is itself worth surfacing rather than retrying forever.
            const max_supersede_retries = 8;
            var attempt: usize = 0;
            var current_checkpoint = checkpoint;
            while (true) {
                // A writer/rebased cache contains transient traversal
                // inventories, which need not describe the current on-disk
                // metadata graph. Explicit integrity validates a fresh
                // ledger as well as fresh pages. Reads pin to
                // `current_checkpoint` specifically (`pinnedLedgerReadAny`'s
                // own doc comment) -- `check()` holds no lock across this
                // call, so a plain `ledgerReadAny`/`self.activeCheckpoint()`
                // read could tear across a concurrent background checkpoint
                // publish, especially with page reuse enabled.
                var pinned_ctx = CheckpointPinnedLedgerContext{ .file = self, .checkpoint = current_checkpoint };
                var state = (if (current_checkpoint.free_map_root_page == 0) allocator_v4.State.init(self.allocator) else allocator_v4.State.load(self.allocator, .{
                    .context = &pinned_ctx,
                    .allocate = pinnedLedgerReadOnlyAllocate,
                    .read = pinnedLedgerReadAny,
                    .write = pinnedLedgerReadOnlyWrite,
                    .payload_bytes = self.maxPagePayloadBytes(),
                    .cancel_requested = if (cancel) |token| &token.requested else null,
                }, current_checkpoint.free_map_root_page)) catch |err| {
                    if (err == error.MaintenanceCanceled) return err;
                    return invalidCheck(report, issueForPageCheckError(err));
                };
                defer state.deinit();
                const records = self.validateIndexedAllocator(current_checkpoint, &state, cancel) catch |err| {
                    if (err == error.MaintenanceCanceled) return err;
                    if (err == error.NativeCheckpointSuperseded and attempt < max_supersede_retries) {
                        attempt += 1;
                        current_checkpoint = self.activeCheckpoint();
                        continue;
                    }
                    return invalidCheck(report, issueForPageCheckError(err));
                };
                const live = try self.liveStats(cancel);
                // A retried attempt validated `current_checkpoint`, not the
                // (possibly now superseded) `checkpoint` `report` above was
                // built from -- recompute the size-derived fields against
                // the checkpoint actually validated, or a retry's own
                // larger, perfectly legitimate `expected_size` reads back
                // as a spurious `tail_bytes` mismatch against the stale
                // one.
                const current_expected_size = try checkpointPrefixSize(current_checkpoint, self.header.page_size);
                var valid = report;
                valid.valid_prefix_size = @min(file_size, current_expected_size);
                valid.tail_bytes = if (file_size > current_expected_size) file_size - current_expected_size else 0;
                valid.record_count = records + self.redoOverlayEntryCount();
                valid.live_file_count = live.record_count;
                valid.live_bytes = live.bytes;
                valid.live_accounting = live.accounting;
                valid.compact_size = live.compact_size;
                valid.reclaimable_bytes = file_size -| live.compact_size;
                if (valid.tail_bytes != 0) return invalidCheck(valid, "tail_bytes");
                return valid;
            }
        }
        var reachable_pages = std.AutoHashMapUnmanaged(u64, void){};
        defer reachable_pages.deinit(self.allocator);

        const catalog_records = self.countReachableChainPagesWithCancel(.catalog, checkpoint.catalog_root_page, &reachable_pages, cancel) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        if (cancel) |token| try token.check();
        const namespace_directory_records = self.countReachableChainPagesWithCancel(.catalog, checkpoint.namespace_directory_root_page, &reachable_pages, cancel) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        if ((checkpoint.document_root_page == 0 and namespace_directory_records != 0) or
            (checkpoint.document_root_page != 0 and namespace_directory_records == 0))
            return invalidCheck(report, "invalid_namespace_directory");
        self.validateNamespaceDirectory(checkpoint) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        if (cancel) |token| try token.check();
        const index_catalog_records = self.countReachableChainPagesWithCancel(.catalog, checkpoint.index_catalog_root_page, &reachable_pages, cancel) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        const document_records = self.countReachableChainPagesWithCancel(.document, checkpoint.document_root_page, &reachable_pages, cancel) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        if (checkpoint.document_root_page == 0 and checkpoint.document_index_root_page != 0)
            return invalidCheck(report, "invalid_document_index");
        const document_index_pages = self.collectDocumentIndexPages(checkpoint, &reachable_pages, true, true, cancel) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        self.validateDocumentIndexCoverage(checkpoint, cancel) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        if (cancel) |token| try token.check();
        self.validateReachableFreeMap(checkpoint, &reachable_pages) catch |err| {
            return invalidCheck(report, issueForPageCheckError(err));
        };
        const live = self.liveStats(cancel) catch |err| {
            if (err == error.MaintenanceCanceled) return err;
            return invalidCheck(report, issueForPageCheckError(err));
        };

        var valid = report;
        _ = document_index_pages;
        valid.record_count = catalog_records + index_catalog_records + document_records + self.redoOverlayEntryCount();
        valid.live_file_count = live.record_count;
        valid.live_bytes = live.bytes;
        valid.live_accounting = live.accounting;
        valid.compact_size = live.compact_size;
        valid.reclaimable_bytes = if (file_size > live.compact_size) file_size - live.compact_size else 0;
        if (valid.tail_bytes != 0) return invalidCheck(valid, "tail_bytes");
        return valid;
    }

    pub fn allocatePage(self: *NativeFile, contents: []const u8) !u64 {
        try self.flushTransactionWrites();
        if (self.read_only) return error.ReadOnly;
        const previous = self.activeCheckpoint();
        var page_allocator = try self.pageAllocatorFromFreeMap(previous);
        defer page_allocator.deinit();
        errdefer self.resetBareCommitManifestWindow();

        const page_id = try page_allocator.allocate();
        try page_allocator.writePage(page_id, .data, contents);

        var next = previous;
        next.commit_sequence += 1;
        next.free_map_root_page = try page_allocator.allocate();
        next.page_count = page_allocator.next_page_id;

        try page_allocator.flush();
        try self.reserveBareCommitManifestPage(&page_allocator);
        try self.persistAllocator(&page_allocator, &next);
        try self.publishBareCommit(&page_allocator, &next);
        return page_id;
    }

    pub fn readPageAlloc(self: *NativeFile, allocator: Allocator, page_id: u64) ![]u8 {
        return try self.readPageAllocForCheckpoint(allocator, page_id, self.activeCheckpoint());
    }

    fn readPageAllocForCheckpoint(self: *NativeFile, allocator: Allocator, page_id: u64, checkpoint: CheckpointSlot) ![]u8 {
        if (page_id & packed_record_flag != 0) {
            // unpackRecordPage used to always re-read and re-validate the
            // whole shared record_bundle page (even on a repeat access of a
            // page this process already verified), just to copy out one
            // packed record. Borrow the cache's already-validated payload
            // when there is one: validate-via-cache and
            // repackage-into-owned-buffer are now separate steps, so a
            // cache hit pays for the repackage copy but not another CRC.
            const physical = physicalPage(page_id);
            const use_cache = self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0;
            if (physical != 0 and physical < checkpoint.page_count and use_cache) {
                if (try self.page_cache.acquirePayload(allocator, physical, @intCast(self.header.page_size))) |view| {
                    defer self.page_cache.releaseRaw(allocator, view);
                    if (view.validation.?.kind != .record_bundle) return error.UnexpectedNativePageKind;
                    const payload = view.bytes[page_header_size..][0..view.validation.?.payload_len];
                    const record = try packedRecordPayload(payload, page_id);
                    const page_size: usize = @intCast(self.header.page_size);
                    const page = try allocator.alloc(u8, page_size);
                    errdefer allocator.free(page);
                    encodePage(page, record.kind, record.bytes);
                    return page;
                }
            }
            // Cache miss (or cache disabled/bypassed): read and validate the
            // whole page, then unpack in place as before.
            const page = try self.readPhysicalPageAlloc(allocator, physical, checkpoint);
            errdefer allocator.free(page);
            try unpackRecordPage(page, page_id);
            return page;
        }
        const page = try self.readPhysicalPageAlloc(allocator, physicalPage(page_id), checkpoint);
        errdefer allocator.free(page);
        return page;
    }

    fn admitPageToCache(self: *const NativeFile, page: []const u8) bool {
        if (page.len <= 4 or page[4] == @backingInt(PageKind.free_map)) return false;
        if (self.page_cache_policy == .normal) return true;
        return switch (page[4]) {
            @backingInt(PageKind.document_index), @backingInt(PageKind.catalog_index), @backingInt(PageKind.value_extent) => true,
            else => false,
        };
    }

    fn readPhysicalPageAlloc(self: *NativeFile, allocator: Allocator, page_id: u64, checkpoint: CheckpointSlot) ![]u8 {
        if (builtin.is_test) if (self.test_cancel_on_read) |token| token.request();
        if (builtin.is_test) _ = self.test_page_reads.fetchAdd(1, .monotonic);
        if (page_id == 0 or page_id >= checkpoint.page_count) return error.InvalidPageId;

        const use_cache = self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0;
        if (use_cache) {
            if (try self.page_cache.getCopy(allocator, page_id)) |cached| return cached;
        }

        const page_size: usize = @intCast(self.header.page_size);
        const page = try allocator.alloc(u8, page_size);
        errdefer allocator.free(page);

        try self.readBackingPages(page, page_id * @as(u64, self.header.page_size));
        // Free-map pages are rewritten every commit and read once, so caching
        // them buys nothing; skipping them also keeps free-map validation
        // reading disk truth before any pages are handed out for reuse.
        if (use_cache and self.admitPageToCache(page)) {
            self.page_cache.put(self.allocator, page_id, page);
        }
        return page;
    }

    /// A proof still validates every referenced page and both checkpoint
    /// graphs. Its short-lived read window only coalesces backing I/O; it is
    /// discarded before any publication can mutate this file.
    const AllocatorProofWindow = struct {
        file: *NativeFile,
        buffer: ?[]u8 = null,
        reservation: ?resource_manager_mod.Reservation = null,
        offset: u64 = 0,
        length: usize = 0,
        limit: u64 = 0,

        fn initInto(self: *@This(), file: *NativeFile) void {
            self.* = .{ .file = file };
            if (file.allocator_proof_window != null) return;
            const size = (file.file.stat(file.runtimeIo()) catch return).size;
            var capacity: usize = @intCast(@min(size, 1024 * 1024));
            if (file.page_cache.resource_manager) |manager| {
                self.reservation = manager.reserveAtMostWithoutReclaim(.lite_native_page_cache, capacity) catch return;
                capacity = @intCast(@min(capacity, self.reservation.?.reservedBytes()));
            }
            capacity -= capacity % file.header.page_size;
            if (capacity == 0) return;
            // Optional acceleration must not turn allocator/cache admission
            // failure into failure of an otherwise valid bounded proof.
            self.buffer = file.allocator.alloc(u8, capacity) catch {
                if (self.reservation) |*reservation| reservation.release();
                self.reservation = null;
                return;
            };
            self.limit = size;
            file.allocator_proof_window = self;
        }

        fn deinit(self: *@This()) void {
            if (self.buffer) |buffer| {
                std.debug.assert(self.file.allocator_proof_window == self);
                self.file.allocator_proof_window = null;
                self.file.allocator.free(buffer);
            }
            if (self.reservation) |*reservation| reservation.release();
        }

        fn read(self: *@This(), out: []u8, offset: u64) !bool {
            const buffer = self.buffer.?;
            if (out.len > buffer.len or offset > self.limit or out.len > self.limit - offset) return false;
            if (self.length == 0 or offset < self.offset or offset - self.offset > self.length or
                out.len > self.length - @as(usize, @intCast(offset - self.offset)))
            {
                const start = offset / buffer.len * buffer.len;
                const count: usize = @intCast(@min(buffer.len, self.limit - start));
                if (out.len > count - @as(usize, @intCast(offset - start))) return false;
                try self.file.readBackingPagesUncached(buffer[0..count], start);
                self.offset = start;
                self.length = count;
            }
            const begin: usize = @intCast(offset - self.offset);
            @memcpy(out, buffer[begin..][0..out.len]);
            return true;
        }
    };

    fn readBackingPages(self: *NativeFile, out: []u8, offset: u64) !void {
        // §9.3a: a page the overlay holds has no correct physical copy on
        // disk yet (it was diverted into the redo log instead of pwritten
        // -- see `PageWriteBatch.flushCount`), so it must be served from
        // here before even the ordinary page cache (whose free-map
        // exclusion, and eviction in general, cannot be trusted to hold
        // it). This is the single choke point every page-sized,
        // page-aligned read in this file reaches -- `readPhysicalPageAlloc`
        // and `readPageInto` both call this, never `readBackingPagesUncached`
        // directly -- so hooking here (not either of those two separately)
        // covers both without duplicating the check. `AllocatorProofWindow.
        // read` is the one caller that bypasses this wrapper, straight to
        // `readBackingPagesUncached`: it reads multi-page buffered windows
        // for a bulk allocator-verification scan, not page-id-keyed single
        // pages, so a single `page_id` lookup does not apply there; that
        // path's own callers run outside any live transaction a redo-log
        // commit could have staged into this overlay.
        if (self.redo) |*redo| {
            const page_size = self.header.page_size;
            if (offset % page_size == 0 and out.len % page_size == 0 and out.len != 0) {
                const page_count = out.len / page_size;
                if (page_count == 1) {
                    const page_id = offset / page_size;
                    if (try redo.shared.readPageAlloc(self.allocator, self.runtimeIo(), page_id)) |bytes| {
                        defer self.allocator.free(bytes);
                        if (builtin.is_test) _ = self.test_redo_page_overlay_hits.fetchAdd(1, .monotonic);
                        @memcpy(out, bytes);
                        return;
                    }
                } else if (!redo.shared.pagesEmpty(self.runtimeIo())) {
                    // `RecordReadWindow`'s own multi-page read-ahead
                    // window, never a single page-id-keyed lookup: any
                    // page in this span -- not just the first -- may be
                    // redo-log-only with no correct physical copy yet,
                    // same as the single-page case above. A single bulk
                    // `readBackingPagesUncached` call below would skip
                    // the overlay check entirely for every page past the
                    // first, reading right past the physical end of file
                    // for one the file was never extended to cover --
                    // observed as `EndOfStream` in
                    // `getDocumentsAtCheckpointWithState`'s own batch-read
                    // path, immediately after a `putDocumentBatch` whose
                    // writes this same commit diverted into the redo log.
                    //
                    // Redo is now the default, so this window is the
                    // common case on the hot batch-read path benchmarked
                    // against SQLite: serving it one page at a time
                    // unconditionally (an earlier version of this fix)
                    // would turn every such read-ahead window into N
                    // physical preads instead of one, even when nothing
                    // in it is actually diverted -- the overwhelmingly
                    // common case once a fold has run. Instead: walk the
                    // span once, copying each overlay hit directly and
                    // coalescing every maximal run of consecutive
                    // non-overlay pages into a single physical read --
                    // so a window with zero diverted pages among them
                    // still costs exactly one pread, same as legacy, and
                    // only a window that actually straddles a diverted
                    // page pays for more than one. `pagesEmpty` above
                    // (one cheap, non-allocating check) skips this walk
                    // entirely once nothing is staged anywhere, which is
                    // true for the whole process between folds.
                    const first_page = offset / page_size;
                    var i: usize = 0;
                    while (i < page_count) {
                        const page_id = first_page + i;
                        if (try redo.shared.readPageAlloc(self.allocator, self.runtimeIo(), page_id)) |bytes| {
                            defer self.allocator.free(bytes);
                            if (builtin.is_test) _ = self.test_redo_page_overlay_hits.fetchAdd(1, .monotonic);
                            @memcpy(out[i * page_size ..][0..page_size], bytes);
                            i += 1;
                            continue;
                        }
                        var run: usize = 1;
                        while (i + run < page_count and !redo.shared.hasPage(self.runtimeIo(), first_page + i + run)) run += 1;
                        try self.readBackingPagesUncached(out[i * page_size ..][0 .. run * page_size], offset + i * page_size);
                        i += run;
                    }
                    return;
                }
                // Either a single page already handled above and not
                // found in the overlay, or a multi-page window with
                // nothing staged anywhere: fall through to the one bulk
                // uncached read below, exactly as before this function
                // knew about multi-page windows at all.
            }
        }
        if (self.allocator_proof_window) |window| if (try window.read(out, offset)) return;
        try self.readBackingPagesUncached(out, offset);
    }

    fn readBackingPagesUncached(self: *NativeFile, out: []u8, offset: u64) !void {
        if (builtin.is_test) {
            _ = self.test_backing_read_calls.fetchAdd(1, .monotonic);
            _ = self.test_backing_read_bytes.fetchAdd(out.len, .monotonic);
        }
        try readExactAt(self.file, self.runtimeIo(), out, offset);
    }

    /// Bounded scratch reads for point lookups avoid allocating decoded keys
    /// and page copies at every level of the catalog/document B-tree.
    fn readPageInto(self: *NativeFile, page_id: u64, checkpoint: CheckpointSlot, scratch: []u8) ![]const u8 {
        if (scratch.len < self.header.page_size) return error.InvalidNativePageLength;
        if (page_id & packed_record_flag != 0) {
            _ = try self.readPageInto(physicalPage(page_id), checkpoint, scratch);
            try unpackRecordPage(scratch[0..self.header.page_size], page_id);
            return scratch[0..self.header.page_size];
        }
        if (builtin.is_test) _ = self.test_page_reads.fetchAdd(1, .monotonic);
        if (page_id == 0 or page_id >= checkpoint.page_count) return error.InvalidPageId;
        const page = scratch[0..self.header.page_size];
        const use_cache = self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0;
        if (use_cache and self.page_cache.copyInto(page_id, page)) return page;
        try self.readBackingPages(page, page_id * @as(u64, self.header.page_size));
        if (use_cache and self.admitPageToCache(page)) self.page_cache.put(self.allocator, page_id, page);
        return page;
    }

    pub fn readPagePayloadAlloc(self: *NativeFile, allocator: Allocator, page_id: u64) ![]u8 {
        const page = try self.readPageAlloc(allocator, page_id);
        defer allocator.free(page);
        return try decodePagePayloadAlloc(allocator, page, .data);
    }

    pub fn putCatalogRecord(self: *NativeFile, key: []const u8, value: []const u8) !void {
        try self.putCatalogBatch(&.{.{ .key = key, .value = value }});
    }

    pub fn deleteCatalogRecord(self: *NativeFile, key: []const u8) !void {
        try self.putCatalogBatch(&.{.{ .key = key, .is_delete = true }});
    }

    pub fn putCatalogBatch(self: *NativeFile, mutations: []const CatalogMutation) !void {
        return try self.putCatalogBatchForRoot(.metadata, mutations, .{});
    }

    pub fn putIndexCatalogRecord(self: *NativeFile, key: []const u8, value: []const u8) !void {
        try self.putIndexCatalogRecordWithOptions(key, value, .{});
    }

    pub fn putIndexCatalogRecordWithOptions(self: *NativeFile, key: []const u8, value: []const u8, options: WriteOptions) !void {
        try self.putCatalogBatchForRoot(.index, &.{.{ .key = key, .value = value }}, options);
    }

    /// Import a private, seekable staging file using bounded buffers. The
    /// caller serializes publication with other native mutations and keeps the
    /// source alive and unchanged throughout this call. No staged data enters
    /// the committed catalog until the final checkpoint publication.
    pub fn putIndexCatalogRecordFromFile(self: *NativeFile, key: []const u8, source: std.Io.File, len: usize, options: WriteOptions) !void {
        if (self.change_capture) |capture| capture.record(self.allocator, .index, key);
        if (self.read_only) return error.ReadOnly;
        if (key.len > catalog_key_len_mask or len > std.math.maxInt(u32)) return error.RecordTooLarge;
        const fixed_len = 16 + key.len;
        if (fixed_len > self.maxPagePayloadBytes()) return error.PageTooLarge;
        var buffer: [65536]u8 = undefined;
        if (len <= self.maxPagePayloadBytes() - fixed_len) {
            try readExactAt(source, self.runtimeIo(), buffer[0..len], 0);
            return try self.putIndexCatalogRecordWithOptions(key, buffer[0..len], options);
        }
        if (fixed_len + 8 > self.maxPagePayloadBytes()) return error.PageTooLarge;
        const previous = self.activeCheckpoint();
        const roots = try self.readCatalogRoots(previous.index_catalog_root_page, previous);
        var local_pages: PageAllocator = undefined;
        if (!self.stagingTransaction()) local_pages = try self.pageAllocatorFromFreeMap(previous);
        defer if (!self.stagingTransaction()) local_pages.deinit();
        errdefer if (!self.stagingTransaction()) self.resetBareCommitManifestWindow();
        const pages = if (self.stagingTransaction()) &(try self.transactionWrites()).pages else &local_pages;
        var builder = ExtentAppender{ .file = self, .pages = pages, .tail = undefined, .batch = .{ .file = self, .options = options, .diverting = pages.diverting } };
        defer builder.deinit();
        const chunk_size = self.maxValuePagePayloadBytes();
        const read_size = buffer.len / chunk_size * chunk_size;
        self.direct_value_pages = true;
        defer self.direct_value_pages = false;
        var offset: usize = 0;
        while (offset < len) {
            const n = @min(read_size, len - offset);
            try readExactAt(source, self.runtimeIo(), buffer[0..n], offset);
            var pos: usize = 0;
            while (pos < n) {
                const end = @min(n, pos + chunk_size);
                try builder.pushValue(buffer[pos..end]);
                pos = end;
            }
            offset += n;
        }
        const value = try builder.finish();
        if (self.stagingTransaction()) {
            try self.flushTransactionPayloads();
            return try self.putIndexCatalogBatch(&.{.{ .key = key, .external_value_root_page = value.page, .external_value_len = len }});
        }
        var payload = std.ArrayListUnmanaged(u8).empty;
        defer payload.deinit(self.allocator);
        try encodeCatalogEntryRaw(self.allocator, &payload, .{ .previous_page = if (self.header.indexed_reclamation) 0 else roots.history, .key = key, .external_value_root_page = value.page, .external_value_len = len });
        const record = try pages.allocate();
        try pages.writePage(record, .catalog, payload.items);
        var editor = IndexEditor.init(self, previous, roots.index);
        editor.accounting_pages = pages;
        defer editor.deinit();
        try editor.put(key, record);
        const index = try editor.finish(pages);
        var next = previous;
        next.commit_sequence += 1;
        next.index_catalog_root_page = try self.writeCatalogRoot(pages, record, index, previous.index_catalog_root_page);
        next.free_map_root_page = try pages.allocate();
        next.page_count = pages.next_page_id;
        try pages.flush();
        try self.reserveBareCommitManifestPage(pages);
        try self.persistAllocator(pages, &next);
        try self.publishBareCommit(pages, &next);
    }

    pub fn appendIndexCatalogRecord(self: *NativeFile, key: []const u8, suffix: []const u8) !void {
        try self.appendCatalogRecordForRoot(.index, key, suffix);
    }

    pub fn deleteIndexCatalogRecord(self: *NativeFile, key: []const u8) !void {
        try self.putIndexCatalogBatch(&.{.{ .key = key, .is_delete = true }});
    }

    pub fn renameIndexCatalogRecord(self: *NativeFile, old_key: []const u8, new_key: []const u8) !void {
        try self.renameCatalogRecordForRoot(.index, old_key, new_key);
    }

    pub fn putIndexCatalogBatch(self: *NativeFile, mutations: []const CatalogMutation) !void {
        return try self.putCatalogBatchForRoot(.index, mutations, .{});
    }

    const CatalogRoots = struct { history: u64, index: u64 = 0, indexed: bool = false };

    fn readCatalogRoots(self: *NativeFile, page: u64, checkpoint: CheckpointSlot) !CatalogRoots {
        if (page == 0) return .{ .history = 0 };
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        if (page & packed_record_flag != 0) {
            if (page != checkpoint.namespace_directory_root_page) return error.UnexpectedNativePageKind;
            _ = try reader.readPayload(self, checkpoint, page, 1, .catalog);
            return .{ .history = page };
        }
        const raw = try reader.read(self, checkpoint, page, 1);
        if (raw[4] != @backingInt(PageKind.catalog_index)) {
            // Namespace-directory records have their own delta-chain format.
            // Metadata and index catalogs must carry the revision-3 descriptor.
            if (page != checkpoint.namespace_directory_root_page) return error.UnexpectedNativePageKind;
            _ = try reader.payload(raw, .catalog);
            return .{ .history = page };
        }
        const payload = try reader.payload(raw, .catalog_index);
        if (payload.len != 16) return error.InvalidNativePageChain;
        const history = std.mem.readInt(u64, payload[0..8], .little);
        const index = std.mem.readInt(u64, payload[8..16], .little);
        if ((!self.header.indexed_reclamation and history == 0) or physicalPage(history) >= checkpoint.page_count or index >= checkpoint.page_count) return error.InvalidNativePageChain;
        return .{ .history = history, .index = index, .indexed = true };
    }

    fn catalogHistoryRoot(self: *NativeFile, checkpoint: CheckpointSlot, root: CatalogRoot) !u64 {
        return (try self.readCatalogRoots(catalogRootPage(checkpoint, root), checkpoint)).history;
    }

    fn lookupCatalogPage(self: *NativeFile, checkpoint: CheckpointSlot, root: CatalogRoot, key: []const u8) !?u64 {
        const roots = try self.readCatalogRoots(catalogRootPage(checkpoint, root), checkpoint);
        var indexed = checkpoint;
        indexed.document_index_root_page = roots.index;
        return try self.lookupDocumentIndexPage(indexed, key);
    }

    fn upsertCatalogIndex(self: *NativeFile, pages: *PageAllocator, index: u64, key: []const u8, page: u64) !u64 {
        var checkpoint = self.activeCheckpoint();
        checkpoint.page_count = pages.next_page_id;
        return try self.upsertDocumentIndex(pages, index, key, page, checkpoint);
    }

    fn writeCatalogRoot(self: *NativeFile, pages: *PageAllocator, history: u64, index: u64, previous_root: u64) !u64 {
        if (self.header.indexed_reclamation and index == 0) {
            try pages.retire(previous_root, .page);
            return 0;
        }
        var payload: [16]u8 = undefined;
        std.mem.writeInt(u64, payload[0..8], if (self.header.indexed_reclamation) 0 else history, .little);
        std.mem.writeInt(u64, payload[8..16], index, .little);
        const page = try pages.allocate();
        try pages.writePage(page, .catalog_index, &payload);
        try pages.retire(previous_root, .page);
        return page;
    }

    fn validateCatalogIndexEntries(self: *NativeFile, checkpoint: CheckpointSlot, index: u64, reachable: *ReachablePageSet) !void {
        var records = RecordPageReader{};
        defer records.deinit(self.allocator);
        var indexed = checkpoint;
        indexed.document_index_root_page = index;
        var cursor = CheckpointedTree.init(self, indexed);
        defer cursor.deinit();
        var current = try cursor.first();
        while (current) |entry| {
            var owned = entry;
            defer owned.deinit(self.allocator);
            if (!reachable.contains(owned.document_page_id)) return error.InvalidNativePageChain;
            const payload = try records.read(self, self.allocator, checkpoint, owned.document_page_id, .catalog);
            const record = try decodeCatalogEntry(payload);
            if (!std.mem.eql(u8, record.key, owned.key)) return error.InvalidNativePageChain;
            current = try cursor.next();
        }
    }

    fn putCatalogBatchForRoot(self: *NativeFile, root: CatalogRoot, mutations: []const CatalogMutation, options: WriteOptions) anyerror!void {
        if (self.read_only) return error.ReadOnly;
        if (mutations.len == 0) return;
        for (mutations) |mutation| {
            if (self.artifact_lease_transaction and (root != .metadata or !std.mem.startsWith(u8, mutation.key, artifact_lease_key_prefix)))
                return error.InvalidArtifactLeaseMutation;
            try self.validateCatalogMutation(mutation);
        }
        if (self.stagingTransaction()) for (mutations) |mutation| self.discardCatalogAppend(root, mutation.key);
        if (self.change_capture) |capture| for (mutations) |mutation| capture.record(self.allocator, if (root == .metadata) .metadata else .index, mutation.key);

        // Small index files include WAL control records, which are frequently
        // reset to the same contents. Avoid growing catalog history for those
        // writes. Bound comparison work to one inline record; bulk mutations
        // and spilled values retain the normal publication path.
        //
        // Never while `checkpointRedoLog`'s own fold is replaying a head
        // (`self.redo.?.checkpointing`): `getCatalogRecordSizeFromRoot`
        // consults the redo overlay (`redoOverlayEntry`) before ever
        // falling back to the real tree, and the head being replayed *is*
        // the overlay's own current entry for this key -- so this "does it
        // already match?" check is comparing the mutation against itself
        // and always "matches," silently treating the fold's own replay as
        // a no-op. For a delete this is actively wrong:
        // `getCatalogRecordSizeFromRoot` reports `null` for a key the
        // overlay already marks deleted (the exact mutation being folded),
        // so `mutation.is_delete and size == null` looks like "already
        // absent, nothing to do" and returns without ever staging the
        // delete into `transaction_writes` -- the real tree (which still
        // has the key, unmodified) never gets edited, and
        // `checkpointRedoLog`'s epilogue then reclaims the overlay entry
        // and may reset the log, discarding the only durable record of the
        // delete. The real tree is the only thing this fold's own replay
        // should ever compare against.
        if (!self.flushing_transaction and root == .index and mutations.len == 1 and !self.checkpoint_publication_uncertain and
            !(self.redo != null and self.redo.?.checkpointing))
        {
            const mutation = mutations[0];
            const size = try self.getCatalogRecordSizeFromRoot(root, mutation.key);
            if (mutation.is_delete and size == null) return self.syncIfRequired(null);
            if (mutation.external_value_root_page == 0 and !mutation.is_delete and size != null and size.? == mutation.value.len and self.catalogEntryFitsInline(mutation.key, mutation.value)) {
                const existing = try self.getCatalogRecordFromRootAlloc(self.allocator, root, mutation.key);
                defer if (existing) |bytes| self.allocator.free(bytes);
                if (existing) |bytes| {
                    if (std.mem.eql(u8, bytes, mutation.value)) return self.syncIfRequired(null);
                }
            }
        }

        if (self.stagingTransaction() and mutations.len >= TransactionWrites.max_keys) {
            // The caller already owns a complete batch until this call returns.
            // Consume it directly instead of copying it into bounded staging
            // and rebuilding the same index for every staging-sized chunk.
            try self.flushTransactionWrites();
            const writes = try self.transactionWrites();
            self.flushing_transaction = true;
            self.transaction_pages = &writes.pages;
            defer {
                self.transaction_pages = null;
                self.flushing_transaction = false;
            }
            try self.putCatalogBatchForRoot(root, mutations, options);
            try writes.pages.flush();
            return;
        }
        if (self.stagingTransaction()) {
            for (mutations) |m| try self.stageMutation(if (root == .metadata) .metadata else .index, .{ .key = m.key, .value = m.value, .is_delete = m.is_delete, .external_value_root_page = m.external_value_root_page, .external_value_len = m.external_value_len }, options);
            return;
        }

        const previous = self.activeCheckpoint();
        const roots = try self.readCatalogRoots(catalogRootPage(previous, root), previous);
        var next_root_page = roots.history;
        var local_pages: PageAllocator = undefined;
        if (self.transaction_pages == null) local_pages = try self.pageAllocatorFromFreeMap(previous);
        defer if (self.transaction_pages == null) local_pages.deinit();
        errdefer if (self.transaction_pages == null) self.resetBareCommitManifestWindow();
        const page_allocator = self.transaction_pages orelse &local_pages;
        page_allocator.pack_records = self.header.packed_records and (mutations.len > 1 or self.transaction_pages != null);
        var editor = IndexEditor.init(self, previous, roots.index);
        defer editor.deinit();
        editor.useSortedBatch(page_allocator, mutations);

        for (mutations) |mutation| {
            if (self.header.indexed_reclamation and mutation.is_delete) {
                try editor.remove(mutation.key);
                continue;
            }
            var external_value_root_page: u64 = mutation.external_value_root_page;
            if (external_value_root_page == 0 and !mutation.is_delete and !self.catalogEntryFitsInline(mutation.key, mutation.value)) {
                external_value_root_page = try self.writeCatalogValue(page_allocator, mutation.value, options);
            }

            const page_id = try page_allocator.writeCatalog(.{
                .previous_page = if (self.header.indexed_reclamation) 0 else next_root_page,
                .key = mutation.key,
                .value = mutation.value,
                .is_delete = mutation.is_delete,
                .external_value_root_page = external_value_root_page,
                .external_value_len = mutation.external_value_len,
            });
            next_root_page = page_id;
            if (mutation.is_delete) {
                try page_allocator.retire(page_id, .record);
                try editor.remove(mutation.key);
            } else try editor.put(mutation.key, page_id);
        }

        const key_index = try editor.finish(page_allocator);
        var next = previous;
        next.commit_sequence += 1;
        setCatalogRootPage(&next, root, try self.writeCatalogRoot(page_allocator, next_root_page, key_index, catalogRootPage(previous, root)));
        if (self.transaction_pages == null) next.free_map_root_page = try page_allocator.allocate();
        next.page_count = page_allocator.next_page_id;

        if (self.transaction_pages == null) {
            try page_allocator.flush();
            try self.reserveBareCommitManifestPage(page_allocator);
            try self.persistAllocator(page_allocator, &next);
            try self.publishBareCommit(page_allocator, &next);
        } else {
            try self.publishCheckpoint(next, false, null);
        }
    }

    fn transactionCatalogEntry(self: *NativeFile, root: CatalogRoot, key: []const u8, scratch: *[65536]u8) !?CatalogEntry {
        try self.finishCatalogAppend(root, key);
        const checkpoint = self.activeCheckpoint();
        if (self.stagedEntry(if (root == .metadata) .metadata else .index, key)) |entry| return if (entry.is_delete) null else entry;
        // §9.7c (ReadView): the overlay-blind-read bug class, found three
        // times already at other call sites (docstore.Cursor,
        // getDocumentsAtCheckpointWithState, readBackingPages's read-ahead
        // window) -- this is a fourth. A key whose current value lives
        // only in the redo-log overlay (logged by an earlier commit via
        // appendLogicalMutation, not yet folded into the real tree by
        // checkpointRedoLog) falls straight through to `lookupCatalogPage`
        // below, which only ever sees the real tree -- returning null (or
        // a stale, pre-overlay value) for a key that is very much live.
        // `stageCatalogAppend`'s own caller then treats that as "nothing to
        // append to" and builds its new suffix on the wrong base, silently
        // discarding (or duplicating, if the stale on-disk value is itself
        // a shorter prefix of the live one) whatever the overlay held.
        // Checked here, before the real-tree fallback, so every caller of
        // this function (append and rename) sees exactly what a plain
        // `get()` on the same key already would. The overlay returns an
        // owned value; copied into `scratch` (bounded the same way the
        // real-tree path already is, by `maxPagePayloadBytes` <=
        // scratch.len) so this function's own ownership contract -- every
        // returned `CatalogEntry.value` borrows from either `scratch` or
        // `stagedEntry`'s map, never something the caller must free --
        // stays the same for both existing callers.
        if (try self.redoOverlayEntry(if (root == .metadata) .metadata else .index, checkpoint, key)) |overlay_entry| {
            defer self.allocator.free(overlay_entry.value);
            if (overlay_entry.is_delete) return null;
            if (overlay_entry.external_value_root_page != 0) return .{
                .previous_page = 0,
                .key = key,
                .value = &.{},
                .external_value_root_page = overlay_entry.external_value_root_page,
                .external_value_len = overlay_entry.external_value_len,
            };
            if (overlay_entry.value.len > scratch.len) return error.RecordTooLarge;
            @memcpy(scratch[0..overlay_entry.value.len], overlay_entry.value);
            return .{ .previous_page = 0, .key = key, .value = scratch[0..overlay_entry.value.len] };
        }
        const page = (try self.lookupCatalogPage(checkpoint, root, key)) orelse return null;
        const payload = try decodePagePayload(try self.readPageInto(page, checkpoint, scratch), .catalog);
        const entry = try decodeCatalogEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNativePageChain;
        return if (entry.is_delete) null else entry;
    }

    fn stageCatalogAppend(self: *NativeFile, root: CatalogRoot, key: []const u8, suffix: []const u8) !void {
        if (self.transaction_writes) |writes| {
            if (writes.appends[@backingInt(root)].get(key)) |state| {
                if (suffix.len == 0) return;
                try state.append(suffix);
                self.header.checkpoints[self.header.active_checkpoint].commit_sequence += 1;
                return;
            }
            if (writes.append_count >= TransactionWrites.max_append_files) try self.flushTransactionWrites();
        }
        var scratch: [65536]u8 = undefined;
        const entry = (try self.transactionCatalogEntry(root, key, &scratch)) orelse
            return self.putCatalogBatchForRoot(root, &.{.{ .key = key, .value = suffix }}, .{});
        if (suffix.len == 0) return;
        const old_len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        const len = try std.math.add(usize, old_len, suffix.len);
        if (len > std.math.maxInt(u32)) return error.RecordTooLarge;
        const fixed_len = 16 + key.len;
        if (fixed_len > self.maxPagePayloadBytes()) return error.PageTooLarge;
        if (len <= self.maxPagePayloadBytes() - fixed_len) {
            const value = try self.allocator.alloc(u8, len);
            defer self.allocator.free(value);
            if (entry.external_value_root_page == 0) @memcpy(value[0..old_len], entry.value) else {
                const old = try self.catalogEntryValueAlloc(self.allocator, entry);
                defer self.allocator.free(old);
                @memcpy(value[0..old_len], old);
            }
            @memcpy(value[old_len..], suffix);
            return self.putCatalogBatchForRoot(root, &.{.{ .key = key, .value = value }}, .{});
        }
        if (fixed_len + 8 > self.maxPagePayloadBytes()) return error.PageTooLarge;
        // Own the base entry before any staging spill can release its bytes.
        // Its slot also owns the key borrowed by the append-state map.
        try self.stageMutation(if (root == .metadata) .metadata else .index, .{
            .key = key,
            .value = entry.value,
            .external_value_root_page = entry.external_value_root_page,
            .external_value_len = entry.external_value_len,
        }, .{});
        const writes = self.transaction_writes.?;
        const base = writes.maps[@backingInt(root)].get(key).?;
        const state = try CatalogAppendState.create(self, &writes.pages, TransactionWrites.entry(base));
        errdefer state.destroy();
        try state.append(suffix);
        try writes.appends[@backingInt(root)].put(self.allocator, base.key, state);
        writes.append_count += 1;
    }

    fn discardCatalogAppend(self: *NativeFile, root: CatalogRoot, key: []const u8) void {
        const writes = self.transaction_writes orelse return;
        if (writes.appends[@backingInt(root)].fetchRemove(key)) |removed| {
            removed.value.destroy();
            writes.append_count -= 1;
        }
    }

    // Writer-only visibility barrier. Pinned checkpoint APIs deliberately never
    // touch append frontiers or any other private transaction state.
    fn finishCatalogAppend(self: *NativeFile, root: CatalogRoot, key: []const u8) !void {
        if (!self.stagingTransaction()) return;
        const writes = self.transaction_writes orelse return;
        const map = &writes.appends[@backingInt(root)];
        const state = map.get(key) orelse return;
        try self.finishCatalogAppendState(writes, root, key, state);
        _ = map.remove(key);
        state.destroy();
        writes.append_count -= 1;
    }

    fn finishCatalogAppendState(self: *NativeFile, writes: *TransactionWrites, root: CatalogRoot, key: []const u8, state: *CatalogAppendState) !void {
        const ref = try state.finish();
        const mutation = writes.maps[@backingInt(root)].getPtr(key).?;
        writes.bytes -= mutation.value.len;
        // `mutation.value` came from `writes.value_arena` (stageMutation),
        // reclaimed in one shot with everything else at `writes.clear` --
        // not individually freed here.
        mutation.value = &.{};
        mutation.external_value_root_page = ref.page;
        mutation.external_value_len = state.len;
        self.header.checkpoints[self.header.active_checkpoint].page_count = writes.pages.next_page_id;
    }

    fn finishCatalogAppends(self: *NativeFile, writes: *TransactionWrites) !void {
        for (&writes.appends, 0..) |*map, root| {
            var it = map.iterator();
            while (it.next()) |entry| {
                try self.finishCatalogAppendState(writes, @fromBackingInt(@intCast(root)), entry.key_ptr.*, entry.value_ptr.*);
                entry.value_ptr.*.destroy();
                _ = map.remove(entry.key_ptr.*);
                writes.append_count -= 1;
            }
        }
    }

    fn stageCatalogRename(self: *NativeFile, root: CatalogRoot, old_key: []const u8, new_key: []const u8) !void {
        var scratch: [65536]u8 = undefined;
        const entry = (try self.transactionCatalogEntry(root, old_key, &scratch)) orelse return;
        // put validates the destination (which may require spilling an inline
        // value after a longer rename) before changing either key.
        try self.putCatalogBatchForRoot(root, &.{.{ .key = new_key, .value = entry.value, .external_value_root_page = entry.external_value_root_page, .external_value_len = entry.external_value_len }}, .{});
        try self.putCatalogBatchForRoot(root, &.{.{ .key = old_key, .is_delete = true }}, .{});
    }

    fn appendCatalogRecordForRoot(self: *NativeFile, root: CatalogRoot, key: []const u8, suffix: []const u8) !void {
        if (self.change_capture) |capture| capture.record(self.allocator, if (root == .metadata) .metadata else .index, key);
        if (self.read_only) return error.ReadOnly;

        if (self.stagingTransaction()) return self.stageCatalogAppend(root, key, suffix);

        const previous = self.activeCheckpoint();
        const found_page = (try self.lookupCatalogPage(previous, root, key)) orelse {
            return try self.putCatalogBatchForRoot(root, &.{.{ .key = key, .value = suffix }}, .{});
        };
        const found_payload = try self.readPagePayloadByKindAlloc(self.allocator, found_page, .catalog);
        defer self.allocator.free(found_payload);
        const entry = try decodeCatalogEntry(found_payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNativePageChain;
        if (entry.is_delete) return try self.putCatalogBatchForRoot(root, &.{.{ .key = key, .value = suffix }}, .{});

        const old_len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        const total_len = try std.math.add(usize, old_len, suffix.len);

        const roots = try self.readCatalogRoots(catalogRootPage(previous, root), previous);
        var next_root_page = roots.history;
        var page_allocator = try self.pageAllocatorFromFreeMap(previous);
        defer page_allocator.deinit();
        errdefer self.resetBareCommitManifestWindow();
        var key_index = roots.index;

        var external_value_root_page: u64 = 0;
        var inline_value: []u8 = &.{};
        defer if (inline_value.len > 0) self.allocator.free(inline_value);

        const fixed_len = 16 + key.len;
        const fits_inline = fixed_len <= self.maxPagePayloadBytes() and total_len <= self.maxPagePayloadBytes() - fixed_len;
        if (fits_inline) {
            inline_value = try self.allocator.alloc(u8, total_len);
            if (entry.external_value_root_page != 0) {
                const old_value = try self.readValuePagesAlloc(self.allocator, entry.external_value_root_page, entry.external_value_len);
                defer self.allocator.free(old_value);
                @memcpy(inline_value[0..old_value.len], old_value);
            } else {
                @memcpy(inline_value[0..entry.value.len], entry.value);
            }
            @memcpy(inline_value[old_len..], suffix);
        } else {
            external_value_root_page = try self.appendCatalogValueTree(&page_allocator, entry, suffix);
        }

        const catalog_page_id = try page_allocator.allocate();
        var payload = std.ArrayListUnmanaged(u8).empty;
        defer payload.deinit(self.allocator);
        try encodeCatalogEntryRaw(self.allocator, &payload, .{
            .previous_page = if (self.header.indexed_reclamation) 0 else next_root_page,
            .key = key,
            .value = inline_value,
            .external_value_root_page = external_value_root_page,
            .external_value_len = if (external_value_root_page != 0) total_len else 0,
        });
        try page_allocator.writePage(catalog_page_id, .catalog, payload.items);
        next_root_page = catalog_page_id;
        key_index = try self.upsertCatalogIndex(&page_allocator, key_index, key, catalog_page_id);

        var next = previous;
        next.commit_sequence += 1;
        setCatalogRootPage(&next, root, try self.writeCatalogRoot(&page_allocator, next_root_page, key_index, catalogRootPage(previous, root)));
        next.free_map_root_page = try page_allocator.allocate();
        next.page_count = page_allocator.next_page_id;

        try page_allocator.flush();
        try self.reserveBareCommitManifestPage(&page_allocator);
        try self.persistAllocator(&page_allocator, &next);
        try self.publishBareCommit(&page_allocator, &next);
    }

    fn renameCatalogRecordForRoot(self: *NativeFile, root: CatalogRoot, old_key: []const u8, new_key: []const u8) !void {
        if (self.change_capture) |capture| {
            capture.record(self.allocator, if (root == .metadata) .metadata else .index, old_key);
            capture.record(self.allocator, if (root == .metadata) .metadata else .index, new_key);
        }
        if (self.read_only) return error.ReadOnly;
        if (std.mem.eql(u8, old_key, new_key)) return;

        if (self.stagingTransaction()) return self.stageCatalogRename(root, old_key, new_key);

        const previous = self.activeCheckpoint();
        const found_page = (try self.lookupCatalogPage(previous, root, old_key)) orelse {
            return;
        };
        const found_payload = try self.readPagePayloadByKindAlloc(self.allocator, found_page, .catalog);
        defer self.allocator.free(found_payload);
        const entry = try decodeCatalogEntry(found_payload);
        if (!std.mem.eql(u8, entry.key, old_key)) return error.InvalidNativePageChain;
        if (entry.is_delete) return;

        const roots = try self.readCatalogRoots(catalogRootPage(previous, root), previous);
        var next_root_page = roots.history;
        var page_allocator = try self.pageAllocatorFromFreeMap(previous);
        defer page_allocator.deinit();
        errdefer self.resetBareCommitManifestWindow();
        var editor = IndexEditor.init(self, previous, roots.index);
        editor.accounting_pages = &page_allocator;
        defer editor.deinit();

        var external_value_root_page: u64 = 0;
        if (entry.external_value_root_page != 0) {
            external_value_root_page = entry.external_value_root_page;
        }

        {
            const new_page_id = try page_allocator.allocate();
            var payload = std.ArrayListUnmanaged(u8).empty;
            defer payload.deinit(self.allocator);
            try encodeCatalogEntryRaw(self.allocator, &payload, .{
                .previous_page = if (self.header.indexed_reclamation) 0 else next_root_page,
                .key = new_key,
                .value = entry.value,
                .external_value_root_page = external_value_root_page,
                .external_value_len = entry.external_value_len,
            });
            try page_allocator.writePage(new_page_id, .catalog, payload.items);
            next_root_page = new_page_id;
            try editor.put(new_key, new_page_id);
        }

        if (self.header.indexed_reclamation) {
            try editor.remove(old_key);
        } else {
            const tombstone_page_id = try page_allocator.allocate();
            var payload = std.ArrayListUnmanaged(u8).empty;
            defer payload.deinit(self.allocator);
            try encodeCatalogEntryRaw(self.allocator, &payload, .{
                .previous_page = if (self.header.indexed_reclamation) 0 else next_root_page,
                .key = old_key,
                .is_delete = true,
            });
            try page_allocator.writePage(tombstone_page_id, .catalog, payload.items);
            next_root_page = tombstone_page_id;
            try editor.remove(old_key);
        }

        const key_index = try editor.finish(&page_allocator);
        var next = previous;
        next.commit_sequence += 1;
        setCatalogRootPage(&next, root, try self.writeCatalogRoot(&page_allocator, next_root_page, key_index, catalogRootPage(previous, root)));
        next.free_map_root_page = try page_allocator.allocate();
        next.page_count = page_allocator.next_page_id;

        try page_allocator.flush();
        try self.reserveBareCommitManifestPage(&page_allocator);
        try self.persistAllocator(&page_allocator, &next);
        try self.publishBareCommit(&page_allocator, &next);
    }

    pub fn getCatalogRecordAlloc(self: *NativeFile, allocator: Allocator, key: []const u8) !?[]u8 {
        return try self.getCatalogRecordFromRootAlloc(allocator, .metadata, key);
    }

    /// Includes scope heads retained after every secret has been deleted.
    /// Caller holds the catalog lock; values never need to be loaded/decrypted.
    pub fn hasSecretState(self: *NativeFile) !bool {
        var cursor = try self.metadataCatalogCursor(try self.materializeTransactionCheckpoint(), secret_catalog_prefix);
        defer cursor.deinit();
        const entry = (try cursor.next()) orelse return false;
        self.allocator.free(entry.key);
        return true;
    }

    pub fn metadataCatalogCursor(self: *NativeFile, checkpoint: CheckpointSlot, prefix: []const u8) !CatalogCursor {
        return try self.catalogCursor(checkpoint, .metadata, prefix);
    }

    pub fn getIndexCatalogRecordAlloc(self: *NativeFile, allocator: Allocator, key: []const u8) !?[]u8 {
        return try self.getCatalogRecordFromRootAlloc(allocator, .index, key);
    }

    pub fn getIndexCatalogRecordAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, key: []const u8, checkpoint: CheckpointSlot) !?[]u8 {
        return try self.getIndexCatalogRecordLimitedAtCheckpointAlloc(allocator, key, std.math.maxInt(usize), checkpoint);
    }

    /// Enforce the caller's limit against catalog metadata before allocating
    /// or reading any external payload, within the same pinned checkpoint.
    pub fn getIndexCatalogRecordLimitedAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, key: []const u8, max_bytes: usize, checkpoint: CheckpointSlot) !?[]u8 {
        return try self.getCatalogRecordFromRootAtCheckpointAlloc(allocator, .index, key, checkpoint, max_bytes);
    }

    pub fn getIndexCatalogRecordSize(self: *NativeFile, key: []const u8) !?usize {
        return try self.getCatalogRecordSizeFromRoot(.index, key);
    }

    pub fn getIndexCatalogRecordSizeAtCheckpoint(self: *NativeFile, key: []const u8, checkpoint: CheckpointSlot) !?usize {
        return try self.getCatalogRecordSizeFromRootAtCheckpoint(.index, key, checkpoint);
    }

    pub fn getIndexCatalogRecordRangeAlloc(
        self: *NativeFile,
        allocator: Allocator,
        key: []const u8,
        offset: u64,
        len: usize,
    ) !?[]u8 {
        return try self.getCatalogRecordRangeFromRootAlloc(allocator, .index, key, offset, len);
    }

    pub fn getIndexCatalogRecordRangeAtCheckpointAlloc(
        self: *NativeFile,
        allocator: Allocator,
        key: []const u8,
        offset: u64,
        len: usize,
        checkpoint: CheckpointSlot,
    ) !?[]u8 {
        return try self.getCatalogRecordRangeFromRootAtCheckpointAlloc(allocator, .index, key, offset, len, checkpoint);
    }

    fn getCatalogRecordFromRootAlloc(
        self: *NativeFile,
        allocator: Allocator,
        root: CatalogRoot,
        key: []const u8,
    ) !?[]u8 {
        try self.finishCatalogAppend(root, key);
        if (self.stagedEntry(if (root == .metadata) .metadata else .index, key)) |entry| {
            if (entry.is_delete) return null;
            return try self.catalogEntryValueAtCheckpointAlloc(allocator, entry, self.activeCheckpoint());
        }
        return try self.getCatalogRecordFromRootAtCheckpointAlloc(allocator, root, key, self.activeCheckpoint(), std.math.maxInt(usize));
    }

    fn getCatalogRecordFromRootAtCheckpointAlloc(
        self: *NativeFile,
        allocator: Allocator,
        root: CatalogRoot,
        key: []const u8,
        checkpoint: CheckpointSlot,
        max_bytes: usize,
    ) !?[]u8 {
        if (try self.redoOverlayEntry(if (root == .metadata) .metadata else .index, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return null;
            const value_len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
            if (value_len > max_bytes) return error.FileTooBig;
            return try self.catalogEntryValueAtCheckpointAlloc(allocator, entry, checkpoint);
        }
        const page_id = (try self.lookupCatalogPage(checkpoint, root, key)) orelse return null;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const payload = try reader.readPayload(self, checkpoint, page_id, 1, .catalog);
        const entry = try decodeCatalogEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNativePageChain;
        if (entry.is_delete) return null;
        const value_len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        if (value_len > max_bytes) return error.FileTooBig;
        return try self.catalogEntryValueAtCheckpointAlloc(allocator, entry, checkpoint);
    }

    fn getCatalogRecordSizeFromRoot(
        self: *NativeFile,
        root: CatalogRoot,
        key: []const u8,
    ) !?usize {
        if (self.stagingTransaction()) {
            if (self.transaction_writes) |writes| {
                if (writes.appends[@backingInt(root)].get(key)) |state| return state.len;
            }
        }
        if (self.stagedEntry(if (root == .metadata) .metadata else .index, key)) |entry| {
            if (entry.is_delete) return null;
            return if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        }
        return try self.getCatalogRecordSizeFromRootAtCheckpoint(root, key, self.activeCheckpoint());
    }

    fn getCatalogRecordSizeFromRootAtCheckpoint(
        self: *NativeFile,
        root: CatalogRoot,
        key: []const u8,
        checkpoint: CheckpointSlot,
    ) !?usize {
        if (try self.redoOverlayEntry(if (root == .metadata) .metadata else .index, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return null;
            return if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        }
        const page_id = (try self.lookupCatalogPage(checkpoint, root, key)) orelse return null;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const payload = try reader.readPayload(self, checkpoint, page_id, 1, .catalog);
        const entry = try decodeCatalogEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNativePageChain;
        if (entry.is_delete) return null;
        return if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
    }

    fn getCatalogRecordRangeFromRootAlloc(
        self: *NativeFile,
        allocator: Allocator,
        root: CatalogRoot,
        key: []const u8,
        offset: u64,
        len: usize,
    ) !?[]u8 {
        try self.finishCatalogAppend(root, key);
        if (self.stagedEntry(if (root == .metadata) .metadata else .index, key)) |entry| {
            if (entry.is_delete) return null;
            return try self.catalogEntryRangeAlloc(allocator, entry, offset, len, self.activeCheckpoint());
        }
        return try self.getCatalogRecordRangeFromRootAtCheckpointAlloc(allocator, root, key, offset, len, self.activeCheckpoint());
    }

    fn getCatalogRecordRangeFromRootAtCheckpointAlloc(
        self: *NativeFile,
        allocator: Allocator,
        root: CatalogRoot,
        key: []const u8,
        offset: u64,
        len: usize,
        checkpoint: CheckpointSlot,
    ) !?[]u8 {
        if (try self.redoOverlayEntry(if (root == .metadata) .metadata else .index, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return null;
            return try self.catalogEntryRangeAlloc(allocator, entry, offset, len, checkpoint);
        }
        const page_id = (try self.lookupCatalogPage(checkpoint, root, key)) orelse return null;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const payload = try reader.readPayload(self, checkpoint, page_id, 1, .catalog);
        const entry = try decodeCatalogEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNativePageChain;
        if (entry.is_delete) return null;
        return try self.catalogEntryRangeAlloc(allocator, entry, offset, len, checkpoint);
    }

    pub const IndexValue = struct {
        root: u64,
        length: usize,
        inline_bytes: []u8 = &.{},

        pub fn deinit(self: *IndexValue, allocator: Allocator) void {
            allocator.free(self.inline_bytes);
            self.* = undefined;
        }
    };

    /// Resolve an immutable artifact once. A generation/checkpoint pin must
    /// outlive this descriptor; only small inline values require owned bytes.
    pub fn openIndexValue(self: *NativeFile, allocator: Allocator, key: []const u8, checkpoint: CheckpointSlot) !IndexValue {
        // §9.3a: artifact leases resolve their external-value pointer through
        // here (artifact_source.zig's Registry.open/Capture.apply), so this
        // must see redo-log-diverted index-root entries, not just the real
        // tree -- same rule as getCatalogRecordFromRootAtCheckpointAlloc.
        if (try self.redoOverlayEntry(.index, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return error.FileNotFound;
            if (entry.external_value_root_page != 0) return .{ .root = entry.external_value_root_page, .length = entry.external_value_len };
            return .{ .root = 0, .length = entry.value.len, .inline_bytes = try allocator.dupe(u8, entry.value) };
        }
        const page_id = (try self.lookupCatalogPage(checkpoint, .index, key)) orelse return error.FileNotFound;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const payload = try reader.readPayload(self, checkpoint, page_id, 1, .catalog);
        const entry = try decodeCatalogEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNativePageChain;
        if (entry.is_delete) return error.FileNotFound;
        if (entry.external_value_root_page != 0) return .{ .root = entry.external_value_root_page, .length = entry.external_value_len };
        return .{ .root = 0, .length = entry.value.len, .inline_bytes = try allocator.dupe(u8, entry.value) };
    }

    pub fn readIndexValueInto(self: *NativeFile, value: IndexValue, offset: u64, out: []u8, checkpoint: CheckpointSlot) !void {
        if (offset > value.length or out.len > value.length - offset) return error.EndOfStream;
        if (value.root != 0) {
            return self.readValuePagesRangeInto(value.root, value.length, @intCast(offset), out, checkpoint);
        }
        @memcpy(out, value.inline_bytes[@intCast(offset)..][0..out.len]);
    }

    /// Authenticate a logical range in one forward traversal. Extent subtrees
    /// preceding the range are skipped without reading their payload pages.
    pub fn checksumIndexValue(self: *NativeFile, value: IndexValue, offset: u64, length: u64, checkpoint: CheckpointSlot) !u32 {
        if (offset > value.length or length > value.length - offset) return error.EndOfStream;
        if (length == 0) return Crc32.hash("");
        if (value.root == 0) return Crc32.hash(value.inline_bytes[@intCast(offset)..][0..@intCast(length)]);
        var cursor: ValueChunkCursor = undefined;
        try cursor.initInto(self, value.root, value.length, checkpoint, true);
        defer cursor.deinit();
        cursor.skip = @intCast(offset);
        cursor.read_end = @intCast(offset + length);
        var remaining: usize = @intCast(length);
        var crc = Crc32.init();
        while (remaining != 0) {
            const chunk = (try cursor.next(null)) orelse return error.InvalidNativeValueChain;
            const take = @min(remaining, chunk.len);
            crc.update(chunk[0..take]);
            remaining -= take;
        }
        return crc.final();
    }

    /// One forward traversal for cache fills, checksumming, and range delivery.
    pub fn visitIndexValue(self: *NativeFile, value: IndexValue, offset: u64, length: u64, checkpoint: CheckpointSlot, context: *anyopaque, visit: *const fn (*anyopaque, u64, []const u8) anyerror!void) !void {
        if (offset > value.length or length > value.length - offset) return error.EndOfStream;
        if (length == 0) return;
        if (value.root == 0) return visit(context, 0, value.inline_bytes[@intCast(offset)..][0..@intCast(length)]);
        var cursor: ValueChunkCursor = undefined;
        try cursor.initInto(self, value.root, value.length, checkpoint, true);
        defer cursor.deinit();
        cursor.skip = @intCast(offset);
        cursor.read_end = @intCast(offset + length);
        var position: u64 = 0;
        while (position < length) {
            const chunk = (try cursor.next(null)) orelse return error.InvalidNativeValueChain;
            const take: usize = @intCast(@min(chunk.len, length - position));
            try visit(context, position, chunk[0..take]);
            position += take;
        }
    }

    /// Authenticate and deliver a logical subrange in one forward traversal.
    /// Output is private scratch until the expected CRC has been checked.
    pub fn readAuthenticatedIndexValue(self: *NativeFile, value: IndexValue, offset: u64, length: u64, within: usize, out: []u8, expected: ?u32, checkpoint: CheckpointSlot) !void {
        if (offset > value.length or length > value.length - offset or within > length or out.len > length - within) return error.EndOfStream;
        if (expected == null) return self.readIndexValueInto(value, offset + within, out, checkpoint);
        if (value.root == 0) {
            const bytes = value.inline_bytes[@intCast(offset)..][0..@intCast(length)];
            if (Crc32.hash(bytes) != expected.?) return error.CrcMismatch;
            @memcpy(out, bytes[within..][0..out.len]);
            return;
        }
        var cursor: ValueChunkCursor = undefined;
        try cursor.initInto(self, value.root, value.length, checkpoint, true);
        defer cursor.deinit();
        cursor.skip = @intCast(offset);
        cursor.read_end = @intCast(offset + length);
        var position: u64 = 0;
        var crc = Crc32.init();
        while (position < length) {
            const chunk = (try cursor.next(null)) orelse return error.InvalidNativeValueChain;
            const take: usize = @intCast(@min(chunk.len, length - position));
            crc.update(chunk[0..take]);
            const begin = @max(position, within);
            const end = @min(position + take, @as(u64, within) + out.len);
            if (begin < end) @memcpy(out[@intCast(begin - within)..][0..@intCast(end - begin)], chunk[@intCast(begin - position)..][0..@intCast(end - begin)]);
            position += take;
        }
        if (crc.final() != expected.?) return error.CrcMismatch;
    }

    /// Export a pinned artifact with bounded scratch and one forward page
    /// traversal. The destination remains private until its caller publishes.
    pub fn copyIndexValueTo(self: *NativeFile, value: IndexValue, destination: std.Io.File, checkpoint: CheckpointSlot) !void {
        if (value.root == 0) return destination.writePositionalAll(self.runtimeIo(), value.inline_bytes, 0);
        var cursor: ValueChunkCursor = undefined;
        try cursor.initInto(self, value.root, value.length, checkpoint, false);
        defer cursor.deinit();
        var position: u64 = 0;
        while (try cursor.next(null)) |chunk| {
            try destination.writePositionalAll(self.runtimeIo(), chunk, position);
            position += chunk.len;
        }
        if (position != value.length) return error.InvalidNativeValueChain;
    }

    pub fn snapshotCatalogRecordsAlloc(self: *NativeFile, allocator: Allocator) ![]OwnedCatalogRecord {
        return try self.snapshotCatalogRecordsFromRootAlloc(allocator, .metadata);
    }

    pub fn snapshotIndexCatalogRecordsAlloc(self: *NativeFile, allocator: Allocator) ![]OwnedCatalogRecord {
        return try self.snapshotCatalogRecordsFromRootAlloc(allocator, .index);
    }

    pub fn snapshotIndexCatalogKeysAlloc(self: *NativeFile, allocator: Allocator) ![]OwnedCatalogKey {
        return try self.snapshotCatalogKeysFromRootAlloc(allocator, .index);
    }

    pub fn indexCatalogCursor(self: *NativeFile, checkpoint: CheckpointSlot, prefix: []const u8) !CatalogCursor {
        return try self.catalogCursor(checkpoint, .index, prefix);
    }

    /// Compare a physical index read set between pinned checkpoints of the
    /// same inode. Copy-on-write subtree references prove equality without
    /// enumerating unchanged records. Splits/heights may differ; fall back to
    /// comparing leaf keys and immutable record references in changed paths.
    /// The caller fences page reuse and generation replacement for both roots.
    pub fn indexCatalogPrefixUnchanged(self: *NativeFile, latest: *NativeFile, prefix: []const u8) !bool {
        const upper = try prefixUpperAlloc(self.allocator, prefix);
        defer if (upper) |bytes| self.allocator.free(bytes);
        return self.catalogRangeUnchanged(latest, .index, prefix, upper);
    }

    fn prefixUpperAlloc(a: Allocator, prefix: []const u8) !?[]u8 {
        var end = prefix.len;
        while (end > 0 and prefix[end - 1] == 255) end -= 1;
        if (end == 0) return null;
        const upper = try a.dupe(u8, prefix[0..end]);
        upper[end - 1] += 1;
        return upper;
    }

    /// Runtime metadata is stable across artifact-lease bookkeeping. Primary
    /// namespace roots and every other metadata record must remain identical;
    /// callers separately fence the physical index prefixes they have loaded.
    pub fn runtimeMetadataUnchanged(self: *NativeFile, latest: *NativeFile) !bool {
        const before = self.activeCheckpoint();
        const after = latest.activeCheckpoint();
        if (self.header.indexed_reclamation and latest.header.indexed_reclamation) {
            if (self.header.page_size != latest.header.page_size or
                !std.mem.eql(u8, &before.logical.primary, &after.logical.primary)) return false;
            if (std.mem.eql(u8, &before.logical.metadata, &after.logical.metadata)) return true;
            // Raw catalog callers can publish lease keys without the dedicated
            // lease transaction. Retain the fenced exact comparison for that
            // conservative identity change; never traverse an unretained cut.
        }
        // An idle runtime has no inode reader fence. Its old page IDs are
        // comparable only while the allocator still retains that checkpoint;
        // a retired slot could already have been reused for unrelated bytes.
        const retained = for (latest.header.checkpoints) |slot| {
            if (validCheckpointSlot(slot) and std.meta.eql(before, slot)) break true;
        } else false;
        if (!retained) return false;
        if (self.header.page_size != latest.header.page_size or self.header.indexed_reclamation != latest.header.indexed_reclamation or
            before.document_root_page != after.document_root_page or before.document_index_root_page != after.document_index_root_page or
            before.namespace_directory_root_page != after.namespace_directory_root_page) return false;
        if (before.catalog_root_page == after.catalog_root_page) return true;
        const upper = (try prefixUpperAlloc(self.allocator, artifact_lease_key_prefix)).?;
        defer self.allocator.free(upper);
        return try self.catalogRangeUnchanged(latest, .metadata, "", artifact_lease_key_prefix) and
            try self.catalogRangeUnchanged(latest, .metadata, upper, null);
    }

    fn catalogRangeUnchanged(self: *NativeFile, latest: *NativeFile, root: CatalogRoot, lower: []const u8, upper: ?[]const u8) !bool {
        var before = try self.catalogCursor(self.activeCheckpoint(), root, "");
        defer before.deinit();
        var after = try latest.catalogCursor(latest.activeCheckpoint(), root, "");
        defer after.deinit();
        var lhs = try before.index.seekAtOrAfter(lower, false);
        defer if (lhs) |*entry| entry.deinit(self.allocator);
        var rhs = try after.index.seekAtOrAfter(lower, false);
        defer if (rhs) |*entry| entry.deinit(latest.allocator);
        while (true) {
            const left_in_range = if (lhs) |entry| if (upper) |limit| std.mem.lessThan(u8, entry.key, limit) else true else false;
            const right_in_range = if (rhs) |entry| if (upper) |limit| std.mem.lessThan(u8, entry.key, limit) else true else false;
            if (!left_in_range or !right_in_range) return left_in_range == right_in_range;
            if (!std.mem.eql(u8, lhs.?.key, rhs.?.key) or lhs.?.document_page_id != rhs.?.document_page_id) return false;
            // Find the largest common subtree on the two cursor paths. A
            // shared page can occur at different depths after a root split.
            var shared: ?struct { left: usize, right: usize } = null;
            outer: for (0..before.index.depth) |i| {
                const left_page = before.index.subtreePage(i);
                for (0..after.index.depth) |j| {
                    if (left_page == after.index.subtreePage(j)) {
                        shared = .{ .left = i, .right = j };
                        break :outer;
                    }
                }
            }
            lhs.?.deinit(self.allocator);
            lhs = null;
            rhs.?.deinit(latest.allocator);
            rhs = null;
            if (shared) |node| {
                var left_page = try before.index.nextSubtree(node.left);
                var right_page = try after.index.nextSubtree(node.right);
                while (left_page != 0 and left_page == right_page) {
                    left_page = try before.index.nextSubtree(before.index.depth);
                    right_page = try after.index.nextSubtree(after.index.depth);
                }
                if (left_page != 0) {
                    try before.index.descendExtreme(left_page, true);
                    lhs = try before.index.currentEntry();
                }
                if (right_page != 0) {
                    try after.index.descendExtreme(right_page, true);
                    rhs = try after.index.currentEntry();
                }
            } else {
                lhs = try before.index.next();
                rhs = try after.index.next();
            }
        }
    }

    /// Requires canonical file keys with no empty path components. The
    /// borrowed prefix must end at a directory separator. Callers accepting
    /// repeated/trailing separators must use indexCatalogCursor and dirname
    /// filtering instead: such byte ranges can contain immediate files.
    /// Nested subtrees are skipped within the same checkpoint.
    pub fn indexCatalogDirectoryCursor(self: *NativeFile, checkpoint: CheckpointSlot, prefix: []const u8) !CatalogCursor {
        if (prefix.len == 0 or prefix[prefix.len - 1] != '/') return error.InvalidNativeIndexPath;
        var cursor = try self.catalogCursor(checkpoint, .index, prefix);
        cursor.immediate_children_only = true;
        return cursor;
    }

    fn catalogCursor(self: *NativeFile, checkpoint: CheckpointSlot, root: CatalogRoot, prefix: []const u8) !CatalogCursor {
        const roots = try self.readCatalogRoots(catalogRootPage(checkpoint, root), checkpoint);
        var indexed = checkpoint;
        indexed.document_index_root_page = roots.index;
        const overlay_root: TransactionWrites.Root = if (root == .metadata) .metadata else .index;
        var overlay = try OverlayScanState.initForPrefix(self.allocator, self, overlay_root, checkpoint, prefix);
        errdefer overlay.deinit();
        return .{ .index = CheckpointedTree.init(self, indexed), .prefix = prefix, .overlay_root = overlay_root, .overlay = overlay };
    }

    fn snapshotCatalogRecordsFromRootAlloc(self: *NativeFile, allocator: Allocator, root: CatalogRoot) ![]OwnedCatalogRecord {
        const checkpoint = try self.materializeTransactionCheckpoint();
        var cursor = try self.catalogCursor(checkpoint, root, "");
        defer cursor.deinit();
        var records = std.ArrayListUnmanaged(OwnedCatalogRecord).empty;
        errdefer {
            for (records.items) |record| {
                allocator.free(record.key);
                allocator.free(record.value);
            }
            records.deinit(allocator);
        }
        while (try cursor.nextRecordAlloc(allocator)) |record| {
            errdefer allocator.free(record.key);
            errdefer allocator.free(record.value);
            try records.append(allocator, record);
        }

        return try records.toOwnedSlice(allocator);
    }

    fn snapshotCatalogKeysFromRootAlloc(self: *NativeFile, allocator: Allocator, root: CatalogRoot) ![]OwnedCatalogKey {
        var cursor = try self.catalogCursor(try self.materializeTransactionCheckpoint(), root, "");
        defer cursor.deinit();
        var keys = std.ArrayListUnmanaged(OwnedCatalogKey).empty;
        errdefer {
            for (keys.items) |record| allocator.free(record.key);
            keys.deinit(allocator);
        }
        while (try cursor.next()) |record| {
            defer self.allocator.free(record.key);
            const key = try allocator.dupe(u8, record.key);
            errdefer allocator.free(key);
            try keys.append(allocator, .{ .key = key });
        }
        return try keys.toOwnedSlice(allocator);
    }

    pub fn freeSnapshotCatalogRecords(allocator: Allocator, records: []OwnedCatalogRecord) void {
        for (records) |record| {
            allocator.free(record.key);
            allocator.free(record.value);
        }
        allocator.free(records);
    }

    pub fn freeSnapshotCatalogKeys(allocator: Allocator, records: []OwnedCatalogKey) void {
        for (records) |record| allocator.free(record.key);
        allocator.free(records);
    }

    fn snapshotCatalogRefsFromRootAlloc(self: *NativeFile, allocator: Allocator, root: CatalogRoot) ![]OwnedLiveRecordRef {
        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(allocator);
        var tombstones = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (tombstones.items) |key| allocator.free(key);
            tombstones.deinit(allocator);
        }
        var refs = std.ArrayListUnmanaged(OwnedLiveRecordRef).empty;
        errdefer {
            for (refs.items) |record| allocator.free(record.key);
            refs.deinit(allocator);
        }

        var page_id = try self.catalogHistoryRoot(self.activeCheckpoint(), root);
        while (page_id != 0) {
            const payload = try self.readPagePayloadByKindAlloc(allocator, page_id, .catalog);
            defer allocator.free(payload);
            const entry = try decodeCatalogEntry(payload);
            if (!seen.contains(entry.key)) {
                try seen.ensureUnusedCapacity(allocator, 1);
                const key = try allocator.dupe(u8, entry.key);
                errdefer allocator.free(key);
                if (entry.is_delete) {
                    try tombstones.append(allocator, key);
                } else {
                    try refs.append(allocator, .{ .key = key, .page_id = page_id });
                }
                seen.putAssumeCapacity(key, {});
            }
            page_id = entry.previous_page;
        }
        std.mem.sort(OwnedLiveRecordRef, refs.items, {}, liveRecordRefLessThan);
        return try refs.toOwnedSlice(allocator);
    }

    fn snapshotDocumentRefsAlloc(self: *NativeFile, allocator: Allocator) ![]OwnedLiveRecordRef {
        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(allocator);
        var tombstones = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (tombstones.items) |key| allocator.free(key);
            tombstones.deinit(allocator);
        }
        var refs = std.ArrayListUnmanaged(OwnedLiveRecordRef).empty;
        errdefer {
            for (refs.items) |record| allocator.free(record.key);
            refs.deinit(allocator);
        }

        var page_id = self.activeCheckpoint().document_root_page;
        while (page_id != 0) {
            const payload = try self.readPagePayloadByKindAlloc(allocator, page_id, .document);
            defer allocator.free(payload);
            const entry = try decodeDocumentEntry(payload);
            if (!seen.contains(entry.key)) {
                try seen.ensureUnusedCapacity(allocator, 1);
                const key = try allocator.dupe(u8, entry.key);
                errdefer allocator.free(key);
                if (entry.is_delete) {
                    try tombstones.append(allocator, key);
                } else {
                    try refs.append(allocator, .{ .key = key, .page_id = page_id });
                }
                seen.putAssumeCapacity(key, {});
            }
            page_id = entry.previous_page;
        }
        std.mem.sort(OwnedLiveRecordRef, refs.items, {}, liveRecordRefLessThan);
        return try refs.toOwnedSlice(allocator);
    }

    fn freeLiveRecordRefs(allocator: Allocator, refs: []OwnedLiveRecordRef) void {
        for (refs) |record| allocator.free(record.key);
        allocator.free(refs);
    }

    const LiveRecordSource = union(enum) {
        catalog: CatalogRoot,
        documents,
    };

    /// Borrow record metadata from the checkpoint's ordered index. Values stay
    /// on disk; returned slices remain valid until the next call to next().
    const LiveRecordCursor = struct {
        index: CheckpointedTree,
        kind: PageKind,
        started: bool = false,
        records: RecordPageReader = .{},
        /// §9.3a revised: see CatalogCursor's own fields of the same name.
        overlay_root: TransactionWrites.Root,
        overlay: OverlayScanState,
        pending_tree: ?DocumentIndexEntry = null,
        /// §9.6a: the owned value backing the most recent overlay-sourced
        /// `CatalogEntry` this cursor returned, if any -- `redoOverlayEntry`
        /// now allocates rather than borrowing from the live map (the
        /// shared overlay can be reclaimed by another instance the
        /// instant its own lock releases), so this cursor must hold the
        /// value itself for as long as its own lifetime contract
        /// ("returned slices remain valid until the next call to
        /// next()") requires, freeing it at the start of the next call
        /// (or in `deinit`, for the last one returned).
        overlay_value: ?[]const u8 = null,

        fn init(file: *NativeFile, source: LiveRecordSource) !LiveRecordCursor {
            var checkpoint = try file.materializeTransactionCheckpoint();
            const overlay_root: TransactionWrites.Root = switch (source) {
                .catalog => |root| if (root == .metadata) .metadata else .index,
                .documents => .documents,
            };
            const kind: PageKind = switch (source) {
                .catalog => |root| blk: {
                    const roots = try file.readCatalogRoots(catalogRootPage(checkpoint, root), checkpoint);
                    checkpoint.document_index_root_page = roots.index;
                    break :blk .catalog;
                },
                .documents => .document,
            };
            var overlay = try OverlayScanState.initForPrefix(file.allocator, file, overlay_root, checkpoint, "");
            errdefer overlay.deinit();
            return .{ .index = CheckpointedTree.init(file, checkpoint), .kind = kind, .overlay_root = overlay_root, .overlay = overlay };
        }

        pub fn deinit(self: *LiveRecordCursor) void {
            if (self.overlay_value) |v| self.index.file.allocator.free(v);
            if (self.pending_tree) |*p| p.deinit(self.index.file.allocator);
            self.overlay.deinit();
            self.records.deinit(self.index.file.allocator);
            self.index.deinit();
        }

        fn next(self: *LiveRecordCursor, cancel: ?*const maintenance.CancelToken) !?CatalogEntry {
            const file = self.index.file;
            if (self.overlay_value) |v| {
                file.allocator.free(v);
                self.overlay_value = null;
            }
            while (true) {
                if (cancel) |token| try token.check();
                const candidate = self.pending_tree orelse blk: {
                    const fetched = if (self.started) try self.index.next() else try self.index.first();
                    self.started = true;
                    break :blk fetched;
                };
                self.pending_tree = null;

                // Merge-join against the overlay, same rule as
                // CatalogCursor.next(): smaller key wins, a tie means the
                // overlay supersedes the tree's own stale entry.
                const overlay_key = try self.overlay.peek();
                const tree_key: ?[]const u8 = if (candidate) |c| c.key else null;
                const take_overlay = overlay_key != null and (tree_key == null or std.mem.order(u8, overlay_key.?, tree_key.?) != .gt);
                if (take_overlay) {
                    const key = overlay_key.?;
                    // §9.7c (ReadView): resolve before deciding whether
                    // `candidate` is actually superseded -- the overlay
                    // enumerates every key with *any* version currently
                    // in the live map, regardless of this cursor's own
                    // pinned checkpoint, so a cursor pinned to an older,
                    // already-superseded checkpoint can enumerate a key
                    // whose entire chain postdates it. `resolveAlloc`
                    // then correctly returns `null` -- "nothing at or
                    // before this checkpoint" -- which must be treated
                    // like the real tree never having had this key
                    // diverted away from it at this checkpoint (re-stash
                    // `candidate`, exactly as the non-tied branch below
                    // already does, and continue to find the next real
                    // candidate), not as corruption; `candidate` must
                    // never be freed here, only in the genuinely-tied
                    // case (same bug class as `MergedCursor.advance`'s
                    // own fix, and the mirror image of this function's
                    // own leak fix -- that fix made the error path free
                    // `candidate` instead of leaking it; this one makes
                    // the error path not exist at all, re-stashing
                    // `candidate` instead, same as every other "not
                    // actually superseded" path in this loop).
                    const entry = try file.redoOverlayEntry(self.overlay_root, self.index.checkpoint, key);
                    _ = try self.overlay.takeFront();
                    if (entry == null) {
                        self.pending_tree = candidate;
                        continue;
                    }
                    const tied = tree_key != null and std.mem.eql(u8, tree_key.?, key);
                    if (tied) {
                        var owned = candidate.?;
                        owned.deinit(file.allocator);
                    } else {
                        self.pending_tree = candidate;
                    }
                    if (entry.?.is_delete) {
                        file.allocator.free(entry.?.value);
                        continue;
                    }
                    self.overlay_value = entry.?.value;
                    return entry;
                }

                var indexed = candidate orelse return null;
                defer indexed.deinit(file.allocator);
                const payload = try self.records.read(file, file.allocator, self.index.checkpoint, indexed.document_page_id, self.kind);
                const entry = if (self.kind == .catalog) try decodeCatalogEntry(payload) else blk: {
                    const document = try decodeDocumentEntry(payload);
                    break :blk CatalogEntry{
                        .previous_page = document.previous_page,
                        .key = document.key,
                        .value = document.value,
                        .is_delete = document.is_delete,
                        .external_value_root_page = document.external_value_root_page,
                        .external_value_len = document.external_value_len,
                    };
                };
                if (!std.mem.eql(u8, entry.key, indexed.key)) return error.InvalidDocumentIndex;
                if (!entry.is_delete) return entry;
            }
        }
    };

    const NamespaceDirectory = std.StringHashMapUnmanaged(u64);
    const NamespaceDirectoryRecordKind = enum(u8) {
        snapshot = 0,
        delta = 1,
    };

    const LoadedNamespaceDirectory = struct {
        entries: NamespaceDirectory,
        delta_depth: u16,
    };

    fn documentNamespace(key: []const u8) []const u8 {
        const end = (std.mem.indexOfScalar(u8, key, 0) orelse return "") + 1;
        return key[0..end];
    }

    fn deinitNamespaceDirectory(allocator: Allocator, directory: *NamespaceDirectory) void {
        var it = directory.keyIterator();
        while (it.next()) |key| allocator.free(key.*);
        directory.deinit(allocator);
    }

    fn applyNamespaceDirectoryRecord(
        allocator: Allocator,
        directory: *NamespaceDirectory,
        raw: []const u8,
    ) !NamespaceDirectoryRecordKind {
        if (raw.len < namespace_directory_magic.len + 1 + 4 or
            !std.mem.eql(u8, raw[0..namespace_directory_magic.len], namespace_directory_magic))
            return error.InvalidNamespaceDirectory;
        var offset: usize = namespace_directory_magic.len;
        const kind: NamespaceDirectoryRecordKind = switch (raw[offset]) {
            0 => .snapshot,
            1 => .delta,
            else => return error.InvalidNamespaceDirectory,
        };
        offset += 1;
        const count = std.mem.readInt(u32, raw[offset..][0..4], .little);
        offset += 4;
        if (@as(usize, count) > (raw.len - offset) / 12) return error.InvalidNamespaceDirectory;
        try directory.ensureUnusedCapacity(allocator, count);
        var record_keys = std.StringHashMapUnmanaged(void).empty;
        defer record_keys.deinit(allocator);
        try record_keys.ensureTotalCapacity(allocator, count);
        var i: u32 = 0;
        while (i < count) : (i += 1) {
            if (raw.len - offset < 4) return error.InvalidNamespaceDirectory;
            const len = std.mem.readInt(u32, raw[offset..][0..4], .little);
            offset += 4;
            if (len > raw.len - offset or raw.len - offset - len < 8) return error.InvalidNamespaceDirectory;
            const raw_key = raw[offset..][0..len];
            offset += len;
            const head = std.mem.readInt(u64, raw[offset..][0..8], .little);
            offset += 8;
            if ((raw_key.len > 0 and raw_key[raw_key.len - 1] != 0) or head == 0 or record_keys.contains(raw_key))
                return error.InvalidNamespaceDirectory;
            record_keys.putAssumeCapacity(raw_key, {});

            // Records are replayed newest to oldest. The first head for a
            // namespace is authoritative; older snapshots/deltas fill only
            // namespaces not mentioned by a newer record.
            if (!directory.contains(raw_key)) {
                const key = try allocator.dupe(u8, raw_key);
                directory.putAssumeCapacity(key, head);
            }
        }
        if (offset != raw.len) return error.InvalidNamespaceDirectory;
        return kind;
    }

    fn encodeNamespaceDirectoryAlloc(
        allocator: Allocator,
        kind: NamespaceDirectoryRecordKind,
        directory: *const NamespaceDirectory,
    ) ![]u8 {
        var out: std.Io.Writer.Allocating = .init(allocator);
        errdefer out.deinit();
        try out.writer.writeAll(namespace_directory_magic);
        try out.writer.writeByte(@backingInt(kind));
        try out.writer.writeInt(u32, std.math.cast(u32, directory.count()) orelse return error.RecordTooLarge, .little);
        var it = directory.iterator();
        while (it.next()) |entry| {
            try out.writer.writeInt(u32, @intCast(entry.key_ptr.*.len), .little);
            try out.writer.writeAll(entry.key_ptr.*);
            try out.writer.writeInt(u64, entry.value_ptr.*, .little);
        }
        return try out.toOwnedSlice();
    }

    fn loadNamespaceDirectoryWithDepthAlloc(self: *NativeFile, allocator: Allocator) !?LoadedNamespaceDirectory {
        return try self.loadNamespaceDirectoryWithDepthAtCheckpointAlloc(allocator, self.activeCheckpoint());
    }

    fn loadNamespaceDirectoryWithDepthAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot) !?LoadedNamespaceDirectory {
        var root = checkpoint.namespace_directory_root_page;
        if (root == 0) return null;
        const roots = try self.readCatalogRoots(root, checkpoint);
        if (roots.indexed) {
            var directory = NamespaceDirectory.empty;
            errdefer deinitNamespaceDirectory(allocator, &directory);
            var indexed = checkpoint;
            indexed.document_index_root_page = roots.index;
            var cursor = CheckpointedTree.init(self, indexed);
            defer cursor.deinit();
            var reader = RecordPageReader{};
            defer reader.deinit(allocator);
            var current = try cursor.first();
            while (current) |entry| {
                var owned = entry;
                defer owned.deinit(self.allocator);
                const record = try decodeCatalogEntry(try reader.read(self, allocator, checkpoint, entry.document_page_id, .catalog));
                if (!std.mem.eql(u8, record.key, entry.key)) return error.InvalidNamespaceDirectory;
                const head = try decodeNamespaceHead(record, checkpoint);
                const key = try allocator.dupe(u8, entry.key);
                directory.put(allocator, key, head) catch |err| {
                    allocator.free(key);
                    return err;
                };
                current = try cursor.next();
            }
            return .{ .entries = directory, .delta_depth = 0 };
        }
        var directory = NamespaceDirectory.empty;
        errdefer deinitNamespaceDirectory(allocator, &directory);
        var depth: u16 = 0;
        var walked: u64 = 0;
        while (root != 0) {
            const payload = try self.readPagePayloadByKindAllocForCheckpoint(allocator, root, .catalog, checkpoint);
            defer allocator.free(payload);
            const entry = try decodeCatalogEntry(payload);
            if (!std.mem.eql(u8, entry.key, namespace_directory_key) or entry.is_delete)
                return error.InvalidNamespaceDirectory;
            const raw = try self.catalogEntryValueAtCheckpointAlloc(allocator, entry, checkpoint);
            defer allocator.free(raw);
            const kind = try applyNamespaceDirectoryRecord(allocator, &directory, raw);
            walked += 1;
            if (walked > recordWalkLimit(checkpoint, self.header.page_size)) return error.InvalidNativePageChain;
            switch (kind) {
                .snapshot => {
                    if (entry.previous_page != 0) return error.InvalidNamespaceDirectory;
                    return .{ .entries = directory, .delta_depth = depth };
                },
                .delta => {
                    depth = std.math.add(u16, depth, 1) catch return error.InvalidNamespaceDirectory;
                    root = entry.previous_page;
                    if (root == 0) return error.InvalidNamespaceDirectory;
                },
            }
        }
        return error.InvalidNamespaceDirectory;
    }

    fn loadNamespaceDirectoryAlloc(self: *NativeFile, allocator: Allocator) !?NamespaceDirectory {
        const loaded = (try self.loadNamespaceDirectoryWithDepthAlloc(allocator)) orelse return null;
        return loaded.entries;
    }

    fn loadNamespaceDirectoryAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot) !?NamespaceDirectory {
        const loaded = (try self.loadNamespaceDirectoryWithDepthAtCheckpointAlloc(allocator, checkpoint)) orelse return null;
        return loaded.entries;
    }

    fn namespaceHeadAtCheckpoint(self: *NativeFile, checkpoint: CheckpointSlot, index: u64, namespace: []const u8) !u64 {
        var indexed = checkpoint;
        indexed.document_index_root_page = index;
        const page = (try self.lookupDocumentIndexPage(indexed, namespace)) orelse return 0;
        var scratch: [65536]u8 = undefined;
        const entry = try decodeCatalogEntry(try decodePagePayload(try self.readPageInto(page, checkpoint, &scratch), .catalog));
        if (!std.mem.eql(u8, entry.key, namespace)) return error.InvalidNamespaceDirectory;
        return decodeNamespaceHead(entry, checkpoint);
    }

    // One borrowed key per touched namespace. Collect before writing so map
    // storage and lookup scratch scale with namespaces, not document count,
    // and repeated mutations can update stable head pointers in input order.
    fn prepareNamespaceHeads(self: *NativeFile, checkpoint: CheckpointSlot, roots: CatalogRoots, mutations: []const DocumentMutation) !NamespaceDirectory {
        var heads = NamespaceDirectory.empty;
        errdefer heads.deinit(self.allocator);
        var last: ?[]const u8 = null;
        for (mutations) |mutation| {
            const namespace = documentNamespace(mutation.key);
            if (last) |previous| if (std.mem.eql(u8, previous, namespace)) continue;
            const entry = try heads.getOrPut(self.allocator, namespace);
            if (!entry.found_existing) entry.value_ptr.* = 0;
            last = namespace;
        }
        if (roots.indexed) {
            try self.loadNamespaceHeadsAtCheckpoint(checkpoint, roots.index, &heads);
        } else {
            var it = heads.iterator();
            while (it.next()) |entry| entry.value_ptr.* = self.namespace_directory_cache.get(entry.key_ptr.*) orelse 0;
        }
        return heads;
    }

    fn sortedNamespaceKeysAlloc(allocator: Allocator, heads: *const NamespaceDirectory) ![][]const u8 {
        const keys = try allocator.alloc([]const u8, heads.count());
        var it = heads.keyIterator();
        for (keys) |*key| key.* = it.next().?.*;
        std.mem.sort([]const u8, keys, {}, struct {
            fn less(_: void, a: []const u8, b: []const u8) bool {
                return std.mem.lessThan(u8, a, b);
            }
        }.less);
        return keys;
    }

    fn loadNamespaceHeadsAtCheckpoint(self: *NativeFile, checkpoint: CheckpointSlot, index: u64, heads: *NamespaceDirectory) !void {
        if (heads.count() == 0 or index == 0) return;
        if (heads.count() == 1) {
            var it = heads.iterator();
            const entry = it.next().?;
            entry.value_ptr.* = try self.namespaceHeadAtCheckpoint(checkpoint, index, entry.key_ptr.*);
            return;
        }
        const keys = try sortedNamespaceKeysAlloc(self.allocator, heads);
        defer self.allocator.free(keys);
        const references = try self.allocator.alloc(u64, keys.len);
        defer self.allocator.free(references);
        @memset(references, 0);
        var indexed = checkpoint;
        indexed.document_index_root_page = index;
        // Share the sorted multi-read traversal with documents: each relevant
        // tree node is decoded once, even when many keys share its path.
        try self.readDocumentBatchNode(indexed, index, keys, references);
        // Key order and physical order diverge after independent updates.
        // Reorder both borrowed keys and references together so every packed
        // record page is fetched/decoded once, without a third ordering array.
        const PhysicalOrder = struct {
            keys: [][]const u8,
            references: []u64,
            pub fn lessThan(ctx: @This(), a: usize, b: usize) bool {
                return recordReferenceLessThan(ctx.references[a], ctx.references[b]);
            }
            pub fn swap(ctx: @This(), a: usize, b: usize) void {
                std.mem.swap([]const u8, &ctx.keys[a], &ctx.keys[b]);
                std.mem.swap(u64, &ctx.references[a], &ctx.references[b]);
            }
        };
        std.sort.pdqContext(0, keys.len, PhysicalOrder{ .keys = keys, .references = references });
        var reader = RecordPageReader{};
        defer reader.deinit(self.allocator);
        for (keys, references) |key, reference| {
            if (reference == 0) continue;
            const entry = try decodeCatalogEntry(try reader.read(self, self.allocator, checkpoint, reference, .catalog));
            if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNamespaceDirectory;
            heads.getPtr(key).?.* = try decodeNamespaceHead(entry, checkpoint);
        }
    }

    fn decodeNamespaceHead(entry: CatalogEntry, checkpoint: CheckpointSlot) !u64 {
        if (entry.is_delete or entry.external_value_root_page != 0 or entry.value.len != 8 or
            (entry.key.len > 0 and entry.key[entry.key.len - 1] != 0)) return error.InvalidNamespaceDirectory;
        const head = std.mem.readInt(u64, entry.value[0..8], .little);
        if (head == 0 or physicalPage(head) >= checkpoint.page_count) return error.InvalidNamespaceDirectory;
        return head;
    }

    // Uses existing revision-3 catalog descriptors, records and B+ tree pages.
    // A legacy directory is converted once; indexed updates retain only the
    // touched paths. Bulk construction also serves vacuum and initial ingest.
    const WrittenNamespaceDirectory = struct { page: u64, indexed: bool };

    fn writeNamespaceIndex(self: *NativeFile, pages: *PageAllocator, checkpoint: CheckpointSlot, roots: CatalogRoots, heads: *const NamespaceDirectory) !WrittenNamespaceDirectory {
        // Keep tiny directories in the existing inline snapshot encoding.
        // This bounds their cost while avoiding an extra tree/descriptor on
        // the common single-namespace path. Promotion is one-way until vacuum.
        if (!self.header.indexed_reclamation and !roots.indexed and heads.count() <= 32) {
            const encoded = try encodeNamespaceDirectoryAlloc(self.allocator, .snapshot, heads);
            defer self.allocator.free(encoded);
            if (self.catalogEntryFitsInline(namespace_directory_key, encoded)) {
                var payload = std.ArrayListUnmanaged(u8).empty;
                defer payload.deinit(self.allocator);
                try encodeCatalogEntry(self.allocator, &payload, .{ .previous_page = 0, .key = namespace_directory_key, .value = encoded });
                const page = try pages.allocate();
                try pages.writePage(page, .catalog, payload.items);
                return .{ .page = page, .indexed = false };
            }
        }
        const keys = try sortedNamespaceKeysAlloc(self.allocator, heads);
        defer self.allocator.free(keys);
        const bulk = roots.index == 0;
        var builder = DocumentIndexBulkBuilder{ .owner = self, .file = self.file, .next_page_id = &pages.next_page_id, .pages = pages };
        defer builder.deinit();
        var editor = IndexEditor.init(self, checkpoint, roots.index);
        editor.accounting_pages = pages;
        defer editor.deinit();
        if (keys.len > 1) editor.streaming_pages = pages;
        var history = if (roots.indexed) roots.history else 0;
        for (keys) |key| {
            var value: [8]u8 = undefined;
            std.mem.writeInt(u64, &value, heads.get(key).?, .little);
            history = try pages.writeCatalog(.{ .previous_page = if (self.header.indexed_reclamation) 0 else history, .key = key, .value = &value });
            if (bulk) try builder.add(key, history) else try editor.put(key, history);
        }
        const index = if (bulk) try builder.finish() else try editor.finish(pages);
        return .{ .page = try self.writeCatalogRoot(pages, history, index, checkpoint.namespace_directory_root_page), .indexed = true };
    }

    fn ensureNamespaceDirectoryCache(self: *NativeFile) !void {
        const root = self.activeCheckpoint().namespace_directory_root_page;
        if (self.namespace_directory_cache_root == root) return;
        const loaded = (try self.loadNamespaceDirectoryWithDepthAlloc(self.allocator)) orelse LoadedNamespaceDirectory{
            .entries = NamespaceDirectory.empty,
            .delta_depth = 0,
        };
        deinitNamespaceDirectory(self.allocator, &self.namespace_directory_cache);
        self.namespace_directory_cache = loaded.entries;
        self.namespace_directory_delta_depth = loaded.delta_depth;
        self.namespace_directory_cache_root = root;
    }

    fn validateNamespaceDirectory(self: *NativeFile, checkpoint: CheckpointSlot) !void {
        var records = RecordPageReader{};
        defer records.deinit(self.allocator);
        var directory = (try self.loadNamespaceDirectoryAlloc(self.allocator)) orelse return;
        defer deinitNamespaceDirectory(self.allocator, &directory);

        // Verify the complete index in one global-history pass. Each map value
        // is the document page that the next occurrence of that namespace must
        // have. This proves directory heads are current, every document is
        // indexed exactly once, and every namespace link targets the next older
        // document without adding a second O(history) namespace traversal.
        var expected_pages = std.StringHashMapUnmanaged(u64).empty;
        defer expected_pages.deinit(self.allocator);
        try expected_pages.ensureTotalCapacity(self.allocator, directory.count());
        var directory_it = directory.iterator();
        while (directory_it.next()) |entry| {
            expected_pages.putAssumeCapacity(entry.key_ptr.*, entry.value_ptr.*);
        }

        var page_id = checkpoint.document_root_page;
        var walked: u64 = 0;
        while (page_id != 0) {
            if (physicalPage(page_id) >= checkpoint.page_count) return error.InvalidPageId;
            const payload = try records.read(self, self.allocator, checkpoint, page_id, .document);
            const entry = try decodeDocumentEntry(payload);
            const expected = expected_pages.getPtr(documentNamespace(entry.key)) orelse return error.InvalidNamespaceDirectory;
            if (expected.* != page_id) return error.InvalidNamespaceDirectory;
            expected.* = entry.previous_namespace_page;
            page_id = entry.previous_page;
            walked += 1;
            if (walked > recordWalkLimit(checkpoint, self.header.page_size)) return error.InvalidNativePageChain;
        }
        var expected_it = expected_pages.valueIterator();
        while (expected_it.next()) |expected| {
            if (expected.* != 0) return error.InvalidNamespaceDirectory;
        }
    }

    pub fn putDocument(self: *NativeFile, key: []const u8, value: []const u8) !void {
        try self.putDocumentBatch(&.{.{ .key = key, .value = value }});
    }

    pub fn deleteDocument(self: *NativeFile, key: []const u8) !void {
        try self.putDocumentBatch(&.{.{ .key = key, .is_delete = true }});
    }

    pub fn putDocumentBatch(self: *NativeFile, mutations: []const DocumentMutation) anyerror!void {
        if (self.read_only) return error.ReadOnly;
        if (mutations.len == 0) return;
        for (mutations) |mutation| try self.validateDocumentMutation(mutation);
        // All backends and SQL/DDL producers meet at this physical writer.
        // A standalone schema write also uses a transaction, so no crash can
        // expose recovery work without its agenda marker (or vice versa).
        if (self.header.indexed_reclamation and !self.flushing_transaction) {
            const tracked = for (mutations) |mutation| {
                if (recovery_agenda.namespace(mutation.key) != null) break true;
            } else false;
            if (tracked and self.transaction_header == null) {
                try self.beginTransaction();
                errdefer self.abortTransaction();
                try self.putDocumentBatch(mutations);
                try self.commitTransaction();
                return;
            }
            if (tracked) for (mutations) |mutation| {
                const scope = recovery_agenda.namespace(mutation.key) orelse continue;
                const marker = try std.mem.concat(self.allocator, u8, &.{ recovery_agenda.prefix, scope });
                defer self.allocator.free(marker);
                try self.putCatalogRecord(marker, "");
            };
        }
        if (self.change_capture) |capture| for (mutations) |mutation| capture.record(self.allocator, .documents, mutation.key);

        if (self.stagingTransaction() and mutations.len >= TransactionWrites.max_keys) {
            // The caller already owns a complete batch until this call returns.
            // Consume it directly instead of copying it into bounded staging
            // and rebuilding the same index for every staging-sized chunk --
            // but only for a non-diverting commit, where that rebuild cost is
            // real. `writes.pages.diverting` (computed by `transactionWrites`
            // from the same `self.redo`/`checkpointing`/`overLargeTransactionThreshold`
            // condition `flushTransactionWrites` uses) means this transaction
            // logs mutations logically instead of building real pages; taking
            // this branch anyway would run `putIndexedDocumentBatch`'s real
            // `IndexEditor`/bulk-builder pass straight through
            // `writes.pages`, writing document and document-index *B-tree*
            // pages into a diverting, no-ledger `PageAllocator`
            // (`pageAllocatorForDivertingCommit`'s own doc comment: no
            // `.ledger` is ever attached to it). `PageWriteBatch.flushCount`'s
            // diverting branch stages those pages into
            // `RedoCommitState.pending`/`appendPending` the same way it
            // stages an external value chain's pages -- but
            // `appendPending`'s own doc comment is explicit that only
            // external value chains are meant to land there, never B-tree
            // pages, because `checkpointRedoLog`'s `has_logical_work`
            // check (`redo.shared.count(...) != 0` across all three roots)
            // assumes page-shaped writes never accumulate without an
            // accompanying logical mutation in the same commit. A bulk
            // batch taking this shortcut stages B-tree pages with no
            // logical mutation to go with them, so that check sees no
            // logical work, treats the fold as a no-op, and the ledger
            // never learns about the newly built pages at all --
            // `check()`'s reachability walk then finds them referenced
            // but uncounted and fails with `error.InvalidNativeAllocator`,
            // even though the commit itself reported success. Falling
            // through to the per-mutation `stageMutation` loop below is
            // exactly as cheap under diverting as this shortcut: logging a
            // mutation logically never rebuilds an index, regardless of
            // how many `TransactionWrites.max_keys`-sized chunks a large
            // batch spills across.
            try self.flushTransactionWrites();
            const writes = try self.transactionWrites();
            if (!writes.pages.diverting) {
                self.flushing_transaction = true;
                self.transaction_pages = &writes.pages;
                defer {
                    self.transaction_pages = null;
                    self.flushing_transaction = false;
                }
                try self.putDocumentBatch(mutations);
                try writes.pages.flush();
                return;
            }
        }
        if (self.stagingTransaction()) {
            for (mutations) |m| try self.stageMutation(.documents, .{ .key = m.key, .value = m.value, .is_delete = m.is_delete, .external_value_root_page = m.external_value_root_page, .external_value_len = m.external_value_len }, .{});
            return;
        }

        if (self.header.indexed_reclamation) return self.putIndexedDocumentBatch(mutations);
        const previous = self.activeCheckpoint();
        const namespace_roots = try self.readCatalogRoots(previous.namespace_directory_root_page, previous);
        if (!namespace_roots.indexed) try self.ensureNamespaceDirectoryCache();
        if (previous.document_root_page != 0 and
            (if (namespace_roots.indexed) namespace_roots.index == 0 else self.namespace_directory_cache.count() == 0))
            return error.InvalidNamespaceDirectory;
        var changed_heads = try self.prepareNamespaceHeads(previous, namespace_roots, mutations);
        defer changed_heads.deinit(self.allocator);
        var next_root_page = previous.document_root_page;
        var next_index_root_page = previous.document_index_root_page;
        const bulk_build_initial_index = next_index_root_page == 0;
        const stream_initial_index = bulk_build_initial_index and mutationKeysSorted(mutations);
        var initial_index_entries = std.ArrayListUnmanaged(PendingDocumentIndexEntry).empty;
        defer initial_index_entries.deinit(self.allocator);
        if (bulk_build_initial_index and !stream_initial_index) try initial_index_entries.ensureTotalCapacity(self.allocator, mutations.len);
        var local_pages: PageAllocator = undefined;
        if (self.transaction_pages == null) local_pages = try self.pageAllocatorFromFreeMap(previous);
        defer if (self.transaction_pages == null) local_pages.deinit();
        errdefer if (self.transaction_pages == null) self.resetBareCommitManifestWindow();
        const page_allocator = self.transaction_pages orelse &local_pages;
        page_allocator.pack_records = self.header.packed_records and (mutations.len > 1 or self.transaction_pages != null);
        // Release the document editor before building the namespace index.
        // The two immutable roots need not retain both edit arenas at once.
        next_index_root_page = index_root: {
            var editor = IndexEditor.init(self, previous, next_index_root_page);
            defer editor.deinit();
            if (!bulk_build_initial_index) editor.useSortedBatch(page_allocator, mutations);
            var builder = DocumentIndexBulkBuilder{
                .owner = self,
                .file = self.file,
                .next_page_id = &page_allocator.next_page_id,
                .pages = page_allocator,
            };
            defer builder.deinit();

            for (mutations, 0..) |mutation, ordinal| {
                var external_value_root_page: u64 = mutation.external_value_root_page;
                if (external_value_root_page == 0 and !mutation.is_delete and !self.documentEntryFitsInline(mutation.key, mutation.value)) {
                    external_value_root_page = try self.writeDocumentValue(page_allocator, mutation.value);
                }

                const namespace = documentNamespace(mutation.key);
                const namespace_head = changed_heads.getPtr(namespace).?;
                const page_id = try page_allocator.writeDocument(.{
                    .previous_page = if (self.header.indexed_reclamation) 0 else next_root_page,
                    .previous_namespace_page = if (self.header.indexed_reclamation) 0 else namespace_head.*,
                    .key = mutation.key,
                    .value = mutation.value,
                    .is_delete = mutation.is_delete,
                    .external_value_root_page = external_value_root_page,
                    .external_value_len = mutation.external_value_len,
                });
                next_root_page = page_id;
                if (stream_initial_index) {
                    // Preserve every history record, but index only the last
                    // mutation in each equal-key group, including tombstones.
                    const last = ordinal + 1 == mutations.len or !std.mem.eql(u8, mutation.key, mutations[ordinal + 1].key);
                    if (last and !mutation.is_delete) try builder.add(mutation.key, page_id) else try page_allocator.retire(page_id, .record);
                } else if (bulk_build_initial_index) {
                    initial_index_entries.appendAssumeCapacity(.{
                        .key = mutation.key,
                        .document_page_id = page_id,
                        .ordinal = ordinal,
                    });
                } else if (mutation.is_delete) {
                    // History retains the tombstone; immutable older index roots
                    // retain their values. The current index contains only live keys.
                    try page_allocator.retire(page_id, .record);
                    try editor.remove(mutation.key);
                } else {
                    try editor.put(mutation.key, page_id);
                }
                namespace_head.* = page_id;
            }

            if (bulk_build_initial_index) {
                // Sorted input has already streamed through the builder. Unsorted
                // input keeps the ordinal-aware sort and latest-write-wins fallback.
                std.mem.sort(PendingDocumentIndexEntry, initial_index_entries.items, {}, PendingDocumentIndexEntry.lessThan);
                var index: usize = 0;
                while (index < initial_index_entries.items.len) {
                    var end = index + 1;
                    while (end < initial_index_entries.items.len and
                        std.mem.eql(u8, initial_index_entries.items[index].key, initial_index_entries.items[end].key)) : (end += 1)
                    {}
                    const latest = initial_index_entries.items[end - 1];
                    if (!mutations[latest.ordinal].is_delete)
                        try builder.add(latest.key, latest.document_page_id);
                    for (initial_index_entries.items[index..end]) |candidate| {
                        if (candidate.ordinal != latest.ordinal or mutations[latest.ordinal].is_delete) try page_allocator.retire(candidate.document_page_id, .record);
                    }
                    index = end;
                }
                break :index_root try builder.finish();
            } else {
                break :index_root try editor.finish(page_allocator);
            }
        };

        // Migration materializes the legacy map only once. New and already
        // indexed directories write only changed heads, without a global cache.
        var migrated = NamespaceDirectory.empty;
        defer migrated.deinit(self.allocator);
        const heads = if (!namespace_roots.indexed and self.namespace_directory_cache.count() != 0) blk: {
            try migrated.ensureTotalCapacity(self.allocator, self.namespace_directory_cache.count() + changed_heads.count());
            var old = self.namespace_directory_cache.iterator();
            while (old.next()) |entry| migrated.putAssumeCapacity(entry.key_ptr.*, entry.value_ptr.*);
            var changed = changed_heads.iterator();
            while (changed.next()) |entry| migrated.putAssumeCapacity(entry.key_ptr.*, entry.value_ptr.*);
            break :blk &migrated;
        } else &changed_heads;
        const directory = try self.writeNamespaceIndex(page_allocator, previous, namespace_roots, heads);

        // The inline cache is bounded by one page and 32 namespaces. Reserve
        // ownership before publication; updating its heads afterward cannot
        // fail. Ordinary overwrites acquire no new keys or cache allocations.
        var new_entries: [32]struct { key: []u8, head: u64 } = undefined;
        var new_count: usize = 0;
        defer for (new_entries[0..new_count]) |entry| self.allocator.free(entry.key);
        if (!directory.indexed) {
            try self.namespace_directory_cache.ensureTotalCapacity(self.allocator, heads.count());
            var it = heads.iterator();
            while (it.next()) |entry| {
                if (!self.namespace_directory_cache.contains(entry.key_ptr.*)) {
                    new_entries[new_count] = .{ .key = try self.allocator.dupe(u8, entry.key_ptr.*), .head = entry.value_ptr.* };
                    new_count += 1;
                }
            }
        }

        var next = previous;
        next.commit_sequence += 1;
        next.document_root_page = if (self.header.indexed_reclamation) 0 else next_root_page;
        next.namespace_directory_root_page = directory.page;
        next.document_index_root_page = next_index_root_page;
        if (self.transaction_pages == null) next.free_map_root_page = try page_allocator.allocate();
        next.page_count = page_allocator.next_page_id;

        if (self.transaction_pages == null) {
            try page_allocator.flush();
            try self.reserveBareCommitManifestPage(page_allocator);
            try self.persistAllocator(page_allocator, &next);
            try self.publishBareCommit(page_allocator, &next);
        } else {
            try self.publishCheckpoint(next, false, null);
        }
        if (directory.indexed) {
            deinitNamespaceDirectory(self.allocator, &self.namespace_directory_cache);
            self.namespace_directory_cache = .empty;
            self.namespace_directory_cache_root = std.math.maxInt(u64);
        } else {
            var it = changed_heads.iterator();
            while (it.next()) |entry| {
                if (self.namespace_directory_cache.getPtr(entry.key_ptr.*)) |head| head.* = entry.value_ptr.*;
            }
            for (new_entries[0..new_count]) |entry| self.namespace_directory_cache.putAssumeCapacity(entry.key, entry.head);
            new_count = 0;
            self.namespace_directory_cache_root = directory.page;
        }
        self.namespace_directory_delta_depth = 0;
    }

    fn readDocumentIndexNode(self: *NativeFile, page_id: u64, checkpoint: CheckpointSlot) !DocumentIndexNode {
        const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, page_id, .document_index, checkpoint);
        defer self.allocator.free(payload);
        return try self.decodeResolvedDocumentIndexNode(payload, checkpoint);
    }

    fn decodeResolvedDocumentIndexNode(self: *NativeFile, payload: []const u8, checkpoint: CheckpointSlot) !DocumentIndexNode {
        var node = try decodeDocumentIndexNode(self.allocator, payload);
        errdefer node.deinit(self.allocator);
        for (0..node.keys.len) |i| {
            const key = try self.resolveIndexKey(&node, i, checkpoint);
            if (i > 0 and std.mem.order(u8, node.keys[i - 1], key) != .lt) return error.InvalidDocumentIndex;
        }
        return node;
    }

    fn resolveIndexKey(self: *NativeFile, node: *DocumentIndexNode, index: usize, checkpoint: CheckpointSlot) ![]const u8 {
        const page = node.key_pages.?[index];
        if (page == 0 or node.keys[index].len != 0) return node.keys[index];
        const raw = try self.readPageAllocForCheckpoint(self.allocator, page, checkpoint);
        defer self.allocator.free(raw);
        const bytes = switch (raw[4]) {
            @backingInt(PageKind.catalog) => (try decodeCatalogEntry(try decodePagePayload(raw, .catalog))).key,
            @backingInt(PageKind.document) => (try decodeDocumentEntry(try decodePagePayload(raw, .document))).key,
            @backingInt(PageKind.key) => try NativeFile.decodeKey(try decodePagePayload(raw, .key)),
            else => return error.InvalidDocumentIndex,
        };
        if (bytes.len <= index_inline_key_limit) return error.InvalidDocumentIndex;
        const owned = try self.allocator.dupe(u8, bytes);
        self.allocator.free(node.keys[index]);
        node.keys[index] = owned;
        return owned;
    }

    fn writeDocumentIndexNode(self: *NativeFile, page_allocator: *PageAllocator, node: DocumentIndexNode) !u64 {
        if (self.header.indexed_reclamation) try self.materializeIndexKeys(page_allocator, node);
        const encoded = try encodeDocumentIndexNode(self.allocator, node);
        defer self.allocator.free(encoded);
        if (encoded.len > self.maxPagePayloadBytes()) return error.DocumentIndexNodeTooLarge;
        const page_id = try page_allocator.allocate();
        try page_allocator.writePage(page_id, .document_index, encoded);
        return page_id;
    }

    fn putIndexedDocumentBatch(self: *NativeFile, mutations: []const DocumentMutation) !void {
        // Regression: a bare commit here (self.transaction_pages == null,
        // the only branch that reaches publishBareCommit below) builds its
        // real pages directly through this indexed-reclamation path --
        // never through flushTransactionWrites's redo diversion -- so it
        // never stages anything into redo.logical_pending/pending/shared.
        // publishCheckpoint's own preemptive "would this record overflow
        // the log" check (redo.pendingRecordLen() > redo.writer.remaining())
        // is therefore always comparing against this commit's own (empty)
        // staged bytes, never against how full the log already is from
        // *prior* commits -- and its "page-shaped only" fallback branch,
        // finding nothing of this commit's own to flush, is a complete
        // no-op. publishBareCommit's own maybeAutoCheckpointRedoLog call
        // runs too late to help: only *after* publishCheckpoint has
        // already tried (and, once the log is genuinely full, failed) to
        // append this commit's own ride-along marker record
        // (error.LogFull, surfacing as error.OutcomeUnknown). Must run
        // here, before `previous` is captured below: checkpointRedoLog
        // advances the real checkpoint's own commit_sequence, so running
        // it any later -- once `next.commit_sequence = previous
        // .commit_sequence + 1` is fixed relative to a `previous` this
        // call would make stale -- would corrupt that sequencing instead.
        if (self.transaction_pages == null) try self.maybeAutoCheckpointRedoLog();
        const previous = self.activeCheckpoint();
        var local: PageAllocator = undefined;
        if (self.transaction_pages == null) local = try self.pageAllocatorFromFreeMap(previous);
        defer if (self.transaction_pages == null) local.deinit();
        errdefer if (self.transaction_pages == null) self.resetBareCommitManifestWindow();
        const pages = self.transaction_pages orelse &local;
        pages.pack_records = true;
        var editor = IndexEditor.init(self, previous, previous.document_index_root_page);
        defer editor.deinit();
        editor.useSortedBatch(pages, mutations);
        const bulk = previous.document_index_root_page == 0 and mutationKeysSorted(mutations);
        var builder = DocumentIndexBulkBuilder{ .owner = self, .file = self.file, .next_page_id = &pages.next_page_id, .pages = pages };
        defer builder.deinit();
        for (mutations, 0..) |mutation, ordinal| {
            if (bulk and ordinal + 1 < mutations.len and std.mem.eql(u8, mutation.key, mutations[ordinal + 1].key)) continue;
            if (mutation.is_delete) {
                try editor.remove(mutation.key);
                continue;
            }
            var value_root = mutation.external_value_root_page;
            if (value_root == 0 and !self.documentEntryFitsInline(mutation.key, mutation.value)) value_root = try self.writeDocumentValue(pages, mutation.value);
            const record = try pages.writeDocument(.{ .previous_page = 0, .previous_namespace_page = 0, .key = mutation.key, .value = mutation.value, .external_value_root_page = value_root, .external_value_len = mutation.external_value_len });
            if (bulk) try builder.add(mutation.key, record) else try editor.put(mutation.key, record);
        }
        var next = previous;
        next.commit_sequence += 1;
        next.document_root_page = 0;
        next.namespace_directory_root_page = 0;
        next.document_index_root_page = if (bulk) try builder.finish() else try editor.finish(pages);
        next.page_count = pages.next_page_id;
        if (self.transaction_pages == null) {
            next.free_map_root_page = try pages.allocate();
            try self.reserveBareCommitManifestPage(pages);
            try self.persistAllocator(pages, &next);
            try self.publishBareCommit(pages, &next);
        } else {
            try self.publishCheckpoint(next, false, null);
        }
    }

    fn decodeKey(payload: []const u8) ![]const u8 {
        if (payload.len <= 8 or !std.mem.eql(u8, payload[0..8], "AFKEY004")) return error.InvalidDocumentIndex;
        return payload[8..];
    }
    fn materializeIndexKeys(self: *NativeFile, pages: *PageAllocator, node: DocumentIndexNode) !void {
        const references = node.key_pages orelse return error.InvalidDocumentIndex;
        for (references, node.keys) |*reference, key| {
            if (reference.* == 0) continue;
            // Buffered record bundles must be readable before resolving keys.
            try pages.flush();
            var checkpoint = self.activeCheckpoint();
            checkpoint.page_count = pages.next_page_id;
            const raw = try self.readPageAllocForCheckpoint(self.allocator, reference.*, checkpoint);
            defer self.allocator.free(raw);
            if (raw[4] == @backingInt(PageKind.key)) {
                _ = try decodeKey(try decodePagePayload(raw, .key));
                continue;
            }
            const bytes = if (key.len != 0) key else switch (raw[4]) {
                @backingInt(PageKind.document) => (try decodeDocumentEntry(try decodePagePayload(raw, .document))).key,
                @backingInt(PageKind.key) => try NativeFile.decodeKey(try decodePagePayload(raw, .key)),
                @backingInt(PageKind.catalog) => (try decodeCatalogEntry(try decodePagePayload(raw, .catalog))).key,
                else => return error.InvalidDocumentIndex,
            };
            const payload = try self.allocator.alloc(u8, 8 + bytes.len);
            defer self.allocator.free(payload);
            @memcpy(payload[0..8], "AFKEY004");
            @memcpy(payload[8..], bytes);
            const page = try pages.allocate();
            try pages.writePage(page, .key, payload);
            reference.* = page;
        }
    }

    fn upsertDocumentIndex(
        self: *NativeFile,
        page_allocator: *PageAllocator,
        root_page_id: u64,
        key: []const u8,
        document_page_id: u64,
        checkpoint: CheckpointSlot,
    ) !u64 {
        var editor = IndexEditor.init(self, checkpoint, root_page_id);
        editor.accounting_pages = page_allocator;
        defer editor.deinit();
        try editor.put(key, document_page_id);
        return try editor.finish(page_allocator);
    }

    fn lookupDocumentIndexPage(self: *NativeFile, checkpoint: CheckpointSlot, key: []const u8) !?u64 {
        var page_id = checkpoint.document_index_root_page;
        var scratch: [65536]u8 = undefined;
        var view = IndexReadFrame{};
        defer view.deinit(self.allocator);
        var depth: usize = 0;
        while (page_id != 0) : (depth += 1) {
            if (depth > 64) return error.InvalidDocumentIndex;
            if (page_id >= checkpoint.page_count) return error.InvalidPageId;
            if (try self.probeCachedDocumentIndex(page_id, checkpoint, key, &view)) |probe| {
                if (builtin.is_test) _ = self.test_page_reads.fetchAdd(1, .monotonic);
                if (probe.leaf) return probe.page;
                page_id = probe.page orelse return error.InvalidDocumentIndex;
                continue;
            }
            const raw = try decodePagePayload(try self.readPageInto(page_id, checkpoint, &scratch), .document_index);
            const probe = (try self.probeCachedDocumentIndex(page_id, checkpoint, key, &view)) orelse (probeDocumentIndexNode(raw, key) catch |err| switch (err) {
                error.ExternalIndexKey => blk: {
                    try view.decode(self.allocator, raw);
                    const low = try view.bound(self, checkpoint, key, view.kind == .internal);
                    if (view.kind == .leaf) {
                        const matches = low < view.entries().len and std.mem.eql(u8, try view.key(self, checkpoint, low), key);
                        break :blk IndexProbe{ .leaf = true, .page = if (matches) view.pointer(low) else null };
                    }
                    break :blk IndexProbe{ .leaf = false, .page = view.pointer(low) };
                },
                else => return err,
            });
            if (probe.leaf) return probe.page;
            page_id = probe.page orelse return error.InvalidDocumentIndex;
        }
        return null;
    }

    fn probeCachedDocumentIndex(self: *NativeFile, page_id: u64, checkpoint: CheckpointSlot, key: []const u8, scratch: *IndexReadFrame) !?IndexProbe {
        if (!self.page_cache_enabled.load(.monotonic) or self.page_cache_bypass.load(.monotonic) != 0) return null;
        const cached = (try self.page_cache.acquireIndex(self.allocator, page_id)) orelse return null;
        defer self.page_cache.releaseIndex(self.allocator, cached);
        if (builtin.is_test) _ = self.test_index_view_hits.fetchAdd(1, .monotonic);
        // Only the caller's overflow scratch is mutable. The pin protects raw
        // bytes and offsets across eviction, replacement, and recursive reads.
        var view = cached.frame;
        view.overflow = scratch.overflow;
        view.overflow_reference = scratch.overflow_reference;
        view.overflow_key = scratch.overflow_key;
        defer {
            scratch.overflow = view.overflow;
            scratch.overflow_reference = view.overflow_reference;
            scratch.overflow_key = view.overflow_key;
        }
        const low = try view.bound(self, checkpoint, key, view.kind == .internal);
        if (view.kind == .leaf) {
            const matches = low < view.entries().len and std.mem.eql(u8, try view.key(self, checkpoint, low), key);
            return .{ .leaf = true, .page = if (matches) view.pointer(low) else null };
        }
        return .{ .leaf = false, .page = view.pointer(low) };
    }

    /// §9.7c: `indexed` must come from a `CheckpointedTree`/`DocumentIndexEntry`
    /// walk the caller already ran itself (e.g. the fold, vacuum, or
    /// recovery) -- this only materializes the value a raw tree entry
    /// already named, with no key-based overlay lookup of its own (and
    /// none is possible here: by the time a caller has a
    /// `DocumentIndexEntry` in hand, the key-level merge decision --
    /// whether the overlay's own version for this key supersedes the
    /// tree's -- has to have already been made, by whoever produced
    /// `indexed`, not by this function). Non-`pub` and named
    /// `...CheckpointedOnly` so a reader cannot reach for this instead of
    /// `ReadView`/`redoOverlayEntry` and silently skip that merge.
    fn documentValueAtCheckpointedIndexEntryOnlyAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, indexed: DocumentIndexEntry) !?[]u8 {
        const payload = try self.readPagePayloadByKindAllocForCheckpoint(allocator, indexed.document_page_id, .document, checkpoint);
        defer allocator.free(payload);
        const entry = try decodeDocumentEntry(payload);
        if (!std.mem.eql(u8, entry.key, indexed.key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return null;
        return if (entry.external_value_root_page != 0) try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint) else try allocator.dupe(u8, entry.value);
    }

    pub fn getDocumentAlloc(self: *NativeFile, allocator: Allocator, key: []const u8) !?[]u8 {
        const checkpoint = self.activeCheckpoint();
        if (self.stagedEntry(.documents, key)) |entry| {
            if (entry.is_delete) return null;
            return try self.catalogEntryValueAtCheckpointAlloc(allocator, entry, checkpoint);
        }
        return try self.getDocumentAtCheckpointAlloc(allocator, checkpoint, key);
    }

    /// Resolves a key against the ordered index root pinned by `checkpoint`.
    /// Referenced document pages are reclaimed only by vacuum.
    pub fn getDocumentAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, key: []const u8) !?[]u8 {
        if (try self.redoOverlayEntry(.documents, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return null;
            return if (entry.external_value_root_page != 0) try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint) else try allocator.dupe(u8, entry.value);
        }
        const page_id = (try self.lookupDocumentIndexPage(checkpoint, key)) orelse return null;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const payload = try reader.readPayload(self, checkpoint, page_id, 1, .document);
        const entry = try decodeDocumentEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return null;
        return if (entry.external_value_root_page != 0) try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint) else try allocator.dupe(u8, entry.value);
    }

    /// Immutable record identity, meaningful only while the caller retains the
    /// checkpoint's reader pin and the same file incarnation. It names the
    /// document record, not an index leaf that unrelated writes can replace.
    /// External value bytes need not be read to qualify unchanged metadata.
    ///
    /// §9.7c (ReadView)/redo overlay: a key committed-but-not-yet-folded by
    /// `checkpointRedoLog` has no physical document-index page at all yet --
    /// `lookupDocumentIndexPage` alone always reported such a key as absent,
    /// even though a plain `get()` on the same handle found it immediately
    /// (the same overlay-blind-read bug class as `Cursor`'s original merge
    /// and `getDocumentsAtCheckpointWithState`'s pre-pass; see that section's
    /// own "found three times" note -- this caller was a fourth, found via
    /// `PublicationCatalog.verify`'s `valueIdentity`/`valueFingerprint` never
    /// detecting an overlay-only change). Checked first, same as
    /// `getDocumentAtCheckpointAlloc`. An overlay-resident version has no
    /// physical page to name, so it is named by its own redo sequence
    /// instead, with the high bit set (this file's own `packed_record_flag`
    /// convention) so it can never collide with a real, unpacked page id --
    /// still stable and comparable for exactly as long as the caller holds
    /// the pin this checkpoint/mark pair was captured under.
    pub fn documentReferenceAtCheckpoint(self: *NativeFile, checkpoint: CheckpointSlot, key: []const u8) !?u64 {
        if (self.redo) |*redo| {
            if (try redo.shared.resolveAlloc(self.allocator, self.runtimeIo(), @backingInt(TransactionWrites.Root.documents), key, self.readMark(checkpoint))) |resolved| {
                defer self.allocator.free(resolved.value);
                if (resolved.is_delete) return null;
                return packed_record_flag | resolved.sequence;
            }
        }
        return self.lookupDocumentIndexPage(checkpoint, key);
    }

    /// Logical content identity survives physical page reuse. New metadata
    /// records carry the digest in their checksummed record, avoiding payload
    /// hydration; older records use the same digest computed on demand.
    ///
    /// §9.7c/redo overlay: checked first, same as `getDocumentAtCheckpointAlloc`
    /// and for the same reason as `documentReferenceAtCheckpoint` just above --
    /// an uncheckpointed overlay version previously resolved as "unchanged"
    /// here no matter what it actually held, because this function only ever
    /// consulted the real, on-disk tree. The overlay's own `CatalogEntry`
    /// carries no pre-computed digest (unlike an on-disk `DocumentEntry`), so
    /// an overlay hit always hashes its value/external bytes on demand.
    pub fn documentFingerprintAtCheckpoint(self: *NativeFile, checkpoint: CheckpointSlot, key: []const u8) !?[32]u8 {
        if (try self.redoOverlayEntry(.documents, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return null;
            const bytes = if (entry.external_value_root_page != 0)
                try self.readValuePagesAtCheckpointAlloc(self.allocator, entry.external_value_root_page, entry.external_value_len, checkpoint)
            else
                null;
            defer if (bytes) |owned| self.allocator.free(owned);
            var digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(bytes orelse entry.value, &digest, .{});
            return digest;
        }
        const page = (try self.lookupDocumentIndexPage(checkpoint, key)) orelse return null;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const entry = try decodeDocumentEntry(try reader.readPayload(self, checkpoint, page, 1, .document));
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return null;
        if (entry.content_digest) |digest| return digest;
        const bytes = if (entry.external_value_root_page != 0)
            try self.readValuePagesAtCheckpointAlloc(self.allocator, entry.external_value_root_page, entry.external_value_len, checkpoint)
        else
            null;
        defer if (bytes) |owned| self.allocator.free(owned);
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(bytes orelse entry.value, &digest, .{});
        return digest;
    }

    /// Resolve the pinned document once; nearby requested fields share one
    /// extent read and independent spans reuse the same page reader.
    /// §9.7c (ReadView): resolves `ranges` against an overlay entry's own
    /// value directly, instead of a real page -- the overlay-side half
    /// `readDocumentRangesAlloc`/`readDocumentRangesBatchAlloc` were
    /// missing entirely (unlike `getDocumentAtCheckpointAlloc`, they went
    /// straight to the raw tree with no overlay check at all, so a key
    /// logged-but-not-yet-folded by `checkpointRedoLog` always resolved
    /// as not found here even though a plain `get()` on the same handle
    /// found it immediately). Likely root cause of full-text crash-sweep
    /// failures that survived the `Cursor`/`getDocumentsAtCheckpointWithState`
    /// fixes: full-text indexing reads a document's body in ranges,
    /// through exactly this path. Caller owns `entry.value` already.
    fn readDocumentRangesFromOverlayEntry(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, entry: CatalogEntry, ranges: []const @import("../value_ranges.zig").Range, output: [][]const u8) !void {
        if (entry.is_delete) return error.NotFound;
        const size = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        const Context = struct {
            file: *NativeFile,
            a: Allocator,
            checkpoint: CheckpointSlot,
            root: u64,
            size: usize,
            inline_value: []const u8,
            pub fn read(ctx: @This(), begin: usize, len: usize) ![]const u8 {
                if (ctx.root == 0) return ctx.a.dupe(u8, ctx.inline_value[begin..][0..len]);
                return ctx.file.readValuePagesRangeAlloc(ctx.a, ctx.root, ctx.size, begin, len, ctx.checkpoint);
            }
        };
        return @import("../value_ranges.zig").read(size, ranges, output, Context{ .file = self, .a = allocator, .checkpoint = checkpoint, .root = entry.external_value_root_page, .size = size, .inline_value = entry.value });
    }

    pub fn readDocumentRangesAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, key: []const u8, ranges: []const @import("../value_ranges.zig").Range, output: [][]const u8) !void {
        if (ranges.len != output.len or ranges.len > @import("../value_ranges.zig").maximum_ranges) return error.InvalidBatch;
        if (ranges.len == 0) return;
        if (try self.redoOverlayEntry(.documents, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            return self.readDocumentRangesFromOverlayEntry(allocator, checkpoint, entry, ranges, output);
        }
        const page = (try self.lookupDocumentIndexPage(checkpoint, key)) orelse return error.NotFound;
        return self.readDocumentRangesAtPage(allocator, checkpoint, key, page, ranges, output);
    }
    pub fn readDocumentRangesBatchAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, requests: []const @import("../value_ranges.zig").Request) !void {
        if (requests.len > 64) return error.InvalidBatch;
        if (requests.len == 0) return;
        var keys: [64][]const u8 = undefined;
        for (requests, 0..) |request, i| {
            if (request.ranges.len != request.output.len or request.ranges.len > @import("../value_ranges.zig").maximum_ranges) return error.InvalidBatch;
            keys[i] = request.key;
            if (i != 0 and std.mem.order(u8, keys[i - 1], keys[i]) == .gt) return error.InvalidBatch;
        }
        // Same overlay-blind gap as the single-key path above: resolve
        // each request against the overlay first; only requests genuinely
        // absent from it go through the batched tree walk below.
        var remaining: [64]@import("../value_ranges.zig").Request = undefined;
        var remaining_count: usize = 0;
        for (requests) |request| {
            if (try self.redoOverlayEntry(.documents, checkpoint, request.key)) |entry| {
                defer self.allocator.free(entry.value);
                try self.readDocumentRangesFromOverlayEntry(allocator, checkpoint, entry, request.ranges, request.output);
                continue;
            }
            remaining[remaining_count] = request;
            remaining_count += 1;
        }
        if (remaining_count == 0) return;
        const temporary = @import("antfly_platform").allocator.reclaimingScratch(allocator);
        var state: DocumentBatchReadState = .{};
        state.prepare(self);
        defer state.deinit();
        for (remaining[0..remaining_count], 0..) |request, i| keys[i] = request.key;
        const references = try self.resolveBatchReferences(temporary, checkpoint, keys[0..remaining_count], "", &state.path);
        defer temporary.free(references);
        for (remaining[0..remaining_count], references) |request, page| {
            if (page == 0) return error.NotFound;
            try self.readDocumentRangesAtPage(allocator, checkpoint, request.key, page, request.ranges, request.output);
        }
    }
    fn readDocumentRangesAtPage(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, key: []const u8, page: u64, ranges: []const @import("../value_ranges.zig").Range, output: [][]const u8) !void {
        var record: ValuePageReader = undefined;
        record.init();
        defer record.deinit(self);
        const entry = try decodeDocumentEntry(try record.readPayload(self, checkpoint, page, 1, .document));
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return error.NotFound;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const Context = struct {
            file: *NativeFile,
            a: Allocator,
            checkpoint: CheckpointSlot,
            root: u64,
            size: usize,
            inline_value: []const u8,
            reader: *ValuePageReader,
            cursor: *LinkedRangeCursor,
            pub fn read(ctx: @This(), begin: usize, len: usize) ![]const u8 {
                if (ctx.root == 0) return ctx.a.dupe(u8, ctx.inline_value[begin..][0..len]);
                const bytes = try ctx.a.alloc(u8, len);
                errdefer ctx.a.free(bytes);
                try ctx.file.readValuePagesRangeIntoReader(ctx.root, ctx.size, begin, bytes, ctx.checkpoint, ctx.reader, ctx.cursor);
                return bytes;
            }
        };
        var cursor: LinkedRangeCursor = .{};
        const size = if (entry.external_value_root_page == 0) entry.value.len else entry.external_value_len;
        try @import("../value_ranges.zig").read(size, ranges, output, Context{ .file = self, .a = allocator, .checkpoint = checkpoint, .root = entry.external_value_root_page, .size = size, .inline_value = entry.value, .reader = &reader, .cursor = &cursor });
    }

    /// Extents and inline slices are resolved against the caller's checkpoint.
    pub fn readDocumentRangeAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, key: []const u8, offset: u64, length: usize) ![]u8 {
        // §9.7c (ReadView): see `readDocumentRangesAlloc`'s own comment --
        // same overlay-blind gap, same fix.
        if (try self.redoOverlayEntry(.documents, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return error.NotFound;
            const size = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
            if (offset > size or length > size - offset) return error.EndOfStream;
            if (entry.external_value_root_page != 0) return self.readValuePagesRangeAlloc(allocator, entry.external_value_root_page, size, @intCast(offset), length, checkpoint);
            return allocator.dupe(u8, entry.value[@intCast(offset)..][0..length]);
        }
        const page_id = (try self.lookupDocumentIndexPage(checkpoint, key)) orelse return error.NotFound;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const payload = try reader.readPayload(self, checkpoint, page_id, 1, .document);
        const entry = try decodeDocumentEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return error.NotFound;
        const size = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        if (offset > size or length > size - offset) return error.EndOfStream;
        if (entry.external_value_root_page != 0) return self.readValuePagesRangeAlloc(allocator, entry.external_value_root_page, size, @intCast(offset), length, checkpoint);
        return allocator.dupe(u8, entry.value[@intCast(offset)..][0..length]);
    }

    /// Read one document into reusable caller storage. Oversized values are
    /// rejected before loading external pages, and no transaction read cache
    /// retains a copy. Only the initialized prefix of out is returned.
    pub fn readDocumentInto(self: *NativeFile, checkpoint: CheckpointSlot, key: []const u8, out: []u8) ![]const u8 {
        // §9.7c (ReadView): see `readDocumentRangesAlloc`'s own comment --
        // same overlay-blind gap, same fix.
        if (try self.redoOverlayEntry(.documents, checkpoint, key)) |entry| {
            defer self.allocator.free(entry.value);
            if (entry.is_delete) return error.NotFound;
            const length = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
            if (length > out.len) return error.BufferTooSmall;
            if (entry.external_value_root_page != 0) {
                try self.readValuePagesRangeInto(entry.external_value_root_page, length, 0, out[0..length], checkpoint);
            } else {
                @memcpy(out[0..length], entry.value);
            }
            return out[0..length];
        }
        const page_id = (try self.lookupDocumentIndexPage(checkpoint, key)) orelse return error.NotFound;
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        const payload = try reader.readPayload(self, checkpoint, page_id, 1, .document);
        const entry = try decodeDocumentEntry(payload);
        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidDocumentIndex;
        if (entry.is_delete) return error.NotFound;
        const length = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        if (length > out.len) return error.BufferTooSmall;
        if (entry.external_value_root_page != 0) {
            try self.readValuePagesRangeInto(entry.external_value_root_page, length, 0, out[0..length], checkpoint);
        } else {
            @memcpy(out[0..length], entry.value);
        }
        return out[0..length];
    }

    /// Sorted multi-read: decode each visited index node once, and descend
    /// only into children containing requested keys. Each returned value is
    /// independently owned; errors release and clear every output.
    pub fn getDocumentsAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, values: []?[]const u8) !void {
        // Working storage must not be retained in a caller's result arena.
        return self.getDocumentsAtCheckpointWithScratch(allocator, self.allocator, checkpoint, keys, null, values);
    }

    /// Output buffers must not overlap each other or the input keys.
    /// Temporary allocations never escape this call. Caller buffers, when
    /// supplied, own every returned slice; partial output is cleared on errors.
    pub fn getDocumentsAtCheckpointWithScratch(self: *NativeFile, allocator: Allocator, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, buffers: ?[]const []u8, values: []?[]const u8) !void {
        var state = DocumentBatchReadState{};
        defer state.deinit();
        return self.getDocumentsAtCheckpointWithState(allocator, temporary, checkpoint, keys, buffers, values, &state);
    }

    /// Reuse bounded native working storage independently of the result
    /// arena. §9.7c (ReadView): `readBatchAtCheckpoint` now runs its own
    /// overlay pre-pass internally (shared with every score-batch read
    /// too), so this is a thin wrapper again -- the per-site pre-pass
    /// that used to live here (resolving each key's overlay entry
    /// directly, only sending genuinely-absent keys through the real
    /// batch/tree path) has moved down into the one place every batch
    /// read goes through.
    pub fn getDocumentsAtCheckpointWithState(self: *NativeFile, allocator: Allocator, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, buffers: ?[]const []u8, values: []?[]const u8, state: *DocumentBatchReadState) !void {
        return self.readBatchAtCheckpoint(allocator, temporary, checkpoint, keys, buffers, values, @as(?ScoreSink, null), state, null, false);
    }

    /// Fixed-width scores are decoded while the authenticated record is borrowed.
    pub fn getScoresAtCheckpointWithState(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, scores: []?f64, state: *DocumentBatchReadState) !void {
        if (keys.len != scores.len) return error.InvalidBatch;
        @memset(scores, null);
        errdefer @memset(scores, null);
        const Output = struct {
            scores: []?f64,
            fn write(ctx: *anyopaque, index: usize, score: f64) void {
                const out: *@This() = @ptrCast(@alignCast(ctx));
                out.scores[index] = score;
            }
        };
        var output = Output{ .scores = scores };
        return self.visitScoresAtCheckpointWithState(temporary, checkpoint, keys, .{ .context = &output, .write = Output.write }, state);
    }

    pub fn visitScoresAtCheckpointWithState(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, sink: ScoreSink, state: *DocumentBatchReadState) !void {
        return self.readBatchAtCheckpoint(temporary, temporary, checkpoint, keys, null, &.{}, @as(?ScoreSink, sink), state, null, true);
    }

    /// Arbitrary complete batches retain sorted-input validation.
    pub fn readDecodedScoresAtCheckpointWithState(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, values: []f64, state: *DocumentBatchReadState) !void {
        if (keys.len != values.len) return error.InvalidBatch;
        @memset(values, std.math.nan(f64));
        errdefer @memset(values, std.math.nan(f64));
        try self.readBatchAtCheckpoint(temporary, temporary, checkpoint, keys, null, &.{}, @as(?[]f64, values), state, null, true);
    }

    pub fn visitCompleteScoresAtCheckpointWithState(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, sink: CompleteScoreSink, state: *DocumentBatchReadState) !void {
        return self.readBatchAtCheckpoint(temporary, temporary, checkpoint, keys, null, &.{}, @as(?CompleteScoreSink, sink), state, null, true);
    }

    /// Canonical keys come from the owned plan; no caller-supplied validation
    /// flag or identity can bypass input checks. The plan stays immutable during
    /// delivery. Namespace translation preserves its sorted, unique order.
    pub fn visitPreparedScoresAtCheckpointWithState(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, plan: *const @import("../prepared_score_plan.zig").PreparedScorePlan, namespace: []const u8, sink: CompleteScoreSink, state: *DocumentBatchReadState) !void {
        if (!plan.valid or plan.identity == 0) return error.InvalidBatch;
        return self.visitCanonicalScores(temporary, checkpoint, plan.read_keys, plan.identity, plan.retain_decoded, namespace, sink, state);
    }

    pub fn visitOwnedScoresAtCheckpointWithState(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, request: *const @import("../prepared_score_request.zig").PreparedScoreRequest, namespace: []const u8, sink: CompleteScoreSink, state: *DocumentBatchReadState) !void {
        if (request.canonicalIdentity() == 0) return error.InvalidBatch;
        return self.visitCanonicalScores(temporary, checkpoint, request.readKeys(), request.canonicalIdentity(), request.retainDecoded(), namespace, sink, state);
    }

    // This private entry only receives canonical keys proven by an owning plan
    // or request. It is never a caller-supplied sortedness/identity escape hatch.
    fn visitCanonicalScores(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, read_keys: []const []const u8, canonical_identity: u64, retain_decoded: bool, namespace: []const u8, sink: CompleteScoreSink, state: *DocumentBatchReadState) !void {
        // A compiled scan knows it will advance through multiple identities.
        // Reuse required reader scratch without allocating decoded entries that
        // would be displaced before their next use. Restore the independently
        // owned cache pointer before scope cleanup and retention accounting.
        const retained = state.resolved;
        if (!retain_decoded) {
            if (retained) |resolved| {
                resolved.deinit(state.allocator orelse self.allocator);
                resolved.recovered_optional_failure = false;
            }
            state.resolved = null;
        }
        defer state.resolved = retained;
        const identity = ReadIdentity{ .canonical = canonical_identity, .namespace = namespace };
        // §9.7c (ReadView): this used to short-circuit straight to "not
        // found" for every key whenever the physical tree was empty,
        // without ever consulting the overlay -- wrong whenever a
        // graph-metric score document was logged but not yet folded by
        // checkpointRedoLog (the tree can be legitimately empty while
        // the overlay already holds every score this call is for).
        // `readBatchAtCheckpoint` below now has its own overlay-aware
        // version of this same empty-tree case, so there is no need for
        // a second one here; always delegate to it.
        // Owned physical keys and decoded values survive scope detach. A hit
        // needs no namespace reconstruction, record reader, or temporary arena.
        if (state.binding) |binding| if (state.resolved) |resolved| {
            if (self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0 and
                resolved.decoded_ready and resolved.matchesPrepared(binding, checkpoint, identity, read_keys.len))
            {
                resolved.borrowed = true;
                defer resolved.borrowed = false;
                resolved.recovered_optional_failure = false;
                sink.deliverDecoded(resolved.decoded);
                return;
            }
        };
        return self.readBatchAtCheckpoint(temporary, temporary, checkpoint, read_keys, null, &.{}, @as(?CompleteScoreSink, sink), state, identity, true);
    }

    /// §9.7c (ReadView): decode an overlay entry's score the same way
    /// `readBatchRecord`'s own `wants_score` branch decodes a real page's
    /// -- a fixed 8-byte `f64`, inline or through one external-value-chain
    /// read. `null` for a tombstone (consistent with `readBatchRecord`'s
    /// own `entry.is_delete` handling); any other mismatched length is
    /// the same `error.InvalidGraphMetricScore` a real page's own
    /// corruption would raise.
    fn scoreFromCatalogEntry(self: *NativeFile, checkpoint: CheckpointSlot, entry: CatalogEntry) !?f64 {
        if (entry.is_delete) return null;
        const length = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        if (length != 8) return error.InvalidGraphMetricScore;
        var raw: [8]u8 = undefined;
        const score_bytes = if (entry.external_value_root_page != 0) blk: {
            try self.readValuePagesRangeInto(entry.external_value_root_page, 8, 0, &raw, checkpoint);
            break :blk &raw;
        } else entry.value;
        return try decodeScore(score_bytes);
    }

    // Keep record and external-score reads inside the same recovery boundary.
    // Optional capture must be discardable before retrying either allocation.
    inline fn readBatchRecord(self: *NativeFile, state: *DocumentBatchReadState, optional: Allocator, checkpoint: CheckpointSlot, reference: u64, ahead: usize, namespace: []const u8, key: []const u8, comptime wants_score: bool) !struct { entry: DocumentEntry, score: if (wants_score) ?f64 else void } {
        const bytes = try state.reader.readWithWindowAllocators(true, &state.window, self, state.allocator.?, optional, checkpoint, reference, .document, ahead);
        const entry = try decodeDocumentEntry(bytes);
        if (readKeyOrder(entry.key, PrefixedReadKey{ .prefix = namespace, .key = key }) != .eq) return error.InvalidDocumentIndex;
        if (wants_score) {
            if (entry.is_delete) return .{ .entry = entry, .score = null };
            const length = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
            if (length != 8) return error.InvalidGraphMetricScore;
            var raw: [8]u8 = undefined;
            const score_bytes = if (entry.external_value_root_page != 0) blk: {
                try self.readValuePagesRangeInto(entry.external_value_root_page, 8, 0, &raw, checkpoint);
                break :blk &raw;
            } else entry.value;
            return .{ .entry = entry, .score = try decodeScore(score_bytes) };
        }
        return .{ .entry = entry, .score = {} };
    }

    inline fn deliverBatchScore(scores: anytype, index: usize, value: ?f64) void {
        if (comptime @TypeOf(scores) == ?[]f64) {
            scores.?[index] = value orelse std.math.nan(f64);
        } else if (comptime @TypeOf(scores) == ?CompleteScoreSink) {
            scores.?.write(scores.?.context, index, value);
        } else if (value) |score| scores.?.write(scores.?.context, index, score);
    }

    fn readBatchAtCheckpoint(self: *NativeFile, allocator: Allocator, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, buffers: ?[]const []u8, values: []?[]const u8, scores: anytype, state: *DocumentBatchReadState, prepared: ?ReadIdentity, comptime score_reads: bool) !void {
        const direct_span = comptime @TypeOf(scores) == ?[]f64;
        const complete = direct_span or @TypeOf(scores) == ?CompleteScoreSink;
        const namespace = if (prepared) |identity| identity.namespace else "";
        state.prepare(self);
        defer state.reset();
        if (state.resolved) |resolved| resolved.recovered_optional_failure = false;
        if (buffers) |out| if (out.len != keys.len) return error.InvalidBatch;
        if (scores == null and keys.len != values.len) return error.InvalidBatch;
        @memset(values, null);
        if (prepared == null) for (keys, 0..) |key, i| {
            if (i > 0 and std.mem.order(u8, keys[i - 1], key) == .gt) return error.InvalidBatch;
        };
        errdefer {
            if (buffers == null) for (values) |value| if (value) |bytes| allocator.free(bytes);
            @memset(values, null);
        }
        // §9.7c (ReadView): the one overlay-resolution step every batch
        // read this function serves shares -- plain value gets
        // (`getDocumentsAtCheckpointWithState`) and every score-batch
        // variant (`visitScoresAtCheckpointWithState` and siblings)
        // alike. Previously only the value path had its own, separate
        // pre-pass (`getDocumentsAtCheckpointWithState`'s own wrapper,
        // now folded in here and removed there); every score-reading
        // caller went straight to the raw tree walk below with no
        // overlay knowledge at all, so a graph-metric score document
        // logged but not yet folded by `checkpointRedoLog` was
        // invisible to a score-batch read even though a plain `get()`
        // on the same key found it immediately.
        //
        // A key found here is fully resolved and delivered now, then
        // `skip[i]` keeps the tree walk/caching logic below from ever
        // touching it again -- including `resolveBatchReferences`'
        // own (now simply wasted, not wrong) tree lookup for it. This
        // does mean a batch that touches overlay content can never
        // reach `decoded_ready = true` for the score cache (`captured`
        // can never reach `keys.len` while any key is skipped) -- a
        // bounded performance cost, not a correctness one: the cache's
        // own checkpoint-keyed `matches`/`matchesPrepared` check already
        // means a cached, fully-decoded batch can never silently reflect
        // a stale overlay state, since `checkpoint.commit_sequence`
        // advances on every commit, including one that only diverts
        // into the overlay (`NativeFile.committedSequence`'s own doc
        // comment).
        var skip: []bool = &.{};
        defer temporary.free(skip);
        // Cheap, allocation-free out: an empty documents-root overlay
        // (the common case away from a live redo-log write window --
        // nothing uncheckpointed at all) means nothing below could ever
        // match, so skip the per-key lookups and the `skip` array
        // itself entirely. Matters beyond a pure optimization: several
        // memory-budget/OOM-injection tests assert an exact allocation
        // count for this function on a file that happens to have
        // `use_redo_log` on but nothing ever diverted into the overlay
        // during the assertion in question -- this keeps this function
        // allocation-for-allocation identical to before this fix
        // whenever there is genuinely nothing for it to find.
        if (self.redo != null and keys.len != 0 and
            self.redo.?.shared.count(self.runtimeIo(), @backingInt(TransactionWrites.Root.documents)) != 0)
        {
            skip = try temporary.alloc(bool, keys.len);
            @memset(skip, false);
            for (keys, 0..) |key, i| {
                const full_key = if (namespace.len == 0) key else blk: {
                    const buf = try temporary.alloc(u8, namespace.len + key.len);
                    @memcpy(buf[0..namespace.len], namespace);
                    @memcpy(buf[namespace.len..], key);
                    break :blk buf;
                };
                defer if (namespace.len != 0) temporary.free(full_key);
                const entry = (try self.redoOverlayEntry(.documents, checkpoint, full_key)) orelse continue;
                defer self.allocator.free(entry.value);
                skip[i] = true;
                if (comptime score_reads) {
                    const score = try self.scoreFromCatalogEntry(checkpoint, entry);
                    if (score) |s| {
                        deliverBatchScore(scores, i, s);
                    } else if (complete and scores != null) deliverBatchScore(scores, i, null);
                } else if (entry.is_delete) {
                    // values[i] already null from the @memset above.
                } else if (buffers) |out| {
                    const length = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
                    if (length > out[i].len) return error.BufferTooSmall;
                    if (entry.external_value_root_page != 0) {
                        try self.readValuePagesRangeInto(entry.external_value_root_page, length, 0, out[i][0..length], checkpoint);
                    } else @memcpy(out[i][0..length], entry.value);
                    values[i] = out[i][0..length];
                } else {
                    values[i] = if (entry.external_value_root_page != 0)
                        try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint)
                    else
                        try allocator.dupe(u8, entry.value);
                }
            }
        }
        if (keys.len == 0 or checkpoint.document_index_root_page == 0) {
            if (complete and scores != null) for (0..keys.len) |i| {
                if (skip.len == 0 or !skip[i]) deliverBatchScore(scores, i, null);
            };
            return;
        }
        const use_cache = self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0;
        if (!use_cache) if (state.resolved) |resolved| {
            resolved.binding = null;
        };
        var cached = scores != null and state.binding != null and state.resolved != null and use_cache and
            (if (prepared) |identity| state.resolved.?.matchesPrepared(state.binding.?, checkpoint, identity, keys.len) else state.resolved.?.matches(state.binding.?, checkpoint, keys));
        if (cached and state.resolved.?.decoded_ready) {
            state.resolved.?.borrowed = true;
            defer state.resolved.?.borrowed = false;
            if (direct_span) {
                @memcpy(scores.?, state.resolved.?.decoded);
            } else if (complete) {
                scores.?.deliverDecoded(state.resolved.?.decoded);
            } else for (state.resolved.?.decoded, 0..) |score, i| {
                if (!std.math.isNan(score)) scores.?.write(scores.?.context, i, score);
            }
            return;
        }
        const staged = scores != null and prepared != null and state.binding != null and state.resolved != null and use_cache and
            state.resolved.?.compact and state.resolved.?.matchesPrepared(state.binding.?, checkpoint, prepared.?, keys.len);
        if (staged and !state.resolved.?.decoded_ready) cached = false;
        var recovered = false;
        // Release old residency on a miss so resolution keeps the uncached
        // memory floor. Promote offsets only after required reads succeed.
        if (!cached and !staged and scores != null) if (state.resolved) |resolved| {
            resolved.deinit(state.allocator.?);
        };
        // Mandatory growth may evict optional offsets only when not borrowed.
        if (state.resolved) |resolved| resolved.borrowed = cached;
        defer if (state.resolved) |resolved| {
            resolved.borrowed = false;
        };
        var references = if (cached) state.resolved.?.references else self.resolveBatchReferences(temporary, checkpoint, keys, namespace, &state.path) catch |err| retry: {
            if (!staged or (@as(anyerror, err) != error.OutOfMemory and @as(anyerror, err) != error.ResourceBudgetExceeded)) return err;
            state.resolved.?.deinit(state.allocator.?);
            recovered = true;
            break :retry try self.resolveBatchReferences(temporary, checkpoint, keys, namespace, &state.path);
        };
        defer if (!cached) temporary.free(references);
        var order = if (cached) state.resolved.?.order else batchReferenceOrder(temporary, references) catch |err| retry: {
            if (!staged or (@as(anyerror, err) != error.OutOfMemory and @as(anyerror, err) != error.ResourceBudgetExceeded)) return err;
            state.resolved.?.deinit(state.allocator.?);
            recovered = true;
            break :retry try batchReferenceOrder(temporary, references);
        };
        defer if (!cached) {
            if (order) |positions| temporary.free(positions);
        };
        // Resolve required references first, then attempt bounded optional
        // capture. Record and external-value growth can evict it and resume the
        // failed position using these independently owned offsets, without replay.
        if (!cached and scores != null and prepared != null and use_cache and state.binding != null and state.resolved != null) {
            const resolved = state.resolved.?;
            if (!resolved.matchesPrepared(state.binding.?, checkpoint, prepared.?, keys.len)) {
                _ = resolved.rememberPrepared(state.allocator.?, state.binding.?, checkpoint, prepared.?, keys.len);
            }
        }
        var capture = scores != null and state.resolved != null and state.resolved.?.decoded.len == keys.len and
            (cached or (prepared != null and state.binding != null and use_cache and state.resolved.?.matchesPrepared(state.binding.?, checkpoint, prepared.?, keys.len)));
        if (state.resolved) |resolved| resolved.borrowed = cached or capture;
        errdefer if (scores != null) if (state.resolved) |resolved| {
            resolved.decoded_ready = false;
        };
        var captured: usize = 0;
        const reader = &state.reader;
        const window = &state.window;
        const optional_allocator = blk: {
            const candidate = if (state.resolved) |resolved| resolved.promotion_allocator orelse state.allocator.? else state.allocator.?;
            const owner = state.allocator.?;
            // The window is freed by its normal owner, including file changes.
            break :blk if (candidate.ptr == owner.ptr and candidate.vtable.free == owner.vtable.free) candidate else owner;
        };
        var position: usize = 0;
        while (position < keys.len) {
            const i = if (order) |positions| positions[position] else position;
            if (skip.len != 0 and skip[i]) {
                // Already fully resolved and delivered from the overlay
                // above; deliberately never touches `capture`/`captured`
                // (see this function's own overlay-pre-pass comment).
                position += 1;
                continue;
            }
            const reference = references[i];
            if (reference == 0) {
                if (capture) {
                    state.resolved.?.decoded[i] = std.math.nan(f64);
                    captured += 1;
                }
                if (complete and scores != null) deliverBatchScore(scores, i, null);
                position += 1;
                continue;
            }
            const ahead = if (reader.page_id == physicalPage(reference) or window.contains(self, physicalPage(reference))) 1 else recordRunAhead(references, order, position);
            const record = self.readBatchRecord(state, optional_allocator, checkpoint, reference, ahead, namespace, keys[i], score_reads) catch |err| {
                if ((!cached and !capture) or (@as(anyerror, err) != error.OutOfMemory and @as(anyerror, err) != error.ResourceBudgetExceeded)) return err;
                // No borrowed offsets survive their eviction. Resolve again at
                // this same pinned checkpoint and resume the failed position;
                // already delivered scores are never replayed to the sink.
                const resolved = state.resolved.?;
                resolved.borrowed = false;
                resolved.deinit(state.allocator.?);
                capture = false;
                if (!cached) {
                    // Compact staging owns only decoded values. Required
                    // references/order already belong to this read, so retain
                    // them and retry the failed record without resolution or
                    // replaying any deliveries.
                    state.reset();
                    recovered = true;
                    continue;
                }
                cached = false;
                references = &.{};
                order = null;
                state.reset();
                references = try self.resolveBatchReferences(temporary, checkpoint, keys, namespace, &state.path);
                order = try batchReferenceOrder(temporary, references);
                const resumed = if (order) |positions| positions[position] else position;
                if (resumed != i or references[resumed] != reference) return error.InvalidDocumentIndex;
                recovered = true;
                continue;
            };
            const entry = record.entry;
            if (entry.is_delete) {
                if (capture) {
                    state.resolved.?.decoded[i] = std.math.nan(f64);
                    captured += 1;
                }
                if (complete and scores != null) deliverBatchScore(scores, i, null);
                position += 1;
                continue;
            }
            if (comptime score_reads) {
                const score = record.score.?;
                if (capture) {
                    state.resolved.?.decoded[i] = score;
                    captured += 1;
                }
                deliverBatchScore(scores, i, score);
            } else if (buffers) |out| {
                const length = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
                if (length > out[i].len) return error.BufferTooSmall;
                if (entry.external_value_root_page != 0) {
                    try self.readValuePagesRangeInto(entry.external_value_root_page, length, 0, out[i][0..length], checkpoint);
                } else @memcpy(out[i][0..length], entry.value);
                values[i] = out[i][0..length];
            } else values[i] = if (entry.external_value_root_page != 0)
                try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint)
            else
                try allocator.dupe(u8, entry.value);
            position += 1;
        }
        if (capture) state.resolved.?.decoded_ready = captured == keys.len;
        if (!cached and scores != null and state.binding != null and state.resolved != null and use_cache) {
            _ = state.resolved.?.remember(state.allocator.?, state.binding.?, checkpoint, keys, references, order, prepared) catch false;
        }
        if (recovered) state.resolved.?.recovered_optional_failure = true;
    }

    fn resolveBatchReferences(self: *NativeFile, temporary: Allocator, checkpoint: CheckpointSlot, keys: []const []const u8, namespace: []const u8, path: *BatchIndexReadPath) ![]u64 {
        const references = try temporary.alloc(u64, keys.len);
        errdefer temporary.free(references);
        @memset(references, 0);
        if (namespace.len == 0) {
            try self.readDocumentBatchWithPath(checkpoint, checkpoint.document_index_root_page, keys, references, path, 0, {});
        } else {
            try self.readDocumentBatchWithPath(checkpoint, checkpoint.document_index_root_page, keys, references, path, 0, namespace);
        }
        return references;
    }

    fn batchReferenceOrder(temporary: Allocator, references: []const u64) !?[]usize {
        for (references[1..], references[0 .. references.len - 1]) |next, prior| {
            if (recordReferenceLessThan(next, prior)) break;
        } else return null;
        const positions = try temporary.alloc(usize, references.len);
        for (positions, 0..) |*position, i| position.* = i;
        std.mem.sort(usize, positions, references, struct {
            fn less(refs: []const u64, lhs: usize, rhs: usize) bool {
                return if (refs[lhs] == refs[rhs]) lhs < rhs else recordReferenceLessThan(refs[lhs], refs[rhs]);
            }
        }.less);
        return positions;
    }

    fn readDocumentBatchNode(self: *NativeFile, checkpoint: CheckpointSlot, page: u64, keys: []const []const u8, references: []u64) !void {
        var path = IndexReadPath{};
        defer path.deinit(self.allocator);
        try self.readDocumentBatchWithPath(checkpoint, page, keys, references, &path, 0, {});
    }

    fn readDocumentBatchWithPath(self: *NativeFile, checkpoint: CheckpointSlot, page: u64, keys: []const []const u8, references: []u64, path: anytype, depth: usize, namespace: anytype) !void {
        const node = if (comptime @TypeOf(path.*) == BatchIndexReadPath) try path.loadMode(self, checkpoint, depth, page, true) else try path.load(self, checkpoint, depth, page);
        var group_start: usize = 0;
        var group_child: usize = 0;
        var previous_bound: usize = 0;
        for (keys, 0..) |key, i| {
            const wanted = if (comptime @TypeOf(namespace) == void) key else PrefixedReadKey{ .prefix = namespace, .key = key };
            const low = if (i == 0) try node.bound(self, checkpoint, wanted, node.kind == .internal) else try node.boundFrom(self, checkpoint, wanted, node.kind == .internal, previous_bound);
            previous_bound = low;
            if (node.kind == .leaf) {
                if (low < node.entries().len and readKeyOrder(try node.key(self, checkpoint, low), wanted) == .eq) references[i] = node.pointer(low);
            } else {
                if (i > 0 and low != group_child) {
                    try self.readDocumentBatchWithPath(checkpoint, node.pointer(group_child), keys[group_start..i], references[group_start..i], path, depth + 1, namespace);
                    group_start = i;
                }
                group_child = low;
            }
        }
        if (node.kind == .internal) try self.readDocumentBatchWithPath(checkpoint, node.pointer(group_child), keys[group_start..], references[group_start..], path, depth + 1, namespace);
    }

    /// Existence query over live record metadata, never document values. Skip
    /// the excluded key range in one seek; document indexes retain tombstones,
    /// so an index entry alone is not proof that a live document exists.
    pub fn hasLiveDocumentOutsidePrefix(self: *NativeFile, checkpoint: CheckpointSlot, excluded_prefix: []const u8) !bool {
        if (excluded_prefix.len == 0) return false;
        var cursor = CheckpointedTree.init(self, checkpoint);
        defer cursor.deinit();
        var records = RecordPageReader{};
        defer records.deinit(self.allocator);
        var current = try cursor.first();
        while (current) |indexed| {
            var owned = indexed;
            defer owned.deinit(self.allocator);
            if (std.mem.startsWith(u8, owned.key, excluded_prefix)) {
                const successor = try self.allocator.dupe(u8, excluded_prefix);
                defer self.allocator.free(successor);
                var end = successor.len;
                while (end > 0 and successor[end - 1] == 0xff) end -= 1;
                if (end == 0) return false;
                successor[end - 1] += 1;
                current = try cursor.seekAtOrAfter(successor[0..end], false);
                continue;
            }
            // §9.3a revised: the overlay, not the on-disk record, is
            // authoritative for this key's liveness whenever it has a
            // mutation for it -- a newer delete must not be masked by a
            // stale live on-disk entry, and a newer (re-)put must not be
            // masked by a stale on-disk tombstone.
            if (try self.redoOverlayEntry(.documents, checkpoint, owned.key)) |overlay_entry| {
                defer self.allocator.free(overlay_entry.value);
                if (!overlay_entry.is_delete) return true;
                current = try cursor.next();
                continue;
            }
            const entry = try decodeDocumentEntry(try records.read(self, self.allocator, checkpoint, owned.document_page_id, .document));
            if (!std.mem.eql(u8, entry.key, owned.key)) return error.InvalidDocumentIndex;
            if (!entry.is_delete) return true;
            current = try cursor.next();
        }
        // The tree has no live record outside the prefix. The overlay
        // might still have one: a document inserted (or moved outside the
        // prefix) since the last checkpoint, never yet reflected in the
        // tree at all, so the scan above never visited its key.
        //
        // §9.7c (ReadView): this used to gate the check below on
        // `checkpoint.commit_sequence == self.activeCheckpoint().commit_sequence`
        // and, when that held, resolve at `checkpoint.commit_sequence`
        // directly -- the exact same overlay-blind-scan anti-pattern
        // `OverlayScanState.initForPrefix`'s own removed "must equal the
        // live checkpoint exactly" gate had: a caller reached through a
        // `ReadGeneration`'s separately-opened `generation.file` (this
        // function's `self`) passes a tracked, genuinely current
        // `checkpoint` (`Txn.checkpoint`, kept current by
        // `Store.observeReadCheckpoint`) that almost never equals
        // `generation.file`'s own frozen, never-refreshed
        // `activeCheckpoint()` -- so the guard failed on nearly every real
        // call (`Store.hasLiveDocumentOutsidePrefix` always opens a fresh
        // `Txn` this way), silently skipping the overlay fallback and
        // returning `false` even when a document committed after this
        // `generation.file` was opened -- and never yet folded into the
        // physical tree -- made the real answer `true`. `readMark`
        // already resolves this exact (C, M) split correctly in one
        // place (`redoOverlayEntry`'s own primitive); call it unconditionally
        // instead of re-deriving the same guard here.
        if (self.redo) |*redo| {
            if (redo.shared.hasLiveKeyOutsidePrefix(self.runtimeIo(), @backingInt(TransactionWrites.Root.documents), self.readMark(checkpoint), excluded_prefix)) return true;
        }
        return false;
    }

    pub fn snapshotDocumentsAlloc(self: *NativeFile, allocator: Allocator) ![]OwnedDocument {
        return try self.snapshotDocumentsWithPrefixAlloc(allocator, "");
    }

    /// Materializes live documents in key order from the pinned index. Prefix
    /// seeks skip unrelated keys; historical versions never enter the scan.
    pub fn snapshotDocumentsWithPrefixAlloc(self: *NativeFile, allocator: Allocator, prefix: []const u8) ![]OwnedDocument {
        return try self.snapshotDocumentsWithPrefixAtCheckpointAlloc(allocator, prefix, try self.materializeTransactionCheckpoint());
    }

    fn snapshotDocumentsWithPrefixAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, prefix: []const u8, checkpoint: CheckpointSlot) ![]OwnedDocument {
        var docs = std.ArrayListUnmanaged(OwnedDocument).empty;
        errdefer {
            for (docs.items) |doc| {
                allocator.free(doc.key);
                allocator.free(doc.value);
            }
            docs.deinit(allocator);
        }
        var references = std.ArrayListUnmanaged(u64).empty;
        defer references.deinit(self.allocator);
        var cursor = CheckpointedTree.initWithKeyAllocator(self, checkpoint, allocator);
        defer cursor.deinit();
        // §9.3a revised: merge the redo-log logical_overlay's own
        // uncheckpointed document mutations into this scan, in key order,
        // the same way a point `getDocumentAtCheckpointAlloc` already
        // does. `overlay_live_sentinel` marks a result already fully
        // materialized from the overlay (no page to read for it), kept
        // through the later tombstone-compaction filter below (which
        // already treats a *real* `0` reference as "drop this one") but
        // skipped by the batch-read loop that follows it.
        const overlay_live_sentinel = std.math.maxInt(u64);
        var overlay = try OverlayScanState.initForPrefix(self.allocator, self, .documents, checkpoint, prefix);
        defer overlay.deinit();
        var pending_tree: ?DocumentIndexEntry = if (prefix.len == 0) try cursor.first() else try cursor.seekAtOrAfter(prefix, false);
        errdefer if (pending_tree) |*p| p.deinit(allocator);
        while (true) {
            if (pending_tree != null and !std.mem.startsWith(u8, pending_tree.?.key, prefix)) {
                // Past the prefix on the tree side; sorted, so nothing
                // later from the tree can match either. Any remaining
                // overlay keys were already filtered to the prefix at
                // construction, so the loop below still finds them.
                var owned = pending_tree.?;
                owned.deinit(allocator);
                pending_tree = null;
            }
            const overlay_key = try overlay.peek();
            const tree_key: ?[]const u8 = if (pending_tree) |t| t.key else null;
            const take_overlay = overlay_key != null and (tree_key == null or std.mem.order(u8, overlay_key.?, tree_key.?) != .gt);
            if (take_overlay) {
                const key = overlay_key.?;
                const entry = (try self.redoOverlayEntry(.documents, checkpoint, key)) orelse return error.InvalidNativeRedoRecord;
                defer self.allocator.free(entry.value);
                if (tree_key != null and std.mem.eql(u8, tree_key.?, key)) {
                    var owned = pending_tree.?;
                    owned.deinit(allocator);
                    // Null out pending_tree itself (not just the local copy)
                    // before calling cursor.next(): the top errdefer reads
                    // the real pending_tree variable, so if cursor.next()
                    // fails below, it must not see the just-freed key again.
                    pending_tree = null;
                    pending_tree = try cursor.next();
                }
                _ = try overlay.takeFront();
                if (!entry.is_delete) {
                    const value = if (entry.external_value_root_page != 0)
                        try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint)
                    else
                        try allocator.dupe(u8, entry.value);
                    errdefer allocator.free(value);
                    const owned_key = try allocator.dupe(u8, key);
                    errdefer allocator.free(owned_key);
                    try docs.ensureUnusedCapacity(allocator, 1);
                    try references.ensureUnusedCapacity(self.allocator, 1);
                    docs.appendAssumeCapacity(.{ .key = owned_key, .value = value });
                    references.appendAssumeCapacity(overlay_live_sentinel);
                }
                continue;
            }
            const indexed = pending_tree orelse break;
            try docs.ensureUnusedCapacity(allocator, 1);
            try references.ensureUnusedCapacity(self.allocator, 1);
            docs.appendAssumeCapacity(.{ .key = indexed.key, .value = &.{} });
            references.appendAssumeCapacity(indexed.document_page_id);
            // Transfer ownership of the key into docs.items *before* calling
            // cursor.next(): pending_tree (not the local `indexed` copy) is
            // what the top errdefer at this function's entry points at, so
            // if cursor.next() fails below, pending_tree must no longer
            // reference a key docs.items already owns -- otherwise both
            // errdefers free the same allocation.
            if (pending_tree) |*p| p.key = &.{};
            pending_tree = try cursor.next();
        }
        // Materialization already retains every result. One reference per live
        // index entry lets us read each packed record page once, even after
        // scattered updates. Sort the owned results back into key order below.
        const PhysicalOrder = struct {
            docs: []OwnedDocument,
            references: []u64,
            pub fn lessThan(ctx: @This(), a: usize, b: usize) bool {
                return recordReferenceLessThan(ctx.references[a], ctx.references[b]);
            }
            pub fn swap(ctx: @This(), a: usize, b: usize) void {
                std.mem.swap(OwnedDocument, &ctx.docs[a], &ctx.docs[b]);
                std.mem.swap(u64, &ctx.references[a], &ctx.references[b]);
            }
        };
        std.sort.pdqContext(0, docs.items.len, PhysicalOrder{ .docs = docs.items, .references = references.items });
        var records = RecordPageReader{};
        defer records.deinit(self.allocator);
        var window = RecordReadWindow{};
        defer window.deinit(self.allocator);
        for (docs.items, references.items, 0..) |*doc, *reference, position| {
            // Already fully materialized from the overlay above -- no
            // page to read, nothing to decode.
            if (reference.* == std.math.maxInt(u64)) continue;
            const ahead = if (records.page_id == physicalPage(reference.*) or window.contains(self, physicalPage(reference.*))) 1 else recordRunAhead(references.items, null, position);
            const entry = try decodeDocumentEntry(try records.readWithWindow(true, &window, self, self.allocator, checkpoint, reference.*, .document, ahead));
            if (!std.mem.eql(u8, entry.key, doc.key)) return error.InvalidDocumentIndex;
            if (entry.is_delete) {
                // Legacy revision-3 indexes may retain their latest tombstones.
                allocator.free(doc.key);
                doc.key = &.{};
                reference.* = 0;
                continue;
            }
            doc.value = if (entry.external_value_root_page != 0)
                try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint)
            else
                try allocator.dupe(u8, entry.value);
        }
        var live: usize = 0;
        for (docs.items, references.items) |doc, reference| {
            if (reference == 0) continue;
            docs.items[live] = doc;
            live += 1;
        }
        docs.items.len = live;
        std.mem.sort(OwnedDocument, docs.items, {}, struct {
            fn lessThan(_: void, a: OwnedDocument, b: OwnedDocument) bool {
                return std.mem.lessThan(u8, a.key, b.key);
            }
        }.lessThan);
        return try docs.toOwnedSlice(allocator);
    }

    pub fn freeSnapshotDocuments(allocator: Allocator, docs: []OwnedDocument) void {
        for (docs) |doc| {
            allocator.free(doc.key);
            allocator.free(doc.value);
        }
        allocator.free(docs);
    }

    /// Immutable page window. Extents supply proven contiguous leaf runs;
    /// linked chains grow read-ahead only while physical adjacency persists.
    /// Admit requested pages according to policy, never speculative neighbors.
    const ValuePageReader = struct {
        bytes: [64 * 1024]u8 = undefined,
        lease: ?*PageCache.RawView = null,
        first: u64 = 0,
        count: usize = 0,
        admitted: u16 = 0,
        chain_previous: u64 = 0,
        chain_run: usize = 0,
        /// Cold artifact export keeps navigation hot without admitting payloads.
        cache_payload: bool = true,

        fn init(self: *@This()) void {
            // Initialize control state in place: copying a default aggregate
            // also copies its 64 KiB undefined scratch in optimized builds.
            self.lease = null;
            self.first = 0;
            self.count = 0;
            self.admitted = 0;
            self.chain_previous = 0;
            self.chain_run = 0;
            self.cache_payload = true;
        }

        fn deinit(self: *@This(), file: *NativeFile) void {
            if (self.lease) |lease| file.page_cache.releaseRaw(file.allocator, lease);
            self.lease = null;
            self.count = 0;
            self.admitted = 0;
        }

        fn requested(self: *@This(), file: *NativeFile, index: usize) []const u8 {
            const size: usize = file.header.page_size;
            const page = self.bytes[index * size ..][0..size];
            const bit = @as(u16, 1) << @as(u4, @intCast(index));
            if (self.admitted & bit == 0 and file.page_cache_enabled.load(.monotonic) and
                file.page_cache_bypass.load(.monotonic) == 0 and
                (self.cache_payload or page[4] != @backingInt(PageKind.value)) and file.admitPageToCache(page))
            {
                file.page_cache.put(file.allocator, self.first + index, page);
                self.admitted |= bit;
            }
            return page;
        }

        pub fn read(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, page: u64, ahead: usize) ![]const u8 {
            if (page == 0 or page >= checkpoint.page_count) return error.InvalidPageId;
            if (builtin.is_test) _ = file.test_page_reads.fetchAdd(1, .monotonic);
            const size: usize = file.header.page_size;
            if (page >= self.first and page - self.first < self.count)
                return if (self.lease) |lease| lease.bytes else self.requested(file, @intCast(page - self.first));
            self.deinit(file);
            const use_cache = file.page_cache_enabled.load(.monotonic) and file.page_cache_bypass.load(.monotonic) == 0;
            if (use_cache) {
                if (try file.page_cache.acquirePayload(file.allocator, page, size)) |lease| {
                    self.lease = lease;
                    self.first = page;
                    self.count = 1;
                    self.admitted = 1;
                    if (builtin.is_test) _ = file.test_value_cache_borrowed_bytes.fetchAdd(size, .monotonic);
                    return lease.bytes;
                }
            }
            if (use_cache and file.page_cache.copyInto(page, self.bytes[0..size])) {
                if (builtin.is_test) _ = file.test_value_cache_copy_bytes.fetchAdd(size, .monotonic);
                self.first = page;
                self.count = 1;
                self.admitted = 1;
                return self.bytes[0..size];
            }
            const count: usize = @intCast(@min(@max(ahead, 1), self.bytes.len / size, checkpoint.page_count - page));
            if (builtin.is_test) {
                _ = file.test_value_read_calls.fetchAdd(1, .monotonic);
                _ = file.test_value_read_bytes.fetchAdd(count * size, .monotonic);
            }
            try file.readBackingPages(self.bytes[0 .. count * size], page * size);
            self.first = page;
            self.count = count;
            return self.requested(file, 0);
        }

        fn payload(self: *const @This(), raw: []const u8, expected: PageKind) ![]const u8 {
            if (self.lease) |lease| {
                if (raw.ptr == lease.bytes.ptr and raw.len == lease.bytes.len) {
                    const validation = lease.validation.?;
                    if (validation.kind != expected) return error.UnexpectedNativePageKind;
                    return raw[page_header_size..][0..validation.payload_len];
                }
            }
            return decodePagePayload(raw, expected);
        }

        /// Packed references borrow the authenticated bundle directly rather
        /// than copying it into a synthetic, newly checksummed record page.
        fn readPayload(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, reference: u64, ahead: usize, expected: PageKind) ![]const u8 {
            const raw = try self.read(file, checkpoint, physicalPage(reference), ahead);
            if (reference & packed_record_flag != 0) {
                const bundle = try self.payload(raw, .record_bundle);
                const record = if (self.lease) |lease| try lease.packedRecord(reference) else try packedRecordPayload(bundle, reference);
                if (record.kind != expected) return error.UnexpectedNativePageKind;
                return record.bytes;
            }
            return self.payload(raw, expected);
        }

        fn extentNode(self: *const @This(), bytes: []const u8, expected_len: u64) !ExtentNode {
            if (self.lease) |lease| {
                if (lease.extent_entries) |entries| {
                    if (bytes.ptr == lease.bytes[page_header_size..].ptr) {
                        if (lease.extent_length != expected_len) return error.InvalidNativeValueChain;
                        var node = ExtentNode{ .height = lease.extent_height, .count = entries.len };
                        var previous: u64 = 0;
                        for (entries, node.children[0..entries.len]) |entry, *child| {
                            child.* = .{ .page = entry.page, .len = entry.end - previous, .height = lease.extent_height - 1 };
                            previous = entry.end;
                        }
                        return node;
                    }
                }
            }
            return decodeExtentNode(bytes, expected_len);
        }

        fn extentStart(self: *const @This(), start: u64) struct { index: usize = 0, offset: u64 = 0 } {
            const lease = self.lease orelse return .{};
            const entries = lease.extent_entries orelse return .{};
            var lo: usize = 0;
            var hi = entries.len;
            while (lo < hi) {
                const mid = lo + (hi - lo) / 2;
                if (entries[mid].end <= start) lo = mid + 1 else hi = mid;
            }
            return .{ .index = lo, .offset = if (lo == 0) 0 else entries[lo - 1].end };
        }

        fn readChain(self: *@This(), file: *NativeFile, checkpoint: CheckpointSlot, page: u64, remaining: usize) ![]const u8 {
            self.chain_run = if (self.chain_previous != 0 and page > self.chain_previous and page - self.chain_previous == 1) @min(16, self.chain_run + 1) else 1;
            self.chain_previous = page;
            const needed = 1 + (remaining -| 1) / file.maxValuePagePayloadBytes();
            return self.read(file, checkpoint, page, @min(self.chain_run, needed));
        }
    };

    // The parent already owns these references. Bound prefetch by both
    // physical adjacency and the requested logical range, without allocating
    // a separate run list or reading unrelated pages between fragments.
    fn extentLeafReadAhead(children: []const ExtentRef, index: usize, remaining: u64) usize {
        var count: usize = 1;
        var covered = children[index].len;
        while (count < 16 and index + count < children.len and covered < remaining) : (count += 1) {
            const next = children[index + count];
            if (next.height != 0 or next.page <= children[index].page or next.page - children[index].page != count) break;
            covered += next.len;
        }
        return count;
    }

    /// Sequential, checksum-checked reader for both extent trees and document
    /// value chains. Holds one page and one extent node per tree level.
    const ValueChunkCursor = struct {
        const Frame = struct {
            lease: ?*PageCache.RawView = null,
            node: ExtentNode = undefined,
            position: usize = 0,

            fn count(self: *const Frame) usize {
                return if (self.lease) |owner| owner.extent_entries.?.len else self.node.count;
            }

            fn child(self: *const Frame, index: usize) ExtentRef {
                if (self.lease) |owner| {
                    const entries = owner.extent_entries.?;
                    const start = if (index == 0) 0 else entries[index - 1].end;
                    return .{ .page = entries[index].page, .len = entries[index].end - start, .height = owner.extent_height - 1 };
                }
                return self.node.children[index];
            }

            fn readAhead(self: *const Frame, index: usize, remaining: u64) usize {
                const first = self.child(index);
                var covered = first.len;
                var count_: usize = 1;
                while (count_ < 16 and index + count_ < self.count() and covered < remaining) : (count_ += 1) {
                    const next_ = self.child(index + count_);
                    if (next_.height != 0 or next_.page <= first.page or next_.page - first.page != count_) break;
                    covered += next_.len;
                }
                return count_;
            }
        };
        file: *NativeFile,
        checkpoint: CheckpointSlot,
        // Four levels cover ordinary artifact trees without allocator traffic.
        // The format permits at most 63 levels; deeper trees use one exact,
        // bounded overflow allocation, reused for the entire traversal.
        frames: std.ArrayListUnmanaged(Frame) = .empty,
        inline_frames: [4]Frame = undefined,
        frame_count: usize = 0,
        max_depth: usize = 0,
        pending: ?ExtentRef,
        chain_page: u64,
        // Only offsets/lengths survive a returned cursor's stack relocation.
        initial_leaf: ?struct { next_page: u64, len: usize } = null,
        remaining: usize,
        value_length: usize = 0,
        read_end: ?usize = null,
        skip: usize = 0,
        reader: ValuePageReader = .{},

        fn init(file: *NativeFile, root: u64, len: usize) !ValueChunkCursor {
            return initAtCheckpoint(file, root, len, file.activeCheckpoint());
        }

        fn initAtCheckpoint(file: *NativeFile, root: u64, len: usize, checkpoint: CheckpointSlot) !ValueChunkCursor {
            if (len == 0) return error.InvalidNativeValueChain;
            return initWithCacheIntent(file, root, len, checkpoint, true);
        }

        fn initWithCacheIntent(file: *NativeFile, root: u64, len: usize, checkpoint: CheckpointSlot, cache_payload: bool) !ValueChunkCursor {
            var cursor: ValueChunkCursor = undefined;
            try cursor.initInto(file, root, len, checkpoint, cache_payload);
            return cursor;
        }

        // Initialize control state directly in caller storage. Returning this
        // aggregate by value can copy its large, uninitialized page scratch.
        fn initInto(cursor: *ValueChunkCursor, file: *NativeFile, root: u64, len: usize, checkpoint: CheckpointSlot, cache_payload: bool) !void {
            if (len == 0) return error.InvalidNativeValueChain;
            cursor.file = file;
            cursor.checkpoint = checkpoint;
            cursor.frames = .empty;
            cursor.frame_count = 0;
            cursor.max_depth = 0;
            cursor.pending = null;
            cursor.chain_page = root;
            cursor.initial_leaf = null;
            cursor.remaining = len;
            cursor.value_length = len;
            cursor.read_end = null;
            cursor.skip = 0;
            cursor.reader.init();
            cursor.reader.cache_payload = cache_payload;
            errdefer cursor.deinit();
            const raw = try cursor.reader.read(file, checkpoint, root, 1);
            if (raw[4] == @backingInt(PageKind.value_extent)) {
                try cursor.pushPayload(try cursor.reader.payload(raw, .value_extent), len, null);
                cursor.chain_page = 0;
            } else {
                const leaf = try decodeValuePage(try cursor.reader.payload(raw, .value));
                if (leaf.next_page == 0) {
                    if (leaf.chunk.len != len) return error.InvalidNativeValueChain;
                }
                cursor.initial_leaf = .{ .next_page = leaf.next_page, .len = leaf.chunk.len };
                cursor.reader.chain_previous = root;
                cursor.reader.chain_run = 1;
            }
        }

        fn readAheadRemaining(self: *const ValueChunkCursor) usize {
            const position = self.value_length - self.remaining;
            return @min(self.remaining, (self.read_end orelse self.value_length) -| position);
        }

        fn frameSlice(self: *ValueChunkCursor) []Frame {
            return if (self.frames.capacity != 0) self.frames.items else self.inline_frames[0..self.frame_count];
        }

        fn pushPayload(self: *ValueChunkCursor, payload: []const u8, len: u64, height: ?u8) !void {
            if (self.reader.lease) |owner| if (owner.extent_entries != null) {
                if (owner.extent_length != len or (height != null and owner.extent_height != height.?)) return error.InvalidNativeValueChain;
                if (height == null) self.max_depth = owner.extent_height;
                // Reserve before acquiring an extra pin; allocation failures
                // leave both the reader's lease and the frame stack unchanged.
                const frame = try self.reserveFrame();
                _ = owner.references.fetchAdd(1, .monotonic);
                frame.lease = owner;
                frame.position = 0;
                return;
            };
            const node = try decodeExtentNode(payload, len);
            if (height) |expected| {
                if (node.height != expected) return error.InvalidNativeValueChain;
            } else self.max_depth = node.height;
            try self.pushFrame(node);
        }

        fn reserveFrame(self: *ValueChunkCursor) !*Frame {
            if (self.frame_count >= self.max_depth) return error.InvalidNativeValueChain;
            if (self.frames.capacity == 0 and self.frame_count >= self.inline_frames.len) {
                try self.frames.ensureTotalCapacityPrecise(self.file.allocator, self.max_depth);
                // Transfer the frame pins, copying only active owned nodes.
                for (self.inline_frames[0..self.frame_count]) |*source| {
                    const dest = self.frames.addOneAssumeCapacity();
                    dest.lease = source.lease;
                    dest.position = source.position;
                    if (source.lease == null) dest.node = source.node;
                }
            }
            const frame = if (self.frames.capacity == 0) &self.inline_frames[self.frame_count] else self.frames.addOneAssumeCapacity();
            self.frame_count += 1;
            return frame;
        }

        fn pushFrame(self: *ValueChunkCursor, node: ExtentNode) !void {
            const frame = try self.reserveFrame();
            frame.lease = null;
            frame.node = node;
            frame.position = 0;
        }

        fn popFrame(self: *ValueChunkCursor) void {
            const frame = &self.frameSlice()[self.frame_count - 1];
            if (frame.lease) |owner| self.file.page_cache.releaseRaw(self.file.allocator, owner);
            self.frame_count -= 1;
            if (self.frames.capacity != 0) self.frames.items.len = self.frame_count;
        }

        pub fn deinit(self: *ValueChunkCursor) void {
            while (self.frame_count != 0) self.popFrame();
            self.reader.deinit(self.file);
            self.frames.deinit(self.file.allocator);
        }

        /// The returned slice is borrowed until next(). Cancellation is checked
        /// on every page, including internal nodes of large extent trees.
        fn next(self: *ValueChunkCursor, cancel: ?*const maintenance.CancelToken) !?[]const u8 {
            while (true) {
                if (cancel) |token| try token.check();
                if (self.chain_page != 0) {
                    const value: ValuePage = if (self.initial_leaf) |first| blk: {
                        self.initial_leaf = null;
                        const raw = if (self.reader.lease) |lease| lease.bytes else self.reader.bytes[0..self.file.header.page_size];
                        break :blk .{ .next_page = first.next_page, .chunk = raw[page_header_size + value_page_header_size ..][0..first.len] };
                    } else try decodeValuePage(try self.reader.payload(try self.reader.readChain(self.file, self.checkpoint, self.chain_page, self.readAheadRemaining()), .value));
                    if (value.chunk.len == 0 or value.chunk.len > self.remaining) return error.InvalidNativeValueChain;
                    self.remaining -= value.chunk.len;
                    if ((self.remaining == 0) != (value.next_page == 0)) return error.InvalidNativeValueChain;
                    self.chain_page = value.next_page;
                    const skipped = @min(self.skip, value.chunk.len);
                    self.skip -= skipped;
                    if (skipped == value.chunk.len) continue;
                    return value.chunk[skipped..];
                }
                const ref = self.pending orelse blk: {
                    while (self.frame_count > 0) {
                        const frame = &self.frameSlice()[self.frame_count - 1];
                        if (frame.position == frame.count()) {
                            self.popFrame();
                            continue;
                        }
                        const child = frame.child(frame.position);
                        frame.position += 1;
                        break :blk child;
                    }
                    if (self.remaining != 0) return error.InvalidNativeValueChain;
                    return null;
                };
                self.pending = null;
                if (self.skip >= ref.len) {
                    if (ref.len > self.remaining) return error.InvalidNativeValueChain;
                    self.skip -= ref.len;
                    self.remaining -= ref.len;
                    continue;
                }
                const ahead = if (ref.height == 0 and self.frame_count != 0) blk: {
                    const frame = &self.frameSlice()[self.frame_count - 1];
                    break :blk frame.readAhead(frame.position - 1, self.readAheadRemaining());
                } else 1;
                const raw = try self.reader.read(self.file, self.checkpoint, ref.page, ahead);
                if (ref.height != 0) {
                    try self.pushPayload(try self.reader.payload(raw, .value_extent), ref.len, ref.height);
                    continue;
                }
                const value = try decodeValuePage(try self.reader.payload(raw, .value));
                if (value.next_page != 0 or value.chunk.len == 0 or value.chunk.len != ref.len or value.chunk.len > self.remaining)
                    return error.InvalidNativeValueChain;
                self.remaining -= value.chunk.len;
                const skipped = self.skip;
                self.skip = 0;
                return value.chunk[skipped..];
            }
        }
    };

    /// Repack arbitrary source chunk boundaries into full output pages. Catalog
    /// values use the bounded extent frontier; large documents do too.
    fn copyExternalValue(self: *NativeFile, file: std.Io.File, next_page: *u64, root: u64, len: usize, tree: bool, cancel: ?*const maintenance.CancelToken, tracking: ?*PageAllocator) !u64 {
        var source: ValueChunkCursor = undefined;
        try source.initInto(self, root, len, self.activeCheckpoint(), true);
        defer source.deinit();
        var writer = NativeFile{
            .allocator = self.allocator,
            .io_impl = undefined,
            .borrowed_io = self.runtimeIo(),
            .path = @constCast(""),
            .file = file,
            .header = .{ .page_size = self.header.page_size },
            .no_sync = true,
            .page_cache_enabled = .init(false),
            .max_file_bytes = self.vacuum_workspace_limit,
        };
        // `writer` targets a disposable vacuum/copy workspace file, never
        // goes through `beginTransaction`/`commitTransaction`/`close()`, and
        // is abandoned once this function returns. Its page writes still run
        // through the ordinary `PageWriteBatch.flushCount` hook, so with
        // manifest commits enabled they accumulate into `writer.manifest_builder`
        // like any tracked writer's would; nothing else ever frees that
        // state for a value that never calls `close()`.
        defer writer.manifest_builder.deinit(self.allocator);
        var pages = PageAllocator{ .file = &writer, .free_pages = &.{}, .next_page_id = next_page.*, .ledger = if (tracking) |target| target.ledger else null, .can_reuse = false };
        defer pages.deinit();
        var builder = ExtentAppender{ .file = &writer, .pages = &pages, .tail = undefined, .batch = .{ .file = &writer } };
        defer builder.deinit();
        const chain_root = next_page.*;
        var buffer: [65536]u8 = undefined;
        const chunk_size = self.maxValuePagePayloadBytes();
        var buffered: usize = 0;
        var written: usize = 0;
        while (try source.next(cancel)) |chunk| {
            var offset: usize = 0;
            while (offset < chunk.len) {
                const n = @min(chunk_size - buffered, chunk.len - offset);
                @memcpy(buffer[value_page_header_size + buffered ..][0..n], chunk[offset..][0..n]);
                buffered += n;
                offset += n;
                if (buffered == chunk_size or written + buffered == len) {
                    if (cancel) |token| try token.check();
                    if (tree) {
                        try builder.pushValue(buffer[value_page_header_size..][0..buffered]);
                    } else {
                        const page = try pages.allocate();
                        const next = if (written + buffered < len) page + 1 else 0;
                        try pages.noteValue(page, len - written);
                        if (next != 0) try pages.retainValue(next);
                        try builder.batch.appendValue(page, next, buffer[value_page_header_size..][0..buffered]);
                    }
                    written += buffered;
                    buffered = 0;
                }
            }
        }
        if (buffered != 0 or written != len) return error.InvalidNativeValueChain;
        if (!tree) {
            try builder.batch.flush();
            next_page.* = pages.next_page_id;
            try transferPendingValues(&pages, tracking);
            return chain_root;
        }
        const result = try builder.finish();
        next_page.* = pages.next_page_id;
        try transferPendingValues(&pages, tracking);
        return result.page;
    }

    fn transferPendingValues(source: *PageAllocator, tracking: ?*PageAllocator) !void {
        const target = tracking orelse return;
        var pending = source.pending_values.iterator();
        while (pending.next()) |entry| try target.pending_values.put(target.file.allocator, entry.key_ptr.*, entry.value_ptr.*);
    }

    const VacuumValue = struct {
        inline_value: []const u8,
        owned: ?[]u8 = null,
        root: u64 = 0,
        len: usize,

        pub fn deinit(self: VacuumValue, allocator: Allocator) void {
            if (self.owned) |value| allocator.free(value);
        }
    };

    fn copyVacuumValue(self: *NativeFile, file: std.Io.File, next_page: *u64, entry: CatalogEntry, tree: bool, cancel: ?*const maintenance.CancelToken, tracking: ?*PageAllocator) !VacuumValue {
        const len = if (entry.external_value_root_page == 0) entry.value.len else entry.external_value_len;
        if (entry.external_value_root_page == 0) return .{ .inline_value = entry.value, .len = len };
        const header_len: usize = if (tree) 16 else documentHeaderSize(self.header.indexed_reclamation or self.vacuum_target_indexed, entry.key);
        if (header_len + entry.key.len + len <= self.maxPagePayloadBytes()) {
            // Re-inlining an external value allocates at most one page.
            const value = try self.catalogEntryValueAlloc(self.allocator, entry);
            return .{ .inline_value = value, .owned = value, .len = len };
        }
        const root = try self.copyExternalValue(file, next_page, entry.external_value_root_page, len, tree or len >= 64 * 1024, cancel, tracking);
        return .{ .inline_value = "", .root = root, .len = len };
    }

    // These catalog references lease pages only in their source inode.
    // Readers own that descriptor across adoption; copying a temporary lease
    // into the replacement would retain an otherwise dead artifact twice.
    pub const artifact_lease_key_prefix = "\x00AFLEASE/";

    fn copyVacuumCatalogRecords(
        self: *NativeFile,
        compact_file: std.Io.File,
        root: CatalogRoot,
        next_page_id: *u64,
        destination_root_page: *u64,
        live_bytes: *u64,
        cancel: ?*const maintenance.CancelToken,
    ) !usize {
        var cursor = try LiveRecordCursor.init(self, .{ .catalog = root });
        defer cursor.deinit();

        const io = self.runtimeIo();
        var writer = NativeFile{ .allocator = self.allocator, .io_impl = undefined, .borrowed_io = io, .path = @constCast(""), .file = compact_file, .header = self.header, .page_cache_enabled = .init(false), .max_file_bytes = self.vacuum_workspace_limit };
        writer.header.indexed_reclamation = self.header.indexed_reclamation or self.vacuum_target_indexed;
        // See `copyExternalValue`'s matching comment: `writer` never closes,
        // so its manifest tracking state must be freed explicitly.
        defer writer.manifest_builder.deinit(self.allocator);
        var pages = PageAllocator{ .file = &writer, .free_pages = &.{}, .next_page_id = next_page_id.*, .pack_records = true };
        defer pages.deinit();
        var key_index = DocumentIndexBulkBuilder{ .owner = &writer, .file = compact_file, .next_page_id = &pages.next_page_id, .pages = &pages };
        defer key_index.deinit();
        var count: usize = 0;
        while (try cursor.next(cancel)) |record| {
            if (root == .metadata and std.mem.startsWith(u8, record.key, artifact_lease_key_prefix)) continue;
            const value = try self.copyVacuumValue(compact_file, &pages.next_page_id, record, true, cancel, null);
            defer value.deinit(self.allocator);
            destination_root_page.* = try pages.writeCatalog(.{
                .previous_page = if (writer.header.indexed_reclamation) 0 else destination_root_page.*,
                .key = record.key,
                .value = value.inline_value,
                .external_value_root_page = value.root,
                .external_value_len = value.len,
            });
            try key_index.add(record.key, destination_root_page.*);
            live_bytes.* +|= record.key.len + value.len;
            count += 1;
        }
        const index_root = try key_index.finish();
        if (count > 0) {
            destination_root_page.* = try writer.writeCatalogRoot(&pages, destination_root_page.*, index_root, 0);
        }
        try pages.flush();
        next_page_id.* = pages.next_page_id;
        return count;
    }

    fn copyVacuumDocumentRecords(
        self: *NativeFile,
        compact_file: std.Io.File,
        next_page_id: *u64,
        document_root_page: *u64,
        document_index_root_page: *u64,
        namespace_directory: *NamespaceDirectory,
        live_bytes: *u64,
        cancel: ?*const maintenance.CancelToken,
    ) !usize {
        var cursor = try LiveRecordCursor.init(self, .documents);
        defer cursor.deinit();

        const io = self.runtimeIo();
        var writer = NativeFile{ .allocator = self.allocator, .io_impl = undefined, .borrowed_io = io, .path = @constCast(""), .file = compact_file, .header = self.header, .page_cache_enabled = .init(false), .max_file_bytes = self.vacuum_workspace_limit };
        writer.header.indexed_reclamation = self.header.indexed_reclamation or self.vacuum_target_indexed;
        // See `copyExternalValue`'s matching comment: `writer` never closes,
        // so its manifest tracking state must be freed explicitly.
        defer writer.manifest_builder.deinit(self.allocator);
        var pages = PageAllocator{ .file = &writer, .free_pages = &.{}, .next_page_id = next_page_id.*, .pack_records = true };
        defer pages.deinit();
        var document_index = DocumentIndexBulkBuilder{
            .owner = &writer,
            .file = compact_file,
            .next_page_id = &pages.next_page_id,
            .pages = &pages,
        };
        defer document_index.deinit();
        var count: usize = 0;
        while (try cursor.next(cancel)) |record| {
            const value = try self.copyVacuumValue(compact_file, &pages.next_page_id, record, false, cancel, null);
            defer value.deinit(self.allocator);
            const namespace = documentNamespace(record.key);
            const previous_namespace_page = namespace_directory.get(namespace) orelse 0;
            document_root_page.* = try pages.writeDocument(.{
                .previous_page = if (writer.header.indexed_reclamation) 0 else document_root_page.*,
                .previous_namespace_page = if (writer.header.indexed_reclamation) 0 else previous_namespace_page,
                .key = record.key,
                .value = value.inline_value,
                .external_value_root_page = value.root,
                .external_value_len = value.len,
                .content_digest = if (documentHeaderSize(writer.header.indexed_reclamation, record.key) == 60) try self.documentFingerprintAtCheckpoint(self.activeCheckpoint(), record.key) else null,
            });
            try document_index.add(record.key, document_root_page.*);
            if (namespace_directory.getPtr(namespace)) |head| {
                head.* = document_root_page.*;
            } else {
                const owned_namespace = try self.allocator.dupe(u8, namespace);
                namespace_directory.put(self.allocator, owned_namespace, document_root_page.*) catch |err| {
                    self.allocator.free(owned_namespace);
                    return err;
                };
            }
            live_bytes.* +|= record.key.len + value.len;
            count += 1;
        }
        document_index_root_page.* = try document_index.finish();
        if (writer.header.indexed_reclamation) document_root_page.* = 0;
        try pages.flush();
        next_page_id.* = pages.next_page_id;
        return count;
    }

    pub fn vacuum(self: *NativeFile) !VacuumReport {
        return try self.vacuumWithCancel(null);
    }

    pub fn vacuumWithCancel(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !VacuumReport {
        if (self.read_only) return error.ReadOnly;
        // Through the registry, like every other exclusive grant on this
        // inode: a raw `acquireDataRewriteLock` here would self-conflict
        // against any in-process warm `.exclusive` hold on the same inode
        // (this file's own parked epoch-reuse lock, or another NativeFile
        // on the same path in an `externally_locked` setup).
        const data_lock = try self.acquireInodeLock(.exclusive, false, false, "vacuumWithCancel");
        defer data_lock.release(self.runtimeIo());
        try self.refreshIfWriterBaseStale();
        // Replaces the old namespace-directory scan: a live pin in the
        // region's reader table (any reader, indexed or not -- the region
        // doesn't distinguish) refuses the vacuum rather than rewriting
        // pages a reader may still need.
        if (try self.regionForInode()) |region| if (region.minimumPinnedSequence() != null) return error.WouldBlock;
        var image = try self.prepareVacuum(cancel);
        defer image.deinit();
        try self.publishVacuum(&image);
        return image.report;
    }

    pub fn publishVacuum(self: *NativeFile, image: *VacuumImage) !void {
        const outcome = try self.replaceWithPreparedGeneration(&image.prepared);
        if (self.test_fail_vacuum_after_adoption) {
            self.test_fail_vacuum_after_adoption = false;
            return error.InjectedVacuumPostRenameFailure;
        }
        if (outcome == .durability_unknown) return error.OutcomeUnknown;
    }

    pub fn preparePublicationSequence(self: *NativeFile, sequence: u64) !void {
        var checkpoint = self.activeCheckpoint();
        if (self.header.indexed_reclamation) {
            const old_budget = self.retirement_work_pages;
            self.retirement_work_pages = 0;
            defer self.retirement_work_pages = old_budget;
            var pages = try self.pageAllocatorFromFreeMap(checkpoint);
            defer pages.deinit();
            // Private-image normalization may resume an interrupted owner
            // checkpoint. Complete that builder before replacing its baseline.
            while (pages.ledger.?.root.build_limit != 0) {
                const page = try pages.allocate();
                try pages.ledger.?.checkpointStep(.{ .context = &pages, .allocate = PageAllocator.takeMetadataPage, .read = PageAllocator.readLedgerPage, .write = PageAllocator.writeLedgerPage, .payload_bytes = self.maxPagePayloadBytes(), .cancel_requested = if (self.allocator_cancel_token) |token| &token.requested else null }, page, self.publicationEpoch());
            }
            // Epoch rebasing changes existing events rather than appending
            // new IDs, so this private boundary must serialize the full queue.
            pages.ledger.?.incremental = false;
            try pages.ledger.?.rebaseEpochs(sequence, if (self.allocator_cancel_token) |token| &token.requested else null);
            self.header.checkpoints[self.header.active_checkpoint].commit_sequence = sequence -| 1;
            checkpoint.free_map_root_page = try pages.allocate();
            try self.persistAllocator(&pages, &checkpoint);
        }
        try self.finishPublicationSequence(sequence, checkpoint);
    }

    /// Private generations normalize retirement once before catch-up. Later
    /// changes retire at epoch zero, so final sequence publication needs only
    /// the two header slots and never another ownership-table snapshot.
    pub fn finishPublicationSequence(self: *NativeFile, sequence: u64, selected: CheckpointSlot) !void {
        var checkpoint = selected;
        checkpoint.commit_sequence = sequence;
        // perf/lwa-read-audit: `redo_folded_through` must advance to this
        // same final `sequence`, not stay at whatever `selected` already
        // carried. `selected` (`image.prepared.activeCheckpoint()`) was
        // last stamped by `prepareVacuum`'s own construction
        // (`redo_folded_through = previous.commit_sequence + 1`, taken
        // from the *initial* snapshot `Store.performVacuum` captured
        // before any catch-up round ran) -- correct only when `sequence`
        // here still equals that same initial value, i.e. no concurrent
        // commit landed on the live store during the whole copy. Every
        // catch-up round in between (`applyCapturedChanges`) writes
        // directly into this generation's real tree -- `image.prepared`
        // has no redo attached at all until `replaceWithPreparedGeneration`
        // runs, well after this call, so there is nowhere for those
        // writes to divert to -- so by the time this function runs,
        // `sequence` (whatever catch-up advanced `commit_sequence` to,
        // residual included) is exactly as truthfully folded as
        // `prepareVacuum`'s own original stamp was for its own, earlier
        // value. Leaving the stale, too-low value here durably published
        // the wrong fold boundary to both slots: confirmed live as
        // `error.NativeRedoLogCorrupt` on the next reopen under
        // concurrent group-commit load during "lite online vacuum
        // publishes while group-commit mutations keep landing" -- the
        // live generation kept committing correctly past the stale
        // boundary (ordinary diverted commits never touch this field,
        // by design), but a fresh recovery's own `redo_log.replay`,
        // pinned to the stale, far-too-low boundary from the slot it
        // actually read, found the log's first *genuinely new* record
        // nowhere near `stale + 1` and refused it as corrupt, even
        // though nothing was actually malformed on disk.
        checkpoint.redo_folded_through = sequence;
        // Catch-up can replay keys from failed/no-op foreground mutations, so
        // its private sequence may exceed the live store's publication sequence.
        // Both recovery slots must identify the final image; a newer private
        // fallback slot must never win checkpoint selection after reopen.
        // No manifest: this is the same "trust the slot unconditionally"
        // bootstrap case as the very first checkpoint -- both slots are
        // about to say the same thing, so there is no "other, older"
        // candidate a torn write could fall back to anyway.
        checkpoint.presynced = true;
        checkpoint.manifest_page = 0;
        checkpoint.manifest_crc = 0;
        checkpoint.manifest_page_count = 0;
        self.header.checkpoints = .{ checkpoint, checkpoint };
        self.header.active_checkpoint = 0;
        try self.writeSlotPage(0, checkpoint);
        try self.writeSlotPage(1, checkpoint);
        try self.syncIfRequired(null);
    }

    // Bound editor state and retained inline values independently. External
    // values are streamed directly into the unpublished image, never retained.
    const catchup_batch_keys = 1024;
    const catchup_batch_bytes = 1024 * 1024;

    pub fn applyCapturedChanges(self: *NativeFile, destination: *NativeFile, capture: *const ChangeCapture, report: *VacuumReport, cancel: ?*const maintenance.CancelToken) !void {
        if (capture.overflow) return error.FileBusy;
        var updated_report = report.*;
        try destination.beginTransaction();
        errdefer destination.abortTransaction();
        // §9.7c (ReadView): pin one (checkpoint, mark) pair for this whole
        // catch-up round instead of reading `self.activeCheckpoint()` once
        // and re-deriving the overlay mark from it at each key
        // (`redoOverlayEntry`'s own `readMark` -- "checkpoint.commit_sequence
        // == activeCheckpoint().commit_sequence" -- compares against
        // whatever `activeCheckpoint()` returns *at that moment*, not what
        // it returned when this round started). The non-final-round caller
        // (`Store.applyResidualVacuumChanges`, unlike its AssumeLocked
        // sibling) releases the store mutex before calling this, so a
        // concurrent foreground commit publishing a real checkpoint
        // partway through this round's own loop would otherwise flip that
        // comparison mid-copy and silently resolve later keys in the same
        // round against a different, inconsistent mark than earlier ones.
        // `ReadView.open` also pins the shared overlay and this inode's
        // reader table for the capture's duration, same retention
        // guarantee every other multi-key read gets -- a per-call-site
        // `redoOverlayEntry(root_kind, self.activeCheckpoint(), key)` (this
        // function's own prior fix) got the *value* right but reimplemented
        // the merge inline instead of going through the one primitive
        // §9.7c exists to make that mistake impossible to repeat.
        var view = try ReadView.open(self, self.runtimeIo());
        defer view.release(self.runtimeIo());
        const checkpoint = view.checkpoint;
        inline for (0..3) |root| {
            const Mutation = if (root == 2) DocumentMutation else CatalogMutation;
            const map = capture.keys[root];
            const keys = try self.allocator.alloc([]const u8, map.count());
            defer self.allocator.free(keys);
            var iter = map.keyIterator();
            for (keys) |*key| key.* = iter.next().?.*;
            std.mem.sort([]const u8, keys, {}, struct {
                fn less(_: void, lhs: []const u8, rhs: []const u8) bool {
                    return std.mem.order(u8, lhs, rhs) == .lt;
                }
            }.less);
            var reader = RecordPageReader{};
            defer reader.deinit(self.allocator);
            var position: usize = 0;
            while (position < keys.len) {
                var arena = std.heap.ArenaAllocator.init(self.allocator);
                defer arena.deinit();
                const alloc = arena.allocator();
                var mutations = std.ArrayListUnmanaged(Mutation).empty;
                var retained_bytes: usize = 0;
                while (position < keys.len and mutations.items.len < catchup_batch_keys and retained_bytes < catchup_batch_bytes) : (position += 1) {
                    if (cancel) |token| try token.check();
                    const key = keys[position];
                    if (root == 0 and std.mem.startsWith(u8, key, artifact_lease_key_prefix)) continue;
                    const root_kind: TransactionWrites.Root = switch (root) {
                        0 => .metadata,
                        1 => .index,
                        else => .documents,
                    };
                    const old_size = try destination.liveRecordSize(root, key);
                    var record: ?CatalogEntry = null;
                    // §9.3a/§9.7c: a key captured while this source snapshot
                    // was live may be committed but not yet checkpointed --
                    // present only in the redo-log overlay, never in the
                    // physical tree `lookupDocumentIndexPage`/
                    // `lookupCatalogPage` walk below. Check the overlay
                    // first, exactly like `getDocumentAtCheckpointAlloc`,
                    // or an online vacuum silently drops every write that
                    // landed after the last checkpoint but before this
                    // catch-up round copied it (`entry.value` is owned by
                    // `self.allocator` per `redoOverlayEntryAt`'s own doc
                    // comment and must be freed once `copied` is built).
                    // `view.mark`, not a freshly re-derived one: every key
                    // in this round resolves against the exact same pinned
                    // snapshot `view` captured at this function's entry,
                    // regardless of whatever `self.activeCheckpoint()` does
                    // concurrently while this loop runs unlocked.
                    const overlay_entry = try self.redoOverlayEntryAt(root_kind, view.mark, key);
                    defer if (overlay_entry) |entry| self.allocator.free(entry.value);
                    if (overlay_entry) |entry| {
                        if (!entry.is_delete) record = entry;
                    } else if (if (root == 2) try self.lookupDocumentIndexPage(checkpoint, key) else try self.lookupCatalogPage(checkpoint, if (root == 0) .metadata else .index, key)) |id| {
                        const payload = try reader.read(self, self.allocator, checkpoint, id, if (root == 2) .document else .catalog);
                        if (root == 2) {
                            const doc = try decodeDocumentEntry(payload);
                            if (!doc.is_delete) record = .{ .previous_page = 0, .key = doc.key, .value = doc.value, .external_value_root_page = doc.external_value_root_page, .external_value_len = doc.external_value_len };
                        } else {
                            const entry = try decodeCatalogEntry(payload);
                            if (!entry.is_delete) record = entry;
                        }
                    }
                    const copied: VacuumValue = if (record) |entry| blk: {
                        if (!std.mem.eql(u8, entry.key, key)) return error.InvalidNativePageChain;
                        const writes = try destination.transactionWrites();
                        const value = try self.copyVacuumValue(destination.file, &writes.pages.next_page_id, entry, root != 2, cancel, &writes.pages);
                        errdefer value.deinit(self.allocator);
                        try destination.flushTransactionPayloads();
                        break :blk value;
                    } else .{ .inline_value = "", .len = 0 };
                    defer copied.deinit(self.allocator);
                    if (old_size) |len| {
                        updated_report.live_file_count -= 1;
                        updated_report.live_bytes -= len;
                    }
                    if (record != null) {
                        updated_report.live_file_count += 1;
                        updated_report.live_bytes += key.len + copied.len;
                    }
                    const value = try alloc.dupe(u8, copied.inline_value);
                    retained_bytes += key.len + value.len;
                    try mutations.append(alloc, .{ .key = key, .value = value, .is_delete = record == null, .external_value_root_page = copied.root, .external_value_len = if (copied.root != 0) copied.len else 0 });
                }
                if (root == 2) {
                    try destination.putDocumentBatch(mutations.items);
                } else {
                    try destination.putCatalogBatchForRoot(if (root == 0) .metadata else .index, mutations.items, .{ .payload_cache = .cold_sequential });
                }
            }
        }
        if (cancel) |token| try token.check();
        try destination.commitTransaction();
        updated_report.after_size = destination.activeCheckpoint().page_count * @as(u64, destination.header.page_size);
        updated_report.reclaimed_bytes = updated_report.before_size -| updated_report.after_size;
        report.* = updated_report;
    }

    fn liveRecordSize(self: *NativeFile, root: usize, key: []const u8) !?usize {
        const checkpoint = self.activeCheckpoint();
        if (self.stagedEntry(@fromBackingInt(@intCast(root)), key)) |entry| {
            return if (entry.is_delete) null else key.len + (if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len);
        }
        const page = (if (root == 2) try self.lookupDocumentIndexPage(checkpoint, key) else try self.lookupCatalogPage(checkpoint, if (root == 0) .metadata else .index, key)) orelse return null;
        const raw = try self.readPageAllocForCheckpoint(self.allocator, page, checkpoint);
        defer self.allocator.free(raw);
        if (root == 2) {
            const entry = try decodeDocumentEntry(try decodePagePayload(raw, .document));
            return if (entry.is_delete) null else entry.key.len + (if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len);
        }
        const entry = try decodeCatalogEntry(try decodePagePayload(raw, .catalog));
        return if (entry.is_delete) null else entry.key.len + (if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len);
    }

    pub fn prepareVacuum(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !VacuumImage {
        if (cancel) |token| try token.check();

        const io = self.runtimeIo();

        const before_size = (try self.file.stat(io)).size;
        const previous = self.activeCheckpoint();
        // §9's "the vacuumed generation should come out as a redo-log file
        // too": a vacuum used to always rebuild a plain, non-redo compacted
        // image (`attachFreshRedoState`'s own doc comment), permanently
        // reverting any redo-log store to the legacy commit path after its
        // first vacuum -- every long-lived database would lose the whole
        // point of the redo-log write path the moment maintenance first
        // compacted it. Reserve the same capacity the original file
        // already has (`self.header.redo_log_capacity`) in the compacted
        // image too, rather than recomputing docstore.zig's own
        // size-under-budget policy (§9.7a) here -- that scaling is a
        // `Store.createWithOptions`-level decision keyed off
        // `reclamation.max_storage_bytes`, which this layer already
        // respects via `self.max_file_bytes`/`vacuum_workspace_limit`;
        // preserving whatever capacity this file was already reserving is
        // the same budget by construction.
        const reserve_redo_log = self.redo != null;
        var redo_log_offset_bytes: u64 = 0;
        var redo_log_capacity_bytes: u64 = 0;

        const page_size: usize = @intCast(self.header.page_size);
        var random: [16]u8 = undefined;
        try io.randomSecure(&random);
        const basename = try std.fmt.allocPrint(self.allocator, ".aflite-compact-{x}", .{random});
        defer self.allocator.free(basename);
        const tmp_path = try std.fs.path.join(self.allocator, &.{ std.fs.path.dirname(self.path) orelse ".", basename });
        errdefer self.allocator.free(tmp_path);
        errdefer deleteFilePath(io, tmp_path) catch {};
        var compact_file = try std.Io.Dir.cwd().createFile(io, tmp_path, .{ .read = true, .exclusive = true, .permissions = .fromMode(0o600) });
        var compact_file_open = true;
        defer if (compact_file_open) compact_file.close(io);
        try compact_file.setLength(io, reserved_header_pages * @as(u64, page_size));

        var next_page_id: u64 = reserved_header_pages;
        var catalog_root_page: u64 = 0;
        var index_catalog_root_page: u64 = 0;
        var document_root_page: u64 = 0;
        var document_index_root_page: u64 = 0;
        var namespace_directory_root_page: u64 = 0;
        var free_map_root_page: u64 = 0;
        var live_bytes: u64 = 0;
        var live_record_count: usize = 0;
        var namespace_directory = NamespaceDirectory.empty;
        defer deinitNamespaceDirectory(self.allocator, &namespace_directory);

        live_record_count += try self.copyVacuumCatalogRecords(compact_file, .metadata, &next_page_id, &catalog_root_page, &live_bytes, cancel);
        live_record_count += try self.copyVacuumCatalogRecords(compact_file, .index, &next_page_id, &index_catalog_root_page, &live_bytes, cancel);
        const document_count = try self.copyVacuumDocumentRecords(compact_file, &next_page_id, &document_root_page, &document_index_root_page, &namespace_directory, &live_bytes, cancel);
        live_record_count += document_count;

        const indexed = self.header.indexed_reclamation or self.vacuum_target_indexed;
        if (document_count > 0 and !indexed) {
            var writer = NativeFile{ .allocator = self.allocator, .io_impl = undefined, .borrowed_io = io, .path = @constCast(""), .file = compact_file, .header = self.header, .page_cache_enabled = .init(false), .max_file_bytes = self.vacuum_workspace_limit };
            // See `copyExternalValue`'s matching comment: `writer` never
            // closes, so its manifest tracking state must be freed explicitly.
            defer writer.manifest_builder.deinit(self.allocator);
            var pages = PageAllocator{ .file = &writer, .free_pages = &.{}, .next_page_id = next_page_id, .pack_records = true };
            defer pages.deinit();
            namespace_directory_root_page = (try writer.writeNamespaceIndex(&pages, previous, .{ .history = 0 }, &namespace_directory)).page;
            try pages.flush();
            next_page_id = pages.next_page_id;
        }

        if (self.vacuum_workspace_limit) |limit| {
            if (next_page_id >= limit / self.header.page_size) return error.LiteStorageBudgetExceeded;
        }
        if (!indexed) free_map_root_page = try appendFreeMapPageToFile(self.allocator, compact_file, io, page_size, &next_page_id, next_page_id + 1, &.{});
        if (reserve_redo_log and !indexed) {
            // Mirrors `enableRedoLog`'s own non-indexed branch: bump
            // `page_count` past the reserved span with no free-map update
            // (a plain free map tolerates `page_count` running ahead of
            // its own last-written content -- that function's own doc
            // comment).
            const page_size_u64: u64 = self.header.page_size;
            const log_pages = std.math.divCeil(u64, @max(self.header.redo_log_capacity, 1), page_size_u64) catch unreachable;
            redo_log_offset_bytes = next_page_id * page_size_u64;
            redo_log_capacity_bytes = log_pages * page_size_u64;
            next_page_id += log_pages;
        }

        var checkpoint = CheckpointSlot{
            .commit_sequence = previous.commit_sequence + 1,
            .catalog_root_page = catalog_root_page,
            .document_root_page = document_root_page,
            .index_catalog_root_page = index_catalog_root_page,
            .free_map_root_page = free_map_root_page,
            .page_count = next_page_id,
            .namespace_directory_root_page = namespace_directory_root_page,
            .document_index_root_page = document_index_root_page,
            // perf/lwa-fold-boundary: vacuum's compaction folds everything
            // -- every live mutation already reached this generation's own
            // tree through the ordinary copy pass above, never through a
            // log -- so this new checkpoint's fold boundary is its own
            // `commit_sequence`, exactly like `checkpointRedoLog`'s own
            // fold. See `redo_folded_through`'s own doc comment.
            .redo_folded_through = previous.commit_sequence + 1,
        };
        if (indexed) {
            // A replacement inode has a new logical lineage. Its freshly copied
            // roots are also the private writer's baseline, so ordinary root
            // comparison cannot stamp these identities during allocator bootstrap.
            inline for (@typeInfo(LogicalGenerations).@"struct".field_names) |identity|
                try io.randomSecure(&@field(checkpoint.logical, identity));
        }
        var compact_header = Header{
            // `reader_epoch_namespace` is now vestigial on-disk field only
            // (migration row 2: reader admission moves onto the shared
            // lock region, which is keyed by inode, not a path-resolved
            // namespace). Left zeroed, same as every other new write path.
            .indexed_reclamation = indexed,
            .page_size = self.header.page_size,
            .active_checkpoint = 0,
            .checkpoints = .{ checkpoint, .{} },
        };

        if (indexed) {
            // One-time graph bootstrap belongs to migration/shrinking, never a
            // normal commit. Ownership follows immutable DAG edges and records.
            var writer = NativeFile{ .allocator = self.allocator, .io_impl = undefined, .borrowed_io = io, .path = @constCast(""), .file = compact_file, .header = compact_header, .page_cache_enabled = .init(false), .max_file_bytes = self.vacuum_workspace_limit };
            writer.allocator_cancel_token = cancel;
            // See `copyExternalValue`'s matching comment: `writer` never
            // closes, so its manifest tracking state must be freed explicitly.
            defer writer.manifest_builder.deinit(self.allocator);
            const state = try self.allocator.create(allocator_v4.State);
            state.* = allocator_v4.State.init(self.allocator);
            writer.ledger = state;
            defer writer.invalidateLedger();
            for (1..@intCast(next_page_id)) |page| {
                if (cancel) |token| try token.check();
                try state.reserveTail(page);
            }
            var graph = try writer.indexedGraph(checkpoint, state, cancel);
            defer graph.deinit(self.allocator);
            var pages = PageAllocator{ .file = &writer, .free_pages = &.{}, .next_page_id = next_page_id, .ledger = state, .can_reuse = false };
            defer pages.deinit();
            if (reserve_redo_log) {
                // Mirrors `enableRedoLog`'s own indexed branch: reserve the
                // log region's page-id span through the real allocator
                // *before* the free-map root page, the same order that
                // function uses, so the ledger's own coverage and the
                // checkpoint's `page_count` (set by `persistAllocator`
                // below, from `pages.next_page_id`) land in lockstep.
                const page_size_u64: u64 = self.header.page_size;
                const log_pages = std.math.divCeil(u64, @max(self.header.redo_log_capacity, 1), page_size_u64) catch unreachable;
                redo_log_offset_bytes = next_page_id * page_size_u64;
                redo_log_capacity_bytes = log_pages * page_size_u64;
                for (0..log_pages) |_| _ = try pages.allocateFresh();
            }
            checkpoint.free_map_root_page = try pages.allocate();
            try writer.persistAllocator(&pages, &checkpoint);
            next_page_id = pages.next_page_id;
            compact_header.checkpoints = .{ checkpoint, checkpoint };
        }
        // Deferred until after the agenda-bootstrap projection below (not
        // set on `compact_header` yet): that projection runs a real
        // transaction (`beginTransaction`/`commitTransaction`) against a
        // bare `NativeFile` literal whose own `.redo` is `null` by
        // construction -- setting `redo_log_capacity` on its header before
        // that would make `self.header.redo_log_capacity != 0` (a redo-log
        // signal several call sites outside this function trust, e.g.
        // `decodeFreeMapAlloc`) disagree with `self.redo == null` (the
        // actual diversion state) for the span of that one migration pass,
        // the same inconsistent-intermediate-state hazard this design's own
        // §9.3d per-subsystem audit exists to rule out. The page-id span
        // itself is already reserved above either way (`redo_log_offset_
        // bytes`/`redo_log_capacity_bytes`, computed from `next_page_id`
        // before this function ever allocates more), so deferring only the
        // header *field write* changes nothing about where the region
        // physically ends up.

        if (indexed and !self.header.indexed_reclamation) {
            // Legacy formats have no agenda. Bootstrap it once from the source
            // keys before this private image becomes a revision-7 generation.
            var projection = NativeFile{ .allocator = self.allocator, .io_impl = undefined, .borrowed_io = io, .path = tmp_path, .file = compact_file, .header = compact_header, .no_sync = true, .page_cache_enabled = .init(false) };
            defer projection.invalidateLedger();
            defer projection.page_cache.deinit(self.allocator);
            // `projection` never calls `close()` either. A successful
            // `commitTransaction` below already resets `manifest_builder`
            // (see `publishCheckpoint`), making this a no-op on that path;
            // on the `errdefer projection.abortTransaction()` path just below,
            // nothing else ever frees whatever this transaction's own
            // flush(es) tracked.
            defer projection.manifest_builder.deinit(self.allocator);
            try projection.beginTransaction();
            errdefer projection.abortTransaction();
            var records = try LiveRecordCursor.init(self, .documents);
            defer records.deinit();
            while (try records.next(cancel)) |record| {
                const scope = recovery_agenda.namespace(record.key) orelse continue;
                const marker = try std.mem.concat(self.allocator, u8, &.{ recovery_agenda.prefix, scope });
                defer self.allocator.free(marker);
                const existing = try projection.getCatalogRecordAlloc(self.allocator, marker);
                if (existing) |bytes| {
                    self.allocator.free(bytes);
                } else {
                    try projection.putCatalogRecord(marker, "");
                    live_record_count += 1;
                    live_bytes += marker.len;
                }
            }
            try projection.commitTransaction();
            compact_header = projection.header;
            next_page_id = projection.activeCheckpoint().page_count;
        }
        compact_header.redo_log_offset = redo_log_offset_bytes;
        compact_header.redo_log_capacity = redo_log_capacity_bytes;
        var encoded_header: [header_size]u8 = undefined;
        encodeHeader(&encoded_header, compact_header);
        try compact_file.writePositionalAll(io, &encoded_header, 0);
        // This is a wholesale new generation, not an ordinary commit: both
        // slots are trusted unconditionally, the same as the very first
        // checkpoint a fresh file ever gets. (The agenda-bootstrap branch
        // above already wrote slot 1 for real through the normal commit
        // path onto this same compact_file; re-writing it here with the
        // identical final value is a harmless duplicate, not a correctness
        // issue.)
        inline for (0..checkpoint_slot_count) |index| {
            var slot = compact_header.checkpoints[index];
            slot.presynced = true;
            slot.manifest_page = 0;
            slot.manifest_crc = 0;
            slot.manifest_page_count = 0;
            try writeSlotPageTo(compact_file, io, compact_header.page_size, index, slot);
        }
        const after_size = next_page_id * @as(u64, self.header.page_size);
        try compact_file.setLength(io, after_size);
        if (!self.no_sync) try compact_file.sync(io);
        if (cancel) |token| try token.check();
        compact_file_open = false;
        // `prepared` gets published into `self.path`'s place
        // (`replaceWithPreparedGeneration`, called from the owning
        // `Store`'s vacuum path) and so *becomes* the live file other
        // NativeFile instances in this process -- including a fresh probe
        // like `Store.checkWithCancel`'s -- can concurrently open on that
        // same path/inode. Without a real registry entry here, every one
        // of this NativeFile's own commits during the catch-up/residual
        // phase that runs *after* that publish would fall back to
        // `acquireInodeLock`'s unshared `acquireStandalone` path (a fresh
        // raw fd per acquisition on `tmp_path`, which the rename has
        // already moved to be the very same inode `self.inode_lock_ref`
        // now points to after the swap) and self-conflict against
        // anything using the registry on that inode, the same class of
        // bug this registry exists to rule out everywhere else.
        const inode_entry = try inode_lock.open(io, tmp_path);
        const prepared: NativeFile = .{ .allocator = self.allocator, .io_impl = undefined, .borrowed_io = io, .path = tmp_path, .file = compact_file, .header = compact_header, .no_sync = self.no_sync, .page_cache_policy = .metadata_only, .page_cache = .{ .resource_manager = self.page_cache.resource_manager }, .max_file_bytes = self.vacuum_workspace_limit, .inode_lock_ref = .init(inode_entry) };
        // `prepared.redo` stays `null` here, deliberately, even when
        // `reserve_redo_log` reserved the page-id span and header fields
        // for one above: `prepared` is still under construction --
        // `Store.performVacuum`'s own `preparePublicationSequence` and
        // catch-up-round machinery still run real, undiverted ledger/
        // free-map writes against it before this generation is ever
        // adopted. Attaching `self.redo` this early made every one of
        // those internal writes divert into the (empty, not-yet-shared)
        // overlay instead of writing real pages -- `next_page_id`/
        // `checkpoint.page_count` kept advancing as if they had, so the
        // adopted header ended up claiming pages the file was never
        // actually extended to hold (`PageWriteBatch.flush`'s own
        // diversion check, confirmed live: `checkpointPrefixSize >
        // file_size` on the very first read after an *online* vacuum,
        // `recoverActiveCheckpoint`'s `candidates == 0`). Attaching
        // `self.redo` happens instead in `replaceWithPreparedGeneration`,
        // after every such internal write this generation will ever make
        // is already done and the swap has settled.
        return .{ .prepared = prepared, .report = .{
            .before_size = before_size,
            .after_size = after_size,
            .reclaimed_bytes = if (before_size > after_size) before_size - after_size else 0,
            .live_file_count = @intCast(live_record_count),
            .live_bytes = live_bytes,
        } };
    }

    pub fn copyStableSnapshotToPath(self: *NativeFile, dest_path: []const u8, replace: bool) !StableSnapshotReport {
        const io = self.runtimeIo();
        if (std.mem.eql(u8, self.path, dest_path) or try pathsReferToSameExistingFile(self.allocator, io, self.path, dest_path)) {
            return error.InvalidNativeSnapshotPath;
        }
        const dest_exists = pathExists(io, dest_path);
        if (!replace and dest_exists) return error.PathAlreadyExists;

        var dest_lock = try lockWriterPathWithIo(self.allocator, io, dest_path);
        defer dest_lock.close();

        if (!replace and !dest_exists and pathExists(io, dest_path)) return error.PathAlreadyExists;

        const checkpoint = self.activeCheckpoint();
        const snapshot_size = try checkpointPrefixSize(checkpoint, self.header.page_size);
        const source_size = (try self.file.stat(io)).size;
        if (source_size < snapshot_size) return error.TruncatedNativeSnapshotSource;

        const tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.tmp-aflite-snapshot", .{dest_path});
        defer self.allocator.free(tmp_path);
        errdefer deleteFilePath(io, tmp_path) catch {};

        {
            var out_file = try createSnapshotFile(io, tmp_path);
            defer out_file.close(io);

            const chunk_size: usize = 1024 * 1024;
            const buffer_len: usize = @intCast(@min(@as(u64, chunk_size), snapshot_size));
            const buffer = try self.allocator.alloc(u8, @max(buffer_len, 1));
            defer self.allocator.free(buffer);

            var offset: u64 = 0;
            while (offset < snapshot_size) {
                const len: usize = @intCast(@min(@as(u64, buffer.len), snapshot_size - offset));
                try readExactAt(self.file, io, buffer[0..len], offset);
                try out_file.writePositionalAll(io, buffer[0..len], offset);
                offset += len;
            }
            var destination = NativeFile{ .allocator = self.allocator, .io_impl = undefined, .borrowed_io = io, .path = @constCast(dest_path), .file = out_file, .header = self.header, .no_sync = false, .page_cache_enabled = .init(false) };
            defer destination.page_cache.deinit(self.allocator);
            // See `copyExternalValue`'s matching comment: `destination` never
            // closes, so its manifest tracking state (populated by the
            // `writePage`/`writeSlotPage` calls below) must be freed
            // explicitly.
            defer destination.manifest_builder.deinit(self.allocator);
            try destination.bindPrivateEpochNamespace(dest_path);
            // The raw copy above just took whatever bytes were physically at
            // both slot pages at copy time, which (this handle's own
            // checkpoint, `self`, having been pinned since before the
            // source's writer may have advanced further) can be a *later*
            // generation than the snapshot's own checkpoint and may name
            // roots past `snapshot_size`. bindPrivateEpochNamespace only
            // fixes up the static header; rewrite both slots explicitly so
            // the snapshot is self-contained: slot 0 authoritatively holds
            // this handle's own (pinned) checkpoint, trusted unconditionally
            // like a fresh file's bootstrap slot, and slot 1 is zeroed so it
            // can never be mistaken for a later, now-truncated-away
            // generation's stale copied bytes.
            var snapshot_checkpoint = checkpoint;
            // §9.3/§9.3a: under redo, `self.activeCheckpoint().commit_sequence`
            // is not the real physical checkpoint on disk -- `stageMutation`'s
            // own "track private changes" bump (its own doc comment)
            // advances it on every ordinary, overlay-only commit so
            // in-process callers can tell versions apart, while the real
            // on-disk slot (and the physical tree this raw byte copy above
            // just reproduced) stays at the last real `checkpointRedoLog`
            // fold's sequence. Stamping the bumped value into the
            // snapshot's own slot told a reopening `recoverRedoLog`
            // "every record through this sequence is already in the
            // tree," which is false under redo: every log record at or
            // below that sequence is then treated as superseded and never
            // replayed into the overlay, silently losing every write that
            // only ever lived in the log (confirmed live: a reopened
            // snapshot resolved a secret's "head" pointer back to
            // revision 0 even though the live file it was copied from
            // resolved it correctly). Use the real physical sequence
            // instead, the same one `publishRedoLogState`/
            // `checkpointRedoLog` already treat as authoritative.
            //
            // perf/lwa-fold-boundary: kept even now that recovery itself
            // reads `redo_folded_through` (set right below, to the same
            // value) rather than trusting `commit_sequence` as the fold
            // boundary -- this still matters independently, because
            // `commit_sequence` is also this slot's own *tip* (compared
            // directly by `readMark`/`committedSequence`-style callers,
            // and by `recoverRedoLog`'s own metadata pass whenever the
            // copied log region happens to hold nothing past the fold to
            // correct it from). Leaving it at the inflated, bumped-for-
            // bookkeeping value would make the snapshot's reported tip
            // disagree with what its own copied tree pages actually
            // contain.
            if (self.redo) |redo| snapshot_checkpoint.commit_sequence = redo.checkpoint_sequence;
            // The fold boundary itself: this snapshot's tree pages are a
            // raw byte copy, so they reflect real content only up to the
            // source's last real fold -- exactly `redo.checkpoint_sequence`
            // -- regardless of how much further the copied log region (if
            // any was included in `snapshot_size`) advances the tip once
            // replayed on reopen.
            if (self.redo) |redo| snapshot_checkpoint.redo_folded_through = redo.checkpoint_sequence;
            snapshot_checkpoint.presynced = true;
            snapshot_checkpoint.manifest_page = 0;
            snapshot_checkpoint.manifest_crc = 0;
            snapshot_checkpoint.manifest_page_count = 0;
            // bindPrivateEpochNamespace above already re-stamped any embedded
            // allocator certificate's fingerprint for the new namespace, but
            // it did so against the *untouched* two-slot checkpoints array
            // (whatever this handle's in-memory header held, matching the
            // state at certify time). The final on-disk state instead carries
            // snapshot_checkpoint in slot 0 and a zeroed slot 1, so the
            // fingerprint a later reopen recomputes would differ from what
            // was just stamped. Re-stamp once more against the *final*
            // checkpoints so the certificate stays valid after reopen.
            if (destination.header.indexed_reclamation and checkpoint.free_map_root_page != 0) {
                const root = try destination.readPagePayloadByKindAllocForCheckpoint(destination.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
                defer destination.allocator.free(root);
                const post_namespace_fingerprint = fingerprintHeader(destination.header);
                if (root.len == 192 and std.mem.eql(u8, root[128..160], &post_namespace_fingerprint)) {
                    var final_header = destination.header;
                    final_header.checkpoints = .{ snapshot_checkpoint, .{ .page_count = 0 } };
                    final_header.active_checkpoint = 0;
                    @memcpy(root[128..160], &fingerprintHeader(final_header));
                    try destination.writePage(checkpoint.free_map_root_page, .free_map, root);
                }
            }
            try destination.writeSlotPage(0, snapshot_checkpoint);
            var zeroed_slot: [default_page_size]u8 = @splat(0);
            try out_file.writePositionalAll(io, &zeroed_slot, slotPhysicalPage(1) * @as(u64, destination.header.page_size));
            destination.header.checkpoints = .{ snapshot_checkpoint, .{ .page_count = 0 } };
            destination.header.active_checkpoint = 0;
            try out_file.setLength(io, snapshot_size);
            try out_file.sync(io);
        }

        renameFilePath(io, tmp_path, dest_path) catch |err| {
            deleteFilePath(io, tmp_path) catch {};
            return err;
        };
        try fs_paths.syncDirPortable(
            io,
            std.fs.path.dirname(dest_path) orelse ".",
        );

        return .{
            .source_size = source_size,
            .snapshot_size = snapshot_size,
            .checkpoint_sequence = checkpoint.commit_sequence,
            .page_count = checkpoint.page_count,
            .tail_bytes = source_size - snapshot_size,
        };
    }

    pub fn maxPagePayloadBytes(self: *const NativeFile) usize {
        return @as(usize, @intCast(self.header.page_size)) - page_header_size;
    }

    pub fn maxValuePagePayloadBytes(self: *const NativeFile) usize {
        return self.maxPagePayloadBytes() - value_page_header_size;
    }

    fn validateCatalogMutation(self: *const NativeFile, mutation: CatalogMutation) !void {
        if (mutation.key.len > catalog_key_len_mask or mutation.value.len > std.math.maxInt(u32)) return error.RecordTooLarge;
        const fixed_len = 16 + mutation.key.len;
        if (fixed_len > self.maxPagePayloadBytes()) return error.PageTooLarge;
        if (mutation.external_value_root_page != 0) {
            if (self.transaction_header == null or mutation.is_delete or mutation.value.len != 0 or mutation.external_value_len == 0 or mutation.external_value_len > std.math.maxInt(u32) or mutation.external_value_root_page >= self.activeCheckpoint().page_count) return error.InvalidNativeValueChain;
            if (fixed_len + 8 > self.maxPagePayloadBytes()) return error.PageTooLarge;
            return;
        }
        if (mutation.is_delete) return;
        if (mutation.value.len <= self.maxPagePayloadBytes() - fixed_len) return;
        if (value_page_header_size > self.maxPagePayloadBytes()) return error.InvalidNativePageLength;
        if (fixed_len + 8 > self.maxPagePayloadBytes()) return error.PageTooLarge;
    }

    fn catalogEntryFitsInline(self: *const NativeFile, key: []const u8, value: []const u8) bool {
        const fixed_len = 16 + key.len;
        return fixed_len <= self.maxPagePayloadBytes() and value.len <= self.maxPagePayloadBytes() - fixed_len;
    }

    fn catalogEntryValueAlloc(self: *NativeFile, allocator: Allocator, entry: CatalogEntry) ![]u8 {
        return try self.catalogEntryValueAtCheckpointAlloc(allocator, entry, self.activeCheckpoint());
    }

    fn catalogEntryValueAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, entry: CatalogEntry, checkpoint: CheckpointSlot) ![]u8 {
        if (entry.external_value_root_page != 0) {
            return try self.readValuePagesAtCheckpointAlloc(allocator, entry.external_value_root_page, entry.external_value_len, checkpoint);
        }
        return try allocator.dupe(u8, entry.value);
    }

    fn catalogEntryRangeAlloc(self: *NativeFile, allocator: Allocator, entry: CatalogEntry, offset: u64, len: usize, checkpoint: CheckpointSlot) ![]u8 {
        const value_len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
        if (offset > std.math.maxInt(usize)) return error.EndOfStream;
        const start: usize = @intCast(offset);
        if (start > value_len or value_len - start < len) return error.EndOfStream;
        if (entry.external_value_root_page != 0) {
            return try self.readValuePagesRangeAlloc(allocator, entry.external_value_root_page, value_len, start, len, checkpoint);
        }
        return try allocator.dupe(u8, entry.value[start..][0..len]);
    }

    fn validateDocumentMutation(self: *const NativeFile, mutation: DocumentMutation) !void {
        if (mutation.key.len > std.math.maxInt(u32) or mutation.value.len > std.math.maxInt(u32)) return error.RecordTooLarge;
        const fixed_len = documentHeaderSize(self.header.indexed_reclamation, mutation.key) + mutation.key.len;
        if (fixed_len > self.maxPagePayloadBytes()) return error.PageTooLarge;
        if (mutation.external_value_root_page != 0) {
            if (self.transaction_header == null or mutation.is_delete or mutation.value.len != 0 or mutation.external_value_len == 0 or mutation.external_value_len > std.math.maxInt(u32) or mutation.external_value_root_page >= self.activeCheckpoint().page_count) return error.InvalidNativeValueChain;
            if (fixed_len + 8 > self.maxPagePayloadBytes()) return error.PageTooLarge;
            return;
        }
        if (mutation.is_delete) return;
        if (mutation.value.len <= self.maxPagePayloadBytes() - fixed_len) return;
        if (value_page_header_size > self.maxPagePayloadBytes()) return error.InvalidNativePageLength;
        if (fixed_len + 8 > self.maxPagePayloadBytes()) return error.PageTooLarge;
    }

    fn documentEntryFitsInline(self: *const NativeFile, key: []const u8, value: []const u8) bool {
        const fixed_len = documentHeaderSize(self.header.indexed_reclamation, key) + key.len;
        return fixed_len <= self.maxPagePayloadBytes() and value.len <= self.maxPagePayloadBytes() - fixed_len;
    }

    fn documentEntryValueAlloc(self: *NativeFile, allocator: Allocator, entry: DocumentEntry) ![]u8 {
        if (entry.external_value_root_page != 0) {
            return try self.readValuePagesAlloc(allocator, entry.external_value_root_page, entry.external_value_len);
        }
        return try allocator.dupe(u8, entry.value);
    }

    fn readPagePayloadByKindAlloc(self: *NativeFile, allocator: Allocator, page_id: u64, kind: PageKind) ![]u8 {
        return try self.readPagePayloadByKindAllocForCheckpoint(allocator, page_id, kind, self.activeCheckpoint());
    }

    fn readPagePayloadByKindAllocForCheckpoint(
        self: *NativeFile,
        allocator: Allocator,
        page_id: u64,
        kind: PageKind,
        checkpoint: CheckpointSlot,
    ) ![]u8 {
        // Mirrors ledgerRead's fix: a cache hit already holds a
        // CRC-validated page, so borrow its payload instead of duplicating
        // the whole page just to decode and immediately discard the copy.
        // A packed record reference names one record inside a shared
        // record_bundle page, not the page's own payload -- unpackRecordPage
        // (inside readPageAllocForCheckpoint) does that extraction, so those
        // references must keep going through the slow path below.
        if (page_id & packed_record_flag == 0 and page_id != 0 and page_id < checkpoint.page_count) {
            const physical = physicalPage(page_id);
            const use_cache = self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0;
            if (use_cache) {
                if (try self.page_cache.acquirePayload(allocator, physical, @intCast(self.header.page_size))) |view| {
                    defer self.page_cache.releaseRaw(allocator, view);
                    if (view.validation.?.kind != kind) return error.UnexpectedNativePageKind;
                    return try allocator.dupe(u8, view.bytes[page_header_size..][0..view.validation.?.payload_len]);
                }
            }
        }
        const page = try self.readPageAllocForCheckpoint(allocator, page_id, checkpoint);
        defer allocator.free(page);
        return try decodePagePayloadAlloc(allocator, page, kind);
    }

    const ReachablePageSet = std.AutoHashMapUnmanaged(u64, void);

    fn markReachablePage(self: *NativeFile, reachable_pages: *ReachablePageSet, page_id: u64, page_count: u64) !void {
        const physical = physicalPage(page_id);
        if (physical == 0 or physical >= page_count) return error.InvalidPageId;
        const entry = try reachable_pages.getOrPut(self.allocator, page_id);
        if (entry.found_existing) return error.InvalidNativePageChain;
        // Multiple records may share a physical page. Keep both identities:
        // record addresses detect cycles; physical addresses protect reuse.
        if (physical != page_id) try reachable_pages.put(self.allocator, physical, {});
    }

    fn countReachableChainPages(self: *NativeFile, kind: PageKind, root_page_id: u64, reachable_pages: *ReachablePageSet) !u64 {
        return try self.countReachableChainPagesWithCancel(kind, root_page_id, reachable_pages, null);
    }

    fn countReachableChainPagesWithCancel(self: *NativeFile, kind: PageKind, root_page_id: u64, reachable_pages: *ReachablePageSet, cancel: ?*const maintenance.CancelToken) !u64 {
        return try self.countReachableChainPagesForCheckpoint(kind, root_page_id, self.activeCheckpoint(), reachable_pages, cancel);
    }

    fn countReachableChainPagesForCheckpoint(
        self: *NativeFile,
        kind: PageKind,
        root_page_id: u64,
        checkpoint: CheckpointSlot,
        reachable_pages: *ReachablePageSet,
        cancel: ?*const maintenance.CancelToken,
    ) !u64 {
        var records = RecordPageReader{};
        defer records.deinit(self.allocator);
        var seen_catalog_keys = std.StringHashMapUnmanaged(void).empty;
        defer {
            var it = seen_catalog_keys.iterator();
            while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
            seen_catalog_keys.deinit(self.allocator);
        }

        var count: u64 = 0;
        var page_id = root_page_id;
        var catalog_index: u64 = 0;
        var has_catalog_index = false;
        if (kind == .catalog and root_page_id != 0) {
            const roots = try self.readCatalogRoots(root_page_id, checkpoint);
            if (roots.indexed) {
                try self.markReachablePage(reachable_pages, root_page_id, checkpoint.page_count);
                catalog_index = roots.index;
                has_catalog_index = true;
                page_id = roots.history;
            }
        }
        var coverage = HistoryIndexCoverage{};
        defer coverage.deinit(self.allocator);
        if (has_catalog_index) try coverage.initIndex(self, checkpoint, catalog_index, cancel);
        const use_link_cache = !has_catalog_index and self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0;
        while (page_id != 0) {
            if (cancel) |token| try token.check();
            try self.markReachablePage(reachable_pages, page_id, checkpoint.page_count);

            if (use_link_cache) blk: {
                const links = (try self.page_cache.getLinksCopy(self.allocator, page_id)) orelse break :blk;
                defer if (links.key) |key| self.allocator.free(key);
                if (links.kind != kind) return error.UnexpectedNativePageKind;
                switch (kind) {
                    .catalog => {
                        const entry_key = links.key orelse &[_]u8{};
                        const seen = seen_catalog_keys.contains(entry_key);
                        if (!seen) {
                            const owned_key = try self.allocator.dupe(u8, entry_key);
                            errdefer self.allocator.free(owned_key);
                            try seen_catalog_keys.put(self.allocator, owned_key, {});
                        }
                        if (!seen and links.external_value_root_page != 0) {
                            try self.validateReachableValuePages(links.external_value_root_page, links.external_value_len, checkpoint, reachable_pages);
                        }
                    },
                    .document => {
                        if (links.external_value_root_page != 0) {
                            try self.validateReachableValuePages(links.external_value_root_page, links.external_value_len, checkpoint, reachable_pages);
                        }
                    },
                    .data, .value, .free_map, .document_index, .value_extent, .catalog_index, .record_bundle, .allocator, .key, .checkpoint_slot, .commit_manifest => return error.UnexpectedNativePageKind,
                }
                page_id = links.link_page;
                count += 1;
                if (count > recordWalkLimit(checkpoint, self.header.page_size)) return error.InvalidNativePageChain;
                continue;
            }

            const payload = try records.read(self, self.allocator, checkpoint, page_id, kind);
            page_id = switch (kind) {
                .catalog => blk: {
                    const entry = try decodeCatalogEntry(payload);
                    const seen = if (has_catalog_index)
                        !(try coverage.observe(self, checkpoint, .catalog, page_id, entry.key, entry.is_delete))
                    else
                        seen_catalog_keys.contains(entry.key);
                    if (!seen and !has_catalog_index) {
                        const owned_key = try self.allocator.dupe(u8, entry.key);
                        errdefer self.allocator.free(owned_key);
                        try seen_catalog_keys.put(self.allocator, owned_key, {});
                    }
                    if (!seen and entry.external_value_root_page != 0) {
                        try self.validateReachableValuePages(entry.external_value_root_page, entry.external_value_len, checkpoint, reachable_pages);
                    }
                    if (use_link_cache) self.cachePageLinks(page_id, .catalog, payload);
                    break :blk entry.previous_page;
                },
                .document => blk: {
                    const entry = try decodeDocumentEntry(payload);
                    if (entry.external_value_root_page != 0) {
                        try self.validateReachableValuePages(entry.external_value_root_page, entry.external_value_len, checkpoint, reachable_pages);
                    }
                    if (use_link_cache) self.cachePageLinks(page_id, .document, payload);
                    break :blk entry.previous_page;
                },
                .data, .value, .free_map, .document_index, .value_extent, .catalog_index, .record_bundle, .allocator, .key, .checkpoint_slot, .commit_manifest => return error.UnexpectedNativePageKind,
            };
            count += 1;
            if (count > recordWalkLimit(checkpoint, self.header.page_size)) return error.InvalidNativePageChain;
        }
        if (coverage.unresolved != 0) return error.InvalidDocumentIndex;
        if (catalog_index != 0) {
            var indexed = checkpoint;
            indexed.document_index_root_page = catalog_index;
            _ = try self.collectDocumentIndexPages(indexed, reachable_pages, false, true, cancel);
            try self.validateCatalogIndexEntries(checkpoint, catalog_index, reachable_pages);
        }
        return count;
    }

    const extent_fanout = 64;
    const extent_header_size = 16;
    const extent_magic = "AFEXT003";
    const ExtentRef = struct { page: u64, len: u64, height: u8 = 0 };
    const ExtentNode = struct {
        height: u8,
        count: usize,
        children: [extent_fanout]ExtentRef = undefined,
    };

    fn decodeExtentNode(payload: []const u8, expected_len: u64) !ExtentNode {
        const decoded = try decodeExtentNodeWithLength(payload);
        if (decoded.length != expected_len) return error.InvalidNativeValueChain;
        return decoded.node;
    }

    fn decodeExtentNodeWithLength(payload: []const u8) !struct { node: ExtentNode, length: u64 } {
        if (payload.len < extent_header_size or !std.mem.eql(u8, payload[0..8], extent_magic)) return error.InvalidNativeValueChain;
        const height = payload[8];
        const count = std.mem.readInt(u16, payload[10..12], .little);
        if (height == 0 or height > 63 or count == 0 or count > extent_fanout or payload.len != extent_header_size + @as(usize, count) * 16)
            return error.InvalidNativeValueChain;
        if (builtin.is_test) _ = PageDecodeMetrics.extent_decodes.fetchAdd(1, .monotonic);
        var node = ExtentNode{ .height = height, .count = count };
        var total: u64 = 0;
        for (node.children[0..count], 0..) |*child, i| {
            const bytes = payload[extent_header_size + i * 16 ..][0..16];
            child.* = .{
                .page = std.mem.readInt(u64, bytes[0..8], .little),
                .len = std.mem.readInt(u64, bytes[8..16], .little),
                .height = height - 1,
            };
            if (child.page == 0 or child.len == 0) return error.InvalidNativeValueChain;
            total = std.math.add(u64, total, child.len) catch return error.InvalidNativeValueChain;
        }
        return .{ .node = node, .length = total };
    }

    fn writeExtentNode(self: *NativeFile, pages: *PageAllocator, batch: *PageWriteBatch, height: u8, children: []const ExtentRef) !ExtentRef {
        _ = self;
        if (height == 0 or height > 63 or children.len == 0 or children.len > extent_fanout) return error.InvalidNativeValueChain;
        var payload: [extent_header_size + extent_fanout * 16]u8 = @splat(0);
        @memcpy(payload[0..8], extent_magic);
        payload[8] = height;
        std.mem.writeInt(u16, payload[10..12], @intCast(children.len), .little);
        var len: u64 = 0;
        for (children, 0..) |child, i| {
            if (child.height + 1 != height or child.len == 0) return error.InvalidNativeValueChain;
            len = try std.math.add(u64, len, child.len);
            const bytes = payload[extent_header_size + i * 16 ..][0..16];
            std.mem.writeInt(u64, bytes[0..8], child.page, .little);
            std.mem.writeInt(u64, bytes[8..16], child.len, .little);
        }
        const page = try pages.allocate();
        try pages.noteValue(page, len);
        for (children) |child| try pages.retainValue(child.page);
        try batch.appendPage(page, .value_extent, payload[0 .. extent_header_size + children.len * 16]);
        return .{ .page = page, .len = len, .height = height };
    }

    /// Stream a packed tree through the same bounded frontier used by appends.
    /// Neither initial writes nor vacuum need an array of every leaf reference.
    fn writeValueTree(self: *NativeFile, pages: *PageAllocator, value: []const u8, options: WriteOptions) !ExtentRef {
        if (value.len == 0) return error.InvalidNativeValueChain;
        var builder = ExtentAppender{ .file = self, .pages = pages, .tail = undefined, .batch = .{ .file = self, .options = options, .diverting = pages.diverting } };
        defer builder.deinit();
        var offset: usize = 0;
        while (offset < value.len) {
            const end = @min(value.len, offset + self.maxValuePagePayloadBytes());
            try builder.pushValue(value[offset..end]);
            offset = end;
        }
        return try builder.finish();
    }

    fn writeCatalogValue(self: *NativeFile, pages: *PageAllocator, value: []const u8, options: WriteOptions) !u64 {
        self.direct_value_pages = true;
        defer self.direct_value_pages = false;
        return (try self.writeValueTree(pages, value, options)).page;
    }

    fn valueTreeRoot(self: *NativeFile, root: u64, len: usize, checkpoint: CheckpointSlot) !?ExtentRef {
        var scratch: [65536]u8 = undefined;
        const raw = try self.readPageInto(root, checkpoint, &scratch);
        if (raw[4] == @backingInt(PageKind.value_extent)) {
            const payload = try decodePagePayload(raw, .value_extent);
            const node = try decodeExtentNode(payload, len);
            return .{ .page = root, .len = len, .height = node.height };
        }
        const payload = try decodePagePayload(raw, .value);
        const leaf = try decodeValuePage(payload);
        if (leaf.next_page != 0) return null; // document/namespace linked value
        if (leaf.chunk.len != len or len == 0) return error.InvalidNativeValueChain;
        return .{ .page = root, .len = len };
    }

    /// A bounded right frontier: one unfinished node at each height. Sealed
    /// suffix nodes are written once and fed into the next level; existing
    /// full subtrees remain shared. Memory is O(fanout * height), independent
    /// of suffix length, and work is O(new leaves + height).
    const ExtentAppender = struct {
        const Level = struct {
            children: [extent_fanout]ExtentRef = undefined,
            count: usize = 0,
            original: ?ExtentRef = null,
            original_count: usize = 0,
            original_last: ExtentRef = undefined,
            unchanged: bool = true,
        };
        file: *NativeFile,
        pages: *PageAllocator,
        levels: std.ArrayListUnmanaged(Level) = .empty,
        tail: ExtentRef,
        batch: PageWriteBatch,

        fn pushValue(self: *ExtentAppender, value: []const u8) !void {
            const page = try self.pages.allocate();
            try self.pages.noteValue(page, value.len);
            try self.batch.appendValue(page, 0, value);
            try self.push(.{ .page = page, .len = value.len });
        }

        fn init(file: *NativeFile, pages: *PageAllocator, root: ExtentRef) !ExtentAppender {
            var result = ExtentAppender{ .file = file, .pages = pages, .tail = root, .batch = .{ .file = file, .diverting = pages.diverting } };
            errdefer result.deinit();
            var checkpoint = file.activeCheckpoint();
            checkpoint.page_count = pages.next_page_id;
            while (result.tail.height > 0) {
                const ref = result.tail;
                const payload = try file.readPagePayloadByKindAllocForCheckpoint(file.allocator, ref.page, .value_extent, checkpoint);
                defer file.allocator.free(payload);
                const node = try decodeExtentNode(payload, ref.len);
                if (node.height != ref.height) return error.InvalidNativeValueChain;
                try result.ensureLevel(ref.height);
                result.levels.items[ref.height] = .{
                    .children = node.children,
                    .count = node.count - 1,
                    .original = ref,
                    .original_count = node.count,
                    .original_last = node.children[node.count - 1],
                };
                result.tail = node.children[node.count - 1];
            }
            return result;
        }

        pub fn deinit(self: *ExtentAppender) void {
            self.levels.deinit(self.file.allocator);
        }

        fn ensureLevel(self: *ExtentAppender, height: usize) !void {
            if (height >= 64) return error.InvalidNativeValueChain;
            if (height < self.levels.items.len) return;
            const before = self.levels.items.len;
            try self.levels.resize(self.file.allocator, height + 1);
            @memset(self.levels.items[before..], .{});
        }

        fn push(self: *ExtentAppender, child: ExtentRef) anyerror!void {
            if (child.height >= 63) return error.InvalidNativeValueChain;
            const height = child.height + 1;
            try self.ensureLevel(height);
            const level = &self.levels.items[height];
            if (level.original == null or level.count + 1 != level.original_count or
                !std.meta.eql(child, level.original_last)) level.unchanged = false;
            level.children[level.count] = child;
            level.count += 1;
            if (level.count == extent_fanout) {
                const parent = try self.seal(height);
                try self.push(parent);
            }
        }

        fn seal(self: *ExtentAppender, height: u8) !ExtentRef {
            const level = &self.levels.items[height];
            const ref = if (level.unchanged and level.original != null and level.count == level.original_count)
                level.original.?
            else
                try self.file.writeExtentNode(self.pages, &self.batch, height, level.children[0..level.count]);
            level.* = .{};
            return ref;
        }

        fn finish(self: *ExtentAppender) !ExtentRef {
            const root = try self.finishTree();
            // Callers may read newly built trees, then publish their roots.
            // Never return a root while any of its pages remain buffered.
            try self.batch.flush();
            return root;
        }

        fn finishTree(self: *ExtentAppender) !ExtentRef {
            var height: usize = 1;
            while (height < self.levels.items.len) : (height += 1) {
                const level = &self.levels.items[height];
                if (level.count == 0) continue;
                var higher_pending = false;
                for (self.levels.items[height + 1 ..]) |higher| {
                    if (higher.count != 0) higher_pending = true;
                }
                // Do not introduce a unary root above the final subtree.
                if (!higher_pending and level.count == 1) return level.children[0];
                const ref = try self.seal(@intCast(height));
                if (!higher_pending) return ref;
                try self.push(ref);
            }
            return error.InvalidNativeValueChain;
        }
    };

    /// Transaction-owned append state: retain the partial leaf and unfinished
    /// right frontier, stream full leaves once, and seal ancestors only at a
    /// visibility barrier. Abort/overwrite discard buffers without flushing.
    const CatalogAppendState = struct {
        builder: ExtentAppender,
        tail: []u8,
        used: usize = 0,
        len: usize,

        fn create(file: *NativeFile, pages: *PageAllocator, entry: CatalogEntry) !*CatalogAppendState {
            const self = try file.allocator.create(CatalogAppendState);
            errdefer file.allocator.destroy(self);
            self.* = .{
                .builder = .{ .file = file, .pages = pages, .tail = undefined, .batch = .{ .file = file, .diverting = pages.diverting } },
                .tail = try file.allocator.alloc(u8, file.maxValuePagePayloadBytes()),
                .len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len,
            };
            errdefer self.builder.deinit();
            errdefer file.allocator.free(self.tail);
            if (entry.external_value_root_page == 0) {
                @memcpy(self.tail[0..entry.value.len], entry.value);
                self.used = entry.value.len;
            } else {
                var checkpoint = file.activeCheckpoint();
                checkpoint.page_count = pages.next_page_id;
                const root = (try file.valueTreeRoot(entry.external_value_root_page, entry.external_value_len, checkpoint)) orelse return error.InvalidNativeValueChain;
                self.builder = try ExtentAppender.init(file, pages, root);
                const payload = try file.readPagePayloadByKindAllocForCheckpoint(file.allocator, self.builder.tail.page, .value, checkpoint);
                defer file.allocator.free(payload);
                const leaf = try decodeValuePage(payload);
                if (leaf.next_page != 0 or leaf.chunk.len != self.builder.tail.len) return error.InvalidNativeValueChain;
                if (leaf.chunk.len == file.maxValuePagePayloadBytes()) {
                    try self.builder.push(self.builder.tail);
                } else {
                    @memcpy(self.tail[0..leaf.chunk.len], leaf.chunk);
                    self.used = leaf.chunk.len;
                }
            }
            return self;
        }

        fn append(self: *CatalogAppendState, suffix: []const u8) !void {
            self.builder.file.direct_value_pages = true;
            defer self.builder.file.direct_value_pages = false;
            const len = try std.math.add(usize, self.len, suffix.len);
            if (len > std.math.maxInt(u32)) return error.RecordTooLarge;
            const capacity = self.builder.file.maxValuePagePayloadBytes();
            var offset: usize = 0;
            while (offset < suffix.len) {
                const n = @min(capacity - self.used, suffix.len - offset);
                @memcpy(self.tail[self.used..][0..n], suffix[offset..][0..n]);
                self.used += n;
                offset += n;
                if (self.used == capacity) {
                    try self.builder.pushValue(self.tail[0..self.used]);
                    self.used = 0;
                }
            }
            self.len = len;
        }

        fn finish(self: *CatalogAppendState) !ExtentRef {
            self.builder.file.direct_value_pages = true;
            defer self.builder.file.direct_value_pages = false;
            if (self.used != 0) {
                try self.builder.pushValue(self.tail[0..self.used]);
                self.used = 0;
            }
            return try self.builder.finish();
        }

        fn destroy(self: *CatalogAppendState) void {
            const allocator = self.builder.file.allocator;
            self.builder.deinit();
            allocator.free(self.tail);
            allocator.destroy(self);
        }
    };

    fn appendCatalogValueTree(self: *NativeFile, pages: *PageAllocator, entry: CatalogEntry, suffix: []const u8) !u64 {
        const root = if (entry.external_value_root_page != 0)
            (try self.valueTreeRoot(entry.external_value_root_page, entry.external_value_len, self.activeCheckpoint())) orelse return error.InvalidNativeValueChain
        else if (entry.value.len > 0)
            try self.writeValueTree(pages, entry.value, .{})
        else
            return (try self.writeValueTree(pages, suffix, .{})).page;
        if (suffix.len == 0) return root.page;
        var appender = try ExtentAppender.init(self, pages, root);
        defer appender.deinit();
        var checkpoint = self.activeCheckpoint();
        checkpoint.page_count = pages.next_page_id;
        const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, appender.tail.page, .value, checkpoint);
        defer self.allocator.free(payload);
        const tail = try decodeValuePage(payload);
        if (tail.next_page != 0 or tail.chunk.len != appender.tail.len) return error.InvalidNativeValueChain;
        const take = @min(self.maxValuePagePayloadBytes() - tail.chunk.len, suffix.len);
        if (take == 0) {
            try appender.push(appender.tail);
        } else {
            const combined = try self.allocator.alloc(u8, tail.chunk.len + take);
            defer self.allocator.free(combined);
            @memcpy(combined[0..tail.chunk.len], tail.chunk);
            @memcpy(combined[tail.chunk.len..], suffix[0..take]);
            try appender.pushValue(combined);
        }
        var offset = take;
        while (offset < suffix.len) {
            const end = @min(suffix.len, offset + self.maxValuePagePayloadBytes());
            try appender.pushValue(suffix[offset..end]);
            offset = end;
        }
        return (try appender.finish()).page;
    }

    fn readExtentRangeBuffered(self: *NativeFile, ref: ExtentRef, checkpoint: CheckpointSlot, start: usize, out: []u8, reader: *ValuePageReader, ahead: usize) !void {
        if (start > ref.len or out.len > ref.len - start) return error.InvalidNativeValueChain;
        if (ref.height == 0) {
            const payload = try reader.readPayload(self, checkpoint, ref.page, ahead, .value);
            const leaf = try decodeValuePage(payload);
            if (leaf.next_page != 0 or leaf.chunk.len != ref.len) return error.InvalidNativeValueChain;
            @memcpy(out, leaf.chunk[start..][0..out.len]);
            return;
        }
        const payload = try reader.readPayload(self, checkpoint, ref.page, 1, .value_extent);
        if (reader.lease) |lease| if (lease.extent_entries != null) {
            if (lease.extent_length != ref.len or lease.extent_height != ref.height) return error.InvalidNativeValueChain;
            return self.readCachedExtentRange(lease, checkpoint, start, out, reader);
        };
        const node = try reader.extentNode(payload, ref.len);
        if (node.height != ref.height) return error.InvalidNativeValueChain;
        return self.readExtentNodeRange(node, checkpoint, start, out, reader);
    }

    /// Retain the immutable navigation owner across child reads, which replace
    /// the reader's current lease. Pins stay charged to the cache even if evicted.
    /// Only overlapping children are materialized; no whole-node copy is needed.
    fn readCachedExtentRange(self: *NativeFile, lease: *PageCache.RawView, checkpoint: CheckpointSlot, start: usize, out: []u8, reader: *ValuePageReader) anyerror!void {
        const entries = lease.extent_entries.?;
        const first = reader.extentStart(start);
        _ = lease.references.fetchAdd(1, .monotonic);
        defer self.page_cache.releaseRaw(self.allocator, lease);
        var offset = first.offset;
        var written: usize = 0;
        const range_end = start + out.len;
        for (entries[first.index..], first.index..) |entry, i| {
            if (offset >= range_end) break;
            const from: usize = @intCast(@max(offset, start) - offset);
            const count: usize = @intCast(@min(entry.end, range_end) - @max(offset, start));
            var ahead: usize = 1;
            if (lease.extent_height == 1) {
                var covered = entry.end;
                while (ahead < 16 and i + ahead < entries.len and covered < range_end) : (ahead += 1) {
                    const next = entries[i + ahead];
                    if (next.page <= entry.page or next.page - entry.page != ahead) break;
                    covered = next.end;
                }
            }
            try self.readExtentRangeBuffered(.{ .page = entry.page, .len = entry.end - offset, .height = lease.extent_height - 1 }, checkpoint, from, out[written..][0..count], reader, ahead);
            written += count;
            offset = entry.end;
            if (written == out.len) break;
        }
        if (written != out.len) return error.InvalidNativeValueChain;
    }

    fn readExtentNodeRange(self: *NativeFile, node: ExtentNode, checkpoint: CheckpointSlot, start: usize, out: []u8, reader: *ValuePageReader) anyerror!void {
        // Copy the parent node and resolve its first child before recursion
        // releases the parent's lease. No borrowed navigation escapes a read.
        const first = reader.extentStart(start);
        var offset = first.offset;
        var written: usize = 0;
        for (node.children[first.index..node.count], first.index..) |child, i| {
            const end = offset + child.len;
            if (end > start and offset < start + out.len) {
                const from: usize = @intCast(@max(offset, start) - offset);
                const count: usize = @intCast(@min(end, start + out.len) - @max(offset, start));
                const child_ahead = if (child.height == 0) extentLeafReadAhead(node.children[0..node.count], i, start + out.len - offset) else 1;
                try self.readExtentRangeBuffered(child, checkpoint, from, out[written..][0..count], reader, child_ahead);
                written += count;
            }
            offset = end;
            if (written == out.len) break;
        }
        if (written != out.len) return error.InvalidNativeValueChain;
    }

    fn validateExtent(self: *NativeFile, ref: ExtentRef, checkpoint: CheckpointSlot, reachable: *ReachablePageSet) !void {
        try self.markReachablePage(reachable, ref.page, checkpoint.page_count);
        if (ref.height == 0) {
            const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, ref.page, .value, checkpoint);
            defer self.allocator.free(payload);
            const leaf = try decodeValuePage(payload);
            if (leaf.next_page != 0 or leaf.chunk.len != ref.len) return error.InvalidNativeValueChain;
            return;
        }
        const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, ref.page, .value_extent, checkpoint);
        defer self.allocator.free(payload);
        const node = try decodeExtentNode(payload, ref.len);
        if (node.height != ref.height) return error.InvalidNativeValueChain;
        for (node.children[0..node.count]) |child| try self.validateExtent(child, checkpoint, reachable);
    }

    /// Large document ranges need logarithmic seeks, including fields near the
    /// end. Existing readers/reclamation understand both extent trees and old
    /// chains. Keep small values as chains to avoid another index page.
    fn writeDocumentValue(self: *NativeFile, pages: *PageAllocator, value: []const u8) !u64 {
        if (value.len >= 64 * 1024) return (try self.writeValueTree(pages, value, .{})).page;
        return self.writeValuePagesAllocated(pages, value);
    }

    fn writeValuePagesAllocated(self: *NativeFile, page_allocator: *PageAllocator, value: []const u8) !u64 {
        if (value.len == 0) return error.InvalidNativeValueChain;
        const chunk_size = self.maxValuePagePayloadBytes();
        if (chunk_size == 0) return error.InvalidNativePageLength;
        // See `PageAllocator.diverting`'s own doc comment: this batch's
        // pages are the one page-shaped exception a diverting transactional
        // commit still makes (an external value chain under the inline
        // threshold, via `writeDocumentValue`/`writeCatalogValue`). Unlike
        // `ExtentAppender.init`/`writeValueTree` (the >=64 KiB value-tree
        // path), this standalone batch literal was never threaded with
        // `page_allocator.diverting` when 4a7817f3dd scoped diversion to
        // the owning allocator -- it silently kept `diverting`'s `false`
        // default, so every sub-64-KiB external value always took the
        // real-pwrite branch regardless of `self.file.redo`, even during an
        // ordinary diverting commit. That starves the redo log of the
        // page-shaped bytes `maybeAutoCheckpointRedoLog`'s own 25%-remaining
        // backstop is supposed to react to, so a write pattern built almost
        // entirely from such values never opportunistically checkpoints at
        // all and instead runs straight into the page/storage budget wall.
        var batch = PageWriteBatch{ .file = self, .diverting = page_allocator.diverting };
        var page = try page_allocator.allocate();
        const root = page;
        var offset: usize = 0;
        while (offset < value.len) {
            const len = @min(chunk_size, value.len - offset);
            // One-page lookahead preserves arbitrary free-page allocation
            // order without retaining an array of every page in the chain.
            const next = if (offset + len < value.len) try page_allocator.allocate() else 0;
            try page_allocator.noteValue(page, value.len - offset);
            if (next != 0) try page_allocator.retainValue(next);
            try batch.appendValue(page, next, value[offset..][0..len]);
            page = next;
            offset += len;
        }
        try batch.flush();
        return root;
    }

    fn writeValuePageChunk(self: *NativeFile, page_ids: []const u64, page_index: usize, chunk: []const u8, options: WriteOptions) !void {
        if (chunk.len == 0 or chunk.len > self.maxValuePagePayloadBytes()) return error.InvalidNativeValueChain;
        const next_page_id = if (page_index + 1 < page_ids.len) page_ids[page_index + 1] else 0;
        var batch = PageWriteBatch{ .file = self, .options = options };
        try batch.appendValue(page_ids[page_index], next_page_id, chunk);
        try batch.flush();
    }

    /// A non-durable (`changed == false`) commit attempt never adopts its own
    /// `next.page_count` into `self.header` -- `publishCheckpoint` is only
    /// reached for a commit that durably publishes. But `self.manifest_builder
    /// .reserved_page`, once set, deliberately survives across every commit
    /// in the since-last-durable window regardless of whether each one
    /// durably publishes (that is the "only reserve once per window" design
    /// in `flushTransactionWrites`). If an earlier attempt's reservation is
    /// still pending because every attempt since has been a no-op, a brand
    /// new `PageAllocator` built from the *same*, never-advanced
    /// `checkpoint.page_count` would otherwise start handing out that exact
    /// page id again -- to `next.free_map_root_page`, to a catalog edit, to
    /// anything -- stepping on a page `tryBuildCommitManifest` is still
    /// going to claim once a real commit finally lands. Starting past it
    /// makes that impossible without needing to know whether this specific
    /// checkpoint's `page_count` is durable or merely an abandoned attempt's
    /// in-memory echo.
    fn manifestSafeNextPageId(self: *const NativeFile, page_count: u64) u64 {
        if (!self.manifest_commits_enabled) return page_count;
        const reserved = self.manifest_builder.reserved_page orelse return page_count;
        return @max(page_count, reserved + 1);
    }

    fn pageAllocatorFromFreeMap(self: *NativeFile, checkpoint: CheckpointSlot) !PageAllocator {
        return self.pageAllocatorFromFreeMapWithProof(checkpoint, !self.artifact_lease_transaction);
    }

    /// §9 (redo + indexed reclamation): a diverting commit (this file has
    /// a redo log and this is not `checkpointRedoLog`'s own transaction)
    /// never builds a real copy-on-write page for its logical roots (see
    /// `flushTransactionWrites`'s own `diverting` check), so loading the
    /// `allocator_v4.State` ledger, verifying free pages, or draining a
    /// retirement backlog for it would be pure, repeated wasted work on
    /// every foreground commit -- exactly the per-commit cost
    /// `checkpointRedoLog`'s own batched, undiverted transaction exists to
    /// amortize instead (same `pageAllocatorFromFreeMap` call, reached
    /// through `transactionWrites` there too, but with `checkpointing =
    /// true` so the real indexed branch runs). Only `transactionWrites`
    /// takes this shortcut: a direct caller like `reclaimPagesImpl` (owner
    /// background retirement) or `initializeIndexedAllocator` (bootstrap)
    /// calls `pageAllocatorFromFreeMap(WithProof)` itself and always gets
    /// the real ledger -- this only ever defers page work for the
    /// ordinary per-write commit path, never for an explicit
    /// reclaim/maintenance pass, which must keep draining whatever
    /// `checkpointRedoLog` already retired regardless of this file's
    /// redo-log state.
    ///
    /// The one page-shaped exception a diverting commit still makes --
    /// `stageMutation`'s own external value chains, written through this
    /// same allocator at stage time -- only ever needs a fresh page id,
    /// never a reused one and never ledger bookkeeping, so an empty free
    /// list with no ledger attached serves it exactly as well as the real
    /// thing would, at a fraction of the cost.
    fn pageAllocatorForDivertingCommit(self: *NativeFile, checkpoint: CheckpointSlot) !PageAllocator {
        return .{
            .file = self,
            .free_pages = try self.allocator.alloc(u64, 0),
            .append_only = true,
            .diverting = true,
            .next_page_id = self.manifestSafeNextPageId(checkpoint.page_count),
        };
    }

    fn pageAllocatorFromFreeMapWithProof(self: *NativeFile, checkpoint: CheckpointSlot, require_reuse_proof: bool) !PageAllocator {
        // Read leases and their retirement must not force a whole-file proof.
        // Unverified housekeeping only extends the file; no existing page is
        // overwritten. Bounded owners retain ordinary proof/admission so a
        // read lease can use their free pool rather than exceed the hard cap.
        const verify = require_reuse_proof or self.max_file_bytes != null;
        if (self.header.indexed_reclamation) {
            if (self.checkpoint_publication_uncertain) return error.OutcomeReconciliationRequired;
            const state = try self.loadLedger(checkpoint);
            state.incremental = self.reserve_retirement_capacity or self.incremental_checkpoints;
            errdefer self.invalidateLedger();
            if (verify and (!self.defer_allocator_verification or self.max_file_bytes != null) and !self.free_pages_verified and checkpoint.free_map_root_page != 0) {
                _ = try self.validateIndexedAllocator(checkpoint, state, self.allocator_cancel_token);
                self.free_pages_verified = true;
            }
            // Nothing for the reuse-lock machinery to gain this commit: no
            // page is already free to hand out (`state.free_pages == 0`) and
            // no retirement backlog exists to promote (all three heaps
            // empty, so `drainRetirement` below would immediately break out
            // of every one of its loops regardless of the frontier it had).
            // Skip the whole cross-process reuse-lock acquisition --
            // `acquireDataRewriteLock` plus the reader-epoch scan -- for a
            // purely additive (append-only) commit; a later commit that
            // actually retires something (free_pages or any heap becomes
            // non-empty) stops skipping on its own, so this can never starve
            // retirement. Never skip while a window from an *outer*,
            // already-open nested call is live (`reader_window_depth != 0`):
            // that window is already open for free, so there is no cost to
            // avoid and no reason to bypass it.
            // This snapshot (`state`, from `loadLedger` above) must stay the
            // freshest truth for the entire call: nothing else may mutate
            // this file's ledger/free-map/retirement heaps between here and
            // `drainRetirement` below using it. That is no longer "this
            // function already runs under the caller's lock, end of story"
            // once a commit can have that lock released mid-publish (WS2,
            // `Store.commit_in_sync`/`lockStoreExclusive` in docstore.zig):
            // every Store entry point that reaches this function (a
            // foreground commit's `beginTransaction`, or a reclaim/vacuum
            // pass) now waits out another commit's released sync window
            // before calling in, under the same mutex, so this remains a
            // single point-in-time decision made and used without any
            // other thread able to touch this file's allocator state in
            // between. Re-verify there, not here: `NativeFile` stays
            // agnostic of what lock (if any) a caller above it holds.
            const has_retirement_backlog = state.free_pages != 0 or state.heap.count() != 0 or
                state.metadata_heap.count() != 0 or state.chains_heap.count() != 0;
            const skip_reuse_lock = !has_retirement_backlog and self.reader_window_depth == 0;
            const coordinated = if (skip_reuse_lock) false else try self.beginReaderWindow();
            errdefer if (coordinated) self.endReaderWindow();
            const lock = if (skip_reuse_lock or coordinated) null else self.acquireEpochReuseLock("pageAllocatorFromFreeMapWithProof(indexed)") catch |err| switch (err) {
                error.WouldBlock => null,
                else => return err,
            };
            errdefer if (lock) |held| {
                held.release(self.runtimeIo());
                self.epoch_window = null;
            };
            // `retirement_work_pages` is the *background* maintenance budget
            // (reclaimPagesForMaintenanceWithCancel passes it to its own,
            // separate drainRetirement call at full size); its default of
            // 128 is also `reclamation.Options.validate`'s floor for a valid
            // configuration, so it can never be the all-the-way-to-zero
            // sentinel the two other foreground-suppression call sites
            // (reclaimPagesImpl, preparePublicationSequence) use to skip
            // this drain entirely. Cap what this specific inline, every-
            // commit call reads from cold pages for, instead of handing it
            // the full background budget: every ordinary write was paying
            // for up to 128 pages worth of reclamation scan on the
            // foreground path regardless of how small an actual backlog it
            // found. `@min` keeps every existing zero-budget suppression
            // working exactly as before (min(0, cap) is still 0) while
            // bounding the normal (128-budget) case to a few pages per
            // commit; drainRetirement's own heaps already carry the cursor
            // forward between calls; nothing here re-scans from the start.
            // perf/lwa-lease-fold: "fence held" -- the exclusive scan fence
            // this drain's own comment (above `has_retirement_backlog`)
            // requires before touching retirement data structures -- is
            // `lock != null or coordinated`, the same condition `can_reuse`
            // below already uses for the identical reason. It is not the
            // same thing as `self.epoch_window != null`: a direct
            // `acquireEpochReuseLock` (the `lock` branch) always takes the
            // exclusive inode lock first, regardless of whether
            // `regionForInode()` finds a shared region to populate
            // `epoch_window` from -- no `reader_coordinator` configured
            // (the common, single-process case) means no cross-process
            // readers to fence, not "fence not held" or "readers unknown":
            // in-process readers stay tracked unconditionally (`reuseFrontier`/
            // `metadataReuseFrontier`'s own reader-pin terms, unrelated to
            // `epoch_window`), so the frontier `drainRetirement` compares
            // against is already correct either way.
            const fence_held = lock != null or (coordinated and self.reader_window_lock != null);
            _ = try self.drainRetirement(state, checkpoint, @min(self.retirement_work_pages, foreground_retirement_cap_pages), fence_held);
            const can_reuse = self.free_pages_verified and fence_held;
            return .{ .file = self, .free_pages = &.{}, .next_page_id = self.manifestSafeNextPageId(checkpoint.page_count), .ledger = state, .can_reuse = can_reuse, .reuse_retry_enabled = self.free_pages_verified and !can_reuse, .coordinated_reader_window = coordinated, .data_lock_file = lock };
        }
        var free_pages = try self.readFreePagesAlloc(checkpoint);
        errdefer self.allocator.free(free_pages);
        if (verify and (!self.defer_allocator_verification or self.max_file_bytes != null) and !self.free_pages_verified) {
            try self.validateFreePagesSafeForCheckpointSlots(free_pages);
            self.free_pages_verified = true;
        }
        // Same registry-backed exclusive grant as the indexed branch above
        // (`acquireEpochReuseLock`), not a direct `acquireDataRewriteLock`:
        // a non-indexed file can just as well have another NativeFile on
        // the same inode in this process (an `externally_locked` sibling
        // Store, a reader doing `acquireReaderFence`), and a raw
        // `acquireDataRewriteLock` here would self-conflict against it the
        // same way the old per-commit epoch-reuse lock did.
        var data_lock_file: ?inode_lock.Handle = null;
        if (self.free_pages_verified and free_pages.len > 0) {
            data_lock_file = self.acquireInodeLock(.exclusive, false, false, "pageAllocatorFromFreeMapWithProof(non-indexed)") catch |err| switch (err) {
                error.WouldBlock => blk: {
                    self.allocator.free(free_pages);
                    free_pages = try self.allocator.alloc(u64, 0);
                    break :blk null;
                },
                else => return err,
            };
        }
        return .{
            .file = self,
            .free_pages = free_pages,
            .append_only = !self.free_pages_verified,
            .next_page_id = self.manifestSafeNextPageId(checkpoint.page_count),
            .data_lock_file = data_lock_file,
        };
    }

    fn readFreePagesAlloc(self: *NativeFile, checkpoint: CheckpointSlot) ![]u64 {
        if (checkpoint.free_map_root_page == 0) return try self.allocator.alloc(u64, 0);

        const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
        defer self.allocator.free(payload);
        const free_map = try decodeFreeMapAlloc(self.allocator, payload, checkpoint.page_count, self.header.redo_log_capacity != 0);
        return free_map.free_pages;
    }

    fn writeFreeMapPage(self: *NativeFile, page_id: u64, covered_page_count: u64, free_pages: []const u64) !void {
        const payload = try encodeFreeMapAlloc(self.allocator, self.header.page_size, covered_page_count, free_pages);
        defer self.allocator.free(payload);
        try self.writePage(page_id, .free_map, payload);
    }

    fn computeFreePagesForPublishedCheckpoint(self: *NativeFile, next: CheckpointSlot, previous: CheckpointSlot) ![]u64 {
        var reachable_pages = std.AutoHashMapUnmanaged(u64, void){};
        defer reachable_pages.deinit(self.allocator);

        try self.collectCheckpointReachablePages(next, &reachable_pages);
        if (validCheckpointSlot(previous)) {
            try self.collectCheckpointReachablePages(previous, &reachable_pages);
        }

        var free_pages = std.ArrayListUnmanaged(u64).empty;
        errdefer free_pages.deinit(self.allocator);

        const max_entries = maxFreeMapEntries(self.header.page_size);
        // Pages [0, reserved_header_pages) are the header and the two
        // dedicated checkpoint slot pages, never part of any reachable
        // catalog/document/free-map chain and so never caught by the
        // `reachable_pages` check below. Starting at 1 (correct for v3/v7,
        // which reserved only page 0) would otherwise offer a live slot
        // page up for reuse as an ordinary data page the moment this free
        // map's covered range needs one.
        var page_id: u64 = reserved_header_pages;
        while (page_id < next.page_count and free_pages.items.len < max_entries) : (page_id += 1) {
            if (!reachable_pages.contains(page_id)) {
                try free_pages.append(self.allocator, page_id);
            }
        }

        return try free_pages.toOwnedSlice(self.allocator);
    }

    fn collectCheckpointReachablePages(self: *NativeFile, checkpoint: CheckpointSlot, out: *ReachablePageSet) !void {
        var checkpoint_pages = std.AutoHashMapUnmanaged(u64, void){};
        defer checkpoint_pages.deinit(self.allocator);

        _ = try self.countReachableChainPagesForCheckpoint(.catalog, checkpoint.catalog_root_page, checkpoint, &checkpoint_pages, null);
        _ = try self.countReachableChainPagesForCheckpoint(.catalog, checkpoint.index_catalog_root_page, checkpoint, &checkpoint_pages, null);
        _ = try self.countReachableChainPagesForCheckpoint(.catalog, checkpoint.namespace_directory_root_page, checkpoint, &checkpoint_pages, null);
        _ = try self.countReachableChainPagesForCheckpoint(.document, checkpoint.document_root_page, checkpoint, &checkpoint_pages, null);
        _ = try self.collectDocumentIndexPages(checkpoint, &checkpoint_pages, false, true, null);
        if (checkpoint.free_map_root_page != 0) {
            try self.markReachablePage(&checkpoint_pages, checkpoint.free_map_root_page, checkpoint.page_count);
        }

        var it = checkpoint_pages.iterator();
        while (it.next()) |entry| {
            try out.put(self.allocator, entry.key_ptr.*, {});
        }
    }

    fn collectDocumentIndexPages(
        self: *NativeFile,
        checkpoint: CheckpointSlot,
        reachable_pages: *ReachablePageSet,
        validate_documents: bool,
        validate_key_references: bool,
        cancel: ?*const maintenance.CancelToken,
    ) !u64 {
        if (checkpoint.document_index_root_page == 0) return 0;
        var records = RecordPageReader{};
        defer records.deinit(self.allocator);
        return try self.collectDocumentIndexSubtree(
            checkpoint,
            checkpoint.document_index_root_page,
            null,
            null,
            reachable_pages,
            validate_documents,
            validate_key_references,
            cancel,
            0,
            &records,
        );
    }

    fn collectDocumentIndexSubtree(
        self: *NativeFile,
        checkpoint: CheckpointSlot,
        page_id: u64,
        lower: ?[]const u8,
        upper: ?[]const u8,
        reachable_pages: *ReachablePageSet,
        validate_documents: bool,
        validate_key_references: bool,
        cancel: ?*const maintenance.CancelToken,
        depth: usize,
        records: *RecordPageReader,
    ) !u64 {
        if (depth > 64) return error.InvalidDocumentIndex;
        if (cancel) |token| try token.check();
        try self.markReachablePage(reachable_pages, page_id, checkpoint.page_count);
        var node = try self.readDocumentIndexNode(page_id, checkpoint);
        defer node.deinit(self.allocator);
        if (validate_key_references) for (node.key_pages.?) |page| {
            if (page != 0 and !reachable_pages.contains(page)) return error.InvalidDocumentIndex;
        };
        for (node.keys, 0..) |key, i| {
            if (i > 0 and std.mem.order(u8, node.keys[i - 1], key) != .lt) return error.InvalidDocumentIndex;
            if (lower) |bound| if (std.mem.order(u8, key, bound) == .lt) return error.InvalidDocumentIndex;
            if (upper) |bound| if (std.mem.order(u8, key, bound) != .lt) return error.InvalidDocumentIndex;
        }

        switch (node.kind) {
            .leaf => {
                if (validate_documents) {
                    for (node.keys, node.pointers) |key, document_page_id| {
                        if (!reachable_pages.contains(document_page_id)) return error.InvalidDocumentIndex;
                        const payload = try records.read(self, self.allocator, checkpoint, document_page_id, .document);
                        const entry = try decodeDocumentEntry(payload);
                        if (!std.mem.eql(u8, key, entry.key)) return error.InvalidDocumentIndex;
                    }
                }
                return 1;
            },
            .internal => {
                var count: u64 = 1;
                for (node.pointers, 0..) |child, i| {
                    if (physicalPage(child) == 0 or physicalPage(child) >= checkpoint.page_count) return error.InvalidPageId;
                    count += try self.collectDocumentIndexSubtree(
                        checkpoint,
                        child,
                        if (i == 0) lower else node.keys[i - 1],
                        if (i == node.keys.len) upper else node.keys[i],
                        reachable_pages,
                        validate_documents,
                        validate_key_references,
                        cancel,
                        depth + 1,
                        records,
                    );
                }
                return count;
            },
        }
    }

    /// Proves coverage in one index scan and one newest-first history scan.
    fn validateDocumentIndexCoverage(self: *NativeFile, checkpoint: CheckpointSlot, cancel: ?*const maintenance.CancelToken) !void {
        var coverage = HistoryIndexCoverage{};
        defer coverage.deinit(self.allocator);
        try coverage.initIndex(self, checkpoint, checkpoint.document_index_root_page, cancel);
        var records = RecordPageReader{};
        defer records.deinit(self.allocator);
        var page_id = checkpoint.document_root_page;
        var walked: u64 = 0;
        while (page_id != 0) {
            if (cancel) |token| try token.check();
            const payload = try records.read(self, self.allocator, checkpoint, page_id, .document);
            const entry = try decodeDocumentEntry(payload);
            _ = try coverage.observe(self, checkpoint, .document, page_id, entry.key, entry.is_delete);
            page_id = entry.previous_page;
            walked += 1;
            if (walked > recordWalkLimit(checkpoint, self.header.page_size)) return error.InvalidNativePageChain;
        }
        if (coverage.unresolved != 0) return error.InvalidDocumentIndex;
    }

    fn collectAllValidCheckpointReachablePages(self: *NativeFile, out: *ReachablePageSet) !void {
        const file_size = (try self.file.stat(self.runtimeIo())).size;
        for (self.header.checkpoints) |slot| {
            if (!validCheckpointSlot(slot)) continue;
            const expected_size = checkpointPrefixSize(slot, self.header.page_size) catch continue;
            if (expected_size > file_size) continue;
            try self.collectCheckpointReachablePages(slot, out);
        }
    }

    fn validateFreePagesSafeForCheckpointSlots(self: *NativeFile, free_pages: []const u64) !void {
        // Append-only writes have nothing to reclaim. Walking both checkpoint
        // graphs here makes each small catalog write proportional to history.
        // Nonempty free maps still require the full protected-page proof.
        if (free_pages.len == 0) return;
        var window: AllocatorProofWindow = undefined;
        window.initInto(self);
        defer window.deinit();
        var protected_pages = std.AutoHashMapUnmanaged(u64, void){};
        defer protected_pages.deinit(self.allocator);

        try self.collectAllValidCheckpointReachablePages(&protected_pages);
        for (free_pages) |page_id| {
            if (protected_pages.contains(page_id)) return error.InvalidNativeFreeMap;
        }
    }

    fn readValuePagesAlloc(self: *NativeFile, allocator: Allocator, root_page_id: u64, value_len: usize) ![]u8 {
        return try self.readValuePagesAtCheckpointAlloc(allocator, root_page_id, value_len, self.activeCheckpoint());
    }

    pub fn readValuePagesAtCheckpointAlloc(self: *NativeFile, allocator: Allocator, root_page_id: u64, value_len: usize, checkpoint: CheckpointSlot) ![]u8 {
        var cursor: ValueChunkCursor = undefined;
        try cursor.initInto(self, root_page_id, value_len, checkpoint, true);
        defer cursor.deinit();
        const out = try allocator.alloc(u8, value_len);
        errdefer allocator.free(out);
        var offset: usize = 0;
        while (try cursor.next(null)) |chunk| {
            @memcpy(out[offset..][0..chunk.len], chunk);
            offset += chunk.len;
        }
        if (offset != value_len) return error.InvalidNativeValueChain;
        return out;
    }

    fn readValuePagesRangeAlloc(
        self: *NativeFile,
        allocator: Allocator,
        root_page_id: u64,
        value_len: usize,
        range_start: usize,
        range_len: usize,
        checkpoint: CheckpointSlot,
    ) ![]u8 {
        if (value_len == 0 or root_page_id == 0) return error.InvalidNativeValueChain;
        if (range_start > value_len or range_len > value_len - range_start) return error.EndOfStream;
        const out = try allocator.alloc(u8, range_len);
        errdefer allocator.free(out);
        try self.readValuePagesRangeInto(root_page_id, value_len, range_start, out, checkpoint);
        return out;
    }

    fn readValuePagesRangeInto(self: *NativeFile, root_page_id: u64, value_len: usize, range_start: usize, out: []u8, checkpoint: CheckpointSlot) !void {
        var reader: ValuePageReader = undefined;
        reader.init();
        defer reader.deinit(self);
        return self.readValuePagesRangeIntoReader(root_page_id, value_len, range_start, out, checkpoint, &reader, null);
    }
    const LinkedRangeCursor = struct { root: u64 = 0, page: u64 = 0, offset: usize = 0, visited: u64 = 0 };
    fn readValuePagesRangeIntoReader(self: *NativeFile, root_page_id: u64, value_len: usize, range_start: usize, out: []u8, checkpoint: CheckpointSlot, reader: *ValuePageReader, cursor: ?*LinkedRangeCursor) !void {
        const range_len = out.len;
        if (range_start > value_len or range_len > value_len - range_start) return error.EndOfStream;
        if (value_len == 0 or root_page_id == 0) return error.InvalidNativeValueChain;
        if (range_len == 0) return;

        if (cursor) |state| if (state.root == root_page_id and range_start >= state.offset) {
            return self.readLinkedRangeIntoReader(root_page_id, value_len, range_start, out, checkpoint, reader, cursor, state.page, state.offset, null);
        };
        const root_raw = try reader.read(self, checkpoint, root_page_id, 1);
        if (root_raw[4] == @backingInt(PageKind.value_extent)) {
            const payload = try reader.payload(root_raw, .value_extent);
            if (reader.lease) |lease| if (lease.extent_entries != null) {
                if (lease.extent_length != value_len) return error.InvalidNativeValueChain;
                return self.readCachedExtentRange(lease, checkpoint, range_start, out, reader);
            };
            const node = try reader.extentNode(payload, value_len);
            return self.readExtentNodeRange(node, checkpoint, range_start, out, reader);
        }
        const root_leaf = try decodeValuePage(try reader.payload(root_raw, .value));
        if (root_leaf.next_page == 0) {
            if (root_leaf.chunk.len != value_len) return error.InvalidNativeValueChain;
            @memcpy(out, root_leaf.chunk[range_start..][0..range_len]);
            return;
        }

        reader.chain_previous = root_page_id;
        reader.chain_run = 1;
        return self.readLinkedRangeIntoReader(root_page_id, value_len, range_start, out, checkpoint, reader, cursor, root_page_id, 0, root_leaf);
    }
    // Sorted cohorts continue at the last touched page instead of replaying
    // every prefix. Navigation never outlives this document/checkpoint owner.
    fn readLinkedRangeIntoReader(self: *NativeFile, root: u64, value_len: usize, range_start: usize, out: []u8, checkpoint: CheckpointSlot, reader: *ValuePageReader, cursor: ?*LinkedRangeCursor, initial_page: u64, initial_offset: usize, first_leaf: ?ValuePage) !void {
        const range_len = out.len;
        const range_end = range_start + range_len;
        var value_offset = initial_offset;
        var written: usize = 0;
        var page_id = initial_page;
        const continuing = if (cursor) |state| state.root == root and state.page == initial_page and state.offset == initial_offset else false;
        var pages_seen: u64 = if (continuing) cursor.?.visited else 0;
        var first_read = true;
        while (page_id != 0) {
            // Re-reading the last touched page is not a new navigation step.
            // Keep the cycle bound across cohorts, rather than resetting it.
            if (!first_read or !continuing) pages_seen += 1;
            if (pages_seen > checkpoint.page_count) return error.InvalidNativeValueChain;

            const page = if (first_read and first_leaf != null) first_leaf.? else try decodeValuePage(try reader.payload(try reader.readChain(self, checkpoint, page_id, range_end - value_offset), .value));
            first_read = false;
            if (page.chunk.len == 0) return error.InvalidNativeValueChain;
            if (page.chunk.len > value_len - value_offset) return error.InvalidNativeValueChain;

            const page_start = value_offset;
            const page_end = page_start + page.chunk.len;
            if (page_end > range_start and page_start < range_end) {
                const copy_start = if (range_start > page_start) range_start - page_start else 0;
                const copy_end = @min(page.chunk.len, range_end - page_start);
                const copy_len = copy_end - copy_start;
                @memcpy(out[written..][0..copy_len], page.chunk[copy_start..][0..copy_len]);
                written += copy_len;
            }

            if (cursor) |state| state.* = .{ .root = root, .page = page_id, .offset = page_start, .visited = pages_seen };
            value_offset = page_end;
            page_id = page.next_page;
            if (value_offset == value_len and page_id != 0) return error.InvalidNativeValueChain;
            if (value_offset >= range_end and written == range_len) {
                break;
            }
        }

        if (written != range_len) return error.InvalidNativeValueChain;
    }

    fn validateReachableValuePages(
        self: *NativeFile,
        root_page_id: u64,
        value_len: usize,
        checkpoint: CheckpointSlot,
        reachable_pages: *ReachablePageSet,
    ) !void {
        if (value_len == 0 or root_page_id == 0) return error.InvalidNativeValueChain;

        if (try self.valueTreeRoot(root_page_id, value_len, checkpoint)) |ref| {
            return try self.validateExtent(ref, checkpoint, reachable_pages);
        }

        var remaining = value_len;
        var page_id = root_page_id;
        var pages_seen: u64 = 0;
        const use_link_cache = self.page_cache_enabled.load(.monotonic) and self.page_cache_bypass.load(.monotonic) == 0;
        while (page_id != 0) {
            pages_seen += 1;
            if (pages_seen > checkpoint.page_count) return error.InvalidNativeValueChain;

            try self.markReachablePage(reachable_pages, page_id, checkpoint.page_count);

            var chunk_len: usize = 0;
            var next_page: u64 = 0;
            var resolved = false;
            if (use_link_cache) {
                if (try self.page_cache.getLinksCopy(self.allocator, page_id)) |links| {
                    defer if (links.key) |key| self.allocator.free(key);
                    if (links.kind != .value) return error.UnexpectedNativePageKind;
                    chunk_len = links.chunk_len;
                    next_page = links.link_page;
                    resolved = true;
                }
            }
            if (!resolved) {
                const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, page_id, .value, checkpoint);
                defer self.allocator.free(payload);
                const page = try decodeValuePage(payload);
                chunk_len = page.chunk.len;
                next_page = page.next_page;
                if (use_link_cache) self.cachePageLinks(page_id, .value, payload);
            }

            if (chunk_len == 0) return error.InvalidNativeValueChain;
            if (chunk_len > remaining) return error.InvalidNativeValueChain;
            remaining -= chunk_len;
            page_id = next_page;
            if (remaining == 0 and page_id != 0) return error.InvalidNativeValueChain;
        }

        if (remaining != 0) return error.InvalidNativeValueChain;
    }

    fn validateReachableFreeMap(self: *NativeFile, checkpoint: CheckpointSlot, reachable_pages: *ReachablePageSet) !void {
        if (checkpoint.free_map_root_page == 0) return;
        try self.markReachablePage(reachable_pages, checkpoint.free_map_root_page, checkpoint.page_count);

        const payload = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
        defer self.allocator.free(payload);
        const free_map = try decodeFreeMapAlloc(self.allocator, payload, checkpoint.page_count, self.header.redo_log_capacity != 0);
        defer self.allocator.free(free_map.free_pages);

        for (free_map.free_pages) |page_id| {
            if (reachable_pages.contains(page_id)) return error.InvalidNativeFreeMap;
        }
        try self.validateFreePagesSafeForCheckpointSlots(free_map.free_pages);
    }

    pub const LiveStats = struct {
        accounting: LiveByteAccounting = .{},
        record_count: u64,
        bytes: u64,
        compact_size: u64,
    };

    /// Compact-layout accounting uses only record metadata and ordered keys.
    /// Integrity checking separately visits and validates all reachable payloads.
    pub fn liveStats(self: *NativeFile, cancel: ?*const maintenance.CancelToken) !LiveStats {
        var live_bytes: u64 = 0;
        var accounting: LiveByteAccounting = .{};
        const indexed = self.header.indexed_reclamation or self.vacuum_target_indexed;
        var compact_pages: u64 = reserved_header_pages + (if (indexed) @as(u64, 0) else 1); // header + both slots; allocator added below
        var record_count: u64 = 0;
        var namespace_directory = NamespaceDirectory.empty;
        defer deinitNamespaceDirectory(self.allocator, &namespace_directory);

        for ([_]LiveRecordSource{ .{ .catalog = .metadata }, .{ .catalog = .index }, .documents }) |source| {
            var cursor = try LiveRecordCursor.init(self, source);
            defer cursor.deinit();
            var counter = DocumentIndexBulkBuilder{ .owner = self, .file = undefined, .next_page_id = &compact_pages, .count_only = true };
            defer counter.deinit();
            var count: u64 = 0;
            var packed_used: usize = 0;
            while (try cursor.next(cancel)) |record| {
                if (source == .catalog and source.catalog == .metadata and std.mem.startsWith(u8, record.key, artifact_lease_key_prefix)) continue;
                const len = if (record.external_value_root_page == 0) record.value.len else record.external_value_len;
                const is_catalog = cursor.kind == .catalog;
                const header_len: usize = if (is_catalog) 16 else documentHeaderSize(indexed, record.key);
                live_bytes +|= record.key.len + len;
                const category = switch (source) {
                    .catalog => |root| if (root == .metadata) &accounting.metadata_catalog else &accounting.index_catalog,
                    .documents => if (isControlDocumentPhysicalKey(record.key)) &accounting.control_documents else &accounting.documents,
                };
                category.records +|= 1;
                category.key_bytes +|= record.key.len;
                category.value_bytes +|= len;
                const external = header_len + record.key.len + len > self.maxPagePayloadBytes();
                const record_size = header_len + record.key.len + (if (external) @as(usize, 8) else len);
                if (external) compact_pages += if (is_catalog or len >= 64 * 1024) self.valueTreePageCount(len) else self.valuePageCount(len);
                if (record_size + 4 > self.maxPagePayloadBytes() / 2) {
                    compact_pages += 1;
                } else {
                    if (packed_used == 0 or packed_used + 4 + record_size > self.maxPagePayloadBytes()) {
                        compact_pages += 1;
                        packed_used = 0;
                    }
                    packed_used += 4 + record_size;
                }
                if (indexed and record.key.len > index_inline_key_limit) compact_pages += 1;
                try counter.add(record.key, 1);
                count += 1;
                if (!is_catalog and !indexed) {
                    const namespace = documentNamespace(record.key);
                    if (!namespace_directory.contains(namespace)) {
                        const owned = try self.allocator.dupe(u8, namespace);
                        errdefer self.allocator.free(owned);
                        try namespace_directory.put(self.allocator, owned, 1);
                    }
                }
            }
            _ = try counter.finish();
            if (cursor.kind == .catalog and count > 0) compact_pages += 1; // descriptor
            record_count += count;
        }
        if (namespace_directory.count() > 0) namespace_count: {
            if (namespace_directory.count() <= 32) {
                const encoded = try encodeNamespaceDirectoryAlloc(self.allocator, .snapshot, &namespace_directory);
                defer self.allocator.free(encoded);
                if (self.catalogEntryFitsInline(namespace_directory_key, encoded)) {
                    compact_pages += 1;
                    break :namespace_count;
                }
            }
            const keys = try self.allocator.alloc([]const u8, namespace_directory.count());
            defer self.allocator.free(keys);
            var it = namespace_directory.keyIterator();
            for (keys) |*key| key.* = it.next().?.*;
            std.mem.sort([]const u8, keys, {}, struct {
                fn less(_: void, a: []const u8, b: []const u8) bool {
                    return std.mem.lessThan(u8, a, b);
                }
            }.less);
            var counter = DocumentIndexBulkBuilder{ .owner = self, .file = undefined, .next_page_id = &compact_pages, .count_only = true };
            defer counter.deinit();
            var packed_used: usize = 0;
            for (keys) |key| {
                const size = 16 + key.len + 8;
                if (size + 4 > self.maxPagePayloadBytes() / 2) {
                    compact_pages += 1;
                } else {
                    if (packed_used == 0 or packed_used + 4 + size > self.maxPagePayloadBytes()) {
                        compact_pages += 1;
                        packed_used = 0;
                    }
                    packed_used += 4 + size;
                }
                try counter.add(key, 1);
            }
            _ = try counter.finish();
            compact_pages += 1; // directory catalog descriptor
        }
        if (indexed) {
            const data_pages = compact_pages;
            const per_page = (self.maxPagePayloadBytes() - 24) / 4;
            while (true) {
                const total = data_pages + 1 + (try std.math.divCeil(u64, compact_pages - 1, per_page));
                if (total == compact_pages) break;
                compact_pages = total;
            }
        }
        return .{ .accounting = accounting, .record_count = record_count, .bytes = live_bytes, .compact_size = compact_pages * @as(u64, self.header.page_size) };
    }

    fn valueTreePageCount(self: *const NativeFile, value_len: usize) u64 {
        var level = self.valuePageCount(value_len);
        var total = level;
        while (level > 1) {
            level = std.math.divCeil(u64, level, extent_fanout) catch unreachable;
            total += level;
        }
        return total;
    }

    fn valuePageCount(self: *const NativeFile, value_len: usize) u64 {
        std.debug.assert(value_len > 0);
        return @intCast(std.math.divCeil(usize, value_len, self.maxValuePagePayloadBytes()) catch unreachable);
    }

    fn writePage(self: *NativeFile, page_id: u64, kind: PageKind, contents: []const u8) !void {
        return self.writePageWithOptions(page_id, kind, contents, .{});
    }

    fn writePageWithOptions(self: *NativeFile, page_id: u64, kind: PageKind, contents: []const u8, options: WriteOptions) !void {
        var batch = PageWriteBatch{ .file = self, .options = options };
        try batch.appendPage(page_id, kind, contents);
        try batch.flush();
    }

    /// Cache admission happens only after the complete encoded write succeeds.
    fn cacheWrittenPage(self: *NativeFile, page_id: u64, page: []const u8, options: WriteOptions) void {
        const kind: PageKind = @fromBackingInt(page[4]);
        const len = std.mem.readInt(u32, page[8..12], .little);
        const contents = page[page_header_size..][0..len];
        if (!self.admitPageToCache(page) or (kind == .value and options.payload_cache == .cold_sequential)) {
            // Skipping admission must still remove stale bytes AND navigation
            // links from a previous use of this page ID. Cold payload pages
            // also skip link admission; extent/catalog metadata stays warm.
            self.page_cache.remove(self.allocator, page_id);
        } else if (self.page_cache_enabled.load(.monotonic)) {
            self.page_cache.put(self.allocator, page_id, page);
            self.cachePageLinks(page_id, kind, contents);
        }
    }

    /// Best-effort: decode and cache the chain-navigation metadata for a page
    /// just written, so reachability walks can traverse it without re-reading
    /// the payload. On any decode surprise the stale entry is dropped and the
    /// walks fall back to the payload path.
    fn cachePageLinks(self: *NativeFile, page_id: u64, kind: PageKind, payload: []const u8) void {
        if (page_id & packed_record_flag != 0) return;
        if (!self.page_cache_enabled.load(.monotonic)) return;
        switch (kind) {
            .document => {
                const entry = decodeDocumentEntry(payload) catch {
                    self.page_cache.remove(self.allocator, page_id);
                    return;
                };
                self.page_cache.putLinks(self.allocator, page_id, .{
                    .kind = .document,
                    .link_page = entry.previous_page,
                    .external_value_root_page = entry.external_value_root_page,
                    .external_value_len = entry.external_value_len,
                });
            },
            .catalog => {
                const entry = decodeCatalogEntry(payload) catch {
                    self.page_cache.remove(self.allocator, page_id);
                    return;
                };
                self.page_cache.putLinks(self.allocator, page_id, .{
                    .kind = .catalog,
                    .link_page = entry.previous_page,
                    .external_value_root_page = entry.external_value_root_page,
                    .external_value_len = entry.external_value_len,
                    .key = @constCast(entry.key),
                    .is_delete = entry.is_delete,
                    .value_len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len,
                });
            },
            .value => {
                const page = decodeValuePage(payload) catch {
                    self.page_cache.remove(self.allocator, page_id);
                    return;
                };
                self.page_cache.putLinks(self.allocator, page_id, .{
                    .kind = .value,
                    .link_page = page.next_page,
                    .chunk_len = page.chunk.len,
                });
            },
            // A reused page id may carry stale link info from a previous life.
            // checkpoint_slot/commit_manifest pages are written directly
            // through self.file, never through this cache path, but the
            // switch must still be exhaustive.
            .data, .value_extent, .catalog_index, .record_bundle, .allocator, .key, .checkpoint_slot, .commit_manifest => self.page_cache.removeLinks(self.allocator, page_id),
            .document_index => self.page_cache.removeLinks(self.allocator, page_id),
            .free_map => unreachable,
        }
    }

    fn stagingTransaction(self: *const NativeFile) bool {
        return self.transaction_header != null and !self.flushing_transaction;
    }

    fn transactionWrites(self: *NativeFile) !*TransactionWrites {
        if (self.transaction_writes) |writes| return writes;
        const writes = try self.allocator.create(TransactionWrites);
        errdefer self.allocator.destroy(writes);
        const checkpoint = self.activeCheckpoint();
        // §9 (redo + indexed reclamation): the same `diverting` condition
        // `flushTransactionWrites` computes later for this same
        // transaction -- known here too, since `self.redo` and
        // `checkpointing` are both file-level state, not something this
        // specific call discovers. See `pageAllocatorForDivertingCommit`'s
        // own doc comment for why only this call site (not
        // `reclaimPagesImpl`, not bootstrap) takes the shortcut.
        //
        // perf/lwa-txn-overlay (unbounded buffering): must stay exactly in
        // sync with `flushTransactionWrites`'s own `diverting`, including
        // the large-transaction fallback below -- this call always runs
        // (at transaction start, or right after a flush replaces the
        // previous `TransactionWrites`) at a moment when `logical_pending`/
        // `pending` are stable until this same batch's own eventual flush
        // (nothing else appends to either in between), so the threshold
        // check reads the same bytes either place evaluates it.
        const diverting = self.redo != null and !self.redo.?.checkpointing and !self.redo.?.overLargeTransactionThreshold();
        writes.* = .{
            .pages = if (diverting) try self.pageAllocatorForDivertingCommit(checkpoint) else try self.pageAllocatorFromFreeMap(checkpoint),
            .value_arena = std.heap.ArenaAllocator.init(self.allocator),
        };
        self.transaction_writes = writes;
        self.transaction_writes_generation +%= 1;
        return writes;
    }

    fn stagedEntry(self: *NativeFile, root: TransactionWrites.Root, key: []const u8) ?CatalogEntry {
        if (!self.stagingTransaction()) return null;
        const writes = self.transaction_writes orelse return null;
        return TransactionWrites.entry(writes.maps[@backingInt(root)].get(key) orelse return null);
    }

    /// The redo-log analogue of `stagedEntry`: a committed-but-not-yet-
    /// checkpointed logical mutation for `root`/`key` (§9.3a's overlay,
    /// §9.7a's versioned chain). `checkpoint` may be the *current*
    /// checkpoint or a deliberately pinned, older one -- either way, this
    /// resolves to the newest version whose own `sequence` is `<=
    /// checkpoint.commit_sequence`, so a reader pinned to an older
    /// generation sees exactly the value that existed as of its own pin,
    /// never a later overwrite. Returns `null` for a non-redo file, a key
    /// the overlay has never held anything for, or a checkpoint that
    /// predates every version this chain still remembers (in which case
    /// the real tree -- which, at that point, had not yet had this key's
    /// mutation diverted away from it -- is the correct fallback, exactly
    /// as a `stagedEntry` miss does).
    /// §9.6a: `.value` (when present) is an *owned* copy allocated with
    /// `self.allocator` -- the shared overlay never lets a resolved
    /// version's memory outlive its own lock (see `resolveAlloc`'s own
    /// doc comment), so every caller of this function must
    /// `self.allocator.free(entry.value)` once done with it, exactly like
    /// any other `...Alloc` function in this file.
    pub fn redoOverlayEntry(self: *NativeFile, root: TransactionWrites.Root, checkpoint: CheckpointSlot, key: []const u8) !?CatalogEntry {
        return self.redoOverlayEntryAt(root, self.readMark(checkpoint), key);
    }

    /// §9.7c (ReadView): the overlay read mark M corresponding to
    /// `checkpoint` (C) -- the *logical* commit sequence to resolve the
    /// overlay at, which is not always C's own `commit_sequence` number.
    /// Under redo mode, an ordinary commit advances the logical sequence
    /// (`committedSequence`) without moving the physical checkpoint slot
    /// at all until the next `checkpointRedoLog` -- so for the *current*
    /// generation, C trails M, and resolving the overlay at C's own
    /// number (as every caller of `redoOverlayEntry` effectively did
    /// before this existed) incorrectly treats every version newer than
    /// the last real checkpoint as if it postdated this read, when it
    /// is, in fact, exactly what this read is supposed to see. For an
    /// older, already-checkpointed generation, C's own number already
    /// equals the logical sequence that was current at the moment that
    /// checkpoint published (publishing *is* the moment the two numbers
    /// last coincided), so no correction is needed there -- `checkpoint
    /// .commit_sequence == activeCheckpoint().commit_sequence` is
    /// exactly the dividing line between the two cases.
    ///
    /// Found via `getDocumentsAtCheckpointWithState`'s batch read (and,
    /// before that, `docstore.Cursor`'s own overlay branch) silently
    /// treating a just-committed, not-yet-checkpointed document as
    /// though it postdated the read: both called `redoOverlayEntry`
    /// with `checkpoint.commit_sequence` directly, which stayed stuck at
    /// an old, pre-redo value for the entire life of the current
    /// generation. Centralizing the correction here, rather than
    /// recomputing it at each call site, is the §9.7c ReadView design's
    /// whole point: every reader is pinned to a (C, M) pair captured
    /// together, not forced to derive M from C itself on every read.
    pub fn readMark(self: *const NativeFile, checkpoint: CheckpointSlot) u64 {
        if (checkpoint.commit_sequence == self.activeCheckpoint().commit_sequence) return self.committedSequence();
        return checkpoint.commit_sequence;
    }

    /// `redoOverlayEntry`, but resolving at an explicit mark `M` instead
    /// of deriving one from a `CheckpointSlot` -- the primitive
    /// `ReadView`'s own read methods call directly, already holding the
    /// correct `M` for their pinned (C, M) pair; `redoOverlayEntry`
    /// itself is now a thin wrapper computing `M` via `readMark` for
    /// callers that have only a `CheckpointSlot` in hand.
    pub fn redoOverlayEntryAt(self: *NativeFile, root: TransactionWrites.Root, mark: u64, key: []const u8) !?CatalogEntry {
        const redo = self.redo orelse return null;
        const resolved = (try redo.shared.resolveAlloc(self.allocator, self.runtimeIo(), @backingInt(root), key, mark)) orelse return null;
        return .{
            .previous_page = 0,
            .key = key,
            .value = resolved.value,
            .is_delete = resolved.is_delete,
            .external_value_root_page = resolved.external_value_root_page,
            .external_value_len = resolved.external_value_len,
        };
    }

    /// §9.3d/`check()`: the number of keys currently staged only in the
    /// redo-log overlay (uncheckpointed), across all three roots, for the
    /// *active* checkpoint. `check()`'s `record_count` is a raw physical
    /// page/chain count that predates redo-log mode and already double-
    /// counts historical/tombstoned revisions by design (see its own
    /// doc comment); without this, a redo-log commit that only writes
    /// into the overlay (never allocating a page) could make
    /// `record_count` *undercount* `live_file_count` -- a new, narrower
    /// invariant break this restores rather than attempting to make
    /// `record_count` itself overlay-aware (a much bigger semantic change
    /// for every existing, non-redo caller of `check()`).
    fn redoOverlayEntryCount(self: *NativeFile) u64 {
        const redo = self.redo orelse return 0;
        var total: u64 = 0;
        for (0..3) |root_idx| total += redo.shared.count(self.runtimeIo(), @intCast(root_idx));
        return total;
    }

    /// A sorted snapshot of one root's redo-log logical_overlay keys
    /// restricted to a prefix, for merging into a tree-ordered scan
    /// (§9.3a, revised for scans/iterators: every path that enumerates
    /// keys, not just point lookups, must see committed-but-not-yet-
    /// checkpointed mutations, and must never surface a key the overlay
    /// has deleted or superseded). `takeFront`/`takeIfEqual` consume keys
    /// in ascending order; materializing a taken key's *value* still goes
    /// through `redoOverlayEntry` (or an equivalent direct lookup) by
    /// callers, exactly like a point read -- this type only orders the
    /// keys, it does not duplicate value storage.
    ///
    /// `peek`+consume (rather than returning values directly) lets a
    /// caller's own tree-side loop decide, key by key, whether the tree's
    /// or the overlay's candidate comes first in a standard merge-join,
    /// without this type needing to know anything about the tree side.
    pub const OverlayScanState = struct {
        /// Null for a non-redo file (`initForPrefixUnchecked`'s own
        /// short-circuit) -- every method below treats that the same as
        /// "the overlay is permanently empty."
        shared: ?*redo_overlay.SharedRedoOverlay = null,
        io: std.Io = undefined,
        root: u8 = 0,
        prefix: []const u8 = &.{},
        allocator: Allocator,
        /// The overlay candidate at this scan's current position, an
        /// owned copy (perf/lwa-overlay-order: never a borrowed
        /// reference into the live, shared, concurrently-mutated treap
        /// -- see `SharedRedoOverlay.resolveAlloc`'s own doc comment for
        /// why: a reference held across that structure's lock release is
        /// a use-after-free risk once a concurrent `reclaim` can run).
        /// Replaced (never mutated in place) by every `reset*`/`step`
        /// call below; the key a caller is handed back by `peek`/
        /// `takeFront`/`advance` stays valid until the *next* such call
        /// on this same `OverlayScanState` (see `stale`), matching every
        /// existing caller's own usage pattern: use the returned key,
        /// then either dupe it or let it go before asking this type to
        /// move again.
        current: ?[]u8 = null,
        /// The previous `current`, kept alive for exactly one more
        /// transition after it stops being "current" -- freed at the
        /// start of the *next* transition, not immediately, so a caller
        /// that is still holding (and using) the value `takeFront`/
        /// `peek` just returned does not have it pulled out from under
        /// it by this same call's own internal advance.
        stale: ?[]u8 = null,
        started: bool = false,

        /// §9.7c (`ReadView`): this used to refuse (return empty) for any
        /// `checkpoint` other than `file.activeCheckpoint()` exactly --
        /// a guard meant to stop a deliberately pinned, older snapshot
        /// from seeing mutations the overlay only reflects for the
        /// *current* generation. In practice it fired for a case that
        /// guard was never meant to catch: `catalogCursor`'s own callers
        /// (`metadataCatalogCursor`/`indexCatalogCursor`/
        /// `indexCatalogDirectoryCursor`) are reached from a `ReadGeneration`'s
        /// separately-opened `generation.file` with the *tracked* checkpoint
        /// (`Txn.checkpoint`, kept current by `Store.observeReadCheckpoint`)
        /// passed in -- `checkpoint.commit_sequence` is genuinely current,
        /// but `generation.file.activeCheckpoint()` is frozen at that
        /// instance's own open time (it never processes commits itself),
        /// so the two numbers mismatch on every call after the first
        /// commit, and this returned empty every time: the exact
        /// overlay-blind-scan bug class §9.7c describes, just one more
        /// occurrence of it, reached through `index_storage.zig`'s
        /// directory listing and `native_catalog_sink.zig`'s
        /// `loadAllAlloc` (the dense/sparse/graph/full-text native-
        /// catalog seed) rather than through `docstore.Cursor`.
        ///
        /// Per-key value resolution (`redoOverlayEntry`/`resolveAlloc`)
        /// is already correctly version-pinned regardless of which
        /// checkpoint number is passed -- the same function an ordinary
        /// point `get()` uses, with no such gate at all -- so dropping
        /// this precondition does not weaken correctness for a
        /// genuinely stale pin, only widens *enumeration* to match what
        /// point-read resolution already does. Still returns empty for
        /// a non-redo file. Now the same function as
        /// `initForPrefixUnchecked` (kept as a thin alias for existing
        /// callers) -- there is exactly one enumeration behavior.
        pub fn initForPrefix(allocator: Allocator, file: *NativeFile, root: TransactionWrites.Root, checkpoint: CheckpointSlot, prefix: []const u8) !OverlayScanState {
            _ = checkpoint;
            return initForPrefixUnchecked(allocator, file, root, prefix);
        }

        /// perf/lwa-overlay-order: no longer touches the shared overlay
        /// at all -- construction is O(1). Every previous caller eagerly
        /// paid `SharedRedoOverlay.keysWithPrefixAlloc`'s cost (iterate
        /// every key in the whole root, dupe every match, sort) on
        /// *every* cursor open, regardless of whether the cursor ever
        /// visited more than one key (e.g. an existence probe). Lookups
        /// below instead seek `shared`'s own ordered index directly, in
        /// O(log n), fetching (and copying) only the one key actually
        /// being visited at each step.
        pub fn initForPrefixUnchecked(allocator: Allocator, file: *NativeFile, root: TransactionWrites.Root, prefix: []const u8) !OverlayScanState {
            const redo = file.redo orelse return .{ .allocator = allocator };
            return .{
                .shared = redo.shared,
                .io = file.runtimeIo(),
                .root = @backingInt(root),
                .prefix = prefix,
                .allocator = allocator,
            };
        }

        pub fn deinit(self: *OverlayScanState) void {
            self.retireStale();
            if (self.current) |c| self.allocator.free(c);
            self.* = undefined;
        }

        fn retireStale(self: *OverlayScanState) void {
            if (self.stale) |s| self.allocator.free(s);
            self.stale = null;
        }

        fn fetchFirstAlloc(self: *OverlayScanState) !?[]u8 {
            const shared = self.shared orelse return null;
            return try shared.firstKeyWithPrefixAlloc(self.allocator, self.io, self.root, self.prefix);
        }

        fn fetchLastAlloc(self: *OverlayScanState) !?[]u8 {
            const shared = self.shared orelse return null;
            return try shared.lastKeyWithPrefixAlloc(self.allocator, self.io, self.root, self.prefix);
        }

        fn fetchAtOrAfterAlloc(self: *OverlayScanState, key: []const u8, strict: bool) !?[]u8 {
            const shared = self.shared orelse return null;
            return try shared.seekKeyAtOrAfterAlloc(self.allocator, self.io, self.root, self.prefix, key, strict);
        }

        fn fetchAtOrBeforeAlloc(self: *OverlayScanState, key: []const u8, strict: bool) !?[]u8 {
            const shared = self.shared orelse return null;
            return try shared.seekKeyAtOrBeforeAlloc(self.allocator, self.io, self.root, self.prefix, key, strict);
        }

        /// Replaces `current` with `fresh`, staging the outgoing value
        /// as `stale` (see that field's own doc comment) rather than
        /// freeing it immediately.
        fn transitionTo(self: *OverlayScanState, fresh: ?[]u8) void {
            self.started = true;
            self.retireStale();
            self.stale = self.current;
            self.current = fresh;
        }

        /// Resets this scan's position to the smallest key matching
        /// `prefix` -- O(log n). For a fresh cursor open/first() call,
        /// never a continuation (see `step` for that).
        pub fn resetToFirst(self: *OverlayScanState) !void {
            self.transitionTo(try self.fetchFirstAlloc());
        }

        /// Resets to the largest key matching `prefix` -- O(log n).
        pub fn resetToLast(self: *OverlayScanState) !void {
            self.transitionTo(try self.fetchLastAlloc());
        }

        /// Resets to the smallest key `>= key` (or `> key` if `strict`)
        /// matching `prefix` -- O(log n), for `seekAtOrAfter`/a direction
        /// change.
        pub fn resetToAtOrAfter(self: *OverlayScanState, key: []const u8, strict: bool) !void {
            self.transitionTo(try self.fetchAtOrAfterAlloc(key, strict));
        }

        /// Resets to the largest key `<= key` (or `< key` if `strict`)
        /// matching `prefix` -- O(log n), for `seekAtOrBefore`/a
        /// direction change.
        pub fn resetToAtOrBefore(self: *OverlayScanState, key: []const u8, strict: bool) !void {
            self.transitionTo(try self.fetchAtOrBeforeAlloc(key, strict));
        }

        /// Moves to the adjacent key in `direction`, strictly past
        /// whatever is currently cached -- O(log n), a fresh seek each
        /// time rather than an in-place pointer increment, since nothing
        /// may hold a borrowed reference into the shared overlay across
        /// this type's own lock release (see `current`'s doc comment).
        /// A no-op once already exhausted (`current == null`): stays
        /// exhausted, never restarts from the beginning.
        pub fn step(self: *OverlayScanState, forward: bool) !void {
            const cur = self.current orelse return;
            const fresh = if (forward) try self.fetchAtOrAfterAlloc(cur, true) else try self.fetchAtOrBeforeAlloc(cur, true);
            self.transitionTo(fresh);
        }

        /// The current (forward-scan) candidate, lazily positioned at
        /// the first match on first use.
        pub fn peek(self: *OverlayScanState) !?[]const u8 {
            if (!self.started) try self.resetToFirst();
            return self.current;
        }

        /// Consumes and returns the current (forward-scan) candidate,
        /// advancing to the next one. The returned slice remains valid
        /// until the next call to `peek`/`takeFront`/`consumeIfEqual`/
        /// `step` on this same `OverlayScanState` (see `stale`'s own doc
        /// comment) -- every existing caller already only uses it within
        /// that window.
        pub fn takeFront(self: *OverlayScanState) !?[]const u8 {
            const result = try self.peek();
            try self.step(true);
            return result;
        }

        /// If the current (forward-scan) candidate equals `key`
        /// (typically a value this same caller just got from `peek`),
        /// consumes it -- used when the tree side's own candidate
        /// collides with the overlay's, so the tree's stale value for
        /// that key is never also visited on a later step.
        pub fn consumeIfEqual(self: *OverlayScanState, key: []const u8) !void {
            const cur = try self.peek() orelse return;
            if (std.mem.eql(u8, cur, key)) try self.step(true);
        }

        /// Marks the forward scan permanently exhausted -- used when a
        /// caller has independently determined (e.g. the current
        /// candidate no longer matches a narrower prefix than this scan's
        /// own) that nothing further in sorted order can match either.
        pub fn exhaust(self: *OverlayScanState) void {
            self.transitionTo(null);
        }
    };

    fn stageMutation(self: *NativeFile, root: TransactionWrites.Root, mutation: CatalogMutation, options: WriteOptions) !void {
        if (self.artifact_lease_transaction and (root != .metadata or !std.mem.startsWith(u8, mutation.key, artifact_lease_key_prefix)))
            return error.InvalidArtifactLeaseMutation;
        // Acquire ownership before a spill: callers may be appending/renaming
        // an entry borrowed from the write set that the spill will release.
        const inline_value = !mutation.is_delete and mutation.external_value_root_page == 0 and
            (if (root == .documents) self.documentEntryFitsInline(mutation.key, mutation.value) else self.catalogEntryFitsInline(mutation.key, mutation.value));
        // The eventual owned value is either the real inline bytes or "" (an
        // out-of-line value is written below and tracked only by its page
        // reference) -- compute its length now, before any allocation, so
        // the capacity check and a possible flush-and-replace of `writes`
        // (and its arena) can happen before anything is staged into it.
        const owned_value_len: usize = if (inline_value) mutation.value.len else 0;
        var writes = try self.transactionWrites();
        const replaced = writes.maps[@backingInt(root)].get(mutation.key);
        const replaced_bytes = if (replaced) |old| old.key.len + old.value.len else 0;
        if ((replaced == null and writes.count >= TransactionWrites.max_keys) or writes.bytes - replaced_bytes + mutation.key.len + owned_value_len > TransactionWrites.max_bytes) {
            try self.flushTransactionWrites();
            writes = try self.transactionWrites();
        }
        // Acquire ownership from this transaction's own arena: every entry
        // staged here (and every undo-log snapshot of one it replaces) dies
        // together at `writes.clear`/`deinit` (one per flush window), so
        // there is nothing to free individually and no failure-path
        // `errdefer` to register -- an arena allocation that is never
        // stored anywhere just becomes unreferenced garbage, reclaimed at
        // the same point a successful one would have been anyway. Writing
        // `mutation.value` into pages below (not duping it first: those
        // writers only read it synchronously within this call) no longer
        // needs its own temporary copy either.
        const arena = writes.value_arena.allocator();
        var owned = mutation;
        owned.key = try arena.dupe(u8, mutation.key);
        owned.value = try arena.dupe(u8, if (inline_value) mutation.value else "");
        if (!mutation.is_delete and mutation.external_value_root_page == 0 and !inline_value) {
            owned.external_value_root_page = if (root == .documents)
                try self.writeDocumentValue(&writes.pages, mutation.value)
            else
                try self.writeCatalogValue(&writes.pages, mutation.value, options);
            owned.external_value_len = mutation.value.len;
            try self.flushTransactionPayloads();
        }
        const map = &writes.maps[@backingInt(root)];
        const slot = try map.getOrPut(self.allocator, owned.key);
        const recording = writes.undo_depth > 0;
        if (slot.found_existing) {
            const old = slot.value_ptr.*;
            writes.bytes -= old.key.len + old.value.len;
            if (recording) {
                // Transfer the replaced entry into the undo log instead of
                // dropping it, so a savepoint rollback can restore it
                // verbatim. Both live in the same arena either way.
                const undo_key = try arena.dupe(u8, owned.key);
                try writes.undo.append(self.allocator, .{ .root = @backingInt(root), .key = undo_key, .previous = old });
            }
        } else {
            // `getOrPut` already wrote `owned.key` into `slot.key_ptr` for a
            // new entry (its own contract: "if (!found_existing) gop.key_ptr.*
            // = key"), but `slot.value_ptr` is still whatever garbage backed
            // that slot -- this function doesn't fill it in until the very
            // end. If the undo-log append below fails, remove the
            // half-initialized slot before that happens so a dangling key
            // never lingers in the map; `owned.key` itself needs no cleanup
            // (arena memory).
            errdefer _ = map.remove(owned.key);
            writes.count += 1;
            if (recording) {
                const undo_key = try arena.dupe(u8, owned.key);
                try writes.undo.append(self.allocator, .{ .root = @backingInt(root), .key = undo_key, .previous = null });
            }
        }
        slot.key_ptr.* = owned.key;
        slot.value_ptr.* = owned;
        writes.bytes += owned.key.len + owned.value.len;
        // Track private changes; commit collapses them to one revision.
        self.header.checkpoints[self.header.active_checkpoint].commit_sequence += 1;
    }

    fn flushTransactionPayloads(self: *NativeFile) !void {
        const writes = self.transaction_writes.?;
        try writes.pages.flush();
        self.header.checkpoints[self.header.active_checkpoint].page_count = writes.pages.next_page_id;
    }

    fn flushTransactionWrites(self: *NativeFile) anyerror!void {
        if (self.flushing_transaction) return;
        const writes = self.transaction_writes orelse return;
        const debug_starting_page_count = if (builtin.is_test) writes.pages.next_page_id else 0;
        try self.finishCatalogAppends(writes);
        self.flushing_transaction = true;
        self.transaction_pages = &writes.pages;
        defer {
            self.transaction_pages = null;
            self.flushing_transaction = false;
        }
        // §9 (revised): a redo-log commit that isn't itself the
        // checkpointer's own transaction logs every root's staged
        // mutations logically instead of running IndexEditor/PageAllocator
        // to build real copy-on-write pages for them -- the whole point of
        // deferring that work to `checkpointRedoLog`, batched across
        // however many commits accumulate before it runs, instead of once
        // per commit. `checkpointRedoLog` sets `checkpointing = true`
        // around its own transaction specifically so this check is false
        // then, and the real build below runs instead.
        //
        // perf/lwa-txn-overlay (unbounded buffering): also false past
        // `large_txn_fallback_bytes` -- see `RedoCommitState
        // .large_txn_fallback_bytes`'s own doc comment. Must match
        // `transactionWrites`'s own copy of this condition exactly for
        // this same batch (see that call site's comment for why the
        // inputs are stable between the two).
        const diverting = self.redo != null and !self.redo.?.checkpointing and !self.redo.?.overLargeTransactionThreshold();
        var diverted_anything = false;
        // §9.7a: the `commit_sequence` this transaction will publish as,
        // known deterministically now, mirroring `commitTransactionWithDurability`'s
        // own `previous.checkpoints[...].commit_sequence + 1`. Deliberately
        // NOT `self.activeCheckpoint().commit_sequence + 1`: `stageMutation`
        // bumps `self.header.checkpoints[active].commit_sequence` by one on
        // every staged mutation (a provisional per-stage counter used for
        // undo/savepoint bookkeeping, "collapsed to one revision" at commit
        // time -- see its own comment), so `self.header` reads however many
        // mutations this transaction has staged so far, not the one true
        // final sequence. `self.transaction_header`, captured once at
        // `beginTransaction` and never touched by `stageMutation`, is the
        // right source for that value.
        const pending_sequence: u64 = self.transaction_header.?.checkpoints[self.transaction_header.?.active_checkpoint].commit_sequence + 1;
        // Keep entries alive through every root's finalization. Editors own
        // their navigation state; the allocator/record packer is shared.
        for (&writes.maps, 0..) |*map, root| {
            if (map.count() == 0) continue;
            var batch = std.ArrayListUnmanaged(CatalogMutation).empty;
            defer batch.deinit(self.allocator);
            try batch.ensureTotalCapacity(self.allocator, map.count());
            var it = map.valueIterator();
            while (it.next()) |mutation| batch.appendAssumeCapacity(mutation.*);
            std.mem.sort(CatalogMutation, batch.items, {}, struct {
                fn less(_: void, a: CatalogMutation, b: CatalogMutation) bool {
                    return std.mem.order(u8, a.key, b.key) == .lt;
                }
            }.less);
            if (diverting) {
                for (batch.items) |m| {
                    if (builtin.is_test) {
                        if (self.test_logical_write_fail_after) |remaining| {
                            if (remaining == 0) return error.TestPageWriteFailure;
                            self.test_logical_write_fail_after = remaining - 1;
                        }
                        _ = self.test_logical_mutations.fetchAdd(1, .monotonic);
                    }
                    try self.redo.?.appendLogicalMutation(self.allocator, self.runtimeIo(), @intCast(root), m, pending_sequence);
                }
                diverted_anything = true;
            } else if (root == @backingInt(TransactionWrites.Root.documents)) {
                const docs = try self.allocator.alloc(DocumentMutation, batch.items.len);
                defer self.allocator.free(docs);
                for (batch.items, docs) |m, *doc| doc.* = .{ .key = m.key, .value = m.value, .is_delete = m.is_delete, .external_value_root_page = m.external_value_root_page, .external_value_len = m.external_value_len };
                try self.putDocumentBatch(docs);
            } else try self.putCatalogBatchForRoot(if (root == 0) .metadata else .index, batch.items, .{});
            // §9 (redo + indexed reclamation): a *catalog* external
            // value's own pages (`file.direct_value_pages`,
            // `writeCatalogValue`'s own doc comment) were written for
            // real, immediately, by the diverting commit that created
            // them -- `PageWriteBatch.flushCount`'s own
            // `direct_value_pages` branch pwrites them directly instead
            // of staging them through `SharedRedoOverlay.pages`, to keep
            // an unbounded catalog value from accumulating in memory
            // across private-flush chunking. `redo_fold_retain_pending`
            // below is sourced entirely from that overlay's own staged
            // pages, so it never sees these pages at all; the
            // `putCatalogBatchForRoot` call just above only retained
            // each chain's own *root* (`retainRecord`), never its
            // children, which a normal (non-redo) write retains through
            // `writeExtentNode`'s own `retainValue` calls -- calls this
            // exact head's own diverting commit already made, but
            // against `pageAllocatorForDivertingCommit`'s allocator,
            // which never attaches a ledger, so every one of them was a
            // silent no-op. Walking each surviving head's chain here and
            // retaining whatever `writes.pages.ledger` has not already
            // counted covers that gap; a page it already retained (the
            // root) is simply skipped.
            //
            // Scoped to catalog roots only (`root != .documents`):
            // `writeDocumentValue` never sets `direct_value_pages` (only
            // `writeCatalogValue` does), so a document's own chain is
            // always fully covered already, by `retainRecord` (its root)
            // and `redo_fold_retain_pending` (its staged continuation
            // pages) -- walking it here too would be redundant extra
            // page-read/allocation work on every document fold, observed
            // live to tip an already-tight storage budget into failing
            // the triggering commit itself instead of only the
            // opportunistic checkpoint ("lite reclamation opportunistic
            // redo checkpoint failure is visible and recovers").
            if (!diverting and root != @backingInt(TransactionWrites.Root.documents)) {
                if (writes.pages.ledger) |state| {
                    const checkpoint = self.activeCheckpoint();
                    for (batch.items) |m| {
                        if (m.is_delete or m.external_value_root_page == 0) continue;
                        try self.retainUnretainedValueChainPages(state, checkpoint, m.external_value_root_page, m.external_value_len, null);
                    }
                }
            }
            // The next root may resolve external index keys written here.
            try writes.pages.flush();
        }
        // §9 (redo + indexed reclamation): `checkpointRedoLog`'s own
        // `redo_fold_retain_pending` (see that field's own doc comment)
        // names page ids a diverting commit wrote raw, bypassing the
        // ledger entirely, that the fold just above did not already
        // retain as a side effect of writing their owning document's
        // record (`retainRecord`, reached through `writePage`, retains
        // only the chain's own root page -- the one `external_value_root_page`
        // actually points to). Only ever set when `!diverting` (this
        // field exists for `checkpointRedoLog`'s own real build alone),
        // but checked here regardless of that, so a page still at count
        // 0 after the fold -- a continuation page nothing else ever
        // touches -- gets picked up before `persistAllocator` below
        // finalizes the ledger, rather than leaving
        // `validateIndexedOwnership`'s later reachability walk to find
        // a referenced page the ledger never counted.
        if (self.redo_fold_retain_pending) |pending| {
            defer {
                self.allocator.free(pending);
                self.redo_fold_retain_pending = null;
            }
            if (writes.pages.ledger) |state| {
                for (pending) |page_id| {
                    // §9 (redo + indexed reclamation): a page can reach
                    // count() == 0 for two different reasons -- a genuine
                    // continuation page nothing has ever retained (needs
                    // retaining here), or the ledger's own self-describing
                    // root/metadata page (never counted the normal way,
                    // per `isSelfDescribingPage`'s own doc comment), which
                    // `preparePersist`'s rotation below is about to retire
                    // in this same persist cycle. Retaining the latter
                    // double-books it: `validateIndexedOwnership` later
                    // finds the same page simultaneously counted as live
                    // (this retain) and pending retirement (the rotation),
                    // and fails closed with `error.InvalidNativeAllocator`.
                    // Only a page that is neither already counted nor one
                    // of the ledger's own structural pages is a real,
                    // previously-unretained continuation page.
                    //
                    // A page-shaped exception is not always a single
                    // external-value continuation page: a diverting
                    // commit's own `pack_records` path (`PageAllocator
                    // .writeRecord`) can also flush a shared
                    // `record_bundle` page here (`flushRecords`, called
                    // from `takeAllPagesAlloc`'s own drain), bundling
                    // several packed document/catalog records that each
                    // need their own retain -- never touched by
                    // `retainRecord` while diverting, same as a plain
                    // continuation page. A single blind `retain()` left
                    // every bundled record but the first invisible to the
                    // ledger (count stuck at 1 regardless of how many
                    // packed records the page actually holds), so a later
                    // `release()` on just one of them freed the whole
                    // page while the others were still live --
                    // reproduced by "lite replay cleanup commits bounded
                    // chunks isolates namespaces and retries" as
                    // `validateIndexedOwnership`'s own reachability walk
                    // expecting many more references than the ledger had.
                    if (state.count(page_id) == 0 and !state.isSelfDescribingPage(page_id)) {
                        const raw = try self.readPhysicalPageAlloc(self.allocator, page_id, self.activeCheckpoint());
                        defer self.allocator.free(raw);
                        if (raw.len > page_header_size and raw[4] == @backingInt(PageKind.record_bundle)) {
                            const bundle_payload = try decodePagePayload(raw, .record_bundle);
                            var offset: usize = 0;
                            while (offset < bundle_payload.len) {
                                const record = try packedRecordAtOffset(bundle_payload, offset);
                                try state.retain(page_id);
                                offset += 4 + record.bytes.len;
                            }
                        } else {
                            try state.retain(page_id);
                        }
                    }
                }
            }
        }
        // perf/lwa-orphan-pages (Bug 1): `checkpointRedoLog`'s own
        // `redo_fold_retire_pending` (see that field's own doc comment)
        // names every page-shaped chain this fold's overlay snapshot
        // found superseded or deleted strictly within the window just
        // folded -- a version a later write in the same uncheckpointed
        // window already overwrote or deleted before any fold ever
        // applied it to the real tree, so the loop above never retains it
        // as a side effect of writing a surviving record. Retaining each
        // one here is idempotent (`retainUnretainedValueChainPages`'s own
        // `count(page) == 0` guard skips any page the sweep above, or a
        // surviving head's own write, already retained) and then
        // immediately queuing it for retirement gives the ledger the same
        // ownership a normal, non-redo overwrite's `IndexEditor` replace
        // already assigns inline when it displaces a record -- `.value`-
        // kind retirement's own epoch-gated completion (the switch a few
        // hundred lines up) defers the actual release until no reader
        // pinned at an older physical checkpoint could still need these
        // bytes, exactly like any other superseded value chain. Without
        // this, nothing ever marks a superseded page-shaped run for
        // retirement at all: it is retained once (by the sweep above, or
        // `retainUnretainedValueChainPages`'s own surviving-head walk
        // finding it already live) and never released, inflating
        // `retirementReserveBytes`/`current_file_bytes` forever.
        if (self.redo_fold_retire_pending) |retiring| {
            defer {
                self.allocator.free(retiring);
                self.redo_fold_retire_pending = null;
            }
            if (writes.pages.ledger) |state| {
                const checkpoint = self.activeCheckpoint();
                for (retiring) |chain| {
                    try self.retainUnretainedValueChainPages(state, checkpoint, chain.external_value_root_page, chain.external_value_len, null);
                    try state.retire(.{ .epoch = self.publicationEpoch(), .page = chain.external_value_root_page, .length = chain.external_value_len, .kind = .value });
                }
            }
        }
        var next = self.activeCheckpoint();
        // Diverting never touches a real page, so nothing above bumped
        // `commit_sequence` the way a copy-on-write build normally does
        // (inside `putDocumentBatch`/`putCatalogBatchForRoot`'s real-build
        // branch). Bump it explicitly so `commitTransactionWithDurability`'s
        // own `changed` check still sees this commit as having happened --
        // without this, a diverted commit would silently never get logged
        // at all (`changed == false` skips the log-append branches too).
        if (diverted_anything) next.commit_sequence += 1;
        // §9 (revised), point 4: allocator state changes only at a real
        // checkpoint. A diverting commit may still have allocated fresh
        // page ids above (`finishCatalogAppends`'s external value chains,
        // the one page-shaped exception -- see `RedoCommitState`'s own
        // doc comment), so `page_count` still advances to cover them, but
        // the ledger/free-map page itself is not reallocated or persisted:
        // there is nothing to retire or reuse yet, since no copy-on-write
        // page was built this commit.
        if (!diverting) next.free_map_root_page = try writes.pages.allocate();
        next.page_count = writes.pages.next_page_id;
        try writes.pages.flush();
        // Reserve a page for a possible commit manifest before
        // persistAllocator finalizes page_count, so -- if this commit turns
        // out to be manifest-eligible -- that page is already part of the
        // free-map/ledger's own covered range rather than a count bumped on
        // after the fact. Only the commit that might actually durably
        // publish reserves (allow_manifest_reservation), only once per
        // window (reserved_page == null): an intermediate flush inside a
        // large transaction (TransactionWrites.max_keys chunking) or an
        // earlier non-durable commit in the same since-last-durable window
        // must not each abandon their own reservation.
        if (self.allow_manifest_reservation and !self.no_sync and
            !self.manifest_builder.overflowed and self.manifest_builder.reserved_page == null)
        {
            // Always a fresh id, never a reused free page -- see
            // `PageAllocator.allocateFresh`'s doc comment. A reused page
            // can still be the live target of some other root this flush
            // never touched, and this reservation may itself end up
            // abandoned (this attempt might turn out `changed == false`,
            // which never adopts `next` into `self.header` at all) without
            // ever un-reserving it, so it must never risk a page anything
            // else still legitimately references.
            self.manifest_builder.reserved_page = try writes.pages.allocateFresh();
        }
        if (!diverting) {
            try self.persistAllocator(&writes.pages, &next);
        } else if (self.reserve_retirement_capacity and !self.maintenance_publication) {
            // §9 (redo + indexed reclamation, Bug 2's "too generous"
            // direction): a diverting commit never reaches
            // `persistAllocator`'s own ledger-backed reserve-capacity
            // admission check (`persistAllocator`'s own comment) -- no
            // ledger is attached to this commit's allocator
            // (`pageAllocatorForDivertingCommit`'s own doc comment, "never
            // ledger bookkeeping") -- so without this, a diverting commit
            // never enforces the bound a legacy (non-diverting) commit
            // always does: enough free page-id headroom left under
            // `max_file_bytes` for retirement's own future bookkeeping
            // (`allocator_v4.retirementReservePages`). That let an
            // ordinary small write succeed when the identical write would
            // correctly fail closed outside redo, silently admitting more
            // than the budget actually allows room for. Mirror
            // `persistAllocator`'s check here, reading the currently
            // *persisted* ledger instead of one attached to this
            // allocator -- a diverting commit never touches the real
            // ledger at all, so nothing this commit did needs to be
            // reflected in it first.
            // §9.7f: also credit already-free, reusable pages toward
            // `available_pages`, exactly like `persistAllocator`'s own
            // check does (`available = (limit/page_size - next_page_id)
            // +| (can_reuse ? free_pages : 0)`), rather than only
            // `limit/page_size - next.page_count`. Without this, a
            // diverting commit's own admission (this branch) was
            // strictly more conservative than a real commit's, for no
            // reason tied to the budget itself: `pageAllocatorForDivertingCommit`'s
            // own allocator is deliberately `append_only`/never reuses
            // anything (so *this* commit's own page-shaped exception, if
            // any, never consumes a free page), but that is a reason
            // this *specific* commit cannot reuse a page, not a reason
            // the file overall has no usable headroom -- free pages
            // already released by prior retirement (ordinary
            // superseded-chain cleanup) or by `checkpointRedoLog`'s own
            // `maybeShrinkRedoLogCapacity` are exactly the headroom this
            // check exists to recognize. Gated on `free_pages_verified`
            // the same way `PageAllocator.can_reuse` already requires a
            // verified free map before any instance may credit it.
            if (self.max_file_bytes) |limit| {
                const page_size = self.header.page_size;
                // `retirementReserveBytesWithCancel`'s own early return:
                // this whole check (both the reserve cost and the
                // free-pages credit) is meaningless without a real
                // ledger -- a non-indexed (`page_reuse = false`) file has
                // none at all, and `loadLedgerWithCancel` is not safe to
                // call on one.
                var reusable: u64 = 0;
                var reserve_bytes: u64 = 0;
                if (self.header.indexed_reclamation) {
                    const state = try self.loadLedgerWithCancel(self.activeCheckpoint(), self.allocator_cancel_token);
                    if (self.free_pages_verified) reusable = state.free_pages;
                    reserve_bytes = allocator_v4.retirementReservePages(self.maxPagePayloadBytes(), state.counts.items.len, state.pending.count()) *| self.header.page_size;
                }
                const available_pages = (limit / page_size -| next.page_count) +| reusable;
                if (available_pages *| page_size < reserve_bytes) return error.LiteStorageBudgetExceeded;
            }
        }
        if (self.manifest_commits_enabled) {
            // Guaranteed capacity even for a flush that wrote no fresh
            // pages (so `PageWriteBatch.flushCount`'s own reservation
            // never ran this window) -- a no-op once the file's first
            // window has already reserved it.
            try self.manifest_builder.reserveCapacity(self.allocator);
            self.manifest_builder.noteReused(&writes.pages.reused);
        }
        // Every page this flush allocated and should have written
        // (excluding the reserved manifest page itself, not yet written at
        // this point) must already be in manifest_builder -- unless
        // overflowed already latched (entries.count() crossed
        // max_single_sync_pages partway through this very flush, which
        // `note` stops recording from, by design: tryBuildCommitManifest
        // sees `overflowed` and falls back to presynced regardless of what
        // got missed after that point). A gap while NOT overflowed is
        // exactly the bug class that made an earlier version of this
        // feature unsafe (WS1 b): a page the manifest would need to list
        // but never would have.
        if (builtin.is_test and self.manifest_commits_enabled and !self.manifest_builder.overflowed) {
            var page_id = debug_starting_page_count;
            while (page_id < next.page_count) : (page_id += 1) {
                if (page_id == self.manifest_builder.reserved_page) continue;
                std.debug.assert(self.manifest_builder.entries.contains(page_id));
            }
            var reused_it = writes.pages.reused.keyIterator();
            while (reused_it.next()) |page| {
                // The manifest reservation (`flushTransactionWrites` above,
                // "Reserve a page for a possible commit manifest") calls the
                // same `PageAllocator.allocate()` every other page goes
                // through, so it can just as easily be satisfied from the
                // free list as from a fresh `next_page_id` bump -- nothing
                // steers it toward an append. When it is a reuse, the
                // reserved page lands in `writes.pages.reused` like any
                // other reused page, but by design (see `reserved_page`'s
                // doc comment) nothing writes through the tracked hook to
                // it during this flush: `tryBuildCommitManifest` writes it
                // directly, afterward, as either the real manifest page or
                // (every early-return path's `defer`) a filler page. Both
                // `encodeManifestPayloadAlloc` and `verifyManifest` already
                // treat the reserved page as a deliberate gap with no
                // `entries` record, independent of whether it came from
                // reuse or append. Skip it here exactly like the page_id
                // loop above already does.
                if (page.* == self.manifest_builder.reserved_page) continue;
                std.debug.assert(self.manifest_builder.entries.contains(page.*));
            }
        }
        try self.publishCheckpoint(next, false, null);
        self.transaction_writes = null;
        writes.deinit(self.allocator);
    }

    /// Writer-only barrier for a scan that must include prior staged writes.
    /// The caller holds the mutation lock. Checkpoint-based read APIs never
    /// access transaction state, so pinned readers need no mutation lock.
    pub fn materializeTransactionCheckpoint(self: *NativeFile) !CheckpointSlot {
        try self.flushTransactionWrites();
        return self.activeCheckpoint();
    }

    /// Resolves a `checkpoint_publication_uncertain` latch in-process, without
    /// a close+reopen, by re-reading the on-disk slot the failed publish
    /// targeted (`uncertain_slot`) and comparing it against the checkpoint
    /// that was in flight (`uncertain_checkpoint`).
    ///
    /// Two outcomes, both of which clear the latch:
    ///   - The slot matches (same commit_sequence, structurally valid, and
    ///     -- if it carries a manifest -- that manifest verifies): the write
    ///     actually landed before the error fired (a transient fault after
    ///     the bytes reached disk, e.g. a dropped fsync acknowledgment, or a
    ///     retry at the OS level this process never observed). Adopt it as
    ///     the active checkpoint exactly as a successful `publishCheckpoint`
    ///     would have.
    ///   - The slot does not match (absent, torn, stale, or still the
    ///     previous generation): the write never durably landed. The
    ///     previous checkpoint -- never touched by the failed attempt -- is
    ///     still the active, durable one, so nothing adopts; the caller's
    ///     lost commit simply needs to be retried from scratch (which is
    ///     always safe here: nothing claimed that commit succeeded).
    ///
    /// Returns `error.OutcomeReconciliationRequired` only when the disk
    /// itself cannot be read right now (I/O has not yet recovered) or no
    /// in-flight checkpoint was recorded -- the same error every caller
    /// already surfaces today, so adding this call changes nothing about
    /// their behavior on a persistent fault.
    pub fn reconcilePublicationUncertainty(self: *NativeFile) !void {
        if (!self.checkpoint_publication_uncertain) return;
        const slot_index = self.uncertain_slot orelse return error.OutcomeReconciliationRequired;
        const proposed = self.uncertain_checkpoint orelse return error.OutcomeReconciliationRequired;
        const io = self.runtimeIo();
        const file_size = self.file.length(io) catch return error.OutcomeReconciliationRequired;
        const on_disk = loadCheckpointSlot(self.file, io, self.header.page_size, file_size, slot_index);
        if (on_disk.commit_sequence == proposed.commit_sequence and
            validCheckpointSlot(on_disk) and
            verifyManifest(self.file, io, on_disk, self.header.page_size))
        {
            // The write landed. Adopt it exactly as the successful tail of
            // `publishCheckpoint` would have.
            self.header.checkpoints[slot_index] = on_disk;
            self.header.active_checkpoint = slot_index;
            self.last_synced_header = self.header;
        }
        // Else: the previous checkpoint is still active in `self.header`
        // (the failed attempt never overwrote it in memory) and still
        // durable on disk (the failed attempt never overwrote it there
        // either, by construction -- `publishCheckpoint` always targets the
        // *other* slot). The lost commit is simply redone by its caller.
        self.checkpoint_publication_uncertain = false;
        self.uncertain_checkpoint = null;
        self.uncertain_slot = null;
        // `publishCheckpoint`'s own `defer self.notifyPublication()` is the
        // only thing that normally keeps a caching observer (docstore's
        // `read_outcome_unknown`, in particular) in sync with this flag;
        // reconciling outside that function must fire the same observer
        // itself, or a read path gated on the observer's stale `true` would
        // keep refusing forever even though the write path above is clear.
        self.notifyPublication();
    }

    /// Debug-only: see `commit_span_depth`'s own doc comment. Panics
    /// immediately if a non-nested `beginTransaction` reaches this same
    /// instance while another span is still open -- the first-overlapping-
    /// begin backstop the lite-writer-race investigation asked for, wider
    /// than `assertActiveWriter` (which only compares *different*
    /// `NativeFile` pointers sharing one inode, so it can never catch two
    /// callers racing this exact instance). The three sanctioned
    /// same-call-stack reentries bracket their own nested call with
    /// `commit_span_nested_allowance` first, so they deepen the count here
    /// without panicking; everything else that finds the count already
    /// non-zero is a genuine second caller.
    fn debugEnterCommitSpan(self: *NativeFile) void {
        if (!debug_commit_span_tracking) return;
        const previous = self.commit_span_depth.fetchAdd(1, .acq_rel);
        if (previous != 0 and self.commit_span_nested_allowance == 0) {
            std.debug.panic(
                "lite: NativeFile.beginTransaction overlapped an already-open commit span on the same instance (path={s} depth_before={d}) -- two commits racing one NativeFile; this is always a caller-side serialization bug (the writer lease or group-commit queue failed to exclude a second commit on this exact file), never legitimate WS2 pipelining, which only ever overlaps two *different* NativeFile instances",
                .{ self.path, previous },
            );
        }
    }

    /// Debug-only counterpart to `debugEnterCommitSpan`, called via `defer`
    /// from `commitTransactionWithDurability`/`abortTransaction` once each
    /// has confirmed it owns an actually-open transaction (`previous =
    /// self.transaction_header orelse return ...` already succeeded) --
    /// never before that check, so a call that finds nothing to commit/abort
    /// never touches a guard it did not set.
    fn debugExitCommitSpan(self: *NativeFile) void {
        if (!debug_commit_span_tracking) return;
        const previous = self.commit_span_depth.fetchSub(1, .acq_rel);
        std.debug.assert(previous > 0);
    }

    /// The caller serializes writers and checkpoint acquisition throughout a
    /// transaction. Intermediate roots are private; existing pinned readers
    /// continue reading immutable pages from their own checkpoint.
    pub fn beginTransaction(self: *NativeFile) !void {
        if (self.read_only) return error.ReadOnly;
        if (self.transaction_header != null) return error.TransactionAlreadyActive;
        // A previous commit's durability is unknown. Try to resolve it from
        // disk in-process before refusing this one; see
        // `reconcilePublicationUncertainty`. Only a disk that is still
        // failing (or an inconsistent latch) falls through to the refusal.
        if (self.checkpoint_publication_uncertain) try self.reconcilePublicationUncertainty();
        try self.refreshIfWriterBaseStale();
        self.debugEnterCommitSpan();
        if (self.lease_managed) {
            if (self.inode_lock_ref.load(.acquire)) |entry| inode_lock.claimActiveWriter(entry, @intFromPtr(self));
            self.claimed_active_writer = true;
        }
        self.transaction_header = self.header;
        self.artifact_lease_transaction = false;
        self.allocator_certificate_staged = false;
    }

    /// Internal publication of durable immutable-source aliases. These groups
    /// contain no authored document/index writes. Mixed groups use the normal
    /// transaction policy instead, preserving batching and mandatory proof.
    pub fn beginArtifactLeaseTransaction(self: *NativeFile) !void {
        try self.beginTransaction();
        self.artifact_lease_transaction = true;
    }

    /// Mark a point inside an open transaction that one group-commit member's
    /// writes can be unwound back to, without touching any entry staged by
    /// another member before or after it (WS2). The caller must already hold
    /// an open transaction (`beginTransaction`/`beginArtifactLeaseTransaction`).
    ///
    /// Two complementary mechanisms cover the member's writes:
    ///  - `checkpoint` is a snapshot of this transaction's private root
    ///    pointers (document/catalog/index roots, page count, commit
    ///    sequence). A member's own writes are copy-on-write, so restoring
    ///    this snapshot verbatim discards anything the member flushed to
    ///    pages -- whether by `materializeTransactionCheckpoint` (any
    ///    mid-transaction read) or a size-triggered spill in `stageMutation`
    ///    -- without disturbing pages an earlier member already made
    ///    reachable. The pages themselves are not reclaimed; they are
    ///    unreferenced-but-allocated bytes until the next vacuum.
    ///  - `undo`/`undo_mark` covers whatever is still only in the in-memory
    ///    write set (`TransactionWrites.maps`), for the common case where no
    ///    flush happens. A flush replaces the `TransactionWrites` instance
    ///    (see `flushTransactionWrites`), so `writes` records which instance
    ///    this savepoint's undo log belongs to: `release`/`rollback` only
    ///    replay it when `self.transaction_writes` is still that same
    ///    instance, and otherwise rely on the checkpoint restore alone.
    pub fn beginTransactionSavepoint(self: *NativeFile) !TransactionSavepoint {
        if (self.transaction_header == null) return error.InvalidTransactionState;
        const writes = try self.transactionWrites();
        writes.undo_depth += 1;
        return .{
            .checkpoint = self.activeCheckpoint(),
            .writes_generation = self.transaction_writes_generation,
            .undo_mark = writes.undo.items.len,
            .overlay_undo_mark = if (self.redo) |*redo| redo.overlay_undo.items.len else 0,
            .logical_pending_mark = if (self.redo) |*redo| redo.logical_pending.items.len else 0,
            .pending_mark = if (self.redo) |*redo| redo.pending.items.len else 0,
            .pages_next_page_id = writes.pages.next_page_id,
        };
    }

    /// Keep every entry staged since `sp` and stop tracking undo for it.
    pub fn releaseTransactionSavepoint(self: *NativeFile, sp: TransactionSavepoint) void {
        const writes = self.transaction_writes orelse return;
        if (self.transaction_writes_generation != sp.writes_generation) return; // a flush already retired sp's undo log.
        std.debug.assert(writes.undo_depth > 0);
        writes.undo_depth -= 1;
        // The discarded entries' key/previous.key/previous.value all came
        // from `writes.value_arena` (stageMutation); it reclaims them with
        // everything else at `writes.clear`, so there is nothing to free
        // here now -- just stop tracking them for rollback.
        writes.undo.shrinkRetainingCapacity(sp.undo_mark);
    }

    /// Evicts `self.page_cache` for every page noted in
    /// `self.manifest_builder.entries` (every page any commit in the
    /// current since-last-durable window has written, appended or reused --
    /// `PageWriteBatch.flushCount`'s `note` call is the one choke point
    /// every page write passes through) that is below `boundary_page_count`.
    ///
    /// Both callers (`rollbackTransactionSavepoint`, `discardTransactionTail`)
    /// restore some earlier checkpoint's root pointers after a member or a
    /// whole transaction fails, which un-references any page it *reused*
    /// (a recycled, pre-existing id below the restored checkpoint's own
    /// `page_count`) -- but a reused page's fresh content was already
    /// write-through-cached under that id by `PageWriteBatch.flushCount`
    /// (`file.cacheWrittenPage`) before the failure, and restoring root
    /// pointers alone does not touch the cache. Left alone, that stale,
    /// never-durable content stays live under the page id for whichever
    /// later allocation reuses it next -- deterministically likely, since
    /// the free list this failed attempt drew from is otherwise untouched.
    /// A retry (of the same mutation, or any other transaction that reuses
    /// the same ids) can then read that abandoned content back by page id
    /// for its own bookkeeping and wrongly conclude part of its work is
    /// already done, silently skipping it -- an acknowledged write quietly
    /// missing content. Evicting a page that an earlier, still-valid
    /// non-durable commit in the same window wrote is a harmless,
    /// reads-through-to-disk no-op (that commit's bytes are correct and
    /// durable-in-memory), never a correctness cost. Must run before the
    /// caller resets `manifest_builder` (neither caller does so beforehand).
    ///
    /// Also evicts `self.secondary_page_cache` (the read generation's own,
    /// independent `PageCache` -- see `Store.initializeReadGenerationAssumeLocked`
    /// in docstore.zig) for the same page ids. The normal, successful-allocation
    /// path (`PageAllocator.allocate`) already evicts both caches the moment a
    /// page is reused; this rollback path evicted only `self.page_cache` until
    /// now, leaving the read generation's cache exactly as exposed to the
    /// original stale-content bug (see this function's own doc comment above)
    /// as `self.page_cache` was before dc74b9a91c -- a reader pinned to the
    /// read generation could read a failed attempt's abandoned content back
    /// for a page id a retry (or any later commit) then reuses.
    fn evictCacheForPagesReusedSince(self: *NativeFile, boundary_page_count: u64) void {
        if (!self.manifest_commits_enabled) return;
        var it = self.manifest_builder.entries.keyIterator();
        while (it.next()) |page_id| {
            if (page_id.* < boundary_page_count) {
                self.page_cache.remove(self.allocator, page_id.*);
                if (self.secondary_page_cache) |cache| cache.remove(self.allocator, page_id.*);
            }
        }
    }

    /// Undo every entry staged since `sp`. Restores the private checkpoint
    /// snapshot unconditionally (a no-op if nothing flushed since `sp`), and
    /// additionally replays the undo log against `writes.maps` when the
    /// `TransactionWrites` instance from `sp` is still the live one.
    pub fn rollbackTransactionSavepoint(self: *NativeFile, sp: TransactionSavepoint) void {
        self.evictCacheForPagesReusedSince(sp.checkpoint.page_count);
        defer self.header.checkpoints[self.header.active_checkpoint] = sp.checkpoint;
        // perf/lwa-txn-overlay (transaction isolation): undo exactly the
        // shared-overlay versions/pages this transaction pushed since
        // `sp`, and drop the matching bytes from this transaction's own
        // not-yet-logged record -- independent of `writes`'s own
        // generation below. A private flush, which doesn't touch
        // `self.header`'s root pointers under redo-log mode (no real tree
        // write happens for a diverted mutation), already moved anything
        // staged before the flush out of `writes.maps` and into `shared`/
        // `logical_pending`, so the checkpoint restore above cannot
        // discard it the way it discards a legacy, page-shaped flush's
        // build.
        if (self.redo) |*redo| {
            redo.undoOverlaySince(self.allocator, self.runtimeIo(), sp.overlay_undo_mark);
            redo.logical_pending.shrinkRetainingCapacity(sp.logical_pending_mark);
            redo.pending.shrinkRetainingCapacity(sp.pending_mark);
        }
        const writes = self.transaction_writes orelse return;
        if (self.transaction_writes_generation != sp.writes_generation) return; // already superseded by the checkpoint restore above.
        // perf/lwa-budget-tail (Bug 2): see `TransactionSavepoint
        // .pages_next_page_id`'s own doc comment for why rewinding the
        // cursor is only safe for a diverting commit's own allocator
        // (`PageAllocator.diverting`, set only by
        // `pageAllocatorForDivertingCommit`) -- never for a real,
        // page-shaped (non-diverting) build, even one with no ledger
        // attached (e.g. `indexed_reclamation` disabled), where a freshly
        // allocated id may already be `retain()`-ed inside a ledger's own
        // in-memory state with no way back. A diverting commit's own
        // pages, by contrast, are real, physically written bytes
        // (`stageMutation`'s external value chain, written eagerly at
        // stage time -- the "page-shaped exception" `pageAllocatorForDivertingCommit`'s
        // own doc comment names) that `checkpoint.page_count` (restored
        // above, verbatim, by every rollback already) never counted to
        // begin with, so the rewind itself is safe -- but the file is
        // still genuinely grown past that count, same as
        // `discardTransactionTail`'s own append-only tail (only this
        // rollback is savepoint-scoped, not whole-transaction, so it
        // cannot reuse that function directly: `self.header` has not
        // been reset to any earlier checkpoint here). Mirror its
        // cache-eviction-then-truncate pattern for just the rewound
        // range, or `check()`'s own `tail_bytes` validation correctly
        // flags the untruncated growth as invalid, not merely
        // reclaimable. Only a rewind, never an advance, in case some
        // other, unrelated mechanism already moved the cursor back past
        // this mark on its own.
        if (writes.pages.diverting and writes.pages.next_page_id > sp.pages_next_page_id) {
            const first_page = sp.pages_next_page_id;
            writes.pages.next_page_id = first_page;
            self.page_cache.discardFrom(self.allocator, first_page);
            const size = first_page * @as(u64, self.header.page_size);
            self.file.setLength(self.runtimeIo(), size) catch {
                self.checkpoint_publication_uncertain = true;
            };
        }
        std.debug.assert(writes.undo_depth > 0);
        writes.undo_depth -= 1;
        // Every key/value touched below (the popped undo entry's own key,
        // whatever `current`/`previous` it restores or discards) came from
        // `writes.value_arena` (stageMutation); it reclaims all of them
        // together at `writes.clear`, so none of them are freed here --
        // only the map/undo-log bookkeeping changes.
        while (writes.undo.items.len > sp.undo_mark) {
            const item = writes.undo.pop().?;
            const map = &writes.maps[item.root];
            if (item.previous) |previous| {
                if (map.getPtr(item.key)) |current| {
                    writes.bytes -= current.key.len + current.value.len;
                    current.* = previous;
                    writes.bytes += previous.key.len + previous.value.len;
                }
                // else: the key was removed by a later undo entry already.
            } else if (map.fetchRemove(item.key)) |kv| {
                writes.bytes -= kv.value.key.len + kv.value.value.len;
                writes.count -= 1;
            }
        }
    }

    pub fn abortTransaction(self: *NativeFile) void {
        defer self.artifact_lease_transaction = false;
        defer self.allocator_certificate_staged = false;
        // No commit follows, so no `publishCheckpoint` call will ever
        // consume this -- clear it now rather than leaving it to fire
        // against a later, unrelated `sync()`-triggered durable-header
        // flush on this same instance. See `claimed_active_writer`'s own
        // doc comment.
        defer self.claimed_active_writer = false;
        self.invalidateLedger();
        const previous = self.transaction_header orelse return;
        defer self.debugExitCommitSpan();
        // perf/lwa-txn-overlay (transaction isolation): discard every
        // shared-overlay version/page this transaction itself staged
        // (never a version some other, already-published commit owns --
        // safe under the single-writer model), and the not-yet-logged
        // record bytes that would otherwise bleed into whatever
        // transaction stages next on this same instance. See
        // `RedoCommitState.overlay_undo`'s own doc comment for the bug
        // this closes: previously, nothing here ever touched `shared` at
        // all, so an aborted transaction's writes stayed visible in the
        // overlay forever.
        if (self.redo) |*redo| {
            redo.undoOverlaySince(self.allocator, self.runtimeIo(), 0);
            redo.logical_pending.clearRetainingCapacity();
            redo.pending.clearRetainingCapacity();
        }
        if (self.transaction_writes) |writes| writes.deinit(self.allocator);
        self.transaction_writes = null;
        self.header = previous;
        self.transaction_header = null;
        self.discardTransactionTail();
        // See the matching comment in `commitTransactionWithDurability`'s
        // `errdefer`: an abort truncates this transaction's own pages away,
        // so any manifest tracking for them (and a `reserved_page` claimed
        // during one of its flushes) must not survive to be mistaken for a
        // later commit's own fresh reservation. Safe to drop unconditionally
        // -- the next durable commit just falls back to presynced.
        if (self.manifest_commits_enabled) self.manifest_builder.resetForNextWindow();
        self.namespace_directory_cache_root = std.math.maxInt(u64);
        deinitNamespaceDirectory(self.allocator, &self.namespace_directory_cache);
        self.namespace_directory_cache = .empty;
        self.namespace_directory_delta_depth = 0;
    }

    /// Rolls back a failed/aborted transaction. `page_cache.discardFrom`
    /// only evicts pages `>= first_page` (the newly appended tail, which
    /// `setLength` below also physically truncates away) -- it
    /// deliberately preserves everything below that boundary as belonging
    /// to the restored checkpoint (`self.header`, already reset to
    /// `previous` by every caller before this runs). `evictCacheForPagesReusedSince`
    /// (see its own doc comment) closes the gap that leaves for a page this
    /// failed attempt *reused* rather than appended.
    ///
    /// perf/lwa-rollback-clobber (#1216): `self.header` is the correctness-
    /// bearing input here, restored by `publishCheckpoint`'s own matching
    /// fix whenever a failure unwinds through its `durable_header` swap --
    /// but `self.durable_header`, when still set, is this file's own
    /// record of the last page_count a ride-along commit durably-enough
    /// (physically written, if not yet synced) reached, and is never
    /// smaller than this rollback's rightful boundary. Clamping against it
    /// is a backstop, not the fix: never truncate below the one boundary
    /// this instance itself already remembers as "already written," no
    /// matter which caller's own bug might otherwise hand `first_page` a
    /// stale, too-small value.
    fn discardTransactionTail(self: *NativeFile) void {
        const durable_floor = if (self.durable_header) |durable| durable.checkpoints[durable.active_checkpoint].page_count else 0;
        const first_page = @max(self.activeCheckpoint().page_count, durable_floor);
        self.page_cache.discardFrom(self.allocator, first_page);
        self.evictCacheForPagesReusedSince(first_page);
        const size = first_page * @as(u64, self.header.page_size);
        self.file.setLength(self.runtimeIo(), size) catch {
            self.checkpoint_publication_uncertain = true;
        };
    }

    pub fn commitTransaction(self: *NativeFile) !void {
        return self.commitTransactionWithDurability(true, null);
    }

    /// Reset accumulated manifest tracking when a bare (no caller-owned
    /// transaction) commit fails before it publishes. A transactional
    /// commit's failure is covered by `commitTransactionWithDurability`'s
    /// own `errdefer` (see its comment: dropping entries from this and any
    /// earlier non-durable attempt in the same since-last-durable window is
    /// always safe, since the next durable commit just falls back to
    /// presynced). A bare commit has no such errdefer and no
    /// `abortTransaction` call to lean on -- there is no transaction to
    /// abort -- so without this, a page noted (`PageWriteBatch.flushCount`'s
    /// hook) before a later step in the same bare commit fails would sit in
    /// `self.manifest_builder` until some *unrelated* later commit durably
    /// publishes and resets it, at best wasting memory and at worst (a
    /// `reserved_page` left set) silently steering that unrelated commit
    /// away from building a manifest of its own.
    fn resetBareCommitManifestWindow(self: *NativeFile) void {
        if (self.manifest_commits_enabled) self.manifest_builder.resetForNextWindow();
    }

    /// Reserve a manifest page for a bare (no caller-owned transaction)
    /// commit, right before it calls `persistAllocator` -- the same place
    /// `flushTransactionWrites` reserves its own (see that call site's
    /// comment for why this must run before `persistAllocator` finalizes
    /// `page_count`, and why the reservation is always a fresh page id,
    /// never a reused one). Every hand-rolled bare-commit tail below calls
    /// this instead of going straight to a presynced publish, so a small
    /// bare commit gets the same shot at the one-sync manifest path a
    /// transactional commit does.
    fn reserveBareCommitManifestPage(self: *NativeFile, pages: *PageAllocator) !void {
        if (self.manifest_commits_enabled and !self.no_sync and
            !self.manifest_builder.overflowed and self.manifest_builder.reserved_page == null)
        {
            self.manifest_builder.reserved_page = try pages.allocateFresh();
        }
    }

    /// The single manifest-build-and-publish tail every durable commit
    /// reaches, bare or transactional: note any pages this commit pulled
    /// from the free list (`PageWriteBatch.flushCount`'s hook already noted
    /// every page actually written, regardless of caller), try to build a
    /// manifest covering everything written since the last durable
    /// checkpoint, then publish -- one `syncData` when the manifest fits,
    /// the historical presynced two-sync fallback otherwise.
    /// `commitTransactionWithDurability` reaches the equivalent tail via
    /// `flushTransactionWrites` for transactional commits, so this is the
    /// one place manifest/presynced publication logic lives either way.
    fn publishBareCommit(self: *NativeFile, pages: *PageAllocator, next: *CheckpointSlot) !void {
        if (self.manifest_commits_enabled) {
            // See the matching comment in `flushTransactionWrites`.
            try self.manifest_builder.reserveCapacity(self.allocator);
            self.manifest_builder.noteReused(&pages.reused);
        }
        const manifest_prepared = if (self.manifest_commits_enabled) try self.tryBuildCommitManifest(next) else false;
        // Never the group-commit path: a bare commit has no outer Store
        // lock to release around its sync.
        if (!manifest_prepared) try self.syncIfRequired(null);
        try self.publishCheckpoint(next.*, manifest_prepared, null);
        // A bare commit never diverts (putDocumentBatch's bare-commit
        // branch calls this directly, without going through
        // flushTransactionWrites's diversion check at all), so it always
        // logs its own ride-along record on a redo-log file regardless --
        // but unlike commitTransactionWithDurability, nothing was ever
        // calling the same 25%-remaining backstop for it. A workload that
        // only ever issues bare commits (several existing tests call
        // putDocument directly on NativeFile, bypassing Store entirely)
        // would otherwise never checkpoint and eventually hit
        // error.LogFull. Harmless to check unconditionally: a no-op
        // whenever self.redo is null or the log isn't actually close to
        // full.
        try self.maybeAutoCheckpointRedoLog();
    }

    pub fn commitTransactionWithDurability(self: *NativeFile, durable: bool, hooks: ?SyncLockHooks) !void {
        defer self.artifact_lease_transaction = false;
        defer self.allocator_certificate_staged = false;
        // Whatever `beginTransaction` claimed is no longer meaningfully
        // pending once this call returns, on every path: the deferred
        // (non-durable) branch below never calls `publishCheckpoint` at
        // all for this transaction's own commit, and the "not changed"
        // branch's plain `sync()` may not either (nothing pending). Left
        // set, a stale `true` would let a much later, logically unrelated
        // `publishCheckpoint` call on this same instance (most commonly a
        // final `sync()` flushing a leftover `durable_header` at close)
        // wrongly check itself against a claim this instance no longer
        // means to still be asserting -- see `claimed_active_writer`'s own
        // doc comment. Deferred *after* the explicit `self.publishCheckpoint`
        // call the "changed" branch below makes synchronously, so that
        // call's own check-and-consume still sees the true value it needs.
        defer self.claimed_active_writer = false;
        const previous = self.transaction_header orelse return error.InvalidTransactionState;
        // A deferred (non-durable) commit never calls publishCheckpoint or
        // tryBuildCommitManifest below -- it only stages `next` into
        // self.header and returns, with no durability barrier at all. Its
        // writes still accumulate into self.manifest_builder (that is the
        // whole point of the since-last-durable-checkpoint window), but it
        // must not reserve a manifest page of its own: flushTransactionWrites
        // reserves one under allow_manifest_reservation, only for a commit
        // that might actually durably publish.
        const deferred_publication = !durable and !self.no_sync and !self.externally_locked;
        self.allow_manifest_reservation = !deferred_publication and self.manifest_commits_enabled;
        defer self.allow_manifest_reservation = false;
        // `flushTransactionWrites` (and everything else below, before the
        // success path's own `self.transaction_header = null` a few lines
        // down runs) can fail partway through a write already staged via
        // `stageMutation`'s `self.transactionWrites()` call. Without this,
        // an error here leaves `self.transaction_header`/`self.
        // transaction_writes` set forever (and `self.header` holding this
        // failed attempt's partial, uncommitted mutations, and
        // `commit_span_depth` never decremented): every later
        // `stagingTransaction()` check (that name's own doc comment) then
        // wrongly believes a transaction is still open, silently staging
        // every future write into the stale `TransactionWrites` instead of
        // ever really committing it again -- confirmed reachable live, via
        // `check()`'s own `liveStats`/`LiveRecordCursor` path hitting a
        // `std.HashMap` `pointer_stability` double-lock panic inside the
        // eventually-triggered `flushTransactionWrites` call on that same
        // stale, never-cleared instance.
        //
        // Calls `self.abortTransaction()` directly -- the *full* rollback
        // (header restore, `transaction_writes` deinit, `discardTransactionTail`,
        // manifest-window reset, `debugExitCommitSpan`), not a hand-rolled
        // partial copy of two of its fields, which an earlier version of
        // this errdefer was and which left two gaps: `self.header` was
        // never restored to `previous` (this failed attempt's partial
        // writes stayed live on the instance) and `commit_span_depth` was
        // never decremented. The latter depended on the *caller's own*
        // `errdefer self.abortTransaction()` to close it -- but
        // `abortTransaction` itself decides whether it has anything to
        // do by checking `self.transaction_header orelse return`, and this
        // errdefer already having cleared that same field by the time any
        // caller's own errdefer ran meant `abortTransaction` always took
        // the early return and silently skipped its own
        // `debugExitCommitSpan` call. Not a double-decrement -- a leak:
        // `commit_span_depth` stayed elevated forever, so the *next*,
        // wholly unrelated `beginTransaction` on this instance found a
        // stale nonzero depth and panicked with "overlapped an
        // already-open commit span", even though nothing was actually
        // racing it. Caught live by `checkpointRedoLogNested`'s own
        // `maybeAutoCheckpointRedoLog` path hitting
        // `error.LiteStorageBudgetExceeded` inside `flushTransactionWrites`
        // ("lite reclamation opportunistic redo checkpoint failure is
        // visible and recovers"/"lite reclamation budget rejects a
        // mutation before exhausting capacity").
        //
        // Calling the full `abortTransaction()` here is safe for a *later*
        // failure too (after the success-path `self.transaction_header =
        // null` a few lines down has already run): `abortTransaction`'s own
        // `self.transaction_header orelse return` guard then finds `null`
        // and returns immediately, a no-op, leaving that failure to the
        // unconditional `defer self.debugExitCommitSpan()` and the second
        // `errdefer` below exactly as before -- so this one `errdefer` is
        // correct, and is the only one needed, for every failure this
        // function can have, early or late.
        errdefer self.abortTransaction();
        try self.flushTransactionWrites();
        var next = self.activeCheckpoint();
        const changed = next.commit_sequence != previous.checkpoints[previous.active_checkpoint].commit_sequence;
        if (changed and !deferred_publication and self.allocator_certificate_on_commit and
            self.header.indexed_reclamation and self.free_pages_verified and self.durable_header == null and
            !self.checkpoint_publication_uncertain)
        {
            next.commit_sequence = previous.checkpoints[previous.active_checkpoint].commit_sequence + 1;
            // perf/lwa-fold-boundary: must be set *before* `sealAllocatorCheckpoint`
            // below, not after -- that call stamps a fingerprint of `next`
            // into the free-map root page, which a later reopen's
            // `inheritAllocatorCertificate` recomputes and compares byte
            // for byte; setting this field any later (e.g. back inside
            // `publishCheckpoint`, once it is about to write the slot)
            // would let the on-disk slot end up with a different
            // `redo_folded_through` than the one just sealed, failing
            // that comparison on every subsequent open. `self.redo ==
            // null or self.redo.?.checkpointing` is exactly "this will be
            // a real, physically-written checkpoint, not a diverted or
            // large-transaction-fallback one logged instead" -- see
            // `redo_folded_through`'s own doc comment for why that is
            // the correct boundary value for such a commit, not merely a
            // safe one.
            if (self.redo == null or self.redo.?.checkpointing) next.redo_folded_through = next.commit_sequence;
            try self.sealAllocatorCheckpoint(previous, next);
        }
        self.header = previous;
        self.transaction_header = null;
        defer self.debugExitCommitSpan();
        errdefer {
            if (!self.checkpoint_publication_uncertain) {
                self.discardTransactionTail();
                // A clean (not `OutcomeUnknown`) failure past this point --
                // most likely `tryBuildCommitManifest`'s own manifest-page
                // write, or `sealAllocatorCheckpoint` above -- means this
                // attempt's pages are truncated away by the call just above,
                // but whatever `manifest_builder` tracked for them (and any
                // `reserved_page` claimed for this attempt) is not. Carrying
                // that forward would let a retried commit mistake a stale,
                // now-reused-or-gone page id for its own fresh reservation.
                // Resetting here is always safe, even though it also drops
                // legitimate entries from earlier non-durable commits in the
                // same since-last-durable window: the next durable commit
                // just falls back to the presynced two-sync path instead of
                // risking an under- or over-complete manifest, exactly like
                // an ordinary `overflowed` latch.
                if (self.manifest_commits_enabled) self.manifest_builder.resetForNextWindow();
            }
            self.namespace_directory_cache_root = std.math.maxInt(u64);
            deinitNamespaceDirectory(self.allocator, &self.namespace_directory_cache);
            self.namespace_directory_cache = .empty;
            self.namespace_directory_delta_depth = 0;
        }
        if (changed) next.commit_sequence = previous.checkpoints[previous.active_checkpoint].commit_sequence + 1;
        // perf/lwa-fold-boundary: the general case of the same stamp the
        // certify-on-commit branch above already applies for itself --
        // most commits never go through that branch at all, so this is
        // where they get it instead. Harmless to reapply when that
        // branch already ran (same value, `next.commit_sequence` is
        // unchanged by this line too in that case).
        //
        // perf/lwa-read-audit: `!deferred_publication` added -- missing
        // here (unlike the certify-on-commit branch above, which already
        // requires it). `redo.checkpointing` means "this commit certifies
        // no unfolded logical work remains" (`reclaimPagesImpl`'s own
        // ledger-only commit, gated on exactly that), which makes the
        // stamp semantically correct even then -- but a *deferred*
        // publish (`durable=false`'s ride-along path, a few lines below)
        // never reaches `publishCheckpoint`'s real slot-write tail at
        // all: it only appends a redo-log record (`CompactCheckpoint`,
        // which carries no `redo_folded_through` of its own by design)
        // and stages `next` into `self.header` directly. Stamping here
        // regardless left `self.header`'s in-memory active checkpoint
        // slot permanently ahead of what the physical slot page (last
        // written by the previous real fold) actually holds, with
        // nothing short of the *next* real fold ever reconciling the
        // two -- confirmed live: `captureFullReadSnapshot`'s fresh,
        // by-path reopen recovered a `redo_folded_through` two behind
        // the live `self.header`'s, with every other field of the same
        // active slot byte-identical. Same shape as 6c82ab8a0e
        // (`stageAllocatorCertificate` stamping a value never reaching
        // the publish it was sealed against) -- a stamp applied somewhere
        // that does not control (or, here, does not even reach) the
        // actual serialized bytes. Skipping the stamp on the deferred
        // path is always safe (`redo_folded_through` simply carries
        // forward unchanged, same as any ordinary diverted commit),
        // and keeps `self.header` from ever running ahead of the
        // physical slot for this field: the next commit that actually
        // reaches this same site with `deferred_publication == false`
        // (or a real fold) applies it for real, serialized together
        // with everything else in that commit's own slot write.
        if (changed and !deferred_publication and (self.redo == null or self.redo.?.checkpointing)) next.redo_folded_through = next.commit_sequence;
        if (deferred_publication) {
            defer self.notifyPublication();
            // Keep the last durable checkpoint slots intact until an explicit
            // durability barrier. Readers on this handle see the new roots;
            // reopening after a crash sees the previous complete checkpoint.
            if (changed) {
                // Whether this commit's own deferred, non-durable append
                // below can still go ahead -- `false` only in the one edge
                // case handled after this block: even the page-shaped
                // flush below could not free enough room for the minimal
                // tracking entry (a live reader pin blocking every
                // `checkpointRedoLog` reclaim attempt, same edge case
                // `publishCheckpoint`'s own "page-shaped only" branch
                // documents). Declared before the `if (self.redo)` below
                // so the no-redo case (this stays `true`, unused) and the
                // redo case agree on one flag the code after both reads.
                var try_ride_along_append = true;
                if (self.redo) |*redo| {
                    // Same preemptive check as `publishCheckpoint`'s own
                    // redo branch (see that comment for the full
                    // reasoning): this ride-along commit's own mutations
                    // are already staged in `redo.shared`
                    // (`flushTransactionWrites`'s diversion loop ran
                    // before this function was called), so if the log
                    // cannot fit this record, run a real checkpoint
                    // instead -- it already covers this commit -- and
                    // skip every bit of this ride-along's own bookkeeping
                    // below entirely, rather than layering a now-stale
                    // `next` on top of what the checkpoint already
                    // published.
                    if (redo.pendingRecordLen() > redo.writer.remaining()) {
                        if (redo.logical_pending.items.len != 0) {
                            // This commit diverted logical mutations, so
                            // `checkpointRedoLog`'s own fold (over
                            // `redo.shared`, which the same
                            // `appendLogicalMutation` call already
                            // populated) genuinely covers them: once it
                            // returns, this commit is already durable as
                            // part of the checkpoint it just published,
                            // and nothing is left to log. Clearing
                            // `logical_pending`/`pending` here matters --
                            // `checkpointRedoLog` has no knowledge of
                            // them, only of `redo.shared`, so skipping
                            // this would leave them staged forever,
                            // growing unboundedly across every later
                            // commit.
                            // The fold begins from `self.header`, reset to
                            // `previous` above; see `installCommitForFold`.
                            if (self.durable_header == null) self.durable_header = previous;
                            try self.installCommitForFold(redo, next);
                            try self.checkpointRedoLogNested();
                            redo.logical_pending.clearRetainingCapacity();
                            redo.pending.clearRetainingCapacity();
                            // perf/lwa-txn-overlay: this commit's content
                            // just published via the fold above -- see
                            // `dropOverlayUndo`'s own doc comment for why
                            // this must run on every path that publishes,
                            // not just the ordinary `appendRecord` one.
                            redo.dropOverlayUndo(self.allocator);
                            return;
                        }
                        // Page-shaped only (or nothing of this commit's
                        // own -- either way, safe to flush unconditionally):
                        // a bare commit's own real pages (document index,
                        // free map, namespace directory -- not just
                        // external value chains) are diverted here too
                        // (`PageWriteBatch.flushCount`), with no logical
                        // mutation ever staged alongside them, so
                        // `checkpointRedoLog`'s logical-heads fold has
                        // nothing to "absorb" -- it operates on a wholly
                        // separate checkpoint computation than this
                        // commit's own already-correct `next`, and
                        // calling it here would discard `next` instead of
                        // publishing it. Flush the real pages directly
                        // to their own locations instead, then fall
                        // through to publish `next` exactly as this
                        // ride-along branch always does.
                        const pages = try redo.shared.snapshotAllPagesAlloc(std.heap.page_allocator, self.runtimeIo());
                        defer std.heap.page_allocator.free(pages);
                        for (pages) |p| {
                            defer std.heap.page_allocator.free(p.bytes);
                            try self.file.writePositionalAll(self.runtimeIo(), p.bytes, p.page_id * @as(u64, self.header.page_size));
                        }
                        redo.shared.removePages(std.heap.page_allocator, self.runtimeIo(), pages);
                        redo.pending.clearRetainingCapacity();
                        // §9 (redo log full under a reader pin): mirrors
                        // `publishCheckpoint`'s own re-check after the
                        // identical page-shaped flush -- this commit's own
                        // page-shaped content is already flushed above, so
                        // `pendingRecordLen()` is down to the bare tracking
                        // minimum, which can still exceed `remaining()` if
                        // a live reader pin has kept every
                        // `checkpointRedoLog` call from ever physically
                        // reclaiming log bytes. Falling through to
                        // `redo.appendRecord` regardless -- what this used
                        // to do -- would surface the log's own
                        // `error.LogFull` directly, uncaught, on a commit
                        // that is not actually uncertain, merely out of
                        // room to log its own non-durable tracking entry.
                        try_ride_along_append = redo.pendingRecordLen() <= redo.writer.remaining();
                    }
                }
                if (try_ride_along_append) {
                    const was_durable_header_null = self.durable_header == null;
                    if (self.durable_header == null) self.durable_header = previous;
                    // §9.3: a ride-along redo-log commit still appends -- just
                    // like a ride-along copy-on-write commit still physically
                    // writes its pages today (`PageWriteBatch.flushCount`
                    // already ran, diverted, inside `flushTransactionWrites`
                    // above) -- but never syncs. The next commit whose own
                    // `durable` promotes a shared group covers it, exactly as
                    // §3.2a already describes for pages.
                    //
                    // Append (when a redo log backs this file) *before*
                    // publishing `next` into `self.header`, and let a failed
                    // append propagate without ever having touched the header.
                    // The reverse order (publish `self.header` first, append
                    // second -- what this used to do) left `self.header`'s
                    // `commit_sequence` permanently ahead of `redo.writer
                    // .last_sequence` the moment an append failed for any
                    // reason (`error.LogFull`, a transient I/O fault, ...):
                    // nothing here or in `commitTransactionWithDurability`'s
                    // own `errdefer` ever rolled the header back, so every
                    // later commit on this same file instance computed its own
                    // next sequence from the now-wrongly-advanced header --
                    // and could then never equal `redo.writer.last_sequence +
                    // 1` again. One ordinary transient append failure turned
                    // into a one-way ratchet: every subsequent commit,
                    // foreground or background, permanently failed with
                    // `error.SequenceOutOfOrder` (surfacing as the far less
                    // specific `error.OutcomeUnknown`), not a retryable,
                    // one-off error a caller's own retry could ever clear.
                    // Reproduced by "crash sweep: graph add-index mid-scenario"
                    // (gr_idx's/body_text's own background ride-along catch-up
                    // commits), independent of any crash or injected fault --
                    // the uncrashed discovery pass alone could hit it.
                    if (self.redo) |*redo| {
                        redo.appendRecord(self.allocator, next.commit_sequence, CompactCheckpoint.fromCheckpointSlot(next)) catch |err| {
                            // perf/lwa-maint-serialize: `appendRecord` no
                            // longer clears `logical_pending`/`pending` or
                            // drops `overlay_undo` on its own (see that
                            // function's own doc comment) -- a failed
                            // append here leaves this commit's own staged
                            // overlay versions/pages as the only record of
                            // what never published. Undo them the same way
                            // `rollbackTransactionSavepoint`/`abortTransaction`
                            // do, rather than leaving them to leak into a
                            // later fold as phantom, never-logged content.
                            redo.undoOverlaySince(self.allocator, self.runtimeIo(), 0);
                            redo.logical_pending.clearRetainingCapacity();
                            redo.pending.clearRetainingCapacity();
                            return err;
                        };
                        // perf/lwa-reclaim-reconcile: this ride-along
                        // append is this commit's own durability record
                        // for its diverted logical mutations (it becomes
                        // fully durable for free on a later commit's own
                        // sync, never retried or unwound on its own) --
                        // once `appendRecord` above returns successfully,
                        // there is nothing left to ever undo, so clear the
                        // pending buffers and drop the undo log now. Left
                        // undropped, `overlay_undo` kept accumulating this
                        // commit's entries right alongside the durable
                        // path's own.
                        redo.logical_pending.clearRetainingCapacity();
                        redo.pending.clearRetainingCapacity();
                        redo.dropOverlayUndo(self.allocator);
                    }
                    self.header.checkpoints[self.header.active_checkpoint] = next;
                    recoveryDebugLog("ride-along commit (non-durable) commit_sequence={d} captured_durable_header={} durable_header_commit_sequence={d}", .{
                        next.commit_sequence,
                        was_durable_header_null,
                        self.durable_header.?.checkpoints[self.durable_header.?.active_checkpoint].commit_sequence,
                    });
                    return;
                }
                // §9: even the minimal tracking entry has nowhere to go
                // (a live reader pin blocking every reclaim attempt) --
                // rather than fail this commit outright with the log's own
                // `error.LogFull`, fall through past this whole
                // `deferred_publication` block to the ordinary durable
                // path below (`publishCheckpoint`'s own ReadView-aware,
                // already-protected fallback), paying this one commit's
                // own sync instead of losing the write. `next`/`changed`
                // are untouched above, so that path sees exactly the same
                // state a non-deferred caller's commit would have.
            } else return;
        }
        if (changed) {
            recoveryDebugLog("durable commit commit_sequence={d} durable_header_was_set={}", .{ next.commit_sequence, self.durable_header != null });
            const manifest_prepared = if (self.manifest_commits_enabled) try self.tryBuildCommitManifest(&next) else false;
            // A redo-log file's own durability barrier runs inside
            // `publishCheckpoint` below (the log append + its one
            // `sync()`, §9.3 step 3) -- this `syncIfRequired` is the
            // v8/v9 manifest path's extra sync for an unprepared manifest
            // and would otherwise be a wasted, redundant fsync here.
            // Exception: `checkpointRedoLog`'s own transaction built real
            // pages above (`checkpointing = true` disabled every
            // diversion point for its span) and needs this ordinary sync
            // before its slot write, same as any non-redo commit.
            if (!manifest_prepared and (self.redo == null or self.redo.?.checkpointing)) try self.syncIfRequired(hooks);
            try self.publishCheckpoint(next, manifest_prepared, hooks);
            try self.maybeAutoCheckpointRedoLogNested();
        } else try self.sync();
    }

    /// Build step (d)'s automatic trigger (docs/design/lite-performance/
    /// lite-single-commit-write-path.md §9.9), scoped for now to a single
    /// bound checked synchronously on the commit that crosses it, not yet
    /// the owner-only background/idle-timer trigger via docstore.zig's
    /// ride-along/maintenance turn the design calls for. This still
    /// delivers the two properties that actually matter operationally:
    /// the log can never silently grow past its fixed capacity (bounding
    /// `RedoCommitState.overlay`/`logical_overlay` memory, which grows in
    /// lockstep with the log), and a writer that would otherwise fill the
    /// log *is* the backpressure -- it pays for the checkpoint itself,
    /// synchronously, rather than the log filling out from under it.
    /// Moving this onto an async/idle/owner-only trigger is follow-up
    /// work; it does not change this function's own correctness.
    ///
    /// Every caller reaches this *after* its own commit has already
    /// durably published (`publishCheckpoint`, just above either call
    /// site) -- unlike `publishCheckpoint`'s own preemptive branch, where
    /// running a real checkpoint instead of a log append is the only way
    /// that specific commit completes at all, nothing here is required
    /// for the commit that got us this far: it is purely opportunistic
    /// backpressure for whichever commit hits the log next. A failure --
    /// `error.LiteStorageBudgetExceeded` reached indexed_reclamation's
    /// checkpoint-time page work the moment this design let real
    /// page/allocator work defer to `checkpointRedoLog`, same as a
    /// transient disk-space or I/O error -- must never retroactively turn
    /// an already-durable write into a failure the caller then (wrongly)
    /// aborts, so it is never returned to the caller. Not silently
    /// dropped, though: `redo.checkpoint_pending_error` latches so the
    /// *next* commit retries unconditionally (see its own doc comment,
    /// and `redoCheckpointPendingError` for an outside observer), and
    /// `self.allocator_work.redo_checkpoint_failures` -- surfaced through
    /// `Store.reclamationStatus().allocator_work`, the same status both
    /// the budget and maintenance paths already read -- counts every
    /// failure so a persistent one (unlike a one-off transient I/O
    /// error) is visible to whatever is watching that status. Logged via
    /// `std.log.warn`, rate-limited to the first failure and every
    /// power-of-two one after that, so a budget stuck at capacity does
    /// not spam a line per commit.
    /// Calls `maybeAutoCheckpointRedoLog` from `commitTransactionWithDurability`'s
    /// own tail, reached right after this same call's own `publishCheckpoint`
    /// already succeeded -- the span this `*NativeFile` instance's
    /// `beginTransaction` opened is still held (the function has not
    /// returned yet), so `maybeAutoCheckpointRedoLog`'s own possible
    /// `checkpointRedoLog` call is a nested reentry, same reasoning as
    /// `checkpointRedoLogNested`.
    fn maybeAutoCheckpointRedoLogNested(self: *NativeFile) anyerror!void {
        if (debug_commit_span_tracking) self.commit_span_nested_allowance += 1;
        defer if (debug_commit_span_tracking) {
            self.commit_span_nested_allowance -= 1;
        };
        try self.maybeAutoCheckpointRedoLog();
    }

    fn maybeAutoCheckpointRedoLog(self: *NativeFile) anyerror!void {
        const redo: *RedoCommitState = if (self.redo) |*r| r else return;
        if (redo.checkpointing) return;
        if (!redo.checkpoint_pending_error and redo.writer.remaining() >= redo.writer.capacity / 4) return;
        // perf/lwa-fold-churn: the fold below is never a no-op cost just
        // because the log stays past the 25%-remaining line -- it runs a
        // real `IndexEditor` pass over every root plus
        // `SharedRedoOverlay.reclaim`'s own full scan. If the *last*
        // attempt found a cross-process reader pinned below the
        // checkpoint it would have published (`checkpoint_backoff_min_pinned`,
        // set by `checkpointRedoLogWithDurability`'s own `pinned_below`
        // branch), `remaining()` cannot have recovered since then -- the
        // writer only ever appended past the old tail, never reset over
        // it -- so without this check every single commit would repeat
        // the identical, identically-futile attempt for as long as that
        // one reader stays pinned. Checking whether the pin has moved is
        // one shared-memory read; skip the real attempt unless it has.
        // `checkpoint_pending_error` bypasses this (an actual failure,
        // not a reclaim-blocked-by-a-reader non-failure, must always keep
        // retrying per that flag's own doc comment).
        if (!redo.checkpoint_pending_error) {
            if (redo.checkpoint_backoff_min_pinned) |blocking| {
                const still_blocked = blk: {
                    const region = (self.regionForInode() catch break :blk false) orelse break :blk false;
                    const min_pinned = region.minimumUncoveredPinnedSequence(antfly_platform.process.currentId() orelse 0, redo.shared.minimumPin(self.runtimeIo())) orelse break :blk false;
                    break :blk min_pinned <= blocking;
                };
                if (still_blocked) return;
            }
        }
        self.checkpointRedoLog() catch |err| {
            redo.checkpoint_pending_error = true;
            self.allocator_work.redo_checkpoint_failures +|= 1;
            const failures = self.allocator_work.redo_checkpoint_failures;
            if (failures == 1 or std.math.isPowerOfTwo(failures)) {
                std.log.warn("lite: opportunistic redo-log checkpoint failed, retrying on a later commit (path={s} err={s} failures={d})", .{ self.path, @errorName(err), failures });
            }
            return;
        };
        redo.checkpoint_pending_error = false;
    }

    /// Whether `maybeAutoCheckpointRedoLog`'s own opportunistic checkpoint
    /// attempt is currently stuck failing (see `RedoCommitState
    /// .checkpoint_pending_error`'s own doc comment) -- `false` for a
    /// non-redo file. For an outside observer (a test, or a maintenance
    /// path deciding whether a stalled checkpoint needs attention beyond
    /// what the next commit's own retry will do on its own).
    pub fn redoCheckpointPendingError(self: *const NativeFile) bool {
        return if (self.redo) |redo| redo.checkpoint_pending_error else false;
    }

    /// WS1(b) single-fsync commits. A first attempt measured a
    /// 20,000-document bulk-indexed commit allocating ~41,000 pages while
    /// only 31 ever reached `ManifestBuilder.note` -- not an overflow cap,
    /// `note` was simply never called for the rest. That cause is fixed:
    /// the tracking window only opened inside
    /// `commitTransactionWithDurability` itself, but most of a
    /// transaction's page writes (external document/catalog values) happen
    /// eagerly inside `stageMutation`, called synchronously from
    /// `putDocument`/`putCatalogRecord` well before that window ever opens
    /// -- so the window missed almost everything. `manifest_builder` is
    /// now a persistent, file-lifetime field (never a per-commit local)
    /// that `PageWriteBatch.flushCount`'s hook always writes into when this
    /// flag is on, reset only in `publishCheckpoint` right after a durable
    /// publish succeeds. That also gives the window its correct "since the
    /// last durable checkpoint" scope for non-durable
    /// (`commitTransactionWithDurability(false)`) commits: verified with a
    /// dedicated test that tears an *earlier* non-durable commit's own page
    /// and confirms the eventual durable commit's manifest catches it.
    ///
    /// Still disabled, though, on a second finding: the debug cross-check
    /// in `flushTransactionWrites` (every page `PageAllocator.reused`
    /// reports for this flush must have a `manifest_builder` entry) fired
    /// against real DB-layer traffic (`storage.lite.backend.test.lite
    /// backend native engine can back db primary documents`) -- a page the
    /// allocator reused for this commit was never noted, meaning either a
    /// second, still-unfound write path bypasses the tracking hook, or
    /// reusing a page without ever writing to it in the same commit is
    /// itself a legitimate pattern this assert wrongly treats as a bug.
    /// Which of those it is was not determined before time ran out. Until
    /// it is, this flag stays off: the recovery/verification side
    /// (`verifyManifest`, `recoverActiveCheckpoint`, the v8 slot/manifest
    /// page formats, the compact appended-range encoding) is unaffected
    /// and stays covered by its own tests, and the debug assert (gated on
    /// this same flag, so inert while it is false) is exactly the tool to
    /// rerun once someone picks this back up -- it already reproduces
    /// against `make zig-test`-level traffic, not just a synthetic repro.
    ///
    /// Build step (c) of docs/design/lite-performance/
    /// lite-single-commit-write-path.md §9.9 turned this from a
    /// compile-time constant into `NativeFile.manifest_commits_enabled`,
    /// a per-instance field defaulting to `true` (identical behavior for
    /// every file that isn't a redo-log file): a redo-log file's own
    /// `enableRedoLog`/`recoverRedoLog` sets it `false`, since the v8/v9
    /// manifest this flag gates is exactly what the redo log replaces.
    /// Temporary diagnostic (test builds only, opt-in): prints which
    /// branch of `tryBuildCommitManifest` fell back to the presynced
    /// two-sync path, to find why an inline-publication commit
    /// (text/graph/sparse) pays 2 syncs instead of WS1(b)'s 1. Gated on
    /// `builtin.is_test` first so the env lookup never runs in a
    /// production build.
    fn debugManifestFallbackTraceEnabled() bool {
        if (!builtin.is_test) return false;
        return antfly_platform.env.getenv("ANTFLY_DEBUG_MANIFEST_FALLBACK_TRACE") != null;
    }

    /// Builds and writes a `.commit_manifest` page covering every page this
    /// commit's `PageWriteBatch` touched (documents, catalog/index pages,
    /// allocator/free-map ledger pages, value chains, and any certificate
    /// re-stamp from `sealAllocatorCheckpoint`), if the commit stayed within
    /// `max_single_sync_pages` pages and `flushTransactionWrites` reserved a
    /// page for it (see `ManifestBuilder.reserved_page`'s doc comment for
    /// why that page's id is never retrofitted onto `page_count` here). On
    /// success `next` gets `manifest_page`/`manifest_crc`/`manifest_page_count`
    /// and `presynced = false`; `publishCheckpoint`'s own sync, issued right
    /// after it writes the slot page, becomes the single barrier covering
    /// the data pages, this manifest page, and the slot together.
    ///
    /// `next` starts as a copy of the *previous* checkpoint (see
    /// `commitTransactionWithDurability`), so it arrives already carrying
    /// that generation's `manifest_page`/`manifest_crc`/`manifest_page_count`/
    /// `presynced` -- those must never survive into a commit that did not
    /// itself rebuild a manifest, or recovery would verify an entry list
    /// some unrelated, possibly already-overwritten earlier commit wrote.
    /// This function clears all four to the safe presynced default
    /// unconditionally before anything else, so every early return here (no
    /// reservation, no entries, too many entries, or the encoded manifest
    /// would not fit one page) falls back to the historical
    /// presync-then-slot-sync order with a clean slot, not a stale one.
    fn tryBuildCommitManifest(self: *NativeFile, next: *CheckpointSlot) !bool {
        const builder = &self.manifest_builder;
        next.manifest_page = 0;
        next.manifest_crc = 0;
        next.manifest_page_count = 0;
        next.presynced = true;
        const manifest_page_id = builder.reserved_page orelse {
            if (debugManifestFallbackTraceEnabled()) std.debug.print("manifest fallback: no reserved_page\n", .{});
            return false;
        };
        var used = false;
        defer if (!used) {
            var filler_buf: [max_page_size]u8 = undefined;
            const filler = filler_buf[0..self.header.page_size];
            encodePage(filler, .commit_manifest, &[4]u8{ 0, 0, 0, 0 });
            self.file.writePositionalAll(self.runtimeIo(), filler, manifest_page_id * @as(u64, self.header.page_size)) catch {};
        };
        if (builder.overflowed) {
            if (debugManifestFallbackTraceEnabled()) std.debug.print("manifest fallback: overflowed\n", .{});
            return false;
        }
        const count = builder.entries.count();
        if (count == 0 or count > max_single_sync_pages) {
            if (debugManifestFallbackTraceEnabled()) std.debug.print("manifest fallback: count={d}\n", .{count});
            return false;
        }
        const entries = try self.allocator.alloc(ManifestEntry, count);
        defer self.allocator.free(entries);
        var i: usize = 0;
        var it = builder.entries.iterator();
        while (it.next()) |kv| {
            entries[i] = .{ .page_id = kv.key_ptr.*, .crc = kv.value_ptr.* };
            i += 1;
        }
        // v9: the multi-run encoding (see `encodeManifestPayloadAlloc`) has
        // no discontiguity failure mode left to catch here -- a window
        // with scattered appended pages just costs more runs, caught below
        // by the ordinary "too big to fit one page" check, same as always.
        const payload = try encodeManifestPayloadAlloc(self.allocator, entries, &builder.reused_pages, manifest_page_id);
        defer self.allocator.free(payload);
        if (payload.len > self.maxPagePayloadBytes()) {
            if (debugManifestFallbackTraceEnabled()) std.debug.print("manifest fallback: payload too big ({d} > {d})\n", .{ payload.len, self.maxPagePayloadBytes() });
            return false;
        }
        var page_buf: [max_page_size]u8 = undefined;
        const page = page_buf[0..self.header.page_size];
        encodePage(page, .commit_manifest, payload);
        try self.file.writePositionalAll(self.runtimeIo(), page, manifest_page_id * @as(u64, self.header.page_size));
        if (builtin.is_test) PageWriteMetrics.record(.commit_manifest, page.len);
        next.manifest_page = manifest_page_id;
        next.manifest_crc = std.mem.readInt(u32, page[page_crc_offset..][0..4], .little);
        next.manifest_page_count = @intCast(count);
        next.presynced = false;
        used = true;
        return true;
    }

    /// The allocator root is already private to this transaction. Sealing it
    /// adds no allocation, catalog mutation, retirement, or durability barrier.
    /// Both recovery slots and the canonical ledger are covered independently.
    fn sealAllocatorCheckpoint(self: *NativeFile, previous: Header, next: CheckpointSlot) !void {
        for (previous.checkpoints) |slot| if (slot.free_map_root_page == next.free_map_root_page) return;
        const state = try self.loadLedgerForDigest(next, self.allocator_cancel_token, true);
        var published = previous;
        // perf/lwa-peer-cert: same prediction `stageAllocatorCertificate`
        // makes for the identical reason (see its own doc comment) --
        // this caller's own `next.redo_folded_through` stamp just above
        // already uses this exact condition to decide whether the
        // imminent publish is a real physical slot write (flips
        // `active_checkpoint`) or an in-place redo-log append (does
        // not); `published` must predict the same outcome, or this
        // fingerprint disagrees with the real `self.header` on every
        // later `inheritAllocatorCertificate` replay whenever the commit
        // diverts.
        if (self.redo == null or self.redo.?.checkpointing) published.active_checkpoint = 1 - previous.active_checkpoint;
        published.checkpoints[published.active_checkpoint] = next;
        var root: [192]u8 = @splat(0);
        allocator_v4.State.encodeRoot(state.root, root[0..128]);
        std.mem.writeInt(u64, root[56..64], 3, .little);
        @memcpy(root[128..160], &fingerprintHeader(published));
        @memcpy(root[160..192], &try state.incrementalFingerprint());
        try self.writePage(next.free_map_root_page, .free_map, &root);
    }

    /// `manifest_prepared` must be `true` only when the caller itself just
    /// built and wrote a commit manifest for `proposed` (currently only
    /// `commitTransactionWithDurability`, via `tryBuildCommitManifest`).
    /// Every other caller builds `proposed` by copying the previous
    /// checkpoint and touching only a few fields, which would otherwise
    /// carry that previous generation's `manifest_page`/`manifest_crc`/
    /// `manifest_page_count`/`presynced` forward unexamined -- recovery
    /// would then re-verify a stale entry list an unrelated, possibly
    /// already-overwritten commit wrote. `false` resets all four to the
    /// safe presynced default before anything else.
    /// Publishes this handle's own just-durable commit sequence to the
    /// per-inode registry entry (shared, in this process, by every other
    /// `NativeFile` instance on the same inode), so any of them can tell
    /// whether its own in-memory header/allocator state is stale relative
    /// to what another instance already committed -- the writer-side twin
    /// of the on-disk stale-base check. A no-op if this handle never
    /// registered with the registry (e.g. a bare test construction).
    fn publishCommittedSequenceToInode(self: *NativeFile) void {
        if (self.inode_lock_ref.load(.acquire)) |entry| inode_lock.publishCommittedSequence(entry, self.activeCheckpoint().commit_sequence);
    }

    /// The log-full fold in `commitTransactionWithDurability` and
    /// `publishCheckpoint` covers only the logical mutations in
    /// `redo.shared`, and it begins its own transaction from `self.header`,
    /// which still holds the pre-commit checkpoint. A commit that also built
    /// real pages (a large batch's bulk-built document index, say) has roots
    /// only `checkpoint` carries; folding on top of the old roots publishes a
    /// tree holding only the logical part and orphans the rest. Flush the
    /// diverted pages and install `checkpoint`'s roots first, keeping the
    /// pre-commit sequence so the fold's own commit takes exactly the
    /// sequence this commit would have, and the fold then publishes both.
    fn installCommitForFold(self: *NativeFile, redo: anytype, checkpoint: CheckpointSlot) !void {
        // A purely logical commit has no roots of its own to lose, and its
        // checkpoint already carries its own page retirements; basing the
        // fold on it would retire those pages a second time.
        const current = self.activeCheckpoint();
        if (checkpoint.document_index_root_page == current.document_index_root_page and
            checkpoint.document_root_page == current.document_root_page and
            checkpoint.catalog_root_page == current.catalog_root_page and
            checkpoint.index_catalog_root_page == current.index_catalog_root_page and
            checkpoint.namespace_directory_root_page == current.namespace_directory_root_page) return;
        const pages = try redo.shared.snapshotAllPagesAlloc(std.heap.page_allocator, self.runtimeIo());
        defer std.heap.page_allocator.free(pages);
        for (pages) |p| {
            defer std.heap.page_allocator.free(p.bytes);
            try self.file.writePositionalAll(self.runtimeIo(), p.bytes, p.page_id * @as(u64, self.header.page_size));
        }
        redo.shared.removePages(std.heap.page_allocator, self.runtimeIo(), pages);
        // §9 (redo + indexed reclamation): this call always runs
        // immediately before `checkpointRedoLogNested`'s own fold (both
        // call sites), so the pages just flushed above are exactly the
        // ones that fold's own `snapshotAllPagesAlloc`
        // (`checkpointRedoLogWithDurability`'s own `staged_pages`) would
        // otherwise have found and handed to `self.redo_fold_retain_pending`
        // for it. Removing them here first (to install this commit's own
        // roots before the fold starts) empties `redo.shared.pages`
        // before that later snapshot ever runs, so without this, that
        // snapshot sees nothing: a multi-page external value chain whose
        // record the fold is about to build gets its *root* retained as
        // usual (`retainRecord`, reached through the fold's own
        // `writePage`), but every *continuation* page beyond the root --
        // written raw by the original diverting commit, never through a
        // ledger -- is left permanently uncounted. That page then reads
        // as `count() == 0` forever, indistinguishable from "never
        // retained," until some later commit supersedes the record and
        // retires the chain: `releaseDeferred` finds a page it was never
        // told was live and fails closed with `error.InvalidNativeAllocator`
        // (confirmed via "capi resolver curation indexed static profiles
        // exclude seventeen thousand unrelated aliases after projection
        // and reopen" -- a document value chain's own continuation page,
        // flushed here ahead of a ride-along fold, never reached by
        // `checkpointRedoLogWithDurability`'s own tracking because
        // nothing was left for it to find). Record them the same way that
        // later tracking does, so the fold still picks them up.
        if (pages.len != 0 and self.header.indexed_reclamation) {
            if (self.redo_fold_retain_pending) |existing| {
                const merged = try self.allocator.alloc(u64, existing.len + pages.len);
                @memcpy(merged[0..existing.len], existing);
                for (pages, merged[existing.len..]) |p, *out| out.* = p.page_id;
                self.allocator.free(existing);
                self.redo_fold_retain_pending = merged;
            } else {
                const pending = try self.allocator.alloc(u64, pages.len);
                for (pages, pending) |p, *out| out.* = p.page_id;
                self.redo_fold_retain_pending = pending;
            }
        }
        var base = checkpoint;
        base.commit_sequence = self.activeCheckpoint().commit_sequence;
        self.header.checkpoints[self.header.active_checkpoint] = base;
    }

    fn publishCheckpoint(self: *NativeFile, proposed: CheckpointSlot, manifest_prepared: bool, hooks: ?SyncLockHooks) !void {
        // Backstop only: the real fix is `refreshIfWriterBaseStale`, called
        // from every entry point that gains the right to allocate or reuse
        // a page (`beginTransaction`, which `reclaimPagesImpl` also funnels
        // through, and `vacuumWithCancel`) *before* any allocation happens.
        // By the time a stale instance reaches publication, it has already
        // reused and overwritten pages out of its own stale free map --
        // refusing the publish here is too late to prevent the corruption,
        // only to detect that it already happened. This must never fire;
        // if it does, something upstream failed to refresh (or a new path
        // reaches `publishCheckpoint` without going through one of the
        // guarded entry points above), and that is a hard bug, not a
        // transient condition to retry around. Panics rather than
        // returning a catchable error, so it can never be silently
        // swallowed by a broad catch anywhere between here and a test
        // harness.
        if (self.transaction_header == null) {
            if (self.inode_lock_ref.load(.acquire)) |entry| {
                // Second backstop, scoped to `self.lease_managed` (see its
                // own doc comment): only the Owner's own live root and its
                // detached maintenance snapshot are ever marked, and only
                // `self.claimed_active_writer` (see its own doc comment)
                // narrows further to the one publish that actually ends a
                // transaction this exact instance began. Every other
                // publisher (recovery/replay at open, bare tests, a
                // borrowed index writer's rebind, a vacuum-prepared image,
                // ...) never claims or is checked here at all -- checking
                // them would be a guaranteed false positive, not a real
                // signal. The writer-lease admission gate (`WriterLane`/
                // `Owner`, capi/lite_connection.zig) is supposed to
                // guarantee at most one claimant between `beginTransaction`
                // and here for the instances this *does* cover.
                if (self.lease_managed and self.claimed_active_writer) {
                    self.claimed_active_writer = false;
                    inode_lock.assertActiveWriter(entry, @intFromPtr(self));
                }
                const base = self.activeCheckpoint().commit_sequence;
                const latest = inode_lock.committedSequence(entry);
                if (base < latest) {
                    std.debug.panic("lite: stale writer base reached publishCheckpoint (path={s} base={d} latest={d} proposed_seq={d})", .{ self.path, base, latest, proposed.commit_sequence });
                }
            }
        }
        var checkpoint = proposed;
        if (!manifest_prepared) {
            checkpoint.presynced = true;
            checkpoint.manifest_page = 0;
            checkpoint.manifest_crc = 0;
            checkpoint.manifest_page_count = 0;
        }
        try self.stampLogicalGenerations(&checkpoint);
        if (self.transaction_header != null) {
            self.header.checkpoints[self.header.active_checkpoint] = checkpoint;
            return;
        }
        // Capture fallible notification inputs before any checkpoint I/O.
        // Cancellation during publication must propagate without a second,
        // cancelable stat turning unwind into a process abort.
        const publication_inode: ?u64 = if (self.reader_coordinator != null) (try self.file.stat(self.runtime())).inode else null;
        const previous_tip = self.headerFingerprint();
        defer if (self.reader_coordinator) |coordinator| coordinator.published(publication_inode.?, previous_tip, self.headerFingerprint(), self.checkpoint_publication_uncertain);
        defer self.notifyPublication();
        // perf/lwa-rollback-clobber (#1216): capture what this swap is
        // about to discard so a failure anywhere below (a redo append/
        // sync failure, the v8/v9 slot write, the republish branch) can
        // restore it, instead of leaving `self.header` pinned at the
        // stale pre-ride-along `durable` snapshot while the file on disk
        // -- and `self.header` a moment ago -- already reflects every
        // ride-along commit's own, already-physically-written pages.
        // Reproduced live: a background reclaim's non-durable ride-along
        // commit grows the file to a new page_count (its own real pages,
        // written synchronously, just never fsynced -- §9.3's existing
        // ride-along discipline) and leaves `self.durable_header` holding
        // the *older* snapshot it superseded; a *different*, later
        // commit's own redo-log append then fails its sync, and without
        // this restore, this swap had already pointed `self.header` back
        // at that older, smaller snapshot with nothing to undo it --
        // `commitTransactionWithDurability`'s own `discardTransactionTail`
        // then truncates the file down to that stale, too-small page_count,
        // physically destroying the reclaim's already-written pages even
        // though they were never this failing transaction's own.
        var pre_durable_swap_header: ?Header = null;
        var pre_durable_swap_durable: ?Header = null;
        if (self.durable_header) |durable| {
            pre_durable_swap_header = self.header;
            pre_durable_swap_durable = durable;
            self.header = durable;
            self.durable_header = null;
        }
        errdefer if (pre_durable_swap_header) |header| {
            self.header = header;
            self.durable_header = pre_durable_swap_durable;
        };
        var redo_fell_back_to_slot = false;
        if (self.redo != null and !self.redo.?.checkpointing) {
            const redo = &self.redo.?;
            // Writer-race investigation (docs/design/lite-performance/
            // lite-single-commit-write-path.md §8/§9): `proposed`/`checkpoint`
            // can already be the writer's own last-appended record, not a
            // new one to log. This happens whenever a commit whose own
            // `apply` staged nothing new (`commitTransactionWithDurability`'s
            // `changed == false`) still needs to flush a *pending*
            // `durable_header` -- a deferred (`durable = false`) ride-along
            // commit earlier in this same chain already called
            // `redo.appendRecord` for this exact `commit_sequence` (writing
            // the bytes, never syncing them), and the "nothing changed"
            // branch above (`NativeFile.sync`'s `if (self.durable_header)
            // |_| try self.publishCheckpoint(self.activeCheckpoint(), ...)`
            // fallback) reaches here purely to make that already-written
            // record durable, not to add a new one. Calling
            // `redo.appendRecord` again for the same `commit_sequence` would
            // violate the writer's own `commit_sequence == last_sequence + 1`
            // continuity check (`error.SequenceOutOfOrder`, surfacing as the
            // far less specific `error.OutcomeUnknown`) -- not because two
            // commits ever raced each other on this `NativeFile` (the debug
            // backstop added alongside this fix, `beginTransaction`'s
            // `debugEnterCommitSpan`, proves they did not: this reproduces
            // single-threaded, deterministically, on every run), but because
            // this call is a legitimate *republish* of an already-logged
            // sequence, which only the v8/v9 slot-write path is idempotent
            // under -- rewriting the same checkpoint slot and re-syncing is
            // harmless there, which is exactly why `use_redo_log = false`
            // never surfaces this: it just republishes the identical slot
            // and never consults a continuity counter at all. Detected by
            // comparing against the writer's own already-appended tail
            // (`last_sequence`), not `redo.durable_sequence` (which only
            // tracks what is *synced*, not what is merely *appended* --
            // this call may be the very thing that syncs it for the first
            // time).
            if (redo.writer.last_sequence) |already_appended| {
                if (checkpoint.commit_sequence <= already_appended) {
                    self.publication_in_flight = true;
                    defer self.publication_in_flight = false;
                    (blk: {
                        if (comptime builtin.is_test) if (self.test_fail_checkpoint_publication) |err| {
                            self.test_fail_checkpoint_publication = null;
                            break :blk err;
                        };
                        // WS2: release the store mutex for exactly the
                        // fsync syscall, same protocol `syncIfRequired`
                        // already uses for the v8/v9 slot path -- see that
                        // function's own comment. Nothing appends to
                        // `redo.writer` here (this branch republishes an
                        // already-appended sequence), so there is nothing
                        // left to serialize against besides the fsync
                        // itself; `commit_in_sync` still fences every other
                        // `NativeFile` mutation (a new transaction, an
                        // allocate/reclaim, another checkpoint publish) out
                        // for this window, exactly as it does for the
                        // non-redo path.
                        if (hooks) |h| h.release(h.context);
                        defer if (hooks) |h| h.reacquire(h.context);
                        self.applyTestSyncDelay();
                        redo.writer.sync() catch |err| break :blk err;
                        break :blk {};
                    }) catch {
                        return error.OutcomeUnknown;
                    };
                    if (checkpoint.commit_sequence > redo.durable_sequence) redo.durable_sequence = checkpoint.commit_sequence;
                    self.publishRedoLogState();
                    self.header.checkpoints[self.header.active_checkpoint] = checkpoint;
                    wal_trace.recordCommit();
                    self.last_synced_header = self.header;
                    if (self.ledger) |state| {
                        self.retirement_activity_bytes +|= state.released_data_pages *| self.header.page_size;
                        self.retirement_activity_bytes +|= state.retired_inline_bytes;
                        state.released_data_pages = 0;
                        state.retired_inline_bytes = 0;
                    }
                    self.publishCommittedSequenceToInode();
                    return;
                }
            }
            // A log-full condition must be decided before anything is
            // appended, never discovered as a failed, partial append
            // (`error.LogFull`, surfacing as the far less specific
            // `error.OutcomeUnknown` below).
            var try_redo_log = true;
            if (redo.pendingRecordLen() > redo.writer.remaining()) {
                // perf/lwa-reuse-loss: the original condition here was
                // `redo.logical_pending.items.len != 0` -- *this* commit's
                // own diverted logical mutations. But `checkpoint` (the
                // slot about to be published, below, if we fall through)
                // names a `commit_sequence` that recovery's own
                // `redo_log.replay(..., start_after_sequence =
                // checkpoint.commit_sequence, ...)` treats as "everything
                // at or below this is already real, on disk" -- true only
                // if every version `redo.shared` holds at or below that
                // sequence has actually been folded into real pages.
                // `logical_pending` says nothing about *earlier* commits'
                // own still-unfolded heads sitting in `redo.shared.maps`
                // (accumulated across however many commits have landed
                // since the last real `checkpointRedoLog` fold): this
                // commit can easily have no logical mutation of its own
                // (a bare/page-only/no-op commit) while an earlier one's
                // key is still only logical, never folded. Publishing the
                // bare slot below in that case claims coverage of a
                // record that is not actually in real pages yet --
                // confirmed live as "redo differential oracle" data loss
                // (a key written a few commits before a reopen, lost
                // under redo, present under legacy) and as resurrection
                // (an overwrite/delete superseded in the overlay but
                // never folded, with recovery's replay skipping both the
                // live and the superseded version alike and falling back
                // to the real tree's older answer). Folding whenever
                // *any* root still has unfolded logical work -- not just
                // this commit's own -- keeps `checkpoint.commit_sequence`
                // truthful: `checkpointRedoLog` is a no-op when there is
                // truly nothing pending anywhere (`has_logical_work`,
                // mirroring its own early-return check), so this adds no
                // extra fold when `logical_pending` was already the only
                // thing outstanding.
                const log_full_io = self.runtimeIo();
                const has_unfolded_logical_work = redo.logical_pending.items.len != 0 or for (0..3) |root_idx| {
                    if (redo.shared.count(log_full_io, @intCast(root_idx)) != 0) break true;
                } else false;
                if (has_unfolded_logical_work) {
                    // This commit diverted logical mutations, already
                    // staged in `redo.shared` (the same
                    // `appendLogicalMutation` call that built
                    // `logical_pending` populated it too, inside
                    // `flushTransactionWrites`, before this function was
                    // ever called) -- so `checkpointRedoLog`'s own fold
                    // genuinely covers them: once it returns, this
                    // commit is already durable as part of the
                    // checkpoint it just published, and there is nothing
                    // left to log. Clearing `logical_pending`/`pending`
                    // matters here: `checkpointRedoLog` has no knowledge
                    // of them, only of `redo.shared`, so skipping this
                    // would leave them staged forever, growing
                    // unboundedly across every later commit. If
                    // `checkpointRedoLog` itself fails (e.g. no disk
                    // space to allocate the real pages it needs), that
                    // error propagates unchanged: `redo.shared`/
                    // `redo.writer` are untouched by a failed checkpoint
                    // attempt, so the log stays intact and the caller
                    // sees a clean, pre-decision error, never a torn
                    // append. This commit's own durability comes from
                    // `checkpointRedoLog`'s own real, physical publish
                    // (a genuine slot write + sync), regardless of
                    // whether that call could also reclaim log *bytes*
                    // (`pinned_below`, that function's own doc comment)
                    // -- unlike the page-shaped branch below, nothing
                    // here still needs the log to fit anything
                    // afterward.
                    try self.installCommitForFold(redo, checkpoint);
                    try self.checkpointRedoLogNested();
                    redo.logical_pending.clearRetainingCapacity();
                    redo.pending.clearRetainingCapacity();
                    // perf/lwa-txn-overlay: see the matching comment in
                    // `commitTransactionWithDurability`'s own ride-along
                    // branch above.
                    redo.dropOverlayUndo(self.allocator);
                    return;
                }
                // Page-shaped only, and no unfolded logical work anywhere
                // in `redo.shared` (checked above, not just this commit's
                // own `logical_pending`): a bare commit's own real pages
                // (document index, free map, namespace directory -- not
                // just external value chains) are diverted here too
                // (`PageWriteBatch.flushCount`), with no logical mutation
                // ever staged alongside them, so `checkpointRedoLog`'s
                // logical-heads fold has nothing to "absorb" -- it is a
                // wholly separate checkpoint computation from this
                // commit's own already-correct `checkpoint`, and calling
                // it here would discard `checkpoint` (never publish it)
                // instead. Flush the real pages directly to their own
                // locations instead, then fall through to publish
                // `checkpoint` exactly as this function always does.
                const pages = try redo.shared.snapshotAllPagesAlloc(std.heap.page_allocator, self.runtimeIo());
                defer std.heap.page_allocator.free(pages);
                for (pages) |p| {
                    defer std.heap.page_allocator.free(p.bytes);
                    try self.file.writePositionalAll(self.runtimeIo(), p.bytes, p.page_id * @as(u64, self.header.page_size));
                }
                redo.shared.removePages(std.heap.page_allocator, self.runtimeIo(), pages);
                redo.pending.clearRetainingCapacity();
                // §9 (redo log full under a reader pin): this commit's
                // own page-shaped content is already flushed above and
                // `pending` is now empty, so `pendingRecordLen()` is
                // down to the bare minimum -- the record's own framing
                // plus one fixed-size `CompactCheckpoint`, the tracking
                // entry every commit through this branch still appends
                // unconditionally below. That minimum can still exceed
                // `remaining()` if a live reader pin has kept every
                // `checkpointRedoLog` call (this commit's own
                // proactive one, or any earlier one) from ever
                // physically reclaiming log bytes
                // (`checkpointRedoLog`'s own `pinned_below` branch) --
                // no amount of further page-shaped flushing shrinks
                // this minimum, since there is nothing left to flush.
                // Checked again here, after clearing, rather than
                // trusting the first check above (which measured this
                // commit's full, pre-flush record): falling through to
                // `redo.appendRecord` regardless would surface the
                // log's own `error.LogFull` as the far less specific,
                // and wrong, `error.OutcomeUnknown` -- wrong because
                // nothing about this commit is actually uncertain, it
                // simply has nowhere to log its own tracking entry.
                try_redo_log = redo.pendingRecordLen() <= redo.writer.remaining();
            }
            if (try_redo_log) {
                // §9.1/§9.3: the on-disk checkpoint slot is untouched here --
                // it still names the last real checkpoint (build step (d) is
                // the only thing that ever advances it for a redo-log file).
                // This commit's durability comes entirely from appending
                // `pending` (everything `flushTransactionWrites` diverted
                // above) to the log and syncing it -- the commit's one fsync,
                // same durability boundary as the v8/v9 path's slot write +
                // `syncIfRequired`, just covering the log instead.
                //
                // Not replicated here: `checkpoint_publication_uncertain`/
                // `uncertain_checkpoint`/`uncertain_slot` and
                // `reconcilePublicationUncertainty`. Those exist to let a
                // *live* handle recover from a failed slot write without a
                // full reopen, specific to the two-physical-slot model; a
                // redo-log file's recovery path (`recoverRedoLog`) already
                // tolerates a torn or absent tail on the *next* open, which is
                // this design's answer to the same failure instead. A failed
                // sync (not append -- that can no longer fail with `LogFull`
                // here, per the preemptive checks above) still reports
                // `OutcomeUnknown`, so callers (`Store`'s reconciliation)
                // treat this commit exactly as uncertain as the v8/v9 path
                // would.
                self.publication_in_flight = true;
                defer self.publication_in_flight = false;
                // Captured before `appendRecord` below so a `sync()`
                // failure right after a successful append can roll the
                // writer's own cursor back to exactly here -- see
                // `redo_log.Writer.rollbackTo`'s own doc comment for why
                // this matters: without it, this record's bytes are
                // already physically indistinguishable from a durably
                // synced one, while this function's own failure path
                // below never advances `self.header`/`redo.durable_sequence`
                // to match, permanently desyncing the writer's physical
                // cursor from the logical state every later commit
                // computes its own next sequence from.
                const append_mark = redo.writer.mark();
                (blk: {
                    if (comptime builtin.is_test) if (self.test_fail_checkpoint_publication) |err| {
                        self.test_fail_checkpoint_publication = null;
                        break :blk err;
                    };
                    redo.appendRecord(self.allocator, checkpoint.commit_sequence, CompactCheckpoint.fromCheckpointSlot(checkpoint)) catch |err| break :blk err;
                    if (comptime builtin.is_test) if (self.test_fail_redo_sync) |err| {
                        self.test_fail_redo_sync = null;
                        break :blk err;
                    };
                    // WS2 (lite-single-commit-write-path.md §9.3/§3.2a):
                    // append under the lock (above; `redo_log.Writer` is
                    // "not safe for concurrent use from more than one
                    // caller," so the append itself needs full exclusion),
                    // then release the store mutex for exactly the fsync
                    // syscall and reacquire before touching anything else --
                    // the same protocol `syncIfRequired` already uses for
                    // the v8/v9 slot path. Without this, every stage
                    // serialized behind every fsync: the legacy path lets
                    // the *next* group's own `Txn` stage (and, at 8+
                    // concurrent writers, start its own commit) while this
                    // group's fsync is still running (`commit_in_sync`
                    // fences `NativeFile` mutation, not staging); this redo
                    // path held the lock across `redo.writer.sync()` too,
                    // so a new `Txn.openWrite`'s `lockStore` spun for the
                    // syscall's entire duration -- confirmed live as a
                    // multi-hour livelock in "a new Txn opens and stages
                    // while a group's fsync is in flight" at 8 concurrent
                    // writers, and a throughput regression (no group-commit
                    // fsync sharing) even below livelock-triggering
                    // concurrency.
                    if (hooks) |h| h.release(h.context);
                    defer if (hooks) |h| h.reacquire(h.context);
                    self.applyTestSyncDelay();
                    redo.writer.sync() catch |err| break :blk err;
                    break :blk {};
                }) catch {
                    redo.writer.rollbackTo(append_mark);
                    // perf/lwa-maint-serialize: `rollbackTo` above only
                    // restores the log writer's own physical cursor.
                    // `appendRecord` (on success, just above) no longer
                    // clears `logical_pending`/`pending` or drops
                    // `overlay_undo` itself -- see that function's own doc
                    // comment -- specifically so this catch block can still
                    // undo this commit's own staged overlay versions/pages
                    // (and discard its not-yet-logged record bytes) when
                    // the sync that would have made them durable fails.
                    // Without this, `self.redo.shared` kept this commit's
                    // content permanently, invisibly "published" with no
                    // corresponding durable log record, and the next
                    // `checkpointRedoLog` fold (background maintenance's
                    // own, or any other caller's) baked it into the real
                    // tree as if the commit had succeeded -- corrupting it
                    // in a way that outlives this ambiguous outcome and
                    // survives a clean reopen.
                    redo.undoOverlaySince(self.allocator, self.runtimeIo(), 0);
                    redo.logical_pending.clearRetainingCapacity();
                    redo.pending.clearRetainingCapacity();
                    return error.OutcomeUnknown;
                };
                // §9.7c (ReadView): `redo.writer.sync()` above is this
                // commit's own durability barrier, exactly like
                // `syncIfRequired`'s call below is for a non-redo file --
                // but it calls through `redo_log.Writer.sync` directly,
                // never through `syncIfRequired` itself, so it never used
                // to bump this counter. Several tests across both redo
                // and legacy modes assert an exact `test_sync_calls`
                // delta per durable commit; without this, a redo-log
                // file's own foreground writes always read back as zero
                // syncs, with no way to distinguish "no sync happened"
                // from "a sync happened, through a path this counter
                // doesn't know about."
                if (builtin.is_test) _ = self.test_sync_calls.fetchAdd(1, .monotonic);
                // Monotonic, not a bare assignment: the store mutex was
                // released for the `sync()` call just above, so -- in
                // principle, if some future caller is ever added that can
                // reach this same `redo.writer`/`redo.durable_sequence`
                // under `lockStoreExclusive` without going through this
                // exact append-then-sync sequence -- a reacquire here must
                // never retreat `durable_sequence` backward. Matches the
                // republish branch above, which already uses this form.
                if (checkpoint.commit_sequence > redo.durable_sequence) redo.durable_sequence = checkpoint.commit_sequence;
                // §9.3b: publish right after the append this process just
                // made durable, never before -- ride-along/deferred appends
                // elsewhere are unsynced and must never be visible to a
                // cross-process reader until a `durable=true` commit's own
                // sync (the one that just returned, above) covers them.
                // `redo.checkpoint_sequence` is untouched by an ordinary
                // commit (only `checkpointRedoLog` advances it), so this
                // publishes the same baseline a cross-process reader already
                // has whenever nothing has been checkpointed since it last
                // refreshed.
                self.publishRedoLogState();
                self.header.checkpoints[self.header.active_checkpoint] = checkpoint;
                wal_trace.recordCommit();
                self.last_synced_header = self.header;
                if (self.ledger) |state| {
                    self.retirement_activity_bytes +|= state.released_data_pages *| self.header.page_size;
                    self.retirement_activity_bytes +|= state.retired_inline_bytes;
                    state.released_data_pages = 0;
                    state.retired_inline_bytes = 0;
                }
                self.publishCommittedSequenceToInode();
                // perf/lwa-reclaim-reconcile: this is the ordinary (by far
                // most common) successful redo-log append -- durability
                // comes from `redo.writer.sync()` a few lines above, so
                // this commit's own logical mutations are exactly as
                // published as the fold/page-shaped branches' own calls to
                // `dropOverlayUndo` already treat theirs. Missing here,
                // `overlay_undo` kept accumulating every ordinary commit's
                // undo entries indefinitely (nothing ever drains it short
                // of a fold), so a *later*, unrelated commit's own
                // `abortTransaction`/`rollbackTransactionSavepoint` (mark
                // relative to *its own* starting length, `dropOverlayUndo`'s
                // own doc comment) walked straight through every earlier
                // commit's already-published entries too, each
                // `removeLastVersion` silently unwinding one more
                // genuinely-committed version. Before Bug 2
                // (perf/lwa-budget-tail) closed the diverting-commit budget
                // admission gap, a diverting commit essentially never
                // failed this way, so the leak never had anything to
                // wrongly undo; once it can fail, the very next rejected
                // commit erased every prior commit's own retirement debt,
                // observed live as `retirementNeedsService()` reporting
                // `false` after a sequence of successful overwrites that
                // had genuinely superseded chains to retire ("lite
                // reclamation capacity reserve sustains bounded
                // overwrites"/"drains wide value graphs").
                //
                // perf/lwa-maint-serialize: `appendRecord` above no longer
                // clears `logical_pending`/`pending` itself (see its own
                // doc comment) -- now that `redo.writer.sync()` has
                // actually succeeded, this commit is genuinely durable, so
                // clear both here, alongside the existing `dropOverlayUndo`
                // call.
                redo.logical_pending.clearRetainingCapacity();
                redo.pending.clearRetainingCapacity();
                redo.dropOverlayUndo(self.allocator);
                return;
            }
            // §9 (redo log full under a reader pin): even the minimal
            // tracking entry does not fit, and nothing here can make it
            // fit -- the log stays exactly this full until the pin
            // releases. This commit's own content is already real,
            // physical pages (flushed just above); fall through to the
            // ordinary, non-redo checkpoint-slot write below instead of
            // trying to log anyway. That slot write is itself a
            // complete, self-sufficient durability record for this
            // commit -- it needs nothing further from the log -- so
            // writes keep working for exactly as long as a pinned
            // reader keeps the log from reclaiming space, rather than
            // surfacing a commit that never took effect as
            // `error.OutcomeUnknown`.
            redo_fell_back_to_slot = true;
        }
        // perf/lwa-fold-boundary: `commitTransactionWithDurability`'s own
        // central site already stamps `redo_folded_through` for every
        // case where `self.redo.?.checkpointing` is knowable *before*
        // this call (non-redo files, `checkpointRedoLog`'s own fold,
        // `reclaimPagesImpl`'s ledger-only commit) -- early enough that
        // `sealAllocatorCheckpoint`'s own fingerprint (computed before
        // this function ever runs) already reflects it. The one case
        // that decision cannot see coming is this one:
        // `redo_fell_back_to_slot` is only known *here*, once the log-full
        // handling above has run. Stamp it now, for the same reason as
        // the early cases -- this commit's own content is already real
        // physical pages (flushed just above) and, by the time this
        // branch is reached, the shared overlay has already been proven
        // to hold no unfolded logical work at all
        // (`publishCheckpoint`'s own `has_unfolded_logical_work` check
        // above folds first otherwise) -- so `checkpoint.commit_sequence`
        // is not merely a safe upper bound on the fold boundary here, it
        // is the boundary. Carrying forward a stale value here instead
        // (the literal reading of "every other real publish carries the
        // folded-through value forward unchanged") would leave a real
        // gap in the log's own sequence numbering -- this commit's own
        // sequence, consumed above but never logged -- sitting *above*
        // the recorded boundary instead of within the superseded run
        // `redo_log.replay`'s own gap tolerance is built to absorb,
        // which a future reopen's strict continuity check cannot tell
        // apart from real corruption. Scoped to this one branch, not
        // every path through this function, because a certify-on-commit
        // fingerprint (`sealAllocatorCheckpoint`, gated on
        // `self.free_pages_verified`, never true for a commit that
        // diverted or attempted to) is never in flight for a commit that
        // reaches this branch -- unlike the early, `self.redo == null`
        // case, which every such fingerprint *does* go through. See
        // `redo_folded_through`'s own doc comment.
        if (redo_fell_back_to_slot) checkpoint.redo_folded_through = checkpoint.commit_sequence;
        const next_slot: u8 = if (self.header.active_checkpoint == 0) 1 else 0;

        // The whole slot -- roots, logical generations, and the manifest
        // descriptor -- is one page, written and CRC'd as a single unit.
        // Unlike the pre-v8 layout (a separate write for identities and for
        // the 72-byte slot, sharing header sector 0 with the other slot),
        // this is both one write instead of two and physically isolated
        // from the other slot and the header: a torn write here can never
        // damage either of them.
        var slot_buf: [max_page_size]u8 = undefined;
        const slot_page = slot_buf[0..self.header.page_size];
        encodeCheckpointSlotPage(slot_page, checkpoint);

        const io = self.runtimeIo();
        // Ground truth for `reconcilePublicationUncertainty` if the write
        // below fails: which slot and which proposed checkpoint were in
        // flight. Captured before the write unconditionally, but capturing
        // it is not itself "uncertain" -- see `checkpoint_publication_uncertain`'s
        // doc comment for why that flag is set only in the failure path
        // below, never proactively here.
        self.uncertain_checkpoint = checkpoint;
        self.uncertain_slot = next_slot;
        // A publish is "in flight" for this entire window regardless of how
        // it ends; concurrent code that only needs "wait for this to
        // finish" (never "reconcile") belongs on this flag, not on
        // `checkpoint_publication_uncertain`. See that field's doc comment.
        self.publication_in_flight = true;
        defer self.publication_in_flight = false;
        // From here until a failure sets the latch below, a failure leaves
        // the commit's durability unknown: report exactly that, not a raw
        // I/O error a caller might retry as if nothing had been written.
        (blk: {
            if (comptime builtin.is_test) if (self.test_fail_checkpoint_publication) |err| {
                self.test_fail_checkpoint_publication = null;
                break :blk err;
            };
            self.file.writePositionalAll(io, slot_page, slotPhysicalPage(next_slot) * @as(u64, self.header.page_size)) catch |err| break :blk err;
            if (builtin.is_test) PageWriteMetrics.record(.checkpoint_slot, slot_page.len);
            self.syncIfRequired(hooks) catch |err| break :blk err;
            break :blk {};
        }) catch {
            // Cancellation included: once slot I/O may have started, the
            // commit can already be durable, so "cancelled" would wrongly
            // read as "not applied". Only now -- a publication that
            // actually failed, possibly leaving disk ahead of header --
            // does `checkpoint_publication_uncertain` become true.
            self.checkpoint_publication_uncertain = true;
            return error.OutcomeUnknown;
        };

        self.header.checkpoints[next_slot] = checkpoint;
        self.header.active_checkpoint = next_slot;
        // perf/lwa-read-audit: a durable publish must leave the active
        // slot's on-disk bytes and `self.header`'s own in-memory copy
        // byte-identical, `redo_folded_through` included -- the whole
        // point of this slot write being one atomic page, not a
        // separately-tracked field. Decoding what was *actually* just
        // written (not re-deriving it from `checkpoint`, which would only
        // catch an encode bug, not a mismatched assignment) and comparing
        // against `self.header.checkpoints[next_slot]` catches a stamp
        // applied somewhere that does not control these exact bytes --
        // the same shape of bug as 6c82ab8a0e (`stageAllocatorCertificate`
        // fingerprinting a value the real publish never actually wrote)
        // and the `!deferred_publication` gap this branch's own caller,
        // `commitTransactionWithDurability`, just closed for the general
        // `redo_folded_through` stamp. Debug-only: a real decode plus a
        // full-struct comparison on every durable publish is not free.
        if (builtin.mode == .debug) {
            const written = decodeCheckpointSlotPage(slot_page) catch |err|
                std.debug.panic("lite: durable publish wrote an undecodable checkpoint slot: {s}", .{@errorName(err)});
            std.debug.assert(std.meta.eql(written, self.header.checkpoints[next_slot]));
        }
        self.checkpoint_publication_uncertain = false;
        self.uncertain_checkpoint = null;
        self.uncertain_slot = null;
        wal_trace.recordCommit();
        // This checkpoint is now the last durable one, whether it ended up
        // presynced (manifest rejected or never attempted) or not: either
        // way, whatever manifest_builder accumulated describes writes that
        // are now covered by *this* durable publish, not the next one.
        // Tracking restarts clean from here.
        if (self.manifest_commits_enabled) self.manifest_builder.resetForNextWindow();
        self.last_synced_header = self.header;
        if (self.ledger) |state| {
            self.retirement_activity_bytes +|= state.released_data_pages *| self.header.page_size;
            self.retirement_activity_bytes +|= state.retired_inline_bytes;
            state.released_data_pages = 0;
            state.retired_inline_bytes = 0;
        }
        // §9 (redo log full under a reader pin): this slot write is the
        // one taken above in place of the ordinary redo-log append,
        // when even that append's own minimal tracking entry could not
        // fit. `committedSequence`'s own contract reads
        // `redo.durable_sequence` exclusively for a redo-log file (its
        // own doc comment) -- this write just made `checkpoint` durable
        // exactly as thoroughly as a log append would have, so that
        // contract must reflect it too. Deliberately not also
        // `publishRedoLogState`: that call's own `durable_offset` is
        // the log's physical tail, unmoved here (nothing was appended),
        // so publishing an advanced `durable_sequence` paired with that
        // unmoved offset would tell a cross-process reader there is a
        // log record at a position where none exists -- an invariant
        // that function's own callers rely on, not merely a staleness
        // question its own doc comment excuses. Such a reader catches
        // up the ordinary way instead, through this now-durable
        // checkpoint slot on its own next reopen or refresh.
        if (redo_fell_back_to_slot) {
            self.redo.?.durable_sequence = checkpoint.commit_sequence;
            // This commit's sequence was consumed without ever being
            // appended to the log (the slot write above is its only
            // durability record). `redo.writer.last_sequence` still
            // reflects the last sequence actually logged, so the *next*
            // commit that does take the ordinary redo-log-append branch
            // would otherwise fail `Writer.append`'s own continuity
            // check (`error.SequenceOutOfOrder`): it would try to append
            // `last_logged + 1`, which is now stale by however many
            // commits fell back to this slot-write path in between.
            // Advance just the sequence counter, not `tail` -- no bytes
            // were written to the log region by this commit, so the
            // writer's physical append position must not move. This is
            // the same gap `checkpointRedoLog`'s own `pinned_below`
            // branch closes via `Writer.initAt` when it, too, consumes a
            // sequence without logging it.
            self.redo.?.writer.last_sequence = checkpoint.commit_sequence;
        }
        self.publishCommittedSequenceToInode();
    }

    fn notifyPublication(self: *NativeFile) void {
        if (self.publication_observer) |observer| observer.notify(observer.context, self.activeCheckpoint(), self.checkpoint_publication_uncertain);
    }

    /// Opts this handle's durability barriers into the raw `syncData`
    /// primitive. See the `durability_policy` field doc for when that is
    /// safe to call.
    pub fn setDurabilityPolicy(self: *NativeFile, policy: ?antfly_platform.filesystem.DurabilityPolicy) void {
        self.durability_policy = policy;
    }

    /// Test-only: sleep for `test_sync_delay_ns` before a durability-barrier
    /// syscall. Called on every commit fsync path -- the redo log's own
    /// `redo.writer.sync()` as well as `syncIfRequired` -- so a test that
    /// slows fsyncs to force group-commit sharing sees the delay no matter
    /// which durability path the file is on.
    fn applyTestSyncDelay(self: *NativeFile) void {
        if (comptime !builtin.is_test) return;
        const delay_ns = self.test_sync_delay_ns.load(.monotonic);
        if (delay_ns != 0) _ = std.c.nanosleep(&.{
            .sec = @intCast(delay_ns / std.time.ns_per_s),
            .nsec = @intCast(delay_ns % std.time.ns_per_s),
        }, null);
    }

    fn syncIfRequired(self: *NativeFile, hooks: ?SyncLockHooks) !void {
        if (!self.no_sync and self.transaction_header == null) {
            // WS2: release the caller's lock (if any) for exactly the
            // durability-barrier syscall -- the one part of a commit slow
            // enough to be worth not blocking a concurrent reader/writer
            // for -- and re-acquire it before returning, so every other
            // NativeFile field this function or its caller touches, before
            // and after, stays under that lock. `hooks` is this call's own
            // parameter, never a shared field: see `SyncLockHooks`.
            if (hooks) |h| h.release(h.context);
            defer if (hooks) |h| h.reacquire(h.context);
            self.applyTestSyncDelay();
            if (self.durability_policy) |policy|
                try antfly_platform.filesystem.syncData(self.file.handle, policy)
            else
                try self.file.sync(self.runtimeIo());
            if (builtin.is_test) _ = self.test_sync_calls.fetchAdd(1, .monotonic);
        }
    }

    pub fn sync(self: *NativeFile) !void {
        if (self.transaction_header != null) return;
        if (!self.checkpoint_publication_uncertain and self.durable_header == null)
            if (self.last_synced_header) |synced| if (std.meta.eql(synced, self.header)) return;
        // Never the group-commit path: a caller reaching here (Store's
        // `syncIndexContents`/`sync`, a bare durability barrier) holds its
        // own lock across this whole call, unreleased.
        try self.syncIfRequired(null);
        if (self.durable_header != null) try self.publishCheckpoint(self.activeCheckpoint(), false, null);
        self.last_synced_header = self.header;
    }

    pub fn failNextGenerationDirectorySyncForTest(self: *NativeFile) void {
        std.debug.assert(builtin.is_test);
        self.test_fail_generation_directory_sync = true;
    }

    /// Only a fresh/unpublished inode may change its namespace. Preserve a
    /// valid checked allocator seal: neither ownership nor recovery roots
    /// changed when this private image acquired its final publication name.
    fn bindPrivateEpochNamespace(self: *NativeFile, destination_path: []const u8) !void {
        _ = destination_path; // No longer used: the region is keyed by inode, not a path-resolved namespace.
        if (self.transaction_header != null or self.durable_header != null or self.checkpoint_publication_uncertain) return error.InvalidTransactionState;
        const next = self.header;
        if (next.indexed_reclamation) {
            const checkpoint = self.activeCheckpoint();
            if (checkpoint.free_map_root_page != 0) {
                const root = try self.readPagePayloadByKindAllocForCheckpoint(self.allocator, checkpoint.free_map_root_page, .free_map, checkpoint);
                defer self.allocator.free(root);
                if (root.len == 192 and std.mem.eql(u8, root[128..160], &self.headerFingerprint())) {
                    @memcpy(root[128..160], &fingerprintHeader(next));
                    try self.writePage(checkpoint.free_map_root_page, .free_map, root);
                }
            }
        }
        var encoded: [header_size]u8 = undefined;
        encodeHeader(&encoded, next);
        try self.file.writePositionalAll(self.runtimeIo(), &encoded, 0);
        self.header = next;
        self.last_synced_header = null;
        self.allocator_verification_base = null;
    }

    /// Bind and sync an exclusively owned, unpublished image before a caller's
    /// atomic rename. No readers may borrow this inode during preparation.
    pub fn preparePrivatePublication(self: *NativeFile, destination_path: []const u8) !void {
        if (self.read_only) return error.ReadOnly;
        try self.bindPrivateEpochNamespace(destination_path);
        try self.syncIfRequired(null);
    }

    /// Atomically publishes a fully built Lite generation into this file and
    /// adopts its already-open descriptor. The destination writer lock stays
    /// with `self`; `prepared` receives the retired descriptor and can be
    /// closed normally after this returns.
    pub fn replaceWithPreparedGeneration(self: *NativeFile, prepared: *NativeFile) !GenerationPublicationOutcome {
        if (self.read_only or prepared.read_only) return error.ReadOnly;
        if (std.mem.eql(u8, self.path, prepared.path)) return error.InvalidNativeSnapshotPath;

        const io = self.runtimeIo();
        try prepared.preparePrivatePublication(self.path);
        try renameFilePath(io, prepared.path, self.path);

        std.mem.swap(std.Io.File, &self.file, &prepared.file);
        // `self.file` now holds the fd `prepared` had open on its own
        // (staging) path, which the rename above just moved into
        // `self.path`'s place -- the inode is unchanged by a rename, so
        // `prepared.inode_lock_ref` (resolved against that same inode,
        // before the rename, at `prepared`'s own open/create time) is
        // still the correct shared registry entry for what is now
        // `self.path`'s target.
        //
        // Plain field reads/writes would race here: this codebase
        // deliberately allows a foreground commit to interleave with
        // another's released "sync window" (see that comment in
        // `pageAllocatorFromFreeMapWithProof`), and such a commit, running
        // on another thread, could read `self.inode_lock_ref` at any time,
        // including while this swap is in progress. Atomics give it a
        // whole, valid pointer either way -- the pre-swap or the post-swap
        // entry, never a torn one -- and whichever one it sees, the
        // `Handle` it acquires captures that exact entry (see
        // `inode_lock.zig`'s module doc comment), so this swap can only
        // ever change which entry a *future* acquire resolves to, never
        // which one an in-flight one releases against.
        const self_entry = self.inode_lock_ref.load(.acquire);
        const prepared_entry = prepared.inode_lock_ref.load(.acquire);
        self.inode_lock_ref.store(prepared_entry, .release);
        prepared.inode_lock_ref.store(self_entry, .release);
        // Tell the entry now reachable at `self.path` that its path
        // moved: a lazy fd reopen inside it (`ensureFd`, only reached if
        // `entry.fd` had gone back to `null`) must use the name the file
        // is reachable at *now*, not the one it was opened under
        // originally. `prepared`'s post-swap entry (if any) now refers to
        // the retired file the rename just replaced -- unlinked,
        // reachable by no path at all (its fd, if `entry.fd` is already
        // populated, stays valid regardless; `prepared.path`, the old
        // staging name, was never a name for this file and would be
        // actively wrong to rebind to). `prepared` is always closed by
        // its caller shortly after this call adopts its contents, well
        // before anything could need a lazy reopen there.
        if (prepared_entry) |entry| inode_lock.rebind(entry, io, self.path) catch {};
        if (self.inode_lock_ref.load(.acquire)) |entry| std.debug.assert(entry.inode == (try self.file.stat(io)).inode);
        const retired_header = self.header;
        self.header = prepared.header;
        prepared.header = retired_header;
        // `self.inode_lock_ref` now names a different `inode_lock.Entry`
        // (the swap above) -- `prepared`'s own, which may carry a
        // `last_committed_sequence` from `prepared`'s own, entirely
        // separate lineage (its own vacuum/compaction attempt, possibly
        // itself a retried or abandoned one) that has no relationship to
        // the header this call is adopting. A monotonic merge
        // (`publishCommittedSequenceToInode`) is the wrong operation here:
        // if that unrelated leftover happens to be *higher* than the
        // adopted header's own `commit_sequence`, merging would strand
        // this inode's registered sequence permanently ahead of a header
        // that can never publish a commit at that number -- every future
        // publish would then fail the `base < latest` backstop forever,
        // even though nothing is actually racing (reproduced: see
        // `resetCommittedSequence`'s own doc comment). Reset it outright
        // instead: the adopted header's own sequence is this inode's one
        // and only truth immediately after the swap, and nothing else may
        // have published to this entry since (the swap runs under the
        // writer-lease admission gate's own exclusivity).
        if (self.inode_lock_ref.load(.acquire)) |entry| inode_lock.resetCommittedSequence(entry, self.activeCheckpoint().commit_sequence);
        // §9.3a/§9.4/§9 (vacuum redo-log retention): the live `self.redo`,
        // if this file had one, still points its `writer` at the *old*
        // file's fd and byte offsets, which the swap above just moved into
        // `prepared.file` (about to be closed by this call's caller) and
        // which no longer correspond to anything in the compacted file
        // either way -- always drop it; uncheckpointed overlay content is
        // not lost by this, because every committed mutation already
        // reached the compacted file through `copyVacuumCatalogRecords`/
        // `copyVacuumDocumentRecords`'s overlay-aware `LiveRecordCursor`/
        // `OverlayScanState` scans.
        if (self.redo) |*redo| redo.deinit(self.allocator);
        self.redo = null;
        // The adopted header carries a reserved log region whenever
        // `prepareVacuum` found one on the source file (`reserve_redo_log`)
        // -- attach `self.redo` to it now, fresh, rather than reverting to
        // manifest-commit durability, or every redo-log store would
        // permanently lose the whole point of the redo-log write path the
        // moment maintenance first vacuumed it. Deliberately *not* done
        // any earlier (inside `prepareVacuum`, on `prepared` itself):
        // `prepared` was still under construction there --
        // `Store.performVacuum`'s own `preparePublicationSequence` and
        // catch-up-round machinery still had real, undiverted ledger/
        // free-map writes left to make against it before this generation
        // was ever adopted, and attaching redo state that early made every
        // one of those internal writes divert into an overlay instead of
        // writing real pages (confirmed live: `next_page_id`/`checkpoint.
        // page_count` kept advancing as if they had, so the adopted header
        // ended up claiming pages the file was never actually extended to
        // hold -- `recoverActiveCheckpoint`'s `candidates == 0` on the very
        // first read after an *online* vacuum). By this point every such
        // write this generation will ever make is already done, the swap
        // has settled, and `self.file`/`self.inode_lock_ref` are their
        // final, adopted values -- exactly `enableRedoLog`'s own
        // "nothing to replay yet" case (every live mutation already
        // reached the compacted tree through the ordinary copy pass, never
        // through this brand-new, still-empty log region), just reached
        // from a swapped-in generation instead of a freshly bootstrapped
        // file.
        if (self.header.redo_log_capacity != 0) {
            // perf/lwa-fold-boundary: for a genuinely vacuum-compacted
            // `prepared` (the only case this function's own doc comment
            // above promises), `redo_folded_through == commit_sequence`
            // already -- `prepareVacuum`'s compaction folds everything --
            // so these two arguments name the same value. They can
            // legitimately differ if `prepared`'s inode already carries a
            // shared overlay with content logged past its own last real
            // fold (see `attachFreshRedoState`'s own doc comment on this
            // split): the tip (`commit_sequence`) still names every such
            // version, so reads keep resolving them through that
            // surviving overlay, while the fold boundary
            // (`redo_folded_through`) stays truthful for `self`'s own
            // later folds.
            try self.attachFreshRedoState(io, self.header.redo_log_offset, self.header.redo_log_capacity, self.activeCheckpoint().commit_sequence, self.activeCheckpoint().redo_folded_through);
            // `attachFreshRedoState`'s own `Writer.init` call above always
            // resumes at `tail = 0`, correct only for the "nothing to
            // replay yet" case its doc comment promises (a vacuum's
            // `prepared`, never itself redo-attached). A caller that hands
            // this a `prepared` written to directly under redo (the
            // backup/restore-import path, not vacuum -- the exact case
            // the comment above this block already acknowledges can leave
            // `commit_sequence`/`redo_folded_through` genuinely different)
            // has real, valid records already sitting in the log region
            // between `redo_folded_through` and `commit_sequence`.
            // `prepared.redo` -- left completely untouched above, since
            // only `self.redo` is reset -- still holds `prepared`'s own
            // writer at its true on-disk tail/last_sequence. Resuming at
            // `tail = 0` instead would make this generation's very next
            // diverted commit physically overwrite the start of that
            // still-valid region, corrupting a reopen's replay
            // (`recoverRedoLog`'s `NativeRedoLogCorrupt`) even though
            // nothing had actually gone wrong on disk. `prepared.redo.
            // writer.file` already names the post-rename fd -- the same
            // value this function's own swap moved into `self.file` --
            // so only the position fields need to carry over.
            if (prepared.redo) |prepared_redo| {
                self.redo.?.writer.tail = prepared_redo.writer.tail;
                self.redo.?.writer.last_sequence = prepared_redo.writer.last_sequence;
            }
        } else {
            self.manifest_commits_enabled = true;
        }
        // Cross-process readers (§9.3b) cache this inode's log state from
        // the shared lock region's own published watermarks; push this
        // generation's fresh ones (a brand-new, still-empty log: tail 0,
        // `checkpoint_sequence`/`durable_sequence` both the vacuum's own
        // just-synced checkpoint) immediately, or a reader could keep
        // trusting the *old* generation's stale watermarks -- harmless
        // ("stale but safe" per this call's own doc comment) but needlessly
        // so, and actively wrong once this process's own fd/offsets no
        // longer correspond to anything the stale watermarks describe.
        self.publishRedoLogState();
        self.invalidateLedger();
        prepared.invalidateLedger();
        self.durable_header = null;
        prepared.durable_header = null;
        self.free_pages_verified = false;
        self.allocator_verification_base = null;
        prepared.free_pages_verified = false;
        prepared.allocator_verification_base = null;
        self.namespace_directory_cache_root = std.math.maxInt(u64);
        self.namespace_directory_delta_depth = 0;
        deinitNamespaceDirectory(self.allocator, &self.namespace_directory_cache);
        self.namespace_directory_cache = .empty;
        self.page_cache.clear(self.allocator);

        // The generation is already visible and the live handle has adopted
        // it. Preserve that committed state while returning an explicit
        // durability outcome to the layer that can finish rebinding runtime
        // metadata before surfacing it to the caller.
        if (!self.no_sync) {
            if (builtin.is_test and self.test_fail_generation_directory_sync) {
                self.test_fail_generation_directory_sync = false;
                std.log.err("Lite restore published but parent directory sync failed path={s} class={s}", .{ self.path, @errorName(error.InjectedGenerationDirectorySyncFailure) });
                return .durability_unknown;
            }
            fs_paths.syncDirPortable(io, std.fs.path.dirname(self.path) orelse ".") catch |err| {
                std.log.err("Lite restore published but parent directory sync failed path={s} class={s}", .{ self.path, @errorName(err) });
                return .durability_unknown;
            };
        }
        return .complete;
    }
};

/// `manifest` is the same choke point as `PageWriteBatch.flushCount`'s own
/// tracking: this free function writes directly to a raw `std.Io.File`
/// rather than through a `PageWriteBatch`, so it must note its own entry
/// rather than relying on that batch's loop to catch it. `null` is only
/// correct for callers with no commit-manifest concept at all (vacuum's
/// from-scratch image rebuild, test-only direct construction).
fn appendPageToFile(
    allocator: Allocator,
    file: std.Io.File,
    io: std.Io,
    page_size: usize,
    next_page_id: *u64,
    kind: PageKind,
    contents: []const u8,
    manifest: ?*ManifestBuilder,
) !u64 {
    if (contents.len > page_size - page_header_size) return error.PageTooLarge;
    const page_id = next_page_id.*;
    const page = try allocator.alloc(u8, page_size);
    defer allocator.free(page);
    encodePage(page, kind, contents);
    // Reserve before the write, same as `PageWriteBatch.flushCount`: see
    // `ManifestBuilder.reserveCapacity`'s doc comment for why `note` itself
    // must never allocate.
    if (manifest) |builder| try builder.reserveCapacity(allocator);
    try file.writePositionalAll(io, page, page_id * @as(u64, @intCast(page_size)));
    if (builtin.is_test) PageWriteMetrics.record(kind, page.len);
    if (manifest) |builder| builder.note(page_id, std.mem.readInt(u32, page[page_crc_offset..][0..4], .little));
    next_page_id.* += 1;
    return page_id;
}

const DocumentIndexChild = struct {
    first_key: []u8,
    key_page: u64,
    page_id: u64,
};

/// Packed B+ tree builder with one unfinished node per level. Long keys
/// remain record references, including separators; only the last input key is
/// materialized for order validation. Counting uses exactly the same frontier.
const DocumentIndexBulkBuilder = struct {
    const Level = struct {
        children: std.ArrayListUnmanaged(DocumentIndexChild) = .empty,
        bytes: usize = document_index_header_size + @sizeOf(u64),
    };

    owner: *NativeFile,
    file: std.Io.File,
    next_page_id: *u64,
    pages: ?*PageAllocator = null,
    count_only: bool = false,
    leaf_keys: std.ArrayListUnmanaged([]u8) = .empty,
    leaf_key_storage: ?[]u8 = null,
    leaf_key_used: usize = 0,
    leaf_pointers: std.ArrayListUnmanaged(u64) = .empty,
    leaf_key_pages: std.ArrayListUnmanaged(u64) = .empty,
    leaf_bytes: usize = document_index_header_size,
    last_key: std.ArrayListUnmanaged(u8) = .empty,
    has_last_key: bool = false,
    levels: std.ArrayListUnmanaged(Level) = .empty,

    pub fn deinit(self: *DocumentIndexBulkBuilder) void {
        if (self.leaf_key_storage) |storage| self.owner.allocator.free(storage);
        self.leaf_keys.deinit(self.owner.allocator);
        self.leaf_pointers.deinit(self.owner.allocator);
        self.leaf_key_pages.deinit(self.owner.allocator);
        self.last_key.deinit(self.owner.allocator);
        for (self.levels.items) |*level| {
            for (level.children.items) |child| self.owner.allocator.free(child.first_key);
            level.children.deinit(self.owner.allocator);
        }
        self.levels.deinit(self.owner.allocator);
    }

    fn appendNode(self: *DocumentIndexBulkBuilder, node: DocumentIndexNode) !u64 {
        if (self.owner.vacuum_workspace_limit) |limit| {
            if (self.next_page_id.* >= limit / self.owner.header.page_size) return error.LiteStorageBudgetExceeded;
        }
        if (self.count_only) {
            const page = self.next_page_id.*;
            self.next_page_id.* += 1;
            return page;
        }
        if (self.pages) |pages| return self.owner.writeDocumentIndexNode(pages, node);
        const encoded = try encodeDocumentIndexNode(self.owner.allocator, node);
        defer self.owner.allocator.free(encoded);
        return try appendPageToFile(self.owner.allocator, self.file, self.owner.runtimeIo(), self.owner.header.page_size, self.next_page_id, .document_index, encoded, if (self.owner.manifest_commits_enabled) &self.owner.manifest_builder else null);
    }

    fn add(self: *DocumentIndexBulkBuilder, key: []const u8, document_page_id: u64) !void {
        if (self.has_last_key and std.mem.order(u8, self.last_key.items, key) != .lt)
            return error.InvalidDocumentIndexOrder;
        if (key.len > std.math.maxInt(u16)) return error.RecordTooLarge;
        const external = key.len > index_inline_key_limit;
        const slot_size = 10 + (if (external) @as(usize, 8) else key.len);
        if (document_index_header_size + slot_size > self.owner.maxPagePayloadBytes()) return error.DocumentIndexNodeTooLarge;
        if (self.leaf_bytes + slot_size > self.owner.maxPagePayloadBytes()) try self.flushLeaf();
        const alloc = self.owner.allocator;
        try self.leaf_keys.ensureUnusedCapacity(alloc, 1);
        try self.leaf_pointers.ensureUnusedCapacity(alloc, 1);
        try self.leaf_key_pages.ensureUnusedCapacity(alloc, 1);
        try self.last_key.ensureTotalCapacity(alloc, key.len);
        var stored: []u8 = &.{};
        if (!external and key.len != 0) {
            if (self.leaf_key_storage == null) self.leaf_key_storage = try alloc.alloc(u8, self.owner.maxPagePayloadBytes());
            stored = self.leaf_key_storage.?[self.leaf_key_used..][0..key.len];
            @memcpy(stored, key);
            self.leaf_key_used += key.len;
        }
        self.leaf_keys.appendAssumeCapacity(stored);
        self.leaf_pointers.appendAssumeCapacity(document_page_id);
        self.leaf_key_pages.appendAssumeCapacity(if (external) document_page_id else 0);
        self.leaf_bytes += slot_size;
        self.last_key.clearRetainingCapacity();
        self.last_key.appendSliceAssumeCapacity(key);
        self.has_last_key = true;
    }

    fn flushLeaf(self: *DocumentIndexBulkBuilder) !void {
        if (self.leaf_keys.items.len == 0) return;
        const page = try self.appendNode(.{ .kind = .leaf, .keys = self.leaf_keys.items, .pointers = self.leaf_pointers.items, .key_pages = self.leaf_key_pages.items });
        const child = DocumentIndexChild{
            .first_key = try self.owner.allocator.dupe(u8, self.leaf_keys.items[0]),
            .key_page = self.leaf_key_pages.items[0],
            .page_id = page,
        };
        // pushChild consumes the separator even on failure.
        try self.pushChild(0, child);
        self.leaf_key_used = 0;
        self.leaf_keys.clearRetainingCapacity();
        self.leaf_pointers.clearRetainingCapacity();
        self.leaf_key_pages.clearRetainingCapacity();
        self.leaf_bytes = document_index_header_size;
    }

    fn pushChild(self: *DocumentIndexBulkBuilder, height: usize, child: DocumentIndexChild) anyerror!void {
        errdefer self.owner.allocator.free(child.first_key);
        if (height >= 64) return error.InvalidDocumentIndex;
        if (height >= self.levels.items.len) {
            const old = self.levels.items.len;
            try self.levels.resize(self.owner.allocator, height + 1);
            @memset(self.levels.items[old..], .{});
        }
        const slot_size = 10 + (if (child.key_page != 0) @as(usize, 8) else child.first_key.len);
        if (self.levels.items[height].children.items.len > 0 and
            self.levels.items[height].bytes + slot_size > self.owner.maxPagePayloadBytes())
        {
            if (self.levels.items[height].children.items.len < 2) return error.DocumentIndexNodeTooLarge;
            const parent = try self.sealLevel(height);
            try self.pushChild(height + 1, parent);
        }
        // Recursion can relocate levels, so reacquire this pointer afterward.
        const level = &self.levels.items[height];
        const extra = if (level.children.items.len == 0) 0 else slot_size;
        try level.children.append(self.owner.allocator, child);
        level.bytes += extra;
    }

    fn sealLevel(self: *DocumentIndexBulkBuilder, height: usize) !DocumentIndexChild {
        const level = &self.levels.items[height];
        const group = level.children.items;
        const page = try self.appendInternalGroup(group);
        const parent = DocumentIndexChild{ .first_key = group[0].first_key, .key_page = group[0].key_page, .page_id = page };
        for (group[1..]) |child| self.owner.allocator.free(child.first_key);
        level.children.clearRetainingCapacity();
        level.bytes = document_index_header_size + @sizeOf(u64);
        return parent;
    }

    fn finish(self: *DocumentIndexBulkBuilder) !u64 {
        try self.flushLeaf();
        var height: usize = 0;
        while (height < self.levels.items.len) : (height += 1) {
            const count = self.levels.items[height].children.items.len;
            if (count == 0) continue;
            var higher_pending = false;
            for (self.levels.items[height + 1 ..]) |level| {
                if (level.children.items.len != 0) higher_pending = true;
            }
            if (count == 1 and !higher_pending) return self.levels.items[height].children.items[0].page_id;
            const parent = try self.sealLevel(height);
            try self.pushChild(height + 1, parent);
        }
        return 0;
    }

    fn appendInternalGroup(self: *DocumentIndexBulkBuilder, children: []const DocumentIndexChild) !u64 {
        const alloc = self.owner.allocator;
        const keys = try alloc.alloc([]u8, children.len - 1);
        defer alloc.free(keys);
        const pointers = try alloc.alloc(u64, children.len);
        defer alloc.free(pointers);
        const key_pages = try alloc.alloc(u64, children.len - 1);
        defer alloc.free(key_pages);
        for (children, 0..) |child, i| {
            pointers[i] = child.page_id;
            if (i > 0) {
                keys[i - 1] = child.first_key;
                key_pages[i - 1] = child.key_page;
            }
        }
        return try self.appendNode(.{ .kind = .internal, .keys = keys, .pointers = pointers, .key_pages = key_pages });
    }
};

fn appendValuePagesToFile(
    allocator: Allocator,
    file: std.Io.File,
    io: std.Io,
    page_size: usize,
    chunk_size: usize,
    next_page_id: *u64,
    value: []const u8,
) !u64 {
    if (value.len == 0) return error.InvalidNativeValueChain;
    if (chunk_size == 0) return error.InvalidNativePageLength;
    const page_count = std.math.divCeil(usize, value.len, chunk_size) catch unreachable;
    const root_page_id = next_page_id.*;

    var offset: usize = 0;
    var page_index: usize = 0;
    while (offset < value.len) : (page_index += 1) {
        const len = @min(chunk_size, value.len - offset);
        const current_page_id = next_page_id.*;
        const next_value_page = if (page_index + 1 < page_count) current_page_id + 1 else 0;
        const payload = try allocator.alloc(u8, value_page_header_size + len);
        defer allocator.free(payload);
        std.mem.writeInt(u64, payload[0..8], next_value_page, .little);
        @memcpy(payload[value_page_header_size..][0..len], value[offset..][0..len]);
        // No commit-manifest concept here: unused in production (no callers).
        _ = try appendPageToFile(allocator, file, io, page_size, next_page_id, .value, payload, null);
        offset += len;
    }
    return root_page_id;
}

fn appendFreeMapPageToFile(
    allocator: Allocator,
    file: std.Io.File,
    io: std.Io,
    page_size: usize,
    next_page_id: *u64,
    covered_page_count: u64,
    free_pages: []const u64,
) !u64 {
    const payload = try encodeFreeMapAlloc(allocator, @intCast(page_size), covered_page_count, free_pages);
    defer allocator.free(payload);
    // Only used by vacuum's from-scratch image rebuild (presynced=true,
    // no commit-manifest concept there).
    return try appendPageToFile(allocator, file, io, page_size, next_page_id, .free_map, payload, null);
}

fn catalogRootPage(slot: CheckpointSlot, root: CatalogRoot) u64 {
    return switch (root) {
        .metadata => slot.catalog_root_page,
        .index => slot.index_catalog_root_page,
    };
}

fn setCatalogRootPage(slot: *CheckpointSlot, root: CatalogRoot, page_id: u64) void {
    switch (root) {
        .metadata => slot.catalog_root_page = page_id,
        .index => slot.index_catalog_root_page = page_id,
    }
}

pub fn create(io: std.Io, path: []const u8) !void {
    var writer_lock_file = (try acquireWriterLock(std.heap.page_allocator, io, path)).file;
    defer writer_lock_file.close(io);

    var encoded: [header_size]u8 = undefined;
    encodeHeader(&encoded, .{});

    const replace_existing = pathExists(io, path);
    const replacement_path = if (replace_existing)
        try realPathAlloc(std.heap.page_allocator, io, path)
    else
        null;
    defer if (replacement_path) |canonical| std.heap.page_allocator.free(canonical);
    const create_target = if (replacement_path) |canonical| canonical else path;
    const staging_path = if (replace_existing)
        try std.fmt.allocPrint(std.heap.page_allocator, "{s}.tmp-aflite-create", .{create_target})
    else
        null;
    defer if (staging_path) |tmp_path| std.heap.page_allocator.free(tmp_path);
    errdefer if (staging_path) |tmp_path| deleteFilePath(io, tmp_path) catch {};

    var file = try createDataFile(io, staging_path orelse create_target, .{ .truncate = true });
    var file_open = true;
    defer if (file_open) file.close(io);

    try file.writePositionalAll(io, &encoded, 0);
    try file.setLength(io, reserved_header_pages * @as(u64, default_page_size));
    var slot_buf: [default_page_size]u8 = undefined;
    encodeCheckpointSlotPage(&slot_buf, .{});
    try file.writePositionalAll(io, &slot_buf, slotPhysicalPage(0) * @as(u64, default_page_size));
    try file.sync(io);
    if (staging_path) |tmp_path| {
        file.close(io);
        file_open = false;
        renameFilePath(io, tmp_path, create_target) catch |err| {
            deleteFilePath(io, tmp_path) catch {};
            return err;
        };
    }
    try fs_paths.syncDirPortable(io, std.fs.path.dirname(create_target) orelse ".");
}

/// Deliberately stays on the single plain-flock fallback (§8.6) rather
/// than ever attempting the region: this owns a fresh `io_impl` (CLI
/// backup/export/import's "no caller-supplied `Io`" path), and a
/// `Region` caches whatever `Io` opened it (`Region.io`, used later by
/// `close`) for that handle's whole lifetime -- but `PathWriterLock`
/// values, `io_impl` included, are copied/moved pervasively by their own
/// callers (see `PathWriterLock.region`'s own doc comment), which would
/// leave a `Region` opened here pointing at a stale address the moment
/// this function's own `io_impl` local gets copied into the value this
/// returns. `lockWriterPathWithIo` has no such problem: its `io` is
/// always borrowed from a caller who owns their own `Io` instance
/// stably, never a freshly-created local about to move. A CLI single-
/// shot nonblocking attempt has little to gain from the region's own
/// fairness anyway.
pub fn lockWriterPath(allocator: Allocator, path: []const u8) !PathWriterLock {
    var io_impl = threaded_io_limits.initService(allocator);
    errdefer io_impl.deinit();

    const file = (try acquireWriterLock(allocator, io_impl.io(), path)).file;
    errdefer file.close(io_impl.io());

    return .{
        .io_impl = io_impl,
        .file = file,
    };
}

/// Acquires the same cross-process writer lock through a caller-owned
/// std.Io. §8.2's "plain" mode (the region's own `tryAcquireWriter`): a
/// single nonblocking attempt that, unlike `tryFairWriterLockWithIo`,
/// jumps the FIFO -- exactly this function's own pre-region behavior,
/// which never consulted `writer_queue` either. The real sidecar `flock`
/// (still the actual safety authority -- see `PathWriterLock.region`'s
/// own doc comment) is what every error below actually comes from.
pub fn lockWriterPathWithIo(allocator: Allocator, io: std.Io, path: []const u8) !PathWriterLock {
    const pid = antfly_platform.process.currentId() orelse 0;
    if (shared_lock_region.Region.open(std.heap.page_allocator, io, path)) |region_val| {
        var region = region_val;
        if (!region.tryAcquireWriter(pid)) {
            region.close();
            return error.WouldBlock;
        }
        errdefer region.close();
        errdefer region.releaseWriter();
        const file = (try acquireWriterLock(allocator, io, path)).file;
        errdefer file.close(io);
        const owned_region = try std.heap.page_allocator.create(shared_lock_region.Region);
        owned_region.* = region;
        return .{
            .io_impl = undefined,
            .borrowed_io = io,
            .file = file,
            .region = owned_region,
            .acquired_ns = std.Io.Clock.awake.now(io).nanoseconds,
        };
    } else |err| {
        if (!inode_lock.isRegionUnusable(err)) return err;
    }
    const file = (try acquireWriterLock(allocator, io, path)).file;
    errdefer file.close(io);
    return .{
        .io_impl = undefined,
        .borrowed_io = io,
        .file = file,
    };
}

/// Wait in the operating system's lock queue rather than racing short unlock
/// windows. Only an existing sidecar may be opened here: its creation must
/// continue to exclude readers using the data inode as their lock authority.
///
/// Not migrated onto the region, for either of `writer`'s two callers.
/// The reader case (`writer == false`, `capi/lite_connection.zig`'s own
/// blocking fallback when `lockReaderPathWithIo` returns busy) moves onto
/// the region's reader-pin table in a later, separate cutover; left
/// alone here so that cutover is a one-line swap, not a signature
/// change. The writer case (`writer == true`) is purely
/// `plainWriterLockUntil`'s own nested retry primitive -- never a public
/// admission decision of its own, since whatever ticket mattered for
/// fairness was already won (or never needed) by whichever top-level
/// constructor called `plainWriterLockUntil` in the first place. A first
/// attempt at migrating this one onto `Region.waitWriterFreeBounded`
/// opened a *fresh* `Region` on every retry iteration -- `Region.open`'s
/// own one-time setup section takes a real, blocking `fcntl` lock
/// (`setup_lock_offset`) that serializes against every other `openSized`
/// call on this file, existing-and-valid or not -- so three threads
/// retrying concurrently (`lite fair writer lock bounds every writer's
/// wait under sustained contention`) serialized through that setup lock
/// on *every* retry and intermittently blew the test's own 10 s per-
/// attempt deadline. Reusing the caller's own already-open `Region`
/// would fix it, but threading one through means changing this
/// function's signature (or `plainWriterLockUntil`'s) -- exactly the
/// kind of call this design's own delivery plan reserves for a real
/// decision, not a guess under this step's own "keep the constructor's
/// signature stable" instruction.
pub fn waitPathLockWithIo(allocator: Allocator, io: std.Io, path: []const u8, writer: bool, deadline_ns: i96) !PathWriterLock {
    const lock_path = try writerLockPathAlloc(allocator, io, path);
    defer allocator.free(lock_path);
    const file = try std.Io.Dir.cwd().openFile(io, lock_path, .{
        .mode = if (writer) .read_write else .read_only,
    });
    const held = try @import("path_lock_wait.zig").lockUntil(file, io, if (writer) .exclusive else .shared, deadline_ns);
    return .{ .io_impl = undefined, .borrowed_io = io, .file = held };
}

/// FIFO cross-process writer admission. Fairness order is decided by
/// `shared_lock_region`'s own ticket (§8.2). The sidecar `flock`, taken
/// after the region grants this lease its turn, is still the *actual*
/// safety authority (see `PathWriterLock.region`'s own doc comment), so
/// a lease taken through this path and one taken through the single
/// plain-flock fallback below still correctly exclude each other. When
/// nobody is queued, an uncontended writer skips the ticket entirely. An
/// expired deadline still permits that immediate acquisition. `wait_io`
/// must be able to run a concurrent kernel wait.
///
/// Falls back to the single plain-flock path (§8.6: no FIFO fairness, as
/// SQLite behaves on NFS) whenever the region itself can't be used --
/// the same set of conditions `plainWriterLockUntil` itself already
/// treats as "no region here" for its own internal wait, plus the
/// region's own "can't use it here" errors. That fallback is simply
/// calling `plainWriterLockUntil` directly, with no ticket taken at
/// all, since a lease it returns already blocks on the real sidecar
/// lock the same way a ticket-won lease's own second half does.
/// §8.4's "existing code reused, not new recovery logic" recovery
/// callback for `fairWriterLockWithIo`'s dead-writer handling: validates
/// (and, where a rejected candidate needs it, truncates) the on-disk
/// checkpoint state at `path` exactly the way a fresh writer-mode
/// `NativeFile.open` already does (`recoverActiveCheckpoint`'s own
/// doc comment), but run proactively, before `shared_lock_region.zig`
/// clears the dead holder's stale `writer_holder` word, per §8.4: "a
/// holder that died mid-commit may have left the data file in a state
/// only that recovery path already knows how to validate." Opens its
/// own fd rather than reusing any already-open `NativeFile` -- there is
/// none yet at this point in `fairWriterLockWithIo`, which hands back a
/// bare lease for the caller to open a `NativeFile` against afterward --
/// and `openDataFile`'s own `.writer` mode takes no kernel lock on the
/// data file at all (only `.reader` does), so this cannot self-conflict
/// with any lock a concurrent reader or this same process's own already-
/// open `NativeFile` might hold.
fn recoverCrashedWriterDataFile(io: std.Io, path: []const u8) !void {
    const opened = try openDataFile(io, path, .writer, true);
    const file = opened.file;
    defer file.close(io);
    var header_bytes: [header_size]u8 = undefined;
    try readHeaderExactAt(file, io, &header_bytes);
    var header = try decodeHeader(&header_bytes);
    const file_size = (try file.stat(io)).size;
    header.checkpoints = loadCheckpointSlots(file, io, header.page_size, file_size);
    _ = try recoverActiveCheckpoint(file, io, header, file_size, true);
}

const FairLockRecoveryCtx = struct { io: std.Io, path: []const u8 };

fn fairLockRecoverDeadWriter(ctx_ptr: ?*anyopaque) anyerror!void {
    const ctx: *const FairLockRecoveryCtx = @ptrCast(@alignCast(ctx_ptr.?));
    try recoverCrashedWriterDataFile(ctx.io, ctx.path);
}

pub fn fairWriterLockWithIo(allocator: Allocator, io: std.Io, wait_io: std.Io, path: []const u8, deadline_ns: i96) !PathWriterLock {
    const pid = antfly_platform.process.currentId() orelse 0;
    // A read-only or otherwise uncooperative filesystem, proven
    // corruption, or exhausted liveness slots fall back to the single
    // plain-flock path rather than surfacing a region-specific error to
    // callers that have never had to handle one. Anything else (notably
    // `OutOfMemory`) propagates instead of being swallowed into a
    // fallback that would likely fail the same way. See
    // `inode_lock.isRegionUnusable`'s own doc comment: every migrated
    // caller, writer or reader side, shares this one check.
    var region = shared_lock_region.Region.open(std.heap.page_allocator, io, path) catch |err| {
        if (inode_lock.isRegionUnusable(err)) return plainWriterLockUntil(allocator, io, wait_io, path, deadline_ns);
        return err;
    };
    errdefer region.close();
    // §8.4: a dead writer's own `writer_holder` word never clears itself
    // (it only called `releaseWriter` -- which it never reached -- or
    // relied on `recoverDeadWriter` below). Without this, every writer
    // after the dead one queues behind a holder that never releases,
    // paying out its own full `deadline_ns` budget on every single
    // attempt forever. `recovery_ctx` must outlive this call (it does:
    // both live in this function's own frame, and `acquireWriterFairBounded`
    // never retains the pointer past its own return).
    var recovery_ctx = FairLockRecoveryCtx{ .io = io, .path = path };
    const contended = region.acquireWriterFairBounded(wait_io, pid, .{ .nanoseconds = deadline_ns }, .{ .ctx = &recovery_ctx, .run = fairLockRecoverDeadWriter }) catch |err| switch (err) {
        error.Timeout => return error.FileBusy,
        error.Canceled => return error.Canceled,
        else => |e| return e,
    };
    errdefer region.releaseWriter();

    // Our turn, per the region's own ticket: take the real (still
    // authoritative) sidecar lock exactly as the pre-region
    // ticket-won path always did.
    var lease = try plainWriterLockUntil(allocator, io, wait_io, path, deadline_ns);
    // Without this, a `create` failure just below would return holding
    // the sidecar flock forever: `lease` is a local the caller never
    // sees, so only this function can close it on that path.
    errdefer lease.close();
    const owned_region = try std.heap.page_allocator.create(shared_lock_region.Region);
    owned_region.* = region;
    lease.region = owned_region;
    lease.contended = contended;
    lease.acquired_ns = std.Io.Clock.awake.now(io).nanoseconds;
    return lease;
}

/// Nonblocking writer acquisition that never jumps the FIFO: returns
/// `error.WouldBlock` while any writer is queued or holds a turn. §8.2's
/// "try" mode (`region.tryAcquireWriterFair`). Falls back to
/// `lockWriterPathWithIo` (the single plain-flock fallback's own
/// nonblocking attempt, §8.6) when the region can't be used, the same
/// `inode_lock.isRegionUnusable` check every migrated caller shares --
/// that call already jumps straight to a bare nonblocking kernel attempt
/// when it finds the region unusable too, so there is nothing further
/// for this function's own fallback to add.
pub fn tryFairWriterLockWithIo(allocator: Allocator, io: std.Io, path: []const u8) !PathWriterLock {
    const pid = antfly_platform.process.currentId() orelse 0;
    var region = shared_lock_region.Region.open(std.heap.page_allocator, io, path) catch |err| {
        if (inode_lock.isRegionUnusable(err)) return lockWriterPathWithIo(allocator, io, path);
        return err;
    };
    if (!region.tryAcquireWriterFair(pid)) {
        region.close();
        return error.WouldBlock;
    }
    errdefer region.close();
    errdefer region.releaseWriter();
    const file = (try acquireWriterLock(allocator, io, path)).file;
    errdefer file.close(io);
    const owned_region = try std.heap.page_allocator.create(shared_lock_region.Region);
    owned_region.* = region;
    return .{
        .io_impl = undefined,
        .borrowed_io = io,
        .file = file,
        .region = owned_region,
        .acquired_ns = std.Io.Clock.awake.now(io).nanoseconds,
    };
}

const PathRegionForWait = struct { entry: *inode_lock.Entry, region: *shared_lock_region.Region };

/// Gets (not opens fresh) the shared lock region for `path` through the
/// per-inode registry: `inode_lock.open`'s own `Entry` is cached per
/// inode per process, and `ensureRegion` opens the region at most once
/// per `Entry`, reusing it across every call -- unlike an earlier,
/// reverted attempt at this same migration, which called
/// `shared_lock_region.Region.open` fresh on every retry iteration and
/// serialized every concurrent retrier through that call's own one-time
/// setup lock. On success the caller owns the returned `Entry`
/// reference and must `unref` it; on error (including a
/// `inode_lock.isRegionUnusable` one) there is nothing to release.
fn pathRegionForWait(io: std.Io, path: []const u8) !PathRegionForWait {
    const entry = try inode_lock.open(io, path);
    const region = inode_lock.ensureRegion(entry, io) catch |err| {
        inode_lock.unref(entry, io);
        return err;
    };
    return .{ .entry = entry, .region = region };
}

/// The region-based wait when one is available; otherwise (region
/// unusable, or not yet applicable -- the region is genuinely optional
/// here, unlike `fairWriterLockWithIo`'s own ticket) the single plain-
/// flock fallback's own OS-lock-queue wait (`waitPathLockWithIo`), §8.6.
/// Every caller of this function -- region-backed or not -- ends up
/// here for the one, real, authoritative kernel lease.
fn plainWriterLockUntil(allocator: Allocator, io: std.Io, wait_io: std.Io, path: []const u8, deadline_ns: i96) !PathWriterLock {
    // Set up lazily, on the first retry only -- never on a warm,
    // uncontended call that wins `acquireWriterLock` below on its very
    // first attempt. An earlier version of this call set this up
    // unconditionally, up front, which added `inode_lock.open`'s own
    // `statFile` syscall to every single acquisition, uncontended or
    // not; that silently cost this design's own "0 syscalls on a warm
    // write" property and tightened enough margin on a few busy-timeout
    // tests to make them flake.
    var cached: ?PathRegionForWait = null;
    var cache_attempted = false;
    defer if (cached) |c| inode_lock.unref(c.entry, wait_io);

    var backoff_ns: i96 = 50 * std.time.ns_per_us;
    while (true) {
        if (acquireWriterLock(allocator, io, path)) |held| {
            return .{ .io_impl = undefined, .borrowed_io = io, .file = held.file };
        } else |err| if (err != error.WouldBlock and err != error.FileBusy) return err;
        if (deadline_ns - std.Io.Clock.awake.now(io).nanoseconds <= 0) return error.FileBusy;
        if (!cache_attempted) {
            cache_attempted = true;
            // `null` when the region can't be used here --
            // `inode_lock.open`'s own `statFile` on the *data* file (not
            // the sidecar `acquireWriterLock` above creates on demand)
            // can fail with `FileNotFound` on a caller's first-ever
            // acquire, before that data file exists yet, which is not
            // the "this filesystem/region can't be used at all"
            // condition `inode_lock.isRegionUnusable` means -- falls
            // back to the single plain-flock path's own OS-lock-queue
            // wait below either way. Anything else (notably
            // `OutOfMemory`) propagates instead of being swallowed into
            // a fallback that would likely fail the same way, the same
            // posture every other migrated constructor's own
            // `isRegionUnusable` check takes.
            cached = blk: {
                break :blk pathRegionForWait(wait_io, path) catch |err| {
                    if (err != error.FileNotFound and !inode_lock.isRegionUnusable(err)) return err;
                    break :blk null;
                };
            };
        }
        if (cached) |c| {
            // A real wake signal (or a short internal re-check step, not
            // a dumb poll) on the region's own futex -- loop straight
            // back to retry the real flock, no extra backoff on top of
            // it.
            c.region.waitWriterFreeBounded(wait_io, .{ .nanoseconds = deadline_ns }) catch |err| switch (err) {
                error.Canceled => return error.Canceled,
            };
            continue;
        }
        if (waitPathLockWithIo(allocator, wait_io, path, true, deadline_ns)) |held| {
            var lease = held;
            lease.borrowed_io = io;
            return lease;
        } else |err| switch (err) {
            // Sidecar not yet created, or no concurrent executor: poll.
            error.FileNotFound, error.ConcurrencyUnavailable => {},
            else => return err,
        }
        const remaining = deadline_ns - std.Io.Clock.awake.now(io).nanoseconds;
        if (remaining <= 0) return error.FileBusy;
        try io.sleep(.fromNanoseconds(@min(backoff_ns, remaining)), .awake);
        backoff_ns = @min(backoff_ns * 2, 4 * std.time.ns_per_ms);
    }
}

/// Read-only embedded calls coordinate with commits without reserving a writer.
pub fn lockReaderPathWithIo(allocator: Allocator, io: std.Io, path: []const u8) !PathWriterLock {
    const lock_path = try writerLockPathAlloc(allocator, io, path);
    defer allocator.free(lock_path);
    const file = std.Io.Dir.cwd().openFile(io, lock_path, .{
        .mode = .read_only,
        .lock = .shared,
        .lock_nonblocking = true,
    }) catch |err| switch (err) {
        error.FileNotFound => blk: {
            // A distributed snapshot may have no sidecar and live on read-only
            // media. Every sidecar creator must exclude fallback inode readers,
            // including a reader installing the sidecar after media changes.
            var exclusive_inode = true;
            const data = std.Io.Dir.cwd().openFile(io, path, .{
                .mode = .read_only,
                .lock = .exclusive,
                .lock_nonblocking = true,
            }) catch |inode_err| switch (inode_err) {
                error.WouldBlock, error.FileBusy => blk_data: {
                    exclusive_inode = false;
                    break :blk_data try std.Io.Dir.cwd().openFile(io, path, .{
                        .mode = .read_only,
                        .lock = .shared,
                        .lock_nonblocking = true,
                    });
                },
                else => return inode_err,
            };
            var keep_data = false;
            defer if (!keep_data) data.close(io);
            // A writer may have installed the sidecar before our inode fence.
            if (std.Io.Dir.cwd().openFile(io, lock_path, .{
                .mode = .read_only,
                .lock = .shared,
                .lock_nonblocking = true,
            })) |existing| break :blk existing else |open_err| {
                if (open_err != error.FileNotFound) return open_err;
            }
            if (!exclusive_inode) {
                keep_data = true;
                break :blk data;
            }
            break :blk std.Io.Dir.cwd().createFile(io, lock_path, .{
                .read = true,
                .truncate = false,
                .lock = .shared,
                .lock_nonblocking = true,
            }) catch |create_err| switch (create_err) {
                error.AccessDenied, error.ReadOnlyFileSystem => {
                    try data.lock(io, .shared);
                    keep_data = true;
                    break :blk data;
                },
                else => return create_err,
            };
        },
        else => return err,
    };
    return .{ .io_impl = undefined, .borrowed_io = io, .file = file };
}

/// `acquirePathLeaseAssumeLocked`'s reader-admission wait, migrated off the
/// kernel's blocking `.shared` lock queue (`waitPathLockWithIo(...,
/// writer=false, ...)`), the last reader path still parked there.
///
/// A reader's admission at this layer does not need exclusion from a
/// writer at all: the store is copy-on-write (a commit never mutates a
/// page an already-pinned reader can see; it lands on a fresh
/// checkpoint slot/pages instead), and every real caller of this path --
/// plain reads, status/index-list, and the `.maintain`-access snapshot
/// copy -- only ever treats the returned lease as an admission
/// throttle/reference, never as a signal that "no writer is mid-commit"
/// (confirmed by tracing every caller: none inspects writer state
/// through this lease, and the one place that genuinely needs real
/// cross-process writer exclusion, `replaceWithPreparedGeneration`'s
/// generation swap, already gets it independently through
/// `enterMaintenanceWriter`/`tryWriterLeaseAssumeLocked`'s own exclusive
/// re-acquisition, unrelated to this gate). The kernel `.shared`-vs-
/// `.exclusive` wait this replaces was a holdover from flock's own
/// semantics being the only coordination mechanism available before the
/// region existed, not a correctness requirement.
///
/// So in region mode this never waits at all: open the region (to prove
/// it's usable), and succeed immediately with no kernel lock -- `file =
/// null` on the returned lease, nothing to release on `close()`. It does
/// not claim or pin a region reader slot either: there is no commit
/// generation to protect yet at this point (the caller hasn't opened the
/// `NativeFile`, let alone read a header), so a slot held for this
/// lease's -- potentially long-lived, re-admitted-per-query -- lifetime
/// would consume one of the region's fixed 1024 slots for no protective
/// effect, risking exhaustion for genuinely pinned NativeFile-level
/// readers. The actual safety guarantee (pinning a real commit sequence)
/// is `NativeFile.acquireReaderFence`'s job, already region-backed, once
/// a real generation exists to pin. `PathWriterLock` has no field to
/// stash a claimed slot index on for later release even if one were
/// wanted here, and `.region` is writer-only (`close()` unconditionally
/// calls `releaseWriter()` on it whenever set) -- not something a reader
/// lease may ever populate.
///
/// Falls back to exactly the pre-migration two-step dance (one
/// non-blocking `lockReaderPathWithIo` try, then one real blocking
/// `waitPathLockWithIo`) entirely when the region itself can't be used
/// (`inode_lock.isRegionUnusable`), the same posture `fairWriterLockWithIo`
/// already takes for its own callers -- `lockReaderPathWithIo`'s kernel
/// `.shared` lock remains the correctness authority there, unchanged,
/// including `waitPathLockWithIo`'s own `error.FileNotFound`/
/// `error.ConcurrencyUnavailable` cases, which this propagates rather
/// than retrying itself: `acquirePathLeaseAssumeLocked`'s own outer loop
/// already retries the whole admission attempt after those, and
/// duplicating that retry here would just nest two copies of the same
/// backoff.
pub fn fairReaderLockWithIo(allocator: Allocator, io: std.Io, path: []const u8, deadline_ns: i96) !PathWriterLock {
    var region = shared_lock_region.Region.open(std.heap.page_allocator, io, path) catch |err| {
        if (inode_lock.isRegionUnusable(err)) {
            return lockReaderPathWithIo(allocator, io, path) catch |lock_err| {
                if (lock_err != error.WouldBlock and lock_err != error.FileBusy) return lock_err;
                return waitPathLockWithIo(allocator, io, path, false, deadline_ns);
            };
        }
        return err;
    };
    region.close();
    return .{ .io_impl = undefined, .borrowed_io = io, .file = null };
}

fn openDataFile(io: std.Io, path: []const u8, lock_mode: LockMode, wait_for_reader_lock: bool) !LockFile {
    const file = std.Io.Dir.cwd().openFile(io, path, .{
        .mode = if (lock_mode != .writer) .read_only else .read_write,
        .lock = if (lock_mode == .reader) .shared else .none,
        // Readers wait for a bounded in-place allocator write to finish.
        // Writers and maintenance retain nonblocking admission.
        .lock_nonblocking = lock_mode != .reader or !wait_for_reader_lock,
    }) catch |err| switch (err) {
        // Snapshot safety and maintenance fencing depend on the kernel lock.
        // Silently reopening without it turns an unsupported filesystem into
        // a data-corruption hazard, so every normal Lite open fails closed.
        error.FileLocksUnsupported => return error.FileLocksUnsupported,
        else => return err,
    };
    return .{ .file = file };
}

const CreateDataFileOptions = struct {
    truncate: bool = true,
    exclusive: bool = false,
};

fn createDataFile(io: std.Io, path: []const u8, opts: CreateDataFileOptions) !std.Io.File {
    return std.Io.Dir.cwd().createFile(io, path, .{
        .read = true,
        .truncate = opts.truncate,
        .exclusive = opts.exclusive,
    });
}

fn acquireWriterLock(allocator: Allocator, io: std.Io, path: []const u8) !LockFile {
    const lock_path = try writerLockPathAlloc(allocator, io, path);
    defer allocator.free(lock_path);
    if (std.Io.Dir.cwd().openFile(io, lock_path, .{
        .mode = .read_write,
        .lock = .exclusive,
        .lock_nonblocking = true,
    })) |existing| return .{ .file = existing } else |err| {
        if (err != error.FileNotFound) return err;
    }
    // Readers of sidecar-free snapshots hold this inode shared. Exclude them
    // before installing the sidecar so switching lock authorities cannot race
    // a reader's header/catalog capture, even if directory permissions change.
    const data = std.Io.Dir.cwd().openFile(io, path, .{
        .mode = .read_only,
        .lock = .exclusive,
        .lock_nonblocking = true,
    }) catch |err| switch (err) {
        error.FileNotFound => null,
        else => return err,
    };
    defer if (data) |held| held.close(io);
    const file = std.Io.Dir.cwd().createFile(io, lock_path, .{
        .read = true,
        .truncate = false,
        .lock = .exclusive,
        .lock_nonblocking = true,
    }) catch |err| switch (err) {
        error.FileLocksUnsupported => return error.FileLocksUnsupported,
        else => return err,
    };
    return .{ .file = file };
}

fn writerLockPathAlloc(allocator: Allocator, io: std.Io, path: []const u8) ![]u8 {
    const canonical_data_path = realPathAlloc(allocator, io, path) catch |err| switch (err) {
        error.FileNotFound => null,
        else => return err,
    };
    if (canonical_data_path) |canonical| {
        defer allocator.free(canonical);
        return appendLockSuffix(allocator, canonical);
    }

    const dirname = std.fs.path.dirname(path) orelse ".";
    const basename = std.fs.path.basename(path);
    const canonical_parent = try realPathAlloc(allocator, io, dirname);
    defer allocator.free(canonical_parent);
    const canonical_missing_path = try std.fs.path.join(allocator, &.{ canonical_parent, basename });
    defer allocator.free(canonical_missing_path);
    return appendLockSuffix(allocator, canonical_missing_path);
}

fn pathsReferToSameExistingFile(allocator: Allocator, io: std.Io, a: []const u8, b: []const u8) !bool {
    const a_real = realPathAlloc(allocator, io, a) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return false,
        else => return err,
    };
    defer allocator.free(a_real);

    const b_real = realPathAlloc(allocator, io, b) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return false,
        else => return err,
    };
    defer allocator.free(b_real);

    return std.mem.eql(u8, a_real, b_real);
}

pub fn realPathAlloc(allocator: Allocator, io: std.Io, path: []const u8) ![:0]u8 {
    if (std.fs.path.isAbsolute(path)) {
        return try std.Io.Dir.realPathFileAbsoluteAlloc(io, path, allocator);
    }
    return try std.Io.Dir.cwd().realPathFileAlloc(io, path, allocator);
}

fn appendLockSuffix(allocator: Allocator, path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(allocator, "{s}.lock", .{path});
}

fn acquireDataRewriteLock(io: std.Io, path: []const u8) !LockFile {
    const file = std.Io.Dir.cwd().openFile(io, path, .{
        .mode = .read_write,
        .lock = .exclusive,
        .lock_nonblocking = true,
    }) catch |err| switch (err) {
        error.FileLocksUnsupported => return error.FileLocksUnsupported,
        else => return err,
    };
    return .{ .file = file };
}

fn pathExists(io: std.Io, path: []const u8) bool {
    if (std.fs.path.isAbsolute(path)) {
        std.Io.Dir.accessAbsolute(io, path, .{}) catch return false;
    } else {
        std.Io.Dir.cwd().access(io, path, .{}) catch return false;
    }
    return true;
}

fn createSnapshotFile(io: std.Io, path: []const u8) !std.Io.File {
    if (std.fs.path.isAbsolute(path)) {
        return try std.Io.Dir.createFileAbsolute(io, path, .{ .read = true, .truncate = true });
    }
    return try std.Io.Dir.cwd().createFile(io, path, .{ .read = true, .truncate = true });
}

fn renameFilePath(io: std.Io, old_path: []const u8, new_path: []const u8) !void {
    if (std.fs.path.isAbsolute(old_path) and std.fs.path.isAbsolute(new_path)) {
        try std.Io.Dir.renameAbsolute(old_path, new_path, io);
    } else {
        try std.Io.Dir.rename(std.Io.Dir.cwd(), old_path, std.Io.Dir.cwd(), new_path, io);
    }
}

fn deleteFilePath(io: std.Io, path: []const u8) !void {
    if (std.fs.path.isAbsolute(path)) {
        try std.Io.Dir.deleteFileAbsolute(io, path);
    } else {
        try std.Io.Dir.cwd().deleteFile(io, path);
    }
}

/// Unlike pre-v8 (where a header-sized buffer held everything), the
/// recovery slots now live on their own pages, so inspecting a file for
/// real requires file access throughout -- there is no longer a
/// byte-buffer-only `inspectBytes`. Read-only: never truncates, even if a
/// fallback slot's page_count would call for it (that is `NativeFile.open`
/// -- the writer's job).
pub fn inspect(_: Allocator, io: std.Io, path: []const u8) !InspectReport {
    const invalid = struct {
        fn of(err: anyerror) InspectReport {
            return .{ .valid = false, .format_version = 0, .page_size = 0, .active_checkpoint = 0, .commit_sequence = 0, .page_count = 0, .issue = issueForDecodeError(err) };
        }
    }.of;

    var file = (try openDataFile(io, path, .reader, false)).file;
    defer file.close(io);

    var header_bytes: [header_size]u8 = undefined;
    try readHeaderExactAt(file, io, &header_bytes);
    var header = decodeHeader(&header_bytes) catch |err| return invalid(err);
    const file_size = (try file.stat(io)).size;
    header.checkpoints = loadCheckpointSlots(file, io, header.page_size, file_size);
    const recovered = recoverActiveCheckpoint(file, io, header, file_size, false) catch |err| return invalid(err);
    const active = header.checkpoints[recovered.index];
    return .{
        .valid = true,
        .format_version = format_version,
        .page_size = header.page_size,
        .active_checkpoint = recovered.index,
        .commit_sequence = active.commit_sequence,
        .page_count = active.page_count,
    };
}

pub fn checkFile(allocator: Allocator, path: []const u8) !CheckReport {
    var io_impl = std.Io.Threaded.init(allocator, .{});
    defer io_impl.deinit();
    const io = io_impl.io();

    const file_size = blk: {
        var file = (try openDataFile(io, path, .reader, false)).file;
        defer file.close(io);
        break :blk (try file.stat(io)).size;
    };

    // Recovering the active checkpoint (decodeHeader, loading both v8 slot
    // pages, and verifying a non-presynced winner's manifest) requires the
    // same file access `NativeFile.open` already performs; duplicating
    // that logic here just to report a slightly more specific diagnostic
    // string is not worth two independent implementations of recovery to
    // keep in sync. Every failure mode open() can hit already has a
    // specific `issueForDecodeError` mapping.
    var native_file = NativeFile.open(allocator, path, true) catch |err| {
        return invalidCheck(.{
            .valid = true,
            .file_size = file_size,
            .valid_prefix_size = 0,
            .tail_bytes = file_size,
            .record_count = 0,
            .live_file_count = 0,
            .live_bytes = 0,
            .compact_size = 0,
            .reclaimable_bytes = 0,
        }, issueForDecodeError(err));
    };
    defer native_file.close();
    return try native_file.check();
}

pub fn copyStableSnapshot(allocator: Allocator, source_path: []const u8, dest_path: []const u8, replace: bool) !StableSnapshotReport {
    if (std.mem.eql(u8, source_path, dest_path)) return error.InvalidNativeSnapshotPath;

    var source = try NativeFile.open(allocator, source_path, true);
    defer source.close();
    return try source.copyStableSnapshotToPath(dest_path, replace);
}

/// Encodes only the static page-0 fields (magic/version/page_size/
/// reader_epoch_namespace). v8 moved both recovery slots to their own
/// dedicated pages (`slotPhysicalPage`): this no longer touches them at
/// all, so a slot write never needs to also rewrite (and therefore never
/// risks tearing) the header page, and vice versa.
pub fn encodeHeader(out: *[header_size]u8, header: Header) void {
    @memset(out, 0);
    const is_redo_log = header.redo_log_capacity != 0;
    @memcpy(out[magic_offset..][0..magic.len], magic);
    std.mem.writeInt(u32, out[version_offset..][0..4], format_version, .little);
    std.mem.writeInt(u32, out[page_size_offset..][0..4], header.page_size, .little);
    std.mem.writeInt(u32, out[header_size_offset..][0..4], header_size, .little);
    if (header.indexed_reclamation) @memcpy(out[reader_epoch_namespace_offset..][0..32], &header.reader_epoch_namespace);
    // Written unconditionally (not gated on `is_redo_log`), so every
    // `Header` field always round-trips through the encoding regardless of
    // mode -- a pre-this-change file always had zero bytes here anyway
    // (the `@memset(out, 0)` above was the only writer of this range), so
    // this changes nothing for an old file and keeps a non-redo-log file's
    // two new fields meaningfully fingerprinted instead of silently
    // omitted from the encoded bytes whenever `redo_log_capacity == 0`.
    std.mem.writeInt(u64, out[redo_log_offset_offset..][0..8], header.redo_log_offset, .little);
    std.mem.writeInt(u64, out[redo_log_capacity_offset..][0..8], header.redo_log_capacity, .little);
    // §9.5/§9.7a: each mode is its own bit, set purely from this header's
    // own field -- never implied by, or overriding, another bit -- so any
    // combination (redo log plus indexed reclamation included) round-trips
    // exactly as written, unlike the old magic-selection priority chain
    // this replaces.
    var flags: u32 = 0;
    if (is_redo_log) flags |= feature_flag_redo_log;
    if (header.indexed_reclamation) flags |= feature_flag_indexed_reclamation;
    if (header.packed_records) flags |= feature_flag_packed_records;
    std.mem.writeInt(u32, out[feature_flags_offset..][0..4], flags, .little);
    std.mem.writeInt(u32, out[header_checksum_offset..][0..4], headerChecksum(out), .little);
}

/// Decodes only the static page-0 fields. `checkpoints` and
/// `active_checkpoint` come back as unverified placeholders (`page_count =
/// 0`, i.e. structurally invalid): the real recovery slots live on their
/// own pages and require file access to load and verify, which a raw
/// header buffer alone cannot provide. Callers that need a fully recovered
/// `Header` (every production caller) must follow this with
/// `recoverActiveCheckpoint`.
pub fn decodeHeader(raw: []const u8) !Header {
    if (raw.len < header_size) return error.TruncatedNativeHeader;
    const header_raw = raw[0..header_size];
    if (!std.mem.eql(u8, header_raw[magic_offset..][0..magic.len], magic)) return error.InvalidNativeMagic;

    const version = std.mem.readInt(u32, header_raw[version_offset..][0..4], .little);
    if (version != format_version) return error.UnsupportedNativeFormatVersion;

    const encoded_header_size = std.mem.readInt(u32, header_raw[header_size_offset..][0..4], .little);
    if (encoded_header_size != header_size) return error.InvalidNativeHeaderSize;

    const expected_checksum = std.mem.readInt(u32, header_raw[header_checksum_offset..][0..4], .little);
    if (expected_checksum != headerChecksum(header_raw)) return error.NativeHeaderChecksumMismatch;

    const page_size = std.mem.readInt(u32, header_raw[page_size_offset..][0..4], .little);
    if (!validPageSize(page_size)) return error.InvalidNativePageSize;

    // §9.5/§9.7a: each mode bit is read back independently -- no priority
    // chain, no bit implying or overriding another -- the direct inverse
    // of `encodeHeader`'s write above.
    const flags = std.mem.readInt(u32, header_raw[feature_flags_offset..][0..4], .little);
    const indexed_reclamation = flags & feature_flag_indexed_reclamation != 0;

    return .{
        .reader_epoch_namespace = if (indexed_reclamation) header_raw[reader_epoch_namespace_offset..][0..32].* else @splat(0),
        .packed_records = flags & feature_flag_packed_records != 0,
        .indexed_reclamation = indexed_reclamation,
        .page_size = page_size,
        .active_checkpoint = 0,
        .checkpoints = .{ .{ .page_count = 0 }, .{ .page_count = 0 } },
        .redo_log_offset = std.mem.readInt(u64, header_raw[redo_log_offset_offset..][0..8], .little),
        .redo_log_capacity = std.mem.readInt(u64, header_raw[redo_log_capacity_offset..][0..8], .little),
    };
}

const manifest_entry_size: usize = 12; // u64 page_id + u32 crc
pub const max_page_size: usize = 65536;

const ManifestEntry = struct { page_id: u64, crc: u32 };

/// Accumulates every page written since the last durable checkpoint (see
/// `NativeFile.manifest_builder`'s doc comment), keyed by page id so a page
/// rewritten more than once keeps only its final CRC (the only one that
/// will still be on disk when recovery checks it). `overflowed` latches
/// permanently once tracking fails or the window exceeds
/// `max_single_sync_pages`: a window that cannot build a trustworthy
/// manifest falls back to the presynced two-sync path instead of risking
/// an under- or over-complete one.
const ManifestBuilder = struct {
    entries: std.AutoHashMapUnmanaged(u64, u32) = .empty,
    /// Page ids in `entries` that came from the allocator's free-page reuse
    /// rather than a fresh `next_page_id` bump, merged in from each
    /// `PageAllocator.reused` as the window's commits flush. `entries` minus
    /// this set is expected to be exactly one contiguous run (every id the
    /// allocator hands out fresh only ever increases), which lets the
    /// encoded manifest name that whole run with one range and a flat CRC
    /// array instead of a (page_id, crc) pair per page.
    reused_pages: std.AutoHashMapUnmanaged(u64, void) = .empty,
    overflowed: bool = false,
    /// A page id `flushTransactionWrites` reserves through the transaction's
    /// own `PageAllocator` before `persistAllocator` finalizes
    /// `checkpoint.page_count`, so the eventual manifest page is counted by
    /// the free-map/ledger's own bookkeeping exactly like every other page
    /// this commit wrote. `page_count` is never retroactively bumped after
    /// that bookkeeping already settled -- `decodeFreeMapAlloc` and the
    /// allocator ledger both cross-check their own covered-page count
    /// against it.
    reserved_page: ?u64 = null,

    /// Frees `entries`/`reused_pages` for good -- only at a true end of
    /// this struct's lifetime (`NativeFile.close`, or a short-lived helper
    /// file's own one-shot cleanup), never between commits. See
    /// `resetForNextWindow` for the between-commits case: this struct is a
    /// long-lived field of `NativeFile`, and the whole point of
    /// `reserveCapacity`'s pre-size (below) is that steady-state commits
    /// never reach this allocator at all.
    fn deinit(self: *ManifestBuilder, allocator: Allocator) void {
        self.entries.deinit(allocator);
        self.reused_pages.deinit(allocator);
    }

    /// Between-commits reset: drop every entry but keep the underlying
    /// capacity `reserveCapacity` already paid for, so the *next* window's
    /// `note`/`noteReused` calls allocate nothing either -- exactly the
    /// same guarantee `deinit` followed by reconstruction used to defeat
    /// every single commit. Called instead of `deinit` at every window
    /// boundary (commit or abort) for `NativeFile`'s own long-lived
    /// `manifest_builder`; `deinit` remains for the struct's true end of
    /// life.
    fn resetForNextWindow(self: *ManifestBuilder) void {
        self.entries.clearRetainingCapacity();
        self.reused_pages.clearRetainingCapacity();
        self.overflowed = false;
        self.reserved_page = null;
    }

    /// Pre-size `entries`/`reused_pages` to cover the largest window this
    /// struct ever needs to track (`max_single_sync_pages` noted pages,
    /// +1 so `note`'s own overflow check below always has room to make
    /// its one over-budget `putAssumeCapacity` before it fires) -- once,
    /// ever, idempotently, through `allocator` (`NativeFile`'s own
    /// long-lived allocator, not a fresh one scoped to this call). Called
    /// before every window's first `note`/`noteReused`, same as the
    /// incremental reservation this replaced, but `ensureTotalCapacity`
    /// against a fixed ceiling is a guaranteed no-op once that ceiling is
    /// reached -- unlike the old `ensureUnusedCapacity(allocator,
    /// additional)` against the *current, shrunk-by-reset* count, which
    /// re-allocated on every single commit even though the previous
    /// commit had already paid for the exact same capacity and
    /// `resetForNextWindow` only dropped entries, not that capacity's
    /// backing memory.
    ///
    /// This used to also be the one place an ordinary "this window simply
    /// overflowed its size budget" (handled by `note`'s own count check)
    /// could be confused with a genuine allocation failure -- `catch {
    /// self.overflowed = true; }` relabeled a real `error.OutOfMemory` as
    /// that benign case, which `std.testing.checkAllAllocationFailures`
    /// flagged as `SwallowedOutOfMemoryError`. Fixed by construction, not
    /// by catching: once capacity is reached once, this is a no-op for
    /// every later window, so by the time any file sees enough commits for
    /// `checkAllAllocationFailures`-style exhaustive fault injection to
    /// matter, the single real allocation this ever does has already
    /// either succeeded or (this file's very first window) legitimately
    /// propagated `error.OutOfMemory` -- there is no longer a *repeated*
    /// event for the sweep to ever catch mid-steady-state.
    fn reserveCapacity(self: *ManifestBuilder, allocator: Allocator) !void {
        try self.entries.ensureTotalCapacity(allocator, max_single_sync_pages + 1);
        // If `reused_pages` fails to grow, `entries`' just-grown buffer
        // above must not leak: nothing else owns it yet (a caller whose
        // own construction fails partway, e.g. `createWithRuntime`, never
        // reaches a `deinit`/`resetForNextWindow` call for this value).
        errdefer self.entries.clearAndFree(allocator);
        try self.reused_pages.ensureTotalCapacity(allocator, max_single_sync_pages + 1);
    }

    fn note(self: *ManifestBuilder, page_id: u64, crc: u32) void {
        if (self.overflowed) return;
        // Capacity for this entry was already reserved by `reserveCapacity`
        // before the page write it describes: see that function's doc
        // comment for why `note` itself must never allocate.
        self.entries.putAssumeCapacity(page_id, crc);
        if (self.entries.count() > max_single_sync_pages) self.overflowed = true;
    }

    /// Merges one `PageAllocator`'s own reuse set into the window-wide one.
    /// Called once per `flushTransactionWrites` (every commit or
    /// intermediate flush in the window uses its own fresh `PageAllocator`,
    /// each with its own `reused` set) so the final `reused_pages` covers
    /// the whole since-last-durable-checkpoint window, not just the last
    /// flush. Capacity for the whole merge was already reserved up front
    /// by `reserveCapacity`, so this never allocates either.
    fn noteReused(self: *ManifestBuilder, reused: *const std.AutoHashMapUnmanaged(u64, void)) void {
        if (self.overflowed) return;
        if (self.reused_pages.count() + reused.count() > max_single_sync_pages) {
            self.overflowed = true;
            return;
        }
        var it = reused.keyIterator();
        while (it.next()) |page| self.reused_pages.putAssumeCapacity(page.*, {});
    }
};

/// Fixed header before the run table and the reused (page_id, crc) pairs:
/// run_count (u32), reused_count (u32). v9 (design doc §3.2a "Manifest
/// coverage"): a single since-last-durable-checkpoint window commonly spans
/// more than one contiguous appended range -- several `commit_participant`s
/// each triggering their own intermediate `flushTransactionWrites`/
/// `persistAllocator` cycle (each with its own free-map/ledger pages), or
/// several ride-along transactions sharing the window -- so the payload
/// names zero or more runs instead of exactly one.
const manifest_header_size: usize = 8;

/// Fixed header per run, immediately followed by that run's own flat CRC
/// array: range_start (u64), count (u32).
const manifest_run_header_size: usize = 12;

/// A fresh page id the allocator hands out only ever increases
/// (`PageAllocator.allocate`'s non-reuse branch), so every entry this
/// window noted that is not a reuse (see `ManifestBuilder.reused_pages`)
/// forms one or more contiguous runs, with exactly one gap total (not one
/// per run) at `manifest_page_id` -- reserved from that very same sequence
/// before `flushTransactionWrites` calls `persistAllocator` (whose own
/// ledger/metadata pages continue the sequence past it), but never an
/// entry since nothing writes to it until this function runs. Falling
/// inside a run bridges it exactly like the v8 single-run encoding did;
/// falling between two runs (or before the first/after the last) needs no
/// special handling at all. `manifest_page_id` is never re-stored in the
/// payload: it is already `slot.manifest_page` on the decode side, so
/// `verifyManifest` reconstructs the same gap from that alone. Naming a run
/// with a start id, a count, and a flat CRC array costs 4 bytes per page
/// instead of 12 (what a reused page -- explicit, from the free list,
/// never assumed contiguous with anything -- still costs, as a full
/// (page_id, crc) pair), so a window with few, long runs stays cheap; the
/// degenerate case (every appended page its own one-entry run) costs the
/// same 16 bytes/page as encoding every page as if it were reused, still
/// bounded by `max_single_sync_pages` and caught by the caller's own
/// payload-too-big-for-one-page check, so this never needs to fail for
/// discontiguity the way the v8 encoder did.
fn encodeManifestPayloadAlloc(allocator: Allocator, entries: []const ManifestEntry, reused_pages: *const std.AutoHashMapUnmanaged(u64, void), manifest_page_id: u64) ![]u8 {
    var appended = try std.ArrayListUnmanaged(ManifestEntry).initCapacity(allocator, entries.len);
    defer appended.deinit(allocator);
    var reused_count: usize = 0;
    for (entries) |entry| {
        if (reused_pages.contains(entry.page_id)) {
            reused_count += 1;
        } else {
            appended.appendAssumeCapacity(entry);
        }
    }
    std.mem.sort(ManifestEntry, appended.items, {}, manifestEntryLessThan);

    // Greedily merge adjacent (or gap-bridged) appended ids into the fewest
    // runs: this both minimizes payload size and is the only pass needed,
    // since every page id is visited exactly once in sorted order.
    var runs = std.ArrayListUnmanaged(struct { range_start: u64, crcs: std.ArrayListUnmanaged(u32) }).empty;
    defer {
        for (runs.items) |*run| run.crcs.deinit(allocator);
        runs.deinit(allocator);
    }
    var i: usize = 0;
    while (i < appended.items.len) {
        var crcs = std.ArrayListUnmanaged(u32).empty;
        try crcs.append(allocator, appended.items[i].crc);
        const range_start = appended.items[i].page_id;
        var last_id = range_start;
        var j = i + 1;
        while (j < appended.items.len) {
            const next_id = appended.items[j].page_id;
            const bridges_gap = next_id == last_id + 2 and last_id + 1 == manifest_page_id;
            if (next_id != last_id + 1 and !bridges_gap) break;
            try crcs.append(allocator, appended.items[j].crc);
            last_id = next_id;
            j += 1;
        }
        try runs.append(allocator, .{ .range_start = range_start, .crcs = crcs });
        i = j;
    }

    var payload_len: usize = manifest_header_size;
    for (runs.items) |run| payload_len += manifest_run_header_size + run.crcs.items.len * 4;
    payload_len += reused_count * manifest_entry_size;

    const out = try allocator.alloc(u8, payload_len);
    errdefer allocator.free(out);
    std.mem.writeInt(u32, out[0..4], @intCast(runs.items.len), .little);
    std.mem.writeInt(u32, out[4..8], @intCast(reused_count), .little);
    var offset: usize = manifest_header_size;
    for (runs.items) |run| {
        std.mem.writeInt(u64, out[offset..][0..8], run.range_start, .little);
        std.mem.writeInt(u32, out[offset + 8 ..][0..4], @intCast(run.crcs.items.len), .little);
        offset += manifest_run_header_size;
        for (run.crcs.items) |crc| {
            std.mem.writeInt(u32, out[offset..][0..4], crc, .little);
            offset += 4;
        }
    }
    for (entries) |entry| {
        if (!reused_pages.contains(entry.page_id)) continue;
        std.mem.writeInt(u64, out[offset..][0..8], entry.page_id, .little);
        std.mem.writeInt(u32, out[offset + 8 ..][0..4], entry.crc, .little);
        offset += manifest_entry_size;
    }
    std.debug.assert(offset == out.len);
    return out;
}

fn manifestEntryLessThan(_: void, lhs: ManifestEntry, rhs: ManifestEntry) bool {
    return lhs.page_id < rhs.page_id;
}

/// `out` must be exactly one physical page (`header.page_size` bytes): the
/// whole page is zeroed first (as `encodePageParts` does), so a slot
/// written at a smaller size would leave stale bytes in the tail.
/// perf/lwa-fold-boundary: 136 + 8 bytes for `redo_folded_through` (format
/// v11; see `format_version`'s own doc comment).
const checkpoint_slot_payload_size: usize = 144;

/// Deterministic field-by-field encoding (explicit zero-fill, no struct
/// padding) so the same logical `CheckpointSlot` always produces identical
/// bytes -- both for the on-disk slot page and for `fingerprintHeader`,
/// which hashes this payload to stay sensitive to the active checkpoint's
/// content now that `encodeHeader` no longer carries it.
fn encodeCheckpointSlotPayload(out: *[checkpoint_slot_payload_size]u8, slot: CheckpointSlot) void {
    @memset(out, 0);
    std.mem.writeInt(u64, out[0..8], slot.commit_sequence, .little);
    std.mem.writeInt(u64, out[8..16], slot.catalog_root_page, .little);
    std.mem.writeInt(u64, out[16..24], slot.document_root_page, .little);
    std.mem.writeInt(u64, out[24..32], slot.index_catalog_root_page, .little);
    std.mem.writeInt(u64, out[32..40], slot.free_map_root_page, .little);
    std.mem.writeInt(u64, out[40..48], slot.page_count, .little);
    std.mem.writeInt(u64, out[48..56], slot.namespace_directory_root_page, .little);
    std.mem.writeInt(u64, out[56..64], slot.document_index_root_page, .little);
    @memcpy(out[64..80], &slot.logical.primary);
    @memcpy(out[80..96], &slot.logical.metadata);
    @memcpy(out[96..112], &slot.logical.indexes);
    std.mem.writeInt(u64, out[112..120], slot.manifest_page, .little);
    std.mem.writeInt(u32, out[120..124], slot.manifest_crc, .little);
    std.mem.writeInt(u32, out[124..128], slot.manifest_page_count, .little);
    out[128] = @intFromBool(slot.presynced);
    std.mem.writeInt(u64, out[136..144], slot.redo_folded_through, .little);
}

fn encodeCheckpointSlotPage(out: []u8, slot: CheckpointSlot) void {
    var payload: [checkpoint_slot_payload_size]u8 = undefined;
    encodeCheckpointSlotPayload(&payload, slot);
    encodePage(out, .checkpoint_slot, &payload);
}

fn decodeCheckpointSlotPage(raw: []const u8) !CheckpointSlot {
    const payload = try decodePagePayload(raw, .checkpoint_slot);
    if (payload.len != checkpoint_slot_payload_size) return error.InvalidNativeCheckpoint;
    return .{
        .commit_sequence = std.mem.readInt(u64, payload[0..8], .little),
        .catalog_root_page = std.mem.readInt(u64, payload[8..16], .little),
        .document_root_page = std.mem.readInt(u64, payload[16..24], .little),
        .index_catalog_root_page = std.mem.readInt(u64, payload[24..32], .little),
        .free_map_root_page = std.mem.readInt(u64, payload[32..40], .little),
        .page_count = std.mem.readInt(u64, payload[40..48], .little),
        .namespace_directory_root_page = std.mem.readInt(u64, payload[48..56], .little),
        .document_index_root_page = std.mem.readInt(u64, payload[56..64], .little),
        .logical = .{
            .primary = payload[64..80].*,
            .metadata = payload[80..96].*,
            .indexes = payload[96..112].*,
        },
        .manifest_page = std.mem.readInt(u64, payload[112..120], .little),
        .manifest_crc = std.mem.readInt(u32, payload[120..124], .little),
        .manifest_page_count = std.mem.readInt(u32, payload[124..128], .little),
        .presynced = payload[128] != 0,
        .redo_folded_through = std.mem.readInt(u64, payload[136..144], .little),
    };
}

/// Shared by `NativeFile.writeSlotPage` and anything that builds a whole new
/// generation directly on a `std.Io.File` it does not yet own as `self.file`
/// (vacuum's compacted image, the create-time bootstrap).
fn writeSlotPageTo(file: std.Io.File, io: std.Io, page_size: u32, index: u8, slot: CheckpointSlot) !void {
    var buf: [max_page_size]u8 = undefined;
    const page = buf[0..page_size];
    encodeCheckpointSlotPage(page, slot);
    try file.writePositionalAll(io, page, slotPhysicalPage(index) * @as(u64, page_size));
}

/// Reads and decodes the slot page at `slotPhysicalPage(index)`. An absent,
/// truncated, torn (bad page CRC), or wrong-kind page all come back as the
/// same structurally invalid placeholder (`page_count = 0`): v8's slots
/// carry no separate checksum of their own the way the old embedded slots
/// did, because `decodePagePayload`'s own CRC already covers the whole
/// page, including every field the old per-slot checksum covered.
fn loadCheckpointSlot(file: std.Io.File, io: std.Io, page_size: u32, file_size: u64, index: u8) CheckpointSlot {
    const offset = slotPhysicalPage(index) * @as(u64, page_size);
    if (offset + page_size > file_size) return .{ .page_count = 0 };
    var buf: [max_page_size]u8 = undefined;
    const read = file.readPositionalAll(io, buf[0..page_size], offset) catch return .{ .page_count = 0 };
    if (read != page_size) return .{ .page_count = 0 };
    return decodeCheckpointSlotPage(buf[0..page_size]) catch .{ .page_count = 0 };
}

fn loadCheckpointSlots(file: std.Io.File, io: std.Io, page_size: u32, file_size: u64) [checkpoint_slot_count]CheckpointSlot {
    var slots: [checkpoint_slot_count]CheckpointSlot = undefined;
    for (&slots, 0..) |*slot, index| slot.* = loadCheckpointSlot(file, io, page_size, file_size, @intCast(index));
    return slots;
}

fn validCheckpointSlot(slot: CheckpointSlot) bool {
    if (slot.page_count < reserved_header_pages) return false;
    if (!validCheckpointRoot(slot.catalog_root_page, slot.page_count)) return false;
    if (!validCheckpointRoot(slot.document_root_page, slot.page_count)) return false;
    if (!validCheckpointRoot(slot.index_catalog_root_page, slot.page_count)) return false;
    if (!validCheckpointRoot(slot.free_map_root_page, slot.page_count)) return false;
    if (!validCheckpointRoot(slot.namespace_directory_root_page, slot.page_count)) return false;
    if (!validCheckpointRoot(slot.document_index_root_page, slot.page_count)) return false;
    if (!slot.presynced and !validCheckpointRoot(slot.manifest_page, slot.page_count)) return false;
    return true;
}

fn checkpointPrefixSize(slot: CheckpointSlot, page_size: u32) !u64 {
    return std.math.mul(u64, slot.page_count, @as(u64, page_size)) catch error.InvalidNativeCheckpoint;
}

/// A root page of 0 means "none"; otherwise it must name an ordinary,
/// already-allocatable data page -- never page 0 (the header) or either
/// slot page, which `reserved_header_pages` excludes by construction.
fn validCheckpointRoot(root_page: u64, page_count: u64) bool {
    return root_page == 0 or (physicalPage(root_page) >= reserved_header_pages and physicalPage(root_page) < page_count);
}

/// Confirms every page a non-presynced slot's manifest lists still has
/// exactly the CRC recorded when the commit wrote it. A presynced slot (a
/// large commit, or the bootstrap slot) needs no manifest and is trusted
/// unconditionally, exactly as every slot was before v8. Any I/O failure or
/// structural mismatch (bad manifest page CRC, wrong recorded manifest
/// CRC, wrong entry count, an out-of-range listed page, or a listed page
/// whose current on-disk CRC does not match) reports false, never an
/// error: a manifest failure is an ordinary recovery outcome (fall back to
/// the other slot), not a caller-visible fault.
fn verifyManifest(file: std.Io.File, io: std.Io, slot: CheckpointSlot, page_size: u32) bool {
    if (slot.presynced) return true;
    if (slot.manifest_page == 0 or slot.manifest_page_count == 0) return false;
    var buf: [max_page_size]u8 = undefined;
    const read = file.readPositionalAll(io, buf[0..page_size], slot.manifest_page * @as(u64, page_size)) catch return false;
    if (read != page_size) return false;
    const payload = decodePagePayload(buf[0..page_size], .commit_manifest) catch return false;
    if (computePageCrc(.commit_manifest, payload) != slot.manifest_crc) return false;
    if (payload.len < manifest_header_size) return false;
    const run_count = std.mem.readInt(u32, payload[0..4], .little);
    const reused_count = std.mem.readInt(u32, payload[4..8], .little);
    var offset: usize = manifest_header_size;
    var total_appended: u64 = 0;
    for (0..run_count) |_| {
        if (offset + manifest_run_header_size > payload.len) return false;
        const range_start = std.mem.readInt(u64, payload[offset..][0..8], .little);
        const count = std.mem.readInt(u32, payload[offset + 8 ..][0..4], .little);
        offset += manifest_run_header_size;
        if (offset + @as(usize, count) * 4 > payload.len) return false;
        // Walks the same implicit gap encodeManifestPayloadAlloc skipped: a
        // candidate id equal to this slot's own manifest page is never an
        // entry (nothing writes to it until the manifest page itself is
        // built), so it is passed over without consuming one of this run's
        // own CRC array slots -- reconstructed purely from
        // slot.manifest_page, never stored in the payload itself. At most
        // one run ever actually bridges the gap; every other run's walk
        // below never matches it, so this check is a no-op there.
        var i: u32 = 0;
        var page_id = range_start;
        while (i < count) : (i += 1) {
            if (page_id == slot.manifest_page) page_id += 1;
            const expected_crc = std.mem.readInt(u32, payload[offset..][0..4], .little);
            offset += 4;
            if (page_id < reserved_header_pages or page_id >= slot.page_count) return false;
            var crc_buf: [4]u8 = undefined;
            const got = file.readPositionalAll(io, &crc_buf, page_id * @as(u64, page_size) + page_crc_offset) catch return false;
            if (got != 4) return false;
            if (std.mem.readInt(u32, &crc_buf, .little) != expected_crc) return false;
            page_id += 1;
        }
        total_appended += count;
    }
    for (0..reused_count) |_| {
        if (offset + manifest_entry_size > payload.len) return false;
        const reused_page_id = std.mem.readInt(u64, payload[offset..][0..8], .little);
        const expected_crc = std.mem.readInt(u32, payload[offset + 8 ..][0..4], .little);
        offset += manifest_entry_size;
        if (reused_page_id < reserved_header_pages or reused_page_id >= slot.page_count) return false;
        var crc_buf: [4]u8 = undefined;
        const got = file.readPositionalAll(io, &crc_buf, reused_page_id * @as(u64, page_size) + page_crc_offset) catch return false;
        if (got != 4) return false;
        if (std.mem.readInt(u32, &crc_buf, .little) != expected_crc) return false;
    }
    if (offset != payload.len) return false;
    const total = total_appended + reused_count;
    if (total != slot.manifest_page_count) return false;
    return true;
}

pub const RecoveredCheckpoint = struct {
    index: u8,
    /// Set when recovery fell back from a better-looking slot whose
    /// manifest failed verification, and the caller allowed truncation
    /// (the file's actual length no longer matches the slot that was
    /// rejected). The file has already been truncated to this length.
    truncated_to: ?u64 = null,
};

/// The v8 recovery algorithm (design doc §3.1 "Recovery"): among the
/// structurally valid, size-fitting slots in `header.checkpoints`, try the
/// highest `commit_sequence` first; if it is not presynced, verify its
/// manifest. On failure, fall back to the next candidate (lower
/// commit_sequence) and, if `allow_truncate`, truncate the file to that
/// candidate's `page_count` -- any bytes written by the rejected commit
/// become unreachable tail bytes, matching what `check()` already accepts
/// for a crash mid-growth. Read-only callers get the fallback slot without
/// truncating the physical file (only the writer may do that).
fn recoverActiveCheckpoint(
    file: std.Io.File,
    io: std.Io,
    header: Header,
    file_size: u64,
    allow_truncate: bool,
) !RecoveredCheckpoint {
    var order: [checkpoint_slot_count]u8 = undefined;
    var candidates: usize = 0;
    for (0..checkpoint_slot_count) |_| {
        var best: ?u8 = null;
        for (header.checkpoints, 0..) |slot, raw_index| {
            const index: u8 = @intCast(raw_index);
            if (std.mem.indexOfScalar(u8, order[0..candidates], index) != null) continue;
            if (!validCheckpointSlot(slot)) continue;
            const expected_size = checkpointPrefixSize(slot, header.page_size) catch continue;
            if (expected_size > file_size) continue;
            if (best == null or slot.commit_sequence > header.checkpoints[best.?].commit_sequence) best = index;
        }
        const chosen = best orelse break;
        order[candidates] = chosen;
        candidates += 1;
    }
    if (candidates == 0) return error.InvalidNativeCheckpoint;
    if (recovery_debug_log) for (order[0..candidates], 0..) |index, rank| {
        const slot = header.checkpoints[index];
        recoveryDebugLog("candidate rank={d} slot_index={d} commit_sequence={d} presynced={} manifest_page={d} manifest_page_count={d}", .{ rank, index, slot.commit_sequence, slot.presynced, slot.manifest_page, slot.manifest_page_count });
    };
    for (order[0..candidates], 0..) |index, rank| {
        const slot = header.checkpoints[index];
        const verified = verifyManifest(file, io, slot, header.page_size);
        recoveryDebugLog("verify slot_index={d} commit_sequence={d} verified={}", .{ index, slot.commit_sequence, verified });
        if (!verified) continue;
        if (rank == 0) {
            recoveryDebugLog("chosen slot_index={d} commit_sequence={d} (top candidate, no fallback)", .{ index, slot.commit_sequence });
            return .{ .index = index };
        }
        if (!allow_truncate) {
            recoveryDebugLog("chosen slot_index={d} commit_sequence={d} (fallback rank={d}, read-only, no truncate)", .{ index, slot.commit_sequence, rank });
            return .{ .index = index };
        }
        const truncated_size = try checkpointPrefixSize(slot, header.page_size);
        recoveryDebugLog("chosen slot_index={d} commit_sequence={d} (fallback rank={d}, truncating to {d} bytes)", .{ index, slot.commit_sequence, rank, truncated_size });
        try file.setLength(io, truncated_size);
        return .{ .index = index, .truncated_to = truncated_size };
    }
    return error.InvalidNativeCheckpoint;
}

fn encodePage(out: []u8, kind: PageKind, payload: []const u8) void {
    encodePageParts(out, kind, &.{}, payload);
}

fn encodePageParts(out: []u8, kind: PageKind, prefix: []const u8, payload: []const u8) void {
    const len = prefix.len + payload.len;
    std.debug.assert(out.len >= page_header_size);
    std.debug.assert(len <= out.len - page_header_size);
    @memset(out, 0);
    @memcpy(out[0..page_magic.len], page_magic);
    out[4] = @backingInt(kind);
    std.mem.writeInt(u32, out[8..12], @intCast(len), .little);
    @memcpy(out[page_header_size..][0..prefix.len], prefix);
    @memcpy(out[page_header_size + prefix.len ..][0..payload.len], payload);

    var crc = Crc32.init();
    crc.update(out[0..page_crc_offset]);
    crc.update(out[page_header_size..][0..len]);
    std.mem.writeInt(u32, out[page_crc_offset..][0..4], crc.final(), .little);
}

const PackedRecord = struct { kind: PageKind, bytes: []const u8 };

fn packedRecordAtOffset(payload: []const u8, offset: usize) !PackedRecord {
    if (offset > payload.len or payload.len - offset < 4) return error.InvalidNativePageLength;
    const len = std.mem.readInt(u16, payload[offset..][0..2], .little);
    if (len > payload.len - offset - 4 or payload[offset + 3] != 0) return error.InvalidNativePageLength;
    const kind: PageKind = switch (payload[offset + 2]) {
        @backingInt(PageKind.catalog) => .catalog,
        @backingInt(PageKind.document) => .document,
        else => return error.InvalidNativePageKind,
    };
    return .{ .kind = kind, .bytes = payload[offset + 4 ..][0..len] };
}

fn packedRecordPayload(payload: []const u8, reference: u64) !PackedRecord {
    const wanted: usize = @intCast((reference >> 47) & 0xffff);
    var offset: usize = 0;
    while (offset < payload.len) {
        const record = try packedRecordAtOffset(payload, offset);
        if (offset == wanted) return record;
        offset += 4 + record.bytes.len;
    }
    return error.InvalidPageId;
}

fn unpackRecordPage(raw: []u8, reference: u64) !void {
    const record = try packedRecordPayload(try decodePagePayload(raw, .record_bundle), reference);
    var scratch: [65536]u8 = undefined;
    @memcpy(scratch[0..record.bytes.len], record.bytes);
    encodePage(raw, record.kind, scratch[0..record.bytes.len]);
}

fn decodePagePayloadAlloc(allocator: Allocator, raw: []const u8, expected_kind: PageKind) ![]u8 {
    return try allocator.dupe(u8, try decodePagePayload(raw, expected_kind));
}

fn decodePagePayload(raw: []const u8, expected_kind: PageKind) ![]const u8 {
    if (raw.len < page_header_size) return error.TruncatedNativePage;
    if (!std.mem.eql(u8, raw[0..page_magic.len], page_magic)) return error.InvalidNativePageMagic;
    const kind_raw = raw[4];
    const kind: PageKind = switch (kind_raw) {
        @backingInt(PageKind.data) => .data,
        @backingInt(PageKind.catalog) => .catalog,
        @backingInt(PageKind.document) => .document,
        @backingInt(PageKind.value) => .value,
        @backingInt(PageKind.free_map) => .free_map,
        @backingInt(PageKind.document_index) => .document_index,
        @backingInt(PageKind.value_extent) => .value_extent,
        @backingInt(PageKind.catalog_index) => .catalog_index,
        @backingInt(PageKind.record_bundle) => .record_bundle,
        @backingInt(PageKind.allocator) => .allocator,
        @backingInt(PageKind.key) => .key,
        @backingInt(PageKind.checkpoint_slot) => .checkpoint_slot,
        @backingInt(PageKind.commit_manifest) => .commit_manifest,
        else => return error.InvalidNativePageKind,
    };
    if (kind != expected_kind) {
        return error.UnexpectedNativePageKind;
    }

    const payload_len = std.mem.readInt(u32, raw[8..12], .little);
    if (payload_len > raw.len - page_header_size) return error.InvalidNativePageLength;

    if (builtin.is_test) {
        _ = PageDecodeMetrics.crc_calls.fetchAdd(1, .monotonic);
        _ = PageDecodeMetrics.crc_bytes.fetchAdd(page_crc_offset + payload_len, .monotonic);
    }
    var crc = Crc32.init();
    crc.update(raw[0..page_crc_offset]);
    crc.update(raw[page_header_size..][0..payload_len]);
    const expected_crc = std.mem.readInt(u32, raw[page_crc_offset..][0..4], .little);
    if (crc.final() != expected_crc) return error.NativePageChecksumMismatch;

    return raw[page_header_size..][0..payload_len];
}

/// Mirrors `encodePageParts`'s CRC computation without needing a page-sized
/// buffer: used to stamp a slot's `manifest_crc` right after the manifest
/// page's content is known, before the physical write happens.
fn computePageCrc(kind: PageKind, payload: []const u8) u32 {
    var prefix: [page_crc_offset]u8 = @splat(0);
    @memcpy(prefix[0..page_magic.len], page_magic);
    prefix[4] = @backingInt(kind);
    std.mem.writeInt(u32, prefix[8..12], @intCast(payload.len), .little);
    var crc = Crc32.init();
    crc.update(&prefix);
    crc.update(payload);
    return crc.final();
}

fn encodeCatalogEntry(allocator: Allocator, out: *std.ArrayListUnmanaged(u8), entry: CatalogEntry) !void {
    try encodeCatalogEntryRaw(allocator, out, .{
        .previous_page = entry.previous_page,
        .key = entry.key,
        .value = entry.value,
        .is_delete = entry.is_delete,
        .external_value_root_page = entry.external_value_root_page,
        .external_value_len = if (entry.external_value_root_page != 0 and entry.external_value_len == 0) entry.value.len else entry.external_value_len,
    });
}

fn encodeCatalogEntryRaw(allocator: Allocator, out: *std.ArrayListUnmanaged(u8), entry: EncodedCatalogEntry) !void {
    const value_len = if (entry.external_value_root_page != 0) entry.external_value_len else entry.value.len;
    if (entry.key.len > catalog_key_len_mask or value_len > std.math.maxInt(u32)) return error.RecordTooLarge;
    if (entry.is_delete and entry.external_value_root_page != 0) return error.InvalidNativeCatalogEntryFlags;
    const external_value = entry.external_value_root_page != 0;
    if (external_value and entry.external_value_len == 0) return error.InvalidNativeValueChain;

    const start = out.items.len;
    const stored_value_len: usize = if (external_value) 8 else value_len;
    try out.resize(allocator, start + 16 + entry.key.len + stored_value_len);
    const encoded = out.items[start..];
    std.mem.writeInt(u64, encoded[0..8], entry.previous_page, .little);
    const key_len_flags: u32 =
        @as(u32, @intCast(entry.key.len)) |
        (if (entry.is_delete) catalog_delete_flag else 0) |
        (if (external_value) catalog_external_value_flag else 0);
    std.mem.writeInt(u32, encoded[8..12], key_len_flags, .little);
    std.mem.writeInt(u32, encoded[12..16], @intCast(value_len), .little);
    @memcpy(encoded[16..][0..entry.key.len], entry.key);
    if (external_value) {
        std.mem.writeInt(u64, encoded[16 + entry.key.len ..][0..8], entry.external_value_root_page, .little);
    } else {
        @memcpy(encoded[16 + entry.key.len ..][0..entry.value.len], entry.value);
    }
}

fn decodeCatalogEntry(raw: []const u8) !CatalogEntry {
    if (raw.len < 16) return error.TruncatedNativeCatalogEntry;
    const previous_page = std.mem.readInt(u64, raw[0..8], .little);
    const key_len_flags = std.mem.readInt(u32, raw[8..12], .little);
    const flags = key_len_flags & ~catalog_key_len_mask;
    if (flags & ~(catalog_delete_flag | catalog_external_value_flag) != 0) return error.InvalidNativeCatalogEntryFlags;
    const is_delete = flags & catalog_delete_flag != 0;
    const external_value = flags & catalog_external_value_flag != 0;
    if (is_delete and external_value) return error.InvalidNativeCatalogEntryFlags;

    const key_len = key_len_flags & catalog_key_len_mask;
    const value_len = std.mem.readInt(u32, raw[12..16], .little);
    const stored_value_len: u64 = if (external_value) 8 else value_len;
    const payload_len = @as(u64, key_len) + stored_value_len;
    if (payload_len > raw.len - 16) return error.TruncatedNativeCatalogEntry;
    const key_start: usize = 16;
    const key_end = key_start + @as(usize, @intCast(key_len));
    const stored_value_end = key_end + @as(usize, @intCast(stored_value_len));
    const external_value_root_page = if (external_value) blk: {
        if (value_len == 0) return error.InvalidNativeValueChain;
        const root = std.mem.readInt(u64, raw[key_end..][0..8], .little);
        if (root == 0) return error.InvalidNativeValueChain;
        break :blk root;
    } else 0;
    return .{
        .previous_page = previous_page,
        .key = raw[key_start..key_end],
        .value = if (external_value) raw[key_end..key_end] else raw[key_end..stored_value_end],
        .is_delete = is_delete,
        .external_value_root_page = external_value_root_page,
        .external_value_len = if (external_value) @intCast(value_len) else 0,
    };
}

fn encodeDocumentEntry(allocator: Allocator, out: *std.ArrayListUnmanaged(u8), entry: DocumentEntry) !void {
    const value_len = if (entry.external_value_root_page != 0 and entry.external_value_len != 0) entry.external_value_len else entry.value.len;
    if (entry.key.len > std.math.maxInt(u32) or value_len > std.math.maxInt(u32)) return error.RecordTooLarge;
    if (entry.is_delete and entry.external_value_root_page != 0) return error.InvalidNativeDocumentEntryFlags;
    const external_value = entry.external_value_root_page != 0;
    if (external_value and value_len == 0) return error.InvalidNativeValueChain;

    const start = out.items.len;
    const stored_value_len: usize = if (external_value) 8 else value_len;
    const header_len: usize = if (entry.content_digest != null) 60 else 28;
    try out.resize(allocator, start + header_len + entry.key.len + stored_value_len);
    const encoded = out.items[start..];
    std.mem.writeInt(u64, encoded[0..8], entry.previous_page, .little);
    encoded[8] =
        (if (entry.is_delete) document_delete_flag else 0) |
        (if (external_value) document_external_value_flag else 0) |
        document_namespace_link_flag |
        (if (entry.content_digest != null) document_content_digest_flag else 0);
    @memset(encoded[9..12], 0);
    std.mem.writeInt(u32, encoded[12..16], @intCast(entry.key.len), .little);
    std.mem.writeInt(u32, encoded[16..20], @intCast(value_len), .little);
    std.mem.writeInt(u64, encoded[20..28], entry.previous_namespace_page, .little);
    if (entry.content_digest) |digest| @memcpy(encoded[28..60], &digest);
    @memcpy(encoded[header_len..][0..entry.key.len], entry.key);
    if (external_value) {
        std.mem.writeInt(u64, encoded[header_len + entry.key.len ..][0..8], entry.external_value_root_page, .little);
    } else {
        @memcpy(encoded[header_len + entry.key.len ..][0..entry.value.len], entry.value);
    }
}

fn decodeDocumentEntry(raw: []const u8) !DocumentEntry {
    if (raw.len < 20) return error.TruncatedNativeDocumentEntry;
    const previous_page = std.mem.readInt(u64, raw[0..8], .little);
    const flags = raw[8];
    if (flags & ~(document_delete_flag | document_external_value_flag | document_namespace_link_flag | document_content_digest_flag) != 0) return error.InvalidNativeDocumentEntryFlags;
    const is_delete = flags & document_delete_flag != 0;
    const external_value = flags & document_external_value_flag != 0;
    const has_namespace_link = flags & document_namespace_link_flag != 0;
    if (!has_namespace_link) return error.InvalidNativeDocumentEntryFlags;
    if (is_delete and external_value) return error.InvalidNativeDocumentEntryFlags;

    const key_len = std.mem.readInt(u32, raw[12..16], .little);
    const value_len = std.mem.readInt(u32, raw[16..20], .little);
    const stored_value_len: u64 = if (external_value) 8 else value_len;
    const header_len: usize = if (flags & document_content_digest_flag != 0) 60 else 28;
    if (raw.len < header_len) return error.TruncatedNativeDocumentEntry;
    const payload_len = @as(u64, key_len) + stored_value_len;
    if (payload_len > raw.len - header_len) return error.TruncatedNativeDocumentEntry;
    const key_start: usize = header_len;
    const key_end = key_start + @as(usize, @intCast(key_len));
    const stored_value_end = key_end + @as(usize, @intCast(stored_value_len));
    const external_value_root_page = if (external_value) blk: {
        if (value_len == 0) return error.InvalidNativeValueChain;
        const root = std.mem.readInt(u64, raw[key_end..][0..8], .little);
        if (root == 0) return error.InvalidNativeValueChain;
        break :blk root;
    } else 0;
    return .{
        .previous_page = previous_page,
        .previous_namespace_page = std.mem.readInt(u64, raw[20..28], .little),
        .content_digest = if (flags & document_content_digest_flag != 0) raw[28..60].* else null,
        .key = raw[key_start..key_end],
        .value = if (external_value) raw[key_end..key_end] else raw[key_end..stored_value_end],
        .is_delete = is_delete,
        .external_value_root_page = external_value_root_page,
        .external_value_len = if (external_value) @intCast(value_len) else 0,
    };
}

fn encodedDocumentIndexNodeSize(node: DocumentIndexNode) !usize {
    if (node.keys.len > std.math.maxInt(u16)) return error.RecordTooLarge;
    if ((node.kind == .leaf and node.pointers.len != node.keys.len) or
        (node.kind == .internal and node.pointers.len != node.keys.len + 1))
        return error.InvalidDocumentIndex;
    const internal_header_size: usize = if (node.kind == .internal) @sizeOf(u64) else 0;
    var size: usize = document_index_header_size + internal_header_size;
    for (node.keys, 0..) |key, i| {
        if (key.len > std.math.maxInt(u16)) return error.RecordTooLarge;
        size = try std.math.add(usize, size, @sizeOf(u16) + @sizeOf(u64) + (if (key.len > index_inline_key_limit or (node.key_pages != null and node.key_pages.?[i] != 0)) @as(usize, 8) else key.len));
    }
    return size;
}

fn lowerBoundIndexKeys(keys: []const []u8, key: []const u8) usize {
    var low: usize = 0;
    var high = keys.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        if (std.mem.order(u8, keys[mid], key) == .lt)
            low = mid + 1
        else
            high = mid;
    }
    return low;
}

fn upperBoundIndexKeys(keys: []const []u8, key: []const u8) usize {
    var low: usize = 0;
    var high = keys.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        if (std.mem.order(u8, keys[mid], key) != .gt)
            low = mid + 1
        else
            high = mid;
    }
    return low;
}

fn encodeDocumentIndexNode(allocator: Allocator, node: DocumentIndexNode) ![]u8 {
    const size = try encodedDocumentIndexNodeSize(node);
    const out = try allocator.alloc(u8, size);
    errdefer allocator.free(out);
    @memcpy(out[0..document_index_magic.len], document_index_magic);
    out[8] = @backingInt(node.kind);
    out[9] = 0;
    std.mem.writeInt(u16, out[10..12], @intCast(node.keys.len), .little);
    var pos: usize = document_index_header_size;
    if (node.kind == .internal) {
        std.mem.writeInt(u64, out[pos..][0..8], node.pointers[0], .little);
        pos += 8;
    }
    for (node.keys, 0..) |key, i| {
        const external = key.len > index_inline_key_limit or (node.key_pages != null and node.key_pages.?[i] != 0);
        std.mem.writeInt(u16, out[pos..][0..2], if (external) index_external_key_marker else @intCast(key.len), .little);
        pos += 2;
        const pointer_index = if (node.kind == .leaf) i else i + 1;
        std.mem.writeInt(u64, out[pos..][0..8], node.pointers[pointer_index], .little);
        pos += 8;
        if (external) {
            const pages = node.key_pages orelse return error.InvalidDocumentIndex;
            if (pages[i] == 0) return error.InvalidDocumentIndex;
            std.mem.writeInt(u64, out[pos..][0..8], pages[i], .little);
            pos += 8;
        } else {
            @memcpy(out[pos..][0..key.len], key);
            pos += key.len;
        }
    }
    std.debug.assert(pos == out.len);
    return out;
}

const IndexProbe = struct { leaf: bool, page: ?u64 };

fn probeDocumentIndexNode(raw: []const u8, key: []const u8) !IndexProbe {
    if (raw.len < document_index_header_size or !std.mem.eql(u8, raw[0..8], document_index_magic) or raw[9] != 0)
        return error.InvalidDocumentIndex;
    const leaf = switch (raw[8]) {
        1 => true,
        2 => false,
        else => return error.InvalidDocumentIndex,
    };
    const count = std.mem.readInt(u16, raw[10..12], .little);
    if (leaf and count == 0) return error.InvalidDocumentIndex;
    var pos: usize = document_index_header_size;
    var selected: ?u64 = null;
    if (!leaf) {
        if (pos + 8 > raw.len) return error.InvalidDocumentIndex;
        selected = std.mem.readInt(u64, raw[pos..][0..8], .little);
        pos += 8;
    }
    var previous: ?[]const u8 = null;
    for (0..count) |_| {
        if (pos + 10 > raw.len) return error.InvalidDocumentIndex;
        const len = std.mem.readInt(u16, raw[pos..][0..2], .little);
        const pointer = std.mem.readInt(u64, raw[pos + 2 ..][0..8], .little);
        pos += 10;
        if (len == index_external_key_marker) return error.ExternalIndexKey;
        if (len > index_inline_key_limit or len > raw.len - pos) return error.InvalidDocumentIndex;
        const candidate = raw[pos..][0..len];
        if (previous) |prev| if (std.mem.order(u8, prev, candidate) != .lt) return error.InvalidDocumentIndex;
        previous = candidate;
        const order = std.mem.order(u8, key, candidate);
        if ((leaf and order == .eq) or (!leaf and order != .lt)) selected = pointer;
        pos += len;
    }
    if (pos != raw.len) return error.InvalidDocumentIndex;
    return .{ .leaf = leaf, .page = selected };
}

/// First pass for `decodeDocumentIndexNode`: walks the same entry layout
/// (2-byte key_len, 8-byte pointer, then either an 8-byte key_page or
/// `key_len` inline bytes) purely to sum the inline-key bytes, so the real
/// decode pass below can allocate exactly one backing buffer for all of
/// this node's inline keys instead of one `dupe` per key. Bounds-checks the
/// same way the decode pass does (a corrupt length here must not read out
/// of `raw`), but does not validate key ordering or any other invariant --
/// the decode pass still does that on its own, identical, walk.
const InlineDocumentIndexKeyTotals = struct {
    /// Sum of every inline key's byte length -- what `key_storage` must be
    /// sized to hold. Zero whenever every inline key in this node happens
    /// to be empty (e.g. `""`), which is not the same thing as "no inline
    /// keys at all": `has_inline` is the field that distinguishes those,
    /// and is what `decodeDocumentIndexNode` must check before deciding
    /// `key_storage` can stay `null`. An empty-but-inline key still needs
    /// a (zero-length, but non-null) slot in `key_storage` for its
    /// `keys[i]` slice to point into -- see that function's own
    /// `key_storage.?` dereference for every inline key, regardless of
    /// length.
    bytes: usize,
    has_inline: bool,
};

fn sumInlineDocumentIndexKeyBytes(raw: []const u8, start_pos: usize, count: usize) !InlineDocumentIndexKeyTotals {
    var pos = start_pos;
    var total: usize = 0;
    var has_inline = false;
    for (0..count) |_| {
        if (pos + 10 > raw.len) return error.InvalidDocumentIndex;
        const key_len: usize = std.mem.readInt(u16, raw[pos..][0..2], .little);
        pos += 10; // 2-byte length + 8-byte pointer, common to every entry
        if (key_len == index_external_key_marker) {
            if (pos + 8 > raw.len) return error.InvalidDocumentIndex;
            pos += 8;
        } else {
            if (key_len > index_inline_key_limit or pos + key_len > raw.len) return error.InvalidDocumentIndex;
            has_inline = true;
            total += key_len;
            pos += key_len;
        }
    }
    return .{ .bytes = total, .has_inline = has_inline };
}

fn decodeDocumentIndexNode(allocator: Allocator, raw: []const u8) !DocumentIndexNode {
    if (raw.len < document_index_header_size or !std.mem.eql(u8, raw[0..8], document_index_magic))
        return error.InvalidDocumentIndex;
    const kind: DocumentIndexNodeKind = switch (raw[8]) {
        @backingInt(DocumentIndexNodeKind.leaf) => .leaf,
        @backingInt(DocumentIndexNodeKind.internal) => .internal,
        else => return error.InvalidDocumentIndex,
    };
    if (raw[9] != 0) return error.InvalidDocumentIndex;
    const count: usize = std.mem.readInt(u16, raw[10..12], .little);
    if (kind == .leaf and count == 0) return error.InvalidDocumentIndex;
    const keys = try allocator.alloc([]u8, count);
    var keys_initialized: usize = 0;
    const key_pages = try allocator.alloc(u64, count);
    // External keys (`key_pages[i] != 0`) are each their own real
    // allocation (see the comment at their assignment below); inline keys
    // live in `key_storage`, freed once, separately. On an error partway
    // through the loop, only the external keys actually initialized so
    // far need freeing here.
    errdefer {
        for (keys[0..keys_initialized], key_pages[0..keys_initialized]) |key, page| if (page != 0) allocator.free(key);
        allocator.free(keys);
        allocator.free(key_pages);
    }
    @memset(key_pages, 0);
    const pointer_extra: usize = if (kind == .internal) 1 else 0;
    const pointers = try allocator.alloc(u64, count + pointer_extra);
    errdefer allocator.free(pointers);
    var pos: usize = document_index_header_size;
    if (kind == .internal) {
        if (pos + 8 > raw.len) return error.InvalidDocumentIndex;
        pointers[0] = std.mem.readInt(u64, raw[pos..][0..8], .little);
        pos += 8;
    }
    // One allocation for every inline key's bytes in this node, instead of
    // one `dupe` per key -- see `DocumentIndexNode.key_storage`'s doc
    // comment for why (measured as the single largest allocation-site
    // contributor in the write-amplification CPU attribution).
    //
    // `key_storage` must be allocated (even to zero length) whenever
    // *any* key in this node is inline, not merely when their bytes sum
    // to something nonzero: a node mixing one empty inline key (`""`,
    // `key_len == 0`) with otherwise-external keys (every other key's
    // length over `index_inline_key_limit`) has `inline_totals.bytes == 0`
    // despite genuinely needing a slot for that empty key's `keys[i]`
    // slice to point into below (`key_storage.?`) -- gating the
    // allocation on `.bytes != 0` instead of `.has_inline` left that one
    // case with `key_storage == null`, panicing on the first such node
    // (reachable with a mix of a zero-length and multiple
    // `> index_inline_key_limit`-byte keys in the same leaf/internal node,
    // e.g. the catalog index after inserting an empty key alongside
    // several oversized ones).
    const inline_totals = try sumInlineDocumentIndexKeyBytes(raw, pos, count);
    const key_storage = if (inline_totals.has_inline) try allocator.alloc(u8, inline_totals.bytes) else null;
    errdefer if (key_storage) |storage| allocator.free(storage);
    var storage_used: usize = 0;
    for (keys, 0..) |*key, i| {
        if (pos + 10 > raw.len) return error.InvalidDocumentIndex;
        const key_len: usize = std.mem.readInt(u16, raw[pos..][0..2], .little);
        pos += 2;
        const pointer_index = if (kind == .leaf) i else i + 1;
        pointers[pointer_index] = std.mem.readInt(u64, raw[pos..][0..8], .little);
        pos += 8;
        if (key_len == index_external_key_marker) {
            if (pos + 8 > raw.len) return error.InvalidDocumentIndex;
            key_pages[i] = std.mem.readInt(u64, raw[pos..][0..8], .little);
            if (key_pages[i] == 0) return error.InvalidDocumentIndex;
            // A real (if zero-size) individual allocation, not a slice
            // into `key_storage`: `resolveIndexKey` later frees and
            // replaces exactly this key in place once it resolves the
            // external content, so it must be its own allocation the
            // allocator can `free` on its own, not a sub-slice of a
            // larger buffer freed as a whole elsewhere.
            key.* = try allocator.alloc(u8, 0);
            pos += 8;
        } else {
            if (key_len > index_inline_key_limit or pos + key_len > raw.len) return error.InvalidDocumentIndex;
            // `sumInlineDocumentIndexKeyBytes` already proved `key_storage`
            // has room for every inline key's bytes in this same walk.
            const storage = key_storage.?;
            @memcpy(storage[storage_used..][0..key_len], raw[pos .. pos + key_len]);
            key.* = storage[storage_used..][0..key_len];
            storage_used += key_len;
            pos += key_len;
        }
        keys_initialized += 1;
        if (i > 0 and key_pages[i - 1] == 0 and key_pages[i] == 0 and std.mem.order(u8, keys[i - 1], key.*) != .lt) return error.InvalidDocumentIndex;
    }
    if (pos != raw.len) return error.InvalidDocumentIndex;
    return .{ .kind = kind, .keys = keys, .pointers = pointers, .key_pages = key_pages, .key_storage = key_storage };
}

// Regression for a panic in `decodeDocumentIndexNode`: a node mixing one
// empty, genuinely inline key (`""`, zero bytes) with external
// (`> index_inline_key_limit`-byte) siblings used to decode with
// `key_storage == null` -- `sumInlineDocumentIndexKeyBytes`'s byte total
// summed to zero even though a key *was* inline -- and then panic
// dereferencing `key_storage.?` for that empty key. See `has_inline` on
// `InlineDocumentIndexKeyTotals`, the fix for exactly this.
test "lite native document index node decode allocates storage for an empty inline key beside external siblings" {
    const a = std.testing.allocator;
    const big = try a.alloc(u8, index_inline_key_limit + 1);
    defer a.free(big);
    @memset(big, 'x');
    var keys = [_][]u8{ try a.dupe(u8, ""), try a.dupe(u8, big) };
    defer for (keys) |key| a.free(key);
    var key_pages = [_]u64{ 0, 7 };
    var pointers = [_]u64{ 1, 2 };
    const node: DocumentIndexNode = .{
        .kind = .leaf,
        .keys = &keys,
        .pointers = &pointers,
        .key_pages = &key_pages,
    };
    const encoded = try encodeDocumentIndexNode(a, node);
    defer a.free(encoded);
    var decoded = try decodeDocumentIndexNode(a, encoded);
    defer decoded.deinit(a);
    try std.testing.expectEqual(@as(usize, 2), decoded.keys.len);
    try std.testing.expectEqualStrings("", decoded.keys[0]);
    try std.testing.expectEqual(@as(u64, 0), decoded.key_pages.?[0]);
    try std.testing.expect(decoded.key_pages.?[1] != 0);
}

fn decodeValuePage(raw: []const u8) !ValuePage {
    if (raw.len < value_page_header_size) return error.TruncatedNativeValuePage;
    return .{
        .next_page = std.mem.readInt(u64, raw[0..8], .little),
        .chunk = raw[value_page_header_size..],
    };
}

fn encodeFreeMapAlloc(allocator: Allocator, page_size: u32, covered_page_count: u64, free_pages: []const u64) ![]u8 {
    if (free_pages.len > maxFreeMapEntries(page_size)) return error.NativeFreeMapTooLarge;
    if (free_pages.len > std.math.maxInt(u32)) return error.NativeFreeMapTooLarge;

    var previous_page_id: u64 = 0;
    for (free_pages) |page_id| {
        if (page_id == 0 or page_id >= covered_page_count) return error.InvalidNativeFreeMap;
        if (page_id <= previous_page_id) return error.InvalidNativeFreeMap;
        previous_page_id = page_id;
    }

    const payload = try allocator.alloc(u8, free_map_header_size + free_pages.len * 8);
    errdefer allocator.free(payload);
    std.mem.writeInt(u32, payload[0..4], free_map_format_version, .little);
    std.mem.writeInt(u32, payload[4..8], @intCast(free_pages.len), .little);
    std.mem.writeInt(u64, payload[8..16], covered_page_count, .little);
    for (free_pages, 0..) |page_id, index| {
        const offset = free_map_header_size + index * 8;
        std.mem.writeInt(u64, payload[offset..][0..8], page_id, .little);
    }
    return payload;
}

/// `allow_behind` is for a redo-log file only: a diverting commit (§9)
/// advances `checkpoint.page_count` on its own, directly, to hand out
/// fresh page ids for external value chains (`pageAllocatorForDivertingCommit`)
/// without ever touching this free map -- that is the entire point of
/// deferring real page/allocator work to `checkpointRedoLog`'s own
/// batched build. So between two real checkpoints, `checkpoint.page_count`
/// legitimately runs ahead of the free map's own `covered_page_count`;
/// every page in that gap is one a diverting commit already claimed and
/// wrote for real, never reachable through this free map, which is
/// exactly how an already-allocated (non-free) page behaves here anyway.
/// A free map that claims to cover *more* than the checkpoint's own
/// page_count is a different story -- that is always invalid, redo or
/// not, since no page beyond page_count exists yet for anything to be
/// free within.
fn decodeFreeMapAlloc(allocator: Allocator, raw: []const u8, checkpoint_page_count: u64, allow_behind: bool) !FreeMap {
    if (raw.len < free_map_header_size) return error.TruncatedNativeFreeMap;
    const version = std.mem.readInt(u32, raw[0..4], .little);
    if (version != free_map_format_version) return error.InvalidNativeFreeMap;
    const free_page_count = std.mem.readInt(u32, raw[4..8], .little);
    const covered_page_count = std.mem.readInt(u64, raw[8..16], .little);
    if (if (allow_behind) covered_page_count > checkpoint_page_count else covered_page_count != checkpoint_page_count) {
        return error.InvalidNativeFreeMap;
    }
    const expected_len = free_map_header_size + @as(usize, free_page_count) * 8;
    if (raw.len != expected_len) return error.InvalidNativeFreeMap;

    const free_pages = try allocator.alloc(u64, free_page_count);
    errdefer allocator.free(free_pages);
    var previous_page_id: u64 = 0;
    for (free_pages, 0..) |*page_id, index| {
        const offset = free_map_header_size + index * 8;
        page_id.* = std.mem.readInt(u64, raw[offset..][0..8], .little);
        if (page_id.* == 0 or page_id.* >= checkpoint_page_count) return error.InvalidNativeFreeMap;
        if (page_id.* <= previous_page_id) return error.InvalidNativeFreeMap;
        previous_page_id = page_id.*;
    }
    return .{
        .covered_page_count = covered_page_count,
        .free_pages = free_pages,
    };
}

fn maxFreeMapEntries(page_size: u32) usize {
    std.debug.assert(page_size >= page_header_size + free_map_header_size);
    return (@as(usize, @intCast(page_size)) - page_header_size - free_map_header_size) / 8;
}

fn readExactAt(file: std.Io.File, io: std.Io, out: []u8, offset: u64) !void {
    const read = try file.readPositionalAll(io, out, offset);
    if (read != out.len) return error.EndOfStream;
}

fn readHeaderExactAt(file: std.Io.File, io: std.Io, out: *[header_size]u8) !void {
    const read = try file.readPositionalAll(io, out, 0);
    if (read != header_size) return error.TruncatedNativeHeader;
}

/// v8's header page holds nothing but the static fields `encodeHeader`
/// writes once at creation: no embedded checkpoint slots, no
/// active_checkpoint hint, so nothing here ever changes per commit and the
/// checksum can cover the whole prefix unconditionally.
fn headerChecksum(raw: []const u8) u32 {
    var crc = Crc32.init();
    crc.update(raw[0..header_checksum_offset]);
    return crc.final();
}

fn validPageSize(page_size: u32) bool {
    return page_size >= 4096 and page_size <= 65536 and std.math.isPowerOfTwo(page_size);
}

fn issueForDecodeError(err: anyerror) []const u8 {
    return switch (err) {
        error.TruncatedNativeHeader => "truncated_header",
        error.InvalidNativeMagic => "invalid_magic",
        error.UnsupportedNativeFormatVersion => "unsupported_format_version",
        error.InvalidNativeHeaderSize => "invalid_header_size",
        error.NativeHeaderChecksumMismatch => "header_checksum_mismatch",
        error.InvalidNativePageSize => "invalid_page_size",
        error.InvalidNativeCheckpointSlot => "invalid_checkpoint_slot",
        error.NativeCheckpointChecksumMismatch => "checkpoint_checksum_mismatch",
        error.InvalidNativeCheckpoint => "invalid_checkpoint",
        else => "invalid_header",
    };
}

fn issueForPageCheckError(err: anyerror) []const u8 {
    return switch (err) {
        error.InvalidPageId => "invalid_page_id",
        error.InvalidNativeAllocator => "invalid_allocator",
        // Exhausted its bounded retry budget in `checkAtFileSizeWithCancel`
        // -- a background checkpoint publisher that never went quiet for
        // even one validation pass, not an ownership defect. See
        // `validateIndexedAllocator`'s own doc comment on this error.
        error.NativeCheckpointSuperseded => "checkpoint_contended",
        error.TruncatedNativePage => "truncated_page",
        error.InvalidNativePageMagic => "invalid_page_magic",
        error.InvalidNativePageKind => "invalid_page_kind",
        error.UnexpectedNativePageKind => "unexpected_page_kind",
        error.InvalidNativePageLength => "invalid_page_length",
        error.NativePageChecksumMismatch => "page_checksum_mismatch",
        error.TruncatedNativeCatalogEntry => "truncated_catalog_entry",
        error.InvalidNativeCatalogEntryFlags => "invalid_catalog_entry_flags",
        error.TruncatedNativeDocumentEntry => "truncated_document_entry",
        error.InvalidNativeDocumentEntryFlags => "invalid_document_entry_flags",
        error.InvalidNamespaceDirectory => "invalid_namespace_directory",
        error.InvalidDocumentIndex,
        error.InvalidDocumentIndexOrder,
        => "invalid_document_index",
        error.InvalidNativePageChain => "invalid_page_chain",
        error.TruncatedNativeValuePage => "truncated_value_page",
        error.InvalidNativeValueChain => "invalid_value_chain",
        error.TruncatedNativeFreeMap,
        error.InvalidNativeFreeMap,
        error.UnsupportedNativeFreeMap,
        => "invalid_free_map",
        else => "invalid_page",
    };
}

fn invalidCheck(report: CheckReport, issue: []const u8) CheckReport {
    var invalid = report;
    invalid.valid = false;
    invalid.issue = issue;
    return invalid;
}

fn testPath(allocator: Allocator, tmp: std.testing.TmpDir, name: []const u8) ![]u8 {
    return try std.fmt.allocPrint(allocator, ".zig-cache/tmp/{s}/{s}", .{ tmp.sub_path, name });
}

/// The active slot's index and decoded content, for a test that wants to
/// corrupt one field and write it back via `writeTestSlotPage`.
fn readActiveSlotForTest(path: []const u8) !struct { index: u8, slot: CheckpointSlot } {
    var file = try NativeFile.open(std.testing.allocator, path, true);
    defer file.close();
    return .{ .index = file.header.active_checkpoint, .slot = file.activeCheckpoint() };
}

fn writeTestSlotPage(path: []const u8, index: u8, slot: CheckpointSlot) !void {
    var buf: [default_page_size]u8 = undefined;
    encodeCheckpointSlotPage(&buf, slot);
    var raw = try std.Io.Dir.cwd().openFile(std.testing.io, path, .{ .mode = .read_write });
    defer raw.close(std.testing.io);
    try raw.writePositionalAll(std.testing.io, &buf, slotPhysicalPage(index) * @as(u64, default_page_size));
    try raw.sync(std.testing.io);
}

test "lite native header round trips static fields" {
    var encoded: [header_size]u8 = undefined;
    encodeHeader(&encoded, .{});

    const header = try decodeHeader(&encoded);
    try std.testing.expectEqual(default_page_size, header.page_size);
    // decodeHeader alone cannot recover the real checkpoint (v8 slots live
    // on their own pages, not in the header buffer): it comes back as the
    // structurally-invalid placeholder every caller must follow with
    // loadCheckpointSlots + recoverActiveCheckpoint.
    try std.testing.expectEqual(@as(u64, 0), header.checkpoints[0].page_count);
}

test "lite native header rejects corrupted checksum" {
    var encoded: [header_size]u8 = undefined;
    encodeHeader(&encoded, .{});
    encoded[page_size_offset] ^= 0xff;

    try std.testing.expectError(error.NativeHeaderChecksumMismatch, decodeHeader(&encoded));
}

test "lite native header rejects unsupported format version" {
    var encoded: [header_size]u8 = undefined;
    encodeHeader(&encoded, .{});
    std.mem.writeInt(u32, encoded[version_offset..][0..4], format_version + 1, .little);

    try std.testing.expectError(error.UnsupportedNativeFormatVersion, decodeHeader(&encoded));
}

/// Writes a minimal v8 file for slot-recovery tests: the header page plus
/// slot 0 and (optionally) slot 1, with room reserved for both regardless.
/// Callers that want a torn or dropped page corrupt the returned file
/// directly afterward.
fn writeTestAfliteFile(allocator: Allocator, tmp: std.testing.TmpDir, name: []const u8, header: Header, slot0: CheckpointSlot, slot1: ?CheckpointSlot) ![]u8 {
    const path = try testPath(allocator, tmp, name);
    errdefer allocator.free(path);
    var encoded: [header_size]u8 = undefined;
    encodeHeader(&encoded, header);
    var file = try std.Io.Dir.cwd().createFile(std.testing.io, path, .{ .read = true, .truncate = true });
    defer file.close(std.testing.io);
    try file.writePositionalAll(std.testing.io, &encoded, 0);
    const needed_pages = @max(reserved_header_pages, @max(slot0.page_count, if (slot1) |slot| slot.page_count else 0));
    try file.setLength(std.testing.io, needed_pages * @as(u64, default_page_size));
    var slot_buf: [default_page_size]u8 = undefined;
    encodeCheckpointSlotPage(&slot_buf, slot0);
    try file.writePositionalAll(std.testing.io, &slot_buf, slotPhysicalPage(0) * @as(u64, default_page_size));
    if (slot1) |slot| {
        encodeCheckpointSlotPage(&slot_buf, slot);
        try file.writePositionalAll(std.testing.io, &slot_buf, slotPhysicalPage(1) * @as(u64, default_page_size));
    }
    return path;
}

test "lite native header selects newest valid checkpoint slot" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try writeTestAfliteFile(allocator, tmp, "slot-newest.aflite", .{}, .{ .commit_sequence = 1, .page_count = reserved_header_pages }, .{ .commit_sequence = 2, .page_count = reserved_header_pages + 1 });
    defer allocator.free(path);

    const report = try inspect(allocator, std.testing.io, path);
    try std.testing.expect(report.valid);
    try std.testing.expectEqual(@as(u8, 1), report.active_checkpoint);
    try std.testing.expectEqual(@as(u64, 2), report.commit_sequence);
    try std.testing.expectEqual(reserved_header_pages + 1, report.page_count);
}

// WS1(b) required test: "a torn slot falls back to the previous checkpoint."
test "lite native recovery falls back past a torn higher-sequence slot" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(allocator, tmp, "slot-torn.aflite");
    defer allocator.free(path);

    var file = try NativeFile.createWithIo(allocator, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    try file.putDocument("doc", "stable");
    const stable_sequence = file.activeCheckpoint().commit_sequence;
    try file.putDocument("doc", "newest");
    // Tear the newly-active slot's page: its own CRC now fails, so it
    // decodes as structurally invalid regardless of its commit_sequence,
    // and recovery must fall back to the previous ("stable") checkpoint.
    const damaged = slotPhysicalPage(file.header.active_checkpoint) * @as(u64, file.header.page_size) + page_header_size;
    try file.file.writePositionalAll(file.runtimeIo(), "X", damaged);
    file.close();

    const report = try inspect(allocator, std.testing.io, path);
    try std.testing.expect(report.valid);
    try std.testing.expectEqual(stable_sequence, report.commit_sequence);

    file = try NativeFile.openWithIo(allocator, std.testing.io, path, .{ .no_sync = true });
    try std.testing.expectEqual(stable_sequence, file.activeCheckpoint().commit_sequence);
    const recovered = (try file.getDocumentAlloc(allocator, "doc")).?;
    defer allocator.free(recovered);
    try std.testing.expectEqualStrings("stable", recovered);
    // The rejected "newest" commit's pages are still physically present as
    // a stale tail past the recovered checkpoint (the torn slot, not a
    // dropped data page, is what failed, so recoverActiveCheckpoint had no
    // reason to truncate). check() correctly calls that tail out; enough
    // real commits grow the checkpoint past it, the same way an ordinary
    // writer resuming after a crash would.
    for (0..40) |_| try file.putDocument("doc", "settled");
    try std.testing.expect((try file.check()).valid);
}

// WS1(b) required tests, restored (and extended) now that
// manifest_commits_enabled is true. A bare `file.putDocument`/
// `putDocumentBatch` call (no open transaction) used to route
// indexed_reclamation files through `putIndexedDocumentBatch`'s own
// hand-rolled `publishCheckpoint(next, false)` -- always presynced, never
// a manifest. It now calls `reserveBareCommitManifestPage` /
// `publishBareCommit` at the same spot, the bare-commit equivalent of
// `flushTransactionWrites`'s own reservation and
// `commitTransactionWithDurability`'s own `tryBuildCommitManifest`/publish
// tail (see "lite native durable commit costs one sync after dropping the
// active_checkpoint hint" above). Every test below still wraps its writes
// in an explicit beginTransaction/commitTransaction pair to exercise that
// transactional path directly, rather than the bare path's own.

test "lite native small durable commit builds a manifest and costs one sync" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(allocator, tmp, "manifest-small-commit.aflite");
    defer allocator.free(path);

    var file = try NativeFile.createWithIo(allocator, std.testing.io, path, .{ .indexed_reclamation = true });
    defer file.close();

    const before = file.test_sync_calls.load(.monotonic);
    {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("doc", "durable");
        try file.commitTransaction();
    }
    try std.testing.expectEqual(@as(u64, 1), file.test_sync_calls.load(.monotonic) - before);

    const slot = file.activeCheckpoint();
    try std.testing.expect(!slot.presynced);
    try std.testing.expect(slot.manifest_page != 0);
    try std.testing.expect((try file.check()).valid);
    const value = (try file.getDocumentAlloc(allocator, "doc")).?;
    defer allocator.free(value);
    try std.testing.expectEqualStrings("durable", value);
}

test "lite native oversized commit falls back to presynced with two syncs" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(allocator, tmp, "manifest-oversized-commit.aflite");
    defer allocator.free(path);

    var file = try NativeFile.createWithIo(allocator, std.testing.io, path, .{ .indexed_reclamation = true });
    defer file.close();

    // One value spanning more than max_single_sync_pages value-chain pages,
    // all written inside one transaction: tryBuildCommitManifest must give
    // up (too many entries to list) and fall back to the historical
    // presync-then-slot-sync order.
    const large = try allocator.alloc(u8, (max_single_sync_pages + 64) * 4000);
    defer allocator.free(large);
    @memset(large, 'v');

    const before = file.test_sync_calls.load(.monotonic);
    {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("big", large);
        try file.commitTransaction();
    }
    try std.testing.expectEqual(@as(u64, 2), file.test_sync_calls.load(.monotonic) - before);

    const slot = file.activeCheckpoint();
    try std.testing.expect(slot.presynced);
    try std.testing.expectEqual(@as(u64, 0), slot.manifest_page);
    try std.testing.expect((try file.check()).valid);
}

test "lite native manifest catches a torn page from an earlier non-durable commit in the same window" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(allocator, tmp, "manifest-window-torn-page.aflite");
    defer allocator.free(path);

    var file = try NativeFile.createWithIo(allocator, std.testing.io, path, .{ .indexed_reclamation = true });
    {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("doc", "stable");
        try file.commitTransaction();
    }
    const stable_sequence = file.activeCheckpoint().commit_sequence;

    // A non-durable commit inside the same since-last-durable window: it
    // still writes real pages through the ordinary tracked hook, and
    // manifest_builder keeps tracking them even though this attempt never
    // calls tryBuildCommitManifest/publishCheckpoint's real branch. A large
    // value forces an external value chain: unlike the tiny document/index
    // structure pages (which the next commit's own unrelated edit to "doc"
    // can easily revisit and overwrite, erasing the tear before
    // verification ever runs), a value chain is immutable once written and
    // belongs only to this document -- nothing else has any reason to
    // reuse or rewrite it in this short a window.
    const non_durable_value = try allocator.alloc(u8, 20 * 4000);
    defer allocator.free(non_durable_value);
    @memset(non_durable_value, 'n');
    {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("non-durable-marker", non_durable_value);
        try file.commitTransactionWithDurability(false, null);
    }
    try std.testing.expect(file.manifest_builder.entries.count() > 0);

    // Tear every page this non-durable commit touched -- the handful of
    // small structural pages (free map, catalog, index) may well get
    // rewritten and "repaired" by the next commit's own edit to "doc"
    // below, but the bulk of these entries are the value chain's own pages
    // and none of them are.
    {
        var it = file.manifest_builder.entries.keyIterator();
        while (it.next()) |page_id| {
            // verifyManifest compares the page's *stored* CRC field against
            // the CRC the manifest recorded at write time; it does not
            // recompute a fresh CRC from the current payload (full
            // structural re-verification is the slot's own, separate
            // check). Corrupting the CRC field itself (not a payload byte)
            // is what that comparison actually catches.
            const damaged = page_id.* * @as(u64, file.header.page_size) + page_crc_offset;
            try file.file.writePositionalAll(file.runtimeIo(), "X", damaged);
        }
    }

    // The eventual durable commit's manifest must cover that torn page,
    // so its slot fails verification on reopen and recovery falls all the
    // way back to the checkpoint from before either of these two commits.
    {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("doc", "durable-after");
        try file.commitTransaction();
    }
    file.close();

    const report = try inspect(allocator, std.testing.io, path);
    try std.testing.expect(report.valid);
    try std.testing.expectEqual(stable_sequence, report.commit_sequence);

    var reopened = try NativeFile.openWithIo(allocator, std.testing.io, path, .{});
    defer reopened.close();
    try std.testing.expectEqual(stable_sequence, reopened.activeCheckpoint().commit_sequence);
    const recovered = (try reopened.getDocumentAlloc(allocator, "doc")).?;
    defer allocator.free(recovered);
    try std.testing.expectEqualStrings("stable", recovered);
}

// WS1(b) required test: "when the slot is durable but its pages were
// dropped, the manifest check fails and recovery falls back."
test "lite native recovery falls back and truncates when a manifest-listed page is dropped" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(allocator, tmp, "manifest-dropped-page.aflite");
    defer allocator.free(path);

    var file = try NativeFile.createWithIo(allocator, std.testing.io, path, .{ .indexed_reclamation = true });
    {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("doc", "stable");
        try file.commitTransaction();
    }
    const stable_sequence = file.activeCheckpoint().commit_sequence;
    const stable_page_count = file.activeCheckpoint().page_count;

    {
        try file.beginTransaction();
        errdefer file.abortTransaction();
        try file.putDocument("doc", "newest");
        try file.commitTransaction();
    }
    const newest = file.activeCheckpoint();
    try std.testing.expect(!newest.presynced);
    try std.testing.expect(newest.manifest_page != 0);

    // Corrupt every page this commit wrote (everything from the previous
    // frontier up to the new one), except the manifest page itself and the
    // slot: both of their own CRCs stay intact, so only verifyManifest's
    // per-entry CRC check over the data pages it lists can catch this.
    var candidate = stable_page_count;
    while (candidate < newest.page_count) : (candidate += 1) {
        if (candidate == newest.manifest_page) continue;
        // See the matching comment in the earlier window test: corrupt the
        // stored CRC field itself, which is what verifyManifest compares,
        // not a payload byte (a full structural re-check is the slot's own
        // separate, different concern).
        const damaged = candidate * @as(u64, file.header.page_size) + page_crc_offset;
        try file.file.writePositionalAll(file.runtimeIo(), "X", damaged);
    }
    file.close();

    const report = try inspect(allocator, std.testing.io, path);
    try std.testing.expect(report.valid);
    try std.testing.expectEqual(stable_sequence, report.commit_sequence);
    try std.testing.expectEqual(stable_page_count, report.page_count);

    var reopened = try NativeFile.openWithIo(allocator, std.testing.io, path, .{});
    defer reopened.close();
    try std.testing.expectEqual(stable_sequence, reopened.activeCheckpoint().commit_sequence);
    const recovered = (try reopened.getDocumentAlloc(allocator, "doc")).?;
    defer allocator.free(recovered);
    try std.testing.expectEqualStrings("stable", recovered);
}

// v9 required test (design doc §3.2a "Manifest coverage" / 37a00f96fd): a
// torn page in a SECOND (or later) run of a multi-run manifest must still
// be caught, falling recovery back exactly as a single-run v8 manifest
// would. Fabricates a higher-sequence slot, in the file's own spare slot
// page, whose manifest genuinely spans two runs with a real gap between
// them (not the single `manifest_page_id` gap the one-run encoder already
// bridged) -- the shape a window with more than one
// `flushTransactionWrites`/`persistAllocator` cycle commonly produces.
test "lite native manifest with a torn page in a later run falls back and truncates" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(allocator, tmp, "manifest-second-run-torn.aflite");
    defer allocator.free(path);

    var file = try NativeFile.createWithIo(allocator, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    try file.putDocument("doc", "stable");
    const stable_sequence = file.activeCheckpoint().commit_sequence;
    const base_page_count = file.activeCheckpoint().page_count;
    const other_slot_index: u8 = 1 - file.header.active_checkpoint;
    file.close();

    // Never the real active slot -- this must not disturb the already-
    // durable "stable" document this test later confirms survives intact.
    const run1_start = base_page_count;
    const run2_start = base_page_count + 10;
    const manifest_page_id = base_page_count + 20;
    const total_pages = base_page_count + 30;

    var raw = try std.Io.Dir.cwd().openFile(std.testing.io, path, .{ .mode = .read_write });
    try raw.setLength(std.testing.io, total_pages * @as(u64, default_page_size));

    var entries: [6]ManifestEntry = undefined;
    var page_buf: [default_page_size]u8 = undefined;
    for (0..3) |i| {
        const page_id = run1_start + i;
        encodePage(&page_buf, .data, "run1-page");
        try raw.writePositionalAll(std.testing.io, &page_buf, page_id * @as(u64, default_page_size));
        entries[i] = .{ .page_id = page_id, .crc = std.mem.readInt(u32, page_buf[page_crc_offset..][0..4], .little) };
    }
    for (0..3) |i| {
        const page_id = run2_start + i;
        encodePage(&page_buf, .data, "run2-page");
        try raw.writePositionalAll(std.testing.io, &page_buf, page_id * @as(u64, default_page_size));
        entries[3 + i] = .{ .page_id = page_id, .crc = std.mem.readInt(u32, page_buf[page_crc_offset..][0..4], .little) };
    }

    const empty_reused: std.AutoHashMapUnmanaged(u64, void) = .empty;
    const manifest_payload = try encodeManifestPayloadAlloc(allocator, &entries, &empty_reused, manifest_page_id);
    defer allocator.free(manifest_payload);
    // Two genuinely separate runs: a real hole between them, not the single
    // reserved manifest-page id this window also skips over.
    try std.testing.expectEqual(@as(u32, 2), std.mem.readInt(u32, manifest_payload[0..4], .little));

    var manifest_buf: [default_page_size]u8 = undefined;
    encodePage(&manifest_buf, .commit_manifest, manifest_payload);
    try raw.writePositionalAll(std.testing.io, &manifest_buf, manifest_page_id * @as(u64, default_page_size));

    const fabricated_sequence = stable_sequence + 1;
    const fabricated_slot = CheckpointSlot{
        .commit_sequence = fabricated_sequence,
        .page_count = total_pages,
        .presynced = false,
        .manifest_page = manifest_page_id,
        .manifest_crc = std.mem.readInt(u32, manifest_buf[page_crc_offset..][0..4], .little),
        .manifest_page_count = entries.len,
    };
    var slot_buf: [default_page_size]u8 = undefined;
    encodeCheckpointSlotPage(&slot_buf, fabricated_slot);
    try raw.writePositionalAll(std.testing.io, &slot_buf, slotPhysicalPage(other_slot_index) * @as(u64, default_page_size));
    raw.close(std.testing.io);

    // Sanity: the fabricated two-run manifest verifies and wins on its own
    // -- confirms the construction above (and encodeManifestPayloadAlloc's
    // multi-run output) is genuinely valid before the corruption below is
    // what makes it fail.
    {
        const report = try inspect(allocator, std.testing.io, path);
        try std.testing.expect(report.valid);
        try std.testing.expectEqual(fabricated_sequence, report.commit_sequence);
    }

    // Tear one page in the SECOND run only -- the first run (and its own
    // header/CRC-array bounds) verifies cleanly; only the later run's own
    // entry must be what catches this.
    {
        var writable = try std.Io.Dir.cwd().openFile(std.testing.io, path, .{ .mode = .read_write });
        defer writable.close(std.testing.io);
        const damaged = (run2_start + 1) * @as(u64, default_page_size) + page_crc_offset;
        try writable.writePositionalAll(std.testing.io, "X", damaged);
    }

    const report = try inspect(allocator, std.testing.io, path);
    try std.testing.expect(report.valid);
    try std.testing.expectEqual(stable_sequence, report.commit_sequence);
    try std.testing.expectEqual(base_page_count, report.page_count);

    var reopened = try NativeFile.openWithIo(allocator, std.testing.io, path, .{ .no_sync = true });
    defer reopened.close();
    try std.testing.expectEqual(stable_sequence, reopened.activeCheckpoint().commit_sequence);
    const recovered = (try reopened.getDocumentAlloc(allocator, "doc")).?;
    defer allocator.free(recovered);
    try std.testing.expectEqualStrings("stable", recovered);
}

// v9 required test: a corrupted run table (not just a corrupted data page)
// must fail verification safely -- a declared run `count` or `run_count`
// that overruns the manifest page's own payload must return `false`
// (an ordinary "fall back" outcome), never read out of bounds or panic.
// Both payloads below are hand-corrupted: never something
// `encodeManifestPayloadAlloc` itself would produce.
test "lite native manifest run table rejects out-of-bounds run entries instead of crashing" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const total_pages = reserved_header_pages + 4;
    const page_id = reserved_header_pages;
    var page_buf: [default_page_size]u8 = undefined;
    encodePage(&page_buf, .data, "ok");
    const real_crc = std.mem.readInt(u32, page_buf[page_crc_offset..][0..4], .little);

    // Case 1: a run's declared `count` claims far more CRCs than the page
    // has room for.
    {
        const path = try testPath(allocator, tmp, "manifest-run-count-overrun.aflite");
        defer allocator.free(path);
        var raw = try std.Io.Dir.cwd().createFile(std.testing.io, path, .{ .read = true, .truncate = true });
        try raw.setLength(std.testing.io, total_pages * @as(u64, default_page_size));
        try raw.writePositionalAll(std.testing.io, &page_buf, page_id * @as(u64, default_page_size));

        var payload: [manifest_header_size + manifest_run_header_size]u8 = undefined;
        std.mem.writeInt(u32, payload[0..4], 1, .little); // run_count
        std.mem.writeInt(u32, payload[4..8], 0, .little); // reused_count
        std.mem.writeInt(u64, payload[8..16], page_id, .little); // range_start
        std.mem.writeInt(u32, payload[16..20], 1000, .little); // count: bogus, no room on the page
        var manifest_buf: [default_page_size]u8 = undefined;
        encodePage(&manifest_buf, .commit_manifest, &payload);
        const manifest_page_id = reserved_header_pages + 1;
        try raw.writePositionalAll(std.testing.io, &manifest_buf, manifest_page_id * @as(u64, default_page_size));
        raw.close(std.testing.io);

        const slot = CheckpointSlot{
            .commit_sequence = 1,
            .page_count = total_pages,
            .presynced = false,
            .manifest_page = manifest_page_id,
            .manifest_crc = std.mem.readInt(u32, manifest_buf[page_crc_offset..][0..4], .little),
            .manifest_page_count = 1,
        };
        var reader = try std.Io.Dir.cwd().openFile(std.testing.io, path, .{});
        defer reader.close(std.testing.io);
        try std.testing.expect(!verifyManifest(reader, std.testing.io, slot, default_page_size));
    }

    // Case 2: the run table itself claims more runs than fit -- the second
    // run's own 12-byte header has no room left in the page payload at all,
    // even though the first run's single entry is genuinely valid.
    {
        const path = try testPath(allocator, tmp, "manifest-run-table-overrun.aflite");
        defer allocator.free(path);
        var raw = try std.Io.Dir.cwd().createFile(std.testing.io, path, .{ .read = true, .truncate = true });
        try raw.setLength(std.testing.io, total_pages * @as(u64, default_page_size));
        try raw.writePositionalAll(std.testing.io, &page_buf, page_id * @as(u64, default_page_size));

        var payload: [manifest_header_size + manifest_run_header_size + 4]u8 = undefined;
        std.mem.writeInt(u32, payload[0..4], 3, .little); // claims 3 runs
        std.mem.writeInt(u32, payload[4..8], 0, .little);
        std.mem.writeInt(u64, payload[8..16], page_id, .little);
        std.mem.writeInt(u32, payload[16..20], 1, .little); // run 1: one real, valid entry
        std.mem.writeInt(u32, payload[20..24], real_crc, .little);
        // No bytes left at all for runs 2 and 3's own headers.
        var manifest_buf: [default_page_size]u8 = undefined;
        encodePage(&manifest_buf, .commit_manifest, &payload);
        const manifest_page_id = reserved_header_pages + 1;
        try raw.writePositionalAll(std.testing.io, &manifest_buf, manifest_page_id * @as(u64, default_page_size));
        raw.close(std.testing.io);

        const slot = CheckpointSlot{
            .commit_sequence = 1,
            .page_count = total_pages,
            .presynced = false,
            .manifest_page = manifest_page_id,
            .manifest_crc = std.mem.readInt(u32, manifest_buf[page_crc_offset..][0..4], .little),
            .manifest_page_count = 3,
        };
        var reader = try std.Io.Dir.cwd().openFile(std.testing.io, path, .{});
        defer reader.close(std.testing.io);
        try std.testing.expect(!verifyManifest(reader, std.testing.io, slot, default_page_size));
    }
}

