test "lite allocator v4 completed retirement preserves rollback and fallback bytes" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "retirement-completion-recovery.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    file.retirement_work_pages = 0;
    const value: [8192]u8 = @splat('v');
    try file.putCatalogRecord("key", &value);
    const checkpoint = file.activeCheckpoint();
    const reference = (try file.lookupCatalogPage(checkpoint, .metadata, "key")).?;
    const payload = try file.readPagePayloadByKindAllocForCheckpoint(a, reference, .catalog, checkpoint);
    defer a.free(payload);
    const root = (try decodeCatalogEntry(payload)).external_value_root_page;
    try file.putCatalogRecord("key", "replacement");
    try file.putDocument("advance", "frontier");
    var rounds: usize = 0;
    while ((try file.loadLedger(file.activeCheckpoint())).count(root) != 0) : (rounds += 1) {
        try std.testing.expect(rounds < 16);
        _ = try file.reclaimPages(1);
    }
    // The completion is committed, but the previous allocator still owns a
    // queue entry that must read this value node. It cannot be reused yet.
    const state = try file.loadLedger(file.activeCheckpoint());
    var found = false;
    var pending = state.pending.valueIterator();
    while (pending.next()) |item| if (item.kind == .metadata and item.page == root) {
        found = true;
    };
    try std.testing.expect(found);
    try file.beginTransaction();
    try file.putDocument("private", &value);
    _ = try file.materializeTransactionCheckpoint();
    file.abortTransaction();
    try std.testing.expect((try file.check()).valid);
    var fallback = try NativeFile.openWithIo(a, std.testing.io, path, .{ .read_only = true });
    defer fallback.close();
    fallback.header.active_checkpoint = 1 - fallback.header.active_checkpoint;
    try std.testing.expect((try fallback.check()).valid);
}

test "lite allocator v4 external reader waits for in place reclamation lock" {
    const a = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reader-reclamation-lock.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    try file.putDocument("key", "value");
    const held = try acquireDataRewriteLock(io, path);
    var lock_open = true;
    defer if (lock_open) held.file.close(io);
    const Reader = struct {
        started: std.atomic.Value(bool) = .init(false),
        opened: std.atomic.Value(bool) = .init(false),
        result: anyerror!void = {},
        fn run(self: *@This(), allocator: Allocator, runtime_io: std.Io, source: []const u8) void {
            self.started.store(true, .release);
            self.read(allocator, runtime_io, source) catch |err| {
                self.result = err;
            };
        }
        pub fn read(self: *@This(), allocator: Allocator, runtime_io: std.Io, source: []const u8) !void {
            var reader = try NativeFile.openWithIo(allocator, runtime_io, source, .{ .read_only = true, .wait_for_reader_lock = true });
            defer reader.close();
            const value = (try reader.getDocumentAlloc(allocator, "key")).?;
            defer allocator.free(value);
            try std.testing.expectEqualStrings("value", value);
            self.opened.store(true, .release);
        }
    };
    var context = Reader{};
    var future = try io.concurrent(Reader.run, .{ &context, a, io, path });
    var joined = false;
    defer if (!joined) {
        if (lock_open) {
            held.file.close(io);
            lock_open = false;
        }
        future.await(io);
    };
    const deadline = std.Io.Clock.awake.now(io).addDuration(std.Io.Duration.fromSeconds(3));
    while (!context.started.load(.acquire)) {
        if (std.Io.Clock.awake.now(io).nanoseconds >= deadline.nanoseconds) return error.TestUnexpectedResult;
        try std.Io.sleep(io, .fromMilliseconds(1), .awake);
    }
    try std.Io.sleep(io, .fromMilliseconds(10), .awake);
    try std.testing.expect(!context.opened.load(.acquire));
    held.file.close(io);
    lock_open = false;
    future.await(io);
    joined = true;
    try context.result;
    try std.testing.expect(context.opened.load(.acquire));
}

// Regressions for a same-process self-deadlock the inode_lock registry
// (inode_lock.zig) exists to make structurally impossible: an exclusive
// grant this process parks warm on one NativeFile's fd (to amortize
// acquireEpochReuseLock's kernel call across commits) used to self-conflict
// against a *different* fd this same process opened on the very same
// inode, since flock() is scoped to the open file description, not the
// process. Both regressions below run the would-hang call on a background
// task with a bounded deadline, so a recurrence fails the test instead of
// hanging the whole suite.
fn runBoundedReaderFence(a: Allocator, io: std.Io, path: []const u8, coordinator: *ReaderCoordinator, owner: *NativeFile) !void {
    const Reader = struct {
        opened: std.atomic.Value(bool) = .init(false),
        result: anyerror!void = {},
        fn run(self: *@This(), allocator: Allocator, runtime_io: std.Io, source: []const u8, coord: *ReaderCoordinator, writer: *NativeFile) void {
            self.read(allocator, runtime_io, source, coord, writer) catch |err| {
                self.result = err;
            };
        }
        fn read(self: *@This(), allocator: Allocator, runtime_io: std.Io, source: []const u8, coord: *ReaderCoordinator, writer: *NativeFile) !void {
            var reader = try NativeFile.openWithIo(allocator, runtime_io, source, .{ .read_only = true, .internal_reader = true, .reader_coordinator = coord });
            defer reader.close();
            try reader.acquireReaderFence(writer.activeCheckpoint().commit_sequence, writer);
            defer reader.releaseReaderFence();
            self.opened.store(true, .release);
        }
    };
    var context = Reader{};
    var future = try io.concurrent(Reader.run, .{ &context, a, io, path, coordinator, owner });
    var joined = false;
    defer if (!joined) future.await(io);
    const deadline = std.Io.Clock.awake.now(io).addDuration(std.Io.Duration.fromSeconds(3));
    while (!context.opened.load(.acquire)) {
        if (std.Io.Clock.awake.now(io).nanoseconds >= deadline.nanoseconds) {
            future.await(io);
            joined = true;
            return error.TestUnexpectedResult;
        }
        try std.Io.sleep(io, .fromMilliseconds(1), .awake);
    }
    future.await(io);
    joined = true;
    try context.result;
}

test "lite reader fence after a warm writer succeeds instead of hanging" {
    const a = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "warm-writer-reader-fence.aflite");
    defer a.free(path);
    var coordinator = ReaderCoordinator.init(a, io);
    defer coordinator.deinit();
    var writer = try NativeFile.createWithIo(a, io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer writer.close();
    writer.reader_coordinator = &coordinator;
    const value: [8192]u8 = @splat('a');
    // The first write has nothing to retire yet (skip_reuse_lock stays
    // true). Each write after that sees the previous one's retirement in
    // the ledger, so by the last of these the inline commit actually
    // acquires (not skips) the inode registry's exclusive grant, which
    // then stays parked warm on the registry entry (not on `writer`)
    // after the commit releases it.
    for (0..5) |_| try writer.putDocument("doc", &value);
    try runBoundedReaderFence(a, io, path, &coordinator, &writer);
}

test "lite reader fence succeeds across two independently opened NativeFile instances on one externally-locked path" {
    const a = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "shared-inode-reader-fence.aflite");
    defer a.free(path);
    var coordinator = ReaderCoordinator.init(a, io);
    defer coordinator.deinit();
    // `first` and `second` are two entirely independent NativeFile
    // instances (as two independently opened `externally_locked` Stores
    // on the same path would be) that happen to share one underlying
    // inode. `first` parks a warm exclusive grant on the shared registry
    // entry from its own writes; a reader fenced against `second` -- a
    // different NativeFile, with its own fd, that itself never wrote
    // anything -- must still succeed promptly, because both resolve to
    // the one inode_lock Entry for this path, not because of anything
    // `second` itself did.
    var first = try NativeFile.createWithIo(a, io, path, .{ .indexed_reclamation = true, .no_sync = true, .exclusive = false });
    defer first.close();
    first.reader_coordinator = &coordinator;
    const value: [8192]u8 = @splat('b');
    for (0..5) |_| try first.putDocument("doc", &value);
    var second = try NativeFile.openWithIo(a, io, path, .{ .externally_locked = true, .no_sync = true });
    defer second.close();
    second.reader_coordinator = &coordinator;
    try runBoundedReaderFence(a, io, path, &coordinator, &second);
}

// A genuinely foreign process is simulated the same way
// "lite allocator v4 external reader waits for in place reclamation lock"
// (above) does: a raw, independent fd via `acquireDataRewriteLock`,
// bypassing this process's own inode_lock registry entirely -- real
// cross-process contention has no shared in-memory state to consult.
test "lite warm parked exclusive still blocks a genuinely foreign probe but not this process's own shared read" {
    const a = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "warm-parked-foreign-probe.aflite");
    defer a.free(path);
    var coordinator = ReaderCoordinator.init(a, io);
    defer coordinator.deinit();
    var writer = try NativeFile.createWithIo(a, io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer writer.close();
    writer.reader_coordinator = &coordinator;
    const value: [8192]u8 = @splat('c');
    // Same as the other warm-writer tests: enough overwrites that the last
    // commit's inline drain actually acquires (not skips) the exclusive
    // grant, which then stays parked -- no in-process holder, kernel lock
    // still held -- on the registry entry afterward.
    for (0..5) |_| try writer.putDocument("doc", &value);
    // A truly independent fd (standing in for a different OS process)
    // still sees the real kernel lock: parking is not just bookkeeping.
    const foreign = acquireDataRewriteLock(io, path) catch |err| switch (err) {
        error.WouldBlock => null,
        else => return err,
    };
    try std.testing.expect(foreign == null);
    // This process's own fail-fast shared read, by contrast, is granted
    // for free against its own parked (not actively held) exclusive --
    // the whole point of distinguishing parked from actively-held in the
    // registry (inode_lock.zig's `acquire`/`tryAcquireSharedOnce`).
    try runBoundedReaderFence(a, io, path, &coordinator, &writer);
}

test "lite immutable checksums traverse linked values once and seek extent ranges" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "stream-checksum.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .no_sync = true });
    defer file.close();
    const bytes = try a.alloc(u8, 2 * 1024 * 1024);
    defer a.free(bytes);
    for (bytes, 0..) |*byte, i| byte.* = @truncate(i *% 17);
    const chain = try linkedValueForTest(&file, bytes);
    const checkpoint = file.activeCheckpoint();
    const start = bytes.len - 128 * 1024;
    file.test_page_reads.store(0, .monotonic);
    var crc = Crc32.init();
    var scratch: [8192]u8 = undefined;
    var offset: usize = start;
    while (offset < bytes.len) : (offset += scratch.len) {
        try file.readIndexValueInto(chain, offset, &scratch, checkpoint);
        crc.update(&scratch);
    }
    const baseline_reads = file.test_page_reads.load(.monotonic);
    file.test_page_reads.store(0, .monotonic);
    try std.testing.expectEqual(crc.final(), try file.checksumIndexValue(chain, start, bytes.len - start, checkpoint));
    const sequential_reads = file.test_page_reads.load(.monotonic);
    try std.testing.expect(sequential_reads < baseline_reads / 8);
    for ([_]usize{ 0, 1, 8191, 8192, start, bytes.len }) |position| {
        const length = @min(@as(usize, 10001), bytes.len - position);
        try std.testing.expectEqual(Crc32.hash(bytes[position..][0..length]), try file.checksumIndexValue(chain, position, length, checkpoint));
    }
    try file.putIndexCatalogRecord("extent", bytes);
    const extent_checkpoint = file.activeCheckpoint();
    var extent = try file.openIndexValue(a, "extent", extent_checkpoint);
    defer extent.deinit(a);
    file.test_page_reads.store(0, .monotonic);
    try std.testing.expectEqual(Crc32.hash(bytes[start..]), try file.checksumIndexValue(extent, start, bytes.len - start, extent_checkpoint));
    const extent_reads = file.test_page_reads.load(.monotonic);
    try std.testing.expect(extent_reads < sequential_reads / 2);
    try std.testing.expectError(error.EndOfStream, file.checksumIndexValue(extent, bytes.len, 1, extent_checkpoint));
    std.debug.print("LITE_CHECKSUM chain_bytes={d} range_bytes={d} repeated_range_page_reads={d} sequential_page_reads={d} extent_range_page_reads={d}\n", .{ bytes.len, bytes.len - start, baseline_reads, sequential_reads, extent_reads });
}

