test "lite native value cursor uses inline frames and bounded deep overflow" {
    const a = std.testing.allocator;
    var file: NativeFile = undefined;
    var budget = @import("test_allocator.zig").BudgetAllocator{ .backing = a, .limit = 0 };
    file.allocator = budget.allocator();
    var cursor = NativeFile.ValueChunkCursor{ .file = &file, .checkpoint = undefined, .pending = null, .chain_page = 0, .remaining = 0, .max_depth = 63 };
    defer cursor.deinit();
    const node = NativeFile.ExtentNode{ .height = 1, .count = 0 };
    for (0..4) |_| try cursor.pushFrame(node);
    try std.testing.expectEqual(@as(usize, 0), budget.alloc_calls);
    try std.testing.expectError(error.OutOfMemory, cursor.pushFrame(node));
    try std.testing.expectEqual(@as(usize, 4), cursor.frame_count);
    budget.limit = 128 * 1024;
    for (4..63) |_| try cursor.pushFrame(node);
    try std.testing.expectEqual(@as(usize, 1), budget.alloc_calls);
    try std.testing.expectEqual(@as(usize, 63), cursor.frames.capacity);
    try std.testing.expectError(error.InvalidNativeValueChain, cursor.pushFrame(node));
    for (0..63) |_| cursor.popFrame();
    for (0..63) |_| try cursor.pushFrame(node);
    try std.testing.expectEqual(@as(usize, 1), budget.alloc_calls);
    std.debug.print("LITE_CURSOR_FRAMES inline_levels=4 inline_heap=0 max_levels=63 overflow_bytes={d} allocations={d}\n", .{ budget.peak, budget.alloc_calls });
}

test "lite native immutable value traversal needs no heap scratch for ordinary extents" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/cursor-scratch.aflite", .{tmp.sub_path});
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .no_sync = true });
    defer file.close();
    const payload = try a.alloc(u8, 1024 * 1024);
    defer a.free(payload);
    @memset(payload, 19);
    try file.putIndexCatalogRecord("/artifact", payload);
    file.page_cache_enabled.store(false, .monotonic);
    const checkpoint = file.activeCheckpoint();
    var value = try file.openIndexValue(a, "/artifact", checkpoint);
    defer value.deinit(a);
    var budget = @import("test_allocator.zig").BudgetAllocator{ .backing = a, .limit = 0 };
    file.allocator = budget.allocator();
    defer file.allocator = a;
    const Visitor = struct {
        length: usize = 0,
        crc: Crc32 = Crc32.init(),
        fn consume(raw: *anyopaque, offset: u64, bytes: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            try std.testing.expectEqual(self.length, offset);
            self.length += bytes.len;
            self.crc.update(bytes);
        }
    };
    for (0..8) |_| {
        var visitor = Visitor{};
        try file.visitIndexValue(value, 0, payload.len, checkpoint, &visitor, Visitor.consume);
        try std.testing.expectEqual(payload.len, visitor.length);
        try std.testing.expectEqual(Crc32.hash(payload), visitor.crc.final());
        var out: [8]u8 = undefined;
        try file.readAuthenticatedIndexValue(value, 0, payload.len, 123, &out, Crc32.hash(payload), checkpoint);
        try std.testing.expectEqualSlices(u8, payload[123..131], &out);
        const before = file.test_backing_read_bytes.load(.monotonic);
        var limited = Visitor{};
        try file.visitIndexValue(value, 123, 65536, checkpoint, &limited, Visitor.consume);
        try std.testing.expectEqual(@as(usize, 65536), limited.length);
        try std.testing.expectEqual(Crc32.hash(payload[123..][0..65536]), limited.crc.final());
        const bytes_read = file.test_backing_read_bytes.load(.monotonic) - before;
        // Account for overlapping leaves and two navigation levels, without
        // allowing speculative batches to run beyond this logical range.
        try std.testing.expect(bytes_read <= 65536 + 4 * file.header.page_size);
    }
    try std.testing.expectEqual(@as(usize, 0), budget.alloc_calls);
    std.debug.print("LITE_CURSOR_TRAVERSAL bytes=1048576 traversals=24 heap_allocations={d}\n", .{budget.alloc_calls});
}

test "lite sustained writers reclaim bounded retirement pressure before admission" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "writer-retirement-pressure.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithIo(a, std.testing.io, path, .{ .indexed_reclamation = true, .no_sync = true });
    defer file.close();
    file.retirement_work_pages = 0;
    const value = try a.alloc(u8, 8192);
    defer a.free(value);
    @memset(value, 'v');
    try file.beginTransaction();
    for (0..128) |id| {
        var key: [32]u8 = undefined;
        try file.putDocument(try std.fmt.bufPrint(&key, "item-{d}", .{id}), value);
    }
    try file.commitTransaction();
    const pinned = file.activeCheckpoint();
    file.minimum_reader_sequence = pinned.commit_sequence;
    try file.beginTransaction();
    for (0..128) |id| {
        var key: [32]u8 = undefined;
        try file.putDocument(try std.fmt.bufPrint(&key, "item-{d}", .{id}), "replacement");
    }
    try file.commitTransaction();
    const state = try file.loadLedger(file.activeCheckpoint());
    state.pending_limit = state.pending.count() + 64;
    try std.testing.expectError(error.FileBusy, file.reclaimRetirementPressure());
    const old = (try file.getDocumentAtCheckpointAlloc(a, pinned, "item-0")).?;
    defer a.free(old);
    try std.testing.expectEqualSlices(u8, value, old);
    file.minimum_reader_sequence = null;
    try file.reclaimRetirementPressure();
    const after = try file.loadLedger(file.activeCheckpoint());
    try std.testing.expect(after.pending.count() <= after.pending_limit / 2);
    const current = (try file.getDocumentAtCheckpointAlloc(a, file.activeCheckpoint(), "item-0")).?;
    defer a.free(current);
    try std.testing.expectEqualStrings("replacement", current);
    try std.testing.expect((try file.check()).valid);
}

// perf/lwa-peer-cert: reclaimPagesImpl's redo-overlay gate (perf/lwa-reuse-loss,
// ec28c12c66/2b6ee404e8) deferred its ledger-only body whenever unfolded
// logical/page-shaped overlay content existed and no `max_file_bytes`
// budget was configured -- correct for an unbudgeted *ride-along*
// maintenance pass (`reclaimPagesForMaintenanceWithCancel`, `require_reuse_proof
// = false`; see the test right after this one), but the same unconditional
// check also covered `reclaimPagesWithCancel`/`reclaimPages` (`require_reuse_proof
// = true`), an explicit, synchronous caller that already asked for real
// reclamation right now and has no ride-along to fall back on
// (`reclaimRetirementPressure`'s own doc comment: "a sustained writer must
// contribute reclamation before filling the bounded retirement queue").
// Silently returning 0 on every call turned every such explicit request
// into a permanent no-op whenever any logical overlay debt was
// outstanding and no budget happened to be configured -- found live via
// `capi.db_test`'s "coalesces allocator proof outside publication gates":
// an unbudgeted file's `reclaimPages(4096)` loop retired nothing, so
// `allocatorStats().reusable_pages` never moved, and (unrelated to a
// budget at all) `reclaimRetirementPressure`'s own foreground admission
// loop would have spun to `error.FileBusy` with zero progress on any
// unbudgeted store once pending debt crossed half the queue limit.
test "lite native reclaimPages folds unfolded redo overlay debt for an explicit caller even without a configured storage budget" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reclaim-explicit-no-budget.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithRedoLog(a, std.testing.io, path, .{ .indexed_reclamation = true }, 256 * 1024);
    defer file.close();
    // No `max_file_bytes` configured anywhere -- the exact unbudgeted
    // condition the old gate silently starved an explicit caller under.
    try std.testing.expect(file.max_file_bytes == null);
    const large: [32768]u8 = @splat('v');
    var keys: [16][16]u8 = undefined;
    var batch: [16]CatalogMutation = undefined;
    for (&batch, &keys, 0..) |*mutation, *key, i| mutation.* = .{ .key = try std.fmt.bufPrint(key, "doomed-{d}", .{i}), .value = &large };
    try file.putCatalogBatch(&batch);
    for (&batch) |*mutation| mutation.* = .{ .key = mutation.key, .is_delete = true };
    try file.putCatalogBatch(&batch);
    // Exactly the previously-unexercised case: an active redo log, not
    // mid-checkpoint, with real unfolded overlay debt from the puts and
    // deletes above.
    try std.testing.expect(file.redo != null and !file.redo.?.checkpointing);
    var reclaimed: usize = 0;
    for (0..8) |_| reclaimed += try file.reclaimPages(4096);
    try std.testing.expect(reclaimed > 0);
    try std.testing.expect((try file.allocatorStats()).?.reusable_pages > 64);
    try std.testing.expect((try file.check()).valid);
}

// Companion to the test above: the *ride-along*, non-explicit caller
// (`require_reuse_proof = false`) must still stay deferred without a
// budget -- the fix above is scoped to `require_reuse_proof`, not a
// blanket removal of the gate. Matches docstore.zig's "lite reclamation
// ride-along passes force no sync before the next durable write" at the
// `Store` layer; this is the same property one level down, directly on
// `NativeFile.reclaimPagesForMaintenanceWithCancel`. Checked via
// `test_sync_calls`/`redo.checkpoint_sequence`, not `reusable_pages`: a
// diverting commit's own external-value pages are retired through a
// separate mechanism independent of this gate (`PageWriteBatch`'s own
// `direct_value_pages` handling), so some incidental free-map movement
// is expected even while the gated ledger-only fold body itself never
// runs -- the actual property this gate protects is that no *fold*
// (a real, syncing commit) happens, not that the free map never moves
// at all.
test "lite native reclaimPagesForMaintenanceWithCancel still defers the gated ledger fold without a configured storage budget" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try testPath(a, tmp, "reclaim-ride-along-no-budget.aflite");
    defer a.free(path);
    var file = try NativeFile.createWithRedoLog(a, std.testing.io, path, .{ .indexed_reclamation = true }, 256 * 1024);
    defer file.close();
    try std.testing.expect(file.max_file_bytes == null);
    const large: [32768]u8 = @splat('v');
    var keys: [16][16]u8 = undefined;
    var batch: [16]CatalogMutation = undefined;
    for (&batch, &keys, 0..) |*mutation, *key, i| mutation.* = .{ .key = try std.fmt.bufPrint(key, "doomed-{d}", .{i}), .value = &large };
    try file.putCatalogBatch(&batch);
    for (&batch) |*mutation| mutation.* = .{ .key = mutation.key, .is_delete = true };
    try file.putCatalogBatch(&batch);
    try std.testing.expect(file.redo != null and !file.redo.?.checkpointing);
    const folded_before = file.redo.?.checkpoint_sequence;
    const syncs_before = file.test_sync_calls.load(.monotonic);
    for (0..8) |_| _ = try file.reclaimPagesForMaintenanceWithCancel(4096, null, false);
    try std.testing.expectEqual(folded_before, file.redo.?.checkpoint_sequence);
    try std.testing.expectEqual(syncs_before, file.test_sync_calls.load(.monotonic));
    try std.testing.expect((try file.check()).valid);
}

test "lite raw value leases retain replacement bytes and account retired pins" {
    const a = std.testing.allocator;
    var cache = PageCache{};
    defer cache.deinit(a);
    var manager = resource_manager_mod.ResourceManager.init(.{});
    cache.attachResourceManager(&manager);
    cache.put(a, 1, "original");
    const old = cache.acquireRaw(a, 1, 8).?;
    defer cache.releaseRaw(a, old);
    const same = cache.acquireRaw(a, 1, 8).?;
    try std.testing.expectEqual(old, same);
    cache.releaseRaw(a, same);
    cache.put(a, 1, "replaced");
    const newer = cache.acquireRaw(a, 1, 8).?;
    try std.testing.expect(newer != old);
    try std.testing.expectEqualStrings("original", old.bytes);
    try std.testing.expectEqualStrings("replaced", newer.bytes);
    cache.clear(a);
    try std.testing.expectEqual(old.size() + newer.size(), cache.total_bytes);
    try std.testing.expectEqual(cache.total_bytes, manager.sliceStats(.lite_native_page_cache).used_bytes);
    cache.releaseRaw(a, newer);
    cache.limit_bytes = old.size();
    cache.put(a, 2, "pressure");
    try std.testing.expect(!cache.pages.contains(2));
    try std.testing.expectEqualStrings("original", old.bytes);
    try std.testing.expectEqual(old.size(), cache.total_bytes);
}

