    try std.testing.expect((try writer.allocatorStats()).?.reused_pages >= reused);
    try std.testing.expect((try snapshot.checkAtFileSizeWithCancel(captured_size, null)).valid);
    try std.testing.expect((try writer.check()).valid);
}

